Here is a complete, production-ready codebase for a native iOS habit-tracking application. 

This app is built using **Swift**, **SwiftUI** (for a modern declarative UI), and **SwiftData** (Apple’s modern framework for local data persistence, introduced in iOS 17). 

### How to run this:
1. Open **Xcode** (version 15 or newer).
2. Create a new project: **File > New > Project > iOS App**.
3. Name it `HabitTracker`, select **SwiftUI** for Interface, and **Swift** for Language.
4. Replace the contents of your files with the code below.

---

### 1. The Data Model (`Habit.swift`)
This model defines what a "Habit" is and uses SwiftData to save it automatically to the device's on-board database. It contains helper logic to calculate streaks and completion status.

```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var id: UUID = UUID()
    var name: String
    var createdAt: Date = Date()
    // Stores the timestamps of every time the user checked off the habit
    var completionDates: [Date] = []

    init(name: String) {
        self.name = name
    }

    // Check if the habit has been completed today
    var isCompletedToday: Bool {
        completionDates.contains { Calendar.current.isDateInToday($0) }
    }

    // Calculate the current consecutive day streak
    var currentStreak: Int {
        let calendar = Calendar.current
        // Get unique sorted dates normalized to the start of the day
        let completedDays = Set(completionDates.map { calendar.startOfDay(for: $0) })
            .sorted(by: >)

        guard !completedDays.isEmpty else { return 0 }

        var streak = 0
        var checkDate = calendar.startOfDay(for: Date())

        // If not completed today, check if completed yesterday to keep streak alive
        if !completedDays.contains(checkDate) {
            guard let yesterday = calendar.date(byAdding: .day, value: -1, to: checkDate) else { return 0 }
            checkDate = yesterday
        }

        for date in completedDays {
            if date == checkDate {
                streak += 1
                // Move check date back by one day
                guard let previousDay = calendar.date(byAdding: .day, value: -1, to: checkDate) else { break }
                checkDate = previousDay
            } else if date < checkDate {
                // Streak broken
                break
            }
        }
        return streak
    }
}
```

