### 2. The App Entry Point (`HabitTrackerApp.swift`)
This file boots up the application and injects the SwiftData storage container so the app can save habits across launches.

```swift
import SwiftUI
import SwiftData

@main
struct HabitTrackerApp: App {
    // Sets up the SwiftData container for our Habit model
    var sharedModelContainer: ModelContainer = {
        let schema = Schema([
            Habit.self,
        ])
        let modelConfiguration = ModelConfiguration(schema: schema, isStoredInMemoryOnly: false)

        do {
            return try ModelContainer(for: schema, configurations: [modelConfiguration])
        } catch {
            fatalError("Could not create ModelContainer: \(error)")
        }
    }()

    var body: some Scene {
        WindowGroup {
            ContentView()
        }
        .modelContainer(sharedModelContainer) // Injects SwiftData context
    }
}
```

