### 3. The Main User Interface (`ContentView.swift`)
This handles the visual representation: a list of habits, progress metrics, swipe-to-delete functionality, and the logic to toggle a habit's completion status.

```swift
import SwiftUI
import SwiftData

struct ContentView: View {
    @Environment(\.modelContext) private var modelContext
    // Automatically fetches and updates habits from the database, sorted by creation date
    @Query(sort: \Habit.createdAt, order: .forward) private var habits: [Habit]

    @State private var showingAddHabitSheet = false

    var body: some View {
        NavigationStack {
            ZStack {
                Color(.systemGroupedBackground)
                    .ignoresSafeArea()

                if habits.isEmpty {
                    ContentUnavailableView(
                        "No Habits Yet",
                        systemImage: "checkmark.circle.dashed",
                        description: Text("Tap the '+' button to build a new healthy routine.")
                    )
                } else {
                    List {
                        Section(header: Text("Today's Habits")) {
                            ForEach(habits) { habit in
                                HabitRowView(habit: habit)
                            }
                            .onDelete(perform: deleteHabits)
                        }
                    }
                    .listStyle(.insetGrouped)
                }
            }
            .navigationTitle("Habits")
            .toolbar {
                ToolbarItem(placement: .topBarTrailing) {
                    Button(action: { showingAddHabitSheet = true }) {
                        Image(systemName: "plus.circle.fill")
                            .font(.title3)
                            .foregroundStyle(.tint)
                    }
                }
            }
            .sheet(isPresented: $showingAddHabitSheet) {
                AddHabitSheetView()
                    .presentationDetents([.fraction(0.3)])
            }
        }
    }

    private func deleteHabits(offsets: IndexSet) {
        withAnimation {
            for index in offsets {
                modelContext.delete(habits[index])
            }
        }
    }
}

// MARK: - Habit Row View
struct HabitRowView: View {
    @Environment(\.modelContext) private var modelContext
    let habit: Habit

    var body: some View {
        HStack {
            VStack(alignment: .leading, spacing: 4) {
                Text(habit.name)
                    .font(.headline)
                    .strikethrough(habit.isCompletedToday, color: .gray)
                    .foregroundStyle(habit.isCompletedToday ? .secondary : .primary)

                HStack(spacing: 4) {
                    Image(systemName: "flame.fill")
                        .foregroundStyle(habit.currentStreak > 0 ? .orange : .gray)
                    Text("\(habit.currentStreak) day streak")
                        .font(.caption)
                        .foregroundStyle(.secondary)
                }
            }

            Spacer()

            // Checkmark Action Button
            Button(action: toggleCompletion) {
                Image(systemName: habit.isCompletedToday ? "checkmark.circle.fill" : "circle")
                    .resizable()
                    .frame(width: 28, height: 28)
                    .foregroundStyle(habit.isCompletedToday ? .green : .blue)
                    .contentTransition(.symbolEffect(.replace))
            }
            .buttonStyle(.plain)
        }
        .padding(.vertical, 4)
    }

    private func toggleCompletion() {
        withAnimation(.spring(response: 0.3, dampingFraction: 0.6)) {
            if habit.isCompletedToday {
                // Find today's completion and remove it
                habit.completionDates.removeAll { Calendar.current.isDateInToday($0) }
            } else {
                // Add today's date
                habit.completionDates.append(Date())
            }
            // Save state in SwiftData
            try? modelContext.save()
        }
    }
}
```

