### 1. The Data Model (`Habit.swift`)
This defines what a "Habit" is and how it is stored.

```swift
import Foundation
import SwiftData

@Model
class Habit {
    var id: UUID
    var name: String
    var creationDate: Date
    var completedDates: [Date] // Stores all timestamps when the habit was completed
    var colorHex: String // Stores custom color choice

    init(name: String, colorHex: String = "#34C759") {
        self.id = UUID()
        self.name = name
        self.creationDate = Date()
        self.completedDates = []
        self.colorHex = colorHex
    }

    // Helper to check if completed today
    var isCompletedToday: Bool {
        completedDates.contains { Calendar.current.isDateInToday($0) }
    }

    // Toggle completion for today
    func toggleCompletion() {
        let today = Date()
        if isCompletedToday {
            // Remove today's date
            completedDates.removeAll { Calendar.current.isDateInToday($0) }
        } else {
            // Add today's date
            completedDates.append(today)
        }
    }

    // Calculate current streak
    var streakCount: Int {
        let calendar = Calendar.current
        let uniqueDays = Set(completedDates.map { calendar.startOfDay(for: $0) })
        let sortedDates = uniqueDays.sorted(by: >)

        guard !sortedDates.isEmpty else { return 0 }

        var streak = 0
        var checkDate = calendar.startOfDay(for: Date())

        // If not completed today, check if completed yesterday to maintain the streak
        if !sortedDates.contains(checkDate) {
            checkDate = calendar.date(byAdding: .day, value: -1, to: checkDate)!
        }

        while sortedDates.contains(checkDate) {
            streak += 1
            checkDate = calendar.date(byAdding: .day, value: -1, to: checkDate)!
        }

        return streak
    }
}
```

