### 4. Custom Habit Row (`HabitRowView.swift`)
The UI card for each habit. Users can tap the checkmark to mark a habit complete.

```swift
import SwiftUI

struct HabitRowView: View {
    let habit: Habit
    @Environment(\.modelContext) private var modelContext
    @State private var isAnimating = false

    var body: some View {
        HStack(spacing: 16) {
            // Checkbox Button
            Button(action: {
                // Trigger subtle haptic feedback
                UIImpactFeedbackGenerator(style: .medium).impactOccurred()
                withAnimation(.spring(response: 0.3, dampingFraction: 0.6)) {
                    habit.toggleCompletion()
                    isAnimating = true
                }
            }) {
                Image(systemName: habit.isCompletedToday ? "checkmark.circle.fill" : "circle")
                    .resizable()
                    .aspectRatio(contentMode: .fit)
                    .frame(width: 34, height: 34)
                    .foregroundColor(habit.isCompletedToday ? Color(hex: habit.colorHex) : .gray)
                    .scaleEffect(isAnimating ? 1.2 : 1.0)
            }
            .buttonStyle(.plain)
            .onChange(of: habit.isCompletedToday) { _, _ in
                // Reset scale animation
                DispatchQueue.main.asyncAfter(deadline: .now() + 0.15) {
                    isAnimating = false
                }
            }

            // Habit Details
            VStack(alignment: .leading, spacing: 4) {
                Text(habit.name)
                    .font(.headline)
                    .strikethrough(habit.isCompletedToday, color: .gray)
                    .foregroundColor(habit.isCompletedToday ? .gray : .primary)

                Text(habit.isCompletedToday ? "Completed Today" : "Not completed yet")
                    .font(.caption)
                    .foregroundColor(.secondary)
            }

            Spacer()

            // Streak Indicator
            HStack(spacing: 4) {
                Image(systemName: "flame.fill")
                    .foregroundColor(habit.streakCount > 0 ? .orange : .gray.opacity(0.4))
                Text("\(habit.streakCount)")
                    .font(.subheadline)
                    .bold()
                    .foregroundColor(habit.streakCount > 0 ? .primary : .secondary)
            }
            .padding(.horizontal, 10)
            .padding(.vertical, 6)
            .background(Color(.systemBackground))
            .cornerRadius(12)
        }
        .padding()
        .background(Color(.secondarySystemGroupedBackground))
        .cornerRadius(16)
        .shadow(color: Color.black.opacity(0.04), radius: 5, x: 0, y: 2)
    }
}
