### Step 1: Create the Data Model (`Habit.swift`)
This defines what a "Habit" is and includes logic for checking if it's completed today and calculating streaks.

```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var id: UUID
    var name: String
    var createdAt: Date
    var completedDates: [Date] // Stores every date this habit was completed
    var colorHex: String       // Custom color code (Hex format)

    init(name: String, colorHex: String = "#34C759") {
        self.id = UUID()
        self.name = name
        self.createdAt = Date()
        self.completedDates = []
        self.colorHex = colorHex
    }

    // Check if the habit has been completed today
    var isCompletedToday: Bool {
        completedDates.contains { Calendar.current.isDateInToday($0) }
    }

    // Calculate current streak based on chronological dates completed
    var currentStreak: Int {
        let calendar = Calendar.current
        let sortedDates = completedDates
            .map { calendar.startOfDay(for: $0) }
            .sorted(by: >)

        guard !sortedDates.isEmpty else { return 0 }

        var streak = 0
        var checkDate = calendar.startOfDay(for: Date())

        // If not completed today, check if it was completed yesterday to preserve streak
        if !sortedDates.contains(checkDate) {
            guard let yesterday = calendar.date(byAdding: .day, value: -1, to: checkDate) else { return 0 }
            checkDate = yesterday
        }

        while sortedDates.contains(checkDate) {
            streak += 1
            guard let nextCheckDate = calendar.date(byAdding: .day, value: -1, to: checkDate) else { break }
            checkDate = nextCheckDate
        }

        return streak
    }
}
```

