### Step 4: Create the Habit Row UI Component (`HabitRowView.swift`)
This view renders a single habit inside our list, showing the name, current streak, and an interactive "check-off" button.

```swift
import SwiftUI

struct HabitRowView: View {
    var habit: Habit
    @Environment(\.modelContext) private var modelContext

    var body: some View {
        HStack {
            VStack(alignment: .leading, spacing: 4) {
                Text(habit.name)
                    .font(.headline)

                HStack(spacing: 4) {
                    Image(systemName: "flame.fill")
                        .foregroundColor(.orange)
                    Text("\(habit.currentStreak) day streak")
                        .font(.subheadline)
                        .foregroundColor(.secondary)
                }
            }

            Spacer()

            // Checkmark button
            Button {
                toggleCompletion()
            } label: {
                Image(systemName: habit.isCompletedToday ? "checkmark.circle.fill" : "circle")
                    .resizable()
                    .frame(width: 32, height: 32)
                    .foregroundColor(habit.isCompletedToday ? Color(hex: habit.colorHex) : .gray.opacity(0.4))
                    .contentTransition(.symbolEffect(.replace)) // Standard iOS 17 morph animation
            }
            .buttonStyle(.plain)
        }
        .padding(.vertical, 4)
    }

    private func toggleCompletion() {
        let today = Date()
        let calendar = Calendar.current

        if let index = habit.completedDates.firstIndex(where: { calendar.isDateInToday($0) }) {
            habit.completedDates.remove(at: index)
        } else {
            habit.completedDates.append(today)
        }

