import SwiftUI
import WidgetKit

// MARK: - 1. HABIT MODEL
struct Habit: Identifiable, Codable {
    var id = UUID()
    var name: String
    var frequency: String // e.g., "Daily"
    var category: String // e.g., "Health", "Mind", "Fitness"
    var icon: String // SF Symbol name
    var colorHex: String // Custom color
    var completedDates: Set<Date> = [] // Track dates of completion

    // Computed property to check if completed today
    var isCompletedToday: Bool {
        completedDates.contains { Calendar.current.isDateInToday($0) }
    }

    // Computed property to calculate the current daily streak
    var streak: Int {
        let calendar = Calendar.current
        let sortedDates = completedDates
            .map { calendar.startOfDay(for: $0) }
            .sorted(by: >)

        guard !sortedDates.isEmpty else { return 0 }

        let today = calendar.startOfDay(for: Date())
        let yesterday = calendar.date(byAdding: .day, value: -1, to: today)!

        // If the last completed date is neither today nor yesterday, streak is broken
        guard sortedDates[0] == today || sortedDates[0] == yesterday else { return 0 }

        var currentStreak = 0
        var checkDate = sortedDates[0]

        for date in sortedDates {
            if date == checkDate {
                currentStreak += 1
                checkDate = calendar.date(byAdding: .day, value: -1, to: checkDate)!
            } else if date < checkDate {
                break
            }
        }
        return currentStreak
    }
}

// MARK: - 2. DATA STORE (State Management & Persistence)
@Observable
class HabitStore {
    var habits: [Habit] = [] {
        didSet {
            saveHabits()
        }
    }

    private let saveKey = "SavedHabits"

    init() {
        loadHabits()
        // Add sample habits if empty
        if habits.isEmpty {
            habits = [
                Habit(name: "Drink 3L Water", frequency: "Daily", category: "Health", icon: "drop.fill", colorHex: "#3498db"),
                Habit(name: "Meditation", frequency: "Daily", category: "Mind", icon: "brain.head.profile", colorHex: "#9b59b6"),
                Habit(name: "Read 10 Pages", frequency: "Daily", category: "Growth", icon: "book.fill", colorHex: "#e67e22")
            ]
        }
    }

    func toggleHabit(_ habit: Habit) {
        guard let index = habits.firstIndex(where: { $0.id == habit.id }) else { return }

        let today = Calendar.current.startOfDay(for: Date())

        if habits[index].isCompletedToday {
            // Find today's date and remove it
            if let dateToRemove = habits[index].completedDates.first(where: { Calendar.current.isDateInToday($0) }) {
                habits[index].completedDates.remove(dateToRemove)
            }
        } else {
            // Add today's date
            habits[index].completedDates.insert(today)
            triggerHapticFeedback()
        }
    }

    func addHabit(name: String, category: String, icon: String, color: Color) {
        let hex = color.toHex() ?? "#34495e"
        let newHabit = Habit(name: name, frequency: "Daily", category: category, icon: icon, colorHex: hex)
        habits.append(newHabit)
    }

    func deleteHabit(at offsets: IndexSet) {
        habits.remove(atOffsets: offsets)
    }

    private func saveHabits() {
        if let encoded = try? JSONEncoder().encode(habits) {
            UserDefaults.standard.set(encoded, forKey: saveKey)
        }
    }

    private func loadHabits() {
        if let data = UserDefaults.standard.data(forKey: saveKey),
           let decoded = try? JSONDecoder().decode([Habit].self, from: data) {
            self.habits = decoded
        }
    }

    private func triggerHapticFeedback() {
        let generator = UINotificationFeedbackGenerator()
        generator.notificationOccurred(.success)
    }
}

