### 1. The Data Model (`Habit.swift`)
This defines the habit schema. SwiftData uses Swift’s native macro system (`@Model`) to automatically handle database schema creation and persistence.

```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var id: UUID
    var name: String
    var createdAt: Date
    var completedDates: [Date]

    init(name: String) {
        self.id = UUID()
        self.name = name
        self.createdAt = Date()
        self.completedDates = []
    }

    /// Checks if the habit has been completed today
    var isCompletedToday: Bool {
        completedDates.contains { Calendar.current.isDateInToday($0) }
    }

    /// Calculates the current daily streak
    var currentStreak: Int {
        let calendar = Calendar.current

        // Remove time components and filter out duplicate dates on the same day
        let uniqueDates = Set(completedDates.map { calendar.startOfDay(for: $0) })
        let sortedDates = uniqueDates.sorted(by: >)

        guard !sortedDates.isEmpty else { return 0 }

        // Ensure the streak is still active (completed either today or yesterday)
        let mostRecentCompleted = sortedDates[0]
        guard calendar.isDateInToday(mostRecentCompleted) || calendar.isDateInYesterday(mostRecentCompleted) else {
            return 0
        }

        var streak = 0
        var expectedDate = mostRecentCompleted

        for date in sortedDates {
            if calendar.isDate(date, inSameDayAs: expectedDate) {
                streak += 1
                // Expect the next date to be exactly one day prior
                guard let nextExpected = calendar.date(byAdding: .day, value: -1, to: expectedDate) else { break }
                expectedDate = nextExpected
            } else {
                break
            }
        }

        return streak
    }
}
