### Step 1: Define the Data Model (`Habit.swift`)
Create a new Swift file named `Habit.swift`. This uses SwiftData to automatically manage database schema creation, migrations, and local storage.

```swift
import Foundation
import SwiftData

@Model
final class Habit {
    @Attribute(.unique) var id: UUID
    var name: String
    var details: String
    var createdAt: Date
    /// Stores the exact dates when this habit was successfully completed
    var completionHistory: [Date]

    init(name: String, details: String = "") {
        self.id = UUID()
        self.name = name
        self.details = details
        self.createdAt = Date()
        self.completionHistory = []
    }

    // Check if completed today
    var isCompletedToday: Bool {
        completionHistory.contains { Calendar.current.isDateInToday($0) }
    }

    // Calculates the current daily streak
    var currentStreak: Int {
        let calendar = Calendar.current
        let uniqueDates = Set(completionHistory.map { calendar.startOfDay(for: $0) })
        let sortedDates = uniqueDates.sorted(by: >)

        guard !sortedDates.isEmpty else { return 0 }

        var streak = 0
        var checkDate = calendar.startOfDay(for: Date())

        // If not completed today, check if yesterday was completed to keep the streak active
        if !calendar.isDate(sortedDates.first!, inSameDayAs: checkDate) {
            guard let yesterday = calendar.date(byAdding: .day, value: -1, to: checkDate),
                  calendar.isDate(sortedDates.first!, inSameDayAs: yesterday) else {
                return 0
            }
            checkDate = yesterday
        }

        for date in sortedDates {
            if calendar.isDate(date, inSameDayAs: checkDate) {
                streak += 1
                if let nextDate = calendar.date(byAdding: .day, value: -1, to: checkDate) {
                    checkDate = nextDate
                }
            } else if date > checkDate {
                continue
            } else {
                break
            }
        }
        return streak
    }

    // Toggle completion for today
    func toggleCompletion() {
        let today = Date()
        if let index = completionHistory.firstIndex(where: { Calendar.current.isDate($0, inSameDayAs: today) }) {
            completionHistory.remove(at: index)
        } else {
            completionHistory.append(today)
        }
    }
}
```

