This SwiftData model manages habit details. It contains a dynamic, algorithmic streak-calculation property that tracks consecutive days completed.

```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var id: UUID = UUID()
    var name: String = ""
    var createdAt: Date = Date()
    var completionDates: [Date] = []

    init(name: String) {
        self.name = name
        self.createdAt = Date()
        self.completionDates = []
    }

    /// Checks if the habit has been completed today
    var isCompletedToday: Bool {
        let today = Calendar.current.startOfDay(for: Date())
        return completionDates.contains { Calendar.current.isDate($0, inSameDayAs: today) }
    }

    /// Automatically calculates current consecutive day streak
    var currentStreak: Int {
        guard !completionDates.isEmpty else { return 0 }

        let calendar = Calendar.current
        // Remove duplicates and sort descending
        let sortedDates = Array(Set(completionDates.map { calendar.startOfDay(for: $0) }))
            .sorted(by: >)

        var streak = 0
        var checkDate = calendar.startOfDay(for: Date())

        // If not completed today, check if completed yesterday to keep streak alive
        if sortedDates.first != checkDate {
            guard let yesterday = calendar.date(byAdding: .day, value: -1, to: checkDate) else { return 0 }
            if sortedDates.first == yesterday {
                checkDate = yesterday
            } else {
                return 0 // Streak broken
            }
        }

        // Loop backward to find consecutive days
        for date in sortedDates {
            if date == checkDate {
                streak += 1
                guard let nextCheck = calendar.date(byAdding: .day, value: -1, to: checkDate) else { break }
                checkDate = nextCheck
            } else {
                break
            }
        }
        return streak
    }

    /// Toggles completion status for today
    func toggleCompletion() {
        let today = Calendar.current.startOfDay(for: Date())
        if let index = completionDates.firstIndex(where: { Calendar.current.isDate($0, inSameDayAs: today) }) {
            completionDates.remove(at: index)
        } else {
            completionDates.append(Date())
        }
    }
}
