```swift
import Foundation
import SwiftData

@Model
final class Habit {
    @Attribute(.unique) var id: UUID
    var name: String
    var streak: Int
    var lastCompletedDate: Date?
    var createdAt: Date

    init(name: String) {
        self.id = UUID()
        self.name = name
        self.streak = 0
        self.lastCompletedDate = nil
        self.createdAt = Date()
    }

    // Computed property to check if the habit was completed today
    var isCompletedToday: Bool {
        guard let lastCompletedDate = lastCompletedDate else { return false }
        return Calendar.current.isDateInToday(lastCompletedDate)
    }

    // Toggle completion and manage streaks
    func toggleCompletion() {
        let calendar = Calendar.current

        if isCompletedToday {
            // Undo completion (decrement streak)
            streak = max(0, streak - 1)
            // Roll back to previous day or nil for simplicity in this MVP
            lastCompletedDate = nil 
        } else {
            // Mark completed
            if let lastDate = lastCompletedDate {
                if calendar.isDateInYesterday(lastDate) {
                    streak += 1
                } else if !calendar.isDateInToday(lastDate) {
                    streak = 1 // Streak broken, restart at 1
                }
            } else {
                streak = 1 // First time completing
            }
            lastCompletedDate = Date()
        }
    }
}
