import Foundation
import SwiftData

@Model
final class Habit {
    var id: UUID = UUID()
    var name: String = ""
    var dateCreated: Date = Date()
    var streak: Int = 0
    var lastCompletedDate: Date?

    init(name: String) {
        self.id = UUID()
        self.name = name
        self.dateCreated = Date()
        self.streak = 0
        self.lastCompletedDate = nil
    }

    // Helper to check if the habit was completed today
    var isCompletedToday: Bool {
        guard let lastCompletedDate else { return false }
        return Calendar.current.isDateInToday(lastCompletedDate)
    }

    // Toggle completion and recalculate streak
    func toggleCompletion() {
        let calendar = Calendar.current

        if isCompletedToday {
            // Unchecking completion (Rollback)
            if streak > 0 {
                streak -= 1
            }
            lastCompletedDate = nil // Note: In a production app, you'd roll back to the previous completion date.
        } else {
            // Completing habit
            if let lastDate = lastCompletedDate {
                if calendar.isDateInYesterday(lastDate) {
                    // Completed yesterday, increment streak
                    streak += 1
                } else if !calendar.isDateInToday(lastDate) {
                    // Missed days, reset streak to 1
                    streak = 1
                }
            } else {
                // First time completing
                streak = 1
            }
            lastCompletedDate = Date()
        }
    }
}
