### Step 1: The Data Model (`Habit.swift`)
This SwiftData model stores the habit’s name, creation date, current streak, and the timestamp of the last completion.

```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var id: UUID
    var name: String
    var streak: Int
    var lastCompleted: Date?
    var dateCreated: Date

    init(name: String) {
        self.id = UUID()
        self.name = name
        self.streak = 0
        self.lastCompleted = nil
        self.dateCreated = Date()
    }

    /// Computed property to check if the habit has already been completed today
    var isCompletedToday: Bool {
        guard let lastCompleted = lastCompleted else { return false }
        return Calendar.current.isDateInToday(lastCompleted)
    }

    /// Handles completion logic and updates streak values
    func complete() {
        let calendar = Calendar.current
        let today = calendar.startOfDay(for: Date())

        guard !isCompletedToday else { return } // Prevent duplicate completions on the same day

        if let last = lastCompleted {
            let lastCompletedDay = calendar.startOfDay(for: last)
            let daysDifference = calendar.dateComponents([.day], from: lastCompletedDay, to: today).day ?? 0

            if daysDifference == 1 {
                // Completed consecutively (yesterday to today) -> Increment streak
                streak += 1
            } else if daysDifference > 1 {
                // Missed a day -> Reset streak
                streak = 1
            }
        } else {
            // First time completing this habit
            streak = 1
        }

        lastCompleted = Date()
    }
}
```

