import Foundation
import SwiftData

@Model
final class Habit {
    var id: UUID
    var name: String
    var streak: Int
    var lastCompletedDate: Date?

    init(name: String) {
        self.id = UUID()
        self.name = name
        self.streak = 0
        self.lastCompletedDate = nil
    }

    // Returns true if the habit was already completed today
    var isCompletedToday: Bool {
        guard let lastDate = lastCompletedDate else { return false }
        return Calendar.current.isDateInToday(lastDate)
    }

    // Logic to increment streak and update completion date
    func completeHabit() {
        let calendar = Calendar.current
        let today = Date()

        if isCompletedToday {
            // Already done today, do nothing
            return
        }

        if let lastDate = lastCompletedDate {
            if calendar.isDateInYesterday(lastDate) {
                // Streak continues
                streak += 1
            } else {
                // Streak was broken, reset to 1
                streak = 1
            }
        } else {
            // First time completing the habit
            streak = 1
        }

        lastCompletedDate = today
    }
}
