import SwiftUI
import SwiftData

// MARK: - 1. Data Model
@Model
final class Habit {
    var id: UUID
    var title: String
    var streak: Int
    var lastCompletedDate: Date?

    init(title: String) {
        self.id = UUID()
        self.title = title
        self.streak = 0
        self.lastCompletedDate = nil
    }

    // Check if the habit has been completed today
    var isCompletedToday: Bool {
        guard let lastCompletedDate else { return false }
        return Calendar.current.isDateInToday(lastCompletedDate)
    }

    // Handle toggling habit completion and calculating streaks
    func toggleCompletion() {
        let calendar = Calendar.current
        let now = Date()

        if isCompletedToday {
            // Undo today's completion
            streak = max(0, streak - 1)
            lastCompletedDate = nil // Simplified for minimal version
        } else {
            // Mark completed today
            if let lastDate = lastCompletedDate, calendar.isDateInYesterday(lastDate) {
                // Habit was completed yesterday, increment streak
                streak += 1
            } else if lastCompletedDate == nil {
                // First time completing
                streak = 1
            } else if !calendar.isDateInToday(lastCompletedDate!) {
                // Streak was broken, reset to 1
                streak = 1
            }
            lastCompletedDate = now
        }
    }
}

// MARK: - 2. Main View
