import SwiftUI
import SwiftData

// MARK: - 1. Habit Data Model
@Model
final class Habit {
    var id: UUID = UUID()
    var name: String = ""
    var isCompleted: Bool = false
    var streak: Int = 0
    var dateCreated: Date = Date()

    init(name: String) {
        self.name = name
        self.isCompleted = false
        self.streak = 0
        self.dateCreated = Date()
    }
}

// MARK: - 2. Main View
struct ContentView: View {
    // Fetch and auto-sync habits from local database (SwiftData)
    @Query(sort: \Habit.dateCreated, order: .reverse) private var habits: [Habit]
    @Environment(\.modelContext) private var modelContext

    @State private var showingAddSheet = false
    @State private var newHabitName = ""

    // Calculate daily progress
    private var completionRate: Double {
        guard !habits.isEmpty else { return 0 }
        let completed = habits.filter { $0.isCompleted }.count
        return Double(completed) / Double(habits.count)
    }

    var body: some View {
        NavigationStack {
            VStack(spacing: 20) {
                // Progress Header
                progressHeader
                    .padding(.horizontal)

                // Habits List
                if habits.isEmpty {
                    ContentUnavailableView(
                        "No Habits Yet",
                        systemImage: "calendar.badge.plus",
                        description: Text("Tap the '+' button to start tracking a new habit.")
                    )
                } else {
                    List {
                        ForEach(habits) { habit in
                            HabitRowView(habit: habit)
                        }
                        .onDelete(perform: deleteHabit)
                        .listRowSeparator(.hidden)
                        .listRowBackground(Color.clear)
                    }
                    .listStyle(.plain)
                }
            }
            .navigationTitle("My Habits")
            .toolbar {
                ToolbarItem(placement: .topBarTrailing) {
                    Button(action: { showingAddSheet = true }) {
                        Image(systemName: "plus.circle.fill")
                            .font(.title2)
                            .foregroundStyle(.blue)
                    }
                }
            }
            // Add Habit Modal
            .sheet(isPresented: $showingAddSheet) {
                addHabitSheet
            }
        }
    }

    // Progress UI Element
    private var progressHeader: some View {
        VStack(alignment: .leading, spacing: 8) {
            HStack {
                Text("Today's Progress")
                    .font(.headline)
                    .foregroundColor(.secondary)
                Spacer()
                Text("\(Int(completionRate * 100))%")
                    .font(.subheadline)
                    .bold()
                    .foregroundColor(.blue)
            }

            GeometryReader { geo in
                ZCornerProgressBar(progress: completionRate, width: geo.size.width)
            }
            .frame(height: 10)
        }
        .padding()
        .background(Color(.secondarySystemBackground))
        .cornerRadius(12)
    }

    // Bottom Sheet for adding a new habit
    private var addHabitSheet: some View {
        NavigationStack {
            Form {
                TextField("Habit Name (e.g., Drink Water)", text: $newHabitName)
                    .autocorrectionDisabled()
            }
            .navigationTitle("New Habit")
            .navigationBarTitleDisplayMode(.inline)
            .toolbar {
                ToolbarItem(placement: .cancellationAction) {
                    Button("Cancel") { showingAddSheet = false }
                }
                ToolbarItem(placement: .confirmationAction) {
                    Button("Save") {
                        addHabit()
                    }
                    .disabled(newHabitName.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty)
                }
            }
        }
        .presentationDetents([.fraction(0.3)])
    }

    // Core Data Operations
    private func addHabit() {
        let habit = Habit(name: newHabitName)
        modelContext.insert(habit)
        newHabitName = ""
        showingAddSheet = false
    }

    private func deleteHabit(at offsets: IndexSet) {
        for index in offsets {
            modelContext.delete(habits[index])
        }
    }
}

// MARK: - 3. Habit Row Component
struct HabitRowView: View {
    @Bindable var habit: Habit

    var body: some View {
        HStack {
            VStack(alignment: .leading) {
                Text(habit.name)
                    .font(.headline)
                    .strikethrough(habit.isCompleted)
                    .foregroundColor(habit.isCompleted ? .secondary : .primary)

                HStack(spacing: 4) {
                    Image(systemName: "flame.fill")
                        .foregroundColor(habit.streak > 0 ? .orange : .gray)
                    Text("\(habit.streak) day streak")
                        .font(.caption)
                        .foregroundColor(.secondary)
                }
            }

            Spacer()

            // Interactive Checkmark with Haptic Feedback
            Button(action: toggleCompletion) {
                Image(systemName: habit.isCompleted ? "checkmark.circle.fill" : "circle")
                    .font(.title)
                    .foregroundColor(habit.isCompleted ? .green : .gray)
                    .scaleEffect(habit.isCompleted ? 1.1 : 1.0)
                    .animation(.spring(response: 0.3, dampingFraction: 0.6), value: habit.isCompleted)
            }
            .buttonStyle(.plain)
        }
        .padding()
        .background(Color(.systemBackground))
        .cornerRadius(12)
        .shadow(color: Color.black.opacity(0.05), radius: 5, x: 0, y: 2)
    }

    private func toggleCompletion() {
        habit.isCompleted.toggle()

        // Simple streak logic
        if habit.isCompleted {
            habit.streak += 1
            // Trigger success haptic
            let generator = UINotificationFeedbackGenerator()
            generator.notificationOccurred(.success)
        } else {
            if habit.streak > 0 { habit.streak -= 1 }
            // Trigger light haptic
            let generator = UIImpactFeedbackGenerator(style: .light)
            generator.impactOccurred()
        }
    }
}

// MARK: - 4. Progress Bar Utility View
struct ZCornerProgressBar: View {
    var progress: Double
    var width: CGFloat

    var body: some View {
        ZStack(alignment: .leading) {
            Capsule()
                .fill(Color(.systemGray5))
                .frame(width: width)

            Capsule()
                .fill(Color.blue)
                .frame(width: max(0, min(width * CGFloat(progress), width)))
                .animation(.spring(response: 0.5, dampingFraction: 0.7), value: progress)
        }
    }
}

