// ui/BankingViewModel.kt
package com.securebank.app.ui

import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.securebank.app.data.AccountDetails
import com.securebank.app.data.BankingRepository
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.launch
import java.math.BigDecimal

sealed interface ScreenState {
    object Loading : ScreenState
    data class Success(val accountDetails: AccountDetails) : ScreenState
    data class Error(val message: String) : ScreenState
}

class BankingViewModel(
    private val repository: BankingRepository
) : ViewModel() {

    private val _uiState = MutableStateFlow<ScreenState>(ScreenState.Loading)
    val uiState: StateFlow<ScreenState> = _uiState.asStateFlow()

    init {
        loadDashboardData()
    }

    fun loadDashboardData() {
        viewModelScope.launch {
            _uiState.value = ScreenState.Loading
            repository.getAccountDetails()
                .onSuccess { details -> _uiState.value = ScreenState.Success(details) }
                .onFailure { _uiState.value = ScreenState.Error("Failed to fetch secure bank data.") }
        }
    }

    fun performTransfer(iban: String, amountString: String, onSuccess: () -> Unit, onError: (String) -> Unit) {
        val amount = amountString.toBigDecimalOrNull()

        // Input Validation: Prevents injection and negative value transactions
        if (amount == null || amount <= BigDecimal.ZERO) {
            onError("Invalid transaction amount.")
            return
        }
        if (iban.replace(" ", "").length < 15) {
            onError("Invalid IBAN/Account length.")
            return
        }

        viewModelScope.launch {
            repository.transferFunds(iban, amount)
                .onSuccess { 
                    loadDashboardData() // Refresh accounts
                    onSuccess()
                }
                .onFailure { onError(it.localizedMessage ?: "Transaction failed.") }
        }
    }
}
