### 5. Application Lifecycle & Security Best Practices
To ensure this application behaves like a real banking application, we must prevent screen sniffing (preventing screenshots/recording when the app is backgrounded) and intercept rooted devices.

```kotlin
// File: MainActivity.kt
package com.safevault.bank

import android.os.Bundle
import android.view.WindowManager
import androidx.activity.compose.setContent
import androidx.appcompat.app.AppCompatActivity
import com.safevault.bank.ui.screen.DashboardScreen
import com.safevault.bank.ui.viewmodel.BankViewModel

class MainActivity : AppCompatActivity() {
    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)

        // SECURITY FLAG: Prevents users/malicious background apps from taking screenshots 
        // or screen recording the banking details inside this activity.
        window.setFlags(
            WindowManager.LayoutParams.FLAG_SECURE,
            WindowManager.LayoutParams.FLAG_SECURE
        )

        setContent {
            // In a production environment, you would use Hilt or Koin to inject this ViewModel safely.
            val viewModel = BankViewModel()
            DashboardScreen(viewModel = viewModel)
        }
    }
}
