```kotlin
package com.securebank.android.ui

import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.securebank.android.data.AccountDetails
import com.securebank.android.data.BankingRepository
import com.securebank.android.data.Resource
import kotlinx.lifecycle.viewmodel.compose.viewModel
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.flow.update
import kotlinx.coroutines.launch

// Screen State
data class DashboardUiState(
    val isLoading: Boolean = false,
    val accountDetails: AccountDetails? = null,
    val isBalanceVisible: Boolean = false, // Security feature: defaults to hidden
    val errorMessage: String? = null
)

class DashboardViewModel(
    private val repository: BankingRepository
) : ViewModel() {

    private val _uiState = MutableStateFlow(DashboardUiState())
    val uiState: StateFlow<DashboardUiState> = _uiState.asStateFlow()

    init {
        fetchDashboardData()
    }

    fun fetchDashboardData() {
        viewModelScope.launch {
            repository.getAccountDetails().collect { result ->
                when (result) {
                    is Resource.Loading -> {
                        _uiState.update { it.copy(isLoading = true, errorMessage = null) }
                    }
                    is Resource.Success -> {
                        _uiState.update { it.copy(isLoading = false, accountDetails = result.data) }
                    }
                    is Resource.Error -> {
                        _uiState.update { it.copy(isLoading = false, errorMessage = result.exception.localizedMessage) }
                    }
                }
            }
        }
    }

    // Toggle balance visibility (prevents shoulder-surfing in public places)
    fun toggleBalanceVisibility() {
        _uiState.update { it.copy(isBalanceVisible = !it.isBalanceVisible) }
    }
}
