### 5. Main Activity (App Entry Point & Lifecycle Orchestration)

This activity brings the biometrics, state management, and UI screens together securely. It extends `FragmentActivity` because the Biometric library requires a fragment host context.

```kotlin
// MainActivity.kt
package com.securebank.app

import android.os.Bundle
import android.widget.Toast
import androidx.activity.compose.setContent
import androidx.activity.viewModels
import androidx.appcompat.app.AppCompatActivity
import androidx.compose.foundation.layout.*
import androidx.compose.material3.*
import androidx.compose.runtime.collectAsState
import androidx.compose.runtime.getValue
import androidx.compose.ui.Alignment
import androidx.compose.ui.Modifier
import androidx.compose.ui.unit.dp
import com.securebank.app.security.BiometricAuthenticator
import com.securebank.app.ui.BankingScreen
import com.securebank.app.viewmodel.BankingViewModel
import com.securebank.app.viewmodel.UiState

class MainActivity : AppCompatActivity() {

    private val viewModel: BankingViewModel by viewModels()
    private lateinit var biometricAuthenticator: BiometricAuthenticator

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        biometricAuthenticator = BiometricAuthenticator(applicationContext)

        setContent {
            MaterialTheme {
                Surface(
                    modifier = Modifier.fillMaxSize(),
                    color = MaterialTheme.colorScheme.background
                ) {
                    val uiState by viewModel.uiState.collectAsState()

                    when (val state = uiState) {
                        is UiState.Locked -> {
                            Column(
                                modifier = Modifier.fillMaxSize(),
                                verticalArrangement = Arrangement.Center,
                                horizontalAlignment = Alignment.CenterHorizontally
                            ) {
                                Text("Secure Bank App", style = MaterialTheme.typography.headlineMedium)
                                Spacer(modifier = Modifier.height(16.dp))
                                Button(onClick = { triggerBiometricAuth() }) {
                                    Text("Unlock with Biometrics")
                                }
                            }
                        }
                        is UiState.Loading -> {
                            Box(modifier = Modifier.fillMaxSize(), contentAlignment = Alignment.Center) {
                                CircularProgressIndicator()
                            }
                        }
                        is UiState.Success -> {
                            BankingScreen(
                                account = state.account,
                                transactions = state.transactions,
                                onLogout = { viewModel.lockApp() }
                            )
                        }
                        is UiState.Error -> {
                            Box(modifier = Modifier.fillMaxSize(), contentAlignment = Alignment.Center) {
                                Text(text = "Error: ${state.message}", color = MaterialTheme.colorScheme.error)
                            }
                        }
                    }
                }
            }
        }

        // Auto-authenticate on launch
        triggerBiometricAuth()
    }

    private fun triggerBiometricAuth() {
        if (biometricAuthenticator.isBiometricAvailable()) {
            biometricAuthenticator.authenticate(
                activity = this,
                onSuccess = {
                    viewModel.unlockApp()
                },
                onError = { errorCode, errString ->
                    Toast.makeText(this, "Auth error: $errString", Toast.LENGTH_SHORT).show()
                },
                onFailed = {
                    Toast.makeText(this, "Authentication failed", Toast.LENGTH_SHORT).show()
                }
            )
        } else {
            // Fallback for emulators or devices without hardware security features
            Toast.makeText(this, "Biometrics not set up. Bypassing for Demo.", Toast.LENGTH_LONG).show()
            viewModel.unlockApp()
        }
    }

    // Security practice: Lock application when user minimizes it
    override fun onStop() {
        super.onStop()
        viewModel.lockApp()
    }
}
