### Step 3: ViewModel (Handling Business Logic Safely)
The ViewModel processes financial calculations, performs validation (e.g., checking for insufficient funds), and exposes state securely via a read-only `StateFlow`.

```kotlin
package com.securebank.android.viewmodel

import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.securebank.android.data.AccountDetails
import com.securebank.android.data.BankingRepository
import com.securebank.android.data.BankingUiState
import com.securebank.android.data.Transaction
import com.securebank.android.data.TransactionType
import kotlinx.flow.MutableStateFlow
import kotlinx.flow.StateFlow
import kotlinx.flow.asStateFlow
import kotlinx.coroutines.launch
import java.util.Date

class BankingViewModel(
    private val repository: BankingRepository = BankingRepository()
) : ViewModel() {

    private val _uiState = MutableStateFlow<BankingUiState>(BankingUiState.Loading)
    val uiState: StateFlow<BankingUiState> = _uiState.asStateFlow()

    init {
        loadAccountData()
    }

    fun loadAccountData() {
        viewModelScope.launch {
            _uiState.value = BankingUiState.Loading
            try {
                val data = repository.fetchAccountDetails()
                _uiState.value = BankingUiState.Success(data)
            } catch (e: Exception) {
                _uiState.value = BankingUiState.Error("Failed to connect to secure servers.")
            }
        }
    }

    // Business Logic: Securely validating and executing a transfer
    fun executeTransfer(recipientName: String, amount: Double, onSuccess: () -> Unit, onError: (String) -> Unit) {
        val currentState = _uiState.value
        if (currentState is BankingUiState.Success) {
            val currentDetails = currentState.accountDetails

            // Validation Rules
            if (amount <= 0) {
                onError("Invalid transfer amount.")
                return
            }
            if (currentDetails.availableBalance < amount) {
                onError("Insufficient funds for transfer.")
                return
            }
            if (recipientName.isBlank()) {
                onError("Recipient name cannot be blank.")
                return
            }

            viewModelScope.launch {
                _uiState.value = BankingUiState.Loading

                // Simulate secure API ledger write transaction
                delay(1000) 

                val newTransaction = Transaction(
                    description = "Transfer to $recipientName",
                    amount = amount,
                    date = Date(),
                    type = TransactionType.DEBIT
                )

                val updatedDetails = currentDetails.copy(
                    availableBalance = currentDetails.availableBalance - amount,
                    transactions = listOf(newTransaction) + currentDetails.transactions
                )

                _uiState.value = BankingUiState.Success(updatedDetails)
                onSuccess()
            }
        }
    }
}
