### Step 4: Logic Layer (ViewModel)
The `BankingViewModel` handles business logic. It simulates fetching balance and transaction history from a secure backend and handles a transfer operation.

```kotlin
package com.securebank.app.ui

import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.securebank.app.data.BankingUiState
import com.securebank.app.data.Transaction
import kotlinx.coroutines.delay
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.launch

class BankingViewModel : ViewModel() {

    private val _uiState = MutableStateFlow<BankingUiState>(BankingUiState.Locked)
    val uiState: StateFlow<BankingUiState> = _uiState.asStateFlow()

    fun unlockApp() {
        _uiState.value = BankingUiState.Loading
        viewModelScope.launch {
            // Simulate secure API/Database fetch
            delay(1000)
            _uiState.value = BankingUiState.Success(
                accountHolder = "Jane Doe",
                balance = 5420.50,
                transactions = listOf(
                    Transaction(description = "Salary", amount = 3500.00, date = "Oct 25", isIncoming = true),
                    Transaction(description = "Grocery Store", amount = 124.30, date = "Oct 24", isIncoming = false),
                    Transaction(description = "Coffee Shop", amount = 4.75, date = "Oct 23", isIncoming = false)
                )
            )
        }
    }

    fun makeTransfer(recipient: String, amount: Double) {
        val currentState = _uiState.value
        if (currentState is BankingUiState.Success) {
            if (currentState.balance >= amount) {
                val updatedTransactions = listOf(
                    Transaction(description = "To $recipient", amount = amount, date = "Today", isIncoming = false)
                ) + currentState.transactions

                _uiState.value = currentState.copy(
                    balance = currentState.balance - amount,
                    transactions = updatedTransactions
                )
            }
        }
    }

    fun lockApp() {
        _uiState.value = BankingUiState.Locked
    }
}
```

