### Step 6: Main Activity Integration
We bind the view layer with the Android life cycle in the `MainActivity`. Note that we inherit from `FragmentActivity` (rather than `ComponentActivity`) because `BiometricPrompt` requires a fragment activity context.

```kotlin
package com.securebank.app

import android.os.Bundle
import android.widget.Toast
import androidx.activity.compose.setContent
import androidx.activity.viewModels
import androidx.compose.runtime.collectAsState
import androidx.compose.runtime.getValue
import androidx.fragment.app.FragmentActivity
import com.securebank.app.security.BiometricAuthenticator
import com.securebank.app.ui.BankingScreen
import com.securebank.app.ui.BankingViewModel

class MainActivity : FragmentActivity() {

    private val viewModel: BankingViewModel by viewModels()
    private lateinit var authenticator: BiometricAuthenticator

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        authenticator = BiometricAuthenticator(this)

        setContent {
            val uiState by viewModel.uiState.collectAsState()

            BankingScreen(
                uiState = uiState,
                onAuthenticate = { triggerBiometricAuth() },
                onTransferClick = { recipient, amount ->
                    viewModel.makeTransfer(recipient, amount)
                }
            )
        }
    }

    private fun triggerBiometricAuth() {
        authenticator.authenticate(
            onSuccess = {
                viewModel.unlockApp()
            },
            onError = { code, error ->
                Toast.makeText(this, "Authentication error: $error", Toast.LENGTH_SHORT).show()
            },
            onFailed = {
                Toast.makeText(this, "Authentication failed. Try again.", Toast.LENGTH_SHORT).show()
            }
        )
    }

    override fun onPause() {
        super.onPause()
        // Security best practice: Lock app when it goes to background
        viewModel.lockApp()
    }
}
