            val color = if (transaction.isCredit) Color(0xFF388E3C) else Color(0xFFD32F2F)
            Text(
                text = "$prefix$${String.format("%.2f", transaction.amount)}",
                color = color,
                fontWeight = FontWeight.Bold
            )
        }
    }
}
```

