Create `ui/dashboard/DashboardViewModel.kt`:

```kotlin
package com.securebank.app.ui.dashboard

import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.securebank.app.data.repository.BankRepository
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.flow.zip
import kotlinx.coroutines.launch

class DashboardViewModel(
    private val repository: BankRepository = BankRepository()
) : ViewModel() {

    private val _uiState = MutableStateFlow<DashboardUiState>(DashboardUiState.Loading)
    val uiState: StateFlow<DashboardUiState> = _uiState.asStateFlow()

    init {
        loadFinancialData()
    }

    fun loadFinancialData() {
        viewModelScope.launch {
            _uiState.value = DashboardUiState.Loading
            try {
                // Zip flows to run calls concurrently, minimizing loading times
                repository.getAccountDetails()
                    .zip(repository.getTransactionHistory()) { account, transactions ->
                        DashboardUiState.Success(account, transactions)
                    }.collect { state ->
                        _uiState.value = state
                    }
            } catch (e: Exception) {
                _uiState.value = DashboardUiState.Error("Failed to load account details safely.")
            }
        }
    }
}
```

