import kotlinx.coroutines.flow.asStateFlow
import java.util.UUID

// ==========================================
// 1. DATA MODELS & STATE
// ==========================================
data class Transaction(
    val id: String = UUID.randomUUID().toString(),
    val description: String,
    val amount: Double,
    val isIncoming: Boolean,
    val date: String
)

data class AccountState(
    val balance: Double = 5240.50,
    val transactions: List<Transaction> = listOf(
        Transaction(description = "Paycheck - TechCorp", amount = 2500.00, isIncoming = true, date = "Oct 24"),
        Transaction(description = "Grocery Store", amount = 84.20, isIncoming = false, date = "Oct 23"),
        Transaction(description = "Coffee Shop", amount = 4.75, isIncoming = false, date = "Oct 22")
    ),
    val isAuthenticated: Boolean = false,
    val currentScreen: Screen = Screen.Login
)

sealed class Screen {
    object Login : Screen()
    object Dashboard : Screen()
    object Transfer : Screen()
}

// ==========================================
// 2. VIEWMODEL (Business Logic & State Management)
// ==========================================
class BankingViewModel : ViewModel() {
    private val _uiState = MutableStateFlow(AccountState())
    val uiState: StateFlow<AccountState> = _uiState.asStateFlow()

    fun authenticate(pin: String): Boolean {
        return if (pin == "1234") { // Mock PIN verification
            _uiState.value = _uiState.value.copy(
                isAuthenticated = true,
                currentScreen = Screen.Dashboard
            )
            true
        } else {
            false
        }
    }

    fun executeTransfer(recipient: String, amount: Double): Boolean {
        val currentBalance = _uiState.value.balance
        if (amount <= 0 || amount > currentBalance) return false

        val newTransaction = Transaction(
            description = "To: $recipient",
            amount = amount,
            isIncoming = false,
            date = "Today"
        )

        _uiState.value = _uiState.value.copy(
            balance = currentBalance - amount,
            transactions = listOf(newTransaction) + _uiState.value.transactions,
            currentScreen = Screen.Dashboard
        )
        return true
    }

    fun navigateTo(screen: Screen) {
        _uiState.value = _uiState.value.copy(currentScreen = screen)
    }

    fun logout() {
        _uiState.value = AccountState() // Reset State securely
    }
}

// ==========================================
// 3. UI COMPONENTS (Jetpack Compose)
// ==========================================
class MainActivity : ComponentActivity() {
    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        setContent {
            MaterialTheme(colorScheme = darkColorScheme(
                primary = Color(0xFF00E676),      // Secure Green
                background = Color(0xFF121212),   // Dark Mode Theme
                surface = Color(0xFF1E1E1E)
            )) {
                Surface(
                    modifier = Modifier.fillMaxSize(),
                    color = MaterialTheme.colorScheme.background
                ) {
                    BankingApp()
                }
            }
        }
    }
}

@Composable
fun BankingApp(viewModel: BankingViewModel = viewModel()) {
    val state by viewModel.uiState.collectAsState()

    switchScreen(state.currentScreen, viewModel, state)
}

@Composable
fun switchScreen(screen: Screen, viewModel: BankingViewModel, state: AccountState) {
    when (screen) {
        is Screen.Login -> LoginScreen(onLoginAttempt = { pin -> viewModel.authenticate(pin) })
        is Screen.Dashboard -> DashboardScreen(
            state = state,
            onTransferClick = { viewModel.navigateTo(Screen.Transfer) },
            onLogout = { viewModel.logout() }
        )
        is Screen.Transfer -> TransferScreen(
            onBack = { viewModel.navigateTo(Screen.Dashboard) },
            onTransferExecute = { recipient, amount -> viewModel.executeTransfer(recipient, amount) }
        )
    }
}

