### Step 2: State & Business Logic (`BankingViewModel.kt`)
In a real banking app, sensitive data is fetched via secure HTTPS APIs and stored in encrypted local databases (like SQLCipher). Here, we manage the state securely in memory using Kotlin's `StateFlow`.

```kotlin
package com.example.securebank

import androidx.lifecycle.ViewModel
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.flow.update
import java.text.NumberFormat
import java.util.Locale

data class Transaction(val description: String, val amount: Double, val isIncome: Boolean)

data class BankUiState(
    val balance: Double = 5240.50,
    val transactions: List<Transaction> = listOf(
        Transaction("Salary Deposit", 3500.00, true),
        Transaction("Supermarket", 120.50, false),
        Transaction("Streaming Subscription", 14.99, false)
    ),
    val isAuthenticated: Boolean = false,
    val errorMessage: String? = null
)

class BankingViewModel : ViewModel() {
    private val _uiState = MutableStateFlow(BankUiState())
    val uiState: StateFlow<BankUiState> = _uiState.asStateFlow()

    // Real apps would use Android Keystore / Biometrics to verify this PIN
    fun authenticate(pin: String): Boolean {
        return if (pin == "1234") {
            _uiState.update { it.copy(isAuthenticated = true, errorMessage = null) }
            true
        } else {
            _uiState.update { it.copy(errorMessage = "Invalid PIN. Try '1234'") }
            false
        }
    }

    fun executeTransfer(recipient: String, amount: Double): Boolean {
        if (amount <= 0) {
            _uiState.update { it.copy(errorMessage = "Invalid amount") }
            return false
        }
        if (_uiState.value.balance < amount) {
            _uiState.update { it.copy(errorMessage = "Insufficient funds") }
            return false
        }

        _uiState.update { currentState ->
            val updatedTransactions = listOf(
                Transaction("Transfer to $recipient", amount, false)
            ) + currentState.transactions

            currentState.copy(
                balance = currentState.balance - amount,
                transactions = updatedTransactions,
                errorMessage = null
            )
        }
        return true
    }

    fun logout() {
        _uiState.update { it.copy(isAuthenticated = false) }
    }

    fun clearError() {
        _uiState.update { it.copy(errorMessage = null) }
    }
}

// Utility to format currency securely
fun Double.formatAsCurrency(): String {
    return NumberFormat.getCurrencyInstance(Locale.US).format(this)
}
