extern "C" JNIEXPORT jstring JNICALL
Java_com_example_bank_MainActivity_getSecureEndpoint(JNIEnv* env, jobject /* this */) {
    // Obfuscated/Native storage of sensitive API endpoint
    return env->NewStringUTF("https://api.secure-internal-bank.com/v2/transact");
}
