### `App.tsx`

```tsx
import React, { useState, useEffect, useCallback } from 'react';
import {
  StyleSheet,
  Text,
  View,
  TextInput,
  TouchableOpacity,
  FlatList,
  SafeAreaView,
  ActivityIndicator,
  Alert,
  KeyboardAvoidingView,
  Platform,
} from 'react-native';
import * as SQLite from 'expo-sqlite';
import NetInfo from '@react-native-community/netinfo';

// --- TYPES ---
interface Survey {
  id: string;
  location_name: string;
  notes: string;
  latitude: number;
  longitude: number;
  timestamp: string;
  synced: number; // 0 = false, 1 = true
}

// Mock API endpoint (Replace this with your actual backend URL)
const BACKEND_API_URL = 'https://api.example.com/surveys';

// Open SQLite Database (Creates it if it doesn't exist)
const db = SQLite.openDatabaseSync('field_survey.db');

export default function App() {
  const [locationName, setLocationName] = useState('');
  const [notes, setNotes] = useState('');
  const [surveys, setSurveys] = useState<Survey[]>([]);
  const [isOnline, setIsOnline] = useState<boolean | null>(null);
  const [isSyncing, setIsSyncing] = useState(false);

  // --- 1. INITIALIZE DATABASE ---
  useEffect(() => {
    try {
      db.execSync(`
        CREATE TABLE IF NOT EXISTS surveys (
          id TEXT PRIMARY KEY NOT NULL,
          location_name TEXT NOT NULL,
          notes TEXT,
          latitude REAL,
          longitude REAL,
          timestamp TEXT NOT NULL,
          synced INTEGER DEFAULT 0
        );
      `);
      fetchLocalSurveys();
    } catch (error) {
      console.error('Failed to initialize database:', error);
    }
  }, []);

  // --- 2. FETCH LOCAL SURVEYS FROM SQLITE ---
  const fetchLocalSurveys = useCallback(() => {
    try {
      const allRows = db.getAllSync<Survey>(
        'SELECT * FROM surveys ORDER BY timestamp DESC'
      );
      setSurveys(allRows);
    } catch (error) {
      console.error('Error reading local SQLite data:', error);
    }
  }, []);

  // --- 3. MONITOR NETWORK AND AUTO-SYNC ON RECONNECT ---
  useEffect(() => {
    const unsubscribe = NetInfo.addEventListener((state) => {
      const currentlyOnline = !!state.isConnected && !!state.isInternetReachable;

      // If we just transitioned from offline to online, trigger sync
      if (currentlyOnline && isOnline === false) {
        console.log('Network re-connected! Triggering sync...');
        syncPendingSurveys();
      }

      setIsOnline(currentlyOnline);
    });

    return () => unsubscribe();
  }, [isOnline]);

  // --- 4. SAVE SURVEY LOCALLY (OFFLINE-FIRST) ---
  const handleSaveSurvey = async () => {
    if (!locationName.trim()) {
      Alert.alert('Validation Error', 'Location name is required.');
      return;
    }

    const newSurvey: Survey = {
      id: Math.random().toString(36).substring(2, 15), // UUID-like string
      location_name: locationName,
      notes: notes,
      // Mocking coordinates for simplicity (In real-world, use expo-location)
      latitude: 45.5152, 
      longitude: -122.6784,
      timestamp: new Date().toISOString(),
      synced: 0, // Mark as offline/unsynced first
    };

    try {
      db.runSync(
        `INSERT INTO surveys (id, location_name, notes, latitude, longitude, timestamp, synced) 
         VALUES (?, ?, ?, ?, ?, ?, ?);`,
        [
          newSurvey.id,
          newSurvey.location_name,
          newSurvey.notes,
          newSurvey.latitude,
          newSurvey.longitude,
          newSurvey.timestamp,
          newSurvey.synced,
        ]
      );

      // Reset form and update local UI instantly
      setLocationName('');
      setNotes('');
      fetchLocalSurveys();

      // Attempt background sync immediately if we are online
      if (isOnline) {
        syncPendingSurveys();
      } else {
        Alert.alert('Saved Offline', 'Survey saved locally. It will sync automatically when connection is restored.');
      }
    } catch (error) {
      console.error('Failed to save survey locally:', error);
      Alert.alert('Error', 'Failed to save survey locally.');
    }
  };

  // --- 5. SYNCHRONIZATION ALGORITHM ---
  const syncPendingSurveys = async () => {
    if (isSyncing) return;
    setIsSyncing(true);

    try {
      // Get all unsynced local surveys
      const pendingSurveys = db.getAllSync<Survey>(
        'SELECT * FROM surveys WHERE synced = 0'
      );

      if (pendingSurveys.length === 0) {
        setIsSyncing(false);
        return;
      }

      console.log(`Syncing ${pendingSurveys.length} surveys to server...`);

      for (const survey of pendingSurveys) {
        try {
          // --- REAL HTTP SYNC REQUEST MOCK ---
          // Replace this block with your actual fetch call:
          /*
          const response = await fetch(BACKEND_API_URL, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(survey),
          });
          if (!response.ok) throw new Error('Server error');
          */

          // Simulating a network roundtrip delay
          await new Promise((resolve) => setTimeout(resolve, 1000)); 

          // Update local DB status to "synced" upon successful upload
          db.runSync('UPDATE surveys SET synced = 1 WHERE id = ?', [survey.id]);
          console.log(`Successfully synced survey: ${survey.id}`);
        } catch (err) {
          console.error(`Failed to sync survey ${survey.id}:`, err);
          // Don't throw here; allow other surveys in the loop to attempt sync
        }
      }

      // Refresh the UI to show updated sync statuses
      fetchLocalSurveys();
    } catch (error) {
      console.error('Error during synchronization:', error);
    } finally {
      setIsSyncing(false);
    }
  };

  // --- 6. RENDER INDIVIDUAL SURVEY LIST ITEM ---
  const renderSurveyItem = ({ item }: { item: Survey }) => (
    <View style={styles.surveyCard}>
      <View style={styles.surveyHeader}>
        <Text style={styles.surveyTitle}>{item.location_name}</Text>
        <View style={[styles.badge, item.synced ? styles.syncedBadge : styles.pendingBadge]}>
          <Text style={styles.badgeText}>{item.synced ? 'Synced' : 'Pending Sync'}</Text>
        </View>
      </View>
      {item.notes ? <Text style={styles.surveyNotes}>{item.notes}</Text> : null}
      <Text style={styles.surveyTime}>{new Date(item.timestamp).toLocaleTimeString()}</Text>
    </View>
  );

  return (
    <SafeAreaView style={styles.safeArea}>
      <KeyboardAvoidingView
        behavior={Platform.OS === 'ios' ? 'padding' : 'height'}
        style={styles.container}
      >
        {/* Network Status Header */}
        <View style={[styles.statusBar, isOnline ? styles.online : styles.offline]}>
          <Text style={styles.statusText}>
            {isOnline ? '🟢 Connected (Online)' : '🔴 Offline Mode'}
          </Text>
          {isSyncing && <ActivityIndicator size="small" color="#fff" style={{ marginLeft: 8 }} />}
        </View>

        {/* Survey Input Form */}
        <View style={styles.formContainer}>
          <Text style={styles.headerTitle}>Field Survey Entry</Text>
          <TextInput
            style={styles.input}
            placeholder="Location/Asset Name"
            value={locationName}
            onChangeText={setLocationName}
            placeholderTextColor="#888"
          />
          <TextInput
            style={[styles.input, styles.textArea]}
            placeholder="Observational notes..."
            value={notes}
            onChangeText={setNotes}
            multiline
            numberOfLines={4}
            placeholderTextColor="#888"
          />
          <TouchableOpacity style={styles.saveButton} onPress={handleSaveSurvey}>
            <Text style={styles.saveButtonText}>Save Survey</Text>
          </TouchableOpacity>
        </View>

        {/* Local Surveys Database List */}
        <View style={styles.listContainer}>
          <View style={styles.listHeader}>
            <Text style={styles.listTitle}>Local Survey Records</Text>
            {isOnline && (
              <TouchableOpacity onPress={syncPendingSurveys} disabled={isSyncing}>
                <Text style={styles.syncBtnText}>{isSyncing ? 'Syncing...' : 'Sync Now'}</Text>
              </TouchableOpacity>
            )}
          </View>

          <FlatList
            data={surveys}
            keyExtractor={(item) => item.id}
            renderItem={renderSurveyItem}
            contentContainerStyle={styles.listContent}
            ListEmptyComponent={
              <Text style={styles.emptyText}>No surveys captured yet.</Text>
            }
          />
        </View>
      </KeyboardAvoidingView>
    </SafeAreaView>
  );
}

