### 1. Database Configuration (`db.ts`)
This defines our local schema and indices for fast querying.

```typescript
import Dexie, { Table } from 'dexie';

// Define the structure of our Survey Record
export interface SurveyRecord {
  id?: number;              // Local auto-incremented primary key
  uuid: string;             // Globally unique ID for server matching
  surveyorName: string;
  locationName: string;
  latitude: number;
  longitude: number;
  notes: string;
  syncStatus: 'pending' | 'synced' | 'failed';
  createdAt: number;
}

class SurveyDatabase extends Dexie {
  surveys!: Table<SurveyRecord>;

  constructor() {
    super('SurveyDatabase');
    this.version(1).stores({
      surveys: '++id, uuid, syncStatus, createdAt' // index syncStatus for fast lookup of unsynced items
    });
  }
}

export const db = new SurveyDatabase();
```

