### 2. Synchronization Engine (`syncEngine.ts`)
This module handles pushing offline data to the server when connection is available.

```typescript
import { db, SurveyRecord } from './db';

// Mock API endpoint for demonstration
const BACKEND_API_URL = 'https://api.example.com/surveys';

/**
 * Simulates sending a single survey to the remote server.
 */
async function uploadSurveyToServer(survey: SurveyRecord): Promise<void> {
  // In a real application, you would uncomment the fetch block below:
  /*
  const response = await fetch(BACKEND_API_URL, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(survey),
  });
  if (!response.ok) throw new Error('Server failed to process survey');
  */

  // Mock network latency and success
  return new Promise((resolve, reject) => {
    setTimeout(() => {
      if (navigator.onLine) {
        console.log(`Successfully synced survey UUID: ${survey.uuid}`);
        resolve();
      } else {
        reject(new Error('Network disconnected during sync'));
      }
    }, 1000); 
  });
}

/**
 * Iterates through all 'pending' and 'failed' records and syncs them.
 */
export async function syncOfflineData(): Promise<{ successCount: number; failCount: number }> {
  if (!navigator.onLine) {
    console.log('Sync aborted: Device is currently offline.');
    return { successCount: 0, failCount: 0 };
  }

  // Fetch all records that need syncing
  const pendingSurveys = await db.surveys
    .where('syncStatus')
    .anyOf(['pending', 'failed'])
    .toArray();

  if (pendingSurveys.length === 0) {
    console.log('No pending syncs found.');
    return { successCount: 0, failCount: 0 };
  }

  console.log(`Starting sync of ${pendingSurveys.length} survey(s)...`);
  let successCount = 0;
  let failCount = 0;

  for (const survey of pendingSurveys) {
    try {
      await uploadSurveyToServer(survey);

      // Update local record to 'synced' on success
      if (survey.id !== undefined) {
        await db.surveys.update(survey.id, { syncStatus: 'synced' });
        successCount++;
      }
    } catch (error) {
      console.error(`Failed to sync survey ${survey.uuid}:`, error);

      if (survey.id !== undefined) {
        await db.surveys.update(survey.id, { syncStatus: 'failed' });
        failCount++;
      }
    }
  }

  return { successCount, failCount };
}
```

