```tsx
import React, { useState, useEffect } from 'react';
import { useLiveQuery } from 'dexie-react-hooks';
import { v4 as uuidv4 } from 'uuid';
import { db, SurveyRecord } from './db';
import { syncOfflineData } from './syncEngine';

export default function App() {
  // 1. Form States
  const [surveyor, setSurveyor] = useState('');
  const [locationName, setLocationName] = useState('');
  const [notes, setNotes] = useState('');
  const [coords, setCoords] = useState<{ lat: number; lng: number } | null>(null);

  // 2. UI & Connection States
  const [isOnline, setIsOnline] = useState(navigator.onLine);
  const [isSyncing, setIsSyncing] = useState(false);
  const [syncMessage, setSyncMessage] = useState('');

  // 3. Reactive Database Queries
  const surveys = useLiveQuery(() => db.surveys.orderBy('createdAt').reverse().toArray()) || [];
  const pendingCount = useLiveQuery(() => db.surveys.where('syncStatus').anyOf(['pending', 'failed']).count()) || 0;

  // Track online/offline status and trigger auto-sync
  useEffect(() => {
    const handleOnline = async () => {
      setIsOnline(true);
      setSyncMessage('Connection restored. Auto-syncing...');
      setIsSyncing(true);
      const results = await syncOfflineData();
      setIsSyncing(false);
      setSyncMessage(`Sync completed: ${results.successCount} synced, ${results.failCount} failed.`);
    };

    const handleOffline = () => {
      setIsOnline(false);
      setSyncMessage('You are offline. Surveys will be saved locally.');
    };

    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);

    // Initial sync check on app load
    if (isOnline) {
      syncOfflineData();
    }

    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, [isOnline]);

  // Fetch device GPS coordinates
  const captureGPS = () => {
    if (!navigator.geolocation) {
      alert('Geolocation is not supported by your device browser.');
      return;
    }
    navigator.geolocation.getCurrentPosition(
      (position) => {
        setCoords({
          lat: position.coords.latitude,
          lng: position.coords.longitude,
        });
      },
      (error) => {
        alert('Error capturing GPS: ' + error.message);
      }
    );
  };

  // Submit Survey Handler
  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!coords) {
      alert('Please capture GPS coordinates before saving.');
      return;
    }

    const newSurvey: SurveyRecord = {
      uuid: uuidv4(),
      surveyorName: surveyor,
      locationName: locationName,
      latitude: coords.lat,
      longitude: coords.lng,
      notes: notes,
      syncStatus: 'pending',
      createdAt: Date.now(),
    };

    try {
      // 1. Write to local-first database immediately
      await db.surveys.add(newSurvey);

      // Clear form inputs
      setLocationName('');
      setNotes('');
      setCoords(null);

      // 2. Attempt sync immediately in background if online
      if (isOnline) {
        syncOfflineData();
      }
    } catch (err) {
      console.error('Failed to save survey locally:', err);
    }
  };

  return (
    <div style={styles.container}>
      <header style={styles.header}>
        <h1>Field Survey Tool (Offline-First)</h1>
        <div style={styles.statusBar}>
          <span style={isOnline ? styles.onlineBadge : styles.offlineBadge}>
            ● {isOnline ? 'ONLINE' : 'OFFLINE'}
          </span>
          {pendingCount > 0 && (
            <span style={styles.pendingBadge}>
              {pendingCount} unsynced record(s)
            </span>
          )}
        </div>
      </header>

      {syncMessage && <div style={styles.syncNotification}>{syncMessage}</div>}

      <main style={styles.main}>
        {/* Input Form */}
        <section style={styles.formSection}>
          <h2>New Survey</h2>
          <form onSubmit={handleSubmit} style={styles.form}>
            <label style={styles.label}>
              Surveyor Name
              <input 
                type="text" 
                required 
                value={surveyor} 
                onChange={(e) => setSurveyor(e.target.value)} 
                style={styles.input}
              />
            </label>

            <label style={styles.label}>
              Location/Asset Name
              <input 
                type="text" 
                required 
                value={locationName} 
                onChange={(e) => setLocationName(e.target.value)} 
                style={styles.input}
              />
            </label>

            <div style={styles.gpsRow}>
              <button type="button" onClick={captureGPS} style={styles.buttonSecondary}>
                📍 Capture GPS
              </button>
              {coords ? (
                <span style={styles.coordsText}>
                  {coords.lat.toFixed(5)}, {coords.lng.toFixed(5)}
                </span>
              ) : (
                <span style={{ color: '#d9534f' }}>No GPS coordinates</span>
              )}
            </div>

            <label style={styles.label}>
              Notes / Observations
              <textarea 
                value={notes} 
                onChange={(e) => setNotes(e.target.value)} 
                style={styles.textarea}
              />
            </label>

            <button type="submit" style={styles.buttonPrimary}>
              Save Survey Local
            </button>
          </form>
        </section>

        {/* Local History & Sync Status List */}
        <section style={styles.historySection}>
          <div style={styles.historyHeader}>
            <h2>Survey History</h2>
            <button 
              onClick={() => { setIsSyncing(true); syncOfflineData().then(() => setIsSyncing(false)); }} 
              disabled={!isOnline || isSyncing}
              style={styles.buttonSync}
            >
              {isSyncing ? 'Syncing...' : 'Sync Now 🔄'}
            </button>
          </div>

          <div style={styles.listContainer}>
            {surveys.length === 0 ? (
              <p>No surveys logged yet.</p>
            ) : (
              surveys.map((s) => (
                <div key={s.id} style={styles.surveyCard}>
                  <div style={styles.cardHeader}>
                    <strong>{s.locationName}</strong>
                    <span style={styles.syncStatus(s.syncStatus)}>
                      {s.syncStatus === 'synced' ? '✓ Synced' : s.syncStatus === 'pending' ? '⏳ Offline Saved' : '⚠ Sync Failed'}
                    </span>
                  </div>
                  <p style={styles.cardMeta}>Surveyor: {s.surveyorName} | Date: {new Date(s.createdAt).toLocaleString()}</p>
                  <p style={styles.cardMeta}>GPS: {s.latitude}, {s.longitude}</p>
                  {s.notes && <p style={styles.cardNotes}>"{s.notes}"</p>}
                </div>
              ))
            )}
          </div>
        </section>
      </main>
    </div>
  );
}

