### Step 2: The Database Module (`database.ts`)
This file initializes the SQLite database and handles all CRUD operations locally.

```typescript
// database.ts
import * as SQLite from 'expo-sqlite';

export interface Survey {
  id: string;
  location_name: string;
  latitude: number;
  longitude: number;
  notes: string;
  synced: number; // 0 = false, 1 = true
  timestamp: string;
}

const db = SQLite.openDatabaseSync('surveys.db');

export const initDatabase = () => {
  db.execSync(`
    CREATE TABLE IF NOT EXISTS surveys (
      id TEXT PRIMARY KEY NOT NULL,
      location_name TEXT NOT NULL,
      latitude REAL NOT NULL,
      longitude REAL NOT NULL,
      notes TEXT,
      synced INTEGER DEFAULT 0,
      timestamp TEXT NOT NULL
    );
  `);
};

// Insert a new survey locally (defaults to synced = 0)
export const saveSurveyLocally = (survey: Omit<Survey, 'synced'>): void => {
  db.runSync(
    `INSERT INTO surveys (id, location_name, latitude, longitude, notes, synced, timestamp) 
     VALUES (?, ?, ?, ?, ?, 0, ?);`,
    [
      survey.id,
      survey.location_name,
      survey.latitude,
      survey.longitude,
      survey.notes,
      survey.timestamp,
    ]
  );
};

// Retrieve surveys that have not been synced yet
export const getUnsyncedSurveys = (): Survey[] => {
  return db.getAllSync<Survey>('SELECT * FROM surveys WHERE synced = 0;');
};

// Retrieve all surveys (for UI display)
export const getAllSurveys = (): Survey[] => {
  return db.getAllSync<Survey>('SELECT * FROM surveys ORDER BY timestamp DESC;');
};

// Mark a survey as successfully synced
export const markAsSynced = (id: string): void => {
  db.runSync('UPDATE surveys SET synced = 1 WHERE id = ?;', [id]);
};
```

