```typescript
// db.ts
import Dexie, { Table } from 'dexie';

export interface Survey {
  id?: number;
  uuid: string;         // Client-generated unique ID
  surveyorName: string;
  locationName: string;
  soilMoisture: number; // Example survey metric
  vegetationCover: string;
  latitude: number;
  longitude: number;
  createdAt: number;
  syncStatus: 'pending' | 'synced';
}

class SurveyDatabase extends Dexie {
  surveys!: Table<Survey>;

  constructor() {
    super('SurveyDatabase');
    this.version(1).stores({
      // Primary key is auto-incremented local id
      // Indexing uuid and syncStatus for fast sync lookups
      surveys: '++id, uuid, syncStatus'
    });
  }
}

export const db = new SurveyDatabase();
