  const [locationName, setLocationName] = useState('');
  const [soilMoisture, setSoilMoisture] = useState(50);
  const [vegetationCover, setVegetationCover] = useState('Medium');

  // Load surveys from Dexie local database
  const loadLocalSurveys = async () => {
    const localData = await db.surveys.orderBy('createdAt').reverse().toArray();
    setSurveys(localData);
  };

  useEffect(() => {
    loadLocalSurveys();
  }, []);

  // Sync Logic: Triggers automatically when coming back online
  useEffect(() => {
    if (isOnline) {
      syncPendingSurveys();
    }
  }, [isOnline]);

  // Mock API Call (Replace this with your actual backend fetch call)
  const uploadSurveysToBackend = async (pendingSurveys: Survey[]): Promise<string[]> => {
    return new Promise((resolve, reject) => {
      setTimeout(() => {
        // Simulate a successful API response returning the UUIDs of successfully saved surveys
        const successfulUuids = pendingSurveys.map(s => s.uuid);
        resolve(successfulUuids);

        // Uncomment to simulate a network error during sync:
        // reject(new Error("Server unreachable"));
      }, 1500);
    });
  };

  const syncPendingSurveys = async () => {
    if (syncing) return;

    // 1. Fetch only pending records
    const pendingSurveys = await db.surveys.where('syncStatus').equals('pending').toArray();
    if (pendingSurveys.length === 0) return;

    setSyncing(true);
    setSyncError(null);

    try {
      // 2. Upload payload to server
      const syncedUuids = await uploadSurveysToBackend(pendingSurveys);

      // 3. Update syncStatus to 'synced' locally for successful rows
      await db.transaction('rw', db.surveys, async () => {
        for (const uuid of syncedUuids) {
          await db.surveys.where('uuid').equals(uuid).modify({ syncStatus: 'synced' });
        }
      });

      console.log('Sync successful!');
      await loadLocalSurveys();
    } catch (err: any) {
      console.error('Sync failed:', err);
      setSyncError(err.message || 'Failed to connect to backend.');
    } finally {
      setSyncing(false);
    }
  };

  // Submit Handler
  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    // Fetch GPS coordinates (standard browser API, works offline if GPS hardware is available)
    let latitude = 0;
    let longitude = 0;
