        () => console.warn("GPS failed, saving with defaults.")
      );
    }

    const newSurvey: Survey = {
      uuid: uuidv4(),
      surveyorName,
      locationName,
      soilMoisture,
      vegetationCover,
      latitude,
      longitude,
      createdAt: Date.now(),
      syncStatus: 'pending' // Always write to local storage as pending first
    };

    // Save to Local DB (Offline First)
    await db.surveys.add(newSurvey);

    // Reset Form
    setLocationName('');
    await loadLocalSurveys();

    // Trigger sync immediately if online
    if (isOnline) {
      syncPendingSurveys();
    }
  };

  return (
    <div style={styles.container}>
      <header style={styles.header}>
        <h1>Field Survey App</h1>
        <div style={{
          ...styles.badge, 
          backgroundColor: isOnline ? '#2ecc71' : '#e74c3c'
        }}>
          {isOnline ? '● Online' : '○ Offline Mode'}
        </div>
      </header>

      {/* Sync Status Banner */}
      {syncing && <div style={{...styles.banner, backgroundColor: '#3498db'}}>Syncing data...</div>}
      {syncError && <div style={{...styles.banner, backgroundColor: '#e74c3c'}}>Sync error: {syncError}</div>}

      <div style={styles.content}>
        {/* Survey Input Form */}
        <form onSubmit={handleSubmit} style={styles.form}>
          <h2>New Survey Entry</h2>

          <label style={styles.label}>Surveyor Name</label>
          <input 
            type="text" 
            required 
            style={styles.input}
            value={surveyorName} 
            onChange={e => setSurveyorName(e.target.value)} 
          />

          <label style={styles.label}>Location / Plot Name</label>
          <input 
            type="text" 
            required 
            style={styles.input}
            value={locationName} 
            onChange={e => setLocationName(e.target.value)} 
          />

          <label style={styles.label}>Soil Moisture Content ({soilMoisture}%)</label>
          <input 
            type="range" 
            min="0" 
            max="100" 
            style={styles.input}
            value={soilMoisture} 
            onChange={e => setSoilMoisture(Number(e.target.value))} 
          />

          <label style={styles.label}>Vegetation Cover Density</label>
          <select 
            style={styles.input}
