  locationName: string;
  surveyor: string;
  notes: string;
  latitude: number;
  longitude: number;
  timestamp: number;
  synced: 0 | 1;       // 0 = Pending Sync, 1 = Synced (IndexedDB handles 0/1 better than booleans)
}

