### 2. Synchronization Service (`syncService.ts`)
This module handles communication with your remote backend API. It queries the local database for unsynced records (`synced: 0`) and attempts to upload them.

```typescript
// syncService.ts
import { db, SurveyRecord } from './db';

// Mock remote API call (replace with your actual fetch/axios call)
async function uploadSurveyToServer(survey: SurveyRecord): Promise<void> {
  return new Promise((resolve, reject) => {
    setTimeout(async () => {
      // Simulate network volatility
      if (navigator.onLine) {
        console.log(`Successfully synced survey ${survey.id} to server.`);
        resolve();
      } else {
        reject(new Error('Network disconnected during upload'));
      }
    }, 1000); // Simulate network latency
  });
}

/**
 * Scans the local database for pending surveys and attempts to sync them.
 */
export async function syncPendingSurveys(): Promise<{ successCount: number; failCount: number }> {
  let successCount = 0;
  let failCount = 0;

  // 1. Get all records where synced is 0
  const pendingSurveys = await db.surveys.where('synced').equals(0).toArray();

  if (pendingSurveys.length === 0) {
    return { successCount, failCount };
  }

  console.log(`Found ${pendingSurveys.length} pending surveys. Syncing...`);

  // 2. Iterate and attempt to upload each record
  for (const survey of pendingSurveys) {
    try {
      await uploadSurveyToServer(survey);

      // 3. Mark as synced locally upon success
      await db.surveys.update(survey.id, { synced: 1 });
      successCount++;
    } catch (error) {
      console.error(`Failed to sync survey ${survey.id}:`, error);
      failCount++;
      // Stop execution if we lost connection mid-sync
      if (!navigator.onLine) break;
    }
  }

  return { successCount, failCount };
}
