```tsx
// App.tsx
import React, { useState, useEffect } from 'react';
import { useLiveQuery } from 'dexie-react-hooks';
import { v4 as uuidv4 } from 'uuid';
import { db, SurveyRecord } from './db';
import { syncPendingSurveys } from './syncService';

export default function App() {
  // --- STATE ---
  const [isOnline, setIsOnline] = useState<boolean>(navigator.onLine);
  const [isSyncing, setIsSyncing] = useState<boolean>(false);
  const [locationName, setLocationName] = useState('');
  const [surveyor, setSurveyor] = useState('');
  const [notes, setNotes] = useState('');
  const [coords, setCoords] = useState<{ lat: number; lng: number } | null>(null);

  // --- LOCAL DB SUBSCRIPTION ---
  // Dexie's hook automatically updates UI when DB changes
  const surveys = useLiveQuery(() => db.surveys.orderBy('timestamp').reverse().toArray());

  // --- GPS COORDINATES ---
  useEffect(() => {
    if ('geolocation' in navigator) {
      navigator.geolocation.getCurrentPosition(
        (position) => {
          setCoords({
            lat: position.coords.latitude,
            lng: position.coords.longitude,
          });
        },
        (error) => console.warn("Geolocation access denied or unavailable", error)
      );
    }
  }, []);

  // --- OFFLINE/ONLINE LISTENERS ---
  useEffect(() => {
    const handleOnline = () => {
      setIsOnline(true);
      handleSync(); // Auto-sync on reconnection
    };
    const handleOffline = () => setIsOnline(false);

    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);

    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  // --- HANDLERS ---
  const handleSync = async () => {
    if (!navigator.onLine) return;
    setIsSyncing(true);
    try {
      const results = await syncPendingSurveys();
      if (results.successCount > 0) {
        alert(`Sync complete! Successfully uploaded ${results.successCount} records.`);
      }
    } catch (err) {
      console.error("Sync failed", err);
    } finally {
      setIsSyncing(false);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    const newRecord: SurveyRecord = {
      id: uuidv4(),
      locationName,
      surveyor,
      notes,
      latitude: coords?.lat || 0,
      longitude: coords?.lng || 0,
      timestamp: Date.now(),
      synced: 0, // Write locally first as "Pending"
    };

    // Always write to local IndexedDB first
    await db.surveys.add(newRecord);

    // Reset Form
    setLocationName('');
    setNotes('');

    // Attempt sync in background if online
    if (isOnline) {
      handleSync();
    }
  };

  return (
    <div style={styles.container}>
      <header style={styles.header}>
        <h1>Field Survey Tool</h1>
        <div style={{
          ...styles.statusBadge,
          backgroundColor: isOnline ? '#2ecc71' : '#e74c3c'
        }}>
          {isOnline ? '● Online' : '○ Offline - Saving locally'}
        </div>
      </header>

      {/* Survey Submission Form */}
      <form onSubmit={handleSubmit} style={styles.form}>
        <h2>New Survey Record</h2>
        <div style={styles.inputGroup}>
          <label>Surveyor Name</label>
          <input 
            type="text" 
            value={surveyor} 
            onChange={(e) => setSurveyor(e.target.value)} 
            required 
            placeholder="John Doe"
          />
        </div>

        <div style={styles.inputGroup}>
          <label>Location Name</label>
          <input 
            type="text" 
            value={locationName} 
            onChange={(e) => setLocationName(e.target.value)} 
            required 
            placeholder="Plot 42-B"
          />
        </div>

        <div style={styles.inputGroup}>
          <label>Notes</label>
          <textarea 
            value={notes} 
            onChange={(e) => setNotes(e.target.value)} 
            placeholder="Soil conditions, equipment used..."
          />
        </div>

        <div style={styles.gpsContainer}>
          <strong>GPS Coordinates:</strong>{' '}
          {coords ? `${coords.lat.toFixed(5)}, ${coords.lng.toFixed(5)}` : 'Acquiring GPS...'}
        </div>

        <button type="submit" style={styles.submitBtn}>
          Save Survey (Offline-Ready)
        </button>
      </form>

      {/* Sync Control */}
      <div style={styles.syncContainer}>
        <button 
          onClick={handleSync} 
          disabled={!isOnline || isSyncing} 
          style={styles.syncBtn}
        >
          {isSyncing ? 'Syncing...' : 'Force Sync Now'}
        </button>
      </div>

      {/* Survey History List */}
      <section style={styles.listSection}>
        <h2>Local Survey History ({surveys?.length || 0})</h2>
        {surveys?.map((survey) => (
          <div key={survey.id} style={styles.surveyCard}>
            <div style={styles.cardHeader}>
              <h3>{survey.locationName}</h3>
              <span style={{
                ...styles.syncStatus,
                color: survey.synced === 1 ? '#2ecc71' : '#e67e22'
              }}>
                {survey.synced === 1 ? '✓ Synced to Cloud' : '⏳ Pending Sync'}
              </span>
            </div>
            <p><strong>Surveyor:</strong> {survey.surveyor}</p>
            <p><strong>Notes:</strong> {survey.notes || 'No notes'}</p>
            <p style={styles.timestamp}>
              {new Date(survey.timestamp).toLocaleString()} | Coords: {survey.latitude.toFixed(4)}, {survey.longitude.toFixed(4)}
            </p>
          </div>
        ))}
      </section>
    </div>
  );
}

