### 2. The Data Model (`survey_model.dart`)
We use a UUID generated on the device as the primary key. This prevents ID collisions when multiple offline devices sync to the same backend.

```dart
import 'dart:convert';
import 'package:uuid/uuid.dart';

class Survey {
  final String id;
  final String title;
  final double latitude;
  final double longitude;
  final String notes;
  final DateTime createdAt;
  bool isSynced;

  Survey({
    String? id,
    required this.title,
    required this.latitude,
    required this.longitude,
    required this.notes,
    DateTime? createdAt,
    this.isSynced = false,
  })  : id = id ?? const Uuid().v4(),
        createdAt = createdAt ?? DateTime.now();

  // Convert to Map for SQLite
  Map<String, dynamic> toMap() {
    return {
      'id': id,
      'title': title,
      'latitude': latitude,
      'longitude': longitude,
      'notes': notes,
      'created_at': createdAt.toIso8601String(),
      'is_synced': isSynced ? 1 : 0,
    };
  }

  // Create from SQLite Map
  factory Survey.fromMap(Map<String, dynamic> map) {
    return Survey(
      id: map['id'],
      title: map['title'],
      latitude: map['latitude'],
      longitude: map['longitude'],
      notes: map['notes'],
      createdAt: DateTime.parse(map['created_at']),
      isSynced: map['is_synced'] == 1,
    );
  }

  // Convert to JSON for Server Upload
  String toJson() => json.encode({
    'id': id,
    'title': title,
    'gps_coordinates': {
      'latitude': latitude,
      'longitude': longitude,
    },
    'notes': notes,
    'timestamp': createdAt.toUtc().toIso8601String(),
  });
}
```

