### 3. Local Database Helper (`database_helper.dart`)
This service handles initializing SQLite, saving data locally, updating sync flags, and retrieving unsynced records.

```dart
import 'package:path/path.dart';
import 'package:sqflite/sqflite.dart';
import 'survey_model.dart';

class DatabaseHelper {
  static final DatabaseHelper instance = DatabaseHelper._init();
  static Database? _database;

  DatabaseHelper._init();

  Future<Database> get database async {
    if (_database != null) return _database!;
    _database = await _initDB('surveys.db');
    return _database!;
  }

  Future<Database> _initDB(String filePath) async {
    final dbPath = await getDatabasesPath();
    final path = join(dbPath, filePath);

    return await openDatabase(
      path,
      version: 1,
      onCreate: _createDB,
    );
  }

  Future _createDB(Database db, int version) async {
    await db.execute('''
      CREATE TABLE surveys (
        id TEXT PRIMARY KEY,
        title TEXT NOT NULL,
        latitude REAL NOT NULL,
        longitude REAL NOT NULL,
        notes TEXT,
        created_at TEXT NOT NULL,
        is_synced INTEGER NOT NULL
      )
    ''');
  }

  // Save survey (local-first)
  Future<void> insertSurvey(Survey survey) async {
    final db = await instance.database;
    await db.insert(
      'surveys',
      survey.toMap(),
      conflictAlgorithm: ConflictAlgorithm.replace,
    );
  }

  // Get all surveys to display in UI
  Future<List<Survey>> getAllSurveys() async {
    final db = await instance.database;
    final result = await db.query('surveys', orderBy: 'created_at DESC');
    return result.map((json) => Survey.fromMap(json)).toList();
  }

  // Fetch only unsynced records for the sync engine
  Future<List<Survey>> getUnsyncedSurveys() async {
    final db = await instance.database;
    final result = await db.query('surveys', where: 'is_synced = ?', whereArgs: [0]);
    return result.map((json) => Survey.fromMap(json)).toList();
  }

  // Mark record as synced
  Future<void> markAsSynced(String id) async {
    final db = await instance.database;
    await db.update(
      'surveys',
      {'is_synced': 1},
      where: 'id = ?',
      whereArgs: [id],
    );
  }
}
```

