### 4. Background Sync Engine (`sync_service.dart`)
This service monitors internet connectivity. When the connection changes to "online," it grabs all unsynced surveys from SQLite and uploads them to the server API.

```dart
import 'dart:async';
import 'dart:io';
import 'package:connectivity_plus/connectivity_plus.dart';
import 'package:http/http.dart' as http;
import 'database_helper.dart';
import 'survey_model.dart';

class SyncService {
  final DatabaseHelper _dbHelper = DatabaseHelper.instance;
  final Connectivity _connectivity = Connectivity();
  StreamSubscription<ConnectivityResult>? _connectivitySubscription;

  // Callback to update UI when sync status changes
  final Function()? onSyncComplete;

  SyncService({this.onSyncComplete});

  // Initialize network listeners
  void initialize() {
    _connectivitySubscription = _connectivity.onConnectivityChanged.listen((ConnectivityResult result) {
      if (result != ConnectivityResult.none) {
        print("Network connection restored. Starting synchronization...");
        syncUnsyncedData();
      }
    });
  }

  void dispose() {
    _connectivitySubscription?.cancel();
  }

  // Core Sync Logic
  Future<void> syncUnsyncedData() async {
    if (!await _hasInternetAccess()) {
      print("Connected to interface, but no internet routing.");
      return;
    }

    List<Survey> unsynced = await _dbHelper.getUnsyncedSurveys();
    if (unsynced.isEmpty) {
      print("No surveys to sync.");
      return;
    }

    print("Found ${unsynced.length} unsynced surveys. Uploading...");

    for (var survey in unsynced) {
      try {
        // Replace with your actual REST API endpoint
        final response = await http.post(
          Uri.parse('https://api.example.com/surveys'),
          headers: {'Content-Type': 'application/json'},
          body: survey.toJson(),
        ).timeout(const Duration(seconds: 10));

        if (response.statusCode == 200 || response.statusCode == 201) {
          await _dbHelper.markAsSynced(survey.id);
          print("Successfully synced survey: ${survey.id}");
        } else {
          print("Server rejected survey ${survey.id}: ${response.statusCode}");
        }
      } catch (e) {
        print("Failed to sync survey ${survey.id} due to network error: $e");
        // Stop batch execution if server is down to prevent hammering
        break; 
      }
    }

    if (onSyncComplete != null) {
      onSyncComplete!();
    }
  }

  // Verifies that data can actually route to the internet
  Future<bool> _hasInternetAccess() async {
    try {
      final result = await InternetAddress.lookup('google.com');
      return result.isNotEmpty && result[0].rawAddress.isNotEmpty;
    } on SocketException catch (_) {
      return false;
    }
  }
}
```

