### Step 1: Database Setup (`database.ts`)
This module manages the local SQLite database. It creates the table, handles saving new surveys locally (marked as `pending`), and updates their status once synced.

```typescript
// database.ts
import * as SQLite from 'expo-sqlite';

// Open or create the database
const db = SQLite.openDatabaseSync('field_survey.db');

export interface Survey {
  id: string;
  title: string;
  latitude: number;
  longitude: number;
  notes: string;
  status: 'pending' | 'synced';
  createdAt: string;
}

// Initialize the Database Schema
export const initDatabase = async (): Promise<void> => {
  await db.execAsync(`
    CREATE TABLE IF NOT EXISTS surveys (
      id TEXT PRIMARY KEY NOT NULL,
      title TEXT NOT NULL,
      latitude REAL NOT NULL,
      longitude REAL NOT NULL,
      notes TEXT,
      status TEXT NOT NULL CHECK (status IN ('pending', 'synced')),
      createdAt TEXT NOT NULL
    );
  `);
};

// Insert a new survey (defaults to 'pending')
export const insertSurvey = async (survey: Omit<Survey, 'status' | 'createdAt'>): Promise<void> => {
  const createdAt = new Date().toISOString();
  await db.runAsync(
    `INSERT INTO surveys (id, title, latitude, longitude, notes, status, createdAt) 
     VALUES (?, ?, ?, ?, ?, 'pending', ?);`,
    [survey.id, survey.title, survey.latitude, survey.longitude, survey.notes, createdAt]
  );
};

// Get all local surveys
export const getAllSurveys = async (): Promise<Survey[]> => {
  const rows = await db.getAllAsync<Survey>('SELECT * FROM surveys ORDER BY createdAt DESC;');
  return rows;
};

// Get only surveys waiting to be synced
export const getPendingSurveys = async (): Promise<Survey[]> => {
  return await db.getAllAsync<Survey>("SELECT * FROM surveys WHERE status = 'pending';");
};

// Mark surveys as synced after successful upload
export const markAsSynced = async (id: string): Promise<void> => {
  await db.runAsync("UPDATE surveys SET status = 'synced' WHERE id = ?;", [id]);
};
```

