### Step 2: Sync Engine (`syncEngine.ts`)
This engine handles uploading pending local data to your backend API. If the upload succeeds, it updates the local record status to `synced`.

```typescript
// syncEngine.ts
import { getPendingSurveys, markAsSynced, Survey } from './database';

const REMOTE_API_URL = 'https://api.yourdomain.com/surveys';

/**
 * Simulates uploading data to your remote server.
 * Replace this with your actual fetch/axios API call.
 */
const uploadSurveyToRemote = async (survey: Survey): Promise<boolean> => {
  try {
    const response = await fetch(REMOTE_API_URL, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        id: survey.id,
        title: survey.title,
        location: { lat: survey.latitude, lng: survey.longitude },
        notes: survey.notes,
        timestamp: survey.createdAt,
      }),
    });

    return response.ok;
  } catch (error) {
    console.warn(`Sync failed for survey ${survey.id}: Connection error.`);
    return false;
  }
};

/**
 * Iterates through all pending local surveys and attempts to sync them.
 */
export const syncPendingData = async (): Promise<{ successCount: number; failedCount: number }> => {
  const pendingSurveys = await getPendingSurveys();
  let successCount = 0;
  let failedCount = 0;

  if (pendingSurveys.length === 0) {
    return { successCount: 0, failedCount: 0 };
  }

  console.log(`Attempting to sync ${pendingSurveys.length} pending survey(s)...`);

  for (const survey of pendingSurveys) {
    const success = await uploadSurveyToRemote(survey);
    if (success) {
      await markAsSynced(survey.id);
      successCount++;
    } else {
      failedCount++;
    }
  }

  return { successCount, failedCount };
};
```

