### Step 3: UI and Network Listener (`App.tsx`)
This is the main screen of the application. It uses `@react-native-community/netinfo` to listen for network state changes. When the device transitions from offline to online, it automatically triggers the `syncPendingData()` function.

```tsx
// App.tsx
import React, { useEffect, useState } from 'react';
import { StyleSheet, Text, View, TextInput, Button, FlatList, SafeAreaView, Alert } from 'react-native';
import NetInfo from '@react-native-community/netinfo';
import * as Crypto from 'expo-crypto'; // For generating unique IDs
import { initDatabase, insertSurvey, getAllSurveys, Survey } from './database';
import { syncPendingData } from './syncEngine';

export default function App() {
  const [isOnline, setIsOnline] = useState<boolean | null>(null);
  const [surveys, setSurveys] = useState<Survey[]>([]);
  const [title, setTitle] = useState('');
  const [notes, setNotes] = useState('');
  const [syncing, setSyncing] = useState(false);

  // 1. Initialize DB and set up Network Connection Listener
  useEffect(() => {
    const setup = async () => {
      await initDatabase();
      loadLocalSurveys();
    };
    setup();

    // Subscribe to network state updates
    const unsubscribe = NetInfo.addEventListener((state) => {
      const online = !!state.isConnected && !!state.isInternetReachable;
      setIsOnline(online);

      // Auto-trigger sync when transitioning to Online
      if (online) {
        handleSync();
      }
    });

    return () => unsubscribe();
  }, []);

  // 2. Load surveys from SQLite to local UI state
  const loadLocalSurveys = async () => {
    const data = await getAllSurveys();
    setSurveys(data);
  };

  // 3. Handle Sync process
  const handleSync = async () => {
    if (syncing) return;
    setSyncing(true);
    const result = await syncPendingData();
    setSyncing(false);

    if (result.successCount > 0) {
      Alert.alert('Sync Complete', `Successfully synced ${result.successCount} survey(s) to the cloud!`);
      loadLocalSurveys(); // Refresh UI to show updated statuses
    }
  };

  // 4. Save a survey locally (simulating GPS coordinates)
  const handleSubmit = async () => {
    if (!title) return Alert.alert('Error', 'Please enter a title');

    const mockLat = 45.4215 + (Math.random() - 0.5) * 0.1;
    const mockLng = -75.6972 + (Math.random() - 0.5) * 0.1;

    const newSurvey = {
      id: Crypto.randomUUID(),
      title,
      latitude: mockLat,
      longitude: mockLng,
      notes,
    };

    try {
      await insertSurvey(newSurvey);
      setTitle('');
      setNotes('');
      loadLocalSurveys();

      // If online, immediately try to sync. If offline, it stays 'pending'.
      if (isOnline) {
        handleSync();
      } else {
        Alert.alert('Offline Mode', 'Survey saved locally. It will sync automatically when you reconnect.');
      }
    } catch (error) {
      console.error(error);
      Alert.alert('Error', 'Could not save survey locally.');
    }
  };

  return (
    <SafeAreaView style={styles.container}>
      {/* Connection Banner */}
      <View style={[styles.banner, { backgroundColor: isOnline ? '#4CAF50' : '#F44336' }]}>
        <Text style={styles.bannerText}>
          {isOnline ? '🟢 Connected (Cloud Sync Active)' : '🔴 Offline Mode (Saving Locally)'}
        </Text>
      </View>

      <Text style={styles.header}>Field Surveying App</Text>

      {/* Form Section */}
      <View style={styles.form}>
        <TextInput 
          style={styles.input} 
          placeholder="Survey Target Title" 
          value={title} 
          onChangeText={setTitle} 
        />
        <TextInput 
          style={[styles.input, { height: 60 }]} 
          placeholder="Notes/Observations" 
          multiline 
          value={notes} 
          onChangeText={setNotes} 
        />
        <Button title="Save Survey" onPress={handleSubmit} />
      </View>

      {/* Local Sync Monitor Panel */}
      <View style={styles.syncRow}>
        <Text style={styles.sectionTitle}>Local Surveys Cache</Text>
        {isOnline && (
          <Button title={syncing ? "Syncing..." : "Sync Now"} onPress={handleSync} disabled={syncing} />
        )}
      </View>

      {/* Survey List */}
      <FlatList
        data={surveys}
        keyExtractor={(item) => item.id}
        renderItem={({ item }) => (
          <View style={styles.surveyItem}>
            <View>
              <Text style={styles.surveyTitle}>{item.title}</Text>
              <Text style={styles.surveyCoords}>{item.latitude.toFixed(4)}, {item.longitude.toFixed(4)}</Text>
              <Text style={styles.surveyNotes}>{item.notes}</Text>
            </View>
            <View style={[styles.statusIndicator, { backgroundColor: item.status === 'synced' ? '#E8F5E9' : '#FFF3E0' }]}>
