import React, { useState, useEffect, useCallback } from 'react';
import { 
  StyleSheet, 
  Text, 
  View, 
  TextInput, 
  TouchableOpacity, 
  FlatList, 
  SafeAreaView, 
  ActivityIndicator, 
  Alert 
} from 'react-native';
import * as SQLite from 'expo-sqlite';
import NetInfo from '@react-native-community/netinfo';
import 'react-native-get-random-values';
import { v4 as uuidv4 } from 'uuid';

// --- TYPES ---
interface Survey {
  id: string;
  location_name: string;
  notes: string;
  status: 'pending' | 'synced';
  created_at: string;
}

// Simulated Backend API URL
const BACKEND_API_URL = 'https://api.example.com/surveys/sync';

// Initialize SQLite database
const db = SQLite.openDatabaseSync('field_surveys.db');

export default function App() {
  // --- STATE ---
  const [isOnline, setIsOnline] = useState<boolean | null>(null);
  const [locationName, setLocationName] = useState('');
  const [notes, setNotes] = useState('');
  const [surveys, setSurveys] = useState<Survey[]>([]);
  const [isSyncing, setIsSyncing] = useState(false);

  // --- DATABASE INITIALIZATION ---
  useEffect(() => {
    db.execSync(`
      CREATE TABLE IF NOT EXISTS surveys (
        id TEXT PRIMARY KEY NOT NULL,
        location_name TEXT NOT NULL,
        notes TEXT,
        status TEXT NOT NULL,
        created_at TEXT NOT NULL
      );
    `);
    refreshSurveyList();
  }, []);

  // Fetch local surveys to display in the UI
  const refreshSurveyList = useCallback(() => {
    try {
      const result = db.getAllSync<Survey>('SELECT * FROM surveys ORDER BY created_at DESC');
      setSurveys(result);
    } catch (error) {
      console.error('Error fetching surveys from DB', error);
    }
  }, []);

  // --- SYNC ENGINE ---
  const syncPendingSurveys = useCallback(async () => {
    if (isSyncing) return;
    setIsSyncing(true);

    try {
      // 1. Fetch all pending records from SQLite
      const pendingSurveys = db.getAllSync<Survey>(
        "SELECT * FROM surveys WHERE status = 'pending'"
      );

      if (pendingSurveys.length === 0) {
        setIsSyncing(false);
        return;
      }

      console.log(`Attempting to sync ${pendingSurveys.length} pending surveys...`);

      // 2. Push to Remote Server (Batch Sync)
      // Note: In a production app, wrap this in a try-catch for individual item failures
      const response = await fetch(BACKEND_API_URL, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ surveys: pendingSurveys }),
      });

      if (response.ok) {
        // 3. Update local DB status to 'synced' upon success
        db.withTransactionSync(() => {
          for (const survey of pendingSurveys) {
            db.runSync(
              "UPDATE surveys SET status = 'synced' WHERE id = ?", 
              [survey.id]
            );
          }
        });

        console.log('Sync successful!');
        refreshSurveyList();
      } else {
        console.warn('Server rejected sync', response.statusText);
      }
    } catch (error) {
      // Fail silently in the background if network fails mid-sync
      console.warn('Sync failed (likely server offline/timeout):', error);
    } finally {
      setIsSyncing(false);
    }
  }, [isSyncing, refreshSurveyList]);

  // --- NETWORK LISTENER ---
  useEffect(() => {
    const unsubscribe = NetInfo.addEventListener((state) => {
      const online = !!state.isConnected && !!state.isInternetReachable;
      setIsOnline(online);

      // If we just reconnected, trigger sync
      if (online) {
        syncPendingSurveys();
      }
    });

    return () => unsubscribe();
  }, [syncPendingSurveys]);

  // --- CREATE SURVEY (LOCAL WRITE FIRST) ---
  const handleSaveSurvey = () => {
    if (!locationName.trim()) {
      Alert.alert('Validation Error', 'Location name is required');
      return;
    }

    const newSurvey: Survey = {
      id: uuidv4(), // Generate client-side UUID
      location_name: locationName,
      notes: notes,
      status: 'pending',
      created_at: new Date().toISOString()
    };

    try {
      // Insert locally first
      db.runSync(
        `INSERT INTO surveys (id, location_name, notes, status, created_at) 
         VALUES (?, ?, ?, ?, ?);`,
        [newSurvey.id, newSurvey.location_name, newSurvey.notes, newSurvey.status, newSurvey.created_at]
      );

      // Clear Form UI
      setLocationName('');
      setNotes('');
      refreshSurveyList();

      // If we are online, trigger immediate sync in background
      if (isOnline) {
        syncPendingSurveys();
      } else {
        Alert.alert('Saved Offline', 'Survey saved locally. It will sync automatically when you reconnect.');
      }
    } catch (error) {
      console.error('Failed to save survey locally', error);
      Alert.alert('Error', 'Could not save survey data.');
    }
  };

  // --- UI RENDER HELPERS ---
  const renderSurveyItem = ({ item }: { item: Survey }) => (
    <View style={styles.card}>
      <View style={styles.cardHeader}>
        <Text style={styles.cardTitle}>{item.location_name}</Text>
        <View style={[
          styles.badge, 
          item.status === 'synced' ? styles.badgeSynced : styles.badgePending
        ]}>
          <Text style={styles.badgeText}>
            {item.status.toUpperCase()}
          </Text>
        </View>
      </View>
      {item.notes ? <Text style={styles.cardNotes}>{item.notes}</Text> : null}
      <Text style={styles.cardDate}>{new Date(item.created_at).toLocaleTimeString()}</Text>
    </View>
  );

  return (
    <SafeAreaView style={styles.container}>
      {/* Network Status Banner */}
      <View style={[styles.banner, isOnline ? styles.bannerOnline : styles.bannerOffline]}>
        <Text style={styles.bannerText}>
          {isOnline ? '🟢 Connected to Internet' : '🔴 Offline Mode - Data Saved Locally'}
        </Text>
        {isSyncing && <ActivityIndicator size="small" color="#fff" style={{ marginLeft: 8 }} />}
      </View>

      <View style={styles.content}>
        <Text style={styles.title}>Field Survey Form</Text>

        {/* Form */}
        <View style={styles.form}>
          <TextInput
            style={styles.input}
            placeholder="Location / Site Name"
            value={locationName}
            onChangeText={setLocationName}
          />
          <TextInput
            style={[styles.input, styles.textArea]}
            placeholder="Observation Notes"
            multiline
            numberOfLines={4}
            value={notes}
            onChangeText={setNotes}
          />
          <TouchableOpacity style={styles.button} onPress={handleSaveSurvey}>
            <Text style={styles.buttonText}>Submit Survey</Text>
          </TouchableOpacity>
        </View>

        {/* Survey History List */}
        <Text style={styles.subtitle}>Survey Records ({surveys.length})</Text>
        <FlatList
          data={surveys}
          keyExtractor={(item) => item.id}
          renderItem={renderSurveyItem}
          contentContainerStyle={{ paddingBottom: 20 }}
          ListEmptyComponent={
            <Text style={styles.emptyText}>No surveys captured yet.</Text>
          }
        />
      </View>
    </SafeAreaView>
  );
}

