#### 2. Local Storage & Sync Service (`SyncService.ts`)
*For production, you would replace `AsyncStorage` with **SQLite** or **WatermelonDB** for performance. This mock uses AsyncStorage for cross-platform readability.*

```typescript
import AsyncStorage from '@react-native-async-storage/async-storage';
import NetInfo from '@react-native-community/netinfo';
import 'react-native-get-random-values';
import { v4 as uuidv4 } from 'uuid';
import { Survey } from './types';

const SURVEYS_KEY = '@surveys_store';
const API_ENDPOINT = 'https://api.yourdomain.com/surveys';

export class SyncService {

  // 1. Get all local surveys
  static async getLocalSurveys(): Promise<Survey[]> {
    const data = await AsyncStorage.getItem(SURVEYS_KEY);
    return data ? JSON.parse(data) : [];
  }

  // 2. Save a new survey (Always writes locally first)
  static async saveSurvey(latitude: number, longitude: number, notes: string): Promise<Survey> {
    const newSurvey: Survey = {
      id: uuidv4(),
      latitude,
      longitude,
      notes,
      createdAt: new Date().toISOString(),
      synced: false, // Initial state is always unsynced
    };

    const surveys = await this.getLocalSurveys();
    surveys.push(newSurvey);
    await AsyncStorage.setItem(SURVEYS_KEY, JSON.stringify(surveys));

    // Trigger sync attempt immediately (it will fail silently if offline)
    this.syncWithServer(); 

    return newSurvey;
  }

  // 3. Sync Engine: Sends unsynced surveys to the server
  static async syncWithServer(): Promise<void> {
    const state = await NetInfo.fetch();
    if (!state.isConnected) {
      console.log('Offline: Skipping sync.');
      return;
    }

    const surveys = await this.getLocalSurveys();
    const unsyncedSurveys = surveys.filter(s => !s.synced);

    if (unsyncedSurveys.length === 0) {
      console.log('All surveys already synchronized.');
      return;
    }

    console.log(`Attempting to sync ${unsyncedSurveys.length} surveys...`);

    try {
      // POST the payload to server
      const response = await fetch(API_ENDPOINT, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ surveys: unsyncedSurveys }),
      });

      if (response.ok) {
        // Mark sent items as synced locally
        const updatedSurveys = surveys.map(survey => {
          if (unsyncedSurveys.some(unsynced => unsynced.id === survey.id)) {
            return { ...survey, synced: true };
          }
          return survey;
        });

        await AsyncStorage.setItem(SURVEYS_KEY, JSON.stringify(updatedSurveys));
        console.log('Sync successful!');
      } else {
        console.warn('Server rejected sync payload:', response.statusText);
      }
    } catch (error) {
      console.error('Network sync failed:', error);
    }
  }
}
```

