```dart
import 'dart:async';
import 'dart:convert';
import 'dart:math';
import 'package:flutter/material.dart';
import 'package:sqflite/sqflite.dart';
import 'package:path/path.dart' as p;
import 'package:connectivity_plus/connectivity_plus.dart';
import 'package:uuid/uuid.dart';
import 'package:http/http.dart' as http;

void main() async {
  WidgetsFlutterBinding.ensureInitialized();
  final dbHelper = DatabaseHelper.instance;
  await dbHelper.database; // Initialize database

  runApp(SurveyApp(dbHelper: dbHelper));
}

// ==========================================
// 1. DATA MODEL
// ==========================================
class Survey {
  final String id; // UUID generated offline
  final String title;
  final String notes;
  final double latitude;
  final double longitude;
  final bool isSynced;
  final DateTime createdAt;

  Survey({
    required this.id,
    required this.title,
    required this.notes,
    required this.latitude,
    required this.longitude,
    this.isSynced = false,
    required this.createdAt,
  });

  Map<String, dynamic> toMap() {
    return {
      'id': id,
      'title': title,
      'notes': notes,
      'latitude': latitude,
      'longitude': longitude,
      'is_synced': isSynced ? 1 : 0,
      'created_at': createdAt.toIso8601String(),
    };
  }

  factory Survey.fromMap(Map<String, dynamic> map) {
    return Survey(
      id: map['id'],
      title: map['title'],
      notes: map['notes'],
      latitude: map['latitude'],
      longitude: map['longitude'],
      isSynced: map['is_synced'] == 1,
      createdAt: DateTime.parse(map['created_at']),
    );
  }
}

// ==========================================
// 2. LOCAL DATABASE HELPER (SQLite)
// ==========================================
class DatabaseHelper {
  static final DatabaseHelper instance = DatabaseHelper._init();
  static Database? _database;

  DatabaseHelper._init();

  Future<Database> get database async {
    if (_database != null) return _database!;
    _database = await _initDB('surveys.db');
    return _database!;
  }

  Future<Database> _initDB(String filePath) async {
    final dbPath = await getDatabasesPath();
    final path = p.join(dbPath, filePath);

    return await openDatabase(
      path,
      version: 1,
      onCreate: _createDB,
    );
  }

  Future _createDB(Database db, int version) async {
    await db.execute('''
      CREATE TABLE surveys (
        id TEXT PRIMARY KEY,
        title TEXT NOT NULL,
        notes TEXT,
        latitude REAL NOT NULL,
        longitude REAL NOT NULL,
        is_synced INTEGER NOT NULL,
        created_at TEXT NOT NULL
      )
    ''');
  }

  Future<void> insertSurvey(Survey survey) async {
    final db = await instance.database;
    await db.insert('surveys', survey.toMap(), conflictAlgorithm: ConflictAlgorithm.replace);
  }

  Future<List<Survey>> getAllSurveys() async {
    final db = await instance.database;
    final result = await db.query('surveys', orderBy: 'created_at DESC');
    return result.map((json) => Survey.fromMap(json)).toList();
  }

  Future<List<Survey>> getUnsyncedSurveys() async {
    final db = await instance.database;
    final result = await db.query('surveys', where: 'is_synced = ?', whereArgs: [0]);
    return result.map((json) => Survey.fromMap(json)).toList();
  }

  Future<void> markAsSynced(String id) async {
    final db = await instance.database;
    await db.update(
      'surveys',
      {'is_synced': 1},
      where: 'id = ?',
      whereArgs: [id],
    );
  }
}

// ==========================================
// 3. OFFLINE-FIRST SYNC ENGINE
// ==========================================
class SyncService {
  final DatabaseHelper _dbHelper = DatabaseHelper.instance;
  final _connectivity = Connectivity();
  final _syncStatusController = StreamController<SyncState>.broadcast();
  bool _isSyncing = false;

  Stream<SyncState> get syncStatusStream => _syncStatusController.stream;

  // Mock API Endpoint representing your remote GIS/Survey Server
  final String _mockApiUrl = 'https://jsonplaceholder.typicode.com/posts'; 

  void initialize(VoidCallback onSyncComplete) {
    // Listen to network status changes
    _connectivity.onConnectivityChanged.listen((List<ConnectivityResult> results) {
      if (results.any((result) => result != ConnectivityResult.none)) {
        print("Network restored. Triggering sync...");
        syncData().then((_) => onSyncComplete());
      }
    });
  }

  Future<void> syncData() async {
    if (_isSyncing) return;
    _isSyncing = true;
    _syncStatusController.add(SyncState.syncing);

    try {
      List<Survey> unsynced = await _dbHelper.getUnsyncedSurveys();
      if (unsynced.isEmpty) {
        _syncStatusController.add(SyncState.idle);
        _isSyncing = false;
        return;
      }

      print("Found ${unsynced.length} unsynced surveys. Uploading...");

      for (var survey in unsynced) {
        // Send to remote server
        final response = await http.post(
          Uri.parse(_mockApiUrl),
          headers: {'Content-Type': 'application/json'},
          body: jsonEncode({
            'deviceId_uuid': survey.id,
            'title': survey.title,
            'body': '${survey.notes} (Lat: ${survey.latitude}, Lon: ${survey.longitude})',
          }),
        ).timeout(const Duration(seconds: 10));

        if (response.statusCode == 201 || response.statusCode == 200) {
          // Success! Mark locally as synced
          await _dbHelper.markAsSynced(survey.id);
          print("Successfully synced survey: ${survey.id}");
        } else {
          throw Exception("Server rejected payload");
        }
      }
      _syncStatusController.add(SyncState.success);
    } catch (e) {
      print("Sync failed: $e");
      _syncStatusController.add(SyncState.error);
    } finally {
      _isSyncing = false;
      Future.delayed(const Duration(seconds: 3), () {
        _syncStatusController.add(SyncState.idle);
      });
    }
  }
}

enum SyncState { idle, syncing, success, error }

// ==========================================
// 4. USER INTERFACE
// ==========================================
class SurveyApp extends StatelessWidget {
  final DatabaseHelper dbHelper;
  const SurveyApp({super.key, required this.dbHelper});

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      title: 'Field Surveyor (Offline-First)',
      theme: ThemeData(
        useMaterial3: true,
        colorScheme: ColorScheme.fromSeed(seedColor: Colors.teal),
      ),
      home: SurveyListScreen(dbHelper: dbHelper),
    );
  }
}

class SurveyListScreen extends StatefulWidget {
  final DatabaseHelper dbHelper;
  const SurveyListScreen({super.key, required this.dbHelper});

  @override
  State<SurveyListScreen> createState() => _SurveyListScreenState();
}

class _SurveyListScreenState extends State<SurveyListScreen> {
  final SyncService _syncService = SyncService();
  List<Survey> _surveys = [];
  SyncState _syncState = SyncState.idle;

  @override
  void initState() {
    super.initState();
    _refreshList();
    _syncService.initialize(() {
      _refreshList();
    });
    _syncService.syncStatusStream.listen((state) {
      if (mounted) {
        setState(() {
          _syncState = state;
        });
      }
    });
  }

  Future<void> _refreshList() async {
    final data = await widget.dbHelper.getAllSurveys();
    setState(() {
      _surveys = data;
    });
  }

  void _showAddSurveyDialog() {
    final titleController = TextEditingController();
    final notesController = TextEditingController();

    showDialog(
      context: context,
      builder: (context) => AlertDialog(
        title: const Text('New Field Survey'),
        content: Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            TextField(
              controller: titleController,
              decoration: const InputDecoration(labelText: 'Feature / Asset Name'),
            ),
            TextField(
              controller: notesController,
              decoration: const InputDecoration(labelText: 'Observation Notes'),
              maxLines: 3,
            ),
          ],
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(context),
            child: const Text('Cancel'),
          ),
          ElevatedButton(
            onPressed: () async {
              if (titleController.text.isEmpty) return;

              // Generate coordinate metadata (Mocking GPS capture)
              final random = Random();
              double lat = 37.7749 + (random.nextDouble() - 0.5) / 100;
              double lon = -122.4194 + (random.nextDouble() - 0.5) / 100;

              final newSurvey = Survey(
                id: const Uuid().v4(), // Generate UUID
                title: titleController.text,
                notes: notesController.text,
                latitude: lat,
                longitude: lon,
                createdAt: DateTime.now(),
              );

              // 1. Write locally first
              await widget.dbHelper.insertSurvey(newSurvey);
              Navigator.pop(context);
              _refreshList();

              // 2. Attempt sync immediately (will fail silently if offline)
              _syncService.syncData().then((_) => _refreshList());
            },
            child: const Text('Save Survey (Local)'),
          ),
        ],
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: const Text('Field Surveyor'),
        backgroundColor: Theme.of(context).colorScheme.inversePrimary,
        actions: [
          _buildSyncIcon(),
          IconButton(
            icon: const Icon(Icons.sync),
            tooltip: 'Force Sync Now',
            onPressed: () => _syncService.syncData().then((_) => _refreshList()),
          )
        ],
      ),
      body: _surveys.isEmpty
          ? const Center(child: Text('No surveys logged yet. Tap + to begin.'))
          : ListView.builder(
              itemCount: _surveys.length,
              itemBuilder: (context, index) {
                final survey = _surveys[index];
                return Card(
                  margin: const EdgeInsets.symmetric(horizontal: 10, vertical: 5),
                  child: ListTile(
                    leading: Icon(
                      survey.isSynced ? Icons.cloud_done : Icons.cloud_off,
                      color: survey.isSynced ? Colors.green : Colors.orange,
                      size: 32,
                    ),
                    title: Text(survey.title, style: const TextStyle(fontWeight: FontWeight.bold)),
                    subtitle: Text(
                      '${survey.notes}\nGPS: ${survey.latitude.toStringAsFixed(5)}, ${survey.longitude.toStringAsFixed(5)}',
                    ),
                    trailing: Text(
                      '${survey.createdAt.hour}:${survey.createdAt.minute.toString().padLeft(2, '0')}',
                    ),
                    isThreeLine: true,
                  ),
                );
              },
            ),
      floatingActionButton: FloatingActionButton.extended(
        onPressed: _showAddSurveyDialog,
        icon: const Icon(Icons.add_location_alt),
        label: const Text('Log Asset'),
      ),
    );
  }

  Widget _buildSyncIcon() {
    switch (_syncState) {
      case SyncState.syncing:
        return const Padding(
          padding: EdgeInsets.symmetric(horizontal: 16),
          child: SizedBox(width: 20, height: 20, child: CircularProgressIndicator(strokeWidth: 2)),
        );
      case SyncState.success:
        return const Icon(Icons.check_circle, color: Colors.green);
      case SyncState.error:
        return const Icon(Icons.error, color: Colors.red);
      case SyncState.idle:
      default:
        return const SizedBox.shrink();
    }
  }
}
