                    </div>
                </section>

                <!-- Synced Data (Simulated Server Database) -->
                <section class="bg-white p-6 rounded-lg shadow-md border-l-4 border-green-500">
                    <h2 class="text-md font-semibold text-gray-700 mb-2 flex justify-between items-center">
                        <span>Server Database (Synced)</span>
                        <span id="synced-count" class="bg-green-100 text-green-800 text-xs px-2 py-1 rounded-full font-bold">0</span>
                    </h2>
                    <p class="text-xs text-gray-500 mb-4">Confirmed successfully uploaded records.</p>
