    <!-- Application Logic -->
    <script>
        // --- OFFLINE-FIRST DB CONTROLLER (Using LocalStorage as our SQLite/Hive equivalent) ---
        const DB = {
            getQueue: () => JSON.parse(localStorage.getItem('survey_queue')) || [],
            saveQueue: (queue) => localStorage.setItem('survey_queue', JSON.stringify(queue)),
            getSynced: () => JSON.parse(localStorage.getItem('survey_synced')) || [],
            saveSynced: (data) => localStorage.setItem('survey_synced', JSON.stringify(data)),

            // Add to outbox queue first (Offline-First rule)
            addToQueue: (survey) => {
                const queue = DB.getQueue();
                queue.push(survey);
                DB.saveQueue(queue);
            },

            // Move item from queue to synced list upon successful network request
            moveToSynced: (id) => {
                const queue = DB.getQueue();
                const synced = DB.getSynced();

                const itemIndex = queue.findIndex(item => item.id === id);
                if (itemIndex > -1) {
                    const [item] = queue.splice(itemIndex, 1);
                    item.syncedAt = new Date().toLocaleTimeString();
                    synced.unshift(item); // Add newest synced at top
                    DB.saveQueue(queue);
                    DB.saveSynced(synced);
                }
            }
        };

        // --- STATE & CONFIG ---
        let isOnline = navigator.onLine;
        let isSyncing = false;

        // --- DOM ELEMENTS ---
        const form = document.getElementById('survey-form');
        const queueList = document.getElementById('queue-list');
        const syncedList = document.getElementById('synced-list');
        const queueCount = document.getElementById('queue-count');
        const syncedCount = document.getElementById('synced-count');
        const connectionBadge = document.getElementById('connection-badge');
        const statusDot = document.getElementById('status-dot');
        const statusText = document.getElementById('status-text');
        const simulateOfflineCheckbox = document.getElementById('simulate-offline');

        // --- MOCK SERVER API ---
        // Simulates a remote server database API with latency
        const api = {
            uploadSurvey: async (survey) => {
                return new Promise((resolve, reject) => {
                    setTimeout(() => {
                        // Fail if physical network is down OR user checked the "Simulate Outage" box
                        if (!navigator.onLine || simulateOfflineCheckbox.checked) {
                            reject(new Error("Network connection failure."));
                        } else {
                            resolve({ success: true, serverId: 'SRV-' + Math.random().toString(36).substr(2, 9) });
                        }
                    }, 1500); // 1.5-second artificial latency
                });
            }
        };

        // --- CONTROLLERS & SYNC ENGINE ---

        // 1. Update Connection Status UI
        function updateNetworkStatus() {
            const simulatedOffline = simulateOfflineCheckbox.checked;
            isOnline = navigator.onLine && !simulatedOffline;

            if (isOnline) {
                connectionBadge.className = "px-4 py-2 rounded-full font-semibold text-sm flex items-center gap-2 bg-green-100 text-green-800";
                statusDot.className = "w-3 h-3 rounded-full bg-green-500 animate-pulse";
                statusText.innerText = "Online & Connected";
                // Trigger background sync instantly when connection returns
                syncQueue();
            } else {
                connectionBadge.className = "px-4 py-2 rounded-full font-semibold text-sm flex items-center gap-2 bg-red-100 text-red-800";
                statusDot.className = "w-3 h-3 rounded-full bg-red-500";
                statusText.innerText = simulatedOffline ? "Simulated Offline" : "Offline (Local Only)";
            }
        }

        // 2. The Core Sync Loop
        async function syncQueue() {
            if (isSyncing || !isOnline) return;

            const queue = DB.getQueue();
            if (queue.length === 0) return;

            isSyncing = true;
            statusText.innerText = `Syncing (${queue.length} left)...`;

            // Process sequentially to preserve order of events
            for (const survey of queue) {
                try {
                    // Update UI status to show active item syncing
                    document.getElementById(`item-${survey.id}`)?.classList.add('opacity-50', 'animate-pulse');

                    await api.uploadSurvey(survey);
                    DB.moveToSynced(survey.id);
                    renderUI();
                } catch (error) {
                    console.warn("Sync failed for item", survey.id, error.message);
                    // Halt sync loop if network drops during sync
                    break;
                }
            }

            isSyncing = false;
            updateNetworkStatus();
        }

        // 3. Save Form Handler
        form.addEventListener('submit', (e) => {
            e.preventDefault();

            // Assemble survey schema
            const survey = {
                id: 'SURV-' + Date.now(),
                location: document.getElementById('location').value,
                surveyor: document.getElementById('surveyor').value,
                condition: document.getElementById('condition').value,
                notes: document.getElementById('notes').value,
                createdAt: new Date().toLocaleTimeString()
            };

            // Rule #1 of Offline-First: Always write to local DB first
            DB.addToQueue(survey);

            // Clean UI form
            form.reset();
            renderUI();

            // Rule #2: Attempt sync immediately in background
            syncQueue();
        });

        // 4. Render Interface from Local DB State
        function renderUI() {
            const queue = DB.getQueue();
            const synced = DB.getSynced();

            queueCount.innerText = queue.length;
            syncedCount.innerText = synced.length;

            // Render Queue
            if (queue.length === 0) {
                queueList.innerHTML = `<p class="text-xs text-gray-400 text-center py-4">No pending surveys in outbox.</p>`;
            } else {
                queueList.innerHTML = queue.map(item => `
                    <div id="item-${item.id}" class="p-3 bg-amber-50 border border-amber-200 rounded text-xs space-y-1 transition duration-300">
                        <div class="flex justify-between font-bold text-gray-700">
                            <span>📍 ${escapeHtml(item.location)}</span>
                            <span class="text-amber-600">Pending</span>
                        </div>
                        <div class="text-gray-500">By: ${escapeHtml(item.surveyor)} | Rating: ${item.condition}</div>
                        <div class="italic text-gray-400">${escapeHtml(item.notes || 'No notes')}</div>
                        <div class="text-[10px] text-gray-400 text-right">${item.createdAt}</div>
                    </div>
                `).join('');
            }

            // Render Synced
            if (synced.length === 0) {
                syncedList.innerHTML = `<p class="text-xs text-gray-400 text-center py-4">No synced database records.</p>`;
            } else {
                syncedList.innerHTML = synced.map(item => `
                    <div class="p-3 bg-green-50 border border-green-200 rounded text-xs space-y-1">
                        <div class="flex justify-between font-bold text-gray-700">
                            <span>📍 ${escapeHtml(item.location)}</span>
                            <span class="text-green-600 font-normal">✔ Synced</span>
                        </div>
                        <div class="text-gray-500">By: ${escapeHtml(item.surveyor)} | Rating: ${item.condition}</div>
                        <div class="text-[10px] text-gray-400 text-right">Synced: ${item.syncedAt}</div>
                    </div>
                `).join('');
            }
        }

        // Helper to prevent XSS
        function escapeHtml(str) {
            return str.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;").replace(/'/g, "&#039;");
        }

        // --- LIFECYCLE LISTENERS ---
        window.addEventListener('online', updateNetworkStatus);
        window.addEventListener('offline', updateNetworkStatus);
        simulateOfflineCheckbox.addEventListener('change', updateNetworkStatus);

        // Initial Boot
        updateNetworkStatus();
        renderUI();

        // Execute background sync on app start in case there are pending items from previous session
        syncQueue();
    </script>
</body>
</html>
```

### Key Architectural Concepts Visualized in This Code:
1. **Writes Go Local First**: When you submit the form, data is added straight to the `localStorage` queue **before** any API call is initiated. The form clears and the UI updates instantly. There is no waiting spinner blocking the user.
2. **Persistent Queue**: The outbox is stored inside persistent storage. If the user closes the app or if the device runs out of battery, the data is safe and waiting in the queue for the next launch.
3. **Reactive Native Connection Listeners**: The app registers browser events (`window.onLine`/`onOffline`). When your computer regains internet access, the sync loop (`syncQueue()`) is automatically kicked off in the background.
4. **Optimistic UI with Outbox Tracking**: The UI visually separates items that are successfully saved on the server from items currently stuck in the offline queue (the "Outbox Queue").

To demonstrate an offline-first architecture, here is a complete, minimal working version of a field surveying app built using **Dart** and the **Flutter** framework (our #1 ranked recommendation). 

This app allows a surveyor to capture locations (GPS coordinates) and names of survey points. If the app is offline, it saves them to a local database. Once connectivity is restored, a background synchronization engine automatically pushes the unsynced data to a remote server.

### Prerequisites
To make this demo runnable without complex database installations, this implementation uses:
1. `shared_preferences` for local persistent storage.
2. An integrated **"Simulate Offline Mode"** switch so you can test the sync mechanics directly on your screen without having to disable your computer/phone's actual internet connection.

