class SurveyPoint {
  final String id;
  final String name;
  final double latitude;
  final double longitude;
  bool isSynced;

  SurveyPoint({
    required this.id,
    required this.name,
    required this.latitude,
    required this.longitude,
    this.isSynced = false,
  });

  Map<String, dynamic> toMap() {
    return {
      'id': id,
      'name': name,
      'latitude': latitude,
      'longitude': longitude,
      'isSynced': isSynced,
    };
  }

  factory SurveyPoint.fromMap(Map<String, dynamic> map) {
    return SurveyPoint(
      id: map['id'],
      name: map['name'],
      latitude: map['latitude'],
      longitude: map['longitude'],
      isSynced: map['isSynced'] ?? false,
    );
  }
}

// --- MAIN SCREEN ---
class SurveyScreen extends StatefulWidget {
  const SurveyScreen({super.key});

  @override
  State<SurveyScreen> createState() => _SurveyScreenState();
}

class _SurveyScreenState extends State<SurveyScreen> {
  final List<SurveyPoint> _localSurveys = [];
  final _nameController = TextEditingController();
  final _latController = TextEditingController();
  final _lngController = TextEditingController();

  bool _isOnline = true; // Simulated network status
  bool _isSyncing = false;
  late SharedPreferences _prefs;

  @override
  void initState() {
    super.initState();
    _initLocalDatabase();
  }

  // Initialize Local Storage & load saved surveys
  Future<void> _initLocalDatabase() async {
    _prefs = await SharedPreferences.getInstance();
    _loadSurveysFromStorage();
  }

  void _loadSurveysFromStorage() {
    final List<String> savedData = _prefs.getStringList('surveys') ?? [];
    setState(() {
      _localSurveys.clear();
      for (var item in savedData) {
        _localSurveys.add(SurveyPoint.fromMap(jsonDecode(item)));
      }
    });
  }

  Future<void> _saveAllToStorage() async {
    final List<String> dataToSave = _localSurveys
        .map((survey) => jsonEncode(survey.toMap()))
        .toList();
    await _prefs.setStringList('surveys', dataToSave);
  }

  // --- OFFLINE-FIRST LOGIC: WRITE LOCALLY FIRST ---
  Future<void> _addSurvey() async {
    if (_nameController.text.isEmpty ||
        _latController.text.isEmpty ||
        _lngController.text.isEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('Please fill all fields')),
      );
      return;
    }

    final newSurvey = SurveyPoint(
      id: const Uuid().v4(),
      name: _nameController.text,
      latitude: double.parse(_latController.text),
      longitude: double.parse(_lngController.text),
      isSynced: false,
    );

    setState(() {
      _localSurveys.add(newSurvey);
    });

    await _saveAllToStorage();

    _nameController.clear();
    _latController.clear();
    _lngController.clear();

    // Trigger sync automatically
    _syncData();
  }

  // --- SYNC ENGINE ---
  Future<void> _syncData() async {
    if (!_isOnline) {
      debugPrint("Offline: Sync deferred until connection is restored.");
      return;
    }
    if (_isSyncing) return;

    // Find unsynced records
    final unsyncedItems = _localSurveys.where((s) => !s.isSynced).toList();
    if (unsyncedItems.isEmpty) return;

    setState(() {
      _isSyncing = true;
    });

    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(content: Text('Syncing ${unsyncedItems.length} survey(s)...')),
    );

    for (var survey in unsyncedItems) {
      // Mock API call to remote server
      bool success = await _mockApiUpload(survey);
      if (success) {
        setState(() {
          survey.isSynced = true;
        });
      }
    }

    await _saveAllToStorage();

    setState(() {
      _isSyncing = false;
    });

    ScaffoldMessenger.of(context).showSnackBar(
      const SnackBar(content: Text('Synchronization complete!')),
    );
  }

  // Mock API service (e.g., POST to https://api.survey-server.com/points)
  Future<bool> _mockApiUpload(SurveyPoint survey) async {
    await Future.delayed(const Duration(seconds: 1)); // Simulate latency
    debugPrint("POST Request: Sending ${survey.name} to Remote Server");
    return true; // Simulate successful response
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: const Text('Field Surveyor (Offline-First)'),
        backgroundColor: Colors.teal[700],
        foregroundColor: Colors.white,
        actions: [
          // Network Simulator Toggle
          Row(
            children: [
              Icon(_isOnline ? Icons.wifi : Icons.wifi_off, 
                   color: _isOnline ? Colors.greenAccent : Colors.redAccent),
              const SizedBox(width: 4),
              Text(_isOnline ? "Online" : "Offline", style: const TextStyle(fontSize: 12)),
              Switch(
                value: _isOnline,
                activeColor: Colors.greenAccent,
                onChanged: (val) {
                  setState(() {
                    _isOnline = val;
                  });
                  if (_isOnline) {
                    _syncData(); // Automatically sync when connection comes back
                  }
                },
              ),
            ],
          )
        ],
      ),
      body: Padding(
        padding: const EdgeInsets.all(16.0),
        Widget: Column(
          children: [
            // SURVEY INPUT FORM
            Card(
              elevation: 4,
              child: Padding(
                padding: const EdgeInsets.all(16.0),
                child: Column(
                  children: [
                    TextField(
                      controller: _nameController,
                      decoration: const InputDecoration(labelText: 'Location/Feature Name'),
                    ),
                    Row(
                      children: [
                        Expanded(
                          child: TextField(
                            controller: _latController,
                            keyboardType: TextInputType.number,
                            decoration: const InputDecoration(labelText: 'Latitude'),
                          ),
                        ),
                        const SizedBox(width: 16),
                        Expanded(
                          child: TextField(
                            controller: _lngController,
                            keyboardType: TextInputType.number,
                            decoration: const InputDecoration(labelText: 'Longitude'),
                          ),
                        ),
                      ],
                    ),
                    const SizedBox(height: 16),
                    ElevatedButton.icon(
                      onPressed: _addSurvey,
                      icon: const Icon(Icons.add_location_alt),
                      label: const Text('Save Survey Point'),
                      style: ElevatedButton.styleFrom(
                        minimumSize: const Size.fromHeight(45),
                        backgroundColor: Colors.teal,
                        foregroundColor: Colors.white,
                      ),
                    )
                  ],
                ),
              ),
            ),
            const SizedBox(height: 16),
            Row(
              mainAxisAlignment: MainAxisAlignment.spaceBetween,
              children: [
                const Text('Local Survey Records', style: TextStyle(fontSize: 18, fontWeight: FontWeight.bold)),
                if (_isSyncing) const SizedBox(height: 20, width: 20, child: CircularProgressIndicator(strokeWidth: 2))
              ],
            ),
            const SizedBox(height: 8),

            // SURVEY LIST
            Expanded(
              child: _localSurveys.isEmpty
                  ? const Center(child: Text('No surveys saved yet.'))
                  : ListView.builder(
                      itemCount: _localSurveys.length,
                      itemBuilder: (context, index) {
                        final survey = _localSurveys[index];
                        return Card(
