// 1. DATA MODEL
class Survey {
  final String id;
  final String location;
  final String observation;
  bool isSynced;

  Survey({
    required this.id,
    required this.location,
    required this.observation,
    this.isSynced = false,
  });

  Map<String, dynamic> toJson() => {
        'id': id,
        'location': location,
        'observation': observation,
        'isSynced': isSynced,
      };

  factory Survey.fromJson(Map<String, dynamic> json) => Survey(
        id: json['id'],
        location: json['location'],
        observation: json['observation'],
        isSynced: json['isSynced'] ?? false,
      );
}

// 2. MAIN SCREEN & OFFLINE-FIRST LOGIC
class SurveyScreen extends StatefulWidget {
  const SurveyScreen({super.key});

  @override
  State<SurveyScreen> createState() => _SurveyScreenState();
}

class _SurveyScreenState extends State<SurveyScreen> {
  final List<Survey> _surveys = [];
  final _locationController = TextEditingController();
  final _observationController = TextEditingController();

  bool _isOnline = true; // Manual toggle to simulate field connectivity
  bool _isSyncing = false;
  late SharedPreferences _prefs;

  @override
  void initState() {
    super.initState();
    _initLocalStorage();
  }

  // Initialize SharedPreferences and load cached data
  Future<void> _initLocalStorage() async {
    _prefs = await SharedPreferences.getInstance();
    _loadSurveysFromLocal();
  }

  // Load from local storage (Offline-First Read)
  void _loadSurveysFromLocal() {
    final String? surveyData = _prefs.getString('survey_cache');
    if (surveyData != null) {
      final List<dynamic> decoded = jsonDecode(surveyData);
      setState(() {
        _surveys.clear();
        _surveys.addAll(decoded.map((x) => Survey.fromJson(x)).toList());
      });
    }
  }

  // Save to local storage
  Future<void> _saveSurveysToLocal() async {
    final String encoded = jsonEncode(_surveys.map((x) => x.toJson()).toList());
    await _prefs.setString('survey_cache', encoded);
  }

  // 3. OFFLINE-FIRST WRITE ACTION
  Future<void> _submitSurvey() async {
    if (_locationController.text.isEmpty || _observationController.text.isEmpty) {
      return;
    }

    final newSurvey = Survey(
      id: DateTime.now().millisecondsSinceEpoch.toString(),
      location: _locationController.text,
      observation: _observationController.text,
      isSynced: false,
    );

    setState(() {
      // Step A: Immediately add to local list (UI Updates instantly)
      _surveys.add(newSurvey);
      _locationController.clear();
      _observationController.clear();
    });

    // Step B: Persist locally so data isn't lost if app crashes offline
    await _saveSurveysToLocal();

    // Step C: Attempt sync if online
    if (_isOnline) {
      _syncPendingSurveys();
    }
  }

  // 4. THE SYNC ENGINE (Sync on Reconnection)
  Future<void> _syncPendingSurveys() async {
    final pending = _surveys.where((s) => !s.isSynced).toList();
    if (pending.isEmpty || _isSyncing) return;

    setState(() => _isSyncing = true);

    for (var survey in pending) {
      // Simulate network request delay (API POST)
      await Future.delayed(const Duration(seconds: 1)); 

      if (_isOnline) {
        setState(() {
          survey.isSynced = true; // Mark as successfully synced
        });
        debugPrint('Successfully synced survey: ${survey.id}');
      } else {
        debugPrint('Sync interrupted: Network lost.');
        break; // Stop trying to sync if connection dropped mid-process
      }
    }

    // Update local storage with new sync statuses
    await _saveSurveysToLocal();
    setState(() => _isSyncing = false);
  }

  // Toggle Connection State
  void _toggleNetwork(bool value) {
    setState(() {
      _isOnline = value;
    });
    if (_isOnline) {
      // Trigger synchronization immediately upon reconnection
      _syncPendingSurveys();
    }
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: const Text('Field Survey (Offline-First)'),
        backgroundColor: Theme.of(context).colorScheme.inversePrimary,
        actions: [
          // Connection simulation control
          Row(
            children: [
              Icon(
                _isOnline ? Icons.wifi : Icons.wifi_off,
                color: _isOnline ? Colors.green : Colors.red,
              ),
              const SizedBox(width: 4),
              Text(_isOnline ? 'ONLINE' : 'OFFLINE', style: const TextStyle(fontWeight: FontWeight.bold)),
              Switch(
                value: _isOnline,
                onChanged: _toggleNetwork,
                activeColor: Colors.green,
                inactiveThumbColor: Colors.red,
              )
            ],
          )
        ],
      ),
      body: Padding(
        padding: const EdgeInsets.all(16.0),
        child: Column(
          children: [
            // SURVEY CREATION FORM
            Card(
              elevation: 4,
              child: Padding(
                padding: const EdgeInsets.all(12.0),
                child: Column(
                  children: [
                    const Text('New Survey Entry', style: TextStyle(fontWeight: FontWeight.bold, fontSize: 16)),
                    TextField(
                      controller: _locationController,
                      decoration: const InputDecoration(labelText: 'Location / GPS Coordinate Label'),
                    ),
                    TextField(
                      controller: _observationController,
                      decoration: const InputDecoration(labelText: 'Observation / Notes'),
                    ),
                    const SizedBox(height: 12),
                    ElevatedButton.icon(
                      onPressed: _submitSurvey,
                      icon: const Icon(Icons.add_location),
                      label: const Text('Save Local & Submit'),
                    ),
                  ],
                ),
              ),
            ),
            const SizedBox(height: 10),
            if (_isSyncing)
              const LinearProgressIndicator(color: Colors.blue),
            const SizedBox(height: 10),
            const Align(
              alignment: Alignment.centerLeft,
              child: Text('Local Database Records:', style: TextStyle(fontWeight: FontWeight.bold)),
            ),
            // SURVEY LIST DISPLAY
            Expanded(
              child: _surveys.isEmpty
                  ? const Center(child: Text('No local surveys found.'))
                  : ListView.builder(
                      itemCount: _surveys.length,
                      itemBuilder: (context, index) {
                        final survey = _surveys[index];
                        return Card(
                          color: survey.isSynced ? Colors.green[50] : Colors.amber[50],
                          child: ListTile(
                            leading: CircleAvatar(
                              backgroundColor: survey.isSynced ? Colors.green : Colors.amber,
                              child: Icon(
                                survey.isSynced ? Icons.cloud_done : Icons.cloud_off,
                                color: Colors.white,
                              ),
                            ),
                            title: Text(survey.location, style: const TextStyle(fontWeight: FontWeight.bold)),
                            subtitle: Text(survey.observation),
                            trailing: Text(
                              survey.isSynced ? 'Synced' : 'Pending Sync',
                              style: TextStyle(
                                color: survey.isSynced ? Colors.green[800] : Colors.amber[800],
                                fontWeight: FontWeight.bold,
                              ),
                            ),
                          ),
                        );
                      },
                    ),
            ),
          ],
        ),
      ),
    );
  }
}
