            margin-bottom: 10px;
            position: relative;
        }
        .badge {
            position: absolute;
            top: 12px;
            right: 12px;
            font-size: 12px;
            padding: 4px 8px;
            border-radius: 12px;
            font-weight: bold;
        }
        .badge.synced { background-color: #dcfce7; color: var(--success); }
        .badge.pending { background-color: #fef9c3; color: var(--warning); }
    </style>
</head>
<body>

<div class="app-container">
    <h2>Field Surveyor (Offline-First)</h2>

    <!-- Connection Status -->
    <div id="connectionStatus" class="status-bar online">Checking connection...</div>

    <!-- Survey Form -->
    <form id="surveyForm">
        <div class="form-group">
            <label for="surveyor">Surveyor Name</label>
            <input type="text" id="surveyor" required placeholder="John Doe">
        </div>

        <div class="form-group">
            <label>Location (GPS)</label>
            <button type="button" class="gps-btn" onclick="getLocation()">Acquire GPS Coordinates</button>
            <input type="text" id="coords" placeholder="Waiting for GPS..." readonly required>
        </div>

        <div class="form-group">
            <label for="notes">Observation Notes</label>
            <textarea id="notes" rows="3" placeholder="Describe soil, vegetation, or assets..." required></textarea>
        </div>

        <button type="submit">Save Survey</button>
    </form>

    <!-- Local Survey Cache -->
    <div class="survey-list">
        <h3>Local Records</h3>
        <div id="recordsContainer">No records captured yet.</div>
    </div>
</div>

<script>
    // --- 1. LOCAL DATABASE CONFIGURATION (IndexedDB Wrapper) ---
    const DB_NAME = "SurveyFieldDB";
    const STORE_NAME = "surveys";
    let db;

    function initDB() {
        return new Promise((resolve, reject) => {
            const request = indexedDB.open(DB_NAME, 1);
            request.onupgradeneeded = (e) => {
                const database = e.target.result;
                database.createObjectStore(STORE_NAME, { keyPath: "id", autoIncrement: true });
            };
            request.onsuccess = (e) => {
                db = e.target.result;
                resolve(db);
            };
            request.onerror = (e) => reject("IndexedDB failed to open");
        });
    }

    // Save survey locally
    async function saveLocally(survey) {
        return new Promise((resolve, reject) => {
            const transaction = db.transaction([STORE_NAME], "readwrite");
            const store = transaction.objectStore(STORE_NAME);
            const request = store.add(survey);
            request.onsuccess = () => resolve();
            request.onerror = () => reject("Error saving locally");
        });
    }

    // Retrieve all surveys
    async function getAllSurveys() {
        return new Promise((resolve) => {
            const transaction = db.transaction([STORE_NAME], "readonly");
            const store = transaction.objectStore(STORE_NAME);
            const request = store.getAll();
            request.onsuccess = () => resolve(request.result);
        });
    }

    // Update survey status to "synced"
    async function markAsSynced(id) {
        return new Promise((resolve) => {
            const transaction = db.transaction([STORE_NAME], "readwrite");
            const store = transaction.objectStore(STORE_NAME);
            const getReq = store.get(id);
            getReq.onsuccess = () => {
                const data = getReq.result;
                data.status = "synced";
                store.put(data).onsuccess = () => resolve();
            };
        });
    }

    // --- 2. GPS & UI UTILITIES ---
    function getLocation() {
        const coordsInput = document.getElementById('coords');
        coordsInput.value = "Acquiring...";
        if (navigator.geolocation) {
            navigator.geolocation.getCurrentPosition(
                (pos) => {
                    coordsInput.value = `${pos.coords.latitude.toFixed(6)}, ${pos.coords.longitude.toFixed(6)}`;
                },
                () => {
                    coordsInput.value = "GPS Access Denied/Timed out";
                }
            );
        } else {
            coordsInput.value = "Geolocation not supported";
        }
    }

    async function updateUI() {
        const surveys = await getAllSurveys();
        const container = document.getElementById('recordsContainer');
        if (surveys.length === 0) {
            container.innerHTML = "No records captured yet.";
            return;
        }

        container.innerHTML = surveys.reverse().map(s => `
            <div class="survey-card">
                <span class="badge ${s.status}">${s.status.toUpperCase()}</span>
                <strong>${s.surveyor}</strong><br>
                <small>${s.timestamp}</small><br>
                <code style="font-size:12px;">GPS: ${s.coords}</code>
                <p style="margin: 8px 0 0 0; font-size:14px; color:#4b5563;">${s.notes}</p>
            </div>
        `).join('');
    }

    // --- 3. SYNC ENGINE (Offline-First Magic) ---

    // Mock API Server endpoint simulator
    function mockPostToServer(data) {
        return new Promise((resolve, reject) => {
            console.log("Sending data to simulated server:", data);
            setTimeout(() => {
                // Simulating successful write API receipt
                resolve({ success: true });
            }, 1000); 
        });
    }

    // Main sync task
    async function syncData() {
        if (!navigator.onLine) return; // Prevent run if offline

        const surveys = await getAllSurveys();
        const pendingSurveys = surveys.filter(s => s.status === "pending");

        if (pendingSurveys.length === 0) return;

        console.log(`Found ${pendingSurveys.length} pending survey(s). Syncing...`);

        for (const survey of pendingSurveys) {
            try {
                // Post individual item to remote server
                await mockPostToServer(survey);
                // Mark locally as synced on success
                await markAsSynced(survey.id);
            } catch (err) {
                console.error("Sync failed for record: ", survey.id, err);
                break; // Stop execution on server error to preserve queue order
            }
        }
        updateUI();
    }

    // Monitor connectivity status
    function updateConnectionStatus() {
        const statusBar = document.getElementById('connectionStatus');
        if (navigator.onLine) {
            statusBar.innerText = "ONLINE (Sync Active)";
            statusBar.className = "status-bar online";
            syncData(); // Automatically attempt sync when network comes back
        } else {
            statusBar.innerText = "OFFLINE (Saving Locally)";
            statusBar.className = "status-bar offline";
        }
    }

    // --- 4. APP EVENT LISTENERS & INITS ---
    window.addEventListener('online', updateConnectionStatus);
    window.addEventListener('offline', updateConnectionStatus);

    document.getElementById('surveyForm').addEventListener('submit', async (e) => {
        e.preventDefault();

        const newSurvey = {
            surveyor: document.getElementById('surveyor').value,
            coords: document.getElementById('coords').value,
            notes: document.getElementById('notes').value,
            status: "pending", // ALWAYS save as pending first
            timestamp: new Date().toLocaleString()
        };

        // 1. Persist locally first (Offline-first rule #1)
        await saveLocally(newSurvey);
        document.getElementById('notes').value = ""; // Reset form input
        updateUI();

        // 2. Try to sync immediately in the background
        syncData();
    });

    // Run on startup
    window.onload = async () => {
        await initDB();
        updateConnectionStatus();
        updateUI();
    };
</script>
</body>
</html>
```

### Architectural Highlights in This Code:
1. **The DB Paradox Solution:** The UI does not submit data directly to an API. Instead, it submits data *exclusively* to **IndexedDB** locally first. This guarantees data safety even if connection breaks mid-submission.
2. **Dynamic Sync Triggers:** The Sync engine (`syncData()`) is triggered by three events:
   * When the app initializes.
   * When a new survey is saved.
   * When the browser fires the `window.ononline` browser event.
3. **Queue Preservation:** The sync logic steps through the local database systematically. If a remote server failure occurs during the sync loop, it breaks early, preserving the order of unsynced surveys until connectivity becomes stable.

Here is a minimal, fully functional offline-first field surveying application built using **TypeScript**, **React Native (Expo)**, and **SQLite**. 

This app allows field surveyors to capture data offline. It immediately saves surveys to a local database and automatically synchronizes them to a cloud endpoint as soon as an internet connection is detected.

