### 1. Local Database Configuration (`database.ts`)
This file handles local storage on the physical device. It creates the database, initializes the table, and manages local read/write transactions.

```typescript
// database.ts
import * as SQLite from 'expo-sqlite';

export interface Survey {
  id?: number;
  locationName: string;
  surveyorName: string;
  notes: string;
  latitude: number;
  longitude: number;
  status: 'pending' | 'synced';
  createdAt: string;
}

// Open (or create) the SQLite database synchronously
const db = SQLite.openDatabaseSync('survey_db.db');

export const initDB = () => {
  db.execSync(`
    CREATE TABLE IF NOT EXISTS surveys (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      locationName TEXT NOT NULL,
      surveyorName TEXT NOT NULL,
      notes TEXT,
      latitude REAL NOT NULL,
      longitude REAL NOT NULL,
      status TEXT NOT NULL DEFAULT 'pending',
      createdAt TEXT NOT NULL
    );
  `);
  console.log('Local SQLite Database Initialized.');
};

export const saveSurveyLocally = (survey: Omit<Survey, 'id' | 'status' | 'createdAt'>): Survey => {
  const createdAt = new Date().toISOString();

  const result = db.runSync(
    `INSERT INTO surveys (locationName, surveyorName, notes, latitude, longitude, status, createdAt) 
     VALUES (?, ?, ?, ?, ?, 'pending', ?);`,
    [survey.locationName, survey.surveyorName, survey.notes, survey.latitude, survey.longitude, createdAt]
  );

  return {
    id: result.lastInsertRowId,
    ...survey,
    status: 'pending',
    createdAt
  };
};

export const getAllLocalSurveys = (): Survey[] => {
  return db.getAllSync<Survey>('SELECT * FROM surveys ORDER BY id DESC;');
};

export const getUnsyncedSurveys = (): Survey[] => {
  return db.getAllSync<Survey>("SELECT * FROM surveys WHERE status = 'pending';");
};

export const markAsSynced = (id: number) => {
  db.runSync("UPDATE surveys SET status = 'synced' WHERE id = ?;", [id]);
};
```

