### 2. Synchronization Service (`syncService.ts`)
This service handles syncing local "pending" surveys to a mock remote REST API (using standard `fetch`). Upon a successful API call, it marks the local SQLite record as `synced`.

```typescript
// syncService.ts
import { getUnsyncedSurveys, markAsSynced, Survey } from './database';

// Using a public mock API endpoint for demonstration
const REMOTE_API_ENDPOINT = 'https://jsonplaceholder.typicode.com/posts';

export const syncOfflineData = async (): Promise<{ successCount: number; total: number }> => {
  const pendingSurveys = getUnsyncedSurveys();
  let successCount = 0;

  if (pendingSurveys.length === 0) {
    return { successCount, total: 0 };
  }

  console.log(`Attempting to sync ${pendingSurveys.length} survey(s)...`);

  for (const survey of pendingSurveys) {
    try {
      const response = await fetch(REMOTE_API_ENDPOINT, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          title: `Survey: ${survey.locationName}`,
          body: JSON.stringify(survey),
          userId: 1,
        }),
      });

      if (response.ok) {
        // Update local status so we don't sync it again
        markAsSynced(survey.id!);
        successCount++;
        console.log(`Synced survey ID: ${survey.id}`);
      }
    } catch (error) {
      console.error(`Failed to sync survey ID ${survey.id}. Will retry later.`, error);
      break; // Stop syncing loop if server is unreachable
    }
  }

  return { successCount, total: pendingSurveys.length };
};
```

