### 3. User Interface & Network Listener (`App.tsx`)
This file coordinates the UI, listens to real-time network connectivity changes, triggers automatic syncs on reconnection, and displays data from SQLite.

```tsx
// App.tsx
import React, { useEffect, useState } from 'react';
import { 
  StyleSheet, Text, View, TextInput, Button, FlatList, SafeAreaView, ActivityIndicator, Alert 
} from 'react-native';
import NetInfo from '@react-native-community/netinfo';
import { initDB, saveSurveyLocally, getAllLocalSurveys, Survey } from './database';
import { syncOfflineData } from './syncService';

export default function App() {
  const [isConnected, setIsConnected] = useState<boolean | null>(null);
  const [isSyncing, setIsSyncing] = useState(false);
  const [surveys, setSurveys] = useState<Survey[]>([]);

  // Form State
  const [locationName, setLocationName] = useState('');
  const [surveyorName, setSurveyorName] = useState('');
  const [notes, setNotes] = useState('');

  // 1. Initialize SQLite Database on launch
  useEffect(() => {
    initDB();
    refreshLocalList();
  }, []);

  // 2. Listen to Network connectivity changes
  useEffect(() => {
    const unsubscribe = NetInfo.addEventListener((state) => {
      const wasOffline = isConnected === false;
      setIsConnected(state.isConnected);

      // Auto-sync when transitioning from Offline to Online
      if (state.isConnected && wasOffline) {
        triggerSync();
      }
    });

    return () => unsubscribe();
  }, [isConnected]);

  const refreshLocalList = () => {
    const data = getAllLocalSurveys();
    setSurveys(data);
  };

  const handleSubmit = () => {
    if (!locationName || !surveyorName) {
      Alert.alert('Error', 'Please fill in required fields.');
      return;
    }

    // Capture Mock GPS coordinates
    const mockLat = parseFloat((34.0522 + (Math.random() - 0.5) * 0.1).toFixed(4));
    const mockLng = parseFloat((-118.2437 + (Math.random() - 0.5) * 0.1).toFixed(4));

    // Write to SQLite immediately (Offline-First core principle)
    saveSurveyLocally({
      locationName,
      surveyorName,
      notes,
      latitude: mockLat,
      longitude: mockLng,
    });

    // Clear form
    setLocationName('');
    setNotes('');
    refreshLocalList();

    // If online, immediately trigger sync
    if (isConnected) {
      triggerSync();
    } else {
      Alert.alert('Saved Offline', 'Survey saved to local device. It will sync automatically when reconnected.');
    }
  };

  const triggerSync = async () => {
    setIsSyncing(true);
    const result = await syncOfflineData();
    setIsSyncing(false);

    if (result.total > 0) {
      Alert.alert('Sync complete', `Successfully synchronized ${result.successCount}/${result.total} surveys.`);
      refreshLocalList();
    }
  };

  return (
    <SafeAreaView style={styles.container}>
      {/* Network Status Header */}
      <View style={[styles.statusBar, isConnected ? styles.statusOnline : styles.statusOffline]}>
        <Text style={styles.statusText}>
          {isConnected ? '🟢 Online (Synced Mode)' : '🔴 Offline Mode (Saving Locally)'}
        </Text>
        {isSyncing && <ActivityIndicator size="small" color="#fff" />}
      </View>

      {/* Survey Capture Form */}
      <View style={styles.form}>
        <Text style={styles.title}>New Field Survey</Text>
        <TextInput 
          placeholder="Location Name *" 
          value={locationName} 
          onChangeText={setLocationName} 
          style={styles.input} 
        />
        <TextInput 
          placeholder="Surveyor Name *" 
          value={surveyorName} 
          onChangeText={setSurveyorName} 
          style={styles.input} 
        />
        <TextInput 
          placeholder="Notes (Optional)" 
          value={notes} 
          onChangeText={setNotes} 
          style={styles.input} 
          multiline
        />
        <Button title="Save Survey" onPress={handleSubmit} color="#1E88E5" />
      </View>

      {/* Sync Control & List */}
      <View style={styles.listContainer}>
        <View style={styles.listHeader}>
          <Text style={styles.subtitle}>Captured Surveys ({surveys.length})</Text>
          {isConnected && <Button title="Sync Now" onPress={triggerSync} disabled={isSyncing} />}
        </View>

        <FlatList
          data={surveys}
          keyExtractor={(item) => item.id!.toString()}
          renderItem={({ item }) => (
            <View style={styles.surveyCard}>
              <View>
                <Text style={styles.cardTitle}>{item.locationName}</Text>
                <Text style={styles.cardDetail}>By: {item.surveyorName} • GPS: {item.latitude}, {item.longitude}</Text>
                {item.notes ? <Text style={styles.cardNotes}>"{item.notes}"</Text> : null}
              </View>
              <Text style={[styles.badge, item.status === 'synced' ? styles.badgeSynced : styles.badgePending]}>
                {item.status.toUpperCase()}
              </Text>
            </View>
          )}
        />
      </View>
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  container: { flex: 1, backgroundColor: '#F5F7FA' },
  statusBar: { padding: 10, flexDirection: 'row', justifyContent: 'center', alignItems: 'center', gap: 10 },
  statusOnline: { backgroundColor: '#2E7D32' },
  statusOffline: { backgroundColor: '#C62828' },
  statusText: { color: 'white', fontWeight: 'bold', fontSize: 14 },
  form: { padding: 20, backgroundColor: '#FFF', elevation: 2, borderBottomWidth: 1, borderColor: '#DDD' },
  title: { fontSize: 20, fontWeight: 'bold', marginBottom: 15, color: '#333' },
  subtitle: { fontSize: 18, fontWeight: 'bold', color: '#333' },
  input: { borderWidth: 1, borderColor: '#CCC', padding: 10, borderRadius: 5, marginBottom: 12, backgroundColor: '#FAFAFA' },
  listContainer: { flex: 1, padding: 20 },
  listHeader: { flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', marginBottom: 10 },
  surveyCard: { 
    backgroundColor: '#FFF', padding: 15, borderRadius: 8, marginBottom: 10, 
    flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center',
    borderWidth: 1, borderColor: '#E0E0E0' 
  },
  cardTitle: { fontSize: 16, fontWeight: 'bold', color: '#222' },
  cardDetail: { fontSize: 12, color: '#666', marginTop: 2 },
  cardNotes: { fontSize: 13, fontStyle: 'italic', color: '#444', marginTop: 5 },
  badge: { fontSize: 10, fontWeight: 'bold', paddingVertical: 4, paddingHorizontal: 8, borderRadius: 12, overflow: 'hidden' },
  badgeSynced: { backgroundColor: '#E8F5E9', color: '#2E7D32' },
  badgePending: { backgroundColor: '#FFF3E0', color: '#EF6C00' },
});
