#### `backend/src/server.ts`
```typescript
import express from 'express';
import { createServer } from 'http';
import { Server, Socket } from 'socket.io';
import cors from 'cors';
import dotenv from 'dotenv';
import Stripe from 'stripe';
import * as admin from 'firebase-admin';

dotenv.config();

const app = express();
app.use(cors());
app.use(express.json());

const httpServer = createServer(app);
const io = new Server(httpServer, {
  cors: {
    origin: '*',
    methods: ['GET', 'POST']
  }
});

// Initialize Stripe
const stripe = new Stripe(process.env.STRIPE_SECRET_KEY || 'mock_key', {
  apiVersion: '2024-04-10',
});

// Initialize Firebase Admin (for push notifications)
if (process.env.FIREBASE_SERVICE_ACCOUNT_JSON) {
  const serviceAccount = JSON.parse(process.env.FIREBASE_SERVICE_ACCOUNT_JSON);
  admin.initializeApp({
    credential: admin.credential.cert(serviceAccount),
  });
}

interface User {
  id: string;
  username: string;
  socketId?: string;
  fcmToken?: string;
  isPremium: boolean;
}

// In-memory DB for demonstration
const users: Map<string, User> = new Map();

// --- 1. MONETIZATION ENDPOINT (Stripe) ---
app.post('/api/monetize/create-payment-intent', async (req, res) => {
  const { userId } = req.body;
  const user = users.get(userId);

  if (!user) {
    return res.status(404).json({ error: 'User not found' });
  }

  try {
    // Create a PaymentIntent for a Premium Upgrade ($9.99)
    const paymentIntent = await stripe.paymentIntents.create({
      amount: 999, // amount in cents
      currency: 'usd',
      metadata: { userId, product: 'premium_upgrade' },
    });

    res.status(200).json({
      clientSecret: paymentIntent.client_secret,
    });
  } catch (error: any) {
    res.status(500).json({ error: error.message });
  }
});

// Stripe Webhook to handle successful payments
app.post('/api/webhooks/stripe', express.raw({ type: 'application/json' }), async (req, res) => {
  const sig = req.headers['stripe-signature'] as string;
  let event;

  try {
    event = stripe.webhooks.constructEvent(
      req.body,
      sig,
      process.env.STRIPE_WEBHOOK_SECRET || ''
    );
  } catch (err: any) {
    return res.status(400).send(`Webhook Error: ${err.message}`);
  }

  if (event.type === 'payment_intent.succeeded') {
    const paymentIntent = event.data.object as Stripe.PaymentIntent;
    const userId = paymentIntent.metadata.userId;

    // Upgrade user to premium
    const user = users.get(userId);
    if (user) {
      user.isPremium = true;
      users.set(userId, user);
      console.log(`User ${userId} upgraded to Premium!`);

      // Notify client over websocket if they are online
      if (user.socketId) {
        io.to(user.socketId).emit('account_upgraded', { isPremium: true });
      }
    }
  }

  res.json({ received: true });
});

// --- 2. REAL-TIME CHAT & NOTIFICATIONS (Socket.io) ---
io.on('connection', (socket: Socket) => {
  console.log(`Socket connected: ${socket.id}`);

  // Register user device and socket connection
  socket.on('register_user', ({ userId, username, fcmToken }) => {
    const existingUser = users.get(userId) || { id: userId, username, isPremium: false };
    existingUser.socketId = socket.id;
    if (fcmToken) existingUser.fcmToken = fcmToken;
    users.set(userId, existingUser);

    console.log(`User ${username} (${userId}) registered.`);
  });

  // Handle Send Message Event
  socket.on('send_message', async (data: { senderId: string, recipientId: string, text: string }) => {
    const { senderId, recipientId, text } = data;
    const sender = users.get(senderId);
    const recipient = users.get(recipientId);

    if (!sender) return;

    const messagePayload = {
      id: Math.random().toString(36).substring(7),
      senderId,
      senderName: sender.username,
      text,
      createdAt: new Date().toISOString()
    };

    // If recipient is online, route instantly via WebSocket
    if (recipient && recipient.socketId) {
      io.to(recipient.socketId).emit('receive_message', messagePayload);
    } else if (recipient && recipient.fcmToken) {
      // --- PUSH NOTIFICATION ---
      // If recipient is offline, send FCM Push Notification
      const payload = {
        notification: {
          title: `New message from ${sender.username}`,
          body: text.length > 60 ? `${text.substring(0, 60)}...` : text,
        },
        data: {
          senderId,
          type: 'chat_message',
        },
        token: recipient.fcmToken,
      };

      try {
        await admin.messaging().send(payload);
        console.log(`Push notification sent to ${recipient.username}`);
      } catch (err) {
        console.error('Error sending push notification:', err);
      }
    }
  });

  socket.on('disconnect', () => {
    // Remove socket mapping
    for (let [userId, user] of users.entries()) {
      if (user.socketId === socket.id) {
        user.socketId = undefined;
        users.set(userId, user);
        console.log(`User ${user.username} went offline.`);
        break;
      }
    }
  });
});

const PORT = process.env.PORT || 4000;
httpServer.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});
