import express from 'express';
import { WebSocketServer, WebSocket } from 'ws';
import * as admin from 'firebase-admin';
import http from 'http';

const app = express();
app.use(express.json());

const server = http.createServer(app);
const wss = new WebSocketServer({ server });

// 1. Initialize Firebase Admin (for Real-time Push Notifications)
// Place your serviceAccountKey.json in the project root
const serviceAccount = require("../serviceAccountKey.json");
admin.initializeApp({
  credential: admin.credential.cert(serviceAccount)
});

// Mock Database for active user connections & FCM device tokens
interface UserSession {
  userId: string;
  ws?: WebSocket;
  fcmToken?: string;
}
const activeUsers = new Map<string, UserSession>();

// 2. WebSocket Server for Real-Time Instant Messaging
wss.on('connection', (ws: WebSocket) => {
  let authenticatedUserId: string | null = null;

  ws.on('message', async (messageData: string) => {
    try {
      const data = JSON.parse(messageData);

      // Authenticate/Register Connection
      if (data.type === 'auth') {
        authenticatedUserId = data.userId;
        activeUsers.set(authenticatedUserId, { 
          userId: authenticatedUserId, 
          ws, 
          fcmToken: data.fcmToken 
        });
        console.log(`User connected: ${authenticatedUserId}`);
        return;
      }

      // Handle Direct Message
      if (data.type === 'message') {
        const { recipientId, text, senderId } = data;
        const recipientSession = activeUsers.get(recipientId);

        if (recipientSession && recipientSession.ws && recipientSession.ws.readyState === WebSocket.OPEN) {
          // Recipient is online: Deliver instantly via WebSockets
          recipientSession.ws.send(JSON.stringify({
            type: 'message',
            senderId,
            text,
            timestamp: new Date().toISOString()
          }));
        } else {
          // Recipient is offline: Send a Real-Time Push Notification
          if (recipientSession?.fcmToken) {
            await sendPushNotification(recipientSession.fcmToken, senderId, text);
          }
        }
      }
    } catch (err) {
      console.error("Error processing message:", err);
    }
  });

  ws.on('close', () => {
    if (authenticatedUserId) {
      const session = activeUsers.get(authenticatedUserId);
      if (session) {
        session.ws = undefined; // Mark offline, keep FCM Token
      }
      console.log(`User went offline: ${authenticatedUserId}`);
    }
  });
});

// Helper function to send FCM push notification
async function sendPushNotification(token: string, senderId: string, messageText: string) {
  const payload = {
    notification: {
      title: `New message from ${senderId}`,
      body: messageText,
    },
    token: token,
  };

  try {
    await admin.messaging().send(payload);
    console.log(`Push notification successfully sent to ${token}`);
  } catch (error) {
    console.error("Error sending push notification:", error);
  }
}

// 3. In-App Monetization (Receipt/Purchase Verification Endpoint)
app.post('/api/monetize/verify-purchase', async (req, res) => {
  const { userId, productId, purchaseToken, platform } = req.body;

  if (!userId || !productId || !purchaseToken || !platform) {
    return res.status(400).json({ success: false, error: "Missing required fields" });
  }

  try {
    let isValid = false;

    if (platform === 'ios') {
      // In production, send validation request to Apple StoreKit sandbox/production endpoint
      // App Store endpoint: https://sandbox.itunes.apple.com/verifyReceipt
      isValid = true; // Simulate valid receipt
    } else if (platform === 'android') {
      // In production, use Google APIs client to call Android Publisher API
      isValid = true; // Simulate valid receipt
    }

    if (isValid) {
      // Upgrade user status in your database to premium
      console.log(`User ${userId} successfully upgraded to Premium via: ${productId}`);
      return res.status(200).json({ success: true, isPremium: true });
    } else {
      return res.status(400).json({ success: false, error: "Invalid purchase token" });
    }
  } catch (error) {
    return res.status(500).json({ success: false, error: "Verification server error" });
  }
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Secure server running on port ${PORT}`);
});
