class ChatScreen extends StatefulWidget {
  const ChatScreen({super.key});

  @override
  State<ChatScreen> createState() => _ChatScreenState();
}

class _ChatScreenState extends State<ChatScreen> {
  final String currentUserId = "user_alice_123";
  final String recipientId = "user_bob_456";
  final String backendUrl = "http://YOUR_LOCAL_IP:3000"; // Replace with local IP
  final String wsBackendUrl = "ws://YOUR_LOCAL_IP:3000";

  late IOWebSocketChannel _channel;
  final TextEditingController _textController = TextEditingController();
  final List<Map<String, dynamic>> _messages = [];

  // In-App Purchase logic
  final InAppPurchase _iap = InAppPurchase.instance;
  bool _isPremiumUser = false;
  final String _premiumProductId = 'premium_upgrade_tier_1';

  @override
  void initState() {
    super.initState();
    _initializePushNotifications();
    _connectWebSocket();
    _initializeInAppPurchases();
  }

  // 1. Initialize Real-Time Push Notifications (FCM)
  void _initializePushNotifications() async {
    FirebaseMessaging messaging = FirebaseMessaging.instance;
    NotificationSettings settings = await messaging.requestPermission(
      alert: true,
      badge: true,
      sound: true,
    );

    if (settings.authorizationStatus == AuthorizationStatus.authorized) {
      String? token = await messaging.getToken();
      print("FCM Token Generated: $token");

      // Send token authentication payload to backend
      _channel.sink.add(jsonEncode({
        "type": "auth",
        "userId": currentUserId,
        "fcmToken": token,
      }));
    }
  }

  // 2. Initialize Real-Time Chat (WebSockets)
  void _connectWebSocket() {
    _channel = IOWebSocketChannel.connect(Uri.parse(wsBackendUrl));
    _channel.stream.listen((message) {
      final decoded = jsonDecode(message);
      if (decoded['type'] == 'message') {
        setState(() {
          _messages.insert(0, {
            "senderId": decoded['senderId'],
            "text": decoded['text'],
            "isMe": decoded['senderId'] == currentUserId
          });
        });
      }
    });
  }

  void _sendMessage() {
    if (_textController.text.isNotEmpty) {
      final payload = {
        "type": "message",
        "senderId": currentUserId,
        "recipientId": recipientId,
        "text": _textController.text,
      };
      _channel.sink.add(jsonEncode(payload));

      setState(() {
        _messages.insert(0, {
          "senderId": currentUserId,
          "text": _textController.text,
          "isMe": true
        });
      });
      _textController.clear();
    }
  }

  // 3. In-App Monetization integration
  void _initializeInAppPurchases() async {
    final bool available = await _iap.isAvailable();
    if (!available) return;

    // Listen to store transactions
    _iap.purchaseStream.listen((List<PurchaseDetails> purchaseDetailsList) {
      _verifyPurchaseList(purchaseDetailsList);
    });
  }

  void _verifyPurchaseList(List<PurchaseDetails> purchaseDetailsList) async {
    for (var purchase in purchaseDetailsList) {
      if (purchase.status == PurchaseStatus.purchased) {
        // Send receipt to our TypeScript Backend to verify
        final response = await http.post(
          Uri.parse('$backendUrl/api/monetize/verify-purchase'),
          headers: {"Content-Type": "application/json"},
          body: jsonEncode({
            "userId": currentUserId,
            "productId": purchase.productID,
            "purchaseToken": purchase.verificationData.serverVerificationData,
            "platform": Theme.of(context).platform == TargetPlatform.iOS ? "ios" : "android",
          }),
        );

        if (response.statusCode == 200) {
          final resBody = jsonDecode(response.body);
          if (resBody['isPremium'] == true) {
            setState(() {
              _isPremiumUser = true;
            });
          }
        }
        await _iap.completePurchase(purchase); // Confirm receipt with StoreKit/Play Store
      }
    }
  }

  void _triggerPremiumPurchase() async {
    final ProductDetailsResponse response = await _iap.queryProductDetails({_premiumProductId});
    if (response.notFoundIDs.isNotEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('Product not found in App Store/Google Play.')),
      );
      return;
    }

    final ProductDetails productDetails = response.productDetails.first;
    final PurchaseParam purchaseParam = PurchaseParam(productDetails: productDetails);

    // Launch Store UI checkout overlay
    _iap.buyNonConsumable(purchaseParam: purchaseParam);
  }

  @override
  void dispose() {
    _channel.sink.close();
    _textController.dispose();
    super.dispose();
  }

