    super.initState();
    _connectWebSocket();
    _initializeInAppPurchases();
  }

  void _connectWebSocket() {
    _channel = WebSocketChannel.connect(Uri.parse(_wsUrl));
    _channel.stream.listen((message) {
      setState(() {
