          _showPremiumDialog("Unlock successful! You are now Premium.");
          if (purchase.pendingCompletePurchase) {
            await InAppPurchase.instance.completePurchase(purchase);
          }
        }
      }
    }
  }

  // Call Go Backend for validation
  Future<bool> _verifyPurchaseOnBackend(String receiptData, String platform) async {
    try {
      final response = await http.post(
        Uri.parse(_apiVerifyUrl),
        headers: {'Content-Type': 'application/json'},
        body: jsonEncode({
          'receipt_data': receiptData,
          'platform': platform == 'app_store' ? 'ios' : 'android',
          'user_id': 'user_123_test'
        }),
      );
      if (response.statusCode == 200) {
        final data = jsonDecode(response.body);
        return data['success'] ?? false;
      }
    } catch (e) {
      print("Verification error: $e");
    }
    return false;
  }

  // Trigger Purchase
