### Part 1: The Backend (`server.ts`)

This server handles WebSocket connections, validates whether a user has a premium subscription before delivering messages, and exposes a webhook endpoint to receive payment confirmations (simulating Stripe or RevenueCat).

```typescript
import express, { Request, Response } from 'express';
import { createServer } from 'http';
import { Server, Socket } from 'socket.io';
import cors from 'cors';

const app = express();
app.use(cors());
app.use(express.json());

const httpServer = createServer(app);
const io = new Server(httpServer, {
  cors: { origin: "*" }
});

// --- In-Memory Database for demonstration ---
interface User {
  id: string;
  username: string;
  isPremium: boolean;
  messageCount: number;
}

interface Message {
  id: string;
  senderId: string;
  senderName: string;
  text: string;
  timestamp: number;
}

const users: Record<string, User> = {
  "user_1": { id: "user_1", username: "Alice", isPremium: false, messageCount: 0 },
  "user_2": { id: "user_2", username: "Bob", isPremium: false, messageCount: 0 },
};

// --- Real-time Socket.io Architecture ---
io.on('connection', (socket: Socket) => {
  const userId = socket.handshake.query.userId as string;
  if (!userId || !users[userId]) {
    socket.disconnect();
    return;
  }

  console.log(`User connected: ${users[userId].username}`);
  socket.join(userId); // Join private room for targeted push notifications

  // Handle incoming chat messages
  socket.on('send_message', (data: { text: string; recipientId: string }) => {
    const sender = users[userId];

    // --- MONETIZATION PAYWALL CHECK ---
    if (!sender.isPremium && sender.messageCount >= 3) {
      socket.emit('subscription_required', {
        message: "You've reached your free limit of 3 messages. Upgrade to Premium for unlimited chat!"
      });
      return;
    }

    // Increment message count for free users
    if (!sender.isPremium) {
      sender.messageCount++;
    }

    const newMessage: Message = {
      id: Math.random().toString(36).substring(7),
      senderId: sender.id,
      senderName: sender.username,
      text: data.text,
      timestamp: Date.now()
    };

    // Send real-time message to recipient
    socket.to(data.recipientId).emit('receive_message', newMessage);

    // Trigger real-time Notification to recipient
    socket.to(data.recipientId).emit('notification', {
      title: `New message from ${sender.username}`,
      body: data.text.substring(0, 30) + (data.text.length > 30 ? '...' : '')
    });

    // Acknowledge receipt to sender
    socket.emit('message_sent', { newMessage, currentUsage: sender.messageCount });
  });

  socket.on('disconnect', () => {
    console.log(`User disconnected: ${users[userId]?.username}`);
  });
});

// --- MONETIZATION WEBHOOK (Stripe / RevenueCat Integration) ---
// This endpoint is called by your payment provider when a subscription succeeds.
app.post('/api/webhooks/payment', (req: Request, res: Response) => {
  const { userId, eventType } = req.body;

  if (!userId || !users[userId]) {
    return res.status(404).json({ error: "User not found" });
  }

  if (eventType === 'checkout.session.completed' || eventType === 'subscription.active') {
    users[userId].isPremium = true;
    console.log(`SUCCESS: User ${users[userId].username} upgraded to PREMIUM.`);

    // Notify the user client instantly via WebSocket that premium features are unlocked
    io.to(userId).emit('premium_unlocked', { isPremium: true });

    return res.status(200).json({ received: true, status: "Upgraded" });
  }

  res.status(400).json({ error: "Unhandled event type" });
});

const PORT = 3001;
httpServer.listen(PORT, () => {
  console.log(`Social backend running on http://localhost:${PORT}`);
});
