### Part 1: The Backend (`backend/server.ts`)
This server handles real-time WebSockets for messaging, manages rooms, utilizes Stripe to create checkout sessions for premium chat tier monetization, and listens to secure Stripe Webhooks to grant premium status.

First, initialize the backend dependencies:
```bash
# Inside backend/ directory
npm init -y
npm install express socket.io stripe cors dotenv
npm install --save-dev typescript @types/express @types/node ts-node @types/cors
```

Create `backend/server.ts`:

```typescript
import express, { Request, Response } from 'express';
import { createServer } from 'http';
import { Server, Socket } from 'socket.io';
import Stripe from 'stripe';
import cors from 'cors';
import dotenv from 'dotenv';

dotenv.config();

const app = express();
const httpServer = createServer(app);

// Initialize Socket.io with CORS enabled
const io = new Server(httpServer, {
  cors: {
    origin: "http://localhost:3000", // Frontend URL
    methods: ["GET", "POST"]
  }
});

// Initialize Stripe (Use Test Keys!)
const stripe = new Stripe(process.env.STRIPE_SECRET_KEY || 'sk_test_mock_key', {
  apiVersion: '2023-10-16', // or latest
});

app.use(cors());

// Webhook endpoint needs raw body parser for signature verification
app.post('/api/webhook', express.raw({ type: 'application/json' }), async (req: Request, res: Response) => {
  const sig = req.headers['stripe-signature'];
  const endpointSecret = process.env.STRIPE_WEBHOOK_SECRET;

  let event;

  try {
    event = stripe.webhooks.constructEvent(req.body, sig as string, endpointSecret || '');
  } catch (err: any) {
    console.error(`Webhook Error: ${err.message}`);
    return res.status(400).send(`Webhook Error: ${err.message}`);
  }

  // Handle successful payments to unlock premium features
  if (event.type === 'checkout.session.completed') {
    const session = event.data.object as Stripe.Checkout.Session;
    const clientReferenceId = session.client_reference_id; // This is the User ID

    if (clientReferenceId) {
      console.log(`Payment successful for User: ${clientReferenceId}`);

      // Notify the user in real-time via WebSocket that their premium features are active
      io.to(clientReferenceId).emit('notification', {
        type: 'SYSTEM_UPGRADE',
        title: 'Premium Unlocked!',
        message: 'Thank you for your purchase! You now have access to premium chat rooms.'
      });

      io.to(clientReferenceId).emit('user_status_updated', { isPremium: true });
    }
  }

  res.json({ received: true });
});

// Parse JSON for remaining endpoints
app.use(express.json());

// Monetization: Create Stripe Checkout Session
app.post('/api/checkout', async (req: Request, res: Response) => {
  const { userId } = req.body;

  try {
    const session = await stripe.checkout.sessions.create({
      payment_method_types: ['card'],
      line_items: [
        {
          price_data: {
            currency: 'usd',
            product_data: {
              name: 'Premium Chat Access',
              description: 'Unlock exclusive VIP channels and ad-free messaging',
            },
            unit_amount: 999, // $9.99 USD
          },
          quantity: 1,
        },
      ],
      mode: 'payment',
      client_reference_id: userId, // Pass user ID to map webhook back to user
      success_url: 'http://localhost:3000?payment=success',
      cancel_url: 'http://localhost:3000?payment=cancel',
    });

    res.json({ url: session.url });
  } catch (error: any) {
    res.status(500).json({ error: error.message });
  }
});

// Real-Time Socket Connection Logic
io.on('connection', (socket: Socket) => {
  console.log(`User connected: ${socket.id}`);

  // Authenticate and join user-specific room for targeted notifications
  socket.on('auth', (userId: string) => {
    socket.join(userId);
    console.log(`User ${userId} joined their private notification room.`);
  });

  // Join a messaging channel room
  socket.on('join_room', (room: string) => {
    socket.join(room);
    console.log(`Socket ${socket.id} joined channel: ${room}`);
  });

  // Handle incoming messages
  socket.on('send_message', (data: { room: string; sender: string; text: string; isPremiumRoom: boolean }) => {
    // Basic verification: Block standard users from Premium Room
    if (data.isPremiumRoom) {
      // In production, check your DB/session if user has premium status
    }

    // Broadcast message to everyone in the room
    io.to(data.room).emit('receive_message', {
      sender: data.sender,
      text: data.text,
      timestamp: new Date().toLocaleTimeString()
    });

    // Send a real-time system notification to everyone in the channel except sender
    socket.to(data.room).emit('notification', {
      type: 'NEW_MESSAGE',
      title: `New message in #${data.room}`,
      message: `${data.sender}: ${data.text.substring(0, 30)}...`
    });
  });

  socket.on('disconnect', () => {
    console.log(`User disconnected: ${socket.id}`);
  });
});

const PORT = process.env.PORT || 3001;
httpServer.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});
```

