Create `frontend/App.tsx`:

```tsx
import React, { useState, useEffect, useRef } from 'react';
import { io, Socket } from 'socket.io-client';
import { MessageSquare, ShieldAlert, Sparkles, Send, Bell } from 'lucide-react';
import confetti from 'canvas-confetti';

const SOCKET_SERVER_URL = 'http://localhost:3001';

interface Message {
  sender: string;
  text: string;
  timestamp: string;
}

interface AppNotification {
  title: string;
  message: string;
  type: string;
}

export default function App() {
  const [socket, setSocket] = useState<Socket | null>(null);
  const [userId] = useState<string>(`user_${Math.floor(Math.random() * 1000)}`); // Simulated logged-in user
  const [isPremium, setIsPremium] = useState<boolean>(false);
  const [activeRoom, setActiveRoom] = useState<string>('general');
  const [messageText, setMessageText] = useState<string>('');
  const [chatLog, setChatLog] = useState<Message[]>([]);
  const [notification, setNotification] = useState<AppNotification | null>(null);

  const messagesEndRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    // 1. Establish Socket Connection
    const newSocket = io(SOCKET_SERVER_URL);
    setSocket(newSocket);

    // Authenticate user to receive private system notifications
    newSocket.emit('auth', userId);
    newSocket.emit('join_room', activeRoom);

    // 2. Request Notification Permissions
    if (Notification.permission === 'default') {
      Notification.requestPermission();
    }

    // Check url search parameters to see if redirecting from a successful payment
    const urlParams = new URLSearchParams(window.location.search);
    if (urlParams.get('payment') === 'success') {
      setIsPremium(true);
      confetti({ particleCount: 100, spread: 70, origin: { y: 0.6 } });
    }

    return () => {
      newSocket.disconnect();
    };
  }, []);

  // Listen for socket events
  useEffect(() => {
    if (!socket) return;

    // Listen for incoming messages
    socket.on('receive_message', (message: Message) => {
      setChatLog((prev) => [...prev, message]);
    });

    // Listen for real-time notifications (In-app and System Level)
    socket.on('notification', (data: AppNotification) => {
      setNotification(data);

      // Native system-level notification if window is out of focus
      if (Notification.permission === 'granted' && document.hidden) {
        new Notification(data.title, { body: data.message });
      }

      // Auto-hide in-app notification toast after 4 seconds
      setTimeout(() => setNotification(null), 4000);
    });

    // Listen for database updates via webhook trigger
    socket.on('user_status_updated', (status: { isPremium: boolean }) => {
      setIsPremium(status.isPremium);
    });

    return () => {
      socket.off('receive_message');
      socket.off('notification');
      socket.off('user_status_updated');
    };
  }, [socket]);

  // Handle Room switching
  const handleRoomChange = (room: string) => {
    if (room === 'vip-lounge' && !isPremium) {
      alert("⚠️ Access Denied: You must upgrade to Premium to join the VIP Lounge!");
      return;
    }
    setChatLog([]);
    socket?.emit('join_room', room);
    setActiveRoom(room);
  };

  // Send message
  const handleSendMessage = (e: React.FormEvent) => {
    e.preventDefault();
    if (!messageText.trim() || !socket) return;

    socket.emit('send_message', {
      room: activeRoom,
      sender: userId,
      text: messageText,
      isPremiumRoom: activeRoom === 'vip-lounge'
    });

    setMessageText('');
  };

  // In-App Monetization checkout handler
  const handleUpgrade = async () => {
    try {
      const response = await fetch(`${SOCKET_SERVER_URL}/api/checkout`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ userId }),
      });
      const data = await response.json();
      if (data.url) {
        window.location.href = data.url; // Redirect client to secure Stripe checkout
      }
    } catch (error) {
      console.error('Checkout creation error:', error);
    }
  };

  // Scroll to bottom of message panel
  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [chatLog]);

  return (
    <div className="flex h-screen bg-gray-950 text-gray-100 font-sans">
      {/* 🔔 In-App Toast Notification Banner */}
      {notification && (
        <div className="fixed top-4 right-4 bg-indigo-600 border border-indigo-400 text-white px-4 py-3 rounded-lg shadow-2xl flex items-center gap-3 z-50 animate-bounce duration-300">
          <Bell className="animate-swing" />
          <div>
            <h4 className="font-bold text-sm">{notification.title}</h4>
            <p className="text-xs text-indigo-200">{notification.message}</p>
          </div>
        </div>
      )}

      {/* Sidebar Navigation */}
      <div className="w-64 bg-gray-900 border-r border-gray-800 flex flex-col p-4 justify-between">
        <div>
          <div className="flex items-center gap-2 mb-8">
            <MessageSquare className="w-8 h-8 text-indigo-500" />
            <h1 className="text-xl font-bold tracking-wider">CHATHOUSE</h1>
          </div>

          <div className="space-y-4">
            <h2 className="text-xs font-semibold uppercase text-gray-400 tracking-widest">Channels</h2>
            <button
              onClick={() => handleRoomChange('general')}
              className={`w-full flex items-center justify-between p-3 rounded-lg text-sm font-medium transition ${
                activeRoom === 'general' ? 'bg-indigo-600 text-white' : 'hover:bg-gray-800'
              }`}
            >
              # general
            </button>
            <button
              onClick={() => handleRoomChange('vip-lounge')}
              className={`w-full flex items-center justify-between p-3 rounded-lg text-sm font-medium transition ${
                activeRoom === 'vip-lounge' ? 'bg-amber-600 text-white' : 'hover:bg-gray-800'
              }`}
            >
              <span className="flex items-center gap-1.5">
                👑 vip-lounge
              </span>
              {!isPremium && <ShieldAlert className="w-4 h-4 text-amber-500" />}
            </button>
          </div>
        </div>

        {/* User Identity and Premium Monetization CTA */}
        <div className="bg-gray-800 p-4 rounded-xl border border-gray-700 text-center">
          <div className="text-sm font-semibold mb-1 text-gray-300">{userId}</div>
          <div className="flex justify-center mb-3">
            {isPremium ? (
              <span className="text-xs bg-amber-500/20 text-amber-400 px-2 py-1 rounded-full font-bold flex items-center gap-1">
                <Sparkles className="w-3.5 h-3.5" /> Premium User
              </span>
            ) : (
              <span className="text-xs bg-gray-700 text-gray-400 px-2 py-1 rounded-full font-bold">Standard Tier</span>
            )}
          </div>

          {!isPremium && (
            <button
              onClick={handleUpgrade}
              className="w-full bg-gradient-to-r from-amber-500 to-yellow-400 hover:from-amber-600 hover:to-yellow-500 text-gray-950 font-bold py-2 rounded-lg text-xs transition duration-200"
            >
              Upgrade to Premium ($9.99)
            </button>
          )}
        </div>
      </div>

      {/* Main Chat Panel */}
      <div className="flex-1 flex flex-col justify-between">
        {/* Header */}
        <div className="bg-gray-900/50 backdrop-blur-md px-6 py-4 border-b border-gray-800 flex items-center justify-between">
          <h2 className="text-lg font-semibold uppercase tracking-wider">#{activeRoom}</h2>
          <span className="text-xs text-gray-500">Live Socket Connection: Connected</span>
        </div>

        {/* Message Log */}
        <div className="flex-1 overflow-y-auto p-6 space-y-4">
          {chatLog.length === 0 ? (
            <div className="text-center text-gray-600 pt-20">
              <MessageSquare className="w-12 h-12 mx-auto mb-2 opacity-25" />
              <p>No messages yet in #{activeRoom}. Start the conversation!</p>
            </div>
          ) : (
            chatLog.map((msg, index) => (
              <div
                key={index}
                className={`max-w-[70%] p-3.5 rounded-2xl ${
                  msg.sender === userId
                    ? 'ml-auto bg-indigo-600 text-white rounded-br-none'
                    : 'bg-gray-800 text-gray-200 rounded-bl-none border border-gray-750'
                }`}
              >
                <div className="text-xs text-indigo-200 font-bold mb-1">{msg.sender}</div>
                <div className="text-sm">{msg.text}</div>
                <div className="text-[10px] text-right mt-1 opacity-50">{msg.timestamp}</div>
              </div>
            ))
          )}
          <div ref={messagesEndRef} />
        </div>

        {/* Messaging Input Tray */}
        <form onSubmit={handleSendMessage} className="p-4 bg-gray-900 border-t border-gray-850 flex gap-4">
          <input
            type="text"
            value={messageText}
            onChange={(e) => setMessageText(e.target.value)}
            placeholder={`Message #${activeRoom}...`}
            className="flex-1 bg-gray-950 border border-gray-800 focus:border-indigo-500 rounded-xl px-4 py-3 outline-none text-sm transition"
          />
          <button
            type="submit"
            className="bg-indigo-600 hover:bg-indigo-500 text-white px-5 py-3 rounded-xl flex items-center justify-center transition"
          >
            <Send className="w-5 h-5" />
          </button>
        </form>
      </div>
    </div>
  );
}
```

