### 1. The Backend Implementation (`backend/server.ts`)

This server manages active socket connections, processes messages, and handles a receipt verification endpoint simulating Google Play/App Store or Stripe webhooks.

```typescript
import express from 'express';
import { createServer } from 'http';
import { Server, Socket } from 'socket.io';
import cors from 'cors';

const app = express();
app.use(cors());
app.use(express.json());

const httpServer = createServer(app);
const io = new Server(httpServer, {
  cors: { origin: "*" }
});

// Mock Database
interface User {
  id: string;
  username: string;
  isPremium: boolean;
  messageCount: number;
}

const usersDb: Record<string, User> = {};
// Store socket connections to push real-time monetization updates
const activeSockets = new Map<string, string>(); // userId -> socketId

// 1. REAL-TIME CHAT & NOTIFICATIONS (Socket.io)
io.on('connection', (socket: Socket) => {
  console.log(`User connected: ${socket.id}`);

  // Register User Session
  socket.on('register_user', ({ userId, username }) => {
    activeSockets.set(userId, socket.id);
    if (!usersDb[userId]) {
      usersDb[userId] = { id: userId, username, isPremium: false, messageCount: 0 };
    }
    // Sync current state to user
    socket.emit('user_state_updated', usersDb[userId]);
  });

  // Handle incoming messages
  socket.on('send_message', (data: { userId: string; text: string }) => {
    const user = usersDb[data.userId];
    if (!user) return;

    // MONETIZATION GATE: Limit non-premium users to 3 messages
    if (!user.isPremium && user.messageCount >= 3) {
      socket.emit('error_notification', {
        type: 'LIMIT_REACHED',
        message: 'You have reached the free limit. Please upgrade to Premium for unlimited messaging!'
      });
      return;
    }

    // Increment message counter for free tier analytics
    user.messageCount += 1;
    socket.emit('user_state_updated', user);

    // Broadcast message to everyone with a timestamp
    io.emit('receive_message', {
      id: Math.random().toString(36).substr(2, 9),
      username: user.username,
      text: data.text,
      timestamp: new Date().toLocaleTimeString()
    });
  });

  socket.on('disconnect', () => {
    // Clean up connections
    for (const [userId, socketId] of activeSockets.entries()) {
      if (socketId === socket.id) {
        activeSockets.delete(userId);
        break;
      }
    }
  });
});

// 2. MONETIZATION ENDPOINT (Receipt Validation / Webhook Simulation)
// In production, this verifies Apple StoreKit, Google Play Billing, or Stripe receipts.
app.post('/api/verify-purchase', (req, res) => {
  const { userId, receiptToken } = req.body;

  if (!userId || !receiptToken) {
    return res.status(400).json({ success: false, error: 'Missing payment metadata' });
  }

  // Simulate verification with external App Store/Google Play API
  if (receiptToken === 'VALID_MOCK_RECEIPT') {
    if (usersDb[userId]) {
      usersDb[userId].isPremium = true;

      // REAL-TIME NOTIFICATION: Push premium status instantly to the active client
      const socketId = activeSockets.get(userId);
      if (socketId) {
        io.to(socketId).emit('user_state_updated', usersDb[userId]);
        io.to(socketId).emit('premium_unlocked', { 
          message: 'Thank you! Your Premium lifetime access is now active.' 
        });
      }

      return res.status(200).json({ success: true, user: usersDb[userId] });
    }
    return res.status(404).json({ success: false, error: 'User not found' });
  }

  return res.status(400).json({ success: false, error: 'Invalid Payment Receipt Token' });
});

const PORT = 4000;
httpServer.listen(PORT, () => {
  console.log(`Messaging Backend running on http://localhost:${PORT}`);
});
```

