#### `server.ts`
This file runs our HTTP server, handles WebSocket connections for instant messaging, and exposes an endpoint for validating In-App Purchases (IAP).

```typescript
import express from 'express';
import http from 'http';
import { WebSocket, WebSocketServer } from 'ws';
import cors from 'cors';
import bodyParser from 'body-parser';

const app = express();
app.use(cors());
app.use(bodyParser.json());

const server = http.createServer(app);
const wss = new WebSocketServer({ server });

// Database simulation
interface User {
  id: string;
  username: string;
  isPremium: boolean;
  fcmToken?: string; // For push notifications
}

const users: Record<string, User> = {
  "user_1": { id: "user_1", username: "Alice", isPremium: false, fcmToken: "mock_token_alice" },
  "user_2": { id: "user_2", username: "Bob", isPremium: true, fcmToken: "mock_token_bob" },
};

// Keep track of active WebSocket connections
const activeConnections = new Map<string, WebSocket>();

// ==========================================
// 1. REAL-TIME CHAT (WEBSOCKETS) & NOTIFICATIONS
// ==========================================

wss.on('connection', (ws: WebSocket) => {
  let authenticatedUserId: string | null = null;

  ws.on('message', (messageBuffer: string) => {
    const data = JSON.parse(messageBuffer.toString());

    switch (data.type) {
      case 'auth':
        // Authenticate connection
        authenticatedUserId = data.userId;
        if (authenticatedUserId) {
          activeConnections.set(authenticatedUserId, ws);
          console.log(`User ${authenticatedUserId} connected via WebSocket.`);
        }
        break;

      case 'message':
        const { senderId, recipientId, text } = data.payload;

        // Enforce Monetization Rule: Non-premium users can't send messages longer than 50 characters
        const sender = users[senderId];
        if (!sender.isPremium && text.length > 50) {
          ws.send(JSON.stringify({
            type: 'error',
            payload: { message: 'Message too long! Upgrade to Premium for unlimited length.' }
          }));
          return;
        }

        // Send message to recipient if online
        const recipientSocket = activeConnections.get(recipientId);
        const payloadToSend = { senderId, text, timestamp: new Date().toISOString() };

        if (recipientSocket && recipientSocket.readyState === WebSocket.OPEN) {
          recipientSocket.send(JSON.stringify({ type: 'message', payload: payloadToSend }));
        } else {
          // If recipient is offline, trigger a push notification
          triggerPushNotification(recipientId, sender.username, text);
        }
        break;
    }
  });

  ws.on('close', () => {
    if (authenticatedUserId) {
      activeConnections.delete(authenticatedUserId);
      console.log(`User ${authenticatedUserId} disconnected.`);
    }
  });
});

// Mock Push Notification Engine (FCM / APNs)
function triggerPushNotification(userId: string, senderName: string, text: string) {
  const user = users[userId];
  if (user && user.fcmToken) {
    console.log(`[PUSH NOTIFICATION SENT to ${user.fcmToken}]`);
    console.log(`Title: New message from ${senderName}`);
    console.log(`Body: ${text.substring(0, 30)}...`);
  }
}

// ==========================================
// 2. MONETIZATION (IN-APP PURCHASE VERIFICATION)
// ==========================================

// Validate Google Play or Apple App Store receipt
app.post('/api/verify-purchase', async (req, res) => {
  const { userId, receiptToken, platform } = req.body;

  if (!userId || !receiptToken || !platform) {
    return res.status(400).json({ success: false, error: 'Missing parameters' });
  }

  try {
    // In production, you would perform a network request to Apple or Google's validation servers,
    // or use a unified helper service library like RevenueCat.
    console.log(`Verifying ${platform} purchase for user: ${userId}`);
    const isReceiptValid = receiptToken === "valid_premium_receipt_token"; // Mock validation

    if (isReceiptValid) {
      // Upgrade user to premium status
      if (users[userId]) {
        users[userId].isPremium = true;
      }
      return res.status(200).json({ success: true, message: 'Account upgraded to Premium!' });
    } else {
      return res.status(400).json({ success: false, error: 'Invalid receipt token.' });
    }
  } catch (error) {
    return res.status(500).json({ success: false, error: 'Internal Server Error' });
  }
});

const PORT = process.env.PORT || 4000;
server.listen(PORT, () => {
  console.log(`Backend server running on port ${PORT}`);
});
```

