### Part 1: The Backend (Socket.io & Payments)

This backend runs on Node.js using **<language>TypeScript</language>**. It handles WebSockets for real-time delivery and includes a REST endpoint to simulate processing payments (monetization).

Initialize a Node project and install dependencies:
```bash
npm init -y
npm install express socket.io cors dotenv
npm install --save-dev typescript @types/node @types/express @types/cors
```

#### Code: `server.ts`
```typescript
import express from 'express';
import { createServer } from 'http';
import { Server, Socket } from 'socket.io';
import cors from 'cors';

const app = express();
app.use(cors());
app.use(express.json());

const httpServer = createServer(app);
const io = new Server(httpServer, {
  cors: { origin: '*' }
});

interface User {
  id: string;
  username: string;
  isPremium: boolean;
  pushToken?: string;
}

// In-memory databases for demo purposes
const users = new Map<string, User>();
const messageLimits = new Map<string, number>(); // Simple rate limiting for free users

// --- 1. MONETIZATION ENDPOINT (Mock Stripe Webhook / In-App Purchase Verification) ---
app.post('/api/monetize/verify-purchase', (req, res) => {
  const { userId, transactionId } = req.body;

  if (!userId || !transactionId) {
    return res.status(400).json({ success: false, error: 'Missing parameters' });
  }

  // Simulate verification with Apple/Google or Stripe
  console.log(`Verifying payment ${transactionId} for user ${userId}...`);

  const user = users.get(userId);
  if (user) {
    user.isPremium = true;
    users.set(userId, user);

    // Notify the client in real-time that their premium upgrade succeeded
    io.to(userId).emit('account_updated', { isPremium: true });

    return res.json({ success: true, isPremium: true });
  }

  return res.status(404).json({ success: false, error: 'User not found' });
});

// --- 2. REAL-TIME CHAT & NOTIFICATIONS CORE (Socket.io) ---
io.on('connection', (socket: Socket) => {
  console.log(`User connected: ${socket.id}`);

  // Register user info on connect
  socket.on('register_user', ({ username, pushToken }) => {
    users.set(socket.id, {
      id: socket.id,
      username,
      isPremium: false,
      pushToken
    });
    socket.join(socket.id); // Join private room for targeted events (like payment updates)
    messageLimits.set(socket.id, 0);
  });

  // Handle incoming real-time messages
  socket.on('send_message', (data: { text: string; recipientId?: string }) => {
    const sender = users.get(socket.id);
    if (!sender) return;

    // In-App Monetization Rule: Free tier users can only send 3 messages
    const currentMessageCount = messageLimits.get(socket.id) || 0;
    if (!sender.isPremium && currentMessageCount >= 3) {
      socket.emit('error_message', {
        type: 'PAYWALL_TRIGGERED',
        message: 'You have reached the limit of 3 free messages. Upgrade to Premium for unlimited chat!'
      });
      return;
    }

    // Increment message count for free tier
    if (!sender.isPremium) {
      messageLimits.set(socket.id, currentMessageCount + 1);
    }

    const payload = {
      senderId: socket.id,
      senderName: sender.username,
      text: data.text,
      timestamp: new Date().toISOString()
    };

    // Broadcast globally (or send to target recipient)
    if (data.recipientId) {
      io.to(data.recipientId).emit('receive_message', payload);
      // Trigger a real-time push notification simulation to the recipient
      const recipient = users.get(data.recipientId);
      if (recipient?.pushToken) {
        sendMockPushNotification(recipient.pushToken, sender.username, data.text);
      }
    } else {
      socket.broadcast.emit('receive_message', payload);
    }
  });

  socket.on('disconnect', () => {
    console.log(`User disconnected: ${socket.id}`);
    users.delete(socket.id);
    messageLimits.delete(socket.id);
  });
});

// Simulated Mobile Push Notification Sender (e.g., Firebase FCM / Expo Push Services)
function sendMockPushNotification(token: string, sender: string, body: string) {
  console.log(`[PUSH NOTIFICATION SENT] To: ${token} | Title: New Message from ${sender} | Body: "${body}"`);
}

const PORT = 4000;
httpServer.listen(PORT, () => {
  console.log(`Messaging backend running on http://localhost:${PORT}`);
});
```

