```typescript
import express from 'express';
import { createServer } from 'http';
import { Server, Socket } from 'socket.io';
import cors from 'cors';
import { PaymentService } from './services/payment';
import { NotificationService } from './services/notification';

const app = express();
app.use(cors());
app.use(express.json());

const httpServer = createServer(app);
const io = new Server(httpServer, {
  cors: { origin: '*' }
});

// Mock database
interface User {
  id: string;
  name: string;
  deviceToken?: string;
  isPremium: boolean;
  socketId?: string;
}

const usersDb: Record<string, User> = {
  'user_01': { id: 'user_01', name: 'Alice', isPremium: false, deviceToken: 'fcm_token_alice' },
  'user_02': { id: 'user_02', name: 'Bob', isPremium: true, deviceToken: 'fcm_token_bob' },
};

/**
 * 1. Monetization Endpoint: Verifies purchase receipt and unlocks premium features.
 */
app.post('/api/monetize/verify', async (req, res) => {
  const { userId, receiptData, platform } = req.body;

  const user = usersDb[userId];
  if (!user) {
    return res.status(404).json({ error: 'User not found' });
  }

  try {
    const verification = await PaymentService.verifyReceipt(userId, receiptData, platform);

    if (verification.success) {
      user.isPremium = true; // Upgrade user status
      return res.status(200).json({ success: true, message: 'Premium unlocked!', user });
    }

    return res.status(400).json({ success: false, error: 'Invalid Receipt' });
  } catch (error) {
    return res.status(500).json({ error: 'Internal verification failure' });
  }
});

/**
 * 2. Real-Time WebSocket Engine
 */
io.on('connection', (socket: Socket) => {
  console.log(`Socket connected: ${socket.id}`);

  // User authenticates/registers online presence
  socket.on('register_presence', (userId: string) => {
    if (usersDb[userId]) {
      usersDb[userId].socketId = socket.id;
      console.log(`User ${userId} is now online on socket ${socket.id}`);
    }
  });

  // Main messaging event
  socket.on('send_message', async (payload: {
    senderId: string;
    recipientId: string;
    text: string;
    isMedia: boolean; // Media (GIFs/Images) is a premium monetization feature
  }) => {
    const { senderId, recipientId, text, isMedia } = payload;
    const sender = usersDb[senderId];
    const recipient = usersDb[recipientId];

    if (!sender) return;

    // MONETIZATION CHECK: Gate media messaging behind a premium paywall
    if (isMedia && !sender.isPremium) {
      socket.emit('error_message', {
        code: 'PREMIUM_REQUIRED',
        message: 'Sending media files requires a Premium Subscription.'
      });
      return;
    }

    const messageEvent = {
      senderId,
      text,
      isMedia,
      timestamp: Date.now()
    };

    // If recipient is online, deliver instantly via WebSocket
    if (recipient && recipient.socketId) {
      io.to(recipient.socketId).emit('receive_message', messageEvent);
    } else if (recipient && recipient.deviceToken) {
      // REAL-TIME NOTIFICATION: If recipient is offline, trigger a push notification
      await NotificationService.sendPushNotification(
        recipient.deviceToken,
        `New Message from ${sender.name}`,
        isMedia ? '📷 Sent you a photo' : text,
        { senderId }
      );
    }
  });

  socket.on('disconnect', () => {
    // Find and remove socketId association upon disconnect
    for (const userId in usersDb) {
      if (usersDb[userId].socketId === socket.id) {
        usersDb[userId].socketId = undefined;
        console.log(`User ${userId} went offline`);
        break;
      }
    }
  });
});

const PORT = 3000;
httpServer.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
