io.on('connection', (socket: Socket) => {
  const userId = socket.handshake.query.userId as string;
  if (!userId || !users[userId]) {
    socket.disconnect();
    return;
  }

  // Update online status and map socket ID
  users[userId].socketId = socket.id;
  console.log(`User ${users[userId].username} connected online.`);

  socket.on('join_room', (roomId: string) => {
    socket.join(roomId);
    console.log(`User ${userId} joined room: ${roomId}`);
  });

  socket.on('send_message', async (data: { roomId: string; recipientId: string; text: string }) => {
    const { roomId, recipientId, text } = data;
    const sender = users[userId];

    const messagePayload = {
