  const { userId } = req.body;

  if (!users[userId]) {
    return res.status(404).json({ error: 'User not found' });
  }

  try {
    const session = await stripe.checkout.sessions.create({
      payment_method_types: ['card'],
      line_items: [
        {
          price_data: {
            currency: 'usd',
            product_data: {
              name: 'Premium Messaging Membership',
              description: 'Unlock unlimited messaging, media sharing, and custom profile badges!',
            },
            unit_amount: 499, // $4.99 USD
          },
          quantity: 1,
        },
      ],
      mode: 'payment',
      success_url: 'https://yourapp.com/success?session_id={CHECKOUT_SESSION_ID}',
      cancel_url: 'https://yourapp.com/cancel',
      client_reference_id: userId,
    });

    res.json({ checkoutUrl: session.url, sessionId: session.id });
  } catch (err: any) {
    res.status(500).json({ error: err.message });
  }
});

// Stripe Webhook Endpoint to handle asynchronous transaction completions
app.post('/webhook', express.raw({ type: 'application/json' }), (req: Request, res: Response): any => {
  const sig = req.headers['stripe-signature'];
  let event;

  try {
    event = stripe.webhooks.constructEvent(
      req.body,
      sig!,
      process.env.STRIPE_WEBHOOK_SECRET || 'whsec_mock'
    );
  } catch (err: any) {
    return res.status(400).send(`Webhook Error: ${err.message}`);
  }

  // Handle successful payments
  if (event.type === 'checkout.session.completed') {
    const session = event.data.object as Stripe.Checkout.Session;
    const userId = session.client_reference_id;

    if (userId && users[userId]) {
      users[userId].isPremium = true;
      console.log(`Payment confirmed. User ${users[userId].username} has upgraded to PREMIUM!`);

      // Send real-time notification via WebSocket alerting the user of their live status upgrade
      const userSocket = users[userId].socketId;
      if (userSocket) {
        io.to(userSocket).emit('account_upgrade', { isPremium: true });
      }
    }
  }

  res.json({ received: true });
});

const PORT = process.env.PORT || 4000;
httpServer.listen(PORT, () => {
