    socketConn.on('account_upgrade', (data: { isPremium: boolean }) => {
      setIsPremium(data.isPremium);
      Alert.alert('Congratulations!', 'Your account has been upgraded to Premium!');
    });

    setSocket(socketConn);

    // Setup Push Notifications (APNs / FCM) Mock
    // In production, obtain APNS/FCM device token here
    // messaging().getToken().then(token => sendTokenToServer(token));

    return () => {
      socketConn.disconnect();
    };
  }, []);

  const handleSendMessage = () => {
