### 1. Backend: `main.go` (<language>Go</language>)
This backend uses WebSockets to connect clients. It processes chat messages, enforces "Premium" features for paid users, and broadcasts real-time notifications.

```go
package main

import (
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"sync"

	"github.com/gorilla/websocket"
)

// Message represents the JSON structure of our chat/notification data
type Message struct {
	Type      string `json:"type"`       // "chat", "notification", "system"
	Sender    string `json:"sender"`     // Username
	Content   string `json:"content"`    // Message text
	IsPremium bool   `json:"isPremium"`  // Monetization status flag
}

// Client represents a connected user
type Client struct {
	conn      *websocket.Conn
	username  string
	isPremium bool
}

var (
	clients   = make(map[*Client]bool)
	clientsMu sync.Mutex
	upgrader  = websocket.Upgrader{
		CheckOrigin: func(r *http.Request) bool { return true }, // Allow all origins for demo
	}
)

func main() {
	// Serve static frontend files
	http.HandleFunc("/", func(w http.ResponseWriter, r *http.Request) {
		http.ServeFile(w, r, "index.html")
	})

	// WebSocket handler
	http.HandleFunc("/ws", handleConnections)

	// Monetization payment endpoint (Mocking an In-App Purchase Verification)
	http.HandleFunc("/api/pay", handlePayment)

	fmt.Println("Server started on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}

func handleConnections(w http.ResponseWriter, r *http.Request) {
	ws, err := upgrader.Upgrade(w, r, nil)
	if err != nil {
		log.Printf("error upgrading to websocket: %v", err)
		return
	}

	client := &Client{conn: ws, isPremium: false}

	clientsMu.Lock()
	clients[client] = true
	clientsMu.Unlock()

	defer func() {
		clientsMu.Lock()
		delete(clients, client)
		clientsMu.Unlock()
		ws.Close()
	}()

	for {
		var msg Message
		err := ws.ReadJSON(&msg)
		if err != nil {
			log.Printf("error reading JSON: %v", err)
			break
		}

		// Update the connection-level client state
		if client.username == "" {
			client.username = msg.Sender
		}

		// Feature Gate: Prevent non-premium users from sending premium content
		if msg.Type == "premium-sticker" && !client.isPremium {
			// Reject and send warning notification to the bad actor
			warning := Message{
				Type:    "notification",
				Sender:  "System Security",
				Content: "⚠️ Upgrade to Premium to send stickers!",
			}
			client.conn.WriteJSON(warning)
			continue
		}

		// Real-Time Push Notification logic: trigger notification if someone is @mentioned
		broadcast(msg)
	}
}

func broadcast(msg Message) {
	clientsMu.Lock()
	defer clientsMu.Unlock()

	for client := range clients {
		// Send regular messages to everyone
		err := client.conn.WriteJSON(msg)
		if err != nil {
			log.Printf("error writing to client: %v", err)
			client.conn.Close()
			delete(clients, client)
		}
	}
}

// Payment Endpoint simulating App Store/Stripe server-side verification
func handlePayment(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	var req struct {
		Username string `json:"username"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, err.Error(), http.StatusBadRequest)
		return
	}

	// Upgrade user to premium in active sessions
	clientsMu.Lock()
	found := false
	for client := range clients {
		if client.username == req.Username {
			client.isPremium = true
			found = true

			// Send real-time transactional push notification to client acknowledging receipt
			client.conn.WriteJSON(Message{
				Type:    "notification",
				Sender:  "Billing System",
				Content: "🎉 Thank you! Premium features have been unlocked instantly.",
			})
		}
	}
	clientsMu.Unlock()

	if !found {
		http.Error(w, "User session not found", http.StatusNotFound)
		return
	}

	// Broadcast success system-wide
	broadcast(Message{
		Type:    "system",
		Sender:  "System",
		Content: fmt.Sprintf("🌟 Everyone welcome %s to the Premium Tier!", req.Username),
	})

	w.WriteHeader(http.StatusOK)
	w.Write([]byte(`{"status": "success"}`))
}
