### Step 2: The Backend Server (`server.js`)

This server hosts the web app, handles WebSocket connections for real-time messaging, and provides a secure mock payment validation endpoint.

```javascript
const express = require('express');
const http = require('http');
const WebSocket = require('ws');
const path = require('path');

const app = express();
const server = http.createServer(app);
const wss = new WebSocket.Server({ server });

app.use(express.json());
app.use(express.static(path.join(__dirname, 'public')));

// Database mock
const users = {
    "user123": { username: "Alice", isPremium: false },
    "user456": { username: "Bob", isPremium: false }
};

// 1. MONETIZATION: Mock Payment Processing Endpoint
app.post('/api/pay', (req, res) => {
    const { userId, paymentMethodId } = req.body;

    if (!users[userId]) {
        return res.status(404).json({ error: "User not found" });
    }

    // Simulate payment authorization with a processor (e.g., Stripe)
    console.log(`Processing payment for ${users[userId].username} using ${paymentMethodId}...`);

    setTimeout(() => {
        // Upgrade user status to premium on success
        users[userId].isPremium = true;

        res.json({ 
            success: true, 
            message: "Payment successful! Premium features unlocked.",
            isPremium: true
        });

        // Notify the client via WS about their upgraded status
        broadcastToUser(userId, { type: 'SYSTEM_UPGRADE', isPremium: true });
    }, 1000); 
});

// 2. REAL-TIME: WebSocket connection handling
const activeConnections = new Map(); // Map userId -> ws connection

wss.on('connection', (ws, req) => {
    let currentUserId = null;

    ws.on('message', (messageStr) => {
        const data = JSON.parse(messageStr);

        if (data.type === 'auth') {
            currentUserId = data.userId;
            activeConnections.set(currentUserId, ws);
            console.log(`${users[currentUserId]?.username} connected.`);
            return;
        }

        if (data.type === 'message') {
            const sender = users[currentUserId];

            // Security check: Only premium users can send messages to the premium channel
            if (data.channel === 'premium' && !sender.isPremium) {
                ws.send(JSON.stringify({ type: 'error', message: 'You must upgrade to access the premium room.' }));
                return;
            }

            // Broadcast message to all connected clients
            const broadcastPayload = JSON.stringify({
                type: 'message',
                channel: data.channel,
                sender: sender.username,
                text: data.text,
                timestamp: new Date().toLocaleTimeString()
            });

            wss.clients.forEach(client => {
                if (client.readyState === WebSocket.OPEN) {
                    client.send(broadcastPayload);
                }
            });
        }
    });

    ws.on('close', () => {
        if (currentUserId) {
            activeConnections.delete(currentUserId);
            console.log(`${users[currentUserId]?.username} disconnected.`);
        }
    });
});

function broadcastToUser(userId, data) {
    const ws = activeConnections.get(userId);
    if (ws && ws.readyState === WebSocket.OPEN) {
        ws.send(JSON.stringify(data));
    }
}

server.listen(3000, () => {
    console.log('Server running on http://localhost:3000');
});
```

