```javascript
const express = require('express');
const http = require('http');
const { Server } = require('socket.io');
const path = require('path');

const app = express();
const server = http.createServer(app);
const io = new Server(server);

app.use(express.json());
app.use(express.static(path.join(__dirname)));

// In-memory Database
const users = {}; // Store user data: { socketId: { username, isPremium } }
const rooms = {
    general: [],
    vip: [] // Locked behind monetization
};

io.on('connection', (socket) => {
    console.log(`User connected: ${socket.id}`);

    // Register User
    socket.on('register', (username) => {
        users[socket.id] = { username, isPremium: false };
        socket.join('general');
        socket.emit('registered', users[socket.id]);

        // System message
        io.to('general').emit('message', {
            room: 'general',
            sender: 'System',
            text: `${username} joined the chat.`,
            timestamp: new Date().toLocaleTimeString()
        });
    });

    // Handle Join Room request
    socket.on('join-room', (room) => {
        const user = users[socket.id];
        if (!user) return;

        if (room === 'vip' && !user.isPremium) {
            socket.emit('error-msg', 'VIP room requires a Premium Subscription!');
            return;
        }

        // Leave previous rooms
        socket.rooms.forEach(r => {
            if (r !== socket.id) socket.leave(r);
        });

        socket.join(room);
        socket.emit('room-joined', room);
    });

    // Handle Chat Message
    socket.on('send-message', ({ room, text }) => {
        const user = users[socket.id];
        if (!user) return;

        // Security Check: Block non-premium users from posting to VIP
        if (room === 'vip' && !user.isPremium) return;

        const messageData = {
            room,
            sender: user.username,
            text,
            timestamp: new Date().toLocaleTimeString()
        };

        // Broadcast to everyone in that room
        io.to(room).emit('message', messageData);
    });

    // MONETIZATION: Simulate payment processing (Webhook / Stripe style)
    socket.on('process-payment', () => {
        const user = users[socket.id];
        if (!user) return;

        // Simulate credit card charge processing latency
        setTimeout(() => {
            user.isPremium = true;
            socket.emit('payment-success', { isPremium: true });

            // Notify system
            io.to('general').emit('message', {
                room: 'general',
                sender: 'System',
                text: `🎉 ${user.username} upgraded to PREMIUM!`,
                timestamp: new Date().toLocaleTimeString()
            });
        }, 1500); 
    });

    socket.on('disconnect', () => {
        delete users[socket.id];
        console.log(`User disconnected: ${socket.id}`);
    });
});

const PORT = 3000;
server.listen(PORT, () => console.log(`Server running on http://localhost:${PORT}`));
```

