### 2. The Backend (`server.js`)
This server handles Express routing, simulated payment processing (Stripe webhook simulation), and WebSockets for real-time messaging and notifications.

```javascript
import express from 'express';
import { createServer } from 'http';
import { Server } from 'socket.io';
import path from 'path';
import { fileURLToPath } from 'url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const app = express();
const httpServer = createServer(app);
const io = new Server(httpServer);

app.use(express.json());
app.use(express.static(path.join(__dirname, 'public')));

// In-Memory Database
const users = new Map(); // socketId -> { username, isPremium, messageCount }

io.on('connection', (socket) => {
  console.log(`User connected: ${socket.id}`);

  // Register User
  socket.on('register', (username) => {
    users.set(socket.id, {
      username,
      isPremium: false,
      messageCount: 0
    });
    // Broadcast join
    socket.broadcast.emit('system-notification', `${username} joined the chat!`);
    socket.emit('user-status', users.get(socket.id));
  });

  // Handle Real-Time Messages
  socket.on('send-message', (messageText) => {
    const user = users.get(socket.id);
    if (!user) return;

    // Monetization Check: Free tier limit
    if (!user.isPremium && user.messageCount >= 3) {
      socket.emit('payment-required', 'You have reached your 3-message free limit! Please upgrade to Premium.');
      return;
    }

    user.messageCount++;
    users.set(socket.id, user);

    // Broadcast message to all other users
    socket.broadcast.emit('receive-message', {
      sender: user.username,
      text: messageText,
      timestamp: new Date().toLocaleTimeString()
    });

    // Send confirmation back to sender (including updated count)
    socket.emit('message-sent', {
      text: messageText,
      messageCount: user.messageCount,
      isPremium: user.isPremium
    });
  });

  // Handle Disconnect
  socket.on('disconnect', () => {
    const user = users.get(socket.id);
    if (user) {
      socket.broadcast.emit('system-notification', `${user.username} left the chat.`);
      users.delete(socket.id);
    }
  });
});

// Monetization Endpoint: Simulates dynamic checkout / Stripe Webhook
app.post('/api/checkout', (express.json()), (req, res) => {
  const { socketId } = req.body;

  if (!users.has(socketId)) {
    return res.status(400).json({ error: 'User session not found.' });
  }

  // Simulate Stripe processing payment delay...
  setTimeout(() => {
    const user = users.get(socketId);
    if (user) {
      user.isPremium = true;
      users.set(socketId, user);

      // Real-Time Notification: Push "premium unlocked" event to user via websocket
      io.to(socketId).emit('payment-success', {
        message: 'Payment Successful! You now have unlimited messaging.',
        userStatus: user
      });
    }
  }, 1500); // 1.5s simulated checkout validation

  res.status(200).json({ status: 'initiated' });
});

const PORT = 3000;
httpServer.listen(PORT, () => {
  console.log(`Server running at http://localhost:${PORT}`);
});
```

