      const badge = document.getElementById('badge-status');
      if (myUserStatus.isPremium) {
        badge.innerText = 'Premium Member';
        badge.className = 'px-2 py-0.5 text-xs rounded-full bg-emerald-500 text-white font-bold';
      } else {
        badge.innerText = `Free Tier (${myUserStatus.messageCount}/3 messages)`;
        badge.className = 'px-2 py-0.5 text-xs rounded-full bg-amber-500 text-slate-900 font-bold';
      }
    }

    function appendBubble(msg, isMe) {
      const container = document.getElementById('message-container');
      const bubble = `
        <div class="flex flex-col ${isMe ? 'items-end' : 'items-start'}">
          <span class="text-xs text-slate-400 mb-1">${msg.sender} <span class="opacity-50">• ${msg.timestamp}</span></span>
          <div class="max-w-xs md:max-w-md p-3.5 rounded-2xl ${isMe ? 'bg-blue-600 text-white rounded-br-none' : 'bg-slate-700 text-slate-100 rounded-bl-none'}">
            <p class="text-sm">${msg.text}</p>
          </div>
        </div>
      `;
      container.innerHTML += bubble;
      container.scrollTop = container.scrollHeight;
    }
  </script>
