### 1. Backend Server (`server.ts`)
Create a file named `server.ts`. This handles HTTP requests (like payment processing) and persistent WebSocket connections.

```typescript
import express from 'express';
import { createServer } from 'http';
import { Server } from 'socket.io';
import cors from 'cors';

const app = express();
app.use(cors());
app.use(express.json());

const httpServer = createServer(app);
const io = new Server(httpServer, {
  cors: { origin: "*" }
});

// Mock database to track user subscription statuses
const db = {
  users: {} as Record<string, { isPremium: boolean; username: string }>
};

// 1. IN-APP MONETIZATION: Payment Verification Endpoint
app.post('/api/verify-payment', (req, res) => {
  const { userId, transactionId } = req.body;

  if (!userId || !transactionId) {
    return res.status(400).json({ success: false, error: "Missing payload." });
  }

  // Simulate verification with Apple/Google billing servers
  console.log(`Verifying transaction ${transactionId} for user ${userId}...`);

  // Update local DB status to Premium
  db.users[userId] = { ...db.users[userId], isPremium: true };

  // Notify active socket connection of the status upgrade
  io.to(userId).emit('billing_updated', { isPremium: true });

  return res.json({ success: true, message: "Subscription activated!" });
});

// 2. REAL-TIME MESSAGING & NOTIFICATIONS: WebSocket handler
io.on('connection', (socket) => {
  const userId = socket.handshake.query.userId as string;
  const username = socket.handshake.query.username as string || 'Anonymous';

  if (!userId) return socket.disconnect();

  // Initialize user in mock database
  if (!db.users[userId]) {
    db.users[userId] = { isPremium: false, username };
  }

  // Join a private room named after the userId for direct billing/system alerts
  socket.join(userId);
  // Join the global public chat room
  socket.join('public_room');

  console.log(`User connected: ${username} (${userId}) - Premium: ${db.users[userId].isPremium}`);

  // Handle incoming messages
  socket.on('send_message', (data: { text: string }) => {
    const user = db.users[userId];

    // Monetization feature-gate: non-premium users have character limits
    const characterLimit = user.isPremium ? 500 : 30;
    const truncatedText = data.text.substring(0, characterLimit);

    const messagePayload = {
      id: Math.random().toString(36).substring(7),
      senderId: userId,
      senderName: user.username,
      text: truncatedText,
      timestamp: new Date().toLocaleTimeString(),
      wasTruncated: data.text.length > characterLimit
    };

    // Broadcast the message to all users in the chat room
    io.to('public_room').emit('new_message', messagePayload);
  });

  socket.on('disconnect', () => {
    console.log(`User disconnected: ${userId}`);
  });
});

const PORT = 3000;
httpServer.listen(PORT, () => {
  console.log(`Real-time server running at http://localhost:${PORT}`);
});
```

