        function pushNewDataPoint(value) {
            const timeLabel = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' });

            state.dataBuffer.push(value);
            if (state.dataBuffer.length > state.maxDataPoints) {
                state.dataBuffer.shift();
            }

            // Update Chart.js data
            realtimeChart.data.labels.push(timeLabel);
            realtimeChart.data.datasets[0].data.push(value);

            if (realtimeChart.data.labels.length > state.maxDataPoints) {
                realtimeChart.data.labels.shift();
                realtimeChart.data.datasets[0].data.shift();
            }

            realtimeChart.update('none'); // Update without full animation for performance

            updateStats();
            checkThreshold(value);
        }

        // Calculate Average, Min, Max stats
        function updateStats() {
            const current = state.dataBuffer[state.dataBuffer.length - 1] || 0;
            const max = Math.max(...state.dataBuffer);
            const sum = state.dataBuffer.reduce((a, b) => a + b, 0);
            const avg = Math.round(sum / state.dataBuffer.length) || 0;

            document.getElementById('statCurrent').innerText = `${current}%`;
            document.getElementById('statAvg').innerText = `${avg}%`;
            document.getElementById('statMax').innerText = `${max}%`;
        }

        // Check value against alert threshold
        function checkThreshold(value) {
            if (value >= state.alertThreshold) {
                logAlert(`WARNING: Metric exceeded threshold of ${state.alertThreshold}% (Current: ${value}%)`, 'alert');

                // Temporarily flash stat card
                const currentStatCard = document.getElementById('statCurrent').parentElement;
                currentStatCard.classList.add('bg-rose-950/40', 'border-rose-500');
                setTimeout(() => {
                    currentStatCard.classList.remove('bg-rose-950/40', 'border-rose-500');
                }, 800);
            }
        }

        // Manage Simulation Interval loop
        function startSimulation() {
            if (state.intervalId) clearInterval(state.intervalId);
            state.intervalId = setInterval(() => {
                if (state.isRunning) generateDataPoint();
            }, state.updateInterval);
        }

        // --- 5. Interactive Event Listeners & Form Handling ---

        // Real-time slider feedback
        updateIntervalInput.addEventListener('input', (e) => {
            intervalValDisplay.innerText = e.target.value;
        });

        // Form 1: Dashboard Settings Form Submission with validation
        settingsForm.addEventListener('submit', (e) => {
            e.preventDefault(); // Prevent page reload

            const newInterval = parseInt(updateIntervalInput.value);
            const newThreshold = parseInt(alertThresholdInput.value);

            // Validation logic
            if (isNaN(newThreshold) || newThreshold < 1 || newThreshold > 100) {
                thresholdError.classList.remove('hidden');
                return;
            }
            thresholdError.classList.add('hidden');

            // Apply validated settings
            state.updateInterval = newInterval;
            state.alertThreshold = newThreshold;

            logAlert(`Settings updated: Interval = ${newInterval}ms, Threshold = ${newThreshold}%`, 'success');

            // Restart stream with new interval rate
            if (state.isRunning) {
                startSimulation();
            }
        });

        // Form 2: Inject Custom Data Point
        injectionForm.addEventListener('submit', (e) => {
            e.preventDefault();

            const customValue = parseInt(injectValueInput.value);

            // Input validation
            if (!isNaN(customValue) && customValue >= 0 && customValue <= 100) {
                logAlert(`User injected value: ${customValue}%`, 'success');
                pushNewDataPoint(customValue);
                injectValueInput.value = ''; // Reset form input
            }
        });

        // Pause/Play state switcher
        pauseBtn.addEventListener('click', () => {
            state.isRunning = !state.isRunning;
            if (state.isRunning) {
                pauseBtn.innerText = "Pause";
                pauseBtn.className = "bg-slate-700 hover:bg-slate-600 text-white font-bold py-2 px-4 rounded-lg transition text-sm";
                streamStatus.innerHTML = `
                    <span class="relative flex h-3 w-3">
                        <span class="animate-ping absolute inline-flex h-full w-full rounded-full bg-teal-400 opacity-75"></span>
                        <span class="relative inline-flex rounded-full h-3 w-3 bg-teal-500"></span>
                    </span>
                    <span class="text-xs font-semibold text-slate-300 uppercase tracking-wider" id="streamStatus">Receiving Data</span>
                `;
                logAlert("Telemetry stream resumed.");
                startSimulation();
            } else {
                pauseBtn.innerText = "Resume";
                pauseBtn.className = "bg-teal-500 hover:bg-teal-600 text-slate-950 font-bold py-2 px-4 rounded-lg transition text-sm";
                streamStatus.innerHTML = `
                    <span class="relative flex h-3 w-3">
                        <span class="relative inline-flex rounded-full h-3 w-3 bg-amber-500"></span>
                    </span>
                    <span class="text-xs font-semibold text-slate-300 uppercase tracking-wider text-amber-500" id="streamStatus">Paused</span>
                `;
                logAlert("Telemetry stream paused by user.");
                clearInterval(state.intervalId);
            }
        });

        // --- 6. Initialization on Load ---
        startSimulation();
    </script>
</body>
</html>
```

### Features Built into This Code:
1. **Interactive Charting**: Utilizes `Chart.js` with curve smoothing, custom linear gradients, and sliding timelines (retaining the last 20 frames of activity) to prevent browser layout thrashing.
2. **Settings State Form Management**: Enables dynamically speeding up or slowing down the frequency of the simulation loop, adjusting threshold levels on the fly, and handling validation.
3. **Manual Injector Form**: Demonstrates safe, user-driven data pipeline handling by taking input, running range validation, and appending it instantly to the data array.
4. **Active Threshold Alarm Engine**: Generates customized flash visual flags and prints warning entries in the **Alert Feed** logs if a telemetry point breaks user-defined safety bounds.

