### 1. The Backend: `server.js`
This Node.js script serves the web page, generates synthetic telemetry data, accepts form updates over WebSockets, and broadcasts parameters to all connected clients.

```javascript
const express = require('express');
const http = require('http');
const WebSocket = require('ws');
const path = require('path');

const app = express();
const server = http.createServer(app);
const wss = new WebSocket.Server({ server });

// Serve static HTML page
app.get('/', (req, res) => {
    res.sendFile(path.join(__dirname, 'index.html'));
});

// App State
let updateInterval = 1000; // in milliseconds
let baselineValue = 50;    // Baseline for telemetry simulation
let intervalId = null;

// Generate and stream telemetry data
function startTelemetryStream() {
    if (intervalId) clearInterval(intervalId);

    intervalId = setInterval(() => {
        // Create a random walk centered around baselineValue
        const variance = (Math.random() - 0.5) * 10;
        const liveValue = Math.max(0, Math.min(100, baselineValue + variance));

        const payload = JSON.stringify({
            type: 'DATA_STREAM',
            timestamp: new Date().toLocaleTimeString(),
            value: parseFloat(liveValue.toFixed(2))
        });

        // Broadcast to all connected clients
        wss.clients.forEach(client => {
            if (client.readyState === WebSocket.OPEN) {
                client.send(payload);
            }
        });
    }, updateInterval);
}

// WebSocket Connection Handler
wss.on('connection', (ws) => {
    console.log('Client connected');

    // Send initial configuration to client on connection
    ws.send(JSON.stringify({
        type: 'CONFIG_INIT',
        interval: updateInterval,
        baseline: baselineValue
    }));

    // Handle form submissions received over WebSocket
    ws.on('message', (message) => {
        try {
            const data = JSON.parse(message);

            if (data.type === 'UPDATE_SETTINGS') {
                // Form validation on server-side
                const newInterval = parseInt(data.interval);
                const newBaseline = parseFloat(data.baseline);

                if (newInterval >= 100 && newInterval <= 5000 && newBaseline >= 0 && newBaseline <= 100) {
                    updateInterval = newInterval;
                    baselineValue = newBaseline;

                    // Restart stream with new interval
                    startTelemetryStream();

                    // Broadcast configuration changes to all clients
                    wss.clients.forEach(client => {
                        if (client.readyState === WebSocket.OPEN) {
                            client.send(JSON.stringify({
                                type: 'CONFIG_UPDATED',
                                interval: updateInterval,
                                baseline: baselineValue,
                                user: data.user || 'System'
                            }));
                        }
                    });
                }
            }
        } catch (err) {
            console.error('Error parsing client message:', err);
        }
    });

    ws.on('close', () => console.log('Client disconnected'));
});

// Start telemetry simulation
startTelemetryStream();

const PORT = 3000;
server.listen(PORT, () => {
    console.log(`Dashboard running at http://localhost:${PORT}`);
});
```

