    <script>
        // Setup WebSocket
        const socket = new WebSocket(`ws://${window.location.host}`);
        const statusEl = document.getElementById('connectionStatus');
        const liveMetricEl = document.getElementById('liveMetric');
        const logEl = document.getElementById('log');

        // Form elements
        const form = document.getElementById('settingsForm');
        const userInput = document.getElementById('user');
        const baselineInput = document.getElementById('baseline');
        const intervalInput = document.getElementById('interval');

        // Chart Setup
        const ctx = document.getElementById('realtimeChart').getContext('2d');
        const maxDataPoints = 15;
        const chart = new Chart(ctx, {
            type: 'line',
            data: {
                labels: [],
                datasets: [{
                    label: 'Live Telemetry Signal',
                    data: [],
                    borderColor: '#10b981', // Tailwind Emerald-500
                    backgroundColor: 'rgba(16, 185, 129, 0.1)',
                    borderWidth: 2,
                    fill: true,
                    tension: 0.3
                }]
            },
            options: {
                responsive: true,
                maintainAspectRatio: false,
                scales: {
                    x: { grid: { color: '#374151' }, ticks: { color: '#9ca3af' } },
                    y: { min: 0, max: 100, grid: { color: '#374151' }, ticks: { color: '#9ca3af' } }
                },
                plugins: { legend: { display: false } }
            }
        });

        // WebSocket Event Handlers
        socket.onopen = () => {
            statusEl.innerHTML = '<span class="h-3 w-3 rounded-full bg-emerald-500 animate-pulse"></span> Connected';
            statusEl.className = "flex items-center gap-2 text-emerald-500 font-semibold";
            logActivity('System', 'Connected to data stream server.');
        };

        socket.onclose = () => {
            statusEl.innerHTML = '<span class="h-3 w-3 rounded-full bg-red-500"></span> Offline';
            statusEl.className = "flex items-center gap-2 text-red-500 font-semibold";
            logActivity('System', 'Disconnected from server.', 'text-red-400');
        };

        socket.onmessage = (event) => {
            const data = JSON.parse(event.data);

            switch(data.type) {
                case 'CONFIG_INIT':
                    // Populate Form with initial state from Server
                    baselineInput.value = data.baseline;
                    intervalInput.value = data.interval;
                    logActivity('System', `Synchronized parameters: baseline (${data.baseline}), interval (${data.interval}ms).`);
                    break;

                case 'DATA_STREAM':
                    // Handle incoming stream and update Chart
                    liveMetricEl.innerText = data.value;

                    // Add new point and shift older points
                    chart.data.labels.push(data.timestamp);
                    chart.data.datasets[0].data.push(data.value);

                    if (chart.data.labels.length > maxDataPoints) {
                        chart.data.labels.shift();
                        chart.data.datasets[0].data.shift();
                    }
                    chart.update('none'); // Update without full animation lag
                    break;

                case 'CONFIG_UPDATED':
                    // Triggered when an operator updates parameters
                    baselineInput.value = data.baseline;
                    intervalInput.value = data.interval;
                    logActivity(data.user, `Changed baseline to ${data.baseline} & update speed to ${data.interval}ms`, 'text-amber-400');
                    break;
            }
        };

        // Form Submission (Send UI interaction to server via WebSocket)
        form.addEventListener('submit', (e) => {
            e.preventDefault();

            const payload = {
                type: 'UPDATE_SETTINGS',
                user: userInput.value,
                baseline: baselineInput.value,
                interval: intervalInput.value
            };

            socket.send(JSON.stringify(payload));
        });

        // Helper: Activity Logger
        function logActivity(user, message, colorClass = 'text-gray-400') {
            const timestamp = new Date().toLocaleTimeString();
            const logEntry = document.createElement('div');
            logEntry.className = colorClass;
            logEntry.innerHTML = `[${timestamp}] <strong>${user}</strong>: ${message}`;
            logEl.prepend(logEntry);
        }
    </script>
</body>
</html>
