        function generateSensorData() {
            // Generate normal fluctuation centering around 60°C
            const variance = (Math.random() - 0.5) * 8;
            const currentTemp = parseFloat((state.dataHistory[state.dataHistory.length - 1] + variance).toFixed(1));

            // Constrain values within chart limits
            return Math.min(Math.max(currentTemp, 25), 115);
        }

