        form.addEventListener('submit', (e) => {
            e.preventDefault();

            // Read and apply config values from form inputs
            const rawThreshold = parseInt(thresholdInput.value);
            const rawInterval = parseInt(document.getElementById('intervalInput').value);

            state.threshold = rawThreshold;
            state.intervalTime = rawInterval;

            // Update layout view values
            document.getElementById('threshold-val').innerText = rawThreshold;
            document.getElementById('interval-display').innerText = `${(rawInterval / 1000).toFixed(1)}s`;

            addLog(`Configuration successfully saved. Threshold: ${rawThreshold}°C, Interval: ${rawInterval}ms`, 'success');

            // Restart continuous streams with fresh timings
            startStream();
