                addLog(`Manually injecting custom data spike of ${rawValue}°C...`, 'info');
                onNewDataReceived(rawValue);
                customDataInput.value = ''; // Clean input field
            } else {
                alert('Please enter a valid numeric value.');
            }
        });

        // --- 6. Initial Kickoff ---
        addLog("System initialized. Welcome to the console panel.", "success");
        startStream();
    </script>
</body>
