### 1. The Backend: `server.js`
This server handles two things:
1. Serving the static HTML frontend.
2. A **WebSocket server** to stream simulated real-time data.
3. An **API Express POST endpoint** to handle form submissions (adjusting dashboard settings globally in real-time).

```javascript
const express = require('express');
const http = require('http');
const WebSocket = require('ws');
const path = require('path');

const app = express();
app.use(express.json());
app.use(express.urlencoded({ extended: true }));
app.use(express.static(path.join(__dirname, 'public')));

const server = http.createServer(app);
const wss = new WebSocket.Server({ server });

// Dashboard State (can be manipulated via the form)
let config = {
  multiplier: 1.0,
  label: "Sensor Alpha",
  interval: 1000 // milliseconds
};

let streamIntervalId = null;

// Function to start streaming real-time data based on config
function startDataStream() {
  if (streamIntervalId) clearInterval(streamIntervalId);

  streamIntervalId = setInterval(() => {
    // Generate simulated mathematical data
    const rawValue = Math.sin(Date.now() / 5000) * 50 + 50; 
    const finalValue = Math.round(rawValue * config.multiplier);

    const dataPayload = JSON.stringify({
      type: 'DATA_POINT',
      timestamp: new Date().toLocaleTimeString(),
      value: finalValue,
      label: config.label
    });

    // Broadcast data to all connected clients
    wss.clients.forEach(client => {
      if (client.readyState === WebSocket.OPEN) {
        client.send(dataPayload);
      }
    });
  }, config.interval);
}

// Form Handling Endpoint
app.post('/api/config', (req, res) => {
  const { label, multiplier, interval } = req.body;

  // Update server state
  config.label = label || "Sensor Alpha";
  config.multiplier = parseFloat(multiplier) || 1.0;
  config.interval = parseInt(interval, 10) || 1000;

  // Restart data stream with new interval/configurations
  startDataStream();

  // Broadcast configuration update to all clients
  const configPayload = JSON.stringify({
    type: 'CONFIG_UPDATE',
    config: config
  });

  wss.clients.forEach(client => {
    if (client.readyState === WebSocket.OPEN) {
      client.send(configPayload);
    }
  });

  return res.status(200).json({ status: 'success', message: 'Config updated!', config });
});

// Manage WebSocket Connections
wss.on('connection', (ws) => {
  console.log('Client connected to real-time feed');

  // Instantly send current configuration on connect
  ws.send(JSON.stringify({ type: 'CONFIG_UPDATE', config }));

  ws.on('close', () => console.log('Client disconnected'));
});

// Initialize Stream
startDataStream();

const PORT = 3000;
server.listen(PORT, () => {
  console.log(`Dashboard running on http://localhost:${PORT}`);
});
```

