<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Real-Time Telemetry Dashboard</title>
  <!-- Tailwind CSS CDN -->
  <script src="https://cdn.tailwindcss.com"></script>
  <!-- Chart.js CDN -->
  <script src="https://cdn.jsdelivr.net/npm/chart.js"></script>
</head>
<body class="bg-gray-900 text-gray-100 min-h-screen font-sans">

  <div class="container mx-auto px-6 py-8">
    <header class="flex justify-between items-center mb-10 border-b border-gray-800 pb-5">
      <div>
        <h1 class="text-3xl font-bold text-white tracking-tight">Telemetry Control Center</h1>
        <p class="text-gray-400 text-sm mt-1">Real-time data visualization & configuration dashboard</p>
      </div>
      <div class="flex items-center space-x-3">
        <span class="relative flex h-3 w-3">
          <span class="animate-ping absolute inline-flex h-full w-full rounded-full bg-emerald-400 opacity-75"></span>
          <span class="relative inline-flex rounded-full h-3 w-3 bg-emerald-500"></span>
        </span>
        <span class="text-emerald-400 font-semibold tracking-wider text-sm uppercase" id="status-text">Connected</span>
      </div>
    </header>

    <!-- Grid Layout -->
    <div class="grid grid-cols-1 lg:grid-cols-3 gap-8">

      <!-- Col 1: Form Handling / Settings -->
      <div class="bg-gray-800 p-6 rounded-2xl border border-gray-700 shadow-xl">
        <h2 class="text-xl font-bold mb-6 text-white border-b border-gray-700 pb-2">Dashboard Controller</h2>

        <form id="configForm" class="space-y-6">
          <div>
            <label class="block text-sm font-semibold text-gray-300 mb-2">Data Metric Label</label>
            <input type="text" id="label" name="label" required
              class="w-full bg-gray-900 border border-gray-700 rounded-lg px-4 py-2 text-white focus:outline-none focus:ring-2 focus:ring-indigo-500">
          </div>

          <div>
            <label class="block text-sm font-semibold text-gray-300 mb-2">Multiplier Factor</label>
            <input type="number" id="multiplier" name="multiplier" step="0.1" min="0.1" max="10" required
              class="w-full bg-gray-900 border border-gray-700 rounded-lg px-4 py-2 text-white focus:outline-none focus:ring-2 focus:ring-indigo-500">
          </div>

          <div>
            <label class="block text-sm font-semibold text-gray-300 mb-2">Stream Rate (ms)</label>
            <select id="interval" name="interval" 
              class="w-full bg-gray-900 border border-gray-700 rounded-lg px-4 py-2 text-white focus:outline-none focus:ring-2 focus:ring-indigo-500">
              <option value="250">Super Fast (250ms)</option>
              <option value="500">Fast (500ms)</option>
              <option value="1000">Standard (1000ms)</option>
              <option value="3000">Slow (3000ms)</option>
            </select>
          </div>

          <button type="submit" 
            class="w-full bg-indigo-600 hover:bg-indigo-500 text-white font-semibold py-2 px-4 rounded-lg transition duration-200 shadow-lg shadow-indigo-600/20">
            Apply Configuration
          </button>
        </form>

        <div id="form-feedback" class="mt-4 p-3 rounded-lg hidden text-sm font-medium text-center"></div>
      </div>

      <!-- Col 2 & 3: Interactive Data Visualization -->
      <div class="lg:col-span-2 space-y-6">
        <!-- Live Stat Cards -->
        <div class="grid grid-cols-1 md:grid-cols-3 gap-4">
          <div class="bg-gray-800 p-5 rounded-xl border border-gray-700 shadow">
            <p class="text-sm text-gray-400">Current Stream Label</p>
            <p id="stat-label" class="text-xl font-bold text-indigo-400 mt-1">--</p>
          </div>
          <div class="bg-gray-800 p-5 rounded-xl border border-gray-700 shadow">
            <p class="text-sm text-gray-400">Latest Value</p>
            <p id="stat-value" class="text-3xl font-black text-emerald-400 mt-1">0</p>
          </div>
          <div class="bg-gray-800 p-5 rounded-xl border border-gray-700 shadow">
            <p class="text-sm text-gray-400">Refresh Speed</p>
            <p id="stat-interval" class="text-xl font-bold text-amber-400 mt-1">-- ms</p>
          </div>
        </div>

        <!-- Real-Time Chart -->
        <div class="bg-gray-800 p-6 rounded-2xl border border-gray-700 shadow-xl h-[400px]">
          <canvas id="realtimeChart"></canvas>
        </div>
      </div>

    </div>
  </div>

  <script>
    // ----------------------------------------------------
    // 1. CHART INITIALIZATION
    // ----------------------------------------------------
    const ctx = document.getElementById('realtimeChart').getContext('2d');
    const chart = new Chart(ctx, {
      type: 'line',
      data: {
        labels: [], // Time stamps
        datasets: [{
          label: 'Data Feed',
          data: [], // Numerical data values
          borderColor: '#6366f1',
          backgroundColor: 'rgba(99, 102, 241, 0.15)',
          fill: true,
          tension: 0.3,
          borderWidth: 2,
          pointBackgroundColor: '#818cf8',
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        plugins: {
          legend: { display: true, labels: { color: '#9ca3af' } }
        },
        scales: {
          x: { grid: { color: '#374151' }, ticks: { color: '#9ca3af' } },
          y: { grid: { color: '#374151' }, ticks: { color: '#9ca3af' }, beginAtZero: true }
        }
      }
    });

    // Max data points shown in the viewport
    const MAX_DATA_POINTS = 15;

    // ----------------------------------------------------
    // 2. WEBSOCKET REAL-TIME LISTENER
    // ----------------------------------------------------
    const ws = new WebSocket(`ws://${window.location.host}`);
    const statusText = document.getElementById('status-text');

    ws.onopen = () => {
      statusText.textContent = 'Connected';
      statusText.className = 'text-emerald-400 font-semibold tracking-wider text-sm uppercase';
    };

    ws.onclose = () => {
      statusText.textContent = 'Disconnected';
      statusText.className = 'text-rose-400 font-semibold tracking-wider text-sm uppercase';
    };

    ws.onmessage = (event) => {
      const payload = JSON.parse(event.data);

      if (payload.type === 'CONFIG_UPDATE') {
        const { label, multiplier, interval } = payload.config;

        // Sync the Form values instantly across open tabs
        document.getElementById('label').value = label;
        document.getElementById('multiplier').value = multiplier;
        document.getElementById('interval').value = interval;

        // Sync local static metric widgets
        document.getElementById('stat-label').textContent = label;
        document.getElementById('stat-interval').textContent = `${interval}ms`;

        // Update Chart Legend Title dynamically
        chart.data.datasets[0].label = label;
        chart.update();
      }

      if (payload.type === 'DATA_POINT') {
        // Update Stat Card Widget
        document.getElementById('stat-value').textContent = payload.value;

        // Push new data point into Chart.js dataset
        chart.data.labels.push(payload.timestamp);
        chart.data.datasets[0].data.push(payload.value);

        // Shift old data arrays to create a scrolling "live timeline"
        if (chart.data.labels.length > MAX_DATA_POINTS) {
          chart.data.labels.shift();
          chart.data.datasets[0].data.shift();
        }

        chart.update('none'); // Update without full layout animation frames for high performance
      }
    };

    // ----------------------------------------------------
    // 3. ASYNC FORM HANDLING
    // ----------------------------------------------------
    const configForm = document.getElementById('configForm');
    const feedback = document.getElementById('form-feedback');

    configForm.addEventListener('submit', async (e) => {
      e.preventDefault();

      // Gather form inputs
      const formData = {
        label: document.getElementById('label').value,
        multiplier: document.getElementById('multiplier').value,
        interval: document.getElementById('interval').value,
      };

      try {
        // Submit POST request natively via Fetch API
        const response = await fetch('/api/config', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(formData)
        });

        const result = await response.json();

        if (result.status === 'success') {
          showFeedback('Server State Updated Successfully!', 'bg-emerald-900/50 text-emerald-300 border border-emerald-500/50');
        } else {
          throw new Error();
        }
      } catch (err) {
        showFeedback('Error submitting new configuration.', 'bg-rose-900/50 text-rose-300 border border-rose-500/50');
      }
    });

    function showFeedback(text, classes) {
      feedback.className = `mt-4 p-3 rounded-lg text-sm font-medium text-center ${classes}`;
      feedback.textContent = text;
      feedback.classList.remove('hidden');

      setTimeout(() => {
        feedback.classList.add('hidden');
      }, 3000);
    }
  </script>
</body>
</html>
