            <div class="bg-slate-900 border border-slate-800 rounded-xl p-5">
                <h2 class="text-sm font-semibold uppercase tracking-wider text-slate-400 mb-4">Threshold Settings</h2>
                <form id="configForm" class="space-y-4">
                    <div>
                        <label for="threshold" class="block text-xs font-medium text-slate-300 mb-1">Critical Threshold (%)</label>
                        <input type="number" id="threshold" name="threshold" min="10" max="100" value="80" 
                               class="w-full bg-slate-950 border border-slate-700 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-emerald-500 text-white">
