        </section>

        <!-- Right Column: Visualization & Metrics -->
        <section class="xl:col-span-3 flex flex-col gap-6">

            <!-- Live KPI Cards -->
            <div class="grid grid-cols-1 sm:grid-cols-3 gap-4">
