                    <div id="statusBadge" class="mt-2 inline-flex items-center px-2 py-0.5 rounded text-xs font-medium bg-emerald-950 text-emerald-400 border border-emerald-800">
                        Normal
                    </div>
                </div>
                <div class="bg-slate-900 border border-slate-800 rounded-xl p-5">
                    <p class="text-xs font-medium text-slate-400 uppercase">Average Load</p>
                    <p id="averageVal" class="text-3xl font-extrabold text-white mt-1">0%</p>
                    <p class="text-xs text-slate-500 mt-2">Rolling historical average</p>
                </div>
                <div class="bg-slate-900 border border-slate-800 rounded-xl p-5">
                    <p class="text-xs font-medium text-slate-400 uppercase">Peak Load</p>
                    <p id="peakVal" class="text-3xl font-extrabold text-white mt-1">0%</p>
                    <p id="peakTime" class="text-xs text-slate-500 mt-2">No peak recorded</p>
                </div>
            </div>

            <!-- Main Interactive Chart Card -->
            <div class="flex-1 bg-slate-900 border border-slate-800 rounded-xl p-5 flex flex-col">
                <div class="flex justify-between items-center mb-4">
                    <h2 class="font-semibold text-white">Live Stream Graph</h2>
                    <span class="text-xs text-slate-400">Updates dynamically</span>
                </div>
                <div class="relative flex-1 min-h-[300px]">
                    <canvas id="telemetryChart"></canvas>
                </div>
            </div>

            <!-- Event Logs (Form Actions and Anomalies) -->
            <div class="bg-slate-900 border border-slate-800 rounded-xl p-5">
                <h2 class="text-sm font-semibold uppercase tracking-wider text-slate-400 mb-3">System Log</h2>
                <div id="logConsole" class="h-32 overflow-y-auto bg-slate-950 rounded-lg p-3 font-mono text-xs text-slate-300 space-y-1">
                    <p class="text-slate-500">[System] Dashboard initialized...</p>
                </div>
