    <!-- App Logic -->
    <script>
        // --- 1. State Management ---
        const state = {
            data: [],
            labels: [],
            maxElements: 25,
            criticalThreshold: 80,
            intervalTime: 1000,
            isPaused: false,
            intervalId: null
        };

        // --- 2. Chart Setup ---
        const ctx = document.getElementById('telemetryChart').getContext('2d');
        const telemetryChart = new Chart(ctx, {
            type: 'line',
            data: {
                labels: state.labels,
                datasets: [{
                    label: 'System Metrics (%)',
                    data: state.data,
                    borderColor: 'rgb(16, 185, 129)', // Emerald Green
                    borderWidth: 2,
                    tension: 0.3,
                    fill: true,
                    backgroundColor: 'rgba(16, 185, 129, 0.1)',
                    pointRadius: 3,
                    pointBackgroundColor: 'rgb(16, 185, 129)'
                }, {
                    label: 'Threshold',
                    data: [],
                    borderColor: 'rgba(239, 68, 68, 0.7)', // Red Dash
                    borderWidth: 1.5,
                    borderDash: [6, 6],
                    fill: false,
                    pointRadius: 0
                }]
            },
            options: {
                responsive: true,
                maintainAspectRatio: false,
                scales: {
                    y: {
                        min: 0,
                        max: 100,
                        grid: { color: 'rgba(51, 65, 85, 0.3)' },
                        ticks: { color: '#94a3b8' }
                    },
                    x: {
                        grid: { display: false },
                        ticks: { color: '#94a3b8' }
                    }
                },
                plugins: {
                    legend: { display: false }
                }
            }
        });

        // --- 3. DOM Elements ---
        const pauseBtn = document.getElementById('pauseBtn');
        const resetBtn = document.getElementById('resetBtn');
        const configForm = document.getElementById('configForm');
        const injectForm = document.getElementById('injectForm');
        const logConsole = document.getElementById('logConsole');

        // --- 4. Event Logger Helper ---
        function writeLog(message, type = 'info') {
            const timeStamp = new Date().toLocaleTimeString();
            let color = 'text-slate-400';
            if (type === 'warning') color = 'text-amber-500 font-semibold';
            if (type === 'error') color = 'text-red-500 font-semibold';
            if (type === 'success') color = 'text-emerald-400';

            const logItem = document.createElement('p');
            logItem.className = color;
            logItem.innerHTML = `<span>[${timeStamp}]</span> ${message}`;
            logConsole.appendChild(logItem);
            logConsole.scrollTop = logConsole.scrollHeight; // Auto-scroll to bottom
        }

        // --- 5. Data Flow & Metric Updates ---
        function addDataPoint(val) {
            const timeLabel = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' });

            state.data.push(val);
            state.labels.push(timeLabel);

            if (state.data.length > state.maxElements) {
                state.data.shift();
                state.labels.shift();
            }

            updateMetrics(val);
            updateThresholdLine();
            telemetryChart.update('none'); // Quick rendering
        }

        function updateThresholdLine() {
            const thresholdDataset = telemetryChart.data.datasets[1];
            thresholdDataset.data = Array(state.data.length).fill(state.criticalThreshold);
        }

        function updateMetrics(latestValue) {
            // Update Current
            const currentValEl = document.getElementById('currentVal');
            const statusBadge = document.getElementById('statusBadge');
            currentValEl.innerText = `${latestValue}%`;

            if (latestValue >= state.criticalThreshold) {
                statusBadge.innerText = 'Critical Alert';
                statusBadge.className = 'mt-2 inline-flex items-center px-2 py-0.5 rounded text-xs font-medium bg-red-950 text-red-400 border border-red-800';
                writeLog(`Threshold breached! Current Load: ${latestValue}%`, 'error');

                // Color chart points dynamically if critical
                telemetryChart.data.datasets[0].borderColor = 'rgb(239, 68, 68)';
                telemetryChart.data.datasets[0].backgroundColor = 'rgba(239, 68, 68, 0.1)';
            } else {
                statusBadge.innerText = 'Normal';
                statusBadge.className = 'mt-2 inline-flex items-center px-2 py-0.5 rounded text-xs font-medium bg-emerald-950 text-emerald-400 border border-emerald-800';
                telemetryChart.data.datasets[0].borderColor = 'rgb(16, 185, 129)';
                telemetryChart.data.datasets[0].backgroundColor = 'rgba(16, 185, 129, 0.1)';
            }

            // Update Average
            const avg = Math.round(state.data.reduce((a, b) => a + b, 0) / state.data.length);
            document.getElementById('averageVal').innerText = `${avg || 0}%`;

            // Update Peak
            const peakEl = document.getElementById('peakVal');
            const currentPeak = parseInt(peakEl.innerText) || 0;
            if (latestValue > currentPeak) {
                peakEl.innerText = `${latestValue}%`;
                document.getElementById('peakTime').innerText = `At ${new Date().toLocaleTimeString()}`;
            }
        }

        // --- 6. Form Handling & Client Validation ---

        // Handling Config Form (Threshold + Update Speed)
        configForm.addEventListener('submit', function (e) {
            e.preventDefault();

            const thresholdInput = document.getElementById('threshold');
            const intervalInput = document.getElementById('interval');
            const errorSpan = document.getElementById('thresholdError');

            const newThreshold = parseInt(thresholdInput.value);
            const newInterval = parseInt(intervalInput.value);

            // Validation Rule: Range 10 - 100
            if (isNaN(newThreshold) || newThreshold < 10 || newThreshold > 100) {
                errorSpan.classList.remove('hidden');
                thresholdInput.classList.add('border-red-500');
                writeLog("Configuration failed: Threshold invalid", 'error');
                return;
            }

            errorSpan.classList.add('hidden');
            thresholdInput.classList.remove('border-red-500');

            // Apply modifications to State
            state.criticalThreshold = newThreshold;
            state.intervalTime = newInterval;

            writeLog(`Settings updated. Threshold: ${newThreshold}%, Interval: ${newInterval}ms`, 'success');

            // Re-bootstrap Interval cycle
            stopStream();
            if (!state.isPaused) startStream();
        });

        // Handling Manual Injection Form
        injectForm.addEventListener('submit', function (e) {
            e.preventDefault();

            const injectInput = document.getElementById('customValue');
            const errorSpan = document.getElementById('injectError');
            const value = parseInt(injectInput.value);

            if (isNaN(value) || value < 0 || value > 100) {
                errorSpan.classList.remove('hidden');
                injectInput.classList.add('border-red-500');
                return;
            }

            errorSpan.classList.add('hidden');
            injectInput.classList.remove('border-red-500');

            // Immediate data placement
            writeLog(`Manual Event Injected: Data Value ${value}%`, 'warning');
            addDataPoint(value);
            injectForm.reset();
        });

        // --- 7. Generator Engine (Simulated WebSockets) ---
        function startStream() {
            state.intervalId = setInterval(() => {
                // Generates random baseline values that occasionally spike
                const isSpike = Math.random() > 0.85;
                const baseVal = Math.floor(Math.random() * 30) + 40; // 40 - 70 range
                const generatedVal = isSpike ? Math.floor(Math.random() * 20) + 80 : baseVal; // spikes up to 100
                addDataPoint(generatedVal);
            }, state.intervalTime);
        }

        function stopStream() {
            clearInterval(state.intervalId);
        }

        // --- 8. Toolbar Button Handlers ---
        pauseBtn.addEventListener('click', () => {
            state.isPaused = !state.isPaused;
            if (state.isPaused) {
                stopStream();
                pauseBtn.innerText = 'Resume Stream';
                pauseBtn.className = "px-3 py-1.5 text-xs font-semibold bg-emerald-600 hover:bg-emerald-500 text-white rounded transition";
                writeLog("Telemetry feed paused.", 'warning');
            } else {
                startStream();
                pauseBtn.innerText = 'Pause Stream';
                pauseBtn.className = "px-3 py-1.5 text-xs font-semibold bg-amber-600 hover:bg-amber-500 text-white rounded transition";
                writeLog("Telemetry feed resumed.", 'success');
            }
        });

        resetBtn.addEventListener('click', () => {
            state.data = [];
            state.labels = [];
            telemetryChart.data.labels = state.labels;
            telemetryChart.data.datasets[0].data = state.data;
            telemetryChart.data.datasets[1].data = [];
            telemetryChart.update();

            document.getElementById('currentVal').innerText = "0%";
            document.getElementById('averageVal').innerText = "0%";
            document.getElementById('peakVal').innerText = "0%";
            document.getElementById('peakTime').innerText = "No peak recorded";

            writeLog("Dataset reset performed.", 'info');
        });

        // Bootstrap App
        startStream();
    </script>
</body>
</html>
```

