            const timeLabel = customLabel || new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' });

            appState.dataHistory.push(value);
            appState.labelsHistory.push(timeLabel);

            // Maintain horizontal sliding effect limit
            if (appState.dataHistory.length > appState.maxDataPoints) {
                appState.dataHistory.shift();
