    <script>
        // --- State Management ---
        const state = {
            isLive: true,
            updateInterval: 1000, // Milliseconds
            alertThreshold: 80,
            chartLimit: 25,
            dataHistory: [],
            labelsHistory: [],
            intervalId: null
        };

        // --- Chart Initialization ---
        const ctx = document.getElementById('realtimeChart').getContext('2d');
        const chart = new Chart(ctx, {
            type: 'line',
            data: {
                labels: state.labelsHistory,
                datasets: [{
                    label: 'Device Performance metric (%)',
                    data: state.dataHistory,
                    borderColor: '#3b82f6', // Tailwind blue-500
                    borderWidth: 2.5,
                    backgroundColor: 'rgba(59, 130, 246, 0.1)',
                    fill: true,
                    tension: 0.3,
                    pointRadius: 4,
                    pointHoverRadius: 6
                }]
            },
            options: {
                responsive: true,
                maintainAspectRatio: false,
                scales: {
                    x: {
                        grid: { color: '#1e293b' }, // slate-800
                        ticks: { color: '#94a3b8' } // slate-400
                    },
                    y: {
                        min: 0,
                        max: 100,
                        grid: { color: '#1e293b' },
                        ticks: { color: '#94a3b8' }
                    }
                },
                plugins: {
                    legend: { display: false }
                }
            }
        });

        // --- Core Functions ---

        // Generates random simulation data
        function getSimulatedData() {
            // Generate a random walk centered around 50 with occasional spikes
            const lastVal = state.dataHistory[state.dataHistory.length - 1] || 50;
            const variance = (Math.random() - 0.5) * 15;
            let newVal = Math.round(lastVal + variance);

            // Boundary enforcement
            if (newVal > 100) newVal = 100;
            if (newVal < 0) newVal = 0;

            // Random 5% chance of spike
            if (Math.random() > 0.95) {
                newVal = Math.floor(Math.random() * (100 - 85) + 85);
            }
            return newVal;
        }

        // Pushes a new reading into the data pipeline and updates DOM & Chart
        function pushNewData(val) {
            const timeLabel = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' });

            state.dataHistory.push(val);
            state.labelsHistory.push(timeLabel);

            // Maintain horizontal sliding window on the chart
            if (state.dataHistory.length > state.chartLimit) {
                state.dataHistory.shift();
                state.labelsHistory.shift();
            }

            // Update UI components
            updateKPIs(val);
            chart.update();
        }

        // Calculates & renders KPI updates
        function updateKPIs(currentVal) {
            // Current Value update
            document.getElementById('stat-current').innerText = currentVal.toFixed(1) + '%';

            // Running Average update
            const sum = state.dataHistory.reduce((a, b) => a + b, 0);
            const avg = (sum / state.dataHistory.length) || 0;
            document.getElementById('stat-avg').innerText = avg.toFixed(1) + '%';

            // Threshold Alert state handling
            const alertCard = document.getElementById('stat-alert-card');
            const alertText = document.getElementById('stat-alert-text');

            if (currentVal >= state.alertThreshold) {
                alertCard.className = 'bg-rose-950/40 p-4 rounded-xl border border-rose-500 transition-colors duration-300';
                alertText.innerText = '⚠️ Threshold Triggered';
                alertText.className = 'text-rose-400 mt-1.5 font-bold uppercase tracking-wide text-xs';
            } else {
                alertCard.className = 'bg-slate-950 p-4 rounded-xl border border-slate-800 transition-colors duration-300';
                alertText.innerText = 'Nominal';
                alertText.className = 'text-emerald-400 mt-1.5 font-bold uppercase tracking-wide text-xs';
            }
        }

        // Loop control manager
        function startDataStream() {
            if (state.intervalId) clearInterval(state.intervalId);
            state.intervalId = setInterval(() => {
                if (state.isLive) {
                    pushNewData(getSimulatedData());
                }
            }, state.updateInterval);
        }

        // --- DOM Form & Event Listeners ---

        // 1. Settings Form Submissions
        document.getElementById('settings-form').addEventListener('submit', (e) => {
            e.preventDefault();
            const intervalInput = document.getElementById('input-interval');
            const thresholdInput = document.getElementById('input-threshold');

            // Form validation
            const parsedInterval = parseInt(intervalInput.value, 10);
            const parsedThreshold = parseInt(thresholdInput.value, 10);

            if (parsedInterval >= 200 && parsedInterval <= 5000) {
                state.updateInterval = parsedInterval;
            }
            if (parsedThreshold >= 0 && parsedThreshold <= 100) {
                state.alertThreshold = parsedThreshold;
            }

            // Restart Stream loop with new settings
            startDataStream();

            // Visual submit feedback
            const submitBtn = e.target.querySelector('button[type="submit"]');
            const originalText = submitBtn.innerText;
            submitBtn.innerText = 'Saved & Applied!';
            submitBtn.classList.replace('bg-slate-800', 'bg-blue-600');
            setTimeout(() => {
                submitBtn.innerText = originalText;
                submitBtn.classList.replace('bg-blue-600', 'bg-slate-800');
            }, 1500);
        });

        // 2. Custom Data Injection Form Submissions
        document.getElementById('inject-form').addEventListener('submit', (e) => {
            e.preventDefault();
            const injectInput = document.getElementById('input-inject-value');
            const val = parseInt(injectInput.value, 10);

            if (!isNaN(val) && val >= 0 && val <= 100) {
                pushNewData(val);
                injectInput.value = ''; // Reset Form

                // Show success UI feedback
                const feedback = document.getElementById('inject-feedback');
                feedback.classList.remove('hidden');
                setTimeout(() => feedback.classList.add('hidden'), 2000);
            }
        });

        // 3. Play/Pause toggle control
        document.getElementById('btn-toggle').addEventListener('click', (e) => {
            state.isLive = !state.isLive;
            const statusIndicator = document.getElementById('connection-status');
            const statusText = document.getElementById('status-text');

            if (state.isLive) {
                e.target.innerText = 'Pause Stream';
                e.target.classList.replace('bg-emerald-600', 'bg-blue-600');
                statusIndicator.querySelector('span:first-child').classList.add('animate-ping');
                statusIndicator.querySelector('span:last-child').className = 'relative inline-flex rounded-full h-3 w-3 bg-emerald-500';
                statusText.innerText = 'Connected (Live)';
                statusText.className = 'text-sm font-semibold text-emerald-400';
            } else {
                e.target.innerText = 'Resume Stream';
                e.target.classList.replace('bg-blue-600', 'bg-emerald-600');
                statusIndicator.querySelector('span:first-child').classList.remove('animate-ping');
                statusIndicator.querySelector('span:last-child').className = 'relative inline-flex rounded-full h-3 w-3 bg-rose-500';
                statusText.innerText = 'Paused';
                statusText.className = 'text-sm font-semibold text-rose-400';
            }
        });

        // --- App Bootstrapping ---
        // Pre-fill initial mock data history
        for (let i = 0; i < 15; i++) {
            const val = Math.floor(Math.random() * (75 - 40) + 40);
            pushNewData(val);
        }
        startDataStream();
    </script>
</body>
</html>
```

### How this scales into a robust Production Stack
If this app was being migrated into an enterprise dashboard application, you would swap out these components:

* **HTML to TypeScript (React/Vue)**: Componentize your widgets. The JavaScript object literal `state` would map to an interactive React context hook or a `Zustand` store.
* **CDNs to `npm` packages**: Bundle your static dependencies like `Chart.js` via Vite, Webpack, or Next.js.
* **Simulated Randomizer to actual WebSockets**: Swap out `getSimulatedData()` in favor of standard Web browser WebSockets:
```typescript
const socket = new WebSocket('wss://api.example.com/telemetry');
socket.addEventListener('message', (event) => {
    const message = JSON.parse(event.data);
    pushNewData(message.value);
});
```

