        const state = {
            updateInterval: 1000,
            alertThreshold: 80,
            alertCount: 0,
            dataHistory: Array(20).fill(0),
            labels: Array(20).fill(''),
            maxHistorySize: 20,
            peakValue: 0
        };

        // UI Element References
        const configForm = document.getElementById('configForm');
        const injectForm = document.getElementById('injectForm');
        const alertThresholdInput = document.getElementById('alertThreshold');
        const thresholdValText = document.getElementById('thresholdVal');
        const thresholdLabelText = document.getElementById('thresholdLabel');
        const statAvg = document.getElementById('statAvg');
        const statPeak = document.getElementById('statPeak');
        const statAlerts = document.getElementById('statAlerts');
        const alertCard = document.getElementById('alertCard');
        const alertIconBox = document.getElementById('alertIconBox');
        const logTableBody = document.getElementById('logTableBody');

        // Setup Chart.js
        const ctx = document.getElementById('realtimeChart').getContext('2d');
        const gradient = ctx.createLinearGradient(0, 0, 0, 300);
        gradient.addColorStop(0, 'rgba(59, 130, 246, 0.4)');
        gradient.addColorStop(1, 'rgba(59, 130, 246, 0.0)');

        const realtimeChart = new Chart(ctx, {
            type: 'line',
            data: {
                labels: state.labels,
                datasets: [{
                    label: 'CPU Usage (%)',
                    data: state.dataHistory,
                    borderColor: '#3b82f6',
                    borderWidth: 2,
                    fill: true,
                    backgroundColor: gradient,
                    tension: 0.3,
                    pointRadius: 3,
                    pointBackgroundColor: '#3b82f6',
                }]
            },
            options: {
                responsive: true,
                maintainAspectRatio: false,
                animation: { duration: 250 },
                plugins: {
                    legend: { display: false }
                },
                scales: {
                    y: {
                        min: 0,
                        max: 100,
                        grid: { color: 'rgba(51, 65, 85, 0.4)' },
                        ticks: { color: '#94a3b8' }
                    },
                    x: {
                        grid: { display: false },
                        ticks: { color: '#94a3b8' }
                    }
                }
            }
        });

        // Logger Helper
        function addLog(source, value, isAlert = false) {
            const row = document.createElement('tr');
            row.className = `hover:bg-slate-800/30 transition duration-150 ${isAlert ? 'text-rose-400 bg-rose-500/5' : 'text-slate-300'}`;

            const timestamp = new Date().toLocaleTimeString();
            row.innerHTML = `
                <td class="py-2.5 font-mono text-xs">${timestamp}</td>
                <td class="py-2.5">${source}</td>
                <td class="py-2.5 text-right font-mono font-semibold">${value}%</td>
                <td class="py-2.5 text-right">
                    <span class="inline-flex items-center px-1.5 py-0.5 rounded text-[10px] font-bold ${isAlert ? 'bg-rose-500/20 text-rose-300 border border-rose-500/20' : 'bg-slate-700/50 text-slate-400'}">
                        ${isAlert ? 'WARN' : 'OK'}
                    </span>
                </td>
            `;

            logTableBody.prepend(row);
            if (logTableBody.children.length > 50) {
                logTableBody.lastElementChild.remove();
            }
        }

        // Live Data Generation & Chart Updates
        function tick(injectedValue = null, source = 'System Autopilot') {
            const timeNow = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' });

            // 1. Generate real-time random CPU fluctuations if no injected value
            let value = injectedValue;
            if (value === null) {
                const prev = state.dataHistory[state.dataHistory.length - 1] || 40;
                const change = (Math.random() - 0.5) * 15; // smooth variation steps
                value = Math.max(10, Math.min(100, Math.round(prev + change)));
            }

            // 2. Update state arrays
            state.dataHistory.push(value);
            state.labels.push(timeNow);

            if (state.dataHistory.length > state.maxHistorySize) {
                state.dataHistory.shift();
                state.labels.shift();
            }

            // 3. Keep metrics in state updated
            const sum = state.dataHistory.reduce((a, b) => a + b, 0);
            statAvg.textContent = `${Math.round(sum / state.dataHistory.length)}%`;

            if (value > state.peakValue) {
                state.peakValue = value;
                statPeak.textContent = `${state.peakValue}%`;
            }

            // 4. Threshold Breach Detection (Real-Time Warning)
            const isAlert = value >= state.alertThreshold;
            if (isAlert) {
                state.alertCount++;
                statAlerts.textContent = state.alertCount;

                // Flash alert UI styles
                alertCard.className = 'bg-rose-500/10 border border-rose-500 rounded-xl p-4 flex justify-between items-center transition-all duration-300 animate-pulse';
                alertIconBox.className = 'p-3 bg-rose-500/20 rounded-lg text-rose-400 transition-colors duration-300';

                addLog(source, value, true);
            } else {
                // Reset card UI styling if normal
                alertCard.className = 'bg-slate-800/40 border border-slate-800 rounded-xl p-4 flex justify-between items-center transition-all duration-300';
                alertIconBox.className = 'p-3 bg-emerald-500/10 rounded-lg text-emerald-400 transition-colors duration-300';

                if (injectedValue !== null) addLog(source, value, false);
            }

            // Update Chart datasets and refresh view
            realtimeChart.update();
        }

        // Handle Active Interval Loop
        let intervalId;
        function restartSimulation() {
            clearInterval(intervalId);
            intervalId = setInterval(() => tick(), state.updateInterval);
        }

        // FORM HANDLING 1: Settings Form
        configForm.addEventListener('submit', (e) => {
            e.preventDefault();

            // Get values from form inputs
            const intervalVal = parseInt(document.getElementById('updateInterval').value);
            const thresholdVal = parseInt(alertThresholdInput.value);

            // Update state
            state.updateInterval = intervalVal;
            state.alertThreshold = thresholdVal;

            // Reflect state changes visually
            thresholdLabelText.textContent = `${state.alertThreshold}%`;

            // Restart intervals with the new configuration
            restartSimulation();
            addLog('System Configuration Saved', thresholdVal);
        });

        // Slide input visual binding
        alertThresholdInput.addEventListener('input', (e) => {
            thresholdValText.textContent = `${e.target.value}%`;
        });

        // FORM HANDLING 2: Injection Form
        injectForm.addEventListener('submit', (e) => {
            e.preventDefault();

            const injectedVal = parseInt(document.getElementById('injectValue').value);
            const labelTag = document.getElementById('injectNote').value;

            // Inject the data point directly into the flow
            tick(injectedVal, `Form Injection: ${labelTag}`);

            // Reset injection form inputs
            injectForm.reset();
        });

        // Initialize App Start
        restartSimulation();
    </script>
</body>
</html>
```

### Explaining the Implementation Architectures

1. **Reactive State Pattern:** The interface is built using an underlying JS state object `state`. Any form submission acts as a controller, parsing the parameters and updating `state`, which directly shifts the loop speeds and threshold validation values in the active UI components.
2. **Dynamic Chart Buffer:** To keep performance fast and prevent standard memory leaks associated with continuous charts, the JavaScript maintains a moving boundary window (`maxHistorySize: 20`). Once the browser receives details beyond this buffer, it shifts out the oldest elements using Array queues (`shift()`).
3. **WebSockets Integration (Extending this code for Production):**
   In a production scenario, you would replace the simulated local polling loop (`setInterval`) with a standard browser **WebSocket** connection to ingest real-time payloads from your server backend:

   ```javascript
   // Replace standard dynamic generation loop with WebSockets:
   const socket = new WebSocket('ws://your-api-server.com/metrics');

   socket.onmessage = (event) => {
       const serverPayload = JSON.parse(event.data);
       // Push WebSocket metric variables directly into the tick loop
       tick(serverPayload.cpuUsage, serverPayload.serviceName);
   };
   ```

