                                <label class="block text-xs font-semibold uppercase text-slate-400 mb-1">Alert Limit</label>
                                <input type="number" id="alertLimit" value="75" min="10" max="100"
                                    class="w-full bg-slate-900 border border-slate-700 rounded-lg px-3 py-2 text-sm text-slate-200 focus:outline-none focus:border-cyan-500 transition">
                            </div>
                        </div>
                        <button type="submit" class="w-full bg-cyan-600 hover:bg-cyan-500 text-slate-900 font-bold py-2 rounded-lg text-sm transition">
                            Apply & Restart Stream
                        </button>
                    </form>
                </div>

                <!-- FORM 2: MANUAL DATA INJECTION -->
                <div class="bg-slate-800 p-6 rounded-xl border border-slate-700/50">
                    <h2 class="text-lg font-bold text-slate-200 mb-4 flex items-center gap-2">
                        <span>⚡</span> Manual Data Injection
                    </h2>
                    <form id="injectForm" class="space-y-4">
                        <div>
                            <label class="block text-xs font-semibold uppercase text-slate-400 mb-1">Value to Inject</label>
                            <div class="flex gap-2">
                                <input type="number" id="injectValue" placeholder="e.g. 95" required min="0" max="150"
                                    class="w-full bg-slate-900 border border-slate-700 rounded-lg px-3 py-2 text-sm text-slate-200 focus:outline-none focus:border-rose-500 transition">
                                <button type="submit" class="bg-rose-600 hover:bg-rose-500 text-white font-bold px-4 rounded-lg text-sm transition whitespace-nowrap">
                                    Inject Point
                                </button>
                            </div>
                            <span id="injectError" class="text-rose-500 text-[10px] hidden">Must be between 0 and 150</span>
                        </div>
                    </form>
                </div>

                <!-- CONTROLS -->
                <div class="bg-slate-800 p-6 rounded-xl border border-slate-700/50 flex gap-4">
                    <button id="btnPause" class="flex-1 bg-slate-700 hover:bg-slate-600 text-slate-200 font-bold py-2.5 rounded-lg text-sm transition">
                        ⏸️ Pause Stream
                    </button>
                    <button id="btnClear" class="flex-1 bg-slate-900 hover:bg-slate-800 text-slate-400 font-bold py-2.5 rounded-lg text-sm transition border border-slate-700">
                        🗑️ Reset Chart
                    </button>
                </div>

            </div>

            <!-- RIGHT COLUMN: VISUALIZATION & ALERTS -->
            <div class="lg:col-span-2 space-y-6">

                <!-- CHART CONTAINER -->
                <div class="bg-slate-800 p-6 rounded-xl border border-slate-700/50">
                    <div class="flex justify-between items-center mb-4">
                        <h2 id="chartTitle" class="text-lg font-bold text-slate-200">CPU Temperature (°C) — Live</h2>
                        <span class="text-xs text-slate-500">Max 25 points sliding window</span>
                    </div>
                    <div class="relative h-80 w-full">
                        <canvas id="realtimeChart"></canvas>
                    </div>
                </div>

                <!-- LIVE ALERT LOGS -->
                <div class="bg-slate-800 p-6 rounded-xl border border-slate-700/50">
                    <h2 class="text-lg font-bold text-slate-200 mb-4 flex justify-between items-center">
                        <span>🚨 Alert Log</span>
                        <span id="alertCountBadge" class="text-xs bg-rose-500/20 text-rose-400 px-2.5 py-0.5 rounded-full font-bold">0 Active Alerts</span>
                    </h2>
                    <div id="logContainer" class="h-40 overflow-y-auto space-y-2 pr-2 text-xs font-mono scrollbar-thin scrollbar-thumb-slate-700">
                        <div class="text-slate-500 italic">System quiet. No thresholds breached...</div>
                    </div>
                </div>

            </div>
        </div>
    </div>

    <!-- SCRIPT CONFIGURATION AND APP LOGIC -->
    <script>
        // --- APP STATE ---
        let config = {
            metricLabel: 'CPU Temperature (°C)',
            intervalMs: 1000,
            alertLimit: 75
        };

        let isLive = true;
        let dataPoints = [];
        let labels = [];
        let alertCount = 0;
        let streamTimer = null;
        const maxPoints = 25;

        // --- CHART SETUP ---
        const ctx = document.getElementById('realtimeChart').getContext('2d');
        const gradient = ctx.createLinearGradient(0, 0, 0, 300);
        gradient.addColorStop(0, 'rgba(6, 182, 212, 0.4)');
        gradient.addColorStop(1, 'rgba(6, 182, 212, 0.01)');

        const myChart = new Chart(ctx, {
            type: 'line',
            data: {
                labels: labels,
                datasets: [{
                    label: config.metricLabel,
                    data: dataPoints,
                    borderColor: '#06b6d4', // cyan-500
                    borderWidth: 2,
                    backgroundColor: gradient,
                    fill: true,
                    tension: 0.3,
                    pointRadius: 4,
                    pointHoverRadius: 6,
                    pointBackgroundColor: '#06b6d4'
                }]
            },
            options: {
                responsive: true,
                maintainAspectRatio: false,
                plugins: {
                    legend: { display: false }
                },
                scales: {
                    x: {
                        grid: { color: 'rgba(51, 65, 85, 0.3)' },
                        ticks: { color: '#94a3b8' }
                    },
                    y: {
                        grid: { color: 'rgba(51, 65, 85, 0.3)' },
                        ticks: { color: '#94a3b8' },
                        suggestedMin: 30,
                        suggestedMax: 100
                    }
                }
            }
        });

        // --- MATH UTILITIES ---
        function updateStats() {
            if (dataPoints.length === 0) return;
            const current = dataPoints[dataPoints.length - 1];
            const peak = Math.max(...dataPoints);
            const sum = dataPoints.reduce((a, b) => a + b, 0);
            const avg = sum / dataPoints.length;

            document.getElementById('stat-current').innerText = current.toFixed(2);
            document.getElementById('stat-peak').innerText = peak.toFixed(2);
            document.getElementById('stat-avg').innerText = avg.toFixed(2);
            document.getElementById('stat-alerts').innerText = `${alertCount} Time${alertCount === 1 ? '' : 's'}`;
        }

        function generateDataPoint() {
            // Generates realistic random-walk temperature values centered around 55
            const lastVal = dataPoints.length > 0 ? dataPoints[dataPoints.length - 1] : 55;
            const drift = (Math.random() - 0.5) * 12; // fluctuation
            let newVal = lastVal + drift;
            newVal = Math.max(25, Math.min(newVal, 110)); // bounds clamp
            return parseFloat(newVal.toFixed(1));
        }

        // --- ALERT LOGGER ---
        function addLogEntry(value) {
            const container = document.getElementById('logContainer');
            // Remove the empty placeholder if present
            if (alertCount === 1) {
                container.innerHTML = '';
            }
            const timeStr = new Date().toLocaleTimeString();
            const logHTML = `
                <div class="flex justify-between bg-rose-500/10 border-l-4 border-rose-500 p-2 rounded text-rose-300 animate-fadeIn">
                    <span>⚠️ ALERT: ${config.metricLabel} reached ${value}</span>
                    <span>${timeStr}</span>
                </div>
            `;
            container.insertAdjacentHTML('afterbegin', logHTML);
            document.getElementById('alertCountBadge').innerText = `${alertCount} Alerts`;
        }

        // --- PUSH DATA ---
        function addDataPoint(val) {
            const now = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' });

            if (dataPoints.length >= maxPoints) {
                dataPoints.shift();
                labels.shift();
            }

            dataPoints.push(val);
            labels.push(now);

            // Check alerts
            if (val >= config.alertLimit) {
                alertCount++;
                addLogEntry(val);
            }

            // Redraw
            myChart.update();
            updateStats();
        }

        // --- LOOP CONTROL ---
        function startStream() {
            if (streamTimer) clearInterval(streamTimer);
            streamTimer = setInterval(() => {
                if (isLive) {
                    const nextVal = generateDataPoint();
                    addDataPoint(nextVal);
                }
            }, config.intervalMs);
        }

        // --- FORM HANDLING & VALIDATION ---
        document.getElementById('configForm').addEventListener('submit', function(e) {
            e.preventDefault();

            const labelInput = document.getElementById('metricLabel').value.trim();
            const intervalInput = parseInt(document.getElementById('intervalMs').value);
            const alertInput = parseInt(document.getElementById('alertLimit').value);

            // Validation Engine
            let isValid = true;
            if (isNaN(intervalInput) || intervalInput < 200 || intervalInput > 5000) {
                document.getElementById('intervalError').classList.remove('hidden');
                isValid = false;
            } else {
                document.getElementById('intervalError').classList.add('hidden');
            }

            if (isValid) {
                config.metricLabel = labelInput;
                config.intervalMs = intervalInput;
                config.alertLimit = alertInput;

                // Update Visual Titles
                document.getElementById('chartTitle').innerText = `${config.metricLabel} — Live`;
                myChart.data.datasets[0].label = config.metricLabel;

                startStream();
            }
        });

        document.getElementById('injectForm').addEventListener('submit', function(e) {
            e.preventDefault();
            const injectInput = parseFloat(document.getElementById('injectValue').value);

            if (isNaN(injectInput) || injectInput < 0 || injectInput > 150) {
                document.getElementById('injectError').classList.remove('hidden');
            } else {
                document.getElementById('injectError').classList.add('hidden');
                addDataPoint(injectInput);
                document.getElementById('injectForm').reset();
            }
        });

        // --- AUX CONTROLS ---
        const pauseBtn = document.getElementById('btnPause');
        pauseBtn.addEventListener('click', () => {
            isLive = !isLive;
            const statusInd = document.getElementById('status-indicator');
            const statusTxt = document.getElementById('status-text');

            if (isLive) {
                pauseBtn.innerText = '⏸️ Pause Stream';
                pauseBtn.className = "flex-1 bg-slate-700 hover:bg-slate-600 text-slate-200 font-bold py-2.5 rounded-lg text-sm transition";
                statusInd.className = "h-3.5 w-3.5 rounded-full bg-emerald-500 animate-ping";
                statusTxt.innerText = "Live Streaming";
                statusTxt.className = "text-xs font-semibold uppercase tracking-wider text-emerald-400";
            } else {
                pauseBtn.innerText = '▶️ Resume Stream';
                pauseBtn.className = "flex-1 bg-emerald-600 hover:bg-emerald-500 text-slate-900 font-bold py-2.5 rounded-lg text-sm transition";
                statusInd.className = "h-3.5 w-3.5 rounded-full bg-amber-500";
                statusTxt.innerText = "Paused";
                statusTxt.className = "text-xs font-semibold uppercase tracking-wider text-amber-500";
            }
        });

        document.getElementById('btnClear').addEventListener('click', () => {
            dataPoints.length = 0;
            labels.length = 0;
            alertCount = 0;
            myChart.update();
            document.getElementById('logContainer').innerHTML = '<div class="text-slate-500 italic">System reset. Monitoring quiet...</div>';
            document.getElementById('alertCountBadge').innerText = `0 Alerts`;
            document.getElementById('stat-current').innerText = "0.00";
            document.getElementById('stat-peak').innerText = "0.00";
            document.getElementById('stat-avg').innerText = "0.00";
            document.getElementById('stat-alerts').innerText = "0 Times";
        });

        // --- BOOTSTRAP INITIALIZATION ---
        // Fill initial array with historical run data (15 points)
        for(let i=0; i<15; i++) {
            const mockHistoryVal = generateDataPoint();
            const now = new Date();
            now.setSeconds(now.getSeconds() - (15 - i) * (config.intervalMs / 1000));
            labels.push(now.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' }));
            dataPoints.push(mockHistoryVal);
        }
        myChart.update();
        updateStats();
        startStream();
    </script>
</body>
</html>
```

### Key Technical Aspects Demonstrated in This Code:
* **The Sliding Window Strategy**: In real-time data handling, plotting thousands of points over time will crash the browser UI. The code implements a sliding window maximum cap (`maxPoints = 25`), shifting older values out as new ones streaming in via a `Shift()` array pattern.
* **Declarative Configuration State Management**: A single javascript config object governs properties like alerts, metric names, and timers. Form inputs map to this structure.
* **DOM Form Validation**: Input restrictions prevent logic issues (e.g., negative intervals, values too high, empty fields) before execution.
* **Canvas Gradient Rendering**: Custom canvas layouts dynamically render gradients under the lines for a beautiful, premium visual presentation.

