    <script>
        // --- 1. STATE & VARIABLES ---
        let updateInterval = 1000; // ms
        let multiplier = 1;
        let isRunning = true;
        let dataCount = 0;
        let timerId = null;

        const maxDataPoints = 15; // Limit data points shown on graph

        // --- 2. INITIALIZE CHART.JS ---
        const ctx = document.getElementById('realtimeChart').getContext('2d');
        const chart = new Chart(ctx, {
            type: 'line',
            data: {
                labels: [], // Time labels
                datasets: [{
                    label: 'System Load %',
                    data: [], // Numerical data
                    borderColor: '#2dd4bf', // Teal color
                    backgroundColor: 'rgba(45, 212, 191, 0.1)',
                    borderWidth: 2,
                    fill: true,
                    tension: 0.4, // Curved line
                    pointBackgroundColor: '#2dd4bf'
                }]
            },
            options: {
                responsive: true,
                maintainAspectRatio: false,
                scales: {
                    x: {
                        grid: { color: 'rgba(255, 255, 255, 0.1)' },
                        ticks: { color: '#9ca3af' }
                    },
                    y: {
                        min: 0,
                        max: 110,
                        grid: { color: 'rgba(255, 255, 255, 0.1)' },
                        ticks: { color: '#9ca3af' }
                    }
                },
                plugins: {
                    legend: { labels: { color: '#f3f4f6' } }
                }
            }
        });

        // --- 3. CORE LOGIC (REAL-TIME DATA) ---
        function generateDataPoint() {
            if (!isRunning) return;

            const timeLabel = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' });

            // Generate simulated standard load + added volatility
            let baseVal = 40 + Math.sin(dataCount * 0.5) * 15; // Smooth sine wave base
            let noise = (Math.random() - 0.5) * 15 * multiplier; // Random noise scaled by multiplier
            let finalVal = Math.max(0, Math.min(100, Math.round(baseVal + noise))); // Clamp between 0 - 100

            addDataToChart(timeLabel, finalVal);
        }

        function addDataToChart(label, dataValue) {
            chart.data.labels.push(label);
            chart.data.datasets[0].data.push(dataValue);
            dataCount++;

            // If threshold reached, slide window (remove oldest data point)
            if (chart.data.labels.length > maxDataPoints) {
                chart.data.labels.shift();
                chart.data.datasets[0].data.shift();
            }

