            <div class="bg-slate-800 p-5 rounded-xl border border-slate-700 shadow-lg">
                <p class="text-xs font-semibold text-slate-400 uppercase">Data Points Recorded</p>
                <p id="kpi-count" class="text-3xl font-bold text-emerald-400 mt-1 font-mono">0</p>
            </div>
        </div>

        <div class="grid grid-cols-1 lg:grid-cols-3 gap-8">
            <!-- Left Column: Form & Controls -->
            <div class="space-y-6">
                <!-- Control Panel Form -->
                <div class="bg-slate-800 p-6 rounded-xl border border-slate-700 shadow-lg">
                    <h2 class="text-lg font-bold text-white mb-4">Stream Control</h2>

                    <div class="space-y-4">
                        <!-- Play/Pause Button -->
                        <button id="toggle-stream" class="w-full py-2.5 px-4 bg-emerald-600 hover:bg-emerald-500 text-white font-semibold rounded-lg shadow transition duration-200">
                            Pause Data Stream
                        </button>

                        <!-- Live Volatility Slider -->
                        <div>
                            <label class="block text-sm font-medium text-slate-300 mb-1">
                                Max Volatility (Fluctuation): <span id="volatility-val" class="text-blue-400 font-mono">15</span>
                            </label>
                            <input id="volatility-slider" type="range" min="1" max="50" value="15" 
                                class="w-full h-2 bg-slate-700 rounded-lg appearance-none cursor-pointer accent-blue-500">
                        </div>
                    </div>
                </div>

                <!-- Manual Input Form -->
                <div class="bg-slate-800 p-6 rounded-xl border border-slate-700 shadow-lg">
                    <h2 class="text-lg font-bold text-white mb-4">Inject Manual Event</h2>
                    <form id="manual-data-form" class="space-y-4">
                        <div>
                            <label for="manual-value" class="block text-sm font-medium text-slate-300 mb-1">Metric Value (0 - 100)</label>
                            <input type="number" id="manual-value" min="0" max="100" required step="0.1" placeholder="e.g. 74.5"
                                class="w-full bg-slate-900 border border-slate-700 rounded-lg py-2 px-3 text-slate-200 placeholder-slate-500 focus:outline-none focus:ring-2 focus:ring-blue-500">
                        </div>
                        <button type="submit" class="w-full py-2.5 px-4 bg-blue-600 hover:bg-blue-500 text-white font-semibold rounded-lg shadow transition duration-200">
                            Submit Point
                        </button>
                    </form>
                </div>
            </div>

            <!-- Right Column: Chart -->
            <div class="lg:col-span-2 bg-slate-800 p-6 rounded-xl border border-slate-700 shadow-lg flex flex-col justify-between">
                <div class="flex justify-between items-center mb-4">
                    <h2 class="text-lg font-bold text-white">Live Data Feed (Rolling Window)</h2>
                    <span class="text-xs text-slate-400">Updates every 1.5s</span>
                </div>
                <div class="relative h-80 w-full">
                    <canvas id="realtimeChart"></canvas>
                </div>
            </div>
        </div>
    </div>

    <!-- Application Script -->
    <script>
        // --- State Management ---
        let isStreaming = true;
        let maxVolatility = 15;
        const maxDataPoints = 15; // Max points visible on the chart at once
        const chartData = [];
        const chartLabels = [];

        // --- DOM Elements ---
        const kpiCurrent = document.getElementById('kpi-current');
        const kpiAverage = document.getElementById('kpi-average');
        const kpiCount = document.getElementById('kpi-count');
        const toggleStreamBtn = document.getElementById('toggle-stream');
        const volatilitySlider = document.getElementById('volatility-slider');
        const volatilityValDisplay = document.getElementById('volatility-val');
        const manualForm = document.getElementById('manual-data-form');
        const manualInput = document.getElementById('manual-value');

        // --- Chart.js Configuration ---
        const ctx = document.getElementById('realtimeChart').getContext('2d');
        const liveChart = new Chart(ctx, {
            type: 'line',
            data: {
                labels: chartLabels,
                datasets: [{
                    label: 'Engine Pressure (PSI)',
                    data: chartData,
                    borderColor: 'rgb(59, 130, 246)', // Tailwind blue-500
                    backgroundColor: 'rgba(59, 130, 246, 0.1)',
                    fill: true,
                    tension: 0.4,
                    borderWidth: 3,
                    pointRadius: 4,
                    pointBackgroundColor: 'rgb(30, 41, 59)'
                }]
            },
            options: {
                responsive: true,
                maintainAspectRatio: false,
                plugins: { legend: { display: false } },
                scales: {
                    x: { grid: { color: 'rgba(148, 163, 184, 0.05)' }, ticks: { color: 'rgb(148, 163, 184)' } },
                    y: { min: 0, max: 100, grid: { color: 'rgba(148, 163, 184, 0.05)' }, ticks: { color: 'rgb(148, 163, 184)' } }
                }
            }
        });

        // --- Dashboard Update Functions ---
        function addDataPoint(value) {
            const timeLabel = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' });

            chartData.push(value);
            chartLabels.push(timeLabel);

            // Shift oldest data if rolling limit is exceeded
            if (chartData.length > maxDataPoints) {
                chartData.shift();
                chartLabels.shift();
            }

            // Calculate KPIs
            const totalSum = chartData.reduce((acc, val) => acc + val, 0);
            const avg = totalSum / chartData.length;
            const count = parseInt(kpiCount.innerText) + 1;

            // Update DOM KPIs
            kpiCurrent.innerText = value.toFixed(1);
            kpiAverage.innerText = avg.toFixed(1);
            kpiCount.innerText = count;

            // Update Chart
            liveChart.update();
        }

        // --- Form & Interaction Handlers ---

        // 1. Play/Pause stream toggle
        toggleStreamBtn.addEventListener('click', () => {
            isStreaming = !isStreaming;
            if (isStreaming) {
                toggleStreamBtn.innerText = 'Pause Data Stream';
                toggleStreamBtn.className = "w-full py-2.5 px-4 bg-emerald-600 hover:bg-emerald-500 text-white font-semibold rounded-lg shadow transition duration-200";
            } else {
                toggleStreamBtn.innerText = 'Resume Data Stream';
                toggleStreamBtn.className = "w-full py-2.5 px-4 bg-amber-600 hover:bg-amber-500 text-white font-semibold rounded-lg shadow transition duration-200";
            }
        });

        // 2. Volatility Slider Input
        volatilitySlider.addEventListener('input', (e) => {
            maxVolatility = parseFloat(e.target.value);
            volatilityValDisplay.innerText = maxVolatility;
        });

        // 3. Manual Data Submission Form
        manualForm.addEventListener('submit', (e) => {
            e.preventDefault(); // Prevent page reload
            const val = parseFloat(manualInput.value);
            if (!isNaN(val) && val >= 0 && val <= 100) {
                addDataPoint(val);
                manualInput.value = ''; // Reset Form
            }
        });

        // --- Real-time Generation Loop (Simulated SSE/WebSocket) ---
        setInterval(() => {
            if (!isStreaming) return;

            const previousVal = chartData.length > 0 ? chartData[chartData.length - 1] : 50;
            // Generate pseudo-random walk
            const change = (Math.random() - 0.5) * maxVolatility;
            let nextVal = previousVal + change;

            // Keep value bounded between 0 and 100
            nextVal = Math.max(0, Math.min(100, nextVal));

            addDataPoint(nextVal);
        }, 1500);

        // Prime the dashboard with a starting data point
        addDataPoint(50);
    </script>
</body>
</html>
```

### Why this structure works:
*   **Asynchronous DOM Engine:** JavaScript manages the state machine internally. When user inputs or real-time intervals trigger, it seamlessly recalculates visual variables (e.g. Rolling Averages, Chart Points) and pushes updates to the DOM without browser repainting delays.
*   **Preventing Memory Bloat:** Real-time data streams can crash browsers over time. The JavaScript logic handles this by maintaining a rolling array (`.shift()`), keeping memory usage light and fast.
*   **Responsive Layout:** Tailwind CSS classes ensure that if a user opens this on a mobile browser or full-scale desktop browser, the chart grid rearranges itself elegantly.

