    <!-- Application Logic -->
    <script>
        // --- State Management ---
        let streamInterval = 1000; // Default: 1 second
        let dataMultiplier = 5;
        let isPaused = false;
        let intervalId = null;
        const maxDataPoints = 15;

        // --- DOM Elements ---
        const configForm = document.getElementById('configForm');
        const intervalInput = document.getElementById('intervalInput');
        const multiplierInput = document.getElementById('multiplierInput');
        const multiplierValue = document.getElementById('multiplierValue');
        const pauseBtn = document.getElementById('pauseBtn');
        const manualForm = document.getElementById('manualDataForm');
        const manualValueInput = document.getElementById('manualValue');
        const latestValDisplay = document.getElementById('latestValue');
        const statusIndicator = document.getElementById('statusIndicator');

        // --- Chart.js Setup ---
        const ctx = document.getElementById('realtimeChart').getContext('2d');
        const chart = new Chart(ctx, {
            type: 'line',
            data: {
                labels: Array(maxDataPoints).fill(''), // Blank labels placeholder
                datasets: [{
                    label: 'Sensor Metric',
                    data: Array(maxDataPoints).fill(0),
                    borderColor: '#6366f1', // Indigo-500
                    backgroundColor: 'rgba(99, 102, 241, 0.1)',
                    borderWidth: 2.5,
                    fill: true,
                    tension: 0.4, // Curved line
                    pointRadius: 4,
                    pointBackgroundColor: '#ffffff'
                }]
            },
            options: {
                responsive: true,
                maintainAspectRatio: false,
                scales: {
                    x: { grid: { color: 'rgba(75, 85, 99, 0.2)' }, ticks: { color: '#9ca3af' } },
                    y: { min: 0, max: 120, grid: { color: 'rgba(75, 85, 99, 0.2)' }, ticks: { color: '#9ca3af' } }
                },
                plugins: {
                    legend: { display: false }
                }
            }
        });

        // --- Core Functions ---

        // Append new data point to Chart
        function appendData(value) {
            const timeString = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' });

            // Push new data and shift out old data to maintain a clean viewport
            chart.data.labels.push(timeString);
            chart.data.datasets[0].data.push(value);

            if (chart.data.labels.length > maxDataPoints) {
                chart.data.labels.shift();
                chart.data.datasets[0].data.shift();
            }

            chart.update('none'); // Update without heavy animations for performance
            latestValDisplay.textContent = Number(value).toFixed(2);
        }

        // Generate Simulated Real-time Data
        function generateData() {
            if (isPaused) return;
            // Generate a random-walk numerical value
            const previousValue = chart.data.datasets[0].data[chart.data.datasets[0].data.length - 1] || 50;
            const fluctuation = (Math.random() - 0.5) * 10 * dataMultiplier;
            let newValue = previousValue + fluctuation;

            // Keep value within a clean 0-100 range bounds
            newValue = Math.max(5, Math.min(105, newValue));

            appendData(newValue);
        }

        // Start/Reset the timer interval
        function startDataStream() {
            if (intervalId) clearInterval(intervalId);
            intervalId = setInterval(generateData, streamInterval);
        }

        // --- Event Listeners & Interactive Form Handling ---

        // 1. Slider interactivity
        multiplierInput.addEventListener('input', (e) => {
            dataMultiplier = e.target.value;
            multiplierValue.textContent = `Current: ${dataMultiplier}x`;
        });

        // 2. Stream Configuration Form (Interval adjustment)
        configForm.addEventListener('submit', (e) => {
            e.preventDefault();

            // Validation validation rules check
            const inputVal = parseInt(intervalInput.value);
            if (inputVal >= 200 && inputVal <= 5000) {
                streamInterval = inputVal;
                if (!isPaused) {
                    startDataStream();
                }
                alert(`Stream updated to refresh every ${streamInterval}ms.`);
            } else {
                alert("Please enter an interval between 200ms and 5000ms.");
            }
        });

        // 3. Pause / Resume Stream
        pauseBtn.addEventListener('click', () => {
            isPaused = !isPaused;
            if (isPaused) {
                pauseBtn.textContent = "Resume Stream";
                pauseBtn.className = "flex-1 bg-amber-600 hover:bg-amber-500 text-white font-semibold py-2 px-4 rounded transition";
                statusIndicator.className = "flex items-center gap-2 bg-amber-500/10 text-amber-400 px-3 py-1 rounded-full text-sm font-semibold";
                statusIndicator.innerHTML = '<span class="w-2.5 h-2.5 bg-amber-500 rounded-full"></span> Stream Paused';
            } else {
                pauseBtn.textContent = "Pause Stream";
                pauseBtn.className = "flex-1 bg-gray-700 hover:bg-gray-600 text-white font-semibold py-2 px-4 rounded transition";
                statusIndicator.className = "flex items-center gap-2 bg-green-500/10 text-green-400 px-3 py-1 rounded-full text-sm font-semibold";
                statusIndicator.innerHTML = '<span class="w-2.5 h-2.5 bg-green-500 rounded-full animate-ping"></span> Live Connected';
            }
        });

        // 4. Manual Custom Data Injection Form
        manualForm.addEventListener('submit', (e) => {
            e.preventDefault();
            const manualValue = parseFloat(manualValueInput.value);

            if (!isNaN(manualValue)) {
                // Instantly inject manual entry to chart
                appendData(manualValue);
                manualValueInput.value = ''; // Reset Form
            } else {
                alert("Please enter a valid numeric value.");
            }
        });

        // --- Start Application ---
        startDataStream();
    </script>
</body>
</html>
```

### How this code demonstrates the solution:
* **The Visualizer:** Standard rendering with `Chart.js`. Smooth, reactive line curve animation configured for high performance, updating variables immediately inside the Canvas using custom viewport settings.
* **Stream Controller Form:** Collects browser form events. Updates the UI on submission and dynamically destroys and recreates the active browser event-loop interval tracking thread (`setInterval`) based on user timing inputs.
* **Manual Injection Form:** Accepts a custom float metric, sanitizes/validates the input inside pure `<language>JavaScript</language>` client-side script, pushes the new coordinate onto the graph, and translates the layout dynamically without wiping background configurations.

