    <script>
        // --- State Management ---
        let streamIntervalId = null;
        let isPaused = false;
        let updateSpeed = 1000; // ms
        let minVal = 10;
        let maxVal = 80;
        const maxDataPoints = 20; // Keep chart from overflowing
        const historicalData = [];

        // --- DOM Elements ---
        const kpiCurrent = document.getElementById('kpi-current');
        const kpiPeak = document.getElementById('kpi-peak');
        const kpiAvg = document.getElementById('kpi-avg');
        const btnPause = document.getElementById('btn-pause');
        const statusIndicator = document.getElementById('status-indicator');
        const statusText = document.getElementById('status-text');

        // Forms
        const formConfig = document.getElementById('form-config');
        const formInject = document.getElementById('form-inject');

        // --- Chart.js Initialization ---
        const ctx = document.getElementById('realtimeChart').getContext('2d');
        const chart = new Chart(ctx, {
            type: 'line',
            data: {
                labels: [],
                datasets: [{
                    label: 'System CPU Load (%)',
                    data: [],
                    borderColor: '#3b82f6', // blue-500
                    backgroundColor: 'rgba(59, 130, 246, 0.1)',
                    fill: true,
                    tension: 0.4,
                    borderWidth: 3,
                    pointBackgroundColor: '#3b82f6'
                }]
            },
            options: {
                responsive: true,
                maintainAspectRatio: false,
                plugins: { legend: { display: false } },
                scales: {
                    x: { grid: { color: '#374151' }, ticks: { color: '#9ca3af' } },
                    y: { min: 0, max: 120, grid: { color: '#374151' }, ticks: { color: '#9ca3af' } }
                }
            }
        });

        // --- Business Logic ---

        // Generates dummy data simulating CPU fluctuations
        function generateRandomMetric(min, max) {
            return Math.floor(Math.random() * (max - min + 1) + min);
        }

        // Appends data to chart, handles sliding window and KPIs
        function appendData(value) {
            const now = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' });

            chart.data.labels.push(now);
            chart.data.datasets[0].data.push(value);
            historicalData.push(value);

            // Shift data window if limit exceeded
            if (chart.data.labels.length > maxDataPoints) {
                chart.data.labels.shift();
                chart.data.datasets[0].data.shift();
            }

            chart.update('none'); // Update without full, slow re-render animation
            updateKPIs(value);
        }

        // Computes and updates screen stats
        function updateKPIs(latestVal) {
            kpiCurrent.innerText = `${latestVal.toFixed(1)}%`;

            const peak = Math.max(...historicalData);
            kpiPeak.innerText = `${peak.toFixed(1)}%`;

            const sum = historicalData.reduce((a, b) => a + b, 0);
            const avg = sum / historicalData.length;
            kpiAvg.innerText = `${avg.toFixed(1)}%`;
        }

        // Starts/Restarts the simulator loop
        function startDataStream() {
            if (streamIntervalId) clearInterval(streamIntervalId);

            streamIntervalId = setInterval(() => {
                if (!isPaused) {
                    const nextVal = generateRandomMetric(minVal, maxVal);
                    appendData(nextVal);
                }
            }, updateSpeed);
        }

        // --- Event & Form Handlers ---

        // Toggle Stream Pause
        btnPause.addEventListener('click', () => {
            isPaused = !isPaused;
            if (isPaused) {
                btnPause.innerText = "Resume Feed";
                btnPause.classList.replace('bg-gray-700', 'bg-emerald-600');
                btnPause.classList.replace('hover:bg-gray-600', 'hover:bg-emerald-500');
                statusIndicator.className = "h-3.5 w-3.5 rounded-full bg-amber-500";
                statusText.innerText = "Paused";
                statusText.className = "text-sm font-medium text-amber-400";
            } else {
                btnPause.innerText = "Pause Feed";
                btnPause.classList.replace('bg-emerald-600', 'bg-gray-700');
                btnPause.classList.replace('hover:bg-emerald-500', 'hover:bg-gray-600');
                statusIndicator.className = "h-3.5 w-3.5 rounded-full bg-emerald-500 animate-pulse";
                statusText.innerText = "Live Connection";
                statusText.className = "text-sm font-medium text-emerald-400";
            }
        });

        // Form 1: Handle stream interval/ranges configuration
        formConfig.addEventListener('submit', (event) => {
            event.preventDefault(); // Stop page reload

            const rawInterval = parseInt(document.getElementById('input-interval').value);
            const rawMin = parseInt(document.getElementById('input-min').value);
            const rawMax = parseInt(document.getElementById('input-max').value);

            // Basic Form Validation
            if (rawMin >= rawMax) {
                alert("Error: Minimum value must be strictly less than the Maximum value.");
                return;
            }

            // Apply validated state
            updateSpeed = rawInterval;
            minVal = rawMin;
            maxVal = rawMax;

            // Restart stream with new frequency
            startDataStream();

            // Visual submit feedback
            const submitBtn = formConfig.querySelector('button[type="submit"]');
            submitBtn.innerText = "Settings Applied ✓";
            submitBtn.classList.replace('bg-blue-600', 'bg-emerald-600');
            setTimeout(() => {
                submitBtn.innerText = "Apply Stream Settings";
                submitBtn.classList.replace('bg-emerald-600', 'bg-blue-600');
            }, 1500);
        });

        // Form 2: Handle manual spike injection
        formInject.addEventListener('submit', (event) => {
            event.preventDefault();

            const injectVal = parseFloat(document.getElementById('input-inject-val').value);

            // Manual inject works even if stream is paused
            appendData(injectVal);

            // Clear input form
            document.getElementById('input-inject-val').value = '';

            // Visual submit feedback
            const submitBtn = formInject.querySelector('button[type="submit"]');
            submitBtn.innerText = "Spike Injected! ⚡";
            setTimeout(() => {
                submitBtn.innerText = "Trigger Data Spike";
            }, 1500);
        });

        // --- Run App ---
        startDataStream();
    </script>
</body>
</html>
```

### Why this architecture works:
*   **Stateful Forms:** When you submit the "Stream Configuration" form, the JavaScript engine intercepts the submit event (`event.preventDefault()`), validates the inputs (ensuring `Min < Max`), alters the core operational state, and resets the telemetry polling rate instantly.
*   **Real-time UI Reactivity:** The "Trigger Data Spike" form injects custom data outside of the automated interval cycle, instantly forcing the Chart to re-draw and calculations to aggregate. 
*   **Data Bound Elements:** All KPI cards dynamically re-calculate running statistics using pure JavaScript Array methods (`reduce()`, `Math.max()`) on every tick.

To build a modern, privacy-focused tracker blocker, we must use **Manifest V3**—the current standard for browser extensions. 

We will use JavaScript and the **`declarativeNetRequest` (DNR) API**. This API is highly recommended for privacy extensions because the browser handles the blocking natively. This means the extension doesn't need to inspect your private browsing history or web traffic directly, making it incredibly secure and fast.

Here is the complete codebase for a lightweight, privacy-focused tracking script blocker.

