### 3. `background.js`
The background service worker runs in the background. It listens for when the user toggles the extension "ON" or "OFF" in the UI and dynamically enables or disables the rules.

```javascript
// Set default state to enabled on installation
chrome.runtime.onInstalled.addListener(() => {
  chrome.storage.local.set({ enabled: true });
});

// Watch for changes to the state to toggle blocking rules on/off
chrome.storage.onChanged.addListener((changes) => {
  if (changes.enabled) {
    const isEnabled = changes.enabled.newValue;

    chrome.declarativeNetRequest.updateEnabledRulesets({
      [isEnabled ? "enableRulesetIds" : "disableRulesetIds"]: ["tracker_ruleset"]
    });
  }
});
```

