### 5. `popup.js`
This script connects the HTML toggle switch to the chrome storage API, enabling real-time user control.

```javascript
const toggle = document.getElementById('toggle');
const statusText = document.getElementById('statusText');

// Load current state when opening the popup
chrome.storage.local.get('enabled', (data) => {
  const isEnabled = data.enabled !== false; // default true
  toggle.checked = isEnabled;
  updateUI(isEnabled);
});

// Update state when toggle is clicked
toggle.addEventListener('change', () => {
  const isEnabled = toggle.checked;
  chrome.storage.local.set({ enabled: isEnabled });
  updateUI(isEnabled);
});

function updateUI(isEnabled) {
  if (isEnabled) {
    statusText.textContent = "Shield Active";
    statusText.style.color = "#2ecc71";
  } else {
    statusText.textContent = "Shield Disabled";
    statusText.style.color = "#e74c3c";
  }
}
```

