### 5. Popup Logic (`popup.ts`)
This TypeScript file handles the UI interaction. When the user clicks the toggle button, it dynamically registers/deregisters the ruleset using `chrome.declarativeNetRequest`.

```typescript
// popup.ts

const statusText = document.getElementById("status-text") as HTMLSpanElement;
const toggleBtn = document.getElementById("toggle-btn") as HTMLButtonElement;

// Update UI based on state
function updateUI(isEnabled: boolean): void {
  if (isEnabled) {
    statusText.textContent = "Active";
    statusText.className = "status";
    toggleBtn.textContent = "Disable Blocker";
    toggleBtn.className = "toggle-btn";
  } else {
    statusText.textContent = "Inactive";
    statusText.className = "status disabled";
    toggleBtn.textContent = "Enable Blocker";
    toggleBtn.className = "toggle-btn off";
  }
}

// Toggle ruleset on/off in Chrome/Firefox browser engine
async function setBlockingState(enable: boolean): Promise<void> {
  const rulesetId = "blocklist";

  if (enable) {
    await chrome.declarativeNetRequest.updateEnabledRulesets({
      enableRulesetIds: [rulesetId]
    });
  } else {
    await chrome.declarativeNetRequest.updateEnabledRulesets({
      disableRulesetIds: [rulesetId]
    });
  }

  await chrome.storage.local.set({ blockingEnabled: enable });
  updateUI(enable);
}

// On Popup Open: Load saved state
chrome.storage.local.get(["blockingEnabled"], (result) => {
  const isEnabled = result.blockingEnabled ?? true;
  updateUI(isEnabled);
});

// Add click listener to toggle button
toggleBtn.addEventListener("click", async () => {
  chrome.storage.local.get(["blockingEnabled"], async (result) => {
    const currentState = result.blockingEnabled ?? true;
    await setBlockingState(!currentState);
  });
});
```

