### 5. Controller Logic (`popup.js`)
This script communicates with the browser's extension API to enable or disable the rule list when the user flips the UI toggle switch.

```javascript
document.addEventListener('DOMContentLoaded', async () => {
  const toggle = document.getElementById('toggle-shield');
  const statusText = document.getElementById('status-text');

  // Check current ruleset state on popup load
  const enabledRulesets = await chrome.declarativeNetRequest.getEnabledRulesets();
  const isEnabled = enabledRulesets.includes('tracker_rules');

  toggle.checked = isEnabled;
  updateUI(isEnabled);

  // Toggle ruleset on switch change
  toggle.addEventListener('change', async () => {
    const shouldEnable = toggle.checked;

    await chrome.declarativeNetRequest.updateEnabledRulesets({
      [shouldEnable ? 'enableRulesetIds' : 'disableRulesetIds']: ['tracker_rules']
    });

    updateUI(shouldEnable);
  });

  function updateUI(active) {
    if (active) {
      statusText.textContent = "Shields Active";
      statusText.className = "active";
    } else {
      statusText.textContent = "Shields Disabled";
      statusText.className = "disabled";
    }
  }
});
```

