### 4. `popup.js`
This script handles the UI toggle switch. It dynamically enables or disables the static rule set we defined in `rules.json` depending on the user's preference.

```javascript
const toggle = document.getElementById('toggle-blocker');

// Load the current state of the blocker
chrome.storage.local.get(['blockerEnabled'], (result) => {
  // Default to enabled (true) if not set
  const enabled = result.blockerEnabled !== false;
  toggle.checked = enabled;
});

// Watch for changes in the toggle switch
toggle.addEventListener('change', () => {
  const isChecked = toggle.checked;

  chrome.storage.local.set({ blockerEnabled: isChecked }, () => {
    if (isChecked) {
      // Enable the static ruleset
      chrome.declarativeNetRequest.updateEnabledRulesets({
        enableRulesetIds: ["tracker_rules"]
      });
    } else {
      // Disable the static ruleset
      chrome.declarativeNetRequest.updateEnabledRulesets({
        disableRulesetIds: ["tracker_rules"]
      });
    }
  });
});
```

### 5. `background.js`
This service worker runs in the background. It ensures that when the browser starts up, the extension respects the user's saved choice (enabled/disabled) from the local storage.

```javascript
chrome.runtime.onInstalled.addListener(() => {
  // Ensure the default state is Enabled on clean installs
  chrome.storage.local.get(['blockerEnabled'], (result) => {
    const isEnabled = result.blockerEnabled !== false;

    chrome.declarativeNetRequest.updateEnabledRulesets({
      [isEnabled ? 'enableRulesetIds' : 'disableRulesetIds']: ["tracker_rules"]
    });
  });
});
