  const domain = input.value.trim().toLowerCase();
  if (!domain) return;

  // Retrieve current dynamic rules
  const currentRules = await chrome.declarativeNetRequest.getDynamicRules();

  // Create a unique ID for the new rule
  const nextId = currentRules.length > 0 ? Math.max(...currentRules.map(r => r.id)) + 1 : 100;

  const newRule = {
    id: nextId,
    priority: 1,
    action: { type: "block" },
    condition: {
      urlFilter: `||${domain}`,
      resourceTypes: ["script", "xmlhttprequest", "sub_frame"]
    }
  };

  // Register the new rule in the browser's engine
  await chrome.declarativeNetRequest.updateDynamicRules({
    addRules: [newRule]
  });

  input.value = '';
  updateUI();
});

// Update the list in the UI
async function updateUI() {
  blockList.innerHTML = '';
  const rules = await chrome.declarativeNetRequest.getDynamicRules();

  rules.forEach(rule => {
    const li = document.createElement('li');
    // Extract domain from urlFilter
    const domain = rule.condition.urlFilter.replace('||', '');
    li.textContent = domain;

    const removeSpan = document.createElement('span');
    removeSpan.textContent = ' ✕';
    removeSpan.className = 'remove-btn';
    removeSpan.onclick = () => removeDomain(rule.id);

    li.appendChild(removeSpan);
    blockList.appendChild(li);
  });
}

// Remove a dynamic rule
async function removeDomain(ruleId) {
  await chrome.declarativeNetRequest.updateDynamicRules({
    removeRuleIds: [ruleId]
  });
  updateUI();
}
