### 4. `popup.js` (The Logic)
This file handles adding and removing **dynamic rules** (rules defined by the user on the fly). This utilizes JavaScript to interface directly with Chrome’s rule-matching engine.

```javascript
// Initialize UI and load existing custom blocked domains
document.addEventListener('DOMContentLoaded', async () => {
  renderCustomRules();

  document.getElementById('addBtn').addEventListener('click', addDomain);
  document.getElementById('domainInput').addEventListener('keypress', (e) => {
    if (e.key === 'Enter') addDomain();
  });
});

// Fetch current dynamic rules and display them
async function renderCustomRules() {
  const rules = await chrome.declarativeNetRequest.getDynamicRules();
  const list = document.getElementById('customList');
  list.innerHTML = '';

  rules.forEach(rule => {
    const li = document.createElement('li');
    // Extract the blocked domain name from the filter
    const domain = rule.condition.urlFilter.replace('||', '');

    li.innerHTML = `
      <span>${domain}</span>
      <span class="remove-btn" data-id="${rule.id}">✕</span>
    `;
    list.appendChild(li);
  });

  // Attach event listeners to remove buttons
  document.querySelectorAll('.remove-btn').forEach(btn => {
    btn.addEventListener('click', (e) => {
      const ruleId = parseInt(e.target.getAttribute('data-id'));
      removeDomain(ruleId);
    });
  });
}

// Add a custom domain to block
async function addDomain() {
  const input = document.getElementById('domainInput');
  const domain = input.value.trim().toLowerCase();

  if (!domain) return;

  // Clean the domain input to prevent invalid rules (e.g. remove protocols)
  const cleanDomain = domain.replace(/^(?:https?:\/\/)?(?:www\.)?/i, "");

  const rules = await chrome.declarativeNetRequest.getDynamicRules();

  // Dynamic rules need unique IDs. We'll increment from the highest existing ID.
  const newId = rules.reduce((max, r) => r.id > max ? r.id : max, 100) + 1;

  const newRule = {
    id: newId,
    priority: 1,
    action: { type: "block" },
    condition: {
      urlFilter: `||${cleanDomain}`,
      resourceTypes: ["script", "xmlhttprequest", "sub_frame"]
    }
  };

  // Inject rule into the browser's Declarative Net Request engine
  await chrome.declarativeNetRequest.updateDynamicRules({
    addRules: [newRule]
  });

  input.value = '';
  renderCustomRules();
}

// Remove a dynamically blocked domain
async function removeDomain(ruleId) {
  await chrome.declarativeNetRequest.updateDynamicRules({
    removeRuleIds: [ruleId]
  });
  renderCustomRules();
}
```

