  const statusLabel = document.getElementById('status-label');

  // Load the current state of the blocker
  chrome.storage.local.get({ enabled: true }, (result) => {
    toggle.checked = result.enabled;
    updateUI(result.enabled);
  });

  // Handle toggling the blocker on and off
  toggle.addEventListener('change', () => {
    const isEnabled = toggle.checked;

    // Save state to local storage
    chrome.storage.local.set({ enabled: isEnabled }, () => {
      updateUI(isEnabled);

      // Dynamically update the browser's rule engine
      chrome.declarativeNetRequest.updateEnabledRulesets({
        [isEnabled ? "enableRulesetIds" : "disableRulesetIds"]: ["tracker_rules"]
      });
    });
  });

  function updateUI(isEnabled) {
    if (isEnabled) {
      statusLabel.textContent = "Protection Active";
      statusLabel.style.color = "#10b981"; // Active Green
    } else {
      statusLabel.textContent = "Protection Disabled";
      statusLabel.style.color = "#ef4444"; // Inactive Red
    }
  }
