### 3. Background Service Worker (`background.ts`)
This TypeScript file manages the extension state (enabled/disabled). When the user toggles the extension off, it dynamically disables the rule engine.

```typescript
// Type definition for storage state
interface ExtensionState {
  isEnabled: boolean;
}

// Set default state on installation
chrome.runtime.onInstalled.addListener(() => {
  chrome.storage.local.set({ isEnabled: true });
});

// Watch for state changes to enable/disable the blocking rules
chrome.storage.onChanged.addListener((changes, namespace) => {
  if (namespace === 'local' && changes.isEnabled) {
    const isEnabled = changes.isEnabled.newValue;
    updateBlockingState(isEnabled);
  }
});

/**
 * Enables or disables the declarativeNetRequest ruleset
 */
function updateBlockingState(enable: boolean): void {
  chrome.declarativeNetRequest.updateEnabledRulesets({
    [enable ? "enableRulesetIds" : "disableRulesetIds"]: ["tracker_rules"]
  }).then(() => {
    console.log(`Tracking protection is now ${enable ? "ENABLED" : "DISABLED"}.`);
  }).catch((err) => {
    console.error("Failed to update blocking rules:", err);
  });
}
```

