### 5. Popup Controller (`popup.ts`)
This TypeScript file syncs the UI switch with our storage state.

```typescript
const toggleInput = document.getElementById('toggle-blocker') as HTMLInputElement;
const statusText = document.getElementById('status') as HTMLDivElement;

// Get current state when opening the popup
chrome.storage.local.get(['isEnabled'], (result) => {
  const isEnabled = result.isEnabled !== false; // Default to true
  toggleInput.checked = isEnabled;
  updateUI(isEnabled);
});

// Update state when user clicks the toggle
toggleInput.addEventListener('change', () => {
  const isEnabled = toggleInput.checked;
  chrome.storage.local.set({ isEnabled });
  updateUI(isEnabled);
});

function updateUI(isEnabled: boolean): void {
  if (isEnabled) {
    statusText.textContent = "Blocking Active";
    statusText.style.color = "green";
  } else {
    statusText.textContent = "Blocking Paused";
    statusText.style.color = "red";
  }
}
```

