        // Draw stock background rect
        const rects = stocks.append("rect")
            .attr("id", d => `rect-${d.data.symbol}`)
            .attr("width", d => d.x1 - d.x0)
            .attr("height", d => d.y1 - d.y0)
            .attr("fill", d => colorScale(d.data.change))
            .attr("stroke", "#0f172a")
            .attr("stroke-width", "1.5px")
            .attr("rx", 3);

        // Create Text Groups (handles scaling symbol and percentage inside the tile)
        const labels = stocks.append("g")
            .attr("class", "stock-label")
            .attr("id", d => `label-${d.data.symbol}`);

        // Stock Symbol text
        labels.append("text")
            .attr("class", "symbol font-extrabold text-white text-center")
            .attr("text-anchor", "middle")
