        function positionLabels() {
            stocks.each(function(d) {
                const w = d.x1 - d.x0;
                const h = d.y1 - d.y0;
                const g = d3.select(this).select(".stock-label");

                const sym = g.select(".symbol");
                const chg = g.select(".change");

