                // Compute smart font sizes based on rectangle dimension limits
                const symbolSize = Math.max(9, Math.min(w / 4.5, h / 3.5, 16));
                const changeSize = symbolSize * 0.75;

                sym.attr("font-size", `${symbolSize}px`)
                   .attr("x", w / 2)
                   .attr("y", h / 2 - (changeSize / 3));

                chg.attr("font-size", `${changeSize}px`)
                   .attr("x", w / 2)
                   .attr("y", h / 2 + changeSize);
            });
