                }

                tooltip.classed("hidden", false);
            })
            .on("mousemove", function(event) {
                // Smooth tooltip positioning next to cursor offset
                tooltip
                    .style("left", (event.clientX + 15) + "px")
                    .style("top", (event.clientY + 15) + "px");
            })
            .on("mouseleave", function(event, d) {
                d3.select(this).select("rect")
                    .attr("stroke", "#0f172a")
                    .attr("stroke-width", "1.5px");
                tooltip.classed("hidden", true);
            });

        // 8. Handle Window Resizing dynamically
        window.addEventListener("resize", () => {
            width = container.clientWidth;
            height = container.clientHeight;

            svg.attr("viewBox", `0 0 ${width} ${height}`);
            treemap.size([width, height]);
            treemap(root);

            // Re-render sectors
            mainGroup.selectAll(".sector")
                .data(root.children)
                .select("text")
                .attr("x", d => d.x0 + 6)
                .attr("y", d => d.y0 + 15);

            // Re-render stocks
            mainGroup.selectAll(".stock")
                .data(root.leaves())
                .attr("transform", d => `translate(${d.x0},${d.y0})`)
                .select("rect")
                .attr("width", d => d.x1 - d.x0)
                .attr("height", d => d.y1 - d.y0);

            positionLabels();
        });

        // 9. Simulation Loop (Generates Real-Time Updates mimicking WebSockets)
        setInterval(() => {
            // Select 3 random stocks to update every tick
            const leaves = root.leaves();
            const numberOfTicks = 3;

            for (let i = 0; i < numberOfTicks; i++) {
                const randomStock = leaves[Math.floor(Math.random() * leaves.length)];

                // Keep values inside realistic boundaries
                const deltaChange = (Math.random() - 0.5) * 0.4; // max shift +/- 0.2% per tick
                let newChange = randomStock.data.change + deltaChange;
                newChange = Math.max(-5, Math.min(5, newChange)); // bounds check (-5% to +5%)

                const percentShift = 1 + (deltaChange / 100);
                const newPrice = randomStock.data.price * percentShift;

                // Update original state data
                randomStock.data.change = newChange;
                randomStock.data.price = newPrice;

                // Select DOM elements corresponding to updated stocks
                const rect = d3.select(`#rect-${randomStock.data.symbol}`);
                const labelGroup = d3.select(`#label-${randomStock.data.symbol}`);

                // Smoothly color transition the updated stock block
                rect.transition()
                    .duration(500)
                    .attr("fill", colorScale(newChange));

                // Instantly visualizes a "flash highlight frame" around updated stock
                rect.attr("stroke", deltaChange > 0 ? "#10b981" : "#ef4444")
                    .attr("stroke-width", "2.5px")
                    .transition()
                    .delay(200)
                    .duration(400)
                    .attr("stroke", "#0f172a")
                    .attr("stroke-width", "1.5px");

                // Update text displays inside labels
                labelGroup.select(".change")
                    .text(`${newChange > 0 ? '+' : ''}${newChange.toFixed(2)}%`);
            }
        }, 1500); // Trigger ticks every 1.5 seconds

    </script>
