        ctx.fillRect(x, y, w, h);

        // Draw hover border
        if (node === hoveredNode) {
            ctx.strokeStyle = "#fff";
            ctx.lineWidth = 2 / transform.k;
            ctx.strokeRect(x, y, w, h);
        } else {
            ctx.strokeStyle = "#121212";
            ctx.lineWidth = 1 / transform.k;
            ctx.strokeRect(x, y, w, h);
        }

        // Draw Text Labels inside Node (Size optimized dynamically based on zoom & container size)
        const rectWidthOnScreen = w * transform.k;
        const rectHeightOnScreen = h * transform.k;

        // Only render labels if there is enough space on screen
        if (rectWidthOnScreen > 45 && rectHeightOnScreen > 30) {
            ctx.save();
            ctx.rect(x, y, w, h);
            ctx.clip();

            ctx.textAlign = "center";
            ctx.textBaseline = "middle";

            // Symbol Ticker
            ctx.fillStyle = "#fff";
            const fontSizeSymbol = Math.min(15, rectWidthOnScreen / 5);
            ctx.font = `bold ${fontSizeSymbol / transform.k}px sans-serif`;
            ctx.fillText(node.data.name, x + w / 2, y + h / 2 - (6 / transform.k));

            // Price Change String
            const sign = node.data.change >= 0 ? "+" : "";
            ctx.fillStyle = "rgba(255,255,255,0.85)";
            const fontSizePercent = Math.min(12, rectWidthOnScreen / 6);
            ctx.font = `${fontSizePercent / transform.k}px sans-serif`;
            ctx.fillText(`${sign}${node.data.change.toFixed(2)}%`, x + w / 2, y + h / 2 + (10 / transform.k));

            ctx.restore();
        }
    });

    ctx.restore();
}

// Green to Red color map for stock market fluctuations
function getColorForChange(change) {
    // Range normalized at [-3%, +3%]
    const limit = 3.0; 
    const norm = Math.max(-1, Math.min(1, change / limit));

    if (norm > 0) {
        // Linear interpolation to Neon Green
        const green = Math.round(40 + (200 * norm));
        return `rgb(10, ${green}, 40)`;
    } else {
        // Linear interpolation to Hot Red
        const red = Math.round(40 + (210 * Math.abs(norm)));
        return `rgb(${red}, 15, 30)`;
    }
}

// ==========================================
// 5. INTERACTION & INTERPOLATION (Hover Tooltip)
// ==========================================
canvas.addEventListener("mousemove", (event) => {
    const rect = canvas.getBoundingClientRect();
    const mouseX = event.clientX - rect.left;
    const mouseY = event.clientY - rect.top;

    // Convert Screen Coordinate system to Canvas Local Transform System
    const [localX, localY] = transform.invert([mouseX, mouseY]);

    // Find overlapping Stock Node
    let found = null;
    if (rootNode) {
        const leaves = rootNode.leaves();
        for (let i = 0; i < leaves.length; i++) {
            const node = leaves[i];
            if (localX >= node.x0 && localX < node.x1 && localY >= node.y0 && localY < node.y1) {
                found = node;
                break;
            }
        }
    }

    if (found) {
        hoveredNode = found;
        showTooltip(event, found.data);
        requestRender();
    } else {
        if (hoveredNode !== null) {
            hoveredNode = null;
            hideTooltip();
            requestRender();
        }
    }
});

canvas.addEventListener("mouseleave", () => {
    hoveredNode = null;
    hideTooltip();
    requestRender();
});

function showTooltip(event, data) {
    const containerRect = container.getBoundingClientRect();
    const x = event.clientX - containerRect.left + 15;
    const y = event.clientY - containerRect.top + 15;

    const changeClass = data.change >= 0 ? "val-up" : "val-down";
    const sign = data.change >= 0 ? "+" : "";

    tooltip.style.left = `${x}px`;
    tooltip.style.top = `${y}px`;
    tooltip.style.display = "block";
    tooltip.innerHTML = `
        <div class="tooltip-row"><strong>${data.name}</strong> <span>USD</span></div>
        <hr style="border: 0; border-top: 1px solid #333; margin: 6px 0;" />
        <div class="tooltip-row"><span class="label">Price:</span><strong>$${data.price.toFixed(2)}</strong></div>
        <div class="tooltip-row"><span class="label">Change:</span><span class="${changeClass}">${sign}${data.change.toFixed(2)}%</span></div>
        <div class="tooltip-row"><span class="label">Cap Size:</span><span>$${data.value}B</span></div>
    `;
}

function hideTooltip() {
    tooltip.style.display = "none";
}

// ==========================================
// 6. REAL-TIME DATA SIMULATOR (WebSocket Style)
// ==========================================
setInterval(() => {
    // Randomly select 2-4 stock tickers to tick
    const count = Math.floor(Math.random() * 3) + 1;
    const tickers = Object.keys(stockLookup);

    for (let i = 0; i < count; i++) {
        const randomTicker = tickers[Math.floor(Math.random() * tickers.length)];
        const stock = stockLookup[randomTicker];

        // Simulating realistic Brownian price motion bounds (-0.5% to +0.5%)
        const tickPercent = (Math.random() - 0.5) * 0.4;
        stock.price *= (1 + (tickPercent / 100));
        stock.change += tickPercent;

        // Boundaries capping values inside realistic daily percentage limits [-8% to +8%]
        if (stock.change > 8) stock.change = 8;
        if (stock.change < -8) stock.change = -8;
    }

    // Trigger frame updates
    requestRender();
}, 200); // Ticks happen every 200ms

// ==========================================
// 7. WINDOW ACTIONS & EVENT BINDINGS
// ==========================================
document.getElementById("reset-zoom").addEventListener("click", () => {
    d3.select(canvas).transition().duration(400).call(zoom.transform, d3.zoomIdentity);
});

window.addEventListener("resize", () => {
    width = container.clientWidth;
    height = container.clientHeight;

    devicePixelRatio = window.devicePixelRatio || 1;
    canvas.width = width * devicePixelRatio;
    canvas.height = height * devicePixelRatio;

    ctx.resetTransform();
    ctx.scale(devicePixelRatio, devicePixelRatio);

    computeTreemap();
    requestRender();
});

// Run Initial Treemap Calculations & Paint screen
computeTreemap();
requestRender();
</script>
</body>
</html>
```

### Key Performance Features Built into this Code:
1. **Dynamic Frame-Rate Throttling:** Instead of redrawing the entire screen synchronously on every event (which would lock up CPU cycles during high-speed zooming), it uses a flag-based request loop utilizing `requestAnimationFrame`.
2. **Culling / Detail Thresholding:** The heatmap checks how large a stock block is on screen *at current zoom scaling*. If a block scales below 45x30 pixels, it avoids drawing text inside it, saving massive amounts of canvas draw cycles.
3. **Sub-pixel Vector Prevention:** High-DPI screens (Retina, 4K displays) can look incredibly blurry with native canvas contexts. The coordinate space scales smoothly based on `devicePixelRatio` maintaining razor-sharp text and borders.
4. **Pointer Transformation Math:** Handles inverted mouse pointer coordinate projection matrix mapping back onto the canvas coordinate transform, allowing perfectly synchronized pixel-accurate tooltips even when zoomed and panned.

