                        { symbol: "MRK", name: "Merck & Co. Inc.", value: 320, price: 125.10, change: 0.7 }
                    ]
                }
            ]
        };

        // --- 2. SETUP DIMENSIONS & SCALES ---
        const container = document.getElementById('heatmap-container');
        let width = container.clientWidth;
        let height = container.clientHeight;

        const svg = d3.select("#heatmap")
            .attr("width", width)
            .attr("height", height);

        // Group holding all visual elements, used for zoom/pan
        const g = svg.append("g");

        // Color scale: Red (-3% or less) -> Dark Gray (0%) -> Green (+3% or more)
        const colorScale = d3.scaleLinear()
            .domain([-3, 0, 3])
            .range(["#ef4444", "#1e293b", "#22c55e"])
            .interpolate(d3.interpolateRgb)
            .clamp(true);

        // --- 3. D3 TREEMAP LAYOUT ---
        const treemap = d3.treemap()
            .size([width, height])
            .paddingOuter(4)
            .paddingTop(24) // Extra space for sector headers
            .paddingInner(1)
            .round(true);

        // Process hierarchy
        const root = d3.hierarchy(marketData)
            .sum(d => d.value)
            .sort((a, b) => b.value - a.value);

        treemap(root);

        // --- 4. ZOOM AND PAN SETUP ---
        const zoom = d3.zoom()
            .scaleExtent([1, 10]) // Zoom limits: 1x to 10x
            .on("zoom", (event) => {
                g.attr("transform", event.transform);
                // Dynamically scale stroke widths and labels to preserve visual balance
                g.selectAll(".sector-boundary").style("stroke-width", 2 / event.transform.k);
                g.selectAll(".stock-label").style("font-size", d => Math.max(8, Math.min(14, d.dx / 6)) / event.transform.k + "px");
            });

        svg.call(zoom);

        document.getElementById("reset-zoom").addEventListener("click", () => {
            svg.transition()
               .duration(750)
               .call(zoom.transform, d3.zoomIdentity);
        });

        // --- 5. INITIAL RENDERING ---

        // Map elements into an easy lookup structure for updates
        const stockMap = {};

        // Sector Groups
        const sectors = g.selectAll(".sector")
            .data(root.descendants().filter(d => d.depth === 1))
            .enter()
            .append("g")
            .attr("class", "sector");

        // Sector Header Backgrounds
        sectors.append("rect")
            .attr("x", d => d.x0)
            .attr("y", d => d.y0)
            .attr("width", d => d.x1 - d.x0)
            .attr("height", 24)
            .attr("fill", "#1e293b")
            .attr("opacity", 0.8);

        // Sector Header Texts
        sectors.append("text")
            .attr("x", d => d.x0 + 8)
            .attr("y", d => d.y0 + 16)
            .text(d => d.data.name)
            .attr("fill", "#94a3b8")
            .attr("font-size", "11px")
            .attr("font-weight", "bold");

        // Individual Stock Nodes (Leaves)
        const nodes = g.selectAll(".node")
            .data(root.leaves())
            .enter()
            .append("g")
            .attr("class", "node")
            .attr("transform", d => `translate(${d.x0},${d.y0})`);

        // Stock Background Rects
        nodes.append("rect")
            .attr("id", d => "rect-" + d.data.symbol)
            .attr("class", "tile")
            .attr("width", d => d.x1 - d.x0)
            .attr("height", d => d.y1 - d.y0)
            .attr("fill", d => {
                stockMap[d.data.symbol] = d; // populate lookup table
                return colorScale(d.data.change);
            })
            .attr("stroke", "#0f172a")
            .attr("stroke-width", 1)
            // Interactive Hover Events
            .on("mouseover", (event, d) => showTooltip(event, d.data))
            .on("mousemove", moveTooltip)
            .on("mouseleave", hideTooltip);

        // Stock Text Wrap / Labels
        nodes.each(function(d) {
            const nodeWidth = d.x1 - d.x0;
            const nodeHeight = d.y1 - d.y0;
            const self = d3.select(this);

            // Only render text labels if node is big enough
            if (nodeWidth > 45 && nodeHeight > 35) {
                // Symbol (e.g. AAPL)
                self.append("text")
                    .attr("class", "stock-label font-bold")
                    .attr("x", nodeWidth / 2)
                    .attr("y", nodeHeight / 2 - 2)
                    .attr("text-anchor", "middle")
                    .attr("fill", "#ffffff")
                    .style("font-size", Math.min(14, nodeWidth / 5) + "px")
                    .text(d.data.symbol);

                // Percentage Change text
                self.append("text")
                    .attr("id", "text-" + d.data.symbol)
                    .attr("class", "stock-label opacity-90")
                    .attr("x", nodeWidth / 2)
                    .attr("y", nodeHeight / 2 + 12)
                    .attr("text-anchor", "middle")
                    .attr("fill", "#f8fafc")
                    .style("font-size", Math.min(11, nodeWidth / 6) + "px")
                    .text(formatChange(d.data.change));
            }
        });

        // --- 6. TOOLTIP LOGIC ---
        const tooltip = d3.select("#tooltip");

        function showTooltip(event, data) {
            tooltip.style("display", "block");
            d3.select("#tooltip-symbol").text(data.symbol);
            d3.select("#tooltip-name").text(data.name);
            d3.select("#tooltip-price").text(`$${data.price.toFixed(2)}`);

            const changeEl = d3.select("#tooltip-change");
            changeEl.text(formatChange(data.change));
            if (data.change >= 0) {
                changeEl.attr("class", "text-emerald-400");
            } else {
                changeEl.attr("class", "text-red-400");
            }

            d3.select("#tooltip-cap").text(`$${(data.value / 1000).toFixed(1)}T`);
        }

        function moveTooltip(event) {
            tooltip
                .style("left", (event.clientX + 15) + "px")
                .style("top", (event.clientY + 15) + "px");
        }

        function hideTooltip() {
            tooltip.style("display", "none");
        }

        function formatChange(val) {
            return (val >= 0 ? "+" : "") + val.toFixed(2) + "%";
        }

        // --- 7. SIMULATED REAL-TIME UPDATES (WebSocket Mimic) ---
        // Simulates server-side price feed ticks
        setInterval(() => {
            // Pick 3 random stocks to update simultaneously
            const symbols = Object.keys(stockMap);
            for (let i = 0; i < 3; i++) {
                const randomSymbol = symbols[Math.floor(Math.random() * symbols.length)];
                const node = stockMap[randomSymbol];

                // Calculate realistic price/percentage fluctuation
                const changeDelta = (Math.random() - 0.5) * 0.6; // step changes between -0.3% and +0.3%
                node.data.change = Math.max(-10, Math.min(10, node.data.change + changeDelta));
                node.data.price += node.data.price * (changeDelta / 100);

                // Update UI: Color of rect with smooth transition
                d3.select("#rect-" + randomSymbol)
                    .transition()
                    .duration(500)
                    .attr("fill", colorScale(node.data.change));

                // Update UI: Text node percentage
                d3.select("#text-" + randomSymbol)
                    .text(formatChange(node.data.change));
            }
        }, 800); // Trigger ticks every 800ms

        // --- 8. RESPONSIVENESS HANDLING ---
        window.addEventListener('resize', () => {
            width = container.clientWidth;
            height = container.clientHeight;
            svg.attr("width", width).attr("height", height);

            // Re-run treemap engine with new dimensions
            treemap.size([width, height]);
            treemap(root);

            // Re-render sectors
            g.selectAll(".sector rect")
                .attr("x", d => d.x0)
                .attr("y", d => d.y0)
                .attr("width", d => d.x1 - d.x0);

            g.selectAll(".sector text")
                .attr("x", d => d.x0 + 8)
                .attr("y", d => d.y0 + 16);

            // Re-render node groups
            g.selectAll(".node")
                .attr("transform", d => `translate(${d.x0},${d.y0})`);

            g.selectAll(".tile")
                .attr("width", d => d.x1 - d.x0)
                .attr("height", d => d.y1 - d.y0);

            // Re-position text elements
            g.selectAll(".node").each(function(d) {
                const nodeWidth = d.x1 - d.x0;
                const nodeHeight = d.y1 - d.y0;
                const self = d3.select(this);

                self.selectAll("text").remove(); // Wipe and rebuild text for simplicity

                if (nodeWidth > 45 && nodeHeight > 35) {
                    self.append("text")
                        .attr("class", "stock-label font-bold")
                        .attr("x", nodeWidth / 2)
                        .attr("y", nodeHeight / 2 - 2)
                        .attr("text-anchor", "middle")
                        .attr("fill", "#ffffff")
                        .style("font-size", Math.min(14, nodeWidth / 5) + "px")
                        .text(d.data.symbol);

                    self.append("text")
                        .attr("id", "text-" + d.data.symbol)
                        .attr("class", "stock-label opacity-90")
                        .attr("x", nodeWidth / 2)
                        .attr("y", nodeHeight / 2 + 12)
                        .attr("text-anchor", "middle")
                        .attr("fill", "#f8fafc")
                        .style("font-size", Math.min(11, nodeWidth / 6) + "px")
                        .text(formatChange(d.data.change));
                }
            });
        });
    </script>
</body>
</html>
