        });

        // --- 6. RENDER ENGINE (HTML5 Canvas Drawing) ---
        function render() {
            // Clear canvas
            ctx.save();
            ctx.clearRect(0, 0, width, height);

            // Apply zoom/pan transform matrix
            ctx.translate(transform.x, transform.y);
            ctx.scale(transform.k, transform.k);

