                ctx.fillRect(sector.x0, sector.y0, sector.x1 - sector.x0, sector.y1 - sector.y0);

                ctx.strokeStyle = '#333';
                ctx.lineWidth = 1 / transform.k;
                ctx.strokeRect(sector.x0, sector.y0, sector.x1 - sector.x0, sector.y1 - sector.y0);

