                        const flashColor = node.data.lastDirection === 'up' ? 'rgba(0, 255, 0, ' : 'rgba(255, 0, 0, ';
                        baseColor = d3.interpolateRgb(baseColor.toString(), flashColor + intensity + ')')(0.5);
