            partition(marketData.children, 0, 0, width, height, true, totalMarketCap, (sector, x, y, w, h) => {
                sectorNodes.push({ name: sector.name, x, y, w, h });

                // Padding inside sectors
                const pad = 4;
                const innerX = x + pad;
                const innerY = y + pad + 20; // Extra padding on top for sector label
                const innerW = w - pad * 2;
                const innerH = h - pad * 2 - 20;

                if (innerW > 0 && innerH > 0) {
                    const sectorWeight = sector.weight;
                    // 2. Position Individual Stocks inside Sector boundary
                    partition(sector.children, innerX, innerY, innerW, innerH, true, sectorWeight, (stock, sx, sy, sw, sh) => {
                        stockNodes.push({
                            ...stock,
                            x: sx, y: sy, w: sw, h: sh,
                            sectorName: sector.name
                        });
                    });
                }
            });
        }

        // Recursive binary tree partitioner
        function partition(nodes, x, y, w, h, vertical, totalWeight, callback) {
            if (nodes.length === 0) return;
            if (nodes.length === 1) {
                callback(nodes[0], x, y, w, h);
                return;
            }

            // Split array in two halves balancing weights
            let mid = 0;
            let sum = 0;
            const halfWeight = totalWeight / 2;

            for (let i = 0; i < nodes.length; i++) {
                sum += nodes[i].weight;
                if (sum >= halfWeight || i === nodes.length - 2) {
                    mid = i + 1;
                    break;
                }
            }

            const leftPart = nodes.slice(0, mid);
            const rightPart = nodes.slice(mid);
            const leftWeight = leftPart.reduce((s, n) => s + n.weight, 0);
            const ratio = leftWeight / totalWeight;

            if (vertical) {
                const splitW = w * ratio;
                partition(leftPart, x, y, splitW, h, !vertical, leftWeight, callback);
                partition(rightPart, x + splitW, y, w - splitW, h, !vertical, totalWeight - leftWeight, callback);
            } else {
                const splitH = h * ratio;
                partition(leftPart, x, y, w, splitH, !vertical, leftWeight, callback);
                partition(rightPart, x, y + splitH, w, h - splitH, !vertical, totalWeight - leftWeight, callback);
            }
        }

        // --- 4. GRAPHICS / RENDERING ENGINE ---
        function getStockColor(change) {
            // Cap visual intensity at +/- 3%
            const maxVal = 3.0;
            const intensity = Math.min(Math.abs(change) / maxVal, 1.0);

            if (change > 0) {
                // Interpolate from dark grey (neutral) to vibrant green
                const r = Math.round(18 - (18 * intensity));
                const g = Math.round(24 + (160 * intensity));
                const b = Math.round(27 + (50 * intensity));
                return `rgb(${r}, ${g}, ${b})`;
            } else if (change < 0) {
                // Interpolate from dark grey to vibrant red
                const r = Math.round(18 + (200 * intensity));
                const g = Math.round(24 - (10 * intensity));
                const b = Math.round(27 - (10 * intensity));
                return `rgb(${r}, ${g}, ${b})`;
            }
            return "#18181b"; // Flat Grey
        }

        function draw() {
            ctx.save();
            ctx.clearRect(0, 0, width, height);

            // Apply Pan & Zoom transformations
            ctx.translate(offsetX, offsetY);
            ctx.scale(scale, scale);

            const now = Date.now();

            // 1. Draw Sector boundaries
            ctx.strokeStyle = "#27272a";
            ctx.lineWidth = 1.5 / scale;
            sectorNodes.forEach(sector => {
                ctx.strokeRect(sector.x, sector.y, sector.w, sector.h);

                // Draw sector header if there's space
                if (sector.h * scale > 30 && sector.w * scale > 60) {
                    ctx.fillStyle = "#a1a1aa";
                    ctx.font = `bold ${Math.max(10, Math.min(12, sector.w * scale * 0.05))}px sans-serif`;
                    ctx.fillText(sector.name, sector.x + 6, sector.y + 16);
                }
            });

            // 2. Draw Stock Nodes
            stockNodes.forEach(node => {
                // Skip rendering nodes off-canvas (Frustum culling optimization)
                const screenX = node.x * scale + offsetX;
                const screenY = node.y * scale + offsetY;
                const screenW = node.w * scale;
                const screenH = node.h * scale;

                if (screenX + screenW < 0 || screenX > width || screenY + screenH < 0 || screenY > height) {
                    return;
                }

                // Base Rectangle
                ctx.fillStyle = getStockColor(node.change);
                ctx.fillRect(node.x, node.y, node.w, node.h);

                // Flash overlay on price update ticks
                if (activeFlashes.has(node.symbol)) {
                    const elapsed = now - activeFlashes.get(node.symbol);
                    if (elapsed < 300) {
                        const alpha = (1 - (elapsed / 300)) * 0.45;
                        ctx.fillStyle = node.change > 0 ? `rgba(34, 197, 94, ${alpha})` : `rgba(239, 68, 68, ${alpha})`;
                        ctx.fillRect(node.x, node.y, node.w, node.h);
                    } else {
                        activeFlashes.delete(node.symbol);
                    }
                }

                // Node Borders
                if (hoveredNode === node) {
                    ctx.strokeStyle = "#ffffff";
                    ctx.lineWidth = 2.5 / scale;
                } else {
                    ctx.strokeStyle = "#09090b";
                    ctx.lineWidth = 1 / scale;
                }
                ctx.strokeRect(node.x, node.y, node.w, node.h);

                // Text Formatting (Symbol & Price change percentage)
                if (screenW > 35 && screenH > 25) {
                    ctx.fillStyle = "#ffffff";

                    // Responsive sizing based on area size
                    const fontSize = Math.min(screenW * 0.18, screenH * 0.35, 18) / scale;
                    ctx.font = `bold ${fontSize}px sans-serif`;
                    ctx.textAlign = "center";
                    ctx.textBaseline = "middle";

                    const textY = node.y + node.h / 2;
                    ctx.fillText(node.symbol, node.x + node.w / 2, textY - (fontSize * 0.55));

                    ctx.font = `${fontSize * 0.8}px sans-serif`;
                    ctx.fillStyle = node.change >= 0 ? "#4ade80" : "#f87171";
                    const changeStr = `${node.change > 0 ? "+" : ""}${node.change.toFixed(2)}%`;
                    ctx.fillText(changeStr, node.x + node.w / 2, textY + (fontSize * 0.65));
                }
            });

            ctx.restore();
        }

        function triggerRedraw() {
            requestAnimationFrame(draw);
        }

        // --- 5. INTERACTIVE INPUT HANDLERS (ZOOM & PAN) ---

        // Screen Coordinate -> Canvas World Coordinate space
        function screenToWorld(clientX, clientY) {
            return {
                x: (clientX - offsetX) / scale,
                y: (clientY - offsetY) / scale
            };
        }

        canvas.addEventListener('mousedown', (e) => {
            isDragging = true;
            dragStartX = e.clientX - offsetX;
            dragStartY = e.clientY - offsetY;
        });

        window.addEventListener('mousemove', (e) => {
            if (isDragging) {
                // Perform Pan
                offsetX = e.clientX - dragStartX;
                offsetY = e.clientY - dragStartY;
                triggerRedraw();
            } else {
                // Perform Hover Hit Detection
                const worldCoords = screenToWorld(e.clientX, e.clientY);
                let currentHover = null;

                for (let i = 0; i < stockNodes.length; i++) {
                    const node = stockNodes[i];
                    if (worldCoords.x >= node.x && worldCoords.x <= node.x + node.w &&
                        worldCoords.y >= node.y && worldCoords.y <= node.y + node.h) {
                        currentHover = node;
                        break;
                    }
                }

                if (currentHover !== hoveredNode) {
                    hoveredNode = currentHover;
                    triggerRedraw();
                    updateTooltip(e, hoveredNode);
                } else if (hoveredNode) {
                    // Update dynamic tooltip position
                    tooltip.style.left = `${e.clientX + 15}px`;
                    tooltip.style.top = `${e.clientY + 15}px`;
                }
            }
        });

        window.addEventListener('mouseup', () => {
            isDragging = false;
        });

        canvas.addEventListener('wheel', (e) => {
            e.preventDefault();

            // Zoom anchor logic: Keeps mouse coordinate anchored on zoom transition
            const zoomFactor = 1.1;
            const targetScale = e.deltaY < 0 ? scale * zoomFactor : scale / zoomFactor;

            // Constrain
            const clampedScale = Math.max(MIN_SCALE, Math.min(MAX_SCALE, targetScale));
            if (clampedScale === scale) return;

            const mouseWorldX = (e.clientX - offsetX) / scale;
            const mouseWorldY = (e.clientY - offsetY) / scale;

            scale = clampedScale;
            offsetX = e.clientX - mouseWorldX * scale;
            offsetY = e.clientY - mouseWorldY * scale;

            triggerRedraw();
        }, { passive: false });

        function updateTooltip(e, node) {
            if (!node) {
                tooltip.style.display = 'none';
                return;
            }

            const changeClass = node.change >= 0 ? 'text-green' : 'text-red';
            const changeSign = node.change > 0 ? '+' : '';

            tooltip.innerHTML = `
                <div class="tooltip-symbol">${node.symbol}</div>
                <div style="font-size: 11px; color: #a1a1aa; margin-bottom: 6px;">${node.name}</div>
                <div class="tooltip-row">
                    <span class="tooltip-label">Price</span>
                    <span>$${node.price.toFixed(2)}</span>
                </div>
                <div class="tooltip-row">
                    <span class="tooltip-label">Change</span>
                    <span class="${changeClass}">${changeSign}${node.change.toFixed(2)}%</span>
                </div>
                <div class="tooltip-row">
                    <span class="tooltip-label">Sect. Weight</span>
                    <span>${node.weight}M</span>
                </div>
            `;
            tooltip.style.left = `${e.clientX + 15}px`;
            tooltip.style.top = `${e.clientY + 15}px`;
            tooltip.style.display = 'block';
        }

        // --- 6. REAL-TIME SIMULATION FEED ---
        // Simulates WebSocket activity, modifying values on random stocks at set intervals
        function startRealtimeUpdates() {
            setInterval(() => {
                // Select 1 to 3 random stocks to simulate live data ticks
                const updatesCount = Math.floor(Math.random() * 3) + 1;
                const now = Date.now();

                for (let i = 0; i < updatesCount; i++) {
                    const randomSector = marketData.children[Math.floor(Math.random() * marketData.children.length)];
                    const randomStock = randomSector.children[Math.floor(Math.random() * randomSector.children.length)];

                    // Apply slight random walk variation to price & change percent
                    const deltaPercent = (Math.random() - 0.5) * 0.6; // Up to +/-0.3% change
                    randomStock.price *= (1 + (deltaPercent / 100));
                    randomStock.change += deltaPercent;

                    // Tag flash animation
                    activeFlashes.set(randomStock.symbol, now);
                }

                // Regenerate logic references & redraw
                layoutTreemap();
                triggerRedraw();
            }, 800); // Ticks run every 800ms
        }

        // Smooth frame animator loop for rendering dynamic changes (like flashes)
        function animationLoop() {
            if (activeFlashes.size > 0) {
                draw();
            }
            requestAnimationFrame(animationLoop);
        }

        // --- 7. INITIALIZATION & RE-SCALING ---
        function resetView() {
            scale = 1;
            offsetX = 0;
            offsetY = 0;
            layoutTreemap();
            triggerRedraw();
        }

        function resize() {
            width = window.innerWidth;
            height = window.innerHeight;
            canvas.width = width * window.devicePixelRatio;
            canvas.height = height * window.devicePixelRatio;
            canvas.style.width = `${width}px`;
            canvas.style.height = `${height}px`;
            ctx.scale(window.devicePixelRatio, window.devicePixelRatio);

            layoutTreemap();
            triggerRedraw();
        }

        document.getElementById('reset-btn').addEventListener('click', resetView);
        window.addEventListener('resize', resize);

        // Initial setup sequence
        resize();
        startRealtimeUpdates();
        animationLoop();

    </script>
</body>
</html>
```

### Architectural & Performance Features of this Code:

1. **Slice-and-Dice Partitioner:** Built using optimized recursive dividing algorithms that partition sector nodes, calculate offsets, assign inner nested boundaries, and allocate individual stock spaces based on their custom weight (Market Cap).
2. **Dynamic Zoom-to-Cursor:** Zoom transitions recalculate world coordinates under your cursor's screen position, keeping that point fixed on-screen as you scroll.
3. **Frustum Culling:** Any stock node that slips off the edge of the viewport during zoom/pan is excluded from Canvas paint operations, keeping GPU memory footprints low.
4. **WebSocket Mimicry:** A simulation worker generates random real-time adjustments and highlights updated nodes using custom-faded "glowing" canvas overlays.
5. **No External Library Dependencies:** Written entirely in vanilla HTML5/JS. There are no D3 or React overhead packages, eliminating bundle size bloat.

Here is a complete, production-ready, single-file implementation of an interactive stock price heatmap. 

It uses **HTML5**, **Tailwind CSS** for UI styling, and **D3.js (v7)** for the squarified treemap layout, real-time DOM updates, and fluid zoom/pan interactions.

Save the code below as an `.html` file (e.g., `heatmap.html`) and open it in any modern web browser.

