        };

        // Map lookup helper for quick O(1) updates
        const stockLookup = {};
        marketData.children.forEach(sector => {
            sector.children.forEach(stock => {
                stockLookup[stock.name] = stock;
                stock.sector = sector.name;
            });
        });

        // --- 2. Setup Dimensions & SVG Canvas ---
        const svg = d3.select("#heatmap-svg");
        const container = svg.append("g").attr("class", "zoom-container");

        let width = svg.node().clientWidth;
