        // --- 3. Color Scale (Deep Red -> Charcoal Gray -> Deep Green) ---
        const colorScale = d3.scaleLinear()
            .domain([-4, -1.5, 0, 1.5, 4])
            .range(["#dc2626", "#7f1d1d", "#1f2937", "#064e3b", "#16a34a"]);

        // --- 4. Setup D3 Treemap Layout ---
        const treemap = d3.treemap()
            .size([width, height])
            .paddingOuter(6)
            .paddingTop(24) // Leaves vertical space for Sector headers
            .paddingInner(2)
            .round(true);

        const root = d3.hierarchy(marketData)
            .sum(d => d.value)
            .sort((a, b) => b.value - a.value);

        treemap(root);

        // --- 5. Render Treemap Structures ---

        // Render Sectors Groups
        const sectors = container.selectAll(".sector")
