            .style("transition", "fill 0.4s ease");

        // Group container for text inside cell to apply clip-path
        const textContainer = stocks.append("g")
            .attr("clip-path", d => `url(#clip-${d.data.name})`);

        // Ticker symbol label
        const tickerLabels = textContainer.append("text")
            .attr("x", d => (d.x1 - d.x0) / 2)
            .attr("y", d => (d.y1 - d.y0) / 2 - 2)
            .attr("text-anchor", "middle")
            .attr("fill", "#ffffff")
