            } else {
                changeEl.attr("class", "font-bold font-mono text-red-400");
            }

            // Convert raw relative weight value into simulated Trillions/Billions Market Cap
            const capStr = data.value >= 1000 ? `${(data.value / 1000).toFixed(2)}T` : `${data.value}B`;
            d3.select("#tooltip-cap").text(`$${capStr}`);
        }

        // --- 7. Interactive Zoom and Pan Behavior ---
        const zoom = d3.zoom()
            .scaleExtent([0.75, 15]) // Min / Max zoom depth
            .on("zoom", (event) => {
                container.attr("transform", event.transform);

                // Adaptive UX: dynamically adjust visibility and stroke on deep zoom
                if (event.transform.k > 2) {
                    stocks.selectAll("rect").attr("stroke-width", `${1 / event.transform.k}px`);
                }
            });

        svg.call(zoom);

        // Reset view button bind
        d3.select("#reset-zoom").on("click", () => {
            svg.transition()
               .duration(750)
               .call(zoom.transform, d3.zoomIdentity);
        });

        // --- 8. Responsive Resize Handler ---
        window.addEventListener("resize", () => {
            width = svg.node().clientWidth;
            height = svg.node().clientHeight;

            // Recalculate layout size
            treemap.size([width, height]);
            treemap(root);

            // Re-draw sectors
            sectors.selectAll("rect")
                .attr("x", d => d.x0)
                .attr("y", d => d.y0)
                .attr("width", d => d.x1 - d.x0);

            sectors.selectAll("text")
                .attr("x", d => d.x0 + 8)
                .attr("y", d => d.y0 + 16);

            // Re-draw stock node coordinates & clip paths
            stocks.attr("transform", d => `translate(${d.x0},${d.y0})`);

            stocks.selectAll("clipPath rect")
                .attr("width", d => d.x1 - d.x0)
                .attr("height", d => d.y1 - d.y0);

            stocks.selectAll("rect")
                .attr("width", d => d.x1 - d.x0)
                .attr("height", d => d.y1 - d.y0);

            // Re-center text values
            tickerLabels
                .attr("x", d => (d.x1 - d.x0) / 2)
                .attr("y", d => (d.y1 - d.y0) / 2 - 2)
                .style("font-size", d => `${Math.min((d.x1 - d.x0) / 4, 14)}px`);

            changeLabels
                .attr("x", d => (d.x1 - d.x0) / 2)
                .attr("y", d => (d.y1 - d.y0) / 2 + 12)
                .style("font-size", d => `${Math.min((d.x1 - d.x0) / 5, 10)}px`);
        });

        // --- 9. Real-Time WebSocket Mocking Server Feed ---
        setInterval(() => {
            // Select random stocks to receive a real-time price update tick
            const keys = Object.keys(stockLookup);
            const numUpdates = Math.floor(Math.random() * 5) + 2; // Tick 2 to 7 random stocks at a time

            for(let i = 0; i < numUpdates; i++) {
                const randomTicker = keys[Math.floor(Math.random() * keys.length)];
                const stock = stockLookup[randomTicker];

                // Keep simulation realistic (volatility percentage moves)
                const percentageVolatility = (Math.random() - 0.5) * 0.6; // Max 0.3% swing per tick
                stock.change += percentageVolatility;

                // Hard boundaries to prevent simulated metrics from running infinitely off-chart
                if (stock.change > 6) stock.change = 6;
                if (stock.change < -6) stock.change = -6;

                stock.price *= (1 + (percentageVolatility / 100));

                // Visual Flashing feedback indicator on data update
                const rectNode = d3.select(`#rect-${stock.name}`);

                // Set the updated properties and smoothly interpolate colors
                rectNode
                    .transition()
                    .duration(150)
                    .attr("fill", colorScale(stock.change));

                // Update text label values dynamic text strings
                d3.select(`#change-${stock.name}`)
                    .text(`${stock.change > 0 ? "+" : ""}${stock.change.toFixed(2)}%`);

                // If tooltip is currently looking at this active ticker, force update its fields immediately
                if (tooltip.style("display") === "block" && d3.select("#tooltip-ticker").text() === stock.name) {
                    updateTooltipContent(stock);
                }
            }
        }, 1500);

    </script>
</body>
</html>
