                stocks: [
                    { symbol: "LLY", name: "Eli Lilly & Co.", marketCap: 580, price: 590.25, change: 3.45 },
                    { symbol: "UNH", name: "UnitedHealth Group", marketCap: 480, price: 520.10, change: -0.60 },
                    { symbol: "JNJ", name: "Johnson & Johnson", marketCap: 390, price: 156.40, change: -0.20 },
                    { symbol: "MRK", name: "Merck & Co.", marketCap: 270, price: 105.15, change: 0.90 },
                    { symbol: "ABBV", name: "AbbVie Inc.", marketCap: 260, price: 152.30, change: -1.15 }
                ]
            }
        ];

        // --- 2. CONFIGURATION & STATE ---
        const canvas = document.getElementById("heatmapCanvas");
        const ctx = canvas.getContext("2d");
        const tooltip = document.getElementById("tooltip");

        let width = window.innerWidth;
        let height = window.innerHeight;

        // Zoom / Pan transformation state
        let scale = 1;
        let offsetX = 0;
        let offsetY = 0;
        let isDragging = false;
        let dragStart = { x: 0, y: 0 };

        // Treemap node definitions
        let flatNodes = []; // Flat array of leaf nodes (stocks) for hover detection and updates
        let hoveredNode = null;

        // --- 3. RECURSIVE SLICE-AND-DICE TREEMAP ALGORITHM ---
        // Splits spaces recursively alternating horizontal and vertical cuts
        function computeTreemap(nodes, x, y, w, h, vertical = true) {
            if (nodes.length === 0) return;

            if (nodes.length === 1) {
                nodes[0].x = x;
                nodes[0].y = y;
                nodes[0].w = w;
                nodes[0].h = h;
                return;
            }

            const totalValue = nodes.reduce((acc, node) => acc + node.value, 0);
            let cumulativeValue = 0;
            let splitIndex = 0;

            for (let i = 0; i < nodes.length; i++) {
                cumulativeValue += nodes[i].value;
                if (cumulativeValue >= totalValue / 2 || i === nodes.length - 2) {
                    splitIndex = i + 1;
                    break;
                }
            }

            const leftPart = nodes.slice(0, splitIndex);
            const rightPart = nodes.slice(splitIndex);
            const leftValue = leftPart.reduce((acc, n) => acc + n.value, 0);
            const percentage = leftValue / totalValue;

            if (vertical) {
                const currentWidth = w * percentage;
                computeTreemap(leftPart, x, y, currentWidth, h, !vertical);
                computeTreemap(rightPart, x + currentWidth, y, w - currentWidth, h, !vertical);
            } else {
                const currentHeight = h * percentage;
                computeTreemap(leftPart, x, y, w, currentHeight, !vertical);
                computeTreemap(rightPart, x, y + currentHeight, w, h - currentHeight, !vertical);
            }
        }

        // Initialize and structuralize flat and parent layouts
        function layoutHeatmap() {
            // Process sector weights
            const sectorNodes = rawMarketData.map(sector => {
                const sectorMCap = sector.stocks.reduce((acc, s) => acc + s.marketCap, 0);
                const stockNodes = sector.stocks.map(s => ({
                    symbol: s.symbol,
                    name: s.name,
                    value: s.marketCap,
                    price: s.price,
                    change: s.change,
                    parentSector: sector.sector
                }));

                // Sort stocks in sector descending by market cap
                stockNodes.sort((a,b) => b.value - a.value);

                return {
                    name: sector.sector,
                    value: sectorMCap,
                    children: stockNodes
                };
            });

            // Sort sectors descending by market cap
            sectorNodes.sort((a,b) => b.value - a.value);

            // 1. Layout Sectors
            computeTreemap(sectorNodes, 10, 10, width - 20, height - 20, true);

            // 2. Layout Stocks inside Sectors
            flatNodes = [];
            sectorNodes.forEach(sector => {
                // Add inner margin to separate sectors
                const padding = 4;
                computeTreemap(
                    sector.children, 
                    sector.x + padding, 
                    sector.y + padding + 15, // Space for Sector Title
                    sector.w - (padding * 2), 
                    sector.h - (padding * 2) - 15, 
                    sector.w > sector.h
                );
                flatNodes.push(...sector.children);
            });
        }

        // --- 4. COLOR GENERATION ---
        // Green color scale for gainers, Red for decliners
        function getColorForChange(change) {
            const limit = 4.0; // Max out color brightness at 4% change
            const intensity = Math.min(Math.abs(change) / limit, 1.0);

            if (change > 0) {
                // Green: Dark Green to Vibrant Green
                const green = Math.round(40 + (intensity * 175));
                const red = Math.round(15 + (intensity * 15));
                const blue = Math.round(20 + (intensity * 20));
                return `rgb(${red}, ${green}, ${blue})`;
            } else if (change < 0) {
                // Red: Dark Red to Vibrant Red
                const red = Math.round(50 + (intensity * 185));
                const green = Math.round(15 + (intensity * 15));
                const blue = Math.round(20 + (intensity * 20));
                return `rgb(${red}, ${green}, ${blue})`;
            }
            return "#2A2E39"; // Neutral Grey
        }

        // --- 5. RENDER LOOP ---
        function draw() {
            ctx.clearRect(0, 0, width, height);

            ctx.save();
            // Apply zoom/pan transformation matrix
            ctx.translate(offsetX, offsetY);
            ctx.scale(scale, scale);

            // Draw sectors first (Background Container structures)
            rawMarketData.forEach(s => {
                // Find bounds from calculated children
                const sectorChildren = flatNodes.filter(n => n.parentSector === s.sector);
                if (sectorChildren.length === 0) return;

                const minX = Math.min(...sectorChildren.map(c => c.x));
                const minY = Math.min(...sectorChildren.map(c => c.y)) - 15;
                const maxX = Math.max(...sectorChildren.map(c => c.x + c.w));
                const maxY = Math.max(...sectorChildren.map(c => c.y + c.h));

                // Draw Sector Background Card
                ctx.fillStyle = "#1e1e24";
                ctx.fillRect(minX - 2, minY - 2, (maxX - minX) + 4, (maxY - minY) + 4);

                // Draw Sector Header
                ctx.fillStyle = "#a1a5b5";
                ctx.font = `bold ${Math.max(10, 11 / scale)}px sans-serif`;
                ctx.fillText(s.sector.toUpperCase(), minX + 2, minY + 10);
            });

            // Draw stock leaf cells
            flatNodes.forEach(node => {
                // Clip elements out of screen to optimize frame rates
                const screenX = node.x * scale + offsetX;
                const screenY = node.y * scale + offsetY;
                const screenW = node.w * scale;
                const screenH = node.h * scale;

                if (screenX + screenW < 0 || screenX > width || screenY + screenH < 0 || screenY > height) {
                    return; // Dynamic Culling
                }

                // 1. Draw cell body
                ctx.fillStyle = getColorForChange(node.change);
                ctx.fillRect(node.x, node.y, node.w, node.h);

                // Highlight hovered node
