                    ctx.strokeStyle = "#ffffff";
                    ctx.lineWidth = 2 / scale;
                    ctx.strokeRect(node.x, node.y, node.w, node.h);
                } else {
                    ctx.strokeStyle = "#121214";
                    ctx.lineWidth = 1 / scale;
                    ctx.strokeRect(node.x, node.y, node.w, node.h);
                }

                // 2. Draw Text (Adaptive sizing with threshold checks)
                if (node.w > 30 && node.h > 20) {
                    ctx.fillStyle = "#ffffff";
                    ctx.textAlign = "center";
                    ctx.textBaseline = "middle";

                    // Dynamic sizing depending on cell width and zoom factor
                    const symbolFontSize = Math.max(8, Math.min(node.w / 4, 18)) / scale;
                    ctx.font = `bold ${symbolFontSize}px sans-serif`;

                    // Draw ticker symbol
                    const symbolY = node.y + node.h / 2 - (node.h > 35 ? (6 / scale) : 0);
                    ctx.fillText(node.symbol, node.x + node.w / 2, symbolY);

                    // Draw change value underneath if space is sufficient
                    if (node.h > 35) {
                        const changeFontSize = Math.max(7, Math.min(node.w / 5, 14)) / scale;
                        ctx.font = `${changeFontSize}px sans-serif`;
                        ctx.fillStyle = "rgba(255, 255, 255, 0.85)";

                        const prefix = node.change > 0 ? "+" : "";
                        ctx.fillText(`${prefix}${node.change.toFixed(2)}%`, node.x + node.w / 2, node.y + node.h / 2 + (10 / scale));
                    }
                }
            });

            ctx.restore();
        }

        // --- 6. EVENT INTERACTION (ZOOM / PAN / HOVER) ---
        function getTransformedMouseCoords(clientX, clientY) {
            const rect = canvas.getBoundingClientRect();
            const x = clientX - rect.left;
            const y = clientY - rect.top;
            return {
                worldX: (x - offsetX) / scale,
                worldY: (y - offsetY) / scale,
                screenX: x,
                screenY: y
            };
        }

        // Wheel to Zoom towards center cursor
        canvas.addEventListener("wheel", (e) => {
            e.preventDefault();
            const coords = getTransformedMouseCoords(e.clientX, e.clientY);

            const zoomIntensity = 0.12;
            const zoomFactor = e.deltaY < 0 ? (1 + zoomIntensity) : (1 - zoomIntensity);

            // Constrain Zoom
            const nextScale = scale * zoomFactor;
            if (nextScale < 0.8 || nextScale > 15) return;

            // Shift offset relative to pointer positioning
            offsetX = coords.screenX - (coords.screenX - offsetX) * zoomFactor;
            offsetY = coords.screenY - (coords.screenY - offsetY) * zoomFactor;
            scale = nextScale;

            updateTooltipPosition(e.clientX, e.clientY);
            draw();
        }, { passive: false });

        // Pan interactions
        canvas.addEventListener("mousedown", (e) => {
            if (e.button !== 0) return; // Only left click drags
            isDragging = true;
            dragStart.x = e.clientX - offsetX;
            dragStart.y = e.clientY - offsetY;
        });

        window.addEventListener("mousemove", (e) => {
            const coords = getTransformedMouseCoords(e.clientX, e.clientY);

            if (isDragging) {
                offsetX = e.clientX - dragStart.x;
                offsetY = e.clientY - dragStart.y;
                draw();
            } else {
                // Hover Detection
                let found = null;
                for (let i = 0; i < flatNodes.length; i++) {
                    const node = flatNodes[i];
                    if (coords.worldX >= node.x && coords.worldX <= node.x + node.w &&
                        coords.worldY >= node.y && coords.worldY <= node.y + node.h) {
                        found = node;
                        break;
                    }
                }

                if (found !== hoveredNode) {
                    hoveredNode = found;
                    draw();
                    updateTooltip(found, e.clientX, e.clientY);
                } else if (found) {
                    updateTooltipPosition(e.clientX, e.clientY);
                }
            }
        });

        window.addEventListener("mouseup", () => {
            isDragging = false;
        });

        // HTML Tooltip DOM manipulations
        function updateTooltip(node, x, y) {
            if (!node) {
                tooltip.style.display = "none";
                return;
            }

            const prefix = node.change > 0 ? "+" : "";
            const colorClass = node.change >= 0 ? "#00ff66" : "#ff3344";

            tooltip.innerHTML = `
                <div class="tooltip-row" style="font-size: 14px; font-weight: bold; border-bottom: 1px solid #222; padding-bottom: 4px; margin-bottom: 6px;">
                    <span>${node.symbol}</span>
                    <span style="color: ${colorClass}">${prefix}${node.change.toFixed(2)}%</span>
                </div>
                <div class="tooltip-row">
                    <span class="tooltip-label">Name:</span>
                    <span class="tooltip-val">${node.name}</span>
                </div>
                <div class="tooltip-row">
                    <span class="tooltip-label">Price:</span>
                    <span class="tooltip-val">$${node.price.toFixed(2)}</span>
                </div>
                <div class="tooltip-row">
                    <span class="tooltip-label">Mkt Cap:</span>
                    <span class="tooltip-val">$${node.value}B</span>
                </div>
            `;
            tooltip.style.display = "block";
            updateTooltipPosition(x, y);
        }

        function updateTooltipPosition(x, y) {
            const tooltipWidth = tooltip.offsetWidth;
            const tooltipHeight = tooltip.offsetHeight;

            // Boundary collisions
            let left = x + 15;
            let top = y + 15;

            if (left + tooltipWidth > window.innerWidth) {
                left = x - tooltipWidth - 15;
            }
            if (top + tooltipHeight > window.innerHeight) {
                top = y - tooltipHeight - 15;
            }

            tooltip.style.left = `${left}px`;
            tooltip.style.top = `${top}px`;
        }

        // Reset configuration
        document.getElementById("reset-btn").addEventListener("click", () => {
            scale = 1;
            offsetX = 0;
            offsetY = 0;
            layoutHeatmap();
            draw();
        });

        // --- 7. REAL-TIME DATA STREAM SIMULATION (WEBSOCKET SIMULATOR) ---
        function simulateMarketStream() {
            setInterval(() => {
                // Pick 1 to 3 random stocks to modify values
                const updatesCount = Math.floor(Math.random() * 3) + 1;
                for (let i = 0; i < updatesCount; i++) {
                    const targetIndex = Math.floor(Math.random() * flatNodes.length);
                    const node = flatNodes[targetIndex];

                    // Generate minor price ticks (-0.3% to +0.3%)
                    const pctTick = (Math.random() * 0.6) - 0.3;
                    node.change += pctTick;
                    node.price *= (1 + (pctTick / 100));

                    // Keep values bounded within realistic scale ranges (-10% / +10%)
                    node.change = Math.max(-10, Math.min(10, node.change));

                    // Dynamic text updates to the active tooltip if hovered
                    if (hoveredNode && hoveredNode.symbol === node.symbol) {
                        updateTooltip(node, parseFloat(tooltip.style.left), parseFloat(tooltip.style.top));
                    }
                }
                draw(); // Redraw with changes
            }, 500); // Trigger ticks every 500ms
        }

        // --- 8. INITIALIZATION & RESIZE WRAPPING ---
        function resize() {
            width = window.innerWidth;
            height = window.innerHeight;
            canvas.width = width * window.devicePixelRatio;
            canvas.height = height * window.devicePixelRatio;
            canvas.style.width = `${width}px`;
            canvas.style.height = `${height}px`;
            ctx.scale(window.devicePixelRatio, window.devicePixelRatio);

            layoutHeatmap();
            draw();
        }

        window.addEventListener("resize", resize);

        // Boot execution
        resize();
        simulateMarketStream();

    </script>
</body>
</html>
