        <!-- Custom Client-side Tooltip -->
        <div id="tooltip" class="absolute pointer-events-none bg-gray-900/95 border border-gray-700 text-gray-200 text-xs rounded p-3 hidden shadow-xl backdrop-blur-sm z-50"></div>
    </main>

    <script>
        // --- 1. MOCK DATASET (Organized Hierarchically for Treemap) ---
        const marketData = {
            name: "Market",
            children: [
                {
                    name: "Technology",
                    children: [
                        { symbol: "AAPL", name: "Apple Inc.", value: 3000, price: 175.50, change: 0.15 },
                        { symbol: "MSFT", name: "Microsoft Corp.", value: 2900, price: 415.60, change: -0.45 },
                        { symbol: "NVDA", name: "NVIDIA Corp.", value: 2200, price: 875.12, change: 2.45 },
                        { symbol: "AVGO", name: "Broadcom Inc.", value: 650, price: 1350.00, change: -1.20 },
                        { symbol: "CRM", name: "Salesforce Inc.", value: 280, price: 295.40, change: 0.80 }
                    ]
                },
                {
                    name: "Financials",
                    children: [
                        { symbol: "JPM", name: "JPMorgan Chase & Co.", value: 570, price: 195.50, change: 0.40 },
                        { symbol: "BAC", name: "Bank of America Corp.", value: 300, price: 37.20, change: -0.85 },
                        { symbol: "WFC", name: "Wells Fargo & Co.", value: 210, price: 57.80, change: 1.10 },
                        { symbol: "MS", name: "Morgan Stanley", value: 150, price: 94.10, change: -0.20 }
                    ]
                },
                {
                    name: "Healthcare",
                    children: [
                        { symbol: "LLY", name: "Eli Lilly & Co.", value: 720, price: 762.00, change: 1.95 },
                        { symbol: "UNH", name: "UnitedHealth Group", value: 450, price: 490.50, change: -1.50 },
                        { symbol: "JNJ", name: "Johnson & Johnson", value: 380, price: 156.40, change: -0.10 },
                        { symbol: "MRK", name: "Merck & Co. Inc.", value: 310, price: 125.30, change: 0.65 }
                    ]
                },
                {
                    name: "Consumer Discretionary",
                    children: [
                        { symbol: "AMZN", name: "Amazon.com Inc.", value: 1800, price: 178.15, change: 1.12 },
                        { symbol: "TSLA", name: "Tesla Inc.", value: 550, price: 175.34, change: -2.85 },
                        { symbol: "HD", name: "Home Depot Inc.", value: 380, price: 382.10, change: 0.30 },
                        { symbol: "NKE", name: "Nike Inc.", value: 150, price: 99.50, change: -1.10 }
                    ]
                }
            ]
        };

        // --- 2. SETUP DIMENSIONS & SCALES ---
        const container = document.getElementById("heatmap-container");
        let width = container.clientWidth;
        let height = container.clientHeight;

        const svg = d3.select("#heatmap")
            .attr("width", width)
            .attr("height", height);

        // Group element to apply Zoom & Pan transformations
        const mainGroup = svg.append("g").attr("id", "main-transform-group");

        // Diverging Color scale: -3% (Red) to 0% (Gray) to +3% (Green)
        const colorScale = d3.scaleLinear()
            .domain([-3, 0, 3])
            .range(["#dc2626", "#374151", "#16a34a"]) 
            .clamp(true);

        // Create Map to easily reference nodes by symbol during real-time updates
        const stockNodeMap = new Map();

        // --- 3. D3 TREEMAP LAYOUT CONFIGURATION ---
        const treemap = d3.treemap()
            .size([width, height])
            .paddingInner(2)
            .paddingOuter(4)
            .paddingTop(18) // Space for Sector names
            .round(true);

        // Build hierarchical root
        const root = d3.hierarchy(marketData)
            .sum(d).value) // Size based on Market Cap Value
            .sort((a, b) => b.value - a.value);

        // Run the layout generator
        treemap(root);

        // --- 4. RENDER HEATMAP ---

        // Render Sectors (Level 1)
        const sectors = mainGroup.selectAll(".sector")
            .data(root.children)
            .enter().append("g")
            .attr("class", "sector");

        // Sector Headers
        sectors.append("text")
            .attr("x", d => d.x0 + 6)
            .attr("y", d => d.y0 + 14)
            .attr("fill", "#9ca3af")
            .attr("font-size", "11px")
            .attr("font-weight", "600")
            .text(d => d.data.name);

        // Render Stocks (Leaves)
        const stocks = sectors.selectAll(".stock")
            .data(d => d.leaves())
            .enter().append("g")
            .attr("class", "stock")
            .attr("transform", d => `translate(${d.x0},${d.y0})`);

        // Draw Stock Rectangles
        stocks.append("rect")
            .attr("id", d => `rect-${d.data.symbol}`)
            .attr("class", "stock-rect stroke stroke-gray-700")
            .attr("width", d => d.x1 - d.x0)
            .attr("height", d => d.y1 - d.y0)
            .attr("fill", d => colorScale(d.data.change))
            .on("mouseover", showTooltip)
            .on("mousemove", moveTooltip)
            .on("mouseleave", hideTooltip);

        // Draw Stock Symbol Text
        stocks.append("text")
            .attr("id", d => `symbol-${d.data.symbol}`)
            .attr("x", d => (d.x1 - d.x0) / 2)
            .attr("y", d => (d.y1 - d.y0) / 2)
            .attr("text-anchor", "middle")
            .attr("dominant-baseline", "middle")
            .attr("fill", "#ffffff")
            .attr("font-weight", "700")
            .style("pointer-events", "none") // Prevent interfering with mouse hover
            .text(d => {
                // Adjust font size dynamically based on box size
                const boxWidth = d.x1 - d.x0;
                const fontSize = Math.min(boxWidth / 4, 14);
                d3.select(`#symbol-${d.data.symbol}`).style("font-size", `${fontSize}px`);
                return boxWidth > 35 ? d.data.symbol : "";
            });

        // Draw Stock Percentage Text below Symbol
        stocks.append("text")
            .attr("id", d => `change-${d.data.symbol}`)
            .attr("x", d => (d.x1 - d.x0) / 2)
            .attr("y", d => ((d.y1 - d.y0) / 2) + 12)
            .attr("text-anchor", "middle")
            .attr("fill", "#e5e7eb")
            .style("pointer-events", "none")
            .text(d => {
                const boxWidth = d.x1 - d.x0;
                const boxHeight = d.y1 - d.y0;
                const fontSize = Math.min(boxWidth / 5, 11);
                d3.select(`#change-${d.data.symbol}`).style("font-size", `${fontSize}px`);
                return (boxWidth > 45 && boxHeight > 40) ? `${d.data.change > 0 ? '+' : ''}${d.data.change.toFixed(2)}%` : "";
            });

        // Map data instances directly to symbols for the real-time simulation updates
        root.leaves().forEach(leaf => {
            stockNodeMap.set(leaf.data.symbol, leaf);
        });

        // --- 5. ZOOM & PAN IMPLEMENTATION ---
        const zoomBehavior = d3.zoom()
            .scaleExtent([1, 8]) // Minimum zoom 1x, Maximum zoom 8x
            .translateExtent([[0, 0], [width, height]]) // Prevent panning infinitely outside viewport
            .on("zoom", (event) => {
                mainGroup.attr("transform", event.transform);
            });

        // Bind zoom events to main svg
        svg.call(zoomBehavior);

        // Reset Zoom Button functionality
        document.getElementById("reset-zoom").addEventListener("click", () => {
            svg.transition()
                .duration(750)
                .ease(d3.easeCubicOut)
                .call(zoomBehavior.transform, d3.zoomIdentity);
        });

        // --- 6. TOOLTIP LOGIC ---
        const tooltip = d3.select("#tooltip");

        function showTooltip(event, d) {
            tooltip.style("display", "block")
                .html(`
                    <div class="font-bold text-white">${d.data.symbol} (${d.data.name})</div>
                    <div class="text-gray-400 mt-1">Sector: <span class="text-gray-300 font-medium">${d.parent.data.name}</span></div>
                    <div class="flex justify-between space-x-6 mt-1.5">
                        <span>Price: <strong class="text-white">$${d.data.price.toFixed(2)}</strong></span>
                        <span>Change: <strong class="${d.data.change >= 0 ? 'text-green-400' : 'text-red-400'}">${d.data.change > 0 ? '+' : ''}${d.data.change.toFixed(2)}%</strong></span>
                    </div>
                `);
        }

        function moveTooltip(event) {
            tooltip
                .style("left", (event.clientX + 15) + "px")
                .style("top", (event.clientY + 15) + "px");
        }

        function hideTooltip() {
            tooltip.style("display", "none");
        }

        // --- 7. REAL-TIME DATA SIMULATION ---
        // Simulates WebSocket "ticks" pushing update payloads to the client side
        setInterval(() => {
            const symbols = Array.from(stockNodeMap.keys());
            // Randomly select 2 to 4 tickers to update per tick
            const numUpdates = Math.floor(Math.random() * 3) + 2;

            for (let i = 0; i < numUpdates; i++) {
                const randomSymbol = symbols[Math.floor(Math.random() * symbols.length)];
                const leaf = stockNodeMap.get(randomSymbol);

                if (!leaf) continue;

                // Simulate volatile fluctuations (-0.50% to +0.50%)
                const deltaChange = (Math.random() * 1.0 - 0.5);
                leaf.data.change = parseFloat((leaf.data.change + deltaChange).toFixed(2));
                leaf.data.price = parseFloat((leaf.data.price * (1 + deltaChange / 100)).toFixed(2));

                // Constrain simulated change limits for visualization boundary (-5% to +5%)
                leaf.data.change = Math.max(-5, Math.min(5, leaf.data.change));

                // 1. Dynamic background color updates using standard d3 selector
                const rect = d3.select(`#rect-${randomSymbol}`);
                rect.transition()
                    .duration(500)
                    .attr("fill", colorScale(leaf.data.change));

                // 2. Trigger Flash border effect based on direction
                const element = document.getElementById(`rect-${randomSymbol}`);
                if (element) {
                    element.classList.remove('flash-green', 'flash-red');
                    void element.offsetWidth; // Force CSS reflow to re-trigger transition
                    element.classList.add(deltaChange >= 0 ? 'flash-green' : 'flash-red');
                }

                // 3. Update Percentage Text label dynamically inside heatmap
                const changeText = d3.select(`#change-${randomSymbol}`);
                const boxWidth = leaf.x1 - leaf.x0;
                const boxHeight = leaf.y1 - leaf.y0;
                if (boxWidth > 45 && boxHeight > 40) {
                    changeText.text(`${leaf.data.change > 0 ? '+' : ''}${leaf.data.change.toFixed(2)}%`);
                }
            }
        }, 1500); // Trigger ticks every 1.5 seconds

        // --- 8. RESPONSIVENESS HANDLER ---
        window.addEventListener("resize", () => {
            width = container.clientWidth;
            height = container.clientHeight;

            svg.attr("width", width).attr("height", height);

            // Recalculate Treemap layout on size changes
            treemap.size([width, height]);
            treemap(root);

            // Re-render sectors
            mainGroup.selectAll(".sector")
                .selectAll("text")
                .attr("x", d => d.parent.x0 + 6)
                .attr("y", d => d.parent.y0 + 14);

            // Re-adjust stock translates
            mainGroup.selectAll(".stock")
                .attr("transform", d => `translate(${d.x0},${d.y0})`);

            // Re-scale rect boundaries
            mainGroup.selectAll(".stock-rect")
                .attr("width", d => d.x1 - d.x0)
                .attr("height", d => d.y1 - d.y0);

            // Adjust texts
            mainGroup.selectAll(".stock").selectAll("text").each(function(d) {
                const textEl = d3.select(this);
                const isSymbol = textEl.attr("id").startsWith("symbol");
                const boxWidth = d.x1 - d.x0;
                const boxHeight = d.y1 - d.y0;

                if (isSymbol) {
                    const fontSize = Math.min(boxWidth / 4, 14);
                    textEl.attr("x", boxWidth / 2)
                        .attr("y", boxHeight / 2)
                        .style("font-size", `${fontSize}px`)
                        .text(boxWidth > 35 ? d.data.symbol : "");
                } else {
                    const fontSize = Math.min(boxWidth / 5, 11);
                    textEl.attr("x", boxWidth / 2)
                        .attr("y", (boxHeight / 2) + 12)
                        .style("font-size", `${fontSize}px`)
                        .text((boxWidth > 45 && boxHeight > 40) ? `${d.data.change > 0 ? '+' : ''}${d.data.change.toFixed(2)}%` : "");
                }
            });

            // Update Zoom translate constraints
            zoomBehavior.translateExtent([[0, 0], [width, height]]);
        });
    </script>
</body>
