        </header>
        <div id="canvas-container">
            <canvas id="heatmapCanvas"></canvas>
            <div id="tooltip"></div>
        </div>
    </div>

    <script>
        // --- 1. MOCK DATASETS & HIERARCHY ---
        const marketData = {
            name: "Market",
            children: [
                {
                    name: "Technology",
                    children: [
                        { name: "AAPL", value: 3000, change: 0.45 },
                        { name: "MSFT", value: 2950, change: -1.2 },
                        { name: "NVDA", value: 2200, change: 3.10 },
                        { name: "AVGO", value: 800, change: 0.12 },
                        { name: "CRM", value: 300, change: -2.45 }
                    ]
                },
                {
                    name: "Financials",
                    children: [
                        { name: "JPM", value: 550, change: 0.85 },
                        { name: "BAC", value: 320, change: -0.40 },
                        { name: "MS", value: 210, change: 1.15 },
                        { name: "GS", value: 190, change: -1.80 }
                    ]
                },
                {
                    name: "Consumer Cyclical",
                    children: [
                        { name: "AMZN", value: 1800, change: 1.65 },
                        { name: "TSLA", value: 650, change: -4.20 },
                        { name: "HD", value: 380, change: 0.05 },
                        { name: "NKE", value: 150, change: -0.90 }
                    ]
                },
                {
                    name: "Healthcare",
                    children: [
                        { name: "LLY", value: 720, change: 2.40 },
                        { name: "JNJ", value: 410, change: -0.15 },
                        { name: "PG", value: 390, change: 0.55 },
                        { name: "MRK", value: 310, change: -1.10 }
                    ]
                }
            ]
        };

        // --- 2. SETUP CANVAS & SYSTEM VARIABLES ---
        const container = document.getElementById('canvas-container');
        const canvas = document.getElementById('heatmapCanvas');
        const ctx = canvas.getContext('2d');
        const tooltip = document.getElementById('tooltip');

        let width = container.clientWidth;
        let height = container.clientHeight;

        // Handle High DPI displays for crisp rendering
        const dpr = window.devicePixelRatio || 1;
        canvas.width = width * dpr;
        canvas.height = height * dpr;
        canvas.style.width = width + 'px';
        canvas.style.height = height + 'px';
        ctx.scale(dpr, dpr);

        // Map for fast O(1) lookups during live updates
        const stockLookup = {};
        let leaves = []; // Store references to calculated visual elements (leaves)

        // Color interpolator (-3% Red, 0% Dark Gray, +3% Green)
        const colorScale = d3.scaleLinear()
            .domain([-3, 0, 3])
            .range(["#ef4444", "#27272a", "#22c55e"])
            .clamp(true);

        // --- 3. D3 TREEMAP LAYOUT CALCULATION ---
        function computeTreemapLayout() {
            const root = d3.hierarchy(marketData)
                .sum(d => d.value)
                .sort((a, b) => b.value - a.value);

            d3.treemap()
                .size([width, height])
                .paddingOuter(4)
                .paddingInner(2)
                .round(true)(root);

            leaves = root.leaves();

            // Populate the lookup index for updates
            leaves.forEach(leaf => {
                stockLookup[leaf.data.name] = leaf;
            });
        }

        // --- 4. PAN & ZOOM CONTROLLER ---
        let transform = d3.zoomIdentity;

        const zoom = d3.zoom()
            .scaleExtent([1, 15]) // Min zoom 1x, Max zoom 15x
            .on("zoom", (event) => {
                transform = event.transform;
                draw();
            });

        // Bind zoom events to Canvas
        d3.select(canvas).call(zoom);

        // --- 5. RENDER CANVAS GRAPHICS ---
        function draw() {
            ctx.clearRect(0, 0, width, height);

            ctx.save();
            // Apply D3 zoom and pan matrices
            ctx.translate(transform.x, transform.y);
            ctx.scale(transform.k, transform.k);

            // Draw stock leaves
            leaves.forEach(node => {
                const w = node.x1 - node.x0;
                const h = node.y1 - node.y0;

                // 1. Draw Background Tile Color
                ctx.fillStyle = colorScale(node.data.change);
                ctx.fillRect(node.x0, node.y0, w, h);

                // 2. Draw Subtle Border Inside Tile
                ctx.strokeStyle = "#121214";
                ctx.lineWidth = 1 / transform.k; // Constant border width regardless of zoom level
                ctx.strokeRect(node.x0, node.y0, w, h);

                // 3. Render Responsive Text (Tickers)
                const areaOnScreen = w * h * transform.k * transform.k;

                // Only render text if tile has reasonable visual real estate
                if (areaOnScreen > 900) {
                    ctx.save();
                    // Clip text inside the node's bounds
                    ctx.beginPath();
                    ctx.rect(node.x0 + 2, node.y0 + 2, w - 4, h - 4);
                    ctx.clip();

                    ctx.fillStyle = "#ffffff";
                    ctx.textAlign = "center";
                    ctx.textBaseline = "middle";

                    // Dynamic font sizing
                    const fontSize = Math.max(9, Math.min(w / 4, 16));
                    ctx.font = `bold ${fontSize}px sans-serif`;

                    const centerX = node.x0 + w / 2;
                    const centerY = node.y0 + h / 2;

                    // Draw Stock Name
                    ctx.fillText(node.data.name, centerX, centerY - (fontSize / 1.8));

                    // Draw Price Change percentage
                    ctx.font = `${fontSize * 0.85}px sans-serif`;
                    ctx.fillStyle = "#e4e4e7";
                    const changeStr = `${node.data.change >= 0 ? '+' : ''}${node.data.change.toFixed(2)}%`;
                    ctx.fillText(changeStr, centerX, centerY + (fontSize / 1.8));

                    ctx.restore();
                }
            });

            ctx.restore();
        }

        // --- 6. INTERACTIVE TOOLTIP MATCHING ---
        // Inverse matrix calculation maps screen coordinates back to zoomed/panned model space
        function getStockUnderMouse(mx, my) {
            const dataX = (mx - transform.x) / transform.k;
            const dataY = (my - transform.y) / transform.k;

            return leaves.find(node => 
                dataX >= node.x0 && dataX <= node.x1 &&
                dataY >= node.y0 && dataY <= node.y1
            );
        }

        canvas.addEventListener('mousemove', (event) => {
            const rect = canvas.getBoundingClientRect();
            const mouseX = event.clientX - rect.left;
            const mouseY = event.clientY - rect.top;

            const hovered = getStockUnderMouse(mouseX, mouseY);

            if (hovered) {
                tooltip.style.opacity = '1';
                tooltip.style.left = `${event.clientX + 15}px`;
                tooltip.style.top = `${event.clientY + 15}px`;

                const changeClass = hovered.data.change >= 0 ? 'text-green' : 'text-red';
                const sign = hovered.data.change >= 0 ? '+' : '';

                tooltip.innerHTML = `
                    <div class="tooltip-title">${hovered.data.name}</div>
                    <div class="tooltip-row">
                        <span>Sector:</span>
                        <span style="color:#ffffff">${hovered.parent.data.name}</span>
                    </div>
                    <div class="tooltip-row">
                        <span>Market Cap:</span>
                        <span style="color:#ffffff">$${hovered.data.value}B</span>
                    </div>
                    <div class="tooltip-row">
                        <span>Change:</span>
                        <span class="${changeClass}">${sign}${hovered.data.change.toFixed(2)}%</span>
                    </div>
                `;
            } else {
                tooltip.style.opacity = '0';
            }
        });

        canvas.addEventListener('mouseleave', () => {
            tooltip.style.opacity = '0';
        });

        // --- 7. REAL-TIME DATA STREAM SIMULATION ---
        function startWebSocketSimulation() {
            setInterval(() => {
                // Randomly select 1 to 3 stocks to update simultaneously
                const numUpdates = Math.floor(Math.random() * 3) + 1;
                for (let i = 0; i < numUpdates; i++) {
                    const keys = Object.keys(stockLookup);
                    const randomKey = keys[Math.floor(Math.random() * keys.length)];
                    const targetNode = stockLookup[randomKey];

                    // Simulate typical high-frequency minor price micro-fluctuation (-0.3% to +0.3%)
                    const volatility = (Math.random() - 0.5) * 0.6;
                    targetNode.data.change = parseFloat((targetNode.data.change + volatility).toFixed(2));

                    // Clamp simulated performance movements boundaries to realistic session limits
                    if (targetNode.data.change > 6) targetNode.data.change = 6;
                    if (targetNode.data.change < -6) targetNode.data.change = -6;
                }

                // Redraw on Next Frame (Optimal Web Rendering Pattern)
                requestAnimationFrame(draw);
            }, 600); // Trigger updates every 600ms
        }

        // --- 8. INITIALIZE RUNTIME ---
        window.addEventListener('resize', () => {
            width = container.clientWidth;
            height = container.clientHeight;

            canvas.width = width * dpr;
            canvas.height = height * dpr;
            canvas.style.width = width + 'px';
            canvas.style.height = height + 'px';
            ctx.scale(dpr, dpr);

            computeTreemapLayout();
            draw();
        });

        // Kick off calculations, paint background, and ignite simulation
        computeTreemapLayout();
        draw();
        startWebSocketSimulation();

    </script>
</body>
</html>
