                    ctx.strokeStyle = stock.change >= 0 ? `rgba(100, 255, 100, ${opacity})` : `rgba(255, 100, 100, ${opacity})`;
                    ctx.lineWidth = 3 / zoom; // Maintain sharp border regardless of zoom
