};

// 2. Setup Canvas and High-DPI Resolution Support
const canvas = document.getElementById('heatmap');
const ctx = canvas.getContext('2d');
const tooltip = document.getElementById('tooltip');

let width = window.innerWidth;
let height = window.innerHeight;
let transform = d3.zoomIdentity; // Holds current zoom/pan state
let leaves = []; // Flattened array of stock nodes for rendering/collision
let hoveredNode = null;

function resize() {
    width = window.innerWidth;
    height = window.innerHeight;

    // Scale canvas for Retina/high-res displays
    const dpr = window.devicePixelRatio || 1;
    canvas.width = width * dpr;
    canvas.height = height * dpr;
    canvas.style.width = width + 'px';
    canvas.style.height = height + 'px';
    ctx.scale(dpr, dpr);

    calculateTreemapLayout();
    render();
}

// 3. Compute static Treemap layout coordinates using D3
function calculateTreemapLayout() {
    const root = d3.hierarchy(marketData)
        .sum(d => d.value)
        .sort((a, b) => b.value - a.value);

    // Padding between sectors
    d3.treemap()
        .size([width, height])
        .paddingInner(2)
        .paddingOuter(6)
        .paddingTop(18) (root);

    leaves = root.leaves();
}

// 4. Color Scale Helper (Bright Red to Neutral Black to Bright Green)
function getColorForChange(change) {
    if (change > 0) {
        const intensity = Math.min(change * 20, 1); // Caps saturation at 5% change
        return `rgba(38, 166, 154, ${0.3 + intensity * 0.7})`; // Teal/Green
    } else {
        const intensity = Math.min(Math.abs(change) * 20, 1);
        return `rgba(239, 83, 80, ${0.3 + intensity * 0.7})`; // Red
    }
}

// 5. High-Performance Canvas Render Loop
function render() {
    ctx.clearRect(0, 0, width, height);

    ctx.save();
    // Apply zoom/pan transformation matrix
    ctx.translate(transform.x, transform.y);
    ctx.scale(transform.k, transform.k);

    // Draw Leaves (Stock Tiles)
    leaves.forEach(node => {
        const w = node.x1 - node.x0;
        const h = node.y1 - node.y0;

        // Draw Tile Background
        ctx.fillStyle = getColorForChange(node.data.change);
        ctx.fillRect(node.x0, node.y0, w, h);

        // Highlight hovered tile
        if (node === hoveredNode) {
            ctx.strokeStyle = '#ffffff';
            ctx.lineWidth = 2 / transform.k; // Constant line-width regardless of zoom scale
            ctx.strokeRect(node.x0, node.y0, w, h);
        } else {
            ctx.strokeStyle = '#121212';
            ctx.lineWidth = 1 / transform.k;
            ctx.strokeRect(node.x0, node.y0, w, h);
        }

        // Clip text rendering to prevent text overflow
        ctx.save();
        ctx.beginPath();
        ctx.rect(node.x0 + 2, node.y0 + 2, w - 4, h - 4);
        ctx.clip();

        // Dynamically scale font size based on box size and zoom
        const rectArea = w * h * transform.k * transform.k;
        if (rectArea > 1500) { // Don't draw text if box is microscopic
            ctx.fillStyle = '#ffffff';
            ctx.textAlign = 'center';
            ctx.textBaseline = 'middle';

            const fontSize = Math.min(w * 0.2, h * 0.3, 16);
            ctx.font = `bold ${fontSize}px sans-serif`;

            // Draw Ticker
            ctx.fillText(node.data.name, node.x0 + w/2, node.y0 + h/2 - fontSize * 0.4);

            // Draw Percentage
            ctx.font = `${fontSize * 0.8}px sans-serif`;
            ctx.fillStyle = '#e0e0e0';
            const changePct = (node.data.change * 100).toFixed(2) + '%';
            ctx.fillText((node.data.change >= 0 ? '+' : '') + changePct, node.x0 + w/2, node.y0 + h/2 + fontSize * 0.7);
        }
        ctx.restore();
    });

    // Draw Sector Parent Labels (Floating Headers)
    // Only draw headers when not zoomed in too closely to single stocks
    if (transform.k < 3) {
        ctx.fillStyle = 'rgba(255,255,255,0.7)';
        ctx.font = 'bold 10px sans-serif';
        ctx.textAlign = 'left';

        // Find parent nodes (Sectors)
        const sectors = {};
        leaves.forEach(leaf => {
            const p = leaf.parent;
            if (p && !sectors[p.data.name]) {
                sectors[p.data.name] = p;
            }
        });

        for (let key in sectors) {
            const p = sectors[key];
            ctx.fillText(p.data.name, p.x0 + 4, p.y0 + 12);
        }
    }

    ctx.restore();
}

// 6. Setup Zoom & Pan via D3-Zoom
const zoomBehavior = d3.zoom()
    .scaleExtent([0.8, 20]) // Zoom boundaries (min, max)
    .on('zoom', (event) => {
        transform = event.transform;
        render();
    });

d3.select(canvas).call(zoomBehavior);

// 7. Interaction/Hover Handler
canvas.addEventListener('mousemove', (event) => {
    const rect = canvas.getBoundingClientRect();
    // Translate screen coords to canvas workspace
    const mouseX = event.clientX - rect.left;
    const mouseY = event.clientY - rect.top;

    // Convert mouse position to visual "zoomed" space coordinate
    const worldX = (mouseX - transform.x) / transform.k;
    const worldY = (mouseY - transform.y) / transform.k;

    // Find if mouse is inside any leaf node
    const found = leaves.find(node => 
        worldX >= node.x0 && worldX <= node.x1 &&
        worldY >= node.y0 && worldY <= node.y1
    );

    if (found !== hoveredNode) {
        hoveredNode = found;
        render(); // Redraw canvas to apply white border highlighting
    }

    // Update Tooltip UI
    if (hoveredNode) {
        const changeVal = (hoveredNode.data.change * 100).toFixed(2);
        tooltip.style.display = 'block';
        tooltip.style.left = (event.clientX + 15) + 'px';
        tooltip.style.top = (event.clientY + 15) + 'px';
        tooltip.innerHTML = `
            <strong>${hoveredNode.data.name}</strong><br/>
            Sector: ${hoveredNode.parent.data.name}<br/>
            Cap: $${hoveredNode.data.value}B<br/>
            Change: <span style="color:${hoveredNode.data.change >= 0 ? '#26a69a' : '#ef5350'}">
                ${hoveredNode.data.change >= 0 ? '+' : ''}${changeVal}%
            </span>
        `;
    } else {
        tooltip.style.display = 'none';
    }
});

canvas.addEventListener('mouseleave', () => {
    hoveredNode = null;
    tooltip.style.display = 'none';
    render();
});

// 8. Simulated High-Frequency Market Ticks (WebSocket Mock)
setInterval(() => {
    // Choose 1 to 3 random stocks to update every 300ms
    const numUpdates = Math.floor(Math.random() * 3) + 1;
    for (let i = 0; i < numUpdates; i++) {
        const randomIndex = Math.floor(Math.random() * leaves.length);
        const stock = leaves[randomIndex];

        // Tick price up or down by max 0.4%
        const delta = (Math.random() - 0.5) * 0.008;
        stock.data.change += delta;

        // Keep mock data within realistic limits [-15%, +15%]
        stock.data.change = Math.max(-0.15, Math.min(0.15, stock.data.change));
    }

    // Smoothly redraw update
    render();
}, 300);

// Initialize
window.addEventListener('resize', resize);
resize();
</script>
