### 2. The Server (`server.js`)
This server manages the state of the board in memory and synchronizes updates across all connected clients instantly using WebSockets.

```javascript
const express = require('express');
const http = require('http');
const { Server } = require('socket.io');
const path = require('path');

const app = express();
const server = http.createServer(app);
const io = new Server(server);

const PORT = process.env.PORT || 3000;

// Serve static frontend files from the "public" directory
app.use(express.static(path.join(__dirname, 'public')));

// In-memory data store representing the board state
let boardState = {
  'todo': {
    id: 'todo',
    title: 'To Do',
    tasks: [
      { id: 'task-1', content: 'Design collaborative architecture' },
      { id: 'task-2', content: 'Set up Socket.io server' }
    ]
  },
  'inprogress': {
    id: 'inprogress',
    title: 'In Progress',
    tasks: [
      { id: 'task-3', content: 'Build frontend drag-and-drop UI' }
    ]
  },
  'done': {
    id: 'done',
    title: 'Done',
    tasks: []
  }
};

io.on('connection', (socket) => {
  console.log(`User connected: ${socket.id}`);

  // 1. Send the current board state to the newly connected user
  socket.emit('init-state', boardState);

  // 2. Handle adding a new task
  socket.on('add-task', (columnId, content) => {
    const newTask = {
      id: `task-${Date.now()}`,
      content
    };
    boardState[columnId].tasks.push(newTask);

    // Broadcast state update to everyone, including sender
    io.emit('state-updated', boardState);
  });

  // 3. Handle moving a task (Drag & Drop)
  socket.on('move-task', ({ taskId, sourceCol, targetCol, targetIndex }) => {
    // Find and remove task from source column
    let taskToMove = null;
    boardState[sourceCol].tasks = boardState[sourceCol].tasks.filter(task => {
      if (task.id === taskId) {
        taskToMove = task;
        return false;
      }
      return true;
    });

    if (taskToMove) {
      // Insert task at specific index in target column
      boardState[targetCol].tasks.splice(targetIndex, 0, taskToMove);

      // Broadcast state update to all other connected clients
      socket.broadcast.emit('state-updated', boardState);
    }
  });

  // 4. Handle deleting a task
  socket.on('delete-task', (taskId, columnId) => {
    boardState[columnId].tasks = boardState[columnId].tasks.filter(task => task.id !== taskId);
    io.emit('state-updated', boardState);
  });

  socket.on('disconnect', () => {
    console.log(`User disconnected: ${socket.id}`);
  });
});

server.listen(PORT, () => {
  console.log(`Server is running on http://localhost:${PORT}`);
});
```

