### 1. The Backend (`server.js`)
This server manages the state of the board and broadcasts any updates (new tasks, moved tasks) to all connected clients in real-time.

```javascript
const express = require('express');
const http = require('http');
const WebSocket = require('ws');
const path = require('path');

const app = express();
const server = http.createServer(app);
const wss = new WebSocket.Server({ server });

app.use(express.static(path.join(__dirname, 'public')));

// Initial Server State (Single source of truth)
let boardState = {
  todo: [
    { id: 'task-1', content: 'Create project repository' },
    { id: 'task-2', content: 'Design collaborative database schema' }
  ],
  inprogress: [
    { id: 'task-3', content: 'Configure WebSocket server' }
  ],
  done: [
    { id: 'task-4', content: 'Install Node JS' }
  ]
};

// Broadcasts data to all connected clients
function broadcast(data, excludeWs = null) {
  const message = JSON.stringify(data);
  wss.clients.forEach((client) => {
    if (client.readyState === WebSocket.OPEN && client !== excludeWs) {
      client.send(message);
    }
  });
}

wss.on('connection', (ws) => {
  console.log('Client connected. Total clients:', wss.clients.size);

  // 1. Send the current state of the board immediately on connection
  ws.send(JSON.stringify({ type: 'INIT', state: boardState }));

  // 2. Listen for mutations from clients
  ws.on('message', (message) => {
    try {
      const action = JSON.parse(message);

      switch (action.type) {
        case 'UPDATE_BOARD':
          boardState = action.state;
          // Broadcast the updated board to all other clients
          broadcast({ type: 'BOARD_UPDATED', state: boardState }, ws);
          break;
        default:
          console.warn('Unknown action type:', action.type);
      }
    } catch (err) {
      console.error('Error handling WebSocket message:', err);
    }
  });

  ws.on('close', () => {
    console.log('Client disconnected. Total clients:', wss.clients.size);
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

