### 1. The Backend Server: `server.js`
This Node.js server maintains the board state in memory and uses the `ws` library to broadcast changes to all connected clients in real-time.

```javascript
import { WebSocketServer } from 'ws';
import express from 'express';
import http from 'http';
import path from 'path';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

const app = express();
const server = http.createServer(app);
const wss = new WebSocketServer({ server });

// Serve static files from the 'public' directory
app.use(express.static(path.join(__dirname, 'public')));

// Initial Board State
let boardState = {
  todo: [
    { id: 'task-1', content: 'Design system architecture' },
    { id: 'task-2', content: 'Set up database schema' }
  ],
  inprogress: [
    { id: 'task-3', content: 'Implement WebSocket server' }
  ],
  done: [
    { id: 'task-4', content: 'Project kickoff meeting' }
  ]
};

// Broadcast updates to all connected clients
function broadcast(message, excludeWs = null) {
  const payload = JSON.stringify(message);
  wss.clients.forEach((client) => {
    if (client !== excludeWs && client.readyState === 1) {
      client.send(payload);
    }
  });
}

wss.on('connection', (ws) => {
  console.log('Client connected');

  // Send the current board state to the newly connected client
  ws.send(JSON.stringify({ type: 'INITIAL_STATE', data: boardState }));

  ws.on('message', (message) => {
    try {
      const { type, data } = JSON.parse(message);

      if (type === 'MOVE_TASK') {
        const { taskId, fromCol, toCol, targetIndex } = data;

        // Find and remove task from source column
        const taskIndex = boardState[fromCol].findIndex(t => t.id === taskId);
        if (taskIndex !== -1) {
          const [task] = boardState[fromCol].splice(taskIndex, 1);

          // Insert task into destination column at target index
          boardState[toCol].splice(targetIndex, 0, task);

          // Broadcast the updated state to everyone else
          broadcast({ type: 'UPDATE_STATE', data: boardState }, ws);
        }
      }

      if (type === 'ADD_TASK') {
        const { columnId, content } = data;
        const newTask = {
          id: `task-${Date.now()}`,
          content: content
        };
        boardState[columnId].push(newTask);

        // Broadcast state update to everyone (including sender to get the new ID)
        broadcast({ type: 'UPDATE_STATE', data: boardState });
      }
    } catch (err) {
      console.error('Error processing message:', err);
    }
  });

  ws.on('close', () => console.log('Client disconnected'));
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

