        container.addEventListener('drop', (e) => {
          e.preventDefault();
          container.classList.remove('drag-over');

          if (!draggedElement) return;

          const targetColId = colId;
          const taskId = draggedElement.id;

          // Calculate dropping index position relative to surrounding cards
          const cardsInCol = [...container.querySelectorAll('[draggable="true"]')];
          const dropY = e.clientY;
          let targetIndex = cardsInCol.length;

          for (let i = 0; i < cardsInCol.length; i++) {
            const rect = cardsInCol[i].getBoundingClientRect();
            const cardMiddleY = rect.top + rect.height / 2;
            if (dropY < cardMiddleY) {
              targetIndex = i;
              break;
            }
          }

          // Optimistically update local UI state before WS broadcast
          if (sourceColumnId !== targetColId || boardState[sourceColumnId].findIndex(t => t.id === taskId) !== targetIndex) {

            // Send event payload to WebSocket Server
            socket.send(JSON.stringify({
              type: 'MOVE_TASK',
              data: { taskId, fromCol: sourceColumnId, toCol: targetColId, targetIndex }
            }));

            // Local State update
            const sourceIndex = boardState[sourceColumnId].findIndex(t => t.id === taskId);
            const [movedTask] = boardState[sourceColumnId].splice(sourceIndex, 1);
            boardState[targetColId].splice(targetIndex, 0, movedTask);
            renderBoard();
          }

          draggedElement = null;
        });
      });
    }

    function removeDragOverStyles() {
      document.querySelectorAll('.task-list').forEach(list => list.classList.remove('drag-over'));
    }

    // Add Task Prompt
    function openAddTaskModal(columnId) {
      const content = prompt("Enter task details:");
      if (content && content.trim() !== "") {
        socket.send(JSON.stringify({
          type: 'ADD_TASK',
          data: { columnId, content: content.trim() }
        }));
      }
    }

    // Initialize Connection
    connect();
  </script>
</body>
</html>
