### 1. The Backend: `server.js`
This server manages the global state of the project board and broadcasts updates to all connected clients in real-time.

```javascript
const { WebSocketServer } = require('ws');

// Spin up a WebSocket server on port 8080
const wss = new WebSocketServer({ port: 8080 });

// Global board state stored in-memory
let boardState = {
  todo: [
    { id: 'task-1', content: 'Design database schema' },
    { id: 'task-2', content: 'Set up WebSocket server' }
  ],
  inprogress: [
    { id: 'task-3', content: 'Build UI prototype' }
  ],
  done: [
    { id: 'task-4', content: 'Write project requirements' }
  ]
};

console.log('WebSocket Server started on ws://localhost:8080');

wss.on('connection', (ws) => {
  console.log('New client connected');

  // 1. Send the initial board state to the newly connected client
  ws.send(JSON.stringify({ type: 'INIT', data: boardState }));

  // 2. Listen for board updates from clients
  ws.on('message', (message) => {
    try {
      const packet = JSON.parse(message);

      if (packet.type === 'UPDATE_BOARD') {
        boardState = packet.data;

        // Broadcast the updated state to ALL OTHER connected clients
        wss.clients.forEach((client) => {
          if (client !== ws && client.readyState === 1) { // 1 = OPEN
            client.send(JSON.stringify({ type: 'UPDATE_BOARD', data: boardState }));
          }
        });
      }
    } catch (err) {
      console.error('Error handling message:', err);
    }
  });

  ws.on('close', () => {
    console.log('Client disconnected');
  });
});
```

