    let ws;
    let boardState = { todo: [], inprogress: [], done: [] };

    // --- 1. WebSocket connection setup ---
    function connect() {
      ws = new WebSocket('ws://localhost:8080');

      ws.onopen = () => {
        document.getElementById('connection-status-dot').className = "h-3 w-3 rounded-full bg-green-500";
        document.getElementById('connection-status-text').innerText = "Live Collaboration Connected";
      };

      ws.onmessage = (event) => {
