        if (packet.type === 'INIT' || packet.type === 'UPDATE_BOARD') {
          boardState = packet.data;
          renderBoard();
        }
      };

      ws.onclose = () => {
        document.getElementById('connection-status-dot').className = "h-3 w-3 rounded-full bg-red-500 animate-pulse";
        document.getElementById('connection-status-text').innerText = "Disconnected. Reconnecting...";
        setTimeout(connect, 3000); // Reconnect attempt every 3 seconds
      };
    }

    // Send board state updates to the server
    function sendUpdate() {
      if (ws && ws.readyState === WebSocket.OPEN) {
        ws.send(JSON.stringify({ type: 'UPDATE_BOARD', data: boardState }));
      }
    }

    // --- 2. Render functions ---
    function renderBoard() {
      const columns = ['todo', 'inprogress', 'done'];

      columns.forEach(colId => {
        const columnEl = document.getElementById(colId);
        columnEl.innerHTML = ''; // Clear previous items

        // Set task count badge
        document.getElementById(`count-${colId}`).innerText = boardState[colId].length;

        boardState[colId].forEach(task => {
          const card = document.createElement('div');
          card.id = task.id;
          card.className = "bg-white p-4 rounded-xl shadow-sm border border-slate-200 cursor-grab active:cursor-grabbing hover:shadow-md transition-shadow flex justify-between items-center group";
          card.setAttribute('draggable', 'true');

          // Attach Drag events
          card.ondragstart = (e) => dragStart(e, task.id, colId);

          card.innerHTML = `
            <span class="text-slate-700 font-medium">${task.content}</span>
            <button onclick="deleteTask('${task.id}', '${colId}')" class="text-slate-400 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-opacity">
              🗑️
            </button>
          `;
          columnEl.appendChild(card);
        });
      });
    }

    // --- 3. Drag and Drop Actions ---
    function dragStart(e, taskId, fromCol) {
      e.dataTransfer.setData('text/plain', JSON.stringify({ taskId, fromCol }));
    }

    function allowDrop(e) {
      e.preventDefault(); // Required to allow drop action
    }

    function dragEnter(e) {
      e.currentTarget.classList.add('drag-over');
    }

    function dragLeave(e) {
      e.currentTarget.classList.remove('drag-over');
    }

    function drop(e) {
      e.preventDefault();
      const dropzone = e.currentTarget;
      dropzone.classList.remove('drag-over');

      const targetCol = dropzone.id;
      const data = JSON.parse(e.dataTransfer.getData('text/plain'));
      const { taskId, fromCol } = data;

      // Prevent processing if dropped in same column
      if (fromCol === targetCol) return;

      // Find task object
      const taskIndex = boardState[fromCol].findIndex(t => t.id === taskId);
      const [task] = boardState[fromCol].splice(taskIndex, 1);

      // Append to target column
      boardState[targetCol].push(task);

      // Render locally and sync to other clients
      renderBoard();
      sendUpdate();
    }

    // --- 4. Application State Actions (Create / Delete) ---
    function addNewTask() {
      const input = document.getElementById('task-input');
      const text = input.value.trim();
      if (!text) return;

      const newTask = {
        id: 'task-' + Date.now(),
        content: text
      };

      boardState.todo.push(newTask);
      input.value = '';

      renderBoard();
      sendUpdate();
    }

    function deleteTask(taskId, colId) {
      boardState[colId] = boardState[colId].filter(t => t.id !== taskId);
      renderBoard();
      sendUpdate();
    }

    // Initialize Connection on start
    connect();
  </script>
