import { WebSocketServer, WebSocket } from 'ws';

const wss = new WebSocketServer({ port: 8080 });

interface Task {
  id: string;
  title: string;
  description: string;
}

interface BoardState {
  [columnId: string]: Task[];
}

// Initial default board state
let currentBoardState: BoardState = {
  'To Do': [
    { id: '1', title: 'Setup Project', description: 'Initialize repository and setup build tools.' },
    { id: '2', title: 'Design Database', description: 'Create schema for users, boards, and tasks.' }
  ],
  'In Progress': [
    { id: '3', title: 'Implement Auth', description: 'OAuth2 and JWT integration.' }
  ],
  'Done': [
    { id: '4', title: 'Project Kickoff', description: 'Align with stakeholders on deliverables.' }
  ]
};

// Track connected clients
const clients = new Set<WebSocket>();

wss.on('connection', (ws: WebSocket) => {
  clients.add(ws);
  console.log(`Client connected. Total clients: ${clients.size}`);

  // Send the current board state to the newly connected client
  ws.send(JSON.stringify({ type: 'INIT', data: currentBoardState }));

  ws.on('message', (message: string) => {
    try {
      const parsed = JSON.parse(message);

      if (parsed.type === 'UPDATE_BOARD') {
        currentBoardState = parsed.data;

        // Broadcast the updated state to ALL OTHER connected clients
        clients.forEach((client) => {
          if (client !== ws && client.readyState === WebSocket.OPEN) {
            client.send(JSON.stringify({ type: 'BOARD_UPDATED', data: currentBoardState }));
          }
        });
      }
    } catch (err) {
      console.error('Failed to parse message:', err);
    }
  });

  ws.on('close', () => {
    clients.delete(ws);
    console.log(`Client disconnected. Total clients: ${clients.size}`);
  });
});

console.log('WebSocket server is running on ws://localhost:8080');
