### 2. The Frontend (React + TypeScript + Tailwind)

This frontend handles the drag-and-drop state updates locally and synchronizes updates with the WebSocket server.

#### `frontend/src/App.tsx`
```typescript
import React, { useState, useEffect, useRef } from 'react';

interface Task {
  id: string;
  title: string;
  description: string;
}

interface BoardState {
  [columnId: string]: Task[];
}

const COLUMNS = ['To Do', 'In Progress', 'Done'];

export default function App() {
  const [board, setBoard] = useState<BoardState>({});
  const [connectionStatus, setConnectionStatus] = useState<'Connecting' | 'Connected' | 'Disconnected'>('Connecting');
  const ws = useRef<WebSocket | null>(null);

  // Initialize WebSocket connection
  useEffect(() => {
    ws.current = new WebSocket('ws://localhost:8080');

    ws.current.onopen = () => setConnectionStatus('Connected');
    ws.current.onclose = () => setConnectionStatus('Disconnected');

    ws.current.onmessage = (event) => {
      const message = JSON.parse(event.data);
      if (message.type === 'INIT' || message.type === 'BOARD_UPDATED') {
        setBoard(message.data);
      }
    };

    return () => {
      ws.current?.close();
    };
  }, []);

  // Sync board state with backend
  const updateRemoteBoard = (updatedBoard: BoardState) => {
    setBoard(updatedBoard);
    if (ws.current && ws.current.readyState === WebSocket.OPEN) {
      ws.current.send(JSON.stringify({
        type: 'UPDATE_BOARD',
        data: updatedBoard
      }));
    }
  };

  // HTML5 Drag and Drop Handlers
  const handleDragStart = (e: React.DragEvent, taskId: string, sourceCol: string) => {
    e.dataTransfer.setData('text/plain', JSON.stringify({ taskId, sourceCol }));
    e.dataTransfer.effectAllowed = 'move';
  };

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault(); // Required to allow dropping
  };

  const handleDrop = (e: React.DragEvent, targetCol: string) => {
    e.preventDefault();
    const dataStr = e.dataTransfer.getData('text/plain');
    if (!dataStr) return;

    const { taskId, sourceCol } = JSON.parse(dataStr);

    if (sourceCol === targetCol) return;

    const sourceTasks = [...board[sourceCol]];
    const targetTasks = [...board[targetCol]];

    // Find and remove task from source column
    const taskIndex = sourceTasks.findIndex(t => t.id === taskId);
    const [movedTask] = sourceTasks.splice(taskIndex, 1);

    // Add task to target column
    targetTasks.push(movedTask);

    const newBoardState = {
      ...board,
      [sourceCol]: sourceTasks,
      [targetCol]: targetTasks
    };

    updateRemoteBoard(newBoardState);
  };

  // Create a new task helper
  const handleAddTask = (columnId: string) => {
    const title = prompt('Enter task title:');
    if (!title) return;

    const newTask: Task = {
      id: Date.now().toString(),
      title,
      description: 'Click to add description.'
    };

    const newBoardState = {
      ...board,
      [columnId]: [...(board[columnId] || []), newTask]
    };

    updateRemoteBoard(newBoardState);
  };

  return (
    <div className="min-h-screen bg-slate-900 text-slate-100 p-8 font-sans">
      {/* Header */}
      <header className="flex justify-between items-center mb-8 pb-4 border-b border-slate-800">
        <div>
          <h1 className="text-3xl font-extrabold tracking-tight bg-gradient-to-r from-blue-400 to-emerald-400 bg-clip-text text-transparent">
            CoBoard
          </h1>
          <p className="text-sm text-slate-400 mt-1">Real-time collaborative workspace</p>
        </div>
        <div className="flex items-center gap-2">
          <span className={`h-3 w-3 rounded-full ${
            connectionStatus === 'Connected' ? 'bg-emerald-500 animate-pulse' : 'bg-rose-500'
          }`} />
          <span className="text-sm font-medium text-slate-300">{connectionStatus}</span>
        </div>
      </header>

      {/* Board Layout */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        {COLUMNS.map((columnId) => (
          <div
            key={columnId}
            onDragOver={handleDragOver}
            onDrop={(e) => handleDrop(e, columnId)}
            className="bg-slate-800/50 rounded-xl p-4 border border-slate-800 flex flex-col min-h-[500px]"
          >
            <div className="flex justify-between items-center mb-4">
              <h2 className="font-semibold text-lg text-slate-200">{columnId}</h2>
              <span className="bg-slate-700 text-slate-300 text-xs px-2 py-1 rounded-full font-bold">
                {board[columnId]?.length || 0}
              </span>
            </div>

            {/* Tasks list */}
            <div className="flex-1 space-y-3 overflow-y-auto">
              {board[columnId]?.map((task) => (
                <div
                  key={task.id}
                  draggable
                  onDragStart={(e) => handleDragStart(e, task.id, columnId)}
                  className="bg-slate-800 p-4 rounded-lg border border-slate-700/50 shadow-md cursor-grab active:cursor-grabbing hover:border-blue-500/50 transition duration-150 group relative"
                >
                  <h3 className="font-medium text-slate-100 group-hover:text-blue-400 transition">
                    {task.title}
                  </h3>
                  <p className="text-xs text-slate-400 mt-2 line-clamp-2">
                    {task.description}
                  </p>
                </div>
              ))}
            </div>

            {/* Add Task Button */}
            <button
              onClick={() => handleAddTask(columnId)}
              className="mt-4 w-full py-2 bg-slate-800 hover:bg-slate-700 border border-slate-700 hover:border-slate-600 rounded-lg text-sm text-slate-300 font-medium transition flex items-center justify-center gap-1"
            >
              + Add Task
            </button>
          </div>
        ))}
      </div>
    </div>
  );
}
```

