### 1. The Backend: `server.js`
This server hosts the static frontend files, manages the state of the tasks, handles real-time WebSocket connections, and broadcasts events (like moves and additions) to all clients.

```javascript
import express from 'express';
import { createServer } from 'http';
import { WebSocketServer, WebSocket } from 'ws';
import path from 'path';
import { fileURLToPath } from 'url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const app = express();
const server = createServer(app);
const wss = new WebSocketServer({ server });

// Serve frontend static files
app.use(express.static(path.join(__dirname, 'public')));

// In-memory database
let state = {
  tasks: [
    { id: 'task-1', title: 'Create wireframes', column: 'todo' },
    { id: 'task-2', title: 'Set up WebSocket server', column: 'in-progress' },
    { id: 'task-3', title: 'Write documentation', column: 'done' }
  ]
};

// Track active connections
let activeConnections = 0;

wss.on('connection', (ws) => {
  activeConnections++;
  console.log(`Client connected. Total active: ${activeConnections}`);

  // 1. Send current board state & client count to the newly connected client
  ws.send(JSON.stringify({ type: 'INIT', state, activeConnections }));

  // Broadcast updated user count to all clients
  broadcast({ type: 'USERS_UPDATE', activeConnections });

  // 2. Handle incoming real-time actions from clients
  ws.on('message', (message) => {
    try {
      const action = JSON.parse(message);

      switch (action.type) {
        case 'MOVE_TASK': {
          const { taskId, targetColumn } = action.payload;
          const task = state.tasks.find(t => t.id === taskId);
          if (task) {
            task.column = targetColumn;
            // Broadcast the move to EVERYONE except the sender (to avoid jitter)
            broadcastExcept(ws, { type: 'TASK_MOVED', payload: { taskId, targetColumn } });
          }
          break;
        }
        case 'ADD_TASK': {
          const newTask = {
            id: `task-${Date.now()}`,
            title: action.payload.title,
            column: 'todo'
          };
          state.tasks.push(newTask);
          // Broadcast the new task to ALL clients
          broadcast({ type: 'TASK_ADDED', payload: newTask });
          break;
        }
      }
    } catch (err) {
      console.error('Error handling message:', err);
    }
  });

  ws.on('close', () => {
    activeConnections--;
    console.log(`Client disconnected. Total active: ${activeConnections}`);
    broadcast({ type: 'USERS_UPDATE', activeConnections });
  });
});

// Helper: Broadcast to all connected clients
function broadcast(data) {
  const message = JSON.stringify(data);
  wss.clients.forEach((client) => {
    if (client.readyState === WebSocket.OPEN) {
      client.send(message);
    }
  });
}

// Helper: Broadcast to everyone except the initiator (for optimistic UI sync)
function broadcastExcept(excludeWs, data) {
  const message = JSON.stringify(data);
  wss.clients.forEach((client) => {
    if (client !== excludeWs && client.readyState === WebSocket.OPEN) {
      client.send(message);
    }
  });
}

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Collab board running at http://localhost:${PORT}`);
});
```

