### Part 1: Backend Setup (`server.js`)

This server maintains the board state in-memory (acting as a lightweight database) and uses Socket.io to sync state changes across all connected clients in real time.

Create a directory named `collab-board-backend`, run `npm init -y`, install dependencies (`npm install express socket.io cors`), and create `server.js`:

```javascript
// server.js
const express = require('express');
const http = require('http');
const { Server } = require('socket.io');
const cors = require('cors');

const app = express();
app.use(cors());

const server = http.createServer(app);
const io = new Server(server, {
  cors: {
    origin: "http://localhost:5173", // URL of our React frontend
    methods: ["GET", "POST"]
  }
});

// Initial mock DB / shared application state
let boardState = {
  tasks: {
    'task-1': { id: 'task-1', content: 'Design landing page mockup' },
    'task-2': { id: 'task-2', content: 'Set up backend WebSocket server' },
    'task-3': { id: 'task-3', content: 'Implement Drag-and-Drop frontend' },
  },
  columns: {
    'todo': {
      id: 'todo',
      title: 'To Do',
      taskIds: ['task-1'],
    },
    'in-progress': {
      id: 'in-progress',
      title: 'In Progress',
      taskIds: ['task-2'],
    },
    'done': {
      id: 'done',
      title: 'Done',
      taskIds: ['task-3'],
    },
  },
  columnOrder: ['todo', 'in-progress', 'done'],
};

io.on('connection', (socket) => {
  console.log(`User connected: ${socket.id}`);

  // 1. Send the current state to the newly connected user
  socket.emit('init-state', boardState);

  // 2. Listen for drag-and-drop state updates from a user
  socket.on('update-board', (updatedState) => {
    boardState = updatedState; // Update mock DB
    // Broadcast the new state to all OTHER connected clients
    socket.broadcast.emit('board-updated', boardState);
  });

  // 3. Listen for new tasks being added
  socket.on('add-task', ({ columnId, content }) => {
    const newTaskId = `task-${Date.now()}`;
    boardState.tasks[newTaskId] = { id: newTaskId, content };
    boardState.columns[columnId].taskIds.push(newTaskId);

    // Broadcast updated state to EVERYONE (including sender to confirm update)
    io.emit('board-updated', boardState);
  });

  socket.on('disconnect', () => {
    console.log(`User disconnected: ${socket.id}`);
  });
});

const PORT = 3001;
server.listen(PORT, () => {
  console.log(`Real-time server running on http://localhost:${PORT}`);
});
```

