### Part 2: Frontend Setup (`App.tsx`)

This React component connects to the backend WebSocket, renders the board using standard HTML5 drag-and-drop logic, and dispatches updates to the socket server.

Create a Vite + React + TypeScript project (`npm create vite@latest collab-board-frontend -- --template react-ts`), install Socket.io client (`npm install socket.io-client`), configure Tailwind CSS, and replace `src/App.tsx` with:

```tsx
// App.tsx
import React, { useEffect, useState } from 'react';
import { io, Socket } from 'socket.io-client';

// Types matches our backend data structure
interface Task {
  id: string;
  content: string;
}

interface Column {
  id: string;
  title: string;
  taskIds: string[];
}

interface BoardState {
  tasks: Record<string, Task>;
  columns: Record<string, Column>;
  columnOrder: string[];
}

const socket: Socket = io('http://localhost:3001');

export default function App() {
  const [board, setBoard] = useState<BoardState | null>(null);
  const [newTaskText, setNewTaskText] = useState('');

  useEffect(() => {
    // Listen for initial board state
    socket.on('init-state', (initialState: BoardState) => {
      setBoard(initialState);
    });

    // Listen for real-time updates from other users
    socket.on('board-updated', (updatedState: BoardState) => {
      setBoard(updatedState);
    });

    return () => {
      socket.off('init-state');
      socket.off('board-updated');
    };
  }, []);

  // HTML5 Drag Event Handlers
  const handleDragStart = (e: React.DragEvent, taskId: string, sourceColId: string) => {
    e.dataTransfer.setData('taskId', taskId);
    e.dataTransfer.setData('sourceColId', sourceColId);
  };

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault(); // Required to allow dropping
  };

  const handleDrop = (e: React.DragEvent, targetColId: string) => {
    e.preventDefault();
    if (!board) return;

    const taskId = e.dataTransfer.getData('taskId');
    const sourceColId = e.dataTransfer.getData('sourceColId');

    // If dropped in the same column, do nothing (or rearrange if keeping index)
    if (sourceColId === targetColId) return;

    // Create deep copy of state to update immutably
    const newColumns = { ...board.columns };

    // Remove task from old column
    newColumns[sourceColId].taskIds = newColumns[sourceColId].taskIds.filter(id => id !== taskId);
    // Add task to new column
    newColumns[targetColId].taskIds.push(taskId);

    const updatedState = {
      ...board,
      columns: newColumns,
    };

    setBoard(updatedState); // Optimistic UI update
    socket.emit('update-board', updatedState); // Send to backend for sync
  };

  const handleAddTask = (columnId: string) => {
    if (!newTaskText.trim()) return;
    socket.emit('add-task', { columnId, content: newTaskText });
    setNewTaskText('');
  };

  if (!board) {
    return (
      <div className="flex h-screen items-center justify-center bg-gray-900 text-white">
        <p className="text-xl animate-pulse">Connecting to collaborative canvas...</p>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-950 text-gray-100 p-8 font-sans">
      <header className="mb-10 max-w-6xl mx-auto flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-extrabold tracking-tight">SyncBoard ⚡</h1>
          <p className="text-gray-400 text-sm mt-1">Real-time collaborative workspace. Open multiple browser tabs to watch sync.</p>
        </div>
        <div className="flex items-center space-x-2 bg-gray-900 px-4 py-2 rounded-full border border-gray-800">
          <span className="h-2 w-2 rounded-full bg-emerald-500 animate-ping"></span>
          <span className="text-xs font-semibold text-emerald-400">Live Connection Active</span>
        </div>
      </header>

      {/* Main Board Layout */}
      <main className="max-w-6xl mx-auto grid grid-cols-1 md:grid-cols-3 gap-6">
        {board.columnOrder.map((columnId) => {
          const column = board.columns[columnId];
          const tasks = column.taskIds.map((taskId) => board.tasks[taskId]);

          return (
            <div
              key={column.id}
              onDragOver={handleDragOver}
              onDrop={(e) => handleDrop(e, column.id)}
              className="bg-gray-900 rounded-xl p-4 border border-gray-800 flex flex-col min-h-[500px]"
            >
              <div className="flex items-center justify-between mb-4">
                <h2 className="font-bold text-lg text-gray-200">{column.title}</h2>
                <span className="text-xs bg-gray-800 text-gray-400 px-2.5 py-1 rounded-full font-mono">
                  {tasks.length}
                </span>
              </div>

              {/* Task list container */}
              <div className="flex-grow space-y-3">
                {tasks.map((task) => (
                  <div
                    key={task.id}
                    draggable
                    onDragStart={(e) => handleDragStart(e, task.id, column.id)}
                    className="p-4 bg-gray-800 hover:bg-gray-750 border border-gray-750 hover:border-gray-600 rounded-lg shadow-md cursor-grab active:cursor-grabbing transition duration-150 ease-in-out group"
                  >
                    <p className="text-sm text-gray-300 group-hover:text-white leading-relaxed">
                      {task.content}
                    </p>
                  </div>
                ))}
              </div>

              {/* Add New Task Input Area */}
              {columnId === 'todo' && (
                <div className="mt-4 pt-4 border-t border-gray-850 space-y-2">
                  <input
                    type="text"
                    value={newTaskText}
                    onChange={(e) => setNewTaskText(e.target.value)}
                    placeholder="Type a new task..."
                    className="w-full text-xs px-3 py-2 rounded bg-gray-950 border border-gray-800 focus:outline-none focus:border-indigo-500 text-white"
                  />
                  <button
                    onClick={() => handleAddTask(columnId)}
                    className="w-full text-xs bg-indigo-600 hover:bg-indigo-500 font-semibold text-white py-2 px-3 rounded transition"
                  >
                    + Add New Card
                  </button>
                </div>
              )}
            </div>
          );
        })}
      </main>
    </div>
  );
}
```

