### 2. `server.js`
This script serves the static HTML file and runs a WebSocket server. It maintains a single source of truth (the board state) in-memory and broadcasts updates to all connected users in real time.

```javascript
const express = require('express');
const http = require('http');
const WebSocket = require('ws');
const path = require('path');

const app = express();
const server = http.createServer(app);
const wss = new WebSocket.Server({ server });

// Serve static files from the "public" directory
app.use(express.static(path.join(__dirname, 'public')));

// In-memory state of our board
let boardState = {
  tasks: [
    { id: 'task-1', title: 'Setup WebSocket Server', status: 'todo' },
    { id: 'task-2', title: 'Implement Drag-and-Drop', status: 'in-progress' },
    { id: 'task-3', title: 'Styling with Tailwind', status: 'done' }
  ]
};

// Broadcast updates to all connected clients
function broadcast(data, excludeWs = null) {
  const message = JSON.stringify(data);
  wss.clients.forEach((client) => {
    if (client.readyState === WebSocket.OPEN && client !== excludeWs) {
      client.send(message);
    }
  });
}

wss.on('connection', (ws) => {
  console.log('New client connected');

  // Send initial state to the newly connected client
  ws.send(JSON.stringify({ type: 'INITIAL_STATE', payload: boardState }));

  ws.on('message', (message) => {
    try {
      const { type, payload } = JSON.parse(message);

      if (type === 'UPDATE_TASKS') {
        // Update local server state
        boardState.tasks = payload;
        // Broadcast the update to all OTHER clients
        broadcast({ type: 'STATE_UPDATED', payload: boardState }, ws);
      }
    } catch (err) {
      console.error('Error handling message:', err);
    }
  });

  ws.on('close', () => {
    console.log('Client disconnected');
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server is running on http://localhost:${PORT}`);
});
```

