  <title>Real-Time Collaborative Kanban Board</title>
  <!-- Tailwind CSS CDN -->
  <script src="https://cdn.tailwindcss.com"></script>
</head>
<body class="bg-gray-100 font-sans min-h-screen flex flex-col">

  <!-- Header -->
  <header class="bg-white shadow px-6 py-4 flex justify-between items-center">
    <h1 class="text-2xl font-bold text-gray-800">Collaborative Board</h1>
    <div class="flex items-center space-x-3">
      <span id="connection-status" class="px-3 py-1 rounded-full text-xs font-semibold bg-yellow-100 text-yellow-800">Connecting...</span>
    </div>
  </header>

  <!-- Main Board Area -->
  <main class="flex-grow p-6">
    <!-- Add Task Input -->
    <div class="mb-6 flex space-x-2 max-w-md">
      <input id="new-task-input" type="text" placeholder="Add a new task..." class="flex-grow p-2 border rounded shadow-sm focus:outline-none focus:ring-2 focus:ring-blue-500" />
      <button onclick="addTask()" class="bg-blue-600 hover:bg-blue-700 text-white font-semibold px-4 py-2 rounded shadow transition">Add Task</button>
    </div>

    <!-- Kanban Columns -->
    <div class="grid grid-cols-1 md:grid-cols-3 gap-6">

      <!-- TO DO Column -->
      <div class="bg-gray-200 p-4 rounded-lg flex flex-col min-h-[400px]">
        <h2 class="font-bold text-lg text-gray-700 mb-4 flex justify-between">
          To Do <span id="count-todo" class="bg-gray-300 text-gray-700 px-2 rounded-full text-sm">0</span>
        </h2>
        <div id="todo" class="column flex-grow space-y-3" ondragover="allowDrop(event)" ondragenter="dragEnter(event)" ondragleave="dragLeave(event)" ondrop="drop(event, 'todo')">
          <!-- Cards injected here -->
        </div>
      </div>

      <!-- IN PROGRESS Column -->
      <div class="bg-gray-200 p-4 rounded-lg flex flex-col min-h-[400px]">
        <h2 class="font-bold text-lg text-gray-700 mb-4 flex justify-between">
          In Progress <span id="count-in-progress" class="bg-gray-300 text-gray-700 px-2 rounded-full text-sm">0</span>
        </h2>
        <div id="in-progress" class="column flex-grow space-y-3" ondragover="allowDrop(event)" ondragenter="dragEnter(event)" ondragleave="dragLeave(event)" ondrop="drop(event, 'in-progress')">
          <!-- Cards injected here -->
        </div>
      </div>

      <!-- DONE Column -->
      <div class="bg-gray-200 p-4 rounded-lg flex flex-col min-h-[400px]">
        <h2 class="font-bold text-lg text-gray-700 mb-4 flex justify-between">
          Done <span id="count-done" class="bg-gray-300 text-gray-700 px-2 rounded-full text-sm">0</span>
        </h2>
        <div id="done" class="column flex-grow space-y-3" ondragover="allowDrop(event)" ondragenter="dragEnter(event)" ondragleave="dragLeave(event)" ondrop="drop(event, 'done')">
          <!-- Cards injected here -->
        </div>
      </div>

    </div>
  </main>

  <script>
    let ws;
    let localTasks = [];

    // --- WebSocket Setup ---
    function connectWebSocket() {
      const protocol = window.location.protocol === 'https:' ? 'wss:' : 'ws:';
      ws = new WebSocket(`${protocol}//${window.location.host}`);

      const statusIndicator = document.getElementById('connection-status');

      ws.onopen = () => {
        statusIndicator.innerText = 'Connected Live';
        statusIndicator.className = 'px-3 py-1 rounded-full text-xs font-semibold bg-green-100 text-green-800';
      };

      ws.onclose = () => {
        statusIndicator.innerText = 'Disconnected (Reconnecting...)';
        statusIndicator.className = 'px-3 py-1 rounded-full text-xs font-semibold bg-red-100 text-red-800';
        setTimeout(connectWebSocket, 3000); // Reconnection strategy
      };

      ws.onmessage = (event) => {
        const { type, payload } = JSON.parse(event.data);
        if (type === 'INITIAL_STATE' || type === 'STATE_UPDATED') {
          localTasks = payload.tasks;
          renderBoard();
        }
      };
    }

    // --- Drag and Drop Logic ---
    function allowDrop(ev) {
      ev.preventDefault();
    }

    function drag(ev) {
      ev.dataTransfer.setData("taskId", ev.target.id);
      ev.target.classList.add('opacity-50');
    }

    function dragEnd(ev) {
      ev.target.classList.remove('opacity-50');
    }

    function dragEnter(ev) {
      if (ev.currentTarget.classList.contains('column')) {
        ev.currentTarget.classList.add('bg-gray-300/50');
      }
    }

    function dragLeave(ev) {
      if (ev.currentTarget.classList.contains('column')) {
        ev.currentTarget.classList.remove('bg-gray-300/50');
      }
    }

    function drop(ev, targetStatus) {
      ev.preventDefault();
      const columnElement = ev.currentTarget;
      columnElement.classList.remove('bg-gray-300/50');

      const taskId = ev.dataTransfer.getData("taskId");

      // Update local state
      const taskIndex = localTasks.findIndex(t => t.id === taskId);
      if (taskIndex !== -1 && localTasks[taskIndex].status !== targetStatus) {
        localTasks[taskIndex].status = targetStatus;
        renderBoard();
        syncWithServer();
      }
    }

    // --- Client-side State Mutations ---
    function addTask() {
      const input = document.getElementById('new-task-input');
      const title = input.value.trim();
      if (!title) return;

      const newTask = {
        id: 'task-' + Date.now(),
        title: title,
        status: 'todo'
      };

      localTasks.push(newTask);
      renderBoard();
      syncWithServer();
      input.value = '';
    }

    function deleteTask(taskId) {
      localTasks = localTasks.filter(t => t.id !== taskId);
      renderBoard();
      syncWithServer();
    }

    function syncWithServer() {
      if (ws && ws.readyState === WebSocket.OPEN) {
        ws.send(JSON.stringify({
          type: 'UPDATE_TASKS',
          payload: localTasks
        }));
      }
    }

    // --- Render Logic ---
    function renderBoard() {
      const columns = {
        todo: document.getElementById('todo'),
        'in-progress': document.getElementById('in-progress'),
        done: document.getElementById('done')
      };

      // Clear existing UI elements
      Object.keys(columns).forEach(key => columns[key].innerHTML = '');

      // Group cards and inject elements
      const counts = { todo: 0, 'in-progress': 0, done: 0 };

      localTasks.forEach(task => {
        counts[task.status]++;

        const card = document.createElement('div');
        card.id = task.id;
        card.draggable = true;
        card.ondragstart = drag;
        card.ondragend = dragEnd;
        card.className = 'bg-white p-4 rounded shadow hover:shadow-md cursor-grab active:cursor-grabbing border border-gray-200 transition flex justify-between items-start';
        card.innerHTML = `
          <span class="text-gray-800 font-medium">${escapeHTML(task.title)}</span>
          <button onclick="deleteTask('${task.id}')" class="text-red-400 hover:text-red-600 ml-2">
            <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"></path></svg>
          </button>
        `;

        columns[task.status].appendChild(card);
      });

      // Update counters
      document.getElementById('count-todo').innerText = counts.todo;
      document.getElementById('count-in-progress').innerText = counts['in-progress'];
      document.getElementById('count-done').innerText = counts.done;
    }

    // Utility to prevent XSS attacks when users type task names
    function escapeHTML(str) {
      return str.replace(/[&<>'"]/g, 
        tag => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', "'": '&#39;', '"': '&quot;' }[tag] || tag)
      );
    }

    // Start App
    connectWebSocket();
  </script>
</body>
</html>
