#### `backend/server.js`
```javascript
const express = require('express');
const http = require('http');
const { Server } = require('socket.io');
const cors = require('cors');

const app = express();
app.use(cors());

const server = http.createServer(app);
const io = new Server(server, {
  cors: {
    origin: "http://localhost:5173", // Default Vite development port
    methods: ["GET", "POST"]
  }
});

// In-memory global board state shared across all users
let boardState = {
  todo: [
    { id: '1', content: 'Draft design system specs' },
    { id: '2', content: 'Set up database clusters' }
  ],
  inProgress: [
    { id: '3', content: 'Build Socket.io microservice' }
  ],
  done: [
    { id: '4', content: 'Project kickoff presentation' }
  ]
};

io.on('connection', (socket) => {
  console.log(`User connected: ${socket.id}`);

  // Send current board state to the newly connected user
  socket.emit('init-board', boardState);

  // Listen for board modifications from a client
  socket.on('update-board', (updatedBoard) => {
    boardState = updatedBoard;
    // Broadcast changes to every other connected user
    socket.broadcast.emit('board-updated', boardState);
  });

  socket.on('disconnect', () => {
    console.log(`User disconnected: ${socket.id}`);
  });
});

const PORT = 3001;
server.listen(PORT, () => {
  console.log(`⚡ Real-time server running on http://localhost:${PORT}`);
});
```

