#### `frontend/src/App.jsx`
```jsx
import React, { useState, useEffect, useRef } from 'react';
import { io } from 'socket.io-client';

const SOCKET_SERVER_URL = 'http://localhost:3001';

const COLUMNS = {
  todo: { name: 'To Do', color: 'bg-slate-100 border-slate-300' },
  inProgress: { name: 'In Progress', color: 'bg-blue-50/50 border-blue-200' },
  done: { name: 'Done', color: 'bg-emerald-50/50 border-emerald-200' },
};

export default function App() {
  const [board, setBoard] = useState({ todo: [], inProgress: [], done: [] });
  const [newTaskText, setNewTaskText] = useState('');
  const [isConnected, setIsConnected] = useState(false);
  const socketRef = useRef(null);

  // Initialize Socket connection
  useEffect(() => {
    socketRef.current = io(SOCKET_SERVER_URL);

    socketRef.current.on('connect', () => setIsConnected(true));
    socketRef.current.on('disconnect', () => setIsConnected(false));

    // Handle initial board state load
    socketRef.current.on('init-board', (initialBoard) => {
      setBoard(initialBoard);
    });

    // Handle updates from other collaborative clients
    socketRef.current.on('board-updated', (updatedBoard) => {
      setBoard(updatedBoard);
    });

    return () => {
      socketRef.current.disconnect();
    };
  }, []);

  // Helper to update local state and emit to socket server
  const updateBoardState = (newBoard) => {
    setBoard(newBoard);
    socketRef.current.emit('update-board', newBoard);
  };

  // Create new task
  const handleAddTask = (e) => {
    e.preventDefault();
    if (!newTaskText.trim()) return;

    const newTask = {
      id: Date.now().toString(),
      content: newTaskText.trim(),
    };

    const updatedBoard = {
      ...board,
      todo: [...board.todo, newTask],
    };

    updateBoardState(updatedBoard);
    setNewTaskText('');
  };

  // Delete a task
  const handleDeleteTask = (columnId, taskId) => {
    const updatedBoard = {
      ...board,
      [columnId]: board[columnId].filter(task => task.id !== taskId)
    };
    updateBoardState(updatedBoard);
  }

  // --- HTML5 Drag and Drop handlers ---
  const handleDragStart = (e, taskId, sourceCol) => {
    e.dataTransfer.setData('text/plain', JSON.stringify({ taskId, sourceCol }));
  };

  const handleDragOver = (e) => {
    e.preventDefault(); // Required to allow dropping
  };

  const handleDrop = (e, targetCol) => {
    e.preventDefault();
    const data = e.dataTransfer.getData('text/plain');
    if (!data) return;

    const { taskId, sourceCol } = JSON.parse(data);

    if (sourceCol === targetCol) return;

    // Find the task inside source list
    const movedTask = board[sourceCol].find((task) => task.id === taskId);
    if (!movedTask) return;

    const updatedBoard = {
      ...board,
      // Remove from source list
      [sourceCol]: board[sourceCol].filter((task) => task.id !== taskId),
      // Append to target list
      [targetCol]: [...board[targetCol], movedTask],
    };

    updateBoardState(updatedBoard);
  };

  return (
    <div className="min-h-screen bg-slate-50 text-slate-800 font-sans">
      {/* Header */}
      <header className="bg-white border-b border-slate-200 px-6 py-4 flex items-center justify-between">
        <h1 className="text-xl font-bold text-slate-900 flex items-center gap-2">
          🚀 Real-time Team Board
        </h1>
        <div className="flex items-center gap-2">
          <span className={`h-2.5 w-2.5 rounded-full ${isConnected ? 'bg-emerald-500 animate-pulse' : 'bg-rose-500'}`} />
          <span className="text-sm text-slate-500 font-medium">
            {isConnected ? 'Collaborating Live' : 'Connecting...'}
          </span>
        </div>
      </header>

      {/* Main Container */}
      <main className="max-w-7xl mx-auto p-6">

        {/* Add Task Input */}
        <form onSubmit={handleAddTask} className="mb-8 flex gap-2 max-w-md">
          <input
            type="text"
            placeholder="Add a new task to To Do..."
            value={newTaskText}
            onChange={(e) => setNewTaskText(e.target.value)}
            className="flex-1 px-4 py-2 bg-white border border-slate-300 rounded-lg shadow-sm focus:outline-none focus:ring-2 focus:ring-blue-500 text-sm"
          />
          <button
            type="submit"
            className="px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white font-medium text-sm rounded-lg shadow transition-colors"
          >
            Add Task
          </button>
        </form>

        {/* Kanban Board Grid */}
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          {Object.entries(COLUMNS).map(([colId, { name, color }]) => (
            <div
              key={colId}
              onDragOver={handleDragOver}
              onDrop={(e) => handleDrop(e, colId)}
              className={`rounded-xl border p-4 min-h-[450px] transition-all flex flex-col ${color}`}
            >
              <div className="flex justify-between items-center mb-4">
                <h2 className="font-semibold text-slate-700">{name}</h2>
                <span className="bg-slate-200 text-slate-600 text-xs px-2.5 py-0.5 rounded-full font-bold">
                  {board[colId]?.length || 0}
                </span>
              </div>

              {/* Task Items container */}
              <div className="flex-1 space-y-3">
                {board[colId]?.map((task) => (
                  <div
                    key={task.id}
                    draggable
                    onDragStart={(e) => handleDragStart(e, task.id, colId)}
                    className="p-4 bg-white border border-slate-200 rounded-lg shadow-sm cursor-grab active:cursor-grabbing hover:border-slate-300 transition group relative"
                  >
                    <p className="text-sm text-slate-600 font-medium pr-6">{task.content}</p>
                    <button 
                      onClick={() => handleDeleteTask(colId, task.id)}
                      className="absolute right-3 top-3.5 text-slate-300 hover:text-rose-500 opacity-0 group-hover:opacity-100 transition-opacity"
                    >
                      ✕
                    </button>
                  </div>
                ))}

                {board[colId]?.length === 0 && (
                  <div className="border border-dashed border-slate-300 rounded-lg h-24 flex items-center justify-center text-xs text-slate-400">
                    Drop tasks here
                  </div>
                )}
              </div>
            </div>
          ))}
        </div>
      </main>
    </div>
  );
}
```

