```javascript
const express = require('express');
const http = require('http');
const { Server } = require('socket.io');
const cors = require('cors');

const app = express();
app.use(cors());

const server = http.createServer(app);
const io = new Server(server, {
  cors: {
    origin: "http://localhost:5173", // Default Vite development port
    methods: ["GET", "POST"]
  }
});

// In-memory database for demo purposes
let tasks = [
  { id: '1', title: 'Design Database Schema', description: 'Create PostgreSQL tables', columnId: 'todo' },
  { id: '2', title: 'Set up WebSockets', description: 'Integrate Socket.io with Express', columnId: 'in-progress' },
  { id: '3', title: 'Project Initialization', description: 'Scaffold React application', columnId: 'done' },
];

io.on('connection', (socket) => {
  console.log(`User connected: ${socket.id}`);

  // Send initial state of tasks to newly connected client
  socket.emit('initial-tasks', tasks);

  // Handle task movement
  socket.on('move-task', ({ taskId, targetColumn }) => {
    tasks = tasks.map(task => 
      task.id === taskId ? { ...task, columnId: targetColumn } : task
    );
    // Broadcast updated tasks to ALL clients (including sender to sync state)
    io.emit('tasks-updated', tasks);
  });

  // Handle adding a new task
  socket.on('add-task', (newTask) => {
    tasks.push(newTask);
    io.emit('tasks-updated', tasks);
  });

  socket.on('disconnect', () => {
    console.log(`User disconnected: ${socket.id}`);
  });
});

const PORT = 3001;
server.listen(PORT, () => {
  console.log(`WebSocket server running on http://localhost:${PORT}`);
});
```

