```javascript
import { useEffect, useState } from 'react';
import { io } from 'socket.io-client';

const socket = io('http://localhost:3001');

const COLUMNS = [
  { id: 'todo', title: 'To Do', color: 'bg-rose-500/10 text-rose-400 border-rose-500/20' },
  { id: 'in-progress', title: 'In Progress', color: 'bg-amber-500/10 text-amber-400 border-amber-500/20' },
  { id: 'done', title: 'Done', color: 'bg-emerald-500/10 text-emerald-400 border-emerald-500/20' }
];

export default function App() {
  const [tasks, setTasks] = useState([]);
  const [newTaskTitle, setNewTaskTitle] = useState('');
  const [activeDragId, setActiveDragId] = useState(null);

  useEffect(() => {
    // Listen for initial data payload
    socket.on('initial-tasks', (initialTasks) => {
      setTasks(initialTasks);
    });

    // Listen for real-time changes made by self or collaborators
    socket.on('tasks-updated', (updatedTasks) => {
      setTasks(updatedTasks);
    });

    return () => {
      socket.off('initial-tasks');
      socket.off('tasks-updated');
    };
  }, []);

  // HTML5 Drag Event Handlers
  const handleDragStart = (e, taskId) => {
    e.dataTransfer.setData('text/plain', taskId);
    setActiveDragId(taskId);
  };

  const handleDragEnd = () => {
    setActiveDragId(null);
  };

  const handleDragOver = (e) => {
    e.preventDefault(); // Required to allow dropping
  };

  const handleDrop = (e, targetColumnId) => {
    e.preventDefault();
    const taskId = e.dataTransfer.getData('text/plain');

    // Optimistic UI Update locally
    setTasks(prev => prev.map(t => t.id === taskId ? { ...t, columnId: targetColumnId } : t));

    // Notify backend and collaborators
    socket.emit('move-task', { taskId, targetColumn: targetColumnId });
  };

  const handleAddTask = (e) => {
    e.preventDefault();
    if (!newTaskTitle.trim()) return;

    const newTask = {
      id: Date.now().toString(),
      title: newTaskTitle,
      description: 'Click to edit description...',
      columnId: 'todo'
    };

    socket.emit('add-task', newTask);
    setNewTaskTitle('');
  };

  return (
    <div className="min-h-screen bg-slate-950 p-8">
      {/* Header Area */}
      <header className="max-w-7xl mx-auto mb-10 flex flex-col md:flex-row items-center justify-between gap-4">
        <div>
          <h1 className="text-3xl font-bold text-white tracking-tight">Project Board</h1>
          <p className="text-sm text-slate-400 mt-1">Real-time collaborative planning space</p>
        </div>

        {/* Form to Add Tasks */}
        <form onSubmit={handleAddTask} className="flex gap-2 w-full md:w-auto">
          <input
            type="text"
            placeholder="Add a new task..."
            value={newTaskTitle}
            onChange={(e) => setNewTaskTitle(e.target.value)}
            className="px-4 py-2 bg-slate-900 border border-slate-800 rounded-lg text-white focus:outline-none focus:border-indigo-500 w-full md:w-80 transition"
          />
          <button
            type="submit"
            className="px-4 py-2 bg-indigo-600 hover:bg-indigo-500 font-medium rounded-lg text-sm transition shrink-0"
          >
            Add Task
          </button>
        </form>
      </header>

      {/* Kanban Board Grid */}
      <main className="max-w-7xl mx-auto grid grid-cols-1 md:grid-cols-3 gap-6">
        {COLUMNS.map((column) => {
          const columnTasks = tasks.filter(task => task.columnId === column.id);

          return (
            <div
              key={column.id}
              onDragOver={handleDragOver}
              onDrop={(e) => handleDrop(e, column.id)}
              className={`rounded-2xl bg-slate-900/60 border border-slate-800 p-5 flex flex-col min-h-[500px] transition-all duration-200`}
            >
              {/* Column Title */}
              <div className="flex items-center justify-between mb-4 pb-2 border-b border-slate-800">
                <div className="flex items-center gap-2">
                  <span className={`px-2 py-0.5 text-xs font-semibold rounded-full ${column.color}`}>
                    {column.title}
                  </span>
                  <span className="text-sm text-slate-500 font-medium">{columnTasks.length}</span>
                </div>
              </div>

              {/* Task Cards Area */}
              <div className="flex-1 space-y-3">
                {columnTasks.map((task) => (
                  <div
                    key={task.id}
                    draggable
                    onDragStart={(e) => handleDragStart(e, task.id)}
                    onDragEnd={handleDragEnd}
                    className={`p-4 bg-slate-900 border border-slate-800 rounded-xl cursor-grab active:cursor-grabbing hover:border-slate-700 transition shadow-sm ${
                      activeDragId === task.id ? 'opacity-40 border-dashed border-indigo-500' : ''
                    }`}
                  >
                    <h3 className="font-semibold text-white text-sm">{task.title}</h3>
                    <p className="text-xs text-slate-400 mt-1">{task.description}</p>
                  </div>
                ))}

                {/* Dropzone Empty State Helper */}
                {columnTasks.length === 0 && (
                  <div className="h-full flex items-center justify-center border-2 border-dashed border-slate-800/80 rounded-xl py-12">
                    <span className="text-xs text-slate-500">Drop tasks here</span>
                  </div>
                )}
              </div>
            </div>
          );
        })}
      </main>
    </div>
  );
}
