### Part 1: The Backend (`server.js`)

Create a file named `server.js`. This server acts as the single source of truth. When a client moves or adds a task, the server updates its in-memory database and broadcasts the new state to all other connected clients instantly.

```javascript
const { WebSocketServer } = require('ws');

const wss = new WebSocketServer({ port: 8080 });

// In-memory application state
let boardState = {
    todo: [
        { id: 'task-1', text: 'Set up database schema' },
        { id: 'task-2', text: 'Design landing page' }
    ],
    doing: [
        { id: 'task-3', text: 'Implement WebSocket sync' }
    ],
    done: [
        { id: 'task-4', text: 'Write project proposal' }
    ]
};

console.log('WebSocket server started on ws://localhost:8080');

wss.on('connection', (ws) => {
    console.log('New client connected');

    // 1. Send the current state of the board immediately upon connection
    ws.send(JSON.stringify({ type: 'INIT', state: boardState }));

    // 2. Handle incoming updates from clients
    ws.on('message', (message) => {
        try {
            const action = JSON.parse(message);

            if (action.type === 'MOVE_TASK') {
                const { taskId, fromCol, toCol } = action.payload;

                // Find and extract the task from the source column
                const taskIndex = boardState[fromCol].findIndex(t => t.id === taskId);
                if (taskIndex !== -1) {
                    const [task] = boardState[fromCol].splice(taskIndex, 1);
                    // Push to target column
                    boardState[toCol].push(task);

                    // Broadcast updated state to ALL connected clients
                    broadcast({ type: 'UPDATE_BOARD', state: boardState });
                }
            } 

            else if (action.type === 'ADD_TASK') {
                const { columnId, text } = action.payload;
                const newTask = { id: `task-${Date.now()}`, text };
                boardState[columnId].push(newTask);

                broadcast({ type: 'UPDATE_BOARD', state: boardState });
            }
        } catch (err) {
            console.error('Error handling message:', err);
        }
    });

    ws.on('close', () => console.log('Client disconnected'));
});

// Helper function to broadcast data to all active clients
function broadcast(data) {
    wss.clients.forEach(client => {
        if (client.readyState === 1) { // 1 = OPEN
            client.send(JSON.stringify(data));
        }
    });
}
```

