    <script>
        // WebSocket Connection setup
        const socket = new WebSocket('ws://localhost:8080');
        const statusEl = document.getElementById('status');
        let localState = {};

        socket.onopen = () => {
            statusEl.textContent = "Connected";
            statusEl.classList.add('connected');
