        function dragLeave(e) {
            if (e.currentTarget.classList.contains('card-list')) {
                e.currentTarget.classList.remove('drag-over');
            }
        }

        function drop(e) {
            e.preventDefault();
            const targetList = e.currentTarget;
            targetList.classList.remove('drag-over');

            const taskId = e.dataTransfer.getData('text/plain');
            const fromCol = e.dataTransfer.getData('source-col');
            const toCol = targetList.id;

            // Prevent redundant operations
            if (fromCol === toCol) return;

            // Optimistic Local UI Update
            const taskIndex = localState[fromCol].findIndex(t => t.id === taskId);
            const [task] = localState[fromCol].splice(taskIndex, 1);
            localState[toCol].push(task);
            renderBoard();

            // 4. Send action to backend via WebSocket
            socket.send(JSON.stringify({
                type: 'MOVE_TASK',
                payload: { taskId, fromCol, toCol }
            }));
        }

        // Add Task Action Handler
        function addTask(event, columnId) {
            event.preventDefault();
            const input = event.target.querySelector('input');
            const text = input.value.trim();
            if (!text) return;

            // Send payload to backend
            socket.send(JSON.stringify({
                type: 'ADD_TASK',
                payload: { columnId, text }
            }));

            input.value = ''; // Reset input field
        }
