### 1. The Backend: `server.js`
This server serves the frontend, maintains the master list of tasks, and broadcasts real-time updates using WebSockets whenever a task is moved.

```javascript
const http = require('http');
const fs = require('fs');
const path = require('path');
const WebSocket = require('ws');

// 1. Initial State of our Board
let boardState = {
    tasks: [
        { id: "task-1", text: "Design Landing Page", column: "todo" },
        { id: "task-2", text: "Configure WebSockets", column: "progress" },
        { id: "task-3", text: "Write Documentation", column: "done" }
    ]
};

// 2. HTTP Server to serve our HTML file
const server = http.createServer((req, res) => {
    if (req.url === '/' || req.url === '/index.html') {
        fs.readFile(path.join(__dirname, 'index.html'), (err, data) => {
            if (err) {
                res.writeHead(500);
                return res.end('Error loading index.html');
            }
            res.writeHead(200, { 'Content-Type': 'text/html' });
            res.end(data);
        });
    } else {
        res.writeHead(404);
        res.end('Not Found');
    }
});

// 3. WebSocket Server for Real-Time Sync
const wss = new WebSocket.Server({ server });

function broadcast(message, senderWs) {
    wss.clients.forEach(client => {
        // Send to everyone (including sender to ensure sync state)
        if (client.readyState === WebSocket.OPEN) {
            client.send(JSON.stringify(message));
        }
    });
}

wss.on('connection', (ws) => {
    console.log('Client connected');

    // Immediately send the current board state to the newly connected user
    ws.send(JSON.stringify({ type: 'INIT', tasks: boardState.tasks }));

    ws.on('message', (message) => {
        const data = JSON.parse(message);

        if (data.type === 'MOVE_TASK') {
            // Find the task and update its column
            const task = boardState.tasks.find(t => t.id === data.taskId);
            if (task) {
                task.column = data.targetColumn;
                console.log(`Task ${task.id} moved to ${task.column}`);

                // Broadcast the updated tasks array to all clients
                broadcast({ type: 'UPDATE', tasks: boardState.tasks }, ws);
            }
        }
    });

    ws.on('close', () => console.log('Client disconnected'));
});

const PORT = 3000;
server.listen(PORT, () => {
    console.log(`Server running at http://localhost:${PORT}`);
});
```

