            });

            // Fired when the element is dropped
            column.addEventListener('drop', (e) => {
                e.preventDefault();
                column.classList.remove('drag-over');

                const taskId = e.dataTransfer.getData('text/plain');
                const targetColumn = column.id; // 'todo', 'progress', or 'done'

                // Optimistically update local UI state immediately for responsive feel
                const task = tasks.find(t => t.id === taskId);
                if (task && task.column !== targetColumn) {
                    task.column = targetColumn;
                    renderBoard();

                    // Notify server to broadcast change to everyone else
                    socket.send(JSON.stringify({
                        type: 'MOVE_TASK',
                        taskId: taskId,
                        targetColumn: targetColumn
                    }));
                }
            });
        });
