### 1. The Backend (`server.js`)
This Node.js server maintains the board state in memory and broadcasts task updates (adds and moves) to all connected browser clients instantly using WebSockets.

```javascript
const express = require('express');
const http = require('http');
const { Server } = require('socket.io');
const path = require('path');

const app = express();
const server = http.createServer(app);
const io = new Server(server);

// Serve static files from the public folder
app.use(express.static(path.join(__dirname, 'public')));

// In-memory data store representing our collaborative database
let boardState = {
  todo: [
    { id: '1', content: '🎯 Design landing page hero section' },
    { id: '2', content: '⚙️ Configure server routing' }
  ],
  inprogress: [
    { id: '3', content: '✨ Build draggable card system' }
  ],
  done: [
    { id: '4', content: '📝 Define technical architecture' }
  ]
};

io.on('connection', (socket) => {
  console.log(`User connected: ${socket.id}`);

  // Send the current board state to the newly connected user
  socket.emit('init', boardState);

  // Listen for cards being dragged and dropped
  socket.on('move-task', ({ taskId, fromCol, toCol }) => {
    let movedTask = null;

    // Find and remove the task from its source column
    boardState[fromCol] = boardState[fromCol].filter(task => {
      if (task.id === taskId) {
        movedTask = task;
        return false;
      }
      return true;
    });

    // Add the task to its destination column
    if (movedTask) {
      boardState[toCol].push(movedTask);

      // Broadcast the updated state to ALL connected clients
      io.emit('board-update', boardState);
    }
  });

  // Listen for newly created tasks
  socket.on('add-task', ({ content, column }) => {
    const newTask = { id: Date.now().toString(), content };
    boardState[column].push(newTask);

    // Broadcast the updated state to ALL connected clients
    io.emit('board-update', boardState);
  });

  socket.on('disconnect', () => {
    console.log(`User disconnected: ${socket.id}`);
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`🚀 Collaborative server running at http://localhost:${PORT}`);
});
```

