### Backend: `server.js`
This server hosts the static frontend files and manages a WebSocket server to broadcast state updates to all active users when cards are moved.

```javascript
const express = require('express');
const http = require('http');
const WebSocket = require('ws');
const path = require('path');

const app = express();
const server = http.createServer(app);
const wss = new WebSocket.Server({ server });

// Serve static UI files
app.use(express.static(path.join(__dirname, 'public')));

// In-memory data store representing the board state
let boardState = {
  tasks: [
    { id: '1', title: 'Research competitor features', column: 'todo' },
    { id: '2', title: 'Draft system architecture', column: 'todo' },
    { id: '3', title: 'Develop real-time WS connection', column: 'inprogress' },
    { id: '4', title: 'Configure production pipeline', column: 'done' }
  ]
};

wss.on('connection', (ws) => {
  // 1. Send the current state immediately to the newly connected user
  ws.send(JSON.stringify({ type: 'INITIAL_STATE', payload: boardState }));

  // 2. Listen for drag-and-drop actions from clients
  ws.on('message', (message) => {
    try {
      const action = JSON.parse(message);

      if (action.type === 'MOVE_TASK') {
        const { taskId, targetColumn } = action.payload;

        // Update local memory state
        boardState.tasks = boardState.tasks.map(task => 
          task.id === taskId ? { ...task, column: targetColumn } : task
        );

        // Broadcast the update to EVERY connected user
        const broadcastData = JSON.stringify({ type: 'STATE_UPDATE', payload: boardState });
        wss.clients.forEach(client => {
          if (client.readyState === WebSocket.OPEN) {
            client.send(broadcastData);
          }
        });
      }
    } catch (err) {
      console.error("Error processing message: ", err);
    }
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Application running at http://localhost:${PORT}`);
});
```

