            background-color: #dfe1e6;
        }
    </style>
</head>
<body>

    <h1>Collaborative Project Board</h1>

    <div class="board">
        <!-- Columns -->
        <div class="column" id="todo">
            <div class="column-header">To Do</div>
            <div class="task-list" id="todo-list"></div>
        </div>

        <div class="column" id="inprogress">
            <div class="column-header">In Progress</div>
            <div class="task-list" id="inprogress-list"></div>
        </div>

        <div class="column" id="done">
            <div class="column-header">Done</div>
            <div class="task-list" id="done-list"></div>
        </div>
    </div>

    <script>
        const protocol = window.location.protocol === 'https:' ? 'wss:' : 'ws:';
        const ws = new WebSocket(`${protocol}//${window.location.host}`);

        let tasks = [];

        // Connect to the WebSocket Server
        ws.onmessage = (event) => {
            const message = JSON.parse(event.data);
            if (message.type === 'INITIAL_STATE' || message.type === 'STATE_UPDATE') {
                tasks = message.payload.tasks;
                renderBoard();
            }
        };

        // Render tasks into their respective columns
        function renderBoard() {
            const lists = {
                todo: document.getElementById('todo-list'),
                inprogress: document.getElementById('inprogress-list'),
                done: document.getElementById('done-list')
            };

            // Clear columns
            Object.values(lists).forEach(list => list.innerHTML = '');

            // Populate columns
            tasks.forEach(task => {
                const card = document.createElement('div');
                card.className = 'card';
                card.id = `task-${task.id}`;
                card.draggable = true;
                card.innerText = task.title;

                // Drag Start
                card.addEventListener('dragstart', (e) => {
                    e.dataTransfer.setData('text/plain', task.id);
                    card.classList.add('dragging');
                });

                // Drag End
                card.addEventListener('dragend', () => {
                    card.classList.remove('dragging');
                });

                if (lists[task.column]) {
                    lists[task.column].appendChild(card);
                }
            });
        }

        // Configure Drag & Drop Drop-Zones
        const columns = document.querySelectorAll('.column');

        columns.forEach(column => {
            column.addEventListener('dragover', (e) => {
                e.preventDefault(); // Crucial: Allows dropping elements
                column.classList.add('drag-over');
            });

            column.addEventListener('dragleave', () => {
                column.classList.remove('drag-over');
            });

            column.addEventListener('drop', (e) => {
                e.preventDefault();
                column.classList.remove('drag-over');

                const taskId = e.dataTransfer.getData('text/plain');
                const targetColumn = column.id;

                if (taskId) {
                    // Send movement command to server
                    ws.send(JSON.stringify({
                        type: 'MOVE_TASK',
                        payload: { taskId, targetColumn }
                    }));
                }
            });
        });
    </script>
</body>
</html>
```

---

### How to Run the App

1. Install the dependencies:
   ```bash
   npm install
   ```
2. Start the server:
   ```bash
   npm start
   ```
3. Open your browser and navigate to `http://localhost:3000`.
4. To test **real-time collaboration**, open `http://localhost:3000` in two separate browser windows side-by-side. Drag a task card in one window; you will see it instantly move in the other window without reloading.

