To build a low-latency trading platform that can scale in the future, we need to design an architecture that minimizes latency jitter (caused by garbage collection, thread context switching, and memory allocation) while remaining modular.

Below is a production-grade skeleton of a low-latency matching engine written in **Rust** (our #2 recommended language, chosen here because its compiler guarantees the thread safety needed for massive future scaling without sacrificing C++ level performance).

### Key Low-Latency Techniques Used:
1. **Zero Heap Allocation on the Hot Path:** All orders and events are passed as value types (`Copy` trait). There are no `Box`, `Vec`, or `String` allocations during trade matching.
2. **Lock-Free Communication:** We use a lock-free Single-Producer Single-Consumer (SPSC) ring buffer channel to pass events from the network thread to the execution thread without mutex contention.
3. **Data Locality:** The order book uses flat, pre-allocated arrays (cache-friendly contiguous memory) rather than pointer-heavy tree structures to maximize CPU L1/L2 cache hits.
4. **Decoupled Architecture (Scalability):** The Risk Engine, Order Book, and Market Data Publisher are decoupled via Traits, allowing you to scale them out into separate microservices or physical servers in the future.

### Rust Implementation

To run this, you would add `crossbeam-channel` and `lockfree-queue` or similar to your `Cargo.toml`. For this self-contained example, we will use atomic variables to demonstrate a raw lock-free ring buffer interface.

```rust
use std::sync::atomic::{AtomicU64, Ordering};
use std::thread;
use std::time::Instant;

// ==========================================
// 1. CONSTANTS & PRIMITIVES (Pre-allocated)
// ==========================================
const MAX_BOOK_DEPTH: usize = 100;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Side {
    Buy,
    Sell,
}

#[derive(Debug, Clone, Copy)]
pub struct Order {
    pub order_id: u64,
    pub price: u64,     // Scaled integer (e.g., USD cents or micro-cents)
    pub qty: u32,
    pub side: Side,
}

#[derive(Debug, Clone, Copy)]
pub struct ExecutionReport {
    pub order_id: u64,
    pub fill_qty: u32,
    pub fill_price: u64,
    pub remaining_qty: u32,
    pub status: Status,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Status {
    Rejected,
    New,
    Filled,
    PartiallyFilled,
}

// ==========================================
// 2. MODULAR & SCALABLE INTERFACES (TRAITS)
// ==========================================
// This allows scaling the system later (e.g., swapping local risk checks for distributed ones)
pub trait RiskEngine {
    fn check_order(&self, order: &Order) -> bool;
}

pub trait MarketDataPublisher {
    fn publish_trade(&self, price: u64, qty: u32);
}

// Concrete Implementations (Inlined for performance)
pub struct PreTradeRisk {
    max_order_value: u64,
}

impl RiskEngine for PreTradeRisk {
    #[inline(always)]
    fn check_order(&self, order: &Order) -> bool {
        let order_value = order.price * (order.qty as u64);
        order_value <= self.max_order_value
    }
}

pub struct NullPublisher;
impl MarketDataPublisher for NullPublisher {
    #[inline(always)]
    fn publish_trade(&self, _price: u64, _qty: u32) {}
}

// ==========================================
// 3. LOW-LATENCY CACHE-FRIENDLY ORDER BOOK
// ==========================================
// Avoids dynamic trees (like Red-Black trees) which cause L1 cache misses.
// Uses sorted arrays for flat memory access. Suitable for HFT where depth is limited.
pub struct OrderBook {
    bids: [Order; MAX_BOOK_DEPTH],
    asks: [Order; MAX_BOOK_DEPTH],
    bid_count: usize,
    ask_count: usize,
}

impl OrderBook {
    pub fn new() -> Self {
        let empty_order = Order { order_id: 0, price: 0, qty: 0, side: Side::Buy };
        OrderBook {
            bids: [empty_order; MAX_BOOK_DEPTH],
            asks: [empty_order; MAX_BOOK_DEPTH],
            bid_count: 0,
            ask_count: 0,
        }
    }

    /// Matches or inserts an incoming order (Hot Path)
    #[inline(always)]
    pub fn match_order<P: MarketDataPublisher>(
        &mut self, 
        mut order: Order, 
        publisher: &P
    ) -> ExecutionReport {
        let mut report = ExecutionReport {
            order_id: order.order_id,
            fill_qty: 0,
            fill_price: 0,
            remaining_qty: order.qty,
            status: Status::New,
        };

        match order.side {
            Side::Buy => {
                // Match against best asks (Asks are sorted ascending)
                let mut i = 0;
                while i < self.ask_count && order.qty > 0 {
                    let ask = &mut self.asks[i];
                    if order.price >= ask.price {
                        let fill = std::cmp::min(order.qty, ask.qty);
                        order.qty -= fill;
                        ask.qty -= fill;

                        report.fill_qty += fill;
                        report.fill_price = ask.price;
                        publisher.publish_trade(ask.price, fill);

                        if ask.qty == 0 {
                            // Remove Ask (shift left)
                            self.asks.copy_within((i + 1)..self.ask_count, i);
                            self.ask_count -= 1;
                        } else {
                            i += 1;
                        }
                    } else {
                        break;
                    }
                }
                report.remaining_qty = order.qty;
                if order.qty > 0 {
                    self.insert_bid(order);
                }
            }
            Side::Sell => {
                // Match against best bids (Bids are sorted descending)
                let mut i = 0;
                while i < self.bid_count && order.qty > 0 {
                    let bid = &mut self.bids[i];
                    if order.price <= bid.price {
                        let fill = std::cmp::min(order.qty, bid.qty);
                        order.qty -= fill;
                        bid.qty -= fill;

                        report.fill_qty += fill;
                        report.fill_price = bid.price;
                        publisher.publish_trade(bid.price, fill);

                        if bid.qty == 0 {
                            self.bids.copy_within((i + 1)..self.bid_count, i);
                            self.bid_count -= 1;
                        } else {
                            i += 1;
                        }
                    } else {
                        break;
                    }
                }
                report.remaining_qty = order.qty;
                if order.qty > 0 {
                    self.insert_ask(order);
                }
            }
        }

        if report.fill_qty > 0 {
            report.status = if report.remaining_qty == 0 { Status::Filled } else { Status::PartiallyFilled };
        }
        report
    }

    #[inline(always)]
    fn insert_bid(&mut self, order: Order) {
        if self.bid_count >= MAX_BOOK_DEPTH { return; } // Drop/Reject on overflow in production
        // Insert and maintain descending order
        let mut idx = self.bid_count;
        while idx > 0 && self.bids[idx - 1].price < order.price {
            self.bids[idx] = self.bids[idx - 1];
            idx -= 1;
        }
        self.bids[idx] = order;
        self.bid_count += 1;
    }

    #[inline(always)]
    fn insert_ask(&mut self, order: Order) {
        if self.ask_count >= MAX_BOOK_DEPTH { return; }
        // Insert and maintain ascending order
        let mut idx = self.ask_count;
        while idx > 0 && self.asks[idx - 1].price > order.price {
            self.asks[idx] = self.asks[idx - 1];
            idx -= 1;
        }
        self.asks[idx] = order;
        self.ask_count += 1;
    }
}

// ==========================================
// 4. LOCK-FREE INTER-THREAD BUS (Disruptor style)
// ==========================================
// Low-latency engines shouldn't share state via Mutexes. 
// We use a simple lock-free ring-buffer queue for processing inbound orders.
const QUEUE_SIZE: usize = 1024;
struct RingBuffer {
    buffer: [Option<Order>; QUEUE_SIZE],
    write_idx: AtomicU64,
    read_idx: AtomicU64,
}

impl RingBuffer {
    fn new() -> Self {
        const INIT_VAL: Option<Order> = None;
        RingBuffer {
            buffer: [INIT_VAL; QUEUE_SIZE],
            write_idx: AtomicU64::new(0),
            read_idx: AtomicU64::new(0),
        }
    }

    #[inline(always)]
    fn try_push(&mut self, order: Order) -> bool {
        let write = self.write_idx.load(Ordering::Relaxed);
        let read = self.read_idx.load(Ordering::Acquire);
        if write - read >= QUEUE_SIZE as u64 {
            return false; // Queue full (backpressure)
        }
        let index = (write % QUEUE_SIZE as u64) as usize;
        self.buffer[index] = Some(order);
        self.write_idx.store(write + 1, Ordering::Release);
        true
    }

    #[inline(always)]
    fn try_pop(&mut self) -> Option<Order> {
        let read = self.read_idx.load(Ordering::Relaxed);
        let write = self.write_idx.load(Ordering::Acquire);
        if read == write {
            return None; // Queue empty
        }
        let index = (read % QUEUE_SIZE as u64) as usize;
        let item = self.buffer[index].take();
        self.read_idx.store(read + 1, Ordering::Release);
        item
    }
}

// ==========================================
// 5. RUNTIME / EXECUTION THREADS
// ==========================================
fn main() {
    // 1. Initialize Components
    let mut book = OrderBook::new();
    let risk_engine = PreTradeRisk { max_order_value: 10_000_000 }; // $100k limit
    let publisher = NullPublisher;

    // Allocate ring buffer in shared memory
    static mut RING_BUFFER: RingBuffer = RingBuffer {
        buffer: [None; QUEUE_SIZE],
        write_idx: AtomicU64::new(0),
        read_idx: AtomicU64::new(0),
    };

    // 2. Start Execution Loop Thread (Pinned to Core 1 in production)
    let execution_thread = thread::spawn(move || {
        println!("[Engine] Execution Thread started.");
        loop {
            // Busy loop (polling) to avoid context switches / OS sleep latency
            unsafe {
                if let Some(order) = RING_BUFFER.try_pop() {
                    // Pre-Trade Risk Check (Inlined)
                    if risk_engine.check_order(&order) {
                        let start = Instant::now();

                        // Execute Order
                        let report = book.match_order(order, &publisher);

                        let duration = start.nanoseconds_since(); 
                        println!(
                            "[Engine] Processed Order ID: {} | Status: {:?} | Remaining Qty: {} | Latency: {}ns",
                            report.order_id, report.status, report.remaining_qty, duration
                        );
                    } else {
                        println!("[Engine] Order {} Rejected by Risk Engine", order.order_id);
                    }
                }
            }
            // In a real system, you would add a thread spin-loop hint here
            // std::hint::spin_loop();
        }
    });

    // 3. Network/Ingestion Thread Sim (Generates Orders)
    thread::sleep(std::time::Duration::from_millis(500)); // wait for engine setup

    let orders = vec![
        Order { order_id: 1, price: 100, qty: 10, side: Side::Sell }, // Sell 10 @ $100
        Order { order_id: 2, price: 101, qty: 5, side: Side::Buy },   // Buy 5 @ $101 (Matches with Order 1)
        Order { order_id: 3, price: 99, qty: 200, side: Side::Buy },  // Fails Risk Check (Too expensive)
    ];

    println!("[Gateway] Ingesting orders...");
    for order in orders {
        unsafe {
            while !RING_BUFFER.try_push(order) {
                // busy wait if queue is full
            }
        }
    }

    execution_thread.join().unwrap();
}

