// Memory-friendly, cache-aligned Order Book
#[repr(align(64))]
pub struct OrderBook {
    pub symbol: Symbol,
    pub bids: [(Price, Quantity); MAX_BOOK_DEPTH],
    pub asks: [(Price, Quantity); MAX_BOOK_DEPTH],
    pub bid_count: usize,
    pub ask_count: usize,
}

impl OrderBook {
    pub fn new(symbol: Symbol) -> Self {
        Self {
            symbol,
            bids: [(0, 0); MAX_BOOK_DEPTH],
            asks: [(0, 0); MAX_BOOK_DEPTH],
            bid_count: 0,
            ask_count: 0,
        }
    }

    // Zero-allocation, ultra-fast price update
    #[inline(always)]
    pub fn update(&mut self, price: Price, qty: Quantity, side: Side) {
        let (levels, count) = match side {
            Side::Buy => (&mut self.bids, &mut self.bid_count),
            Side::Sell => (&mut self.asks, &mut self.ask_count),
        };

        // Linear scan: highly efficient for small depths due to CPU L1 Cache pre-fetching
        for i in 0..*count {
            if levels[i].0 == price {
                if qty == 0 {
                    // Remove level
                    for j in i..(*count - 1) {
                        levels[j] = levels[j + 1];
                    }
                    *count -= 1;
                } else {
                    levels[i].1 = qty;
                }
                return;
            }
        }

        // Add new level if space permits
        if *count < MAX_BOOK_DEPTH && qty > 0 {
            levels[*count] = (price, qty);
            *count += 1;
            // Sort levels (bids descending, asks ascending)
            match side {
                Side::Buy => levels[0..*count].sort_unstable_by(|a, b| b.0.cmp(&a.0)),
                Side::Sell => levels[0..*count].sort_unstable_by(|a, b| a.0.cmp(&b.0)),
            }
        }
    }
}

