#include <iostream>
#include <atomic>
#include <thread>
#include <vector>
#include <array>
#include <chrono>
#include <optional>
#include <new>
#include <cassert>

// Platform-specific header for CPU pinning (Linux)
#ifdef __linux__
#include <pthread.h>
#include <sched.h>
#endif

// --- CONFIGURATION & CONSTANTS ---
constexpr size_t CACHE_LINE_SIZE = 64;
constexpr size_t RING_BUFFER_SIZE = 1024 * 16; // Must be a power of 2
constexpr size_t MAX_ORDERS_PER_BOOK = 10000;

// Prevent false sharing by aligning structures to CPU cache lines
#ifdef __cpp_lib_hardware_interference_size
using std::hardware_destructive_interference_size;
#else
constexpr size_t hardware_destructive_interference_size = CACHE_LINE_SIZE;
#endif

// --- DATA STRUCTURES (HOT PATH) ---

enum class Side : uint8_t {
    BUY = 0,
    SELL = 1
};

enum class OrderType : uint8_t {
    LIMIT = 0,
    MARKET = 1
};

// Fixed-size, flat structure. No dynamic strings or pointers.
struct alignas(32) Order {
    uint64_t order_id;
    uint32_t price;     // Scaled integer (e.g., cents or micro-cents) to avoid float imprecision
    uint32_t quantity;
    uint32_t symbol_id; // Numeric ID instead of string "AAPL" to save space/bytes
    Side side;
    OrderType type;
};

struct ExecutionReport {
    uint64_t order_id;
    uint32_t match_price;
    uint32_t filled_quantity;
    bool fully_filled;
};

// --- LOCK-FREE SPSC RING BUFFER (Zero Garbage, Low Latency) ---
// Used to pass orders from the network thread to the matching engine thread.
template <typename T, size_t Capacity>
class LockFreeSPSCQueue {
    static_assert((Capacity & (Capacity - 1)) == 0, "Capacity must be a power of 2");

public:
    LockFreeSPSCQueue() : head_(0), tail_(0) {}

    // Writer Thread (Network Ingestion)
    bool enqueue(const T& item) noexcept {
        const size_t current_tail = tail_.load(std::memory_order_relaxed);
        const size_t current_head = head_.load(std::memory_order_acquire);

        if ((current_tail - current_head) == Capacity) {
            return false; // Queue is full
        }

        buffer_[current_tail & (Capacity - 1)] = item;
        tail_.store(current_tail + 1, std::memory_order_release);
        return true;
    }

    // Reader Thread (Matching Engine)
    bool dequeue(T& item) noexcept {
        const size_t current_head = head_.load(std::memory_order_relaxed);
        const size_t current_tail = tail_.load(std::memory_order_acquire);

        if (current_head == current_tail) {
            return false; // Queue is empty
        }

        item = buffer_[current_head & (Capacity - 1)];
        head_.store(current_head + 1, std::memory_order_release);
        return true;
    }

private:
    alignas(hardware_destructive_interference_size) std::atomic<size_t> head_;
    alignas(hardware_destructive_interference_size) std::atomic<size_t> tail_;
    std::array<T, Capacity> buffer_;
};

// --- ZERO-ALLOCATION MATCHING ENGINE ---
// Uses static memory allocation during startup. No heap allocations occur on the hot path.
class OrderBook {
public:
    OrderBook() : buy_count_(0), sell_count_(0) {}

    // Hot path: Matches incoming limit orders against the book.
    void process_limit_order(const Order& incoming, std::vector<ExecutionReport>& reports) noexcept {
        reports.clear();
        Order remaining_order = incoming;

        if (incoming.side == Side::BUY) {
            // Match against resting SELL orders (sorted lowest price first)
            for (size_t i = 0; i < sell_count_ && remaining_order.quantity > 0; ++i) {
                Order& resting = sell_book_[i];
                if (remaining_order.price >= resting.price) {
                    uint32_t match_qty = std::min(remaining_order.quantity, resting.quantity);

                    remaining_order.quantity -= match_qty;
                    resting.quantity -= match_qty;

                    reports.push_back({
                        incoming.order_id, 
                        resting.price, 
                        match_qty, 
                        remaining_order.quantity == 0
                    });

                    // If resting order is fully filled, remove it
                    if (resting.quantity == 0) {
                        remove_resting_order(Side::SELL, i);
                        --i; // Adjust index after removal
                    }
                }
            }

            // If quantity remains, rest it in the BUY book
            if (remaining_order.quantity > 0 && buy_count_ < MAX_ORDERS_PER_BOOK) {
                insert_sorted(buy_book_, buy_count_, remaining_order, std::greater<uint32_t>());
            }
        } 
        else { // Side::SELL
            // Match against resting BUY orders (sorted highest price first)
            for (size_t i = 0; i < buy_count_ && remaining_order.quantity > 0; ++i) {
                Order& resting = buy_book_[i];
                if (remaining_order.price <= resting.price) {
                    uint32_t match_qty = std::min(remaining_order.quantity, resting.quantity);

                    remaining_order.quantity -= match_qty;
                    resting.quantity -= match_qty;

                    reports.push_back({
                        incoming.order_id, 
                        resting.price, 
                        match_qty, 
                        remaining_order.quantity == 0
                    });

                    if (resting.quantity == 0) {
                        remove_resting_order(Side::BUY, i);
                        --i;
                    }
                }
            }

            if (remaining_order.quantity > 0 && sell_count_ < MAX_ORDERS_PER_BOOK) {
                insert_sorted(sell_book_, sell_count_, remaining_order, std::less<uint32_t>());
            }
        }
    }

private:
    // Insert order sorted by price (simulating priority queue on pre-allocated array)
    template <typename Compare>
    void insert_sorted(std::array<Order, MAX_ORDERS_PER_BOOK>& book, size_t& count, const Order& order, Compare comp) noexcept {
        size_t idx = count;
        while (idx > 0 && comp(order.price, book[idx - 1].price)) {
            book[idx] = book[idx - 1];
            --idx;
        }
        book[idx] = order;
        ++count;
    }

    void remove_resting_order(Side side, size_t index) noexcept {
        if (side == Side::BUY) {
            for (size_t i = index; i < buy_count_ - 1; ++i) {
                buy_book_[i] = buy_book_[i + 1];
            }
            --buy_count_;
        } else {
            for (size_t i = index; i < sell_count_ - 1; ++i) {
                sell_book_[i] = sell_book_[i + 1];
            }
            --sell_count_;
        }
    }

    // Pre-allocated flat buffers containing resting orders
    alignas(64) std::array<Order, MAX_ORDERS_PER_BOOK> buy_book_;
    alignas(64) std::array<Order, MAX_ORDERS_PER_BOOK> sell_book_;
    size_t buy_count_;
    size_t sell_count_;
};

// --- SYSTEM UTILITIES ---
void pin_thread_to_cpu(int core_id) {
#ifdef __linux__
    cpu_set_t cpuset;
    CPU_ZERO(&cpuset);
    CPU_SET(core_id, &cpuset);
    pthread_t current_thread = pthread_self();
    if (pthread_setaffinity_np(current_thread, sizeof(cpu_set_t), &cpuset) != 0) {
        std::cerr << "Error: Failed to pin thread to core " << core_id << "\n";
    } else {
        std::cout << "Thread successfully pinned to core " << core_id << "\n";
    }
#else
    std::cout << "CPU Pinning not supported on this operating system. Running normally.\n";
#endif
}

// --- MAIN PIPELINE ---
int main() {
    std::cout << "Starting Low-Latency Scalable Trading Engine...\n";

    // Inter-thread queue for raw ingestion
    auto order_queue = std::make_unique<LockFreeSPSCQueue<Order, RING_BUFFER_SIZE>>();
    std::atomic<bool> run_flag{true};

    // 1. MATCHING ENGINE THREAD (Consumes orders)
    std::thread matching_thread([&order_queue, &run_flag]() {
        // Pin to Core 1 (keep away from Core 0 which handles OS interrupts)
        pin_thread_to_cpu(1);

        OrderBook matching_engine;
        std::vector<ExecutionReport> reports;
        reports.reserve(16); // Pre-allocate report buffer vector

        Order incoming_order;
        while (run_flag.load(std::memory_order_relaxed)) {
            // Busy loop: spin-wait for incoming events (low-latency design)
            if (order_queue->dequeue(incoming_order)) {
                auto start_time = std::chrono::high_resolution_clock::now();

                matching_engine.process_limit_order(incoming_order, reports);

                auto end_time = std::chrono::high_resolution_clock::now();
                auto latency_ns = std::chrono::duration_cast<std::chrono::nanoseconds>(end_time - start_time).count();

                // If trades happened, execute matching reports
                for (const auto& report : reports) {
