                              << " (Qty: " << report.filled_quantity << ") | Latency: " 
                              << latency_ns << " ns\n";
                }
            }
        }
    });

    // 2. INGESTION THREAD (Simulates Network I/O / Inbound gateway)
    std::thread ingestion_thread([&order_queue, &run_flag]() {
        // Pin to Core 2
        pin_thread_to_cpu(2);

