// --- 2. LOCK-FREE SPSC QUEUE (For thread communication) ---
template <typename T, size_t Capacity>
class LockFreeSPSCQueue {
    static_assert((Capacity & (Capacity - 1)) == 0, "Capacity must be a power of 2");
public:
    // Producer Thread Writes Here
    bool push(const T& item) {
        const size_t write_idx = write_index_.load(std::memory_order_relaxed);
        const size_t read_idx = read_index_cached_;

        if (write_idx - read_idx == Capacity) {
            // Queue might be full, check atomic read index
            read_index_cached_ = read_index_.load(std::memory_order_acquire);
            if (write_idx - read_index_cached_ == Capacity) {
                return false; // Queue is genuinely full
            }
        }
        ring_[write_idx & (Capacity - 1)] = item;
        write_index_.store(write_idx + 1, std::memory_order_release);
        return true;
    }

    // Consumer Thread Reads Here
    bool pop(T& item) {
        const size_t read_idx = read_index_.load(std::memory_order_relaxed);
        const size_t write_idx = write_index_cached_;

        if (read_idx == write_idx) {
            // Queue might be empty, check atomic write index
            write_index_cached_ = write_index_.load(std::memory_order_acquire);
            if (read_idx == write_index_cached_) {
                return false; // Queue is genuinely empty
            }
        }
        item = ring_[read_idx & (Capacity - 1)];
        read_index_.store(read_idx + 1, std::memory_order_release);
        return true;
    }

private:
    std::array<T, Capacity> ring_;

    // Align indexes to avoid false sharing (cache-line bouncing)
    alignas(std::hardware_destructive_interference_size) std::atomic<size_t> write_index_{0};
    alignas(std::hardware_destructive_interference_size) size_t write_index_cached_{0};
    alignas(std::hardware_destructive_interference_size) std::atomic<size_t> read_index_{0};
    alignas(std::hardware_destructive_interference_size) size_t read_index_cached_{0};
};

// --- 3. SCALABILITY: Abstract interfaces for future distribution ---
