// --- 4. THE MATCHING ENGINE (Runs on a dedicated pinned CPU core) ---
class MatchingEngine {
public:
    explicit MatchingEngine(std::shared_ptr<MarketDataPublisher> publisher)
        : publisher_(std::move(publisher)) {
        // Pre-allocate space for orders to avoid runtime allocations
        bids_.reserve(10000);
        asks_.reserve(10000);
    }

    void process_order(const Order& incoming) {
        if (incoming.side == Side::Buy) {
            match_buy(incoming);
        } else {
            match_sell(incoming);
        }
    }

private:
    void match_buy(Order buy_order) {
        // Try matching against asks (cheapest sell orders first)
        for (auto it = asks_.begin(); it != asks_.end() && buy_order.qty > 0;) {
            if (buy_order.price >= it->price) {
                uint32_t fill_qty = std::min(buy_order.qty, it->qty);
                buy_order.qty -= fill_qty;
                it->qty -= fill_qty;

                publisher_->publish_trade(Trade{it->order_id, buy_order.order_id, it->price, fill_qty});

                if (it->qty == 0) {
                    it = asks_.erase(it); // Erasure from pre-allocated vector is fast for small vectors
                } else {
                    ++it;
                }
            } else {
                break; // No matching asks
            }
        }
        if (buy_order.qty > 0) {
            bids_.push_back(buy_order); // In real system, keep sorted (e.g., using binary insertion)
        }
    }

    void match_sell(Order sell_order) {
        for (auto it = bids_.begin(); it != bids_.end() && sell_order.qty > 0;) {
            if (sell_order.price <= it->price) {
                uint32_t fill_qty = std::min(sell_order.qty, it->qty);
                sell_order.qty -= fill_qty;
                it->qty -= fill_qty;

                publisher_->publish_trade(Trade{it->order_id, sell_order.order_id, it->price, fill_qty});

                if (it->qty == 0) {
                    it = bids_.erase(it);
                } else {
                    ++it;
                }
            } else {
                break;
            }
        }
        if (sell_order.qty > 0) {
            asks_.push_back(sell_order);
        }
    }

    std::vector<Order> bids_;
    std::vector<Order> asks_;
    std::shared_ptr<MarketDataPublisher> publisher_;
};

