// --- LOCK-FREE RING BUFFER (Single-Producer, Single-Consumer) ---
// Uses cache line alignment to prevent false sharing between reader and writer threads.
template <typename T, size_t Capacity>
class LockFreeQueue {
    static_assert((Capacity & (Capacity - 1)) == 0, "Capacity must be a power of 2");

private:
    alignas(CACHE_LINE_SIZE) std::array<T, Capacity> ring_buffer_;

    // Positioned on separate cache lines to avoid CPU cache bouncing
    alignas(CACHE_LINE_SIZE) std::atomic<size_t> write_idx_{0};
    alignas(CACHE_LINE_SIZE) std::atomic<size_t> read_idx_{0};

public:
    // Pushes an item. Returns false if the queue is full. (Non-blocking)
    bool push(const T& item) noexcept {
        const auto current_write = write_idx_.load(std::memory_order_relaxed);
        const auto current_read = read_idx_.load(std::memory_order_acquire);

        if ((current_write - current_read) == Capacity) {
            return false; // Queue full
        }

        ring_buffer_[current_write & (Capacity - 1)] = item;
        write_idx_.store(current_write + 1, std::memory_order_release);
        return true;
    }

    // Pops an item. Returns false if the queue is empty. (Non-blocking)
    bool pop(T& item) noexcept {
        const auto current_read = read_idx_.load(std::memory_order_relaxed);
        const auto current_write = write_idx_.load(std::memory_order_acquire);

        if (current_read == current_write) {
            return false; // Queue empty
        }

        item = ring_buffer_[current_read & (Capacity - 1)];
        read_idx_.store(current_read + 1, std::memory_order_release);
        return true;
    }
};

