// ============================================================================
constexpr size_t CACHE_LINE_SIZE = 64;
constexpr size_t RING_BUFFER_SIZE = 1024; // Must be power of 2 for fast masking

// Prevent false sharing by aligning variables to CPU cache lines
#define ALIGN_CACHE alignas(CACHE_LINE_SIZE)

// ============================================================================
// 2. DATA STRUCTURES (Zero-allocation on hot path)
// ============================================================================
enum class Side : char { BUY = 'B', SELL = 'S' };

struct MarketUpdate {
    uint32_t sequence;
    char symbol[8];
    double price;
    uint32_t quantity;
    Side side;
};

struct Order {
    uint64_t client_order_id;
    char symbol[8];
    double price;
    uint32_t quantity;
    Side side;
};

// ============================================================================
// 3. ULTRA-FAST LOCK-FREE SPSC RING BUFFER
// ============================================================================
// Lock-free queue optimized for Single-Producer Single-Consumer (SPSC) patterns.
template <typename T, size_t Capacity>
class LockFreeSPSC {
    static_assert((Capacity & (Capacity - 1)) == 0, "Capacity must be a power of 2");

private:
    std::array<T, Capacity> buffer_;

    // Align indices to prevent "False Sharing" between Producer and Consumer threads
    ALIGN_CACHE std::atomic<size_t> write_idx_{0};
    ALIGN_CACHE std::atomic<size_t> read_idx_{0};

public:
    // Push item into the queue (Non-blocking, fails if full)
    bool push(const T& item) noexcept {
        const size_t current_write = write_idx_.load(std::memory_order_relaxed);
        const size_t current_read = read_idx_.load(std::memory_order_acquire);

        if ((current_write - current_read) == Capacity) {
            return false; // Queue is full
        }

        buffer_[current_write & (Capacity - 1)] = item;
        write_idx_.store(current_write + 1, std::memory_order_release);
        return true;
    }

    // Pop item from the queue (Non-blocking, fails if empty)
    bool pop(T& item) noexcept {
        const size_t current_read = read_idx_.load(std::memory_order_relaxed);
        const size_t current_write = write_idx_.load(std::memory_order_acquire);

        if (current_read == current_write) {
            return false; // Queue is empty
        }

        item = buffer_[current_read & (Capacity - 1)];
        read_idx_.store(current_read + 1, std::memory_order_release);
        return true;
    }
};

// ============================================================================
// 4. LOW-LATENCY ORDER BOOK & RISK ENGINE (Core Engine)
// ============================================================================
class OrderBook {
private:
    double best_bid = 0.0;
    double best_ask = 0.0;

public:
    // Inlined for performance to avoid jump instructions
    inline void handle_update(const MarketUpdate& update) noexcept {
        if (update.side == Side::BUY) {
            best_bid = update.price;
        } else {
            best_ask = update.price;
        }
    }

    inline double get_best_bid() const noexcept { return best_bid; }
    inline double get_best_ask() const noexcept { return best_ask; }
};

class RiskEngine {
private:
    const uint32_t MAX_QUANTITY = 10000;

public:
    // Absolute minimum processing path. Inline is critical here.
    inline bool validate_order(const Order& order) noexcept {
        if (order.quantity > MAX_QUANTITY) [[unlikely]] {
            return false; // Pre-allocation risk limit hit
        }
        return true;
    }
};

// ============================================================================
// 5. THE RUNTIME ENVIRONMENT (Engine Threads)
// ============================================================================
class TradingPlatform {
private:
    LockFreeSPSC<MarketUpdate, RING_BUFFER_SIZE> market_data_queue_;
    LockFreeSPSC<Order, RING_BUFFER_SIZE> order_egress_queue_;

    std::atomic<bool> running_{true};

    OrderBook order_book_;
    RiskEngine risk_engine_;

    uint64_t next_order_id = 1000001;

public:
    void stop() { running_.store(false, std::memory_order_release); }

    // Thread 1: Ingests raw market data and writes to the SPSC Queue
    void market_data_ingress_loop() {
        std::cout << "[Ingress Thread] Started..." << std::endl;

        // Simulating incoming market data tick
        uint32_t seq = 1;
        while (running_.load(std::memory_order_relaxed)) {
            MarketUpdate update{
                .sequence = seq++,
                .symbol = "AAPL",
                .price = 150.0 + (seq % 10) * 0.01,
                .quantity = 100,
                .side = (seq % 2 == 0) ? Side::BUY : Side::SELL
            };

            // Spin-wait if the queue is full (Backpressure handling)
            while (!market_data_queue_.push(update)) {
                std::this_thread::yield(); 
            }

            // Artificial delay to simulate real-world market spacing
            std::this_thread::sleep_for(std::chrono::microseconds(100));
        }
    }

    // Thread 2: THE HOT PATH (Single-Threaded Execution Engine)
    void core_execution_loop() {
        std::cout << "[Core Engine] Started on dedicated processing path..." << std::endl;
        MarketUpdate update;

        while (running_.load(std::memory_order_relaxed)) {
            // Busy-wait (spinning) for lowest possible latency
            if (market_data_queue_.pop(update)) {

                // 1. Update Order Book
                order_book_.handle_update(update);

                // 2. Simple Strategy: If ask falls below 150.05, trigger a BUY
                if (update.side == Side::SELL && update.price <= 150.05) {
                    Order potential_order{
                        .client_order_id = next_order_id++,
                        .symbol = "AAPL",
                        .price = update.price,
                        .quantity = 200,
                        .side = Side::BUY
                    };

                    // 3. Inline Risk Checks
                    if (risk_engine_.validate_order(potential_order)) {
                        // 4. Send to Egress Queue
                        while (!order_egress_queue_.push(potential_order)) {
                            std::this_thread::yield();
                        }
                    } else {
                        std::cout << "[Risk Engine] BLOCKED Order " << potential_order.client_order_id << std::endl;
                    }
                }
            }
        }
    }

    // Thread 3: Order Egress Gateway
    void order_egress_loop() {
        std::cout << "[Egress Thread] Started..." << std::endl;
        Order order;

        while (running_.load(std::memory_order_relaxed)) {
            if (order_egress_queue_.pop(order)) {
                // Here, you would invoke your TCP/FIX/Binary socket library.
                // We use standard stdout wrapper for simulation.
                std::cout << "[EXECUTION ENGINE] SENT ORDER -> ID: " << order.client_order_id 
                          << " | Side: " << (char)order.side 
                          << " | Qty: " << order.quantity 
                          << " | Price: " << order.price << std::endl;
            }
        }
    }
};

int main() {
    TradingPlatform platform;

    // Start execution threads
    std::jthread ingress_thread(&TradingPlatform::market_data_ingress_loop, &platform);
    std::jthread core_thread(&TradingPlatform::core_execution_loop, &platform);
    std::jthread egress_thread(&TradingPlatform::order_egress_loop, &platform);

    // Let the demo platform run for 2 seconds
    std::this_thread::sleep_for(std::chrono::seconds(2));

    std::cout << "Shutting down..." << std::endl;
    platform.stop();

    return 0;
}
