use std::collections::BTreeMap;
use std::sync::mpsc::{sync_channel, Receiver, SyncSender};
use std::thread;
use std::time::Instant;

// ============================================================================
// 1. Data Structures (Designed for Cache Locality & Zero Copy)
// ============================================================================

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Side {
    Buy,
    Sell,
}

#[derive(Debug, Clone, Copy)]
pub struct Order {
    pub order_id: u64,
    pub client_id: u32,
    pub price: u64, // Fixed-point integer (e.g., USD cents or USD * 10,000)
    pub qty: u32,
    pub side: Side,
}

#[derive(Debug, Clone, Copy)]
pub struct Trade {
    pub maker_order_id: u64,
    pub taker_order_id: u64,
    pub price: u64,
    pub qty: u32,
}

#[derive(Debug, Clone, Copy)]
pub enum ExecutionReport {
    Accepted { order_id: u64, client_id: u32 },
    Filled { trade: Trade },
    Cancelled { order_id: u64 },
}

// ============================================================================
// 2. Ultra-Low-Latency Order Book
// ============================================================================

pub struct OrderBook {
    // We use BTreeMap for ordered price levels. 
    // For HFT, this would be replaced with a flat array/sparse map to avoid pointer chasing.
    pub bids: BTreeMap<u64, Vec<Order>>, // Key: Price (Descending)
    pub asks: BTreeMap<u64, Vec<Order>>, // Key: Price (Ascending)
}

impl OrderBook {
    pub fn new() -> Self {
        Self {
            bids: BTreeMap::new(),
            asks: BTreeMap::new(),
        }
    }

    /// Match or insert an incoming order. 
    /// Returns matching trades via a pre-allocated vector to prevent heap allocation.
    pub fn limit(&mut self, order: Order, trades: &mut Vec<Trade>) {
        let mut remaining_qty = order.qty;

        match order.side {
            Side::Buy => {
                // Match against cheapest asks
                while remaining_qty > 0 {
                    if let Some(mut entry) = self.asks.first_entry() {
                        let ask_price = *entry.key();
                        if order.price >= ask_price {
                            let orders_at_level = entry.get_mut();
                            while !orders_at_level.is_empty() && remaining_qty > 0 {
                                let maker = &mut orders_at_level[0];
                                let match_qty = std::cmp::min(remaining_qty, maker.qty);

                                trades.push(Trade {
                                    maker_order_id: maker.order_id,
                                    taker_order_id: order.order_id,
                                    price: ask_price,
                                    qty: match_qty,
                                });

                                remaining_qty -= match_qty;
                                maker.qty -= match_qty;

                                if maker.qty == 0 {
                                    orders_at_level.remove(0);
                                }
                            }
                            if orders_at_level.is_empty() {
                                entry.remove();
                            }
                        } else {
                            break; // Ask price is too high
                        }
                    } else {
                        break; // No asks left
                    }
                }

                // If unfilled, add remaining to Bids
                if remaining_qty > 0 {
                    let mut resting_order = order;
                    resting_order.qty = remaining_qty;
                    // Reverse the price key for Bids so bids.keys().next() gives the highest bid
                    self.bids.entry(u64::MAX - order.price)
                        .or_insert_with(|| Vec::with_capacity(16))
                        .push(resting_order);
                }
            }
            Side::Sell => {
                // Match against highest bids
                while remaining_qty > 0 {
                    if let Some(mut entry) = self.bids.first_entry() {
                        let bid_price = u64::MAX - *entry.key();
                        if order.price <= bid_price {
                            let orders_at_level = entry.get_mut();
                            while !orders_at_level.is_empty() && remaining_qty > 0 {
                                let maker = &mut orders_at_level[0];
                                let match_qty = std::cmp::min(remaining_qty, maker.qty);

                                trades.push(Trade {
                                    maker_order_id: maker.order_id,
                                    taker_order_id: order.order_id,
                                    price: bid_price,
                                    qty: match_qty,
                                });

                                remaining_qty -= match_qty;
                                maker.qty -= match_qty;

                                if maker.qty == 0 {
                                    orders_at_level.remove(0);
                                }
                            }
                            if orders_at_level.is_empty() {
                                entry.remove();
                            }
                        } else {
                            break; // Bid price is too low
                        }
                    } else {
                        break; // No bids left
                    }
                }

                // If unfilled, add remaining to Asks
                if remaining_qty > 0 {
                    let mut resting_order = order;
                    resting_order.qty = remaining_qty;
                    self.asks.entry(order.price)
                        .or_insert_with(|| Vec::with_capacity(16))
                        .push(resting_order);
                }
            }
        }
    }
}

// ============================================================================
// 3. Thread Orchestration & Hot Loop
// ============================================================================

pub struct MatchingEngine {
    order_rx: Receiver<Order>,
    report_tx: SyncSender<ExecutionReport>,
    book: OrderBook,
}

impl MatchingEngine {
    pub fn new(order_rx: Receiver<Order>, report_tx: SyncSender<ExecutionReport>) -> Self {
        Self {
            order_rx,
            report_tx,
            book: OrderBook::new(),
        }
    }

    /// The ultra-low-latency execution loop. Runs on its own dedicated thread.
    pub fn run(&mut self) {
        // Pre-allocate vector capacity to avoid heap allocations inside the loop
        let mut trade_buffer = Vec::with_capacity(32);

        while let Ok(order) = self.order_rx.recv() {
            // 1. Acknowledge Receipt immediately
            let _ = self.report_tx.send(ExecutionReport::Accepted {
                order_id: order.order_id,
                client_id: order.client_id,
            });

            // 2. Process matching logic
            trade_buffer.clear();
            self.book.limit(order, &mut trade_buffer);

            // 3. Emit Trade Execution Reports
            for trade in &trade_buffer {
                let _ = self.report_tx.send(ExecutionReport::Filled { trade: *trade });
            }
        }
    }
}

// ============================================================================
// 4. Performance & Scalability Test Harness
// ============================================================================

fn main() {
    // Bounded channels behave like ring buffers (prevents out-of-memory under spikes)
    let (order_tx, order_rx) = sync_channel::<Order>(1024 * 64);
    let (report_tx, report_rx) = sync_channel::<ExecutionReport>(1024 * 64);

    // Spawn Matching Engine Thread
    let engine_handle = thread::spawn(move || {
        // In a real HFT environment, we would pin this thread to a dedicated CPU core here:
        // core_affinity::set_for_current(core_affinity::CoreId { id: 1 });
        let mut engine = MatchingEngine::new(order_rx, report_tx);
        engine.run();
    });

    // Spawn a listener thread to handle downstream reports (e.g., saving to DB, TCP output)
    let reporter_handle = thread::spawn(move || {
        while let Ok(_report) = report_rx.recv() {
            // Keep this lightweight to prevent backpressure on the engine thread.
        }
    });

    // Generate some mock orders and measure throughput/latency
    println!("Warming up engine and generating 1,000,000 orders...");
    let num_orders = 1_000_000;
    let start_time = Instant::now();

    for i in 0..num_orders {
        let side = if i % 2 == 0 { Side::Buy } else { Side::Sell };
        // We match around price 10000 (e.g. $100.00)
        let price = 10000 + (i % 10); 

        let order = Order {
            order_id: i,
            client_id: 1,
            price,
            qty: 10,
            side,
        };

        // Send to Matching Engine
        if let Err(_) = order_tx.send(order) {
            break;
        }
    }

    // Drop the sender to signal termination
    drop(order_tx);

    let duration = start_time.elapsed();
    let nanoseconds_per_order = duration.as_nanos() / num_orders as u128;

    println!("--------------------------------------------------");
    println!("Benchmark Complete!");
    println!("Processed {} orders in {:?}", num_orders, duration);
    println!("Average latency: {} nanoseconds per order", nanoseconds_per_order);
    println!("Throughput: {:.2} million orders / sec", num_orders as f64 / duration.as_secs_f64() / 1_000_000.0);
    println!("--------------------------------------------------");

    // Wait for threads to clean up
    let _ = engine_handle.join();
    let _ = reporter_handle.join();
}
