use std::thread;
use std::time::Instant;
use crossbeam_channel::{bounded, Receiver, Sender};
use hashbrown::HashMap;

// =====================================================================
// 1. DATA STRUCTURES (Optimized for Cache and Latency)
// =====================================================================

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Side {
    Buy,
    Sell,
}

#[derive(Debug, Clone, Copy)]
pub struct Order {
    pub order_id: u64,
    pub price: u64, // Scaled integer (e.g., USD cents or micro-USD) to avoid float overhead
    pub qty: u32,
    pub side: Side,
}

#[derive(Debug, Clone, Copy)]
pub enum ExecutionReport {
    Accepted { order_id: u64 },
    Filled { maker_id: u64, taker_id: u64, price: u64, qty: u32 },
    Cancelled { order_id: u64 },
}

// Representing a single price level in the book
#[derive(Debug, Clone)]
struct LimitLevel {
    price: u64,
    orders: Vec<Order>, // In production, use a custom intrusive doubly-linked list or ring-buffer
}

// =====================================================================
// 2. THE MATCHING ENGINE (Single-Threaded, No Locks, Cache-Friendly)
// =====================================================================
pub struct MatchingEngine {
    symbol: String,
    bids: Vec<LimitLevel>, // Kept sorted: highest price first
    asks: Vec<LimitLevel>, // Kept sorted: lowest price first
    order_lookup: HashMap<u64, Side>, // Track order side for fast cancels
}

impl MatchingEngine {
    pub fn new(symbol: String, capacity: usize) -> Self {
        Self {
            symbol,
            bids: Vec::with_capacity(capacity),
            asks: Vec::with_capacity(capacity),
            order_lookup: HashMap::with_capacity(capacity * 2),
        }
    }

    /// Primary execution path. Zero heap allocations occur here in steady-state.
    #[inline(always)]
    pub fn limit_order(&mut self, incoming: Order, out_q: &Sender<ExecutionReport>) {
        let mut remaining_qty = incoming.qty;

        match incoming.side {
            Side::Buy => {
                // Match against Asks (Sells)
                while remaining_qty > 0 && !self.asks.is_empty() && self.asks[0].price <= incoming.price {
                    let level = &mut self.asks[0];
                    let mut order_idx = 0;

                    while order_idx < level.orders.len() && remaining_qty > 0 {
                        let maker = &mut level.orders[order_idx];
                        let fill_qty = std::cmp::min(remaining_qty, maker.qty);

                        maker.qty -= fill_qty;
                        remaining_qty -= fill_qty;

                        // Emit fill execution report
                        let _ = out_q.send(ExecutionReport::Filled {
                            maker_id: maker.order_id,
                            taker_id: incoming.order_id,
                            price: maker.price,
                            qty: fill_qty,
                        });

                        if maker.qty == 0 {
                            self.order_lookup.remove(&maker.order_id);
                            level.orders.remove(order_idx);
                        } else {
                            order_idx += 1;
                        }
                    }

                    if level.orders.is_empty() {
                        self.asks.remove(0);
                    }
                }

                // If partially filled, rest the remaining quantity on the Bid book
                if remaining_qty > 0 {
                    let resting_order = Order { qty: remaining_qty, ..incoming };
                    self.insert_bid(resting_order);
                    self.order_lookup.insert(incoming.order_id, Side::Buy);
                    let _ = out_q.send(ExecutionReport::Accepted { order_id: incoming.order_id });
                }
            }
            Side::Sell => {
                // Match against Bids (Buys)
                while remaining_qty > 0 && !self.bids.is_empty() && self.bids[0].price >= incoming.price {
                    let level = &mut self.bids[0];
                    let mut order_idx = 0;

                    while order_idx < level.orders.len() && remaining_qty > 0 {
                        let maker = &mut level.orders[order_idx];
                        let fill_qty = std::cmp::min(remaining_qty, maker.qty);

                        maker.qty -= fill_qty;
                        remaining_qty -= fill_qty;

                        let _ = out_q.send(ExecutionReport::Filled {
                            maker_id: maker.order_id,
                            taker_id: incoming.order_id,
                            price: maker.price,
                            qty: fill_qty,
                        });

                        if maker.qty == 0 {
                            self.order_lookup.remove(&maker.order_id);
                            level.orders.remove(order_idx);
                        } else {
                            order_idx += 1;
                        }
                    }

                    if level.orders.is_empty() {
                        self.bids.remove(0);
                    }
                }

                if remaining_qty > 0 {
                    let resting_order = Order { qty: remaining_qty, ..incoming };
                    self.insert_ask(resting_order);
                    self.order_lookup.insert(incoming.order_id, Side::Sell);
                    let _ = out_q.send(ExecutionReport::Accepted { order_id: incoming.order_id });
                }
            }
        }
    }

    #[inline(always)]
    fn insert_bid(&mut self, order: Order) {
        if let Some(pos) = self.bids.iter().position(|l| l.price == order.price) {
            self.bids[pos].orders.push(order);
        } else {
            let insert_pos = self.bids.iter().position(|l| l.price < order.price).unwrap_or(self.bids.len());
            self.bids.insert(insert_pos, LimitLevel { price: order.price, orders: vec![order] });
        }
    }

    #[inline(always)]
    fn insert_ask(&mut self, order: Order) {
        if let Some(pos) = self.asks.iter().position(|l| l.price == order.price) {
            self.asks[pos].orders.push(order);
        } else {
            let insert_pos = self.asks.iter().position(|l| l.price > order.price).unwrap_or(self.asks.len());
            self.asks.insert(insert_pos, LimitLevel { price: order.price, orders: vec![order] });
        }
    }
}

// =====================================================================
// 3. LOW-LATENCY INFRASTRUCTURE RUNTIME
// =====================================================================

fn main() {
    // We use bounded, lock-free channels. Large capacities prevent execution blockages.
    let (input_tx, input_rx): (Sender<Order>, Receiver<Order>) = bounded(65536);
    let (output_tx, output_rx): (Sender<ExecutionReport>, Receiver<ExecutionReport>) = bounded(65536);

    // Get available CPU cores for pinning
    let cores = core_affinity::get_core_ids().expect("Failed to detect CPU cores");

    // Thread 1: Core Matching Engine
    let engine_core = cores[0]; // Pin to Core 0
    let engine_handle = thread::spawn(move || {
        core_affinity::set_for_current(engine_core);
        println!("[Engine] Thread pinned to CPU Core {:?}", engine_core.id);

        let mut engine = MatchingEngine::new("BTC-USD".to_string(), 10000);

        // Busy-spin loop for low latency (no thread-sleeping/parking)
        loop {
            if let Ok(order) = input_rx.try_recv() {
                engine.limit_order(order, &output_tx);
            }
            // In a production system, we'd add CPU hints to lower power during empty spin:
            // std::hint::spin_loop();
        }
    });

    // Thread 2: Simulating Input Gateway (e.g., TCP/FIX parsing)
    let gateway_core = cores[1]; // Pin to Core 1
    let gateway_handle = thread::spawn(move || {
        core_affinity::set_for_current(gateway_core);
        println!("[Gateway] Thread pinned to CPU Core {:?}", gateway_core.id);

        // Warm up and send 1,000,000 orders
        for i in 0..1_000_000 {
            let side = if i % 2 == 0 { Side::Buy } else { Side::Sell };
            let order = Order {
                order_id: i,
                price: 10000 + (i % 10), // Fluctuate price slightly around 100.00
                qty: 10,
                side,
            };
            let _ = input_tx.send(order);
        }
    });

    // Thread 3: Simulating Output Market Data / Drop Copy (Scale-out layer)
    let output_core = cores[2]; // Pin to Core 2
    let output_handle = thread::spawn(move || {
        core_affinity::set_for_current(output_core);
        println!("[Output] Thread pinned to CPU Core {:?}", output_core.id);

        let start_time = Instant::now();
        let mut total_processed = 0;

        loop {
            if let Ok(_report) = output_rx.try_recv() {
                total_processed += 1;
                if total_processed == 1_000_000 {
                    let elapsed = start_time.elapsed();
                    println!(
                        "[Success] Processed 1M orders in {:.2?}. Average latency per order: {:.2?}",
                        elapsed,
                        elapsed / 1_000_000
                    );
                    break;
                }
            }
        }
    });

    // Keep main thread alive
    gateway_handle.join().unwrap();
    output_handle.join().unwrap();
}
```

