#include <iostream>
#include <atomic>
#include <thread>
#include <array>
#include <chrono>
#include <vector>
#include <optional>

// Prevent false sharing by aligning to typical L1/L2 cache line size (64 bytes)
constexpr size_t CACHE_LINE_SIZE = 64;

// --- 1. DATA STRUCTURES (Cache-Friendly, Standard Layout) ---
enum class Side : uint8_t { Buy, Sell };
enum class OrderType : uint8_t { Limit, Market };

struct alignas(CACHE_LINE_SIZE) Order {
    uint64_t order_id;
    uint32_t price; // Represented as fixed-point integer (e.g., USD cents or micro-cents)
    uint32_t quantity;
    Side side;
    OrderType type;
    char symbol[8]; // Fixed size to avoid pointer chasing/heap allocation
};

struct alignas(CACHE_LINE_SIZE) ExecutionReport {
    uint64_t order_id;
    uint32_t filled_quantity;
    uint32_t execution_price;
    bool is_fully_filled;
};

// --- 2. LOCK-FREE SPSC RING BUFFER (Zero Contention Queue) ---
// Used to pass orders from Net/Gateway thread to Core Matching thread without locks.
template <typename T, size_t Capacity>
class alignas(CACHE_LINE_SIZE) SPSCRingBuffer {
    static_assert((Capacity & (Capacity - 1)) == 0, "Capacity must be a power of 2");
public:
    SPSCRingBuffer() : write_idx_(0), read_idx_(0) {}

    bool push(const T& item) {
        const size_t curr_write = write_idx_.load(std::memory_order_relaxed);
        const size_t curr_read = read_idx_.load(std::memory_order_acquire);

        if ((curr_write - curr_read) == Capacity) {
            return false; // Queue is full
        }

        ring_[curr_write & (Capacity - 1)] = item;
        write_idx_.store(curr_write + 1, std::memory_order_release);
        return true;
    }

    bool pop(T& item) {
        const size_t curr_read = read_idx_.load(std::memory_order_relaxed);
        const size_t curr_write = write_idx_.load(std::memory_order_acquire);

        if (curr_read == curr_write) {
            return false; // Queue is empty
        }

        item = ring_[curr_read & (Capacity - 1)];
        read_idx_.store(curr_read + 1, std::memory_order_release);
        return true;
    }

private:
    std::array<T, Capacity> ring_;
    // Keep read and write indices on separate cache lines to avoid "false sharing"
    alignas(CACHE_LINE_SIZE) std::atomic<size_t> write_idx_;
    alignas(CACHE_LINE_SIZE) std::atomic<size_t> read_idx_;
};

// --- 3. ULTRA-LOW LATENCY ORDER BOOK (No Heap Allocations) ---
class OrderBook {
public:
    explicit OrderBook(const char* symbol) {
        std::copy(symbol, symbol + 8, symbol_);
    }

    // Process a Limit Order (Simplified for Demo, but memory deterministic)
    void limit_order(const Order& order, SPSCRingBuffer<ExecutionReport, 1024>& outbound_queue) {
        // Real systems would match against opposite book. 
        // Here we simulate a fill immediately for demo performance metrics.
        ExecutionReport report {
            .order_id = order.order_id,
            .filled_quantity = order.quantity,
            .execution_price = order.price,
            .is_fully_filled = true
        };

        // Non-blocking write to the outbound network gateway
        while (!outbound_queue.push(report)) {
            // Spin/Busy-wait if network outbound queue is temporarily full
            std::this_thread::yield(); 
        }
    }

private:
    char symbol_[8];
    // In a production engine, you would use a pre-allocated flat-array tree
    // or static memory pool for the bid/ask levels instead of dynamic vectors.
};

// --- 4. ENGINE PIPELINE AND THREAD COORDINATION ---
class TradingEngine {
public:
    TradingEngine() : book_("AAPL"), running_(true) {}

    ~TradingEngine() {
        running_ = false;
        if (matching_thread_.joinable()) matching_thread_.join();
        if (outbound_thread_.joinable()) outbound_thread_.join();
    }

    void start() {
        // Start Outbound Network Emulator
        outbound_thread_ = std::thread(&TradingEngine::run_outbound_gateway, this);

        // Start Core Matching Engine (Pin to CPU Core 1 for maximum low-latency cache locality)
        matching_thread_ = std::thread(&TradingEngine::run_matching_engine, this);
    }

    // Clients/API Threads call this to inject orders
    bool submit_order(const Order& order) {
        return inbound_queue_.push(order);
    }

private:
    void run_matching_engine() {
        // Core Thread Pinning (OS dependent, shown conceptually)
        // pthread_setaffinity_np(pthread_self(), ...);

        Order incoming_order;
        std::cout << "[Matching Engine] Running on isolated core. Waiting for orders...\n";

        while (running_.load(std::memory_order_relaxed)) {
            // Busy-wait loop (Spinning is lower latency than thread sleeping/context-switching)
            if (inbound_queue_.pop(incoming_order)) {
                // Execute Order on the isolated Matching Thread
                book_.limit_order(incoming_order, outbound_queue_);
            }
        }
    }

    void run_outbound_gateway() {
        ExecutionReport report;
        while (running_.load(std::memory_order_relaxed)) {
            if (outbound_queue_.pop(report)) {
                // Simulate pushing to a TCP/FIX Socket or multicast feed
                std::cout << "[OUTBOUND FIX] Order " << report.order_id 
                          << " executed " << report.filled_quantity 
                          << " shares @ $" << (report.execution_price / 100.0) << "\n";
            }
        }
    }

    OrderBook book_;
    std::atomic<bool> running_;

    // Core queues
    SPSCRingBuffer<Order, 1024> inbound_queue_;
    SPSCRingBuffer<ExecutionReport, 1024> outbound_queue_;

    std::thread matching_thread_;
    std::thread outbound_thread_;
};

