### Rust Implementation

Below is a complete, highly optimized, memory-efficient implementation of an in-memory Limit Order Book matching engine.

```rust
use std::collections::BTreeMap;
use std::sync::mpsc::{sync_channel, Receiver, SyncSender};
use std::thread;
use std::time::Instant;

// ==========================================
// 1. DATA STRUCTURES (Optimized for Cache)
// ==========================================

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Side {
    Buy,
    Sell,
}

#[derive(Debug, Clone, Copy)]
pub struct Order {
    pub id: u64,
    pub price: u64, // Represented as cents/fixed-point to avoid float issues
    pub qty: u32,
    pub side: Side,
}

#[derive(Debug, Clone)]
pub struct Trade {
    pub maker_order_id: u64,
    pub taker_order_id: u64,
    pub price: u64,
    pub qty: u32,
}

// ==========================================
// 2. THE CORE MATCHING ENGINE (No Locks)
// ==========================================

pub struct OrderBook {
    // BTreeMap keeps prices sorted. 
    // Rev() is used for Bids (highest price first), standard for Asks (lowest first).
    pub bids: BTreeMap<u64, Vec<Order>>, // Key: Price, Value: FIFO queue of Orders
    pub asks: BTreeMap<u64, Vec<Order>>,
}

impl OrderBook {
    pub fn new() -> Self {
        Self {
            bids: BTreeMap::new(),
            asks: BTreeMap::new(),
        }
    }

    /// Matches an incoming order against the book. Zero-allocation on the hot-path.
    pub fn match_order(&mut self, taker_order: Order, trades: &mut Vec<Trade>) {
        let mut remaining_qty = taker_order.qty;

        match taker_order.side {
            Side::Buy => {
                // Buy order matches with cheapest sell orders (asks)
                while remaining_qty > 0 {
                    // Find lowest ask
                    if let Some(entry) = self.asks.first_entry() {
                        let ask_price = *entry.key();
                        if ask_price > taker_order.price {
                            break; // Taker buy price is too low
                        }

                        let ask_orders = entry.into_mut();
                        while !ask_orders.is_empty() && remaining_qty > 0 {
                            let mut maker_order = ask_orders.remove(0);
                            let match_qty = std::cmp::min(remaining_qty, maker_order.qty);

                            trades.push(Trade {
                                maker_order_id: maker_order.id,
                                taker_order_id: taker_order.id,
                                price: ask_price,
                                qty: match_qty,
                            });

                            remaining_qty -= match_qty;
                            maker_order.qty -= match_qty;

                            if maker_order.qty > 0 {
                                // Put partially filled maker order back at the front of FIFO
                                ask_orders.insert(0, maker_order);
                            }
                        }

                        // Clean up empty price levels
                        if ask_orders.is_empty() {
                            self.asks.remove(&ask_price);
                        }
                    } else {
                        break; // No asks available
                    }
                }

                // If unfilled, add remaining to Bids
                if remaining_qty > 0 {
                    let mut order = taker_order;
                    order.qty = remaining_qty;
                    self.bids.entry(order.price).or_insert_with(Vec::new).push(order);
                }
            }
            Side::Sell => {
                // Sell order matches with highest buy orders (bids)
                while remaining_qty > 0 {
                    // Find highest bid
                    if let Some(entry) = self.bids.last_entry() {
                        let bid_price = *entry.key();
                        if bid_price < taker_order.price {
                            break; // Taker sell price is too high
                        }

                        let bid_orders = entry.into_mut();
                        while !bid_orders.is_empty() && remaining_qty > 0 {
                            let mut maker_order = bid_orders.remove(0);
                            let match_qty = std::cmp::min(remaining_qty, maker_order.qty);

                            trades.push(Trade {
                                maker_order_id: maker_order.id,
                                taker_order_id: taker_order.id,
                                price: bid_price,
                                qty: match_qty,
                            });

                            remaining_qty -= match_qty;
                            maker_order.qty -= match_qty;

                            if maker_order.qty > 0 {
                                bid_orders.insert(0, maker_order);
                            }
                        }

                        if bid_orders.is_empty() {
                            self.bids.remove(&bid_price);
                        }
                    } else {
                        break;
                    }
                }

                if remaining_qty > 0 {
                    let mut order = taker_order;
                    order.qty = remaining_qty;
                    self.asks.entry(order.price).or_insert_with(Vec::new).push(order);
                }
            }
        }
    }
}

// ==========================================
// 3. PIPELINE & EXECUTION
// ==========================================

fn main() {
    // Bound channels to prevent memory exhaustion and force backpressure
    let (ingress_tx, ingress_rx): (SyncSender<Order>, Receiver<Order>) = sync_channel(1024);
    let (egress_tx, egress_rx): (SyncSender<Vec<Trade>>, Receiver<Vec<Trade>>) = sync_channel(1024);

    // --- Thread 1: The Matching Engine (Core) ---
    // This thread is dedicated solely to matching. No network I/O, no file writing.
    let engine_handle = thread::spawn(move || {
        let mut order_book = OrderBook::new();
        // Re-use allocation for trades to avoid heap allocation overhead during hot path
        let mut trade_buffer = Vec::with_capacity(16); 

        println!("[Engine] Started.");
        while let Ok(order) = ingress_rx.recv() {
            let start = Instant::now();

            order_book.match_order(order, &mut trade_buffer);

            let duration = start.elapsed();

            if !trade_buffer.is_empty() {
                // Send matches to Egress Thread (offloading network/disk I/O)
                let _ = egress_tx.send(trade_buffer.clone());
                trade_buffer.clear();
            }

            // Print latency (In production, use metrics logging outside hot-path)
            if order.id % 100_000 == 0 {
                println!("[Engine] Processed order {} in {:?}", order.id, duration);
            }
        }
    });

    // --- Thread 2: Egress (Publisher) ---
    let egress_handle = thread::spawn(move || {
        while let Ok(trades) = egress_rx.recv() {
            for trade in trades {
                // In production, publish to WebSocket, FIX protocol, or Kafka
                // println!("[Egress] MATCHED: Maker {} & Taker {} @ Price {}", trade.maker_order_id, trade.taker_order_id, trade.price);
                let _ = trade; // Silent use
            }
        }
    });

    // --- Thread 3: Ingress (Simulator) ---
    // Represents API Gateways pushing orders into the engine pipeline
    let ingress_handle = thread::spawn(move || {
        println!("[Ingress] Sending orders...");

        // 1. Send limit buy order
        ingress_tx.send(Order { id: 1, price: 100, qty: 10, side: Side::Buy }).unwrap();
        // 2. Send limit sell order that doesn't cross
        ingress_tx.send(Order { id: 2, price: 105, qty: 5, side: Side::Sell }).unwrap();
        // 3. Send crossing market/limit buy order that triggers match
        ingress_tx.send(Order { id: 3, price: 105, qty: 5, side: Side::Buy }).unwrap();

        // Send a high volume of orders to measure latency
        for id in 4..100_001 {
            let side = if id % 2 == 0 { Side::Buy } else { Side::Sell };
            let order = Order { id, price: 100, qty: 1, side };
            ingress_tx.send(order).unwrap();
        }
    });

    // Join threads
    ingress_handle.join().unwrap();
    drop(ingress_tx); // Closes the engine loop when finished
    engine_handle.join().unwrap();
    egress_handle.join().unwrap();
}
```

