```rust
use std::collections::{BTreeMap, VecDeque};
use std::sync::mpsc::{channel, Receiver, Sender};
use std::thread;
use std::time::Instant;

// ==========================================
// 1. DATA STRUCTURES (Optimized for Cache)
// ==========================================

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Side {
    Buy,
    Sell,
}

#[derive(Debug, Clone, Copy)]
struct Order {
    id: u64,
    price: u64, // Fixed-point: e.g., $100.50 is represented as 10050 to avoid float latency
    qty: u32,
    side: Side,
}

#[derive(Debug, Clone)]
struct Trade {
    maker_id: u64,
    taker_id: u64,
    price: u64,
    qty: u32,
}

// ==========================================
// 2. ORDER BOOK & MATCHING ENGINE (Hot Path)
// ==========================================
struct OrderBook {
    // Bids sorted descending (highest first). Key is price.
    bids: BTreeMap<u64, VecDeque<Order>>,
    // Asks sorted ascending (lowest first). Key is price.
    asks: BTreeMap<u64, VecDeque<Order>>,
}

impl OrderBook {
    fn new() -> Self {
        Self {
            bids: BTreeMap::new(),
            asks: BTreeMap::new(),
        }
    }

    /// Matches an incoming order against the book. 
    /// ZERO allocations occur here if matches are found immediately.
    fn limit_order(&mut self, mut taker_order: Order, trade_tx: &Sender<Trade>) {
        match taker_order.side {
            Side::Buy => {
                // Try to match with lowest asks
                while taker_order.qty > 0 {
                    if let Some(entry) = self.asks.first_entry() {
                        let ask_price = *entry.key();
                        if taker_order.price >= ask_price {
                            let queue = entry.into_mut();
                            while taker_order.qty > 0 && !queue.is_empty() {
                                let maker_order = queue.front_mut().unwrap();
                                let match_qty = std::cmp::min(taker_order.qty, maker_order.qty);

                                // Send trade to the publisher thread
                                let _ = trade_tx.send(Trade {
                                    maker_id: maker_order.id,
                                    taker_id: taker_order.id,
                                    price: ask_price,
                                    qty: match_qty,
                                });

                                taker_order.qty -= match_qty;
                                maker_order.qty -= match_qty;

                                if maker_order.qty == 0 {
                                    queue.pop_front();
                                }
                            }
                            if queue.is_empty() {
                                let price = ask_price;
                                self.asks.remove(&price);
                            }
                        } else {
                            break; // Price no longer matches
                        }
                    } else {
                        break; // No asks left
                    }
                }
                // If there's remaining quantity, add it to the bids book
                if taker_order.qty > 0 {
                    self.bids
                        .entry(taker_order.price)
                        .or_insert_with(VecDeque::new)
                        .push_back(taker_order);
                }
            }
            Side::Sell => {
                // Try to match with highest bids
                while taker_order.qty > 0 {
                    if let Some(entry) = self.bids.last_entry() {
                        let bid_price = *entry.key();
                        if taker_order.price <= bid_price {
                            let queue = entry.into_mut();
                            while taker_order.qty > 0 && !queue.is_empty() {
                                let maker_order = queue.front_mut().unwrap();
                                let match_qty = std::cmp::min(taker_order.qty, maker_order.qty);

                                // Send trade to the publisher thread
                                let _ = trade_tx.send(Trade {
                                    maker_id: maker_order.id,
                                    taker_id: taker_order.id,
                                    price: bid_price,
                                    qty: match_qty,
                                });

                                taker_order.qty -= match_qty;
                                maker_order.qty -= match_qty;

                                if maker_order.qty == 0 {
                                    queue.pop_front();
                                }
                            }
                            if queue.is_empty() {
                                let price = bid_price;
                                self.bids.remove(&price);
                            }
                        } else {
                            break; // Price no longer matches
                        }
                    } else {
                        break; // No bids left
                    }
                }
                // If there's remaining quantity, add it to the asks book
                if taker_order.qty > 0 {
                    self.asks
                        .entry(taker_order.price)
                        .or_insert_with(VecDeque::new)
                        .push_back(taker_order);
                }
            }
        }
    }
}

// ==========================================
// 3. MAIN RUNTIME PIPELINE
// ==========================================
fn main() {
    // Communication Channels (Can be replaced with IPC or Network Ring Buffers for scale)
    let (gateway_tx, engine_rx): (Sender<Order>, Receiver<Order>) = channel();
    let (engine_tx, publisher_rx): (Sender<Trade>, Receiver<Trade>) = channel();

    // --- Thread 1: Matching Engine (Single-Threaded, Core Path) ---
    thread::spawn(move || {
        let mut book = OrderBook::new();
        println!("[Engine] Initialized and waiting for orders...");

        while let Ok(order) = engine_rx.recv() {
            let start = Instant::now();
