                println!("[Engine] Processed order #{} in {} ns", order.id, duration.as_nanos());
            }
        }
    });

    // --- Thread 2: Market Data Publisher ---
    thread::spawn(move || {
        while let Ok(trade) = publisher_rx.recv() {
            println!(
                "[Publisher] TRADE EXECUTION -> Maker: #{}, Taker: #{}, Price: {:.2}, Qty: {}",
                trade.maker_id,
                trade.taker_id,
                trade.price as f64 / 100.0, // format back to decimal
                trade.qty
            );
