    });

    // --- Thread 3: Simulating Inbound Gateway ---
    println!("[Gateway] Simulating high-frequency order influx...");

    // Seed orders (building liquidity)
    gateway_tx.send(Order { id: 1, price: 10050, qty: 10, side: Side::Buy }).unwrap(); // Bid $100.50
    gateway_tx.send(Order { id: 2, price: 10060, qty: 15, side: Side::Buy }).unwrap(); // Bid $100.60
    gateway_tx.send(Order { id: 3, price: 10080, qty: 5, side: Side::Sell }).unwrap(); // Ask $100.80
    gateway_tx.send(Order { id: 4, price: 10090, qty: 20, side: Side::Sell }).unwrap(); // Ask $100.90

