use std::cmp::min;
use std::sync::mpsc::{sync_channel, Receiver, SyncSender};
use std::thread;
use std::time::Instant;

// ==========================================
// 1. DATA STRUCTURES (Optimized for Cache)
// ==========================================

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Side {
    Buy,
    Sell,
}

#[derive(Debug, Clone, Copy)]
struct Order {
    id: u64,
    price: u64, // Represented as integer ticks (e.g., $100.00 -> 10000) to avoid float jitter
    qty: u32,
    side: Side,
}

#[derive(Debug, Clone, Copy)]
struct Trade {
    maker_id: u64,
    taker_id: u64,
    price: u64,
    qty: u32,
}

// ==========================================
// 2. CACHE-FRIENDLY ORDER BOOK
// ==========================================
struct OrderBook {
    // Vectors pre-allocated on startup to prevent dynamic heap allocation during runtime
    bids: Vec<Order>, // Sorted: Highest price at the end (so pop() is O(1))
    asks: Vec<Order>, // Sorted: Lowest price at the end (so pop() is O(1))
}

impl OrderBook {
    fn new(capacity: usize) -> Self {
        Self {
            bids: Vec::with_capacity(capacity),
            asks: Vec::with_capacity(capacity),
        }
    }

    // Hot path: Matches or inserts an order
    fn process_limit_order(&mut self, mut order: Order, trade_sender: &SyncSender<Trade>) {
        match order.side {
            Side::Buy => {
                // Match against asks (lowest price at the end)
                while order.qty > 0 && !self.asks.is_empty() {
                    let mut best_ask = self.asks.last_mut().unwrap();
                    if order.price >= best_ask.price {
                        let match_qty = min(order.qty, best_ask.qty);

                        let trade = Trade {
                            maker_id: best_ask.id,
                            taker_id: order.id,
                            price: best_ask.price,
                            qty: match_qty,
                        };
                        let _ = trade_sender.send(trade); // Non-blocking dispatch to publisher

                        order.qty -= match_qty;
                        best_ask.qty -= match_qty;

                        if best_ask.qty == 0 {
                            self.asks.pop(); // Remove completed order (O(1))
                        }
                    } else {
                        break;
                    }
                }
                // If remaining quantity, insert into Bids (keep sorted)
                if order.qty > 0 {
                    let pos = self.bids.binary_search_by(|probe| probe.price.cmp(&order.price))
                        .unwrap_or_else(|e| e);
                    self.bids.insert(pos, order);
                }
            }
            Side::Sell => {
                // Match against bids (highest price at the end)
                while order.qty > 0 && !self.bids.is_empty() {
                    let mut best_bid = self.bids.last_mut().unwrap();
                    if order.price <= best_bid.price {
                        let match_qty = min(order.qty, best_bid.qty);

                        let trade = Trade {
                            maker_id: best_bid.id,
                            taker_id: order.id,
                            price: best_bid.price,
                            qty: match_qty,
                        };
                        let _ = trade_sender.send(trade);

                        order.qty -= match_qty;
                        best_bid.qty -= match_qty;

                        if best_bid.qty == 0 {
                            self.bids.pop();
                        }
                    } else {
                        break;
                    }
                }
                // If remaining quantity, insert into Asks (keep sorted)
                if order.qty > 0 {
                    let pos = self.asks.binary_search_by(|probe| order.price.cmp(&probe.price))
                        .unwrap_or_else(|e| e);
                    self.asks.insert(pos, order);
                }
            }
        }
    }
}

// ==========================================
// 3. MULTI-THREADED PIPELINE SETUP
// ==========================================
fn main() {
    // Channels with bounded capacity (acts as low-latency ring buffers)
    let (order_sender, order_receiver): (SyncSender<Order>, Receiver<Order>) = sync_channel(1024);
    let (trade_sender, trade_receiver): (SyncSender<Trade>, Receiver<Trade>) = sync_channel(1024);

    // --- THREAD 1: THE MATCHING ENGINE ---
    // Dedicated thread executing on a single-core loop
    let engine_handle = thread::spawn(move || {
        let mut book = OrderBook::new(10_000); // Pre-allocate room for 10k orders
        println!("[Engine] Orderbook initialized. Waiting for orders...");

        while let Ok(order) = order_receiver.recv() {
            let start = Instant::now();
            book.process_limit_order(order, &trade_sender);
            let duration = start.elapsed();

            // Log matching latency (Normally bypassed in production)
            if order.id % 5 == 0 { 
                println!("[Engine] Processed Order ID {} in {} ns", order.id, duration.as_nanos());
            }
        }
    });

    // --- THREAD 2: THE MARKET DATA PUBLISHER ---
    // Processes outbound trades without slowing down the matching engine
    let publisher_handle = thread::spawn(move || {
        while let Ok(trade) = trade_receiver.recv() {
            println!(
                "[Publisher] TRADE EXECUTION: Maker #{} matched with Taker #{} | {} Units @ ${:.2}",
                trade.maker_id, trade.taker_id, trade.qty, (trade.price as f64) / 100.0
            );
        }
    });

    // --- THREAD 3: THE GATEWAY (INGESTION SIMULATOR) ---
    // Simulates a client API / FIX protocol gateway feeding the engine
    println!("[Gateway] Starting simulated market order stream...");

    let orders = vec![
        Order { id: 1, price: 10050, qty: 10, side: Side::Sell }, // Limit Ask $100.50
        Order { id: 2, price: 10060, qty: 5, side: Side::Sell },  // Limit Ask $100.60
        Order { id: 3, price: 10040, qty: 10, side: Side::Buy },  // Limit Bid $100.40 (No match)
        Order { id: 4, price: 10050, qty: 12, side: Side::Buy },  // Limit Bid $100.50 (Matches Order #1 fully, Order #2 partially)
    ];

    for order in orders {
        thread::sleep(std::time::Duration::from_millis(100)); // Simulate networking arrival interval
        let _ = order_sender.send(order);
    }

    // Drop senders to allow threads to close gracefully after processing
    drop(order_sender);
    let _ = engine_handle.join();
    drop(trade_sender);
    let _ = publisher_handle.join();
}
