### C++ Low-Latency Trading Engine Architecture

This architecture separates the platform into:
* **The Gateway Thread (Producer):** Receives client orders (simulated) and writes them to a lock-free queue.
* **The Matching/Risk Thread (Consumer/Hot Path):** Sequentially polls the queue, performs a pre-trade risk check, updates a simplified Order Book, and matches trades.

```cpp
#include <iostream>
#include <atomic>
#include <thread>
#include <vector>
#include <chrono>
#include <array>
#include <optional>

// --- Configuration & Constants ---
constexpr size_t RING_BUFFER_SIZE = 1024; // Must be a power of 2 for fast bitwise modulo
constexpr size_t CACHE_LINE_SIZE = 64;

// --- Data Structures (PODs - Plain Old Data) ---
enum class Side : char { BUY = 'B', SELL = 'S' };

struct alignas(32) Order {
    uint64_t order_id;
    uint32_t price;       // Scaled integer (e.g., USD cents) to avoid float inaccuracies
    uint32_t quantity;
    Side side;
    char symbol[8];       // Fixed-size char array instead of std::string (prevents heap allocation)
};

struct Trade {
    uint64_t match_id;
    uint64_t maker_order_id;
    uint64_t taker_order_id;
    uint32_t price;
    uint32_t quantity;
};

// --- Low-Latency Lock-Free SPSC Queue ---
// Aligned to cache lines to prevent "False Sharing" between Producer and Consumer threads
template <typename T, size_t Capacity>
class LockFreeSPSCQueue {
    static_assert((Capacity & (Capacity - 1)) == 0, "Capacity must be a power of 2");
public:
    LockFreeSPSCQueue() : write_idx(0), read_idx(0) {}

    // Executed by Gateway Thread
    bool enqueue(const T& item) {
        const size_t curr_write = write_idx.load(std::memory_order_relaxed);
        const size_t curr_read = read_idx.load(std::memory_order_acquire);

        if ((curr_write - curr_read) == Capacity) {
            return false; // Queue is full
        }

        buffer[curr_write & (Capacity - 1)] = item;
        write_idx.store(curr_write + 1, std::memory_order_release);
        return true;
    }

    // Executed by Matching Engine Thread (Hot Path)
    bool dequeue(T& item) {
        const size_t curr_read = read_idx.load(std::memory_order_relaxed);
        const size_t curr_write = write_idx.load(std::memory_order_acquire);

        if (curr_read == curr_write) {
            return false; // Queue is empty
        }

        item = buffer[curr_read & (Capacity - 1)];
        read_idx.store(curr_read + 1, std::memory_order_release);
        return true;
    }

private:
    alignas(CACHE_LINE_SIZE) std::array<T, Capacity> buffer;
    alignas(CACHE_LINE_SIZE) std::atomic<size_t> write_idx;
    alignas(CACHE_LINE_SIZE) std::atomic<size_t> read_idx;
};

// --- Pre-Trade Risk Engine (Sub-microsecond latency) ---
class RiskEngine {
public:
    static constexpr uint32_t MAX_ORDER_VALUE = 1'000'000; // E.g., $10,000.00 max limit

    // Inlined to allow compiler to embed the logic directly in the execution path
    inline bool check_risk(const Order& order) noexcept {
        uint64_t total_value = static_cast<uint64_t>(order.price) * order.quantity;
        return total_value <= MAX_ORDER_VALUE;
    }
};

// --- Execution & Matching Engine ---
class MatchingEngine {
public:
    MatchingEngine() : trade_id_counter(0), best_bid(0), best_ask(0xFFFFFFFF) {}

    // Simplistic O(1) matching logic for demonstration (matching against top of book)
    inline std::optional<Trade> process_order(const Order& order) noexcept {
        if (order.side == Side::BUY) {
            if (order.price >= best_ask) {
                // We have a match! (In production, this would match against an array/tree of Limit Orders)
                Trade trade{ ++trade_id_counter, 9999, order.order_id, best_ask, order.quantity };
                best_ask = 0xFFFFFFFF; // Clear the ask
                return trade;
            } else {
                best_bid = order.price;
            }
        } else { // Side::SELL
            if (order.price <= best_bid) {
                Trade trade{ ++trade_id_counter, 8888, order.order_id, best_bid, order.quantity };
                best_bid = 0; // Clear the bid
                return trade;
            } else {
                best_ask = order.price;
            }
        }
        return std::nullopt;
    }

private:
    uint64_t trade_id_counter;
    uint32_t best_bid;
    uint32_t best_ask;
};

// --- Global Trading Engine Thread context ---
std::atomic<bool> running(true);
LockFreeSPSCQueue<Order, RING_BUFFER_SIZE> order_queue;

// --- Hot Path Thread: Core Trading Engine ---
void run_matching_engine() {
    // Thread pinning concept: ideally you'd pin this thread to an isolated CPU core
    // pthread_setaffinity_np(...); 

    RiskEngine risk_engine;
    MatchingEngine matching_engine;
    Order order;

    std::cout << "[Engine] Matching Engine started on dedicated thread.\n";

    while (running.load(std::memory_order_relaxed)) {
        // Busy-waiting loop (polling) to avoid context-switching/sleeping latency
        if (order_queue.dequeue(order)) {
            auto start_time = std::chrono::high_resolution_clock::now();

            // 1. Run Pre-Trade Risk Check
            if (!risk_engine.check_risk(order)) {
                auto end_time = std::chrono::high_resolution_clock::now();
                auto duration = std::chrono::duration_cast<std::chrono::nanoseconds>(end_time - start_time).count();
                std::cout << "[Engine] Order " << order.order_id << " REJECTED by Risk Engine in " << duration << " ns\n";
                continue;
            }

            // 2. Process Order inside the Matching Engine
            auto trade_opt = matching_engine.process_order(order);

            auto end_time = std::chrono::high_resolution_clock::now();
            auto duration = std::chrono::duration_cast<std::chrono::nanoseconds>(end_time - start_time).count();

            if (trade_opt) {
                std::cout << "[Engine] MATCHED Trade #" << trade_opt->match_id 
                          << " (Taker: " << trade_opt->taker_order_id << ") at $" 
                          << (trade_opt->price / 100.0) << " inside " << duration << " ns\n";
            } else {
                std::cout << "[Engine] Order " << order.order_id << " placed on book inside " << duration << " ns\n";
            }
        }
    }
}

// --- Main execution/Simulation (Cold Path) ---
int main() {
    // Start the hot-path Matching thread
    std::thread engine_thread(run_matching_engine);

    // Give the engine thread a moment to spin up and warm up its CPU caches
    std::this_thread::sleep_for(std::chrono::milliseconds(50));

    std::cout << "[Gateway] Client sending orders...\n";

    // Simulate incoming order flow
    Order order1{ 1001, 5050, 10, Side::SELL, "AAPL" }; // Sell 10 AAPL @ $50.50
    Order order2{ 1002, 5100, 10, Side::BUY,  "AAPL" }; // Buy 10 AAPL @ $51.00 (Should Match)
    Order order3{ 1003, 110000, 10, Side::BUY, "AAPL" }; // Buy 10 AAPL @ $1100.00 (Should FAIL Risk Check: $11,000 > max limit)

    order_queue.enqueue(order1);
    std::this_thread::sleep_for(std::chrono::milliseconds(100)); // Simulating gap between orders

    order_queue.enqueue(order2);
    std::this_thread::sleep_for(std::chrono::milliseconds(100));

    order_queue.enqueue(order3);
    std::this_thread::sleep_for(std::chrono::milliseconds(200));

    // Shutdown gracefully
    running.store(false);
    engine_thread.join();

    std::cout << "[Gateway] Platform stopped.\n";
    return 0;
}
```

