use std::collections::{BTreeMap, VecDeque};
use std::sync::mpsc::{channel, Receiver, Sender};
use std::thread;
use std::time::Instant;

// ==========================================
// 1. Data Models (Optimized for Cache)
// ==========================================

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Side {
    Buy,
    Sell,
}

#[derive(Debug, Clone)]
pub struct Order {
    pub id: u64,
    pub price: u64, // Fixed-point: e.g., $100.50 represented as u64: 10050
    pub qty: u32,
    pub side: Side,
}

#[derive(Debug, Clone)]
pub struct Trade {
    pub buy_order_id: u64,
    pub sell_order_id: u64,
    pub price: u64,
    pub qty: u32,
}

// ==========================================
// 2. High-Performance Order Book
// ==========================================
pub struct OrderBook {
    // BTreeMap keeps prices sorted.
    // Buy orders: highest price first (Reverse order)
    buy_levels: BTreeMap<std::cmp::Reverse<u64>, VecDeque<Order>>,
    // Sell orders: lowest price first
    sell_levels: BTreeMap<u64, VecDeque<Order>>,
}

impl OrderBook {
    pub fn new() -> Self {
        Self {
            buy_levels: BTreeMap::new(),
            sell_levels: BTreeMap::new(),
        }
    }

    /// Matches or inserts a limit order. Returns a list of generated trades.
    pub fn match_order(&mut self, mut incoming: Order) -> Vec<Trade> {
        let mut trades = Vec::with_capacity(4); // Pre-allocate to prevent reallocation delays

        match incoming.side {
            Side::Buy => {
                // Try to match with lowest sells first
                while incoming.qty > 0 {
                    if let Some(mut lowest_sell_entry) = self.sell_levels.first_entry() {
                        let &lowest_sell_price = lowest_sell_entry.key();

                        if incoming.price >= lowest_sell_price {
                            let sell_queue = lowest_sell_entry.get_mut();

                            while incoming.qty > 0 && !sell_queue.is_empty() {
                                let mut resting_sell = sell_queue.pop_front().unwrap();
                                let match_qty = std::cmp::min(incoming.qty, resting_sell.qty);

                                trades.push(Trade {
                                    buy_order_id: incoming.id,
                                    sell_order_id: resting_sell.id,
                                    price: resting_sell.price,
                                    qty: match_qty,
                                });

                                incoming.qty -= match_qty;
                                resting_sell.qty -= match_qty;

                                if resting_sell.qty > 0 {
                                    sell_queue.push_front(resting_sell); // Return remaining back to queue
                                }
                            }
                            if sell_queue.is_empty() {
                                lowest_sell_entry.remove();
                            }
                        } else {
                            break; // Spread is open, cannot match
                        }
                    } else {
                        break; // No sells to match with
                    }
                }
                // If order remains unfilled, add to resting buy orders
                if incoming.qty > 0 {
                    self.buy_levels
                        .entry(std::cmp::Reverse(incoming.price))
                        .or_insert_with(VecDeque::new)
                        .push_back(incoming);
                }
            }
            Side::Sell => {
                // Try to match with highest buys first
                while incoming.qty > 0 {
                    if let Some(mut highest_buy_entry) = self.buy_levels.first_entry() {
                        let highest_buy_price = highest_buy_entry.key().0;

                        if incoming.price <= highest_buy_price {
                            let buy_queue = highest_buy_entry.get_mut();

                            while incoming.qty > 0 && !buy_queue.is_empty() {
                                let mut resting_buy = buy_queue.pop_front().unwrap();
                                let match_qty = std::cmp::min(incoming.qty, resting_buy.qty);

                                trades.push(Trade {
                                    buy_order_id: resting_buy.id,
                                    sell_order_id: incoming.id,
                                    price: resting_buy.price,
                                    qty: match_qty,
                                });

                                incoming.qty -= match_qty;
                                resting_buy.qty -= match_qty;

                                if resting_buy.qty > 0 {
                                    buy_queue.push_front(resting_buy);
                                }
                            }
                            if buy_queue.is_empty() {
                                highest_buy_entry.remove();
                            }
                        } else {
                            break; // Spread is open, cannot match
                        }
                    } else {
                        break; // No buys to match with
                    }
                }
                // If order remains unfilled, add to resting sell orders
                if incoming.qty > 0 {
                    self.sell_levels
                        .entry(incoming.price)
                        .or_insert_with(VecDeque::new)
                        .push_back(incoming);
                }
            }
        }
        trades
    }
}

// ==========================================
// 3. Execution & Scaling Framework
// ==========================================
fn main() {
    // Standard channels are used here for simplicity. 
    // For production, replace these with lock-free Ring Buffers (e.g., `crossbeam-channel` or custom SHM).
    let (ingress_tx, ingress_rx): (Sender<Order>, Receiver<Order>) = channel();
    let (egress_tx, egress_rx): (Sender<Vec<Trade>>, Receiver<Vec<Trade>>) = channel();

    // --- Thread 1: Ingress (Gateway Parser Sim) ---
    let gateway_handle = thread::spawn(move || {
        println!("[Gateway] Ingesting orders...");
        for i in 1..=5 {
            // Alternate buys and sells to create instant matching conditions
            let order = Order {
                id: i,
                price: if i % 2 == 0 { 10000 } else { 10000 }, // $100.00
                qty: 10,
                side: if i % 2 == 0 { Side::Sell } else { Side::Buy },
            };
            ingress_tx.send(order).unwrap();
        }
    });

    // --- Thread 2: Matching Engine (Hot Path) ---
    // Single-threaded state ownership ensures lock-free execution of the critical section
    let engine_handle = thread::spawn(move || {
        let mut order_book = OrderBook::new();
        println!("[Engine] Matching Engine started.");

        while let Ok(order) = ingress_rx.recv() {
            let start_time = Instant::now();

            // Critical section execution
            let trades = order_book.match_order(order);

            let duration = start_time.elapsed();

            if !trades.is_empty() {
                println!("[Engine] Match latency: {:?}", duration);
                egress_tx.send(trades).unwrap();
            }
        }
    });

    // --- Thread 3: Egress (Market Data Feed Sim) ---
    let market_data_handle = thread::spawn(move || {
        println!("[Market Data] Publisher started.");
        while let Ok(trades) = egress_rx.recv() {
            for trade in trades {
                println!(
                    "[MD Feed] Execution Report: Buy Order #{} matched Sell Order #{} | Qty: {} @ Price: ${:.2}",
                    trade.buy_order_id,
                    trade.sell_order_id,
                    trade.qty,
                    (trade.price as f64) / 100.0
                );
            }
        }
    });

    // Join threads to keep the runtime alive
    gateway_handle.join().unwrap();
    engine_handle.join().unwrap();
    market_data_handle.join().unwrap();
}
