use std::collections::VecDeque;
use std::sync::mpsc::{channel, Sender};
use std::thread;
use std::time::{Duration, Instant};

// =====================================================================
// 1. DATA STRUCTURES (Optimized for Cache Locality & Stack Allocation)
// =====================================================================

#[derive(Debug, Clone, Copy)]
pub enum Side {
    Buy,
    Sell,
}

#[derive(Debug, Clone, Copy)]
pub struct Order {
    pub order_id: u64,
    pub symbol_hash: u32, // Numeric hash instead of String to prevent heap allocation
    pub price: u64,       // Fixed-point integer (e.g., USD cents) to avoid float inaccuracies
    pub qty: u32,
    pub side: Side,
}

#[derive(Debug, Clone)]
pub struct TradeReport {
    pub buy_order_id: u64,
    pub sell_order_id: u64,
    pub price: u64,
    pub qty: u32,
    pub latency_ns: u128, // Measure performance in nanoseconds
}

// =====================================================================
// 2. MATCHING ENGINE (The "Hot Path")
// =====================================================================
pub struct MatchingEngine {
    // Vectors pre-allocated on startup to avoid runtime heap allocations
    bids: VecDeque<Order>, // Sorted descending by price
    asks: VecDeque<Order>, // Sorted ascending by price
}

impl MatchingEngine {
    pub fn new(capacity: usize) -> Self {
        Self {
            bids: VecDeque::with_capacity(capacity),
            asks: VecDeque::with_capacity(capacity),
        }
    }

    pub fn process_order(&mut self, incoming: Order) -> Option<TradeReport> {
        let start_time = Instant::now();

        match incoming.side {
            Side::Buy => {
                // Try to match with the lowest ask
                if let Some(best_ask) = self.asks.front_mut() {
                    if incoming.price >= best_ask.price {
                        let fill_qty = std::cmp::min(incoming.qty, best_ask.qty);
                        let report = TradeReport {
                            buy_order_id: incoming.order_id,
                            sell_order_id: best_ask.order_id,
                            price: best_ask.price,
                            qty: fill_qty,
                            latency_ns: start_time.elapsed().as_nanos(),
                        };

                        best_ask.qty -= fill_qty;
                        if best_ask.qty == 0 {
                            self.asks.pop_front();
                        }
                        return Some(report);
                    }
                }
                // No match, insert into bids queue (sorted descending)
                let pos = self.bids.binary_search_by(|probe| probe.price.cmp(&incoming.price).reverse())
                    .unwrap_or_else(|e| e);
                self.bids.insert(pos, incoming);
            }
            Side::Sell => {
                // Try to match with the highest bid
                if let Some(best_bid) = self.bids.front_mut() {
                    if incoming.price <= best_bid.price {
                        let fill_qty = std::cmp::min(incoming.qty, best_bid.qty);
                        let report = TradeReport {
                            buy_order_id: best_bid.order_id,
                            sell_order_id: incoming.order_id,
                            price: best_bid.price,
                            qty: fill_qty,
                            latency_ns: start_time.elapsed().as_nanos(),
                        };

                        best_bid.qty -= fill_qty;
                        if best_bid.qty == 0 {
                            self.bids.pop_front();
                        }
                        return Some(report);
                    }
                }
                // No match, insert into asks queue (sorted ascending)
                let pos = self.asks.binary_search_by(|probe| probe.price.cmp(&incoming.price))
                    .unwrap_or_else(|e| e);
                self.asks.insert(pos, incoming);
            }
        }
        None
    }
}

// =====================================================================
// 3. PIPELINE STAGES (Isolated Thread Logic)
// =====================================================================

// Stage 1: Pre-Trade Risk Check (Executed on thread 2)
fn run_risk_engine(rx_gateway: std::sync::mpsc::Receiver<Order>, tx_matching: Sender<Order>) {
    let price_ceiling = 1_000_000; // Fat-finger threshold (e.g., $10,000.00)

    for order in rx_gateway {
        // Fat-finger protection check
        if order.price < price_ceiling {
            // Forward safely to matching engine
            if tx_matching.send(order).is_err() { break; }
        } else {
            println!("[RISK REJECT] Order {} rejected. Price {} exceeds limit.", order.order_id, order.price);
        }
    }
}

// Stage 2: Matching Engine Executor (Executed on thread 3)
fn run_matching_engine(rx_risk: std::sync::mpsc::Receiver<Order>) {
    let mut engine = MatchingEngine::new(10_000);
    println!("[ENGINE] Matching engine initialized and spinning...");

    for order in rx_risk {
        if let Some(trade) = engine.process_order(order) {
            println!(
                "[TRADE CONCLUDED] Buy ID: {}, Sell ID: {}, Qty: {}, Price: {} | Engine Latency: {} ns",
                trade.buy_order_id, trade.sell_order_id, trade.qty, trade.price, trade.latency_ns
            );
        }
    }
}

// =====================================================================
// 4. MAIN ORCHESTRATION & SIMULATOR
// =====================================================================
fn main() {
    println!("Initializing Low-Latency Trading Platform...");

    // Set up our low-latency communication channels
    // Note: In production, swap std::sync::mpsc with lock-free ring buffers (like crossbeam-channel)
    let (tx_to_risk, rx_at_risk) = channel::<Order>();
    let (tx_to_match, rx_at_match) = channel::<Order>();

    // Spawn Risk Thread
    thread::spawn(move || {
        run_risk_engine(rx_at_risk, tx_to_match);
    });

    // Spawn Matching Engine Thread
    thread::spawn(move || {
        run_matching_engine(rx_at_match);
    });

    // Gateway Simulation (Ingress)
    println!("[GATEWAY] Simulating incoming client orders...");

    // Send a Sell Order
    let sell_order = Order {
        order_id: 101,
        symbol_hash: 1001, // BTCUSD
        price: 9500,       // $95.00
        qty: 10,
        side: Side::Sell,
    };
    tx_to_risk.send(sell_order).unwrap();

    // Small delay to simulate real-world arrival spacing
    thread::sleep(Duration::from_millis(50));

    // Send a Matching Buy Order
    let buy_order = Order {
        order_id: 102,
        symbol_hash: 1001,
        price: 9600,       // $96.00 (Crosses the spread, should execute at $95.00)
        qty: 5,
        side: Side::Buy,
    };
    tx_to_risk.send(buy_order).unwrap();

    // Send a "Fat-Finger" rejected order to test risk scaling
    let fat_finger = Order {
