use std::collections::HashMap;
use std::time::{Duration, Instant};
use tokio::sync::{broadcast, mpsc};
use rand::Rng;

// --- Data Structures ---

#[derive(Debug, Clone)]
struct Tick {
    symbol: String,
    price: f64,
    volume: u64,
    timestamp: Instant,
}

#[derive(Debug, Clone)]
struct Aggregate {
    symbol: String,
    vwap: f64,         // Volume Weighted Average Price
    high: f64,
    low: f64,
    last_price: f64,
    total_volume: u64,
    update_count: u64,
}

// Internal state for tracking running metrics per symbol
struct RunningMetrics {
    total_volume: u64,
    sum_price_volume: f64, // (price * volume) accumulator for VWAP
    high: f64,
    low: f64,
    last_price: f64,
    update_count: u64,
}

impl RunningMetrics {
    fn new(price: f64, volume: u64) -> Self {
        Self {
            total_volume: volume,
            sum_price_volume: price * (volume as f64),
            high: price,
            low: price,
            last_price: price,
            update_count: 1,
        }
    }

    fn update(&mut self, price: f64, volume: u64) {
        self.total_volume += volume;
        self.sum_price_volume += price * (volume as f64);
        self.last_price = price;
        self.update_count += 1;

        if price > self.high {
            self.high = price;
        }
        if price < self.low {
            self.low = price;
        }
    }

    fn to_aggregate(&self, symbol: String) -> Aggregate {
        Aggregate {
            symbol,
            vwap: self.sum_price_volume / (self.total_volume as f64),
            high: self.high,
            low: self.low,
            last_price: self.last_price,
            total_volume: self.total_volume,
            update_count: self.update_count,
        }
    }
}

// --- Processor Logic ---

struct MarketDataProcessor {
    // Ingestion queue receiver
    tick_rx: mpsc::Receiver<Tick>,
    // Publisher channel to stream to subscribers
    broadcast_tx: broadcast::Sender<Aggregate>,
    // State storage (no Mutex required because this is owned by a single task)
    metrics_map: HashMap<String, RunningMetrics>,
}

impl MarketDataProcessor {
    fn new(tick_rx: mpsc::Receiver<Tick>, broadcast_tx: broadcast::Sender<Aggregate>) -> Self {
        Self {
            tick_rx,
            broadcast_tx,
            metrics_map: HashMap::new(),
        }
    }

    async fn run(mut self) {
        println!("[Processor] Starting real-time aggregate processor pipeline...");

        // High-throughput processing loop
        while let Some(tick) = self.tick_rx.recv().await {
            let symbol = tick.symbol.clone();

            // 1. Compute aggregates in-memory
            let metrics = self.metrics_map
                .entry(symbol.clone())
                .and_modify(|m| m.update(tick.price, tick.volume))
                .or_insert_with(|| RunningMetrics::new(tick.price, tick.volume));

            let aggregate = metrics.to_aggregate(symbol);

            // 2. Stream/Broadcast results to subscribers
            // If there are no active subscribers, send will return an error, which we ignore here.
            let _ = self.broadcast_tx.send(aggregate);
        }
    }
}

// --- Mock Data Generator (Ingestion Source) ---

async fn start_mock_feed(tx: mpsc::Sender<Tick>) {
    let symbols = vec!["AAPL".to_string(), "MSFT".to_string(), "TSLA".to_string(), "NVDA".to_string()];
    let mut rng = rand::thread_rng();

    // Initial prices
    let mut prices = HashMap::new();
    prices.insert("AAPL", 175.0);
    prices.insert("MSFT", 415.0);
    prices.insert("TSLA", 180.0);
    prices.insert("NVDA", 850.0);

    println!("[Feed] Launching mock market data feed...");

    loop {
        // Randomly select a symbol
        let sym_idx = rng.gen_range(0..symbols.len());
        let symbol = &symbols[sym_idx];

        // Simulating a random walk for prices
        let current_price = prices.get_mut(symbol.as_str()).unwrap();
        let change_percent = rng.gen_range(-0.002..0.002); // max 0.2% change
        *current_price *= 1.0 + change_percent;

        let tick = Tick {
            symbol: symbol.clone(),
            price: *current_price,
            volume: rng.gen_range(10..200),
            timestamp: Instant::now(),
        };

        if tx.send(tick).await.is_err() {
            break; // Receiver disconnected, stop the feed
        }

        // Simulate high frequency: tick every 5-50 milliseconds
        let delay = rng.gen_range(5..50);
        tokio::time::sleep(Duration::from_millis(delay)).await;
    }
}

// --- Subscriber Simulators ---

async fn start_subscriber(id: usize, mut rx: broadcast::Receiver<Aggregate>) {
    println!("[Subscriber {}] Connected to stream", id);
    while let Ok(agg) = rx.recv().await {
        // Filter: e.g., Subscriber 1 only cares about high-value updates on NVIDIA (NVDA)
        if id == 1 && agg.symbol == "NVDA" {
            println!(
                "[Subscriber 1 - NVDA Only] VWAP: {:.2} | High: {:.2} | Vol: {}",
                agg.vwap, agg.high, agg.total_volume
            );
        } 
        // Subscriber 2 monitors AAPL and prints periodically
        else if id == 2 && agg.symbol == "AAPL" && agg.update_count % 10 == 0 {
             println!(
                "[Subscriber 2 - AAPL Batch] Aggregate update #{} - Last Price: {:.2} | Min: {:.2}",
                agg.update_count, agg.last_price, agg.low
            );
        }
    }
}

// --- Main Orchestrator ---

#[tokio::main]
async fn main() {
    // 1. Ingestion Channel: mpsc (multi-producer, single-consumer)
    // A buffer of 1024 to handle spikes without blocking the ingest pipeline
    let (tick_tx, tick_rx) = mpsc::channel::<Tick>(1024);

    // 2. Broadcast Channel: fan-out stream to multiple concurrent subscribers
    let (broadcast_tx, _broadcast_rx) = broadcast::channel::<Aggregate>(2048);

    // 3. Spawn the Processor Task
    let processor_broadcast_tx = broadcast_tx.clone();
    let processor = MarketDataProcessor::new(tick_rx, processor_broadcast_tx);
    tokio::spawn(async move {
        processor.run().await;
    });

    // 4. Spawn Subscribers
    let sub1_rx = broadcast_tx.subscribe();
    tokio::spawn(async move {
        start_subscriber(1, sub1_rx).await;
    });

    let sub2_rx = broadcast_tx.subscribe();
    tokio::spawn(async move {
        start_subscriber(2, sub2_rx).await;
    });

    // 5. Spawn Mock Data Feed
    let feed_task = tokio::spawn(async move {
        start_mock_feed(tick_tx).await;
    });

    // Run simulator for 10 seconds, then exit
    tokio::time::sleep(Duration::from_secs(10)).await;
    println!("\n[Main] Execution finished.");
    feed_task.abort();
}
```

### Why this design excels at low latency:

1. **Lock-Free State Manipulation:** The `MarketDataProcessor` owns its `HashMap` state. It doesn't require complex mutexes or read-write locks (`RwLock`) to update. Because there is only **one writer** to the aggregates, concurrency overhead is effectively zero.
2. **Backpressure Handling:** Using bounded `tokio::sync::mpsc` (1024) and `tokio::sync::broadcast` (2048) buffers prevents memory runaways if subscribers lag behind.
3. **Asynchronous I/O Execution:** High-speed event scheduling is managed by the multithreaded `Tokio` runtime, ensuring that heavy I/O (like networking, if added) doesn't block critical computation paths.

