struct SymbolTracker {
    cumulative_volume_price: f64, // sum(price * volume)
    total_volume: f64,
    min_price: f64,
    max_price: f64,
    last_price: f64,
}

impl SymbolTracker {
    fn new(first_trade: &Trade) -> Self {
        Self {
            cumulative_volume_price: first_trade.price * first_trade.volume,
            total_volume: first_trade.volume,
            min_price: first_trade.price,
            max_price: first_trade.price,
            last_price: first_trade.price,
        }
    }

    /// Updates state with a new trade and returns the updated aggregate.
    fn update(&mut self, trade: &Trade) -> PriceAggregate {
        self.cumulative_volume_price += trade.price * trade.volume;
        self.total_volume += trade.volume;
        self.last_price = trade.price;

        if trade.price < self.min_price {
            self.min_price = trade.price;
        }
        if trade.price > self.max_price {
            self.max_price = trade.price;
        }

        let vwap = self.cumulative_volume_price / self.total_volume;

        PriceAggregate {
            symbol: trade.symbol.clone(),
            vwap,
            min_price: self.min_price,
            max_price: self.max_price,
            last_price: self.last_price,
            total_volume: self.total_volume,
            updated_at_ms: trade.timestamp_ms,
        }
    }
}

// --- Processor Logic ---

struct MarketDataProcessor {
    trade_rx: mpsc::Receiver<Trade>,
    broadcaster: broadcast::Sender<PriceAggregate>,
    trackers: HashMap<String, SymbolTracker>,
}

impl MarketDataProcessor {
    fn new(trade_rx: mpsc::Receiver<Trade>, broadcaster: broadcast::Sender<PriceAggregate>) -> Self {
        Self {
            trade_rx,
            broadcaster,
            trackers: HashMap::new(),
        }
    }

    async fn run(mut self) {
        // Read trades from the ingestion channel as fast as they arrive
        while let Some(trade) = self.trade_rx.recv().await {
            let aggregate = match self.trackers.get_mut(&trade.symbol) {
                Some(tracker) => tracker.update(&trade),
                None => {
                    let tracker = SymbolTracker::new(&trade);
                    let agg = PriceAggregate {
                        symbol: trade.symbol.clone(),
                        vwap: trade.price,
                        min_price: trade.price,
                        max_price: trade.price,
                        last_price: trade.price,
                        total_volume: trade.volume,
                        updated_at_ms: trade.timestamp_ms,
                    };
                    self.trackers.insert(trade.symbol.clone(), tracker);
                    agg
                }
            };

            // Stream the update out to all active subscribers.
            // If there are no subscribers, this is a no-op.
            let _ = self.broadcaster.send(aggregate);
        }
    }
}

// --- Simulations for Ingestion and Subscriptions ---

#[tokio::main]
