    pub timestamp_ms: u64,
}

#[derive(Debug, Clone)]
pub struct PriceAggregate {
    pub symbol: String,
    pub high: f64,
    pub low: f64,
    pub last_price: f64,
    pub total_volume: f64,
    pub vwap: f64, // Volume Weighted Average Price
    pub cumulative_value: f64,
    pub update_count: u64,
}

impl PriceAggregate {
    fn new(symbol: String, price: f64, volume: f64) -> Self {
        Self {
            symbol,
            high: price,
            low: price,
            last_price: price,
            total_volume: volume,
            vwap: price,
            cumulative_value: price * volume,
            update_count: 1,
        }
    }

    // Pure function to update aggregate with a new trade
    fn update(&mut self, trade: &Trade) {
        self.last_price = trade.price;
        if trade.price > self.high {
            self.high = trade.price;
        }
        if trade.price < self.low {
            self.low = trade.price;
        }
        self.total_volume += trade.volume;
        self.cumulative_value += trade.price * trade.volume;
        self.vwap = self.cumulative_value / self.total_volume;
        self.update_count += 1;
    }
}

// --- Market Data Processor (Actor) ---

pub struct MarketDataProcessor {
    // Aggregated state stored in-memory for low latency
    aggregates: HashMap<String, PriceAggregate>,
    // Ingestion channel receiver
    trade_rx: mpsc::Receiver<Trade>,
    // Broadcast channels per symbol to stream results to subscribers
    subscribers: HashMap<String, broadcast::Sender<PriceAggregate>>,
}

impl MarketDataProcessor {
    pub fn new(trade_rx: mpsc::Receiver<Trade>) -> Self {
        Self {
            aggregates: HashMap::new(),
            trade_rx,
            subscribers: HashMap::new(),
        }
    }

    // Allows dynamic subscription setup
    pub fn subscribe(&mut self, symbol: &str) -> broadcast::Receiver<PriceAggregate> {
        let sender = self.subscribers.entry(symbol.to_string()).or_insert_with(|| {
            let (tx, _) = broadcast::channel(1024); // Buffer size of 1024 updates
            tx
        });
        sender.subscribe()
    }

    // Core event loop processing trades
    pub async fn run(mut self) {
        println!("[Processor] Market Data Processor started.");
        while let Some(trade) = self.trade_rx.recv().await {
            // 1. Compute aggregate
            let agg = self
                .aggregates
                .entry(trade.symbol.clone())
                .and_modify(|existing| existing.update(&trade))
                .or_insert_with(|| PriceAggregate::new(trade.symbol.clone(), trade.price, trade.volume));

            // 2. Stream/Broadcast updated aggregate to subscribers if any exist
            if let Some(sender) = self.subscribers.get(&trade.symbol) {
                // If there are no active receivers, send returns an error which we can ignore
                let _ = sender.send(agg.clone());
            }
        }
    }
}

