use std::collections::HashMap;
use std::time::Duration;
use tokio::sync::{broadcast, mpsc};
use rand::Rng;

// --- Data Structures ---

/// Represents an incoming raw market data tick.
#[derive(Debug, Clone)]
struct Tick {
    symbol: String,
    price: f64,
    volume: f64,
    timestamp: u64,
}

/// Represents the computed aggregate metrics broadcasted to subscribers.
#[derive(Debug, Clone)]
struct Aggregate {
    symbol: String,
    last_price: f64,
    min_price: f64,
    max_price: f64,
    total_volume: f64,
    vwap: f64, // Volume Weighted Average Price
}

/// Internal state kept per ticker symbol to compute running aggregates.
struct SymbolState {
    min_price: f64,
    max_price: f64,
    total_volume: f64,
    cumulative_value: f64, // sum(price * volume)
    last_price: f64,
}

impl SymbolState {
    fn new(first_price: f64, first_volume: f64) -> Self {
        Self {
            min_price: first_price,
            max_price: first_price,
            total_volume: first_volume,
            cumulative_value: first_price * first_volume,
            last_price: first_price,
        }
    }

    fn update(&mut self, price: f64, volume: f64) {
        self.last_price = price;
        if price < self.min_price { self.min_price = price; }
        if price > self.max_price { self.max_price = price; }
        self.total_volume += volume;
        self.cumulative_value += price * volume;
    }

    fn vwap(&self) -> f64 {
        if self.total_volume == 0.0 {
            0.0
        } else {
            self.cumulative_value / self.total_volume
        }
    }
}

// --- Processor Engine ---

struct MarketDataProcessor {
    // Ingests raw ticks from data feeds
    tick_receiver: mpsc::Receiver<Tick>,
    // Broadcasts calculated aggregates to all connected subscribers
    broadcaster: broadcast::Sender<Aggregate>,
    // In-memory state of the market, isolated to this actor task (no Mutex required!)
    state: HashMap<String, SymbolState>,
}

impl MarketDataProcessor {
    fn new(tick_receiver: mpsc::Receiver<Tick>, broadcaster: broadcast::Sender<Aggregate>) -> Self {
        Self {
            tick_receiver,
            broadcaster,
            state: HashMap::new(),
        }
    }

    /// Run the event loop. This is the single-threaded "hot path" for updates.
    async fn run(mut self) {
        println!("[Processor] Market Data Processor started.");

        // Read raw ticks as they arrive
        while let Some(tick) = self.tick_receiver.recv().await {
            let symbol = tick.symbol.clone();

            // Update running aggregates or insert new state if symbol is new
            let state_entry = self.state.entry(symbol.clone())
                .and_modify(|s| s.update(tick.price, tick.volume))
                .or_insert_with(|| SymbolState::new(tick.price, tick.volume));

            let aggregate = Aggregate {
                symbol,
                last_price: state_entry.last_price,
                min_price: state_entry.min_price,
                max_price: state_entry.max_price,
                total_volume: state_entry.total_volume,
                vwap: state_entry.vwap(),
            };

            // Non-blocking broadcast to all active subscribers.
            // If there are no subscribers, this returns an error which we gracefully ignore.
            let _ = self.broadcaster.send(aggregate);
        }
    }
}

