use std::collections::HashMap;
use std::sync::Arc;
use std::time::Duration;
use tokio::sync::{broadcast, mpsc};
use tokio::time::sleep;

// Represents an incoming raw market trade
#[derive(Debug, Clone)]
pub struct Trade {
    pub symbol: String,
    pub price: f64,
    pub quantity: f64,
    pub timestamp_ms: u128,
}

// Represents computed real-time metrics streamed to subscribers
#[derive(Debug, Clone)]
pub struct PriceAggregate {
    pub symbol: String,
    pub last_price: f64,
    pub total_volume: f64,
    pub vwap: f64, // Volume Weighted Average Price
    pub trade_count: u64,
}

/// The stateful processor that aggregates raw tick data
struct MarketDataProcessor {
    rx_trades: mpsc::Receiver<Trade>,
    tx_subscribers: broadcast::Sender<PriceAggregate>,
    // In-memory state tracking for aggregation metrics
    aggregates: HashMap<String, AggregateState>,
}

struct AggregateState {
    last_price: f64,
    total_volume: f64,
    cumulative_pv: f64, // Sum of (Price * Quantity) for VWAP
    trade_count: u64,
}

impl MarketDataProcessor {
    pub fn new(
        rx_trades: mpsc::Receiver<Trade>,
        tx_subscribers: broadcast::Sender<PriceAggregate>,
    ) -> Self {
        Self {
            rx_trades,
            tx_subscribers,
            aggregates: HashMap::new(),
        }
    }

    /// Event loop that processes trade updates sequentially (lock-free execution)
    pub async fn run(mut self) {
        println!("[Processor] Aggregation engine started.");

        while let Some(trade) = self.rx_trades.recv().await {
            // Retrieve or initialize aggregation state for this ticker symbol
            let state = self.aggregates.entry(trade.symbol.clone()).or_insert(AggregateState {
                last_price: 0.0,
                total_volume: 0.0,
                cumulative_pv: 0.0,
                trade_count: 0,
            });

            // 1. Update running aggregates
            state.last_price = trade.price;
            state.total_volume += trade.quantity;
            state.cumulative_pv += trade.price * trade.quantity;
            state.trade_count += 1;

            let vwap = state.cumulative_pv / state.total_volume;

            // 2. Build the output aggregate package
            let aggregate_update = PriceAggregate {
                symbol: trade.symbol,
                last_price: state.last_price,
                total_volume: state.total_volume,
                vwap,
                trade_count: state.trade_count,
            };

            // 3. Stream result to all active subscribers.
            // If there are no subscribers, this will return an error which we can safely ignore.
            let _ = self.tx_subscribers.send(aggregate_update);
        }
    }
}

