// --- 1. Data Structures ---

/// Represents an incoming raw trade event.
#[derive(Debug, Clone)]
pub struct Trade {
    pub symbol: String,
    pub price: f64,
    pub quantity: f64,
    pub timestamp: Instant,
}

/// Represents the calculated aggregate state for a symbol.
#[derive(Debug, Clone)]
pub struct PriceAggregate {
    pub symbol: String,
    pub last_price: f64,
    pub vwap: f64,
    pub high: f64,
    pub low: f64,
    pub total_volume: f64,
    pub update_count: u64,
}

// Running state used to calculate aggregates on the fly.
struct RunningState {
    total_value: f64, // cumulative (price * quantity) for VWAP
    total_volume: f64,
    high: f64,
    low: f64,
    last_price: f64,
    update_count: u64,
}

// --- 2. Market Data Processor ---

pub struct MarketDataProcessor {
    // Receiver for raw trade ticks
    trade_rx: mpsc::Receiver<Trade>,
    // Broadcast channel to stream aggregates to subscribers
    broadcaster: broadcast::Sender<PriceAggregate>,
    // Internal state tracking aggregates per symbol
    state: HashMap<String, RunningState>,
}

impl MarketDataProcessor {
    pub fn new(
        trade_rx: mpsc::Receiver<Trade>,
        broadcaster: broadcast::Sender<PriceAggregate>,
    ) -> Self {
        Self {
            trade_rx,
            broadcaster,
            state: HashMap::new(),
        }
    }

    /// Starts the event loop to process trades and broadcast aggregates.
    pub async fn run(mut self) {
        println!("[Processor] Starting real-time processing loop...");

        while let Some(trade) = self.trade_rx.recv().await {
            let aggregate = self.process_trade(trade);

            // Broadcast the calculated aggregate to all active subscribers.
            // If there are no subscribers, this returns an error which we can safely ignore.
            let _ = self.broadcaster.send(aggregate);
        }
    }

    /// Updates internal running aggregates with the new trade.
    /// This is the "hot path" — kept as light and allocation-free as possible.
    fn process_trade(&mut self, trade: Trade) -> PriceAggregate {
        let state = self.state.entry(trade.symbol.clone()).or_insert_with(|| RunningState {
            total_value: 0.0,
            total_volume: 0.0,
            high: f64::MIN,
            low: f64::MAX,
            last_price: 0.0,
            update_count: 0,
        });

        // Update calculations
        state.total_value += trade.price * trade.quantity;
        state.total_volume += trade.quantity;
        state.last_price = trade.price;
        state.update_count += 1;

        if trade.price > state.high {
            state.high = trade.price;
        }
        if trade.price < state.low {
            state.low = trade.price;
        }

        let vwap = state.total_value / state.total_volume;

        PriceAggregate {
            symbol: trade.symbol,
            last_price: state.last_price,
            vwap,
            high: state.high,
            low: state.low,
            total_volume: state.total_volume,
            update_count: state.update_count,
        }
    }
}

