/// Represents an incoming raw trade tick from an exchange.
#[derive(Debug, Clone)]
pub struct Trade {
    pub symbol: String,
    pub price: f64,
    pub quantity: f64,
    pub timestamp_ms: u128,
}

/// Represents the real-time calculated metrics for a symbol.
#[derive(Debug, Clone)]
pub struct Aggregate {
    pub symbol: String,
    pub last_price: f64,
    pub high: f64,
    pub low: f64,
    pub total_volume: f64,
    pub vwap: f64, // Volume Weighted Average Price
    pub update_count: u64,

    // Internal fields used to calculate VWAP iteratively
    cum_price_volume: f64, 
}

impl Aggregate {
    fn new(symbol: String, price: f64, quantity: f64) -> Self {
        let price_vol = price * quantity;
        Self {
            symbol,
            last_price: price,
            high: price,
            low: price,
            total_volume: quantity,
            vwap: price,
            cum_price_volume: price_vol,
            update_count: 1,
        }
    }

    /// Mutates the state with the new trade in O(1) time
    fn update(&mut self, price: f64, quantity: f64) {
        self.last_price = price;
        if price > self.high { self.high = price; }
        if price < self.low { self.low = price; }

        self.total_volume += quantity;
        self.cum_price_volume += price * quantity;

        if self.total_volume > 0.0 {
            self.vwap = self.cum_price_volume / self.total_volume;
        }
        self.update_count += 1;
    }
}

// ==========================================
// 2. ENGINE LOGIC
// ==========================================

pub struct MarketProcessor {
    // Receives raw trades
    trade_receiver: mpsc::Receiver<Trade>,
    // Broadcasts calculated aggregates to subscribers
    broadcaster: broadcast::Sender<Aggregate>,
    // Local in-memory state (no Mutex needed because this engine owns it)
    state: HashMap<String, Aggregate>,
}

impl MarketProcessor {
    pub fn new(
        trade_receiver: mpsc::Receiver<Trade>,
        broadcaster: broadcast::Sender<Aggregate>
    ) -> Self {
        Self {
            trade_receiver,
            broadcaster,
            state: HashMap::new(),
        }
    }

    /// Runs the event loop. Ingests raw trades, updates state, and broadcasts results.
    pub async fn run(mut self) {
        println!("[Engine] Starting Market Data Processor loop...");
        while let Some(trade) = self.trade_receiver.recv().await {
            let symbol = trade.symbol.clone();

            // O(1) Lookup and Update
            let aggregate = self.state
                .entry(symbol.clone())
                .and_modify(|agg| agg.update(trade.price, trade.quantity))
                .or_insert_with(|| Aggregate::new(symbol, trade.price, trade.quantity));

            // Stream computed aggregate to subscribers. 
            // If there are no active subscribers, this returns an error which we can ignore.
            let _ = self.broadcaster.send(aggregate.clone());
        }
    }
}

