use std::collections::HashMap;
use std::time::Duration;
use rand::RUnlock;
use rand::Rng;
use tokio::sync::{broadcast, mpsc};
use tokio::time::sleep;

/// Represents an incoming raw trade tick from an exchange.
#[derive(Debug, Clone)]
struct Trade {
    symbol: String,
    price: f64,
    quantity: f64,
}

/// Represents the calculated real-time price aggregate sent to subscribers.
#[derive(Debug, Clone)]
struct PriceAggregate {
    symbol: String,
    vwap: f64,
    total_volume: f64,
    last_price: f64,
}

/// Holds the running cumulative metrics to calculate VWAP: (Σ(Price * Quantity) / ΣQuantity)
struct RunningMetrics {
    cumulative_notional: f64, // Σ(Price * Quantity)
    cumulative_volume: f64,   // ΣQuantity
    last_price: f64,
}

/// The Actor responsible for processing trades and maintaining state.
/// By keeping state inside this struct and running it on a single task,
/// we eliminate the need for Mutex locks on the hot path.
struct MarketDataProcessor {
    trade_rx: mpsc::Receiver<Trade>,
    agg_tx: broadcast::Sender<PriceAggregate>,
    state: HashMap<String, RunningMetrics>,
}

impl MarketDataProcessor {
    fn new(trade_rx: mpsc::Receiver<Trade>, agg_tx: broadcast::Sender<PriceAggregate>) -> Self {
        Self {
            trade_rx,
            agg_tx,
            state: HashMap::with_capacity(1000), // Pre-allocate to prevent mid-run reallocations
        }
    }

    /// Starts the event loop to process incoming trades.
    async fn run(mut self) {
        while let Some(trade) = self.trade_rx.recv().await {
            // Retrieve or initialize state for the symbol in-place
            let metrics = self.state.entry(trade.symbol.clone()).or_insert(RunningMetrics {
                cumulative_notional: 0.0,
                cumulative_volume: 0.0,
                last_price: 0.0,
            });

            // Update cumulative aggregates
            metrics.cumulative_notional += trade.price * trade.quantity;
            metrics.cumulative_volume += trade.quantity;
            metrics.last_price = trade.price;

            // Calculate current VWAP
            let vwap = metrics.cumulative_notional / metrics.cumulative_volume;

            let aggregate = PriceAggregate {
                symbol: trade.symbol,
                vwap,
                total_volume: metrics.cumulative_volume,
                last_price: metrics.last_price,
            };

            // Broadcast the calculated aggregate to all active subscribers.
            // If there are no subscribers, we ignore the SendError.
            let _ = self.agg_tx.send(aggregate);
        }
    }
}

