use std::collections::HashMap;
use std::sync::Arc;
use std::time::{Duration, Instant};
use tokio::sync::{broadcast, mpsc};
use rand::Rng;

/// Represents an incoming raw trade tick from an exchange.
#[derive(Debug, Clone)]
pub struct Tick {
    pub symbol: String,
    pub price: f64,
    pub volume: f64,
    pub timestamp: Instant,
}

/// Represents the computed real-time metrics broadcasted to subscribers.
#[derive(Debug, Clone)]
pub struct Aggregate {
    pub symbol: String,
    pub vwap: f64,
    pub total_volume: f64,
    pub high: f64,
    pub low: f64,
    pub update_count: u64,
}

/// Internal tracker for cumulative calculation states.
struct Accumulator {
    total_volume: f64,
    sum_price_volume: f64, // Sum of (Price * Volume) for VWAP
    high: f64,
    low: f64,
    count: u64,
}

impl Accumulator {
    fn new(price: f64, volume: f64) -> Self {
        Self {
            total_volume: volume,
            sum_price_volume: price * volume,
            high: price,
            low: price,
            count: 1,
        }
    }

    fn update(&mut self, price: f64, volume: f64) {
        self.total_volume += volume;
        self.sum_price_volume += price * volume;
        if price > self.high { self.high = price; }
        if price < self.low { self.low = price; }
        self.count += 1;
    }

    fn vwap(&self) -> f64 {
        if self.total_volume == 0.0 { 0.0 } else { self.sum_price_volume / self.total_volume }
    }
}

/// Core Market Data Processor engine
pub struct MarketProcessor {
    // Receiver for raw market ticks
    tick_rx: mpsc::Receiver<Tick>,
    // Broadcast channel transmitter to send computed metrics to all subscribers
    broadcaster: broadcast::Sender<Aggregate>,
    // In-memory state. No Mutex needed because this is owned solely by the processing loop thread!
    metrics_map: HashMap<String, Accumulator>,
}

impl MarketProcessor {
    pub fn new(tick_rx: mpsc::Receiver<Tick>, broadcaster: broadcast::Sender<Aggregate>) -> Self {
        Self {
            tick_rx,
            broadcaster,
            metrics_map: HashMap::new(),
        }
    }

    /// The main event loop. Processes ticks sequentially at ultra-high speed,
    /// updates metrics, and broadcasts the result.
    pub async fn run(mut self) {
        println!("[Processor] Core aggregator loop started.");

        while let Some(tick) = self.tick_rx.recv().await {
            let symbol = tick.symbol.clone();

            // 1. Update Aggregate State
            let entry = self.metrics_map
                .entry(symbol.clone())
                .and_modify(|acc| acc.update(tick.price, tick.volume))
                .or_insert_with(|| Accumulator::new(tick.price, tick.volume));

            // 2. Build the Aggregate payload
            let aggregate = Aggregate {
                symbol,
                vwap: entry.vwap(),
                total_volume: entry.total_volume,
                high: entry.high,
                low: entry.low,
                update_count: entry.count,
            };

            // 3. Broadcast to all active subscribers. 
            // If there are no subscribers, this will return an error which we can safely ignore.
            let _ = self.broadcaster.send(aggregate);
        }
    }
}

