```go
package main

import (
	"bufio"
	"context"
	"encoding/json"
	"fmt"
	"math/rand"
	"net"
	"os"
	"os/signal"
	"syscall"
	"time"
)

// Trade represents incoming raw market data
type Trade struct {
	Symbol    string    `json:"symbol"`
	Price     float64   `json:"price"`
	Quantity  float64   `json:"qty"`
	Timestamp time.Time `json:"ts"`
}

// Aggregate represents computed real-time metrics (VWAP & Volume)
type Aggregate struct {
	Symbol      string    `json:"symbol"`
	VWAP        float64   `json:"vwap"`
	Volume      float64   `json:"volume"`
	LastPrice   float64   `json:"last_price"`
	LastUpdated time.Time `json:"last_updated"`
}

// Engine manages the state, processes trades, and handles subscribers
type Engine struct {
	tradesCh    chan Trade
	register    chan chan Aggregate
	deregister  chan chan Aggregate
	subscribers map[chan Aggregate]bool

	// Internal state (aggregates)
	sumPriceQty map[string]float64 // Sum of (Price * Qty) for VWAP
	totalVolume map[string]float64 // Total Volume
	lastPrice   map[string]float64 // Last traded price
}

func NewEngine() *Engine {
	return &Engine{
		tradesCh:    make(chan Trade, 10000),
		register:    make(chan chan Aggregate),
		deregister:  make(chan chan Aggregate),
		subscribers: make(map[chan Aggregate]bool),
		sumPriceQty: make(map[string]float64),
		totalVolume: make(map[string]float64),
		lastPrice:   make(map[string]float64),
	}
}

// Start the core processing loop (Single-Threaded state modifier for safety)
func (e *Engine) Start(ctx context.Context) {
	fmt.Println("Market Data Engine started...")
	for {
		select {
		case trade := <-e.tradesCh:
			// 1. Update state
			e.sumPriceQty[trade.Symbol] += trade.Price * trade.Quantity
			e.totalVolume[trade.Symbol] += trade.Quantity
			e.lastPrice[trade.Symbol] = trade.Price

			// 2. Compute VWAP (Volume Weighted Average Price)
			vwap := e.sumPriceQty[trade.Symbol] / e.totalVolume[trade.Symbol]

			agg := Aggregate{
				Symbol:      trade.Symbol,
				VWAP:        vwap,
				Volume:      e.totalVolume[trade.Symbol],
				LastPrice:   trade.Price,
				LastUpdated: trade.Timestamp,
			}

			// 3. Broadcast to subscribers (non-blocking)
			for sub := range e.subscribers {
				select {
				case sub <- agg:
				default:
					// Subscriber buffer full; skip to prevent blocking the engine
				}
			}

		case sub := <-e.register:
			e.subscribers[sub] = true
			fmt.Println("New subscriber connected.")

		case sub := <-e.deregister:
			delete(e.subscribers, sub)
			close(sub)
			fmt.Println("Subscriber disconnected.")

		case <-ctx.Done():
			fmt.Println("Shutting down engine...")
			return
		}
	}
}

// StartTCPServer accepts connections from subscribers
func (e *Engine) StartTCPServer(addr string, ctx context.Context) {
	listener, err := net.Listen("tcp", addr)
	if err != nil {
		fmt.Printf("Failed to bind to %s: %v\n", addr, err)
		return
	}
	defer listener.Close()
	fmt.Printf("Streaming server listening on TCP %s\n", addr)

	go func() {
		<-ctx.Done()
		listener.Close()
	}()

	for {
		conn, err := listener.Accept()
		if err != nil {
			select {
			case <-ctx.Done():
				return
			default:
				fmt.Printf("Accept error: %v\n", err)
				continue
			}
		}
		go e.handleSubscriber(conn, ctx)
	}
}

func (e *Engine) handleSubscriber(conn net.Conn, ctx context.Context) {
	defer conn.Close()

	// Create a buffered channel for this specific subscriber
	subCh := make(chan Aggregate, 100)
	e.register <- subCh

	defer func() {
		e.deregister <- subCh
	}()

	writer := bufio.NewWriter(conn)

	for {
		select {
		case agg, ok := <-subCh:
			if !ok {
				return
			}
			// Serialize aggregate to JSON and stream to connection
			data, err := json.Marshal(agg)
			if err != nil {
				return
			}
			_, err = writer.Write(append(data, '\n'))
			if err != nil {
				return // Client disconnected
			}
			writer.Flush()

		case <-ctx.Done():
			return
		}
	}
}

// GenerateMockTrades simulates an exchange feed (e.g., NASDAQ UDP multicast)
func (e *Engine) GenerateMockTrades(ctx context.Context) {
	symbols := []string{"AAPL", "MSFT", "GOOG", "TSLA"}
	prices := map[string]float64{"AAPL": 175.0, "MSFT": 420.0, "GOOG": 150.0, "TSLA": 180.0}

	ticker := time.NewTicker(50 * time.Millisecond) // Generate a trade every 50ms
	defer ticker.Stop()

	for {
		select {
		case <-ticker.C:
			sym := symbols[rand.Intn(len(symbols))]
			// Simulate a slight price walk
			prices[sym] += (rand.Float64() - 0.5) * 0.5 

			trade := Trade{
				Symbol:    sym,
				Price:     prices[sym],
				Quantity:  float64(rand.Intn(100) + 1),
				Timestamp: time.Now(),
			}
			e.tradesCh <- trade
		case <-ctx.Done():
			return
		}
	}
}

func main() {
	ctx, cancel := context.WithCancel(context.Background())
	engine := NewEngine()

	// Start Engine
	go engine.Start(ctx)

	// Start Mock Trade Generator
	go engine.GenerateMockTrades(ctx)

	// Start TCP Server for Streaming on Port 8080
	go engine.StartTCPServer(":8080", ctx)

	// Graceful shutdown on Ctrl+C
	sigCh := make(chan os.Signal, 1)
	signal.Notify(sigCh, syscall.SIGINT, syscall.SIGTERM)
	<-sigCh

	fmt.Println("Shutting down...")
	cancel()
	time.Sleep(500 * time.Millisecond) // Give goroutines time to exit
}
