```go
package main

import (
	"encoding/json"
	"fmt"
	"math/rand"
	"net/http"
	"sync"
	"time"
)

// Trade represents the incoming raw market data tick.
type Trade struct {
	Symbol    string    `json:"symbol"`
	Price     float64   `json:"price"`
	Size      int64     `json:"size"`
	Timestamp time.Time `json:"timestamp"`
}

// Aggregate represents the computed real-time metrics.
type Aggregate struct {
	Symbol      string  `json:"symbol"`
	MinPrice    float64 `json:"min_price"`
	MaxPrice    float64 `json:"max_price"`
	TotalVolume int64   `json:"total_volume"`
	VWAP        float64 `json:"vwap"` // Volume Weighted Average Price
}

// Aggregator retains the state for running calculations.
type Aggregator struct {
	mu          sync.Mutex
	sumPriceVol float64 // sum(price * size)
	totalVolume int64   // sum(size)
	minPrice    float64
	maxPrice    float64
}

// Update incorporates a new trade and returns the updated Aggregate.
func (a *Aggregator) Update(t Trade) Aggregate {
	a.mu.Lock()
	defer a.mu.Unlock()

	if a.totalVolume == 0 {
		a.minPrice = t.Price
		a.maxPrice = t.Price
	} else {
		if t.Price < a.minPrice {
			a.minPrice = t.Price
		}
		if t.Price > a.maxPrice {
			a.maxPrice = t.Price
		}
	}

	a.totalVolume += t.Size
	a.sumPriceVol += t.Price * float64(t.Size)

	return Aggregate{
		Symbol:      t.Symbol,
		MinPrice:    a.minPrice,
		MaxPrice:    a.maxPrice,
		TotalVolume: a.totalVolume,
		VWAP:        a.sumPriceVol / float64(a.totalVolume),
	}
}

// Broker implements a Thread-Safe Pub/Sub pattern for streaming.
type Broker struct {
	subscribers map[chan Aggregate]bool
	subscribe   chan chan Aggregate
	unsubscribe chan chan Aggregate
	publish     chan Aggregate
}

func NewBroker() *Broker {
	return &Broker{
		subscribers: make(map[chan Aggregate]bool),
		subscribe:   make(chan chan Aggregate),
		unsubscribe: make(chan chan Aggregate),
		publish:     make(chan Aggregate),
	}
}

func (b *Broker) Start() {
	for {
		select {
		case ch := <-b.subscribe:
			b.subscribers[ch] = true
		case ch := <-b.unsubscribe:
			delete(b.subscribers, ch)
			close(ch)
		case msg := <-b.publish:
			for ch := range b.subscribers {
				// Non-blocking send to prevent a slow consumer from blocking the pipeline
				select {
				case ch <- msg:
				default:
				}
			}
		}
	}
}

func main() {
	// 1. Initialize Communication Pipelines
	tradeChan := make(chan Trade, 1000)
	broker := NewBroker()
	go broker.Start()

	// Keep track of aggregation state per symbol
	stateStore := make(map[string]*Aggregator)
	var stateMutex sync.Mutex

	// 2. Start the Real-Time Aggregator Engine
	go func() {
		for trade := range tradeChan {
			stateMutex.Lock()
			agg, exists := stateStore[trade.Symbol]
			if !exists {
				agg = &Aggregator{}
				stateStore[trade.Symbol] = agg
			}
			stateMutex.Unlock()

			// Compute new metrics and publish to broker
			updatedMetrics := agg.Update(trade)
			broker.publish <- updatedMetrics
		}
	}()

	// 3. Start Mock Market Feed Handler (Ingests ticks every 100ms)
	go func() {
		symbols := []string{"AAPL", "MSFT", "TSLA"}
		prices := map[string]float64{"AAPL": 175.0, "MSFT": 420.0, "TSLA": 180.0}
		r := rand.New(rand.NewSource(time.Now().UnixNano()))

		for {
			time.Sleep(100 * time.Millisecond)
			sym := symbols[r.Intn(len(symbols))]

			// Simulate a slight price fluctuation (-0.50 to +0.50)
			change := (r.Float64() - 0.5) * 1.0
			prices[sym] += change
			size := int64((r.Intn(10) + 1) * 10) // Size between 10 and 100 shares

			tradeChan <- Trade{
				Symbol:    sym,
				Price:     prices[sym],
				Size:      size,
				Timestamp: time.Now(),
			}
		}
	}()

	// 4. Set up the SSE HTTP Handler for streaming subscribers
	http.HandleFunc("/stream", func(w http.ResponseWriter, r *http.Request) {
		// Set headers for Server-Sent Events (SSE)
		w.Header().Set("Content-Type", "text/event-stream")
		w.Header().Set("Cache-Control", "no-cache")
		w.Header().Set("Connection", "keep-alive")
		w.Header().Set("Access-Control-Allow-Origin", "*")

		// Create unique client channel and register with broker
		clientChan := make(chan Aggregate, 10)
		broker.subscribe <- clientChan

		// De-register on connection termination
		defer func() {
			broker.unsubscribe <- clientChan
		}()

		// Keep connection alive & stream events
		for {
			select {
			case agg, ok := <-clientChan:
				if !ok {
					return
				}
				data, err := json.Marshal(agg)
				if err != nil {
					continue
				}
				// Format message according to SSE Spec (data: <payload>\n\n)
				fmt.Fprintf(w, "data: %s\n\n", data)
				w.(http.Flusher).Flush() // Push packet immediately to network socket
			case <-r.Context().Done():
				return // Client disconnected
			}
		}
	})

	fmt.Println("Market Data Server started on :8080")
	fmt.Println("Subscribe using: curl http://localhost:8080/stream")
	if err := http.ListenAndServe(":8080", nil); err != nil {
		panic(err)
	}
}
