```rust
use std::collections::HashMap;
use std::time::Duration;
use tokio::sync::{broadcast, mpsc};
use tokio::time::sleep;

// 1. Define Core Data Structures
#[derive(Debug, Clone)]
struct Tick {
    symbol: String,
    price: f64,
    volume: f64,
}

#[derive(Debug, Clone)]
struct Aggregate {
    symbol: String,
    vwap: f64,
    total_volume: f64,
    last_price: f64,
}

// Memory structure to keep track of cumulative values per asset
struct RunningState {
    total_volume: f64,
    cumulative_price_volume: f64,
}

// 2. Simulated Ingestion (Simulates exchange feeds pushing data)
async fn market_data_feed_simulator(tx: mpsc::Sender<Tick>) {
    let mut step = 0.0;
    loop {
        sleep(Duration::from_millis(150)).await; // New tick every 150ms
        step += 0.1;

        // Generate synthetic prices oscillating around a base
        let btc_tick = Tick {
            symbol: "BTC/USD".to_string(),
            price: 64000.0 + (step.sin() * 150.0),
            volume: 0.1 + (step.cos().abs() * 1.5),
        };

        let eth_tick = Tick {
            symbol: "ETH/USD".to_string(),
            price: 3400.0 + (step.cos() * 20.0),
            volume: 1.0 + (step.sin().abs() * 10.0),
        };

        let _ = tx.send(btc_tick).await;
        let _ = tx.send(eth_tick).await;
    }
}

// 3. Real-time Processor (Computes VWAP and broadcasts results)
async fn process_market_data(
    mut rx_ticks: mpsc::Receiver<Tick>,
    tx_aggs: broadcast::Sender<Aggregate>,
) {
    let mut state_map: HashMap<String, RunningState> = HashMap::new();

    while let Some(tick) = rx_ticks.recv().await {
        // Fetch or initialize running state for the asset symbol
        let state = state_map.entry(tick.symbol.clone()).or_insert(RunningState {
            total_volume: 0.0,
            cumulative_price_volume: 0.0,
        });

        // Compute VWAP: Sum(Price * Volume) / Sum(Volume)
        state.total_volume += tick.volume;
        state.cumulative_price_volume += tick.price * tick.volume;
        let vwap = state.cumulative_price_volume / state.total_volume;

        let agg = Aggregate {
            symbol: tick.symbol,
            vwap,
            total_volume: state.total_volume,
            last_price: tick.price,
        };

        // Stream aggregate results to all active subscribers
        // Errors (e.g. if there are zero subscribers) are ignored for this demo
        let _ = tx_aggs.send(agg);
    }
}

// 4. Subscriber Client (Simulates a frontend WebSocket or downstream service)
async fn spawn_subscriber(id: usize, mut rx_stream: broadcast::Receiver<Aggregate>) {
    println!("[Subscriber {}] Connected and listening...", id);
    while let Ok(agg) = rx_stream.recv().await {
        println!(
            "[Subscriber {}] Stream: {} | Price: ${:.2} | VWAP: ${:.2} | Agg Vol: {:.2}",
            id, agg.symbol, agg.last_price, agg.vwap, agg.total_volume
        );
    }
}

#[tokio::main]
async fn main() {
    println!("Starting Real-Time Market Data Processor...");

    // Create Channels
    // MPSC (Multi-Producer Single-Consumer) for ingesting raw ticks
    let (tx_inbound, rx_inbound) = mpsc::channel::<Tick>(1000);
    // Broadcast (Single-Producer Multi-Consumer) for streaming updates to subscribers
    let (tx_outbound, _rx_drain) = broadcast::channel::<Aggregate>(1000);

    // Spawn Ingestion Task
    tokio::spawn(market_data_feed_simulator(tx_inbound));

    // Spawn Aggregation Processing Task
    let tx_outbound_clone = tx_outbound.clone();
    tokio::spawn(process_market_data(rx_inbound, tx_outbound_clone));

    // Spawn Subscriber 1
    let rx_sub1 = tx_outbound.subscribe();
    tokio::spawn(spawn_subscriber(1, rx_sub1));

    // Spawn Subscriber 2 (Demonstrating pub/sub multiplexing)
    let rx_sub2 = tx_outbound.subscribe();
    tokio::spawn(spawn_subscriber(2, rx_sub2));

    // Keep main thread alive for 5 seconds of real-time logging
    sleep(Duration::from_secs(5)).await;
    println!("Stopping Market Data Processor.");
}
