```rust
use std::collections::HashMap;
use std::time::Duration;
use rand::Rng;
use tokio::sync::{broadcast, mpsc};
use tokio::time::sleep;

// --- 1. DATA STRUCTURES ---

/// Represents an incoming raw trade event from an exchange.
#[derive(Debug, Clone)]
struct Trade {
    symbol: String,
    price: f64,
    quantity: f64,
}

/// Represents the calculated price aggregates streamed to subscribers.
#[derive(Debug, Clone)]
struct PriceAggregate {
    symbol: String,
    vwap: f64,
    total_volume: f64,
    last_price: f64,
}

/// Internal state tracker for calculating running VWAP.
struct RunningVwap {
    total_volume: f64,
    cumulative_spent: f64,
}

// --- 2. INGESTION SIMULATOR ---

/// Simulates high-frequency market data feeds pushing trades into our pipeline.
async fn simulate_market_data(tx: mpsc::Sender<Trade>) {
    let mut rng = rand::thread_rng();
    let symbols = vec!["BTCUSD".to_string(), "ETHUSD".to_string(), "SOLUSD".to_string()];

    // Seed base prices
    let mut prices = HashMap::new();
    prices.insert("BTCUSD", 65000.0);
    prices.insert("ETHUSD", 3500.0);
    prices.insert("SOLUSD", 140.0);

    println!("[Ingest] Starting live market data feed...");
    loop {
        // Pick a random symbol
        let symbol = &symbols[rng.gen_range(0..symbols.len())];
        let base_price = prices.get_mut(symbol.as_str()).unwrap();

        // Walk the price randomly (simulating market tick)
        let price_change = rng.gen_range(-2.0..2.0);
        *base_price += price_change;

        let trade = Trade {
            symbol: symbol.clone(),
            price: *base_price,
            quantity: rng.gen_range(0.01..1.5),
        };

        // Send trade to the processor
        if tx.send(trade).await.is_err() {
            break; // Channel closed, shut down
        }

        // Simulate high-frequency arrival rate (approx. every 10 to 50 milliseconds)
        let sleep_ms = rng.gen_range(10..50);
        sleep(Duration::from_millis(sleep_ms)).await;
    }
}

// --- 3. AGGREGATION ENGINE ---

/// Processes raw trades, updates VWAP aggregates, and broadcasts results.
async fn process_market_data(
    mut rx: mpsc::Receiver<Trade>,
    broadcaster: broadcast::Sender<PriceAggregate>,
) {
    // Keep internal running metrics for each symbol
    let mut state_map: HashMap<String, RunningVwap> = HashMap::new();

    println!("[Engine] Aggregator initialized. Processing stream...");
    while let Some(trade) = rx.recv().await {
        // Retrieve or initialize the running VWAP tracking for this asset
        let tracker = state_map.entry(trade.symbol.clone()).or_insert(RunningVwap {
            total_volume: 0.0,
            cumulative_spent: 0.0,
        });

        // Update calculations
        tracker.total_volume += trade.quantity;
        tracker.cumulative_spent += trade.price * trade.quantity;
        let vwap = tracker.cumulative_spent / tracker.total_volume;

        // Construct the output aggregate update
        let aggregate = PriceAggregate {
            symbol: trade.symbol,
            vwap,
            total_volume: tracker.total_volume,
            last_price: trade.price,
        };

        // Broadcast to all active subscribers. 
        // If there are no subscribers, this is a safe no-op.
        let _ = broadcaster.send(aggregate);
    }
}

// --- 4. SUBSCRIBER CLIENTS ---

/// Simulates an downstream client consumer (e.g., UI WebSocket server or algorithmic trader)
async fn start_subscriber(id: usize, mut rx: broadcast::Receiver<PriceAggregate>) {
    println!("[Subscriber {}] Connected to stream.", id);
    while let Ok(aggregate) = rx.recv().await {
        println!(
            "  -> [Sub {}] Update: {:<6} | Last: ${:<8.2} | VWAP: ${:<8.2} | CumVol: {:.4}",
            id, aggregate.symbol, aggregate.last_price, aggregate.vwap, aggregate.total_volume
        );
    }
}

// --- 5. ORCHESTRATION ---

#[tokio::main]
async fn main() {
    // Pipeline setup:
    // 1. MPSC channel handles incoming trades (Buffer size 1000)
    let (trade_tx, trade_rx) = mpsc::channel::<Trade>(1000);

    // 2. Broadcast channel streams calculated aggregates to multi-subscribers
    let (broadcaster_tx, _) = broadcast::channel::<PriceAggregate>(16);

    // Spawn Ingestion Feed (Source)
    tokio::spawn(simulate_market_data(trade_tx));

    // Spawn Aggregation Engine (Processor)
    let agg_broadcaster = broadcaster_tx.clone();
    tokio::spawn(process_market_data(trade_rx, agg_broadcaster));

    // Spawn Sub 1 (Simulated subscriber client)
    let sub1_rx = broadcaster_tx.subscribe();
    tokio::spawn(start_subscriber(1, sub1_rx));

    // Spawn Sub 2 (Simulated subscriber client with a slight delay)
    sleep(Duration::from_secs(1)).await;
    let sub2_rx = broadcaster_tx.subscribe();
    tokio::spawn(start_subscriber(2, sub2_rx));

    // Let the demo run for 5 seconds, then gracefully exit
    sleep(Duration::from_secs(5)).await;
    println!("\n[System] Shutting down processor demo.");
}
