```go
package main

import (
	"encoding/json"
	"fmt"
	"math/rand"
	"net"
	"sync"
	"time"
)

// Trade represents incoming raw tick data.
type Trade struct {
	Symbol    string    `json:"symbol"`
	Price     float64   `json:"price"`
	Size      float64   `json:"size"`
	Timestamp time.Time `json:"timestamp"`
}

// Aggregate represents the computed metrics sent to subscribers.
type Aggregate struct {
	Symbol      string    `json:"symbol"`
	LastPrice   float64   `json:"last_price"`
	TotalVolume float64   `json:"total_volume"`
	VWAP        float64   `json:"vwap"`
	Timestamp   time.Time `json:"timestamp"`
}

// Client represents a connected subscriber.
type Client struct {
	conn net.Conn
	send chan []byte // Buffered queue for individual subscriber stream
}

// Processor manages the computation state and subscriber list.
type Processor struct {
	clients     map[*Client]bool
	register    chan *Client
	unregister  chan *Client
	trades      chan Trade
	states      map[string]*aggState
	mu          sync.RWMutex
}

type aggState struct {
	totalVolume float64
	totalValue  float64 // sum(Price * Size) for VWAP
}

func NewProcessor() *Processor {
	return &Processor{
		clients:    make(map[*Client]bool),
		register:   make(chan *Client),
		unregister: make(chan *Client),
		trades:     make(chan Trade, 1000),
		states:     make(map[string]*aggState),
	}
}

// Start processing trades and managing subscribers
func (p *Processor) Start() {
	for {
		select {
		case client := <-p.register:
			p.mu.Lock()
			p.clients[client] = true
			p.mu.Unlock()
			fmt.Printf("[SYSTEM] Subscriber connected: %s\n", client.conn.RemoteAddr())

		case client := <-p.unregister:
			p.mu.Lock()
			if _, ok := p.clients[client]; ok {
				delete(p.clients, client)
				close(client.send)
				fmt.Printf("[SYSTEM] Subscriber disconnected: %s\n", client.conn.RemoteAddr())
			}
			p.mu.Unlock()

		case trade := <-p.trades:
			// 1. Calculate Real-Time Aggregate (VWAP)
			state, exists := p.states[trade.Symbol]
			if !exists {
				state = &aggState{}
				p.states[trade.Symbol] = state
			}

			state.totalVolume += trade.Size
			state.totalValue += trade.Price * trade.Size

			agg := Aggregate{
				Symbol:      trade.Symbol,
				LastPrice:   trade.Price,
				TotalVolume: state.totalVolume,
				VWAP:        state.totalValue / state.totalVolume,
				Timestamp:   time.Now(),
			}

			// Serialize aggregate to JSON
			payload, _ := json.Marshal(agg)
			payload = append(payload, '\n')

			// 2. Stream/Broadcast to all active subscribers
			p.mu.RLock()
			for client := range p.clients {
				select {
				case client.send <- payload:
					// Data sent to subscriber buffer successfully
				default:
					// Slow-Client protection: Drop message if subscriber buffer is full
					fmt.Printf("[WARN] Dropping slow subscriber: %s\n", client.conn.RemoteAddr())
				}
			}
			p.mu.RUnlock()
		}
	}
}

// writePump pushes queued messages from the client's channel to their TCP connection
func (c *Client) writePump(p *Processor) {
	defer func() {
		p.unregister <- c
		c.conn.Close()
	}()
	for msg := range c.send {
		_, err := c.conn.Write(msg)
		if err != nil {
			return // Trigger disconnect on write failure
		}
	}
}

// generateSimulatedTrades mocks a live market data feed (e.g., Websocket from an exchange)
func generateSimulatedTrades(tradeChan chan<- Trade) {
	symbols := []string{"AAPL", "MSFT", "TSLA"}
	prices := map[string]float64{"AAPL": 180.0, "MSFT": 420.0, "TSLA": 175.0}
	r := rand.New(rand.NewSource(time.Now().UnixNano()))

	for {
		sym := symbols[r.Intn(len(symbols))]
		// Random price walk (+/- $0.50)
		prices[sym] += (r.Float64() - 0.5) * 1.0
		size := float64(r.Intn(100) + 1) // 1 to 100 shares

		tradeChan <- Trade{
			Symbol:    sym,
			Price:     prices[sym],
			Size:      size,
			Timestamp: time.Now(),
		}
		// Generate trade every 200 to 500 milliseconds
		time.Sleep(time.Duration(200+r.Intn(300)) * time.Millisecond)
	}
}

