#include <iostream>
#include <atomic>
#include <thread>
#include <vector>
#include <chrono>
#include <iomanip>
#include <array>
#include <numeric>
#include <limits>

// Optimization: Emit CPU hints during spin-wait loops to save power and improve performance
inline void cpu_relax() {
#if defined(__x86_64__) || defined(_M_X64)
    asm volatile("pause" ::: "memory");
#elif defined(__arm__) || defined(__aarch64__)
    asm volatile("yield" ::: "memory");
#endif
}

// Fixed-size message payload to eliminate dynamic memory allocation
struct alignas(64) Message {
    uint64_t id;
    uint32_t route_id;
    uint64_t timestamp_ns; // Ingest timestamp
    char payload[32];      // App-specific data
};

// Highly-optimized, lock-free SPSC Ring Buffer
template <typename T, size_t Capacity>
class LockFreeSPSCQueue {
    static_assert((Capacity & (Capacity - 1)) == 0, "Capacity must be a power of 2");
public:
    LockFreeSPSCQueue() : write_idx_(0), read_idx_(0), write_idx_cached_(0), read_idx_cached_(0) {}

    bool push(const T& item) {
        const size_t write_idx = write_idx_.load(std::memory_order_relaxed);
        const size_t read_idx = read_idx_cached_;

        if (write_idx - read_idx >= Capacity) {
            // Update cached read index from atomic to check if space freed up
            read_idx_cached_ = read_idx_.load(std::memory_order_acquire);
            if (write_idx - read_idx_cached_ >= Capacity) {
                return false; // Queue Full
            }
        }

        buffer_[write_idx & (Capacity - 1)] = item;
        write_idx_.store(write_idx + 1, std::memory_order_release);
        return true;
    }

    bool pop(T& item) {
        const size_t read_idx = read_idx_.load(std::memory_order_relaxed);
        const size_t write_idx = write_idx_cached_;

        if (read_idx == write_idx) {
            // Update cached write index from atomic to check for new elements
            write_idx_cached_ = write_idx_.load(std::memory_order_acquire);
            if (read_idx == write_idx_cached_) {
                return false; // Queue Empty
            }
        }

        item = buffer_[read_idx & (Capacity - 1)];
        read_idx_.store(read_idx + 1, std::memory_order_release);
        return true;
    }

private:
    // Align members to cache lines (64 bytes) to prevent "False Sharing" between CPU cores
    alignas(64) T buffer_[Capacity];
    alignas(64) std::atomic<size_t> write_idx_;
    alignas(64) size_t write_idx_cached_;
    alignas(64) std::atomic<size_t> read_idx_;
    alignas(64) size_t read_idx_cached_;
};

// Thread-safe, ultra-low-overhead Latency Tracker using a fixed-size nanosecond histogram
class LatencyTracker {
public:
    static constexpr size_t BUCKETS = 10000;    // Tracks up to 100,000 ns (100us) in 10ns steps
    static constexpr uint64_t STEP_NS = 10;     // 10ns resolution per bucket

    LatencyTracker() : count_(0), total_ns_(0), min_ns_(std::numeric_limits<uint64_t>::max()), max_ns_(0) {
        histogram_.fill(0);
        overflow_bucket_ = 0;
    }

    void record(uint64_t latency_ns) {
        count_.fetch_add(1, std::memory_order_relaxed);
        total_ns_.fetch_add(latency_ns, std::memory_order_relaxed);

        // Track min latency
        uint64_t current_min = min_ns_.load(std::memory_order_relaxed);
        while (latency_ns < current_min && !min_ns_.compare_exchange_weak(current_min, latency_ns, std::memory_order_relaxed));

        // Track max latency
        uint64_t current_max = max_ns_.load(std::memory_order_relaxed);
        while (latency_ns > current_max && !max_ns_.compare_exchange_weak(current_max, latency_ns, std::memory_order_relaxed));

        // Update histogram
        size_t bucket = latency_ns / STEP_NS;
        if (bucket < BUCKETS) {
            histogram_[bucket].fetch_add(1, std::memory_order_relaxed);
        } else {
            overflow_bucket_.fetch_add(1, std::memory_order_relaxed);
        }
    }

    void print_stats() {
        uint64_t total_count = count_.load(std::memory_order_relaxed);
        if (total_count == 0) return;

        uint64_t sum_ns = total_ns_.load(std::memory_order_relaxed);
        uint64_t min_v = min_ns_.load(std::memory_order_relaxed);
        uint64_t max_v = max_ns_.load(std::memory_order_relaxed);

        uint64_t p50_count = total_count * 0.50;
        uint64_t p90_count = total_count * 0.90;
        uint64_t p99_count = total_count * 0.99;
        uint64_t p999_count = total_count * 0.999;

        uint64_t accumulated = 0;
        uint64_t p50 = 0, p90 = 0, p99 = 0, p999 = 0;

        for (size_t i = 0; i < BUCKETS; ++i) {
            accumulated += histogram_[i].load(std::memory_order_relaxed);
            if (!p50 && accumulated >= p50_count) p50 = i * STEP_NS;
            if (!p90 && accumulated >= p90_count) p90 = i * STEP_NS;
            if (!p99 && accumulated >= p99_count) p99 = i * STEP_NS;
            if (!p999 && accumulated >= p999_count) { p999 = i * STEP_NS; break; }
        }

        std::cout << "  Average Latency: " << std::fixed << std::setprecision(2) << (double)sum_ns / total_count << " ns\n";
        std::cout << "  Min Latency:     " << min_v << " ns\n";
        std::cout << "  P50 Latency:     " << (p50 ? p50 : max_v) << " ns\n";
        std::cout << "  P90 Latency:     " << (p90 ? p90 : max_v) << " ns\n";
        std::cout << "  P99 Latency:     " << (p99 ? p99 : max_v) << " ns\n";
        std::cout << "  P99.9 Latency:   " << (p999 ? p999 : max_v) << " ns\n";
        std::cout << "  Max Latency:     " << max_v << " ns (overflowed hist: " << overflow_bucket_.load() << ")\n";
    }

private:
    std::atomic<uint64_t> count_;
    std::atomic<uint64_t> total_ns_;
    std::atomic<uint64_t> min_ns_;
    std::atomic<uint64_t> max_ns_;
    std::array<std::atomic<uint64_t>, BUCKETS> histogram_;
    std::atomic<uint64_t> overflow_bucket_;
};

// Application configurations
constexpr size_t QUEUE_CAPACITY = 65536; // Must be power of 2
constexpr size_t NUM_ROUTES = 4;
std::atomic<bool> running{true};

// Initialize queues
LockFreeSPSCQueue<Message, QUEUE_CAPACITY> ingest_queue;
std::vector<LockFreeSPSCQueue<Message, QUEUE_CAPACITY>> route_queues(NUM_ROUTES);
std::vector<LatencyTracker> latency_trackers(NUM_ROUTES);

// Ingest Thread: Simulates upstream networking packets arriving at millions of msgs/sec
void ingest_worker() {
    uint64_t id = 0;
    Message msg;
    msg.payload[0] = 'X'; // Dummy payload

    while (running.load(std::memory_order_relaxed)) {
        msg.id = ++id;
        msg.route_id = id % NUM_ROUTES;

        // Accurate timestamp capture using system monotonic clock
        msg.timestamp_ns = std::chrono::duration_cast<std::chrono::nanoseconds>(
            std::chrono::steady_clock::now().time_since_epoch()
        ).count();

        // Push to routing engine (Busy spin on backpressure)
        while (!ingest_queue.push(msg)) {
            cpu_relax();
        }
    }
}

// Router Thread: Distributes inbound messages to workers based on key
void router_worker() {
    Message msg;
    while (running.load(std::memory_order_relaxed)) {
        if (ingest_queue.pop(msg)) {
            // Forward message to its targeted downstream route
            while (!route_queues[msg.route_id].push(msg)) {
                cpu_relax();
            }
        } else {
            cpu_relax();
        }
    }
}

// Egress/Consumer Worker: Simulates outbound serialization and tracks latency
void egress_worker(size_t route_id) {
    Message msg;
    auto& tracker = latency_trackers[route_id];

    while (running.load(std::memory_order_relaxed)) {
        if (route_queues[route_id].pop(msg)) {
            uint64_t now = std::chrono::duration_cast<std::chrono::nanoseconds>(
                std::chrono::steady_clock::now().time_since_epoch()
            ).count();

            // Record latency
            if (now >= msg.timestamp_ns) {
                tracker.record(now - msg.timestamp_ns);
            }
        } else {
            cpu_relax();
        }
    }
}

int main() {
    std::cout << "Initializing 1 Ingest, 1 Router, and " << NUM_ROUTES << " Egress threads...\n";

    // Start Threads
    std::thread ingest_t(ingest_worker);
    std::thread router_t(router_worker);
    std::vector<std::thread> egress_threads;
    for (size_t i = 0; i < NUM_ROUTES; ++i) {
        egress_threads.emplace_back(egress_worker, i);
    }

    // Run benchmark for 5 seconds
    std::cout << "Routing active. Measuring throughput and latency profile...\n" << std::endl;
    std::this_thread::sleep_for(std::chrono::seconds(5));

    // Shutdown pipeline
    running.store(false, std::memory_order_seq_cst);

    // Wait for all threads to finish
    ingest_t.join();
    router_t.join();
    for (auto& t : egress_threads) {
         t.join();
    }

    // Gather global execution statistics
    uint64_t total_routed = 0;
    for (size_t i = 0; i < NUM_ROUTES; ++i) {
        std::cout << "--- Route " << i << " Stats ---" << std::endl;
        latency_trackers[i].print_stats();
        // Sum total counts
        // Accessing the internal private value can be bypassed by recording total messages
    }

    return 0;
}
