```rust
use hdrhistogram::Histogram;
use std::sync::Arc;
use std::time::{Duration, Instant};
use tokio::sync::mpsc::{self, Receiver, Sender};

// High-frequency messages must be copyable and stack-allocated 
// to avoid heap-allocation overhead.
#[derive(Clone, Copy)]
struct Message {
    id: u64,
    topic_id: usize,
    payload: [u8; 64], // Fixed-size payload
    timestamp: Instant, // Captured at ingestion for latency monitoring
}

// Metrics update sent from worker threads to the Monitor thread
struct ThreadMetrics {
    worker_id: usize,
    message_count: u64,
    latency_hist: Histogram<u64>, // Tracks latency in microseconds
}

struct Router {
    // Array index represents the topic ID. $O(1)$ lock-free routing.
    routes: Vec<Sender<Message>>,
}

impl Router {
    #[inline(always)]
    fn route(&self, msg: Message) {
        // In a real system, handle channel fullness (backpressure).
        // Here we use try_send for maximum speed; if the channel is full, we drop/block.
        if let Some(sender) = self.routes.get(msg.topic_id) {
            if let Err(e) = sender.try_send(msg) {
                // In production, route to a dead-letter queue or apply backpressure
                match e {
                    mpsc::error::TrySendError::Full(_) => {} // Queue full
                    mpsc::error::TrySendError::Closed(_) => {} // Channel closed
                }
            }
        }
    }
}

// Simulated Consumer/Worker Task
async fn subscriber_worker(
    worker_id: usize,
    mut rx: Receiver<Message>,
    metrics_tx: Sender<ThreadMetrics>,
) {
    // Record latency in microseconds with 3 significant figures of precision
    let mut hist = Histogram::<u64>::new_with_bounds(1, 10_000_000, 3).unwrap();
    let mut msg_count = 0u64;
    let mut last_flush = Instant::now();

    while let Some(msg) = rx.recv().await {
        msg_count += 1;

        // 1. Calculate latency with microsecond precision
        let elapsed = msg.timestamp.elapsed().as_micros() as u64;
        let _ = hist.record(elapsed);

        // 2. Simulate processing work (e.g., writing to a ring buffer)
        // std::hint::black_box(msg); 

        // 3. Batch metrics updates to the monitor thread once per second 
        // to keep the hot path entirely lock-free.
        if last_flush.elapsed() >= Duration::from_secs(1) {
            let metrics = ThreadMetrics {
                worker_id,
                message_count: msg_count,
                latency_hist: hist.clone(),
            };

            let _ = metrics_tx.try_send(metrics);

            // Reset local counters
            msg_count = 0;
            hist.clear();
            last_flush = Instant::now();
        }
    }
}

// Background Monitor Thread
async fn monitor_task(mut metrics_rx: Receiver<ThreadMetrics>, num_workers: usize) {
    let mut global_hist = Histogram::<u64>::new_with_bounds(1, 10_000_000, 3).unwrap();
    let mut worker_throughput = vec![0u64; num_workers];
    let mut last_report = Instant::now();

    println!("Starting latency and throughput monitor...");

    while let Some(metrics) = metrics_rx.recv().await {
        worker_throughput[metrics.worker_id] = metrics.message_count;
        let _ = global_hist.add(&metrics.latency_hist);

        // Print report once we have heard from our workers and 1 second has elapsed
        if last_report.elapsed() >= Duration::from_secs(1) {
            let total_throughput: u64 = worker_throughput.iter().sum();

            println!("--------------------------------------------------");
            println!("Throughput: {} msg/sec", total_throughput);
            println!("Latency Quantiles:");
            println!("  p50 (Median): {} µs", global_hist.value_at_quantile(0.50));
            println!("  p90         : {} µs", global_hist.value_at_quantile(0.90));
            println!("  p99         : {} µs", global_hist.value_at_quantile(0.99));
            println!("  p99.9       : {} µs", global_hist.value_at_quantile(0.999));
            println!("  Max         : {} µs", global_hist.max());
            println!("--------------------------------------------------");

            global_hist.clear();
            last_report = Instant::now();
        }
    }
}

#[tokio::main(flavor = "multi_thread", worker_threads = 8)]
async fn main() {
    const NUM_TOPICS: usize = 4;
    const QUEUE_CAPACITY: usize = 262_144; // Power of two for rapid ring-buffer indexing
    const NUM_PUBLISHERS: usize = 4;

    let (metrics_tx, metrics_rx) = mpsc::channel::<ThreadMetrics>(100);

    // 1. Spawning Subscribers/Workers
    let mut routes = Vec::new();
    for topic_id in 0..NUM_TOPICS {
        let (tx, rx) = mpsc::channel::<Message>(QUEUE_CAPACITY);
        routes.push(tx);

        let metrics_tx_clone = metrics_tx.clone();
        tokio::spawn(async move {
            subscriber_worker(topic_id, rx, metrics_tx_clone).await;
        });
    }

    let router = Arc::new(Router { routes });

    // 2. Spawning Monitor Thread
    tokio::spawn(async move {
        monitor_task(metrics_rx, NUM_TOPICS).await;
    });

    // 3. Spawning Publishers generating millions of messages
    let mut publishers = Vec::new();
    for pub_id in 0..NUM_PUBLISHERS {
        let router_clone = Arc::clone(&router);
        let handle = tokio::spawn(async move {
            let mut msg_id = 0u64;
            let payload = [42u8; 64]; // Pre-allocated payload buffer

            loop {
                let msg = Message {
                    id: msg_id,
                    topic_id: (msg_id as usize) % NUM_TOPICS, // Alternates topics
                    payload,
                    timestamp: Instant::now(), // Ingestion timestamp
                };

                router_clone.route(msg);
                msg_id += 1;

                // Subtle yield to prevent CPU starvation on a single thread
                if msg_id % 1000 == 0 {
                    tokio::task::consume_budget().await;
                }
            }
        });
        publishers.push(handle);
    }

    // Run the simulation for 10 seconds
    tokio::time::sleep(Duration::from_secs(10)).await;
    println!("Execution completed.");
}
```

