use crossbeam_channel::{bounded, Receiver, Sender};
use hdrhistogram::Histogram;
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::Arc;
use std::thread;
use std::time::{Duration, Instant};

// --- CONFIGURATION ---
const NUM_PRODUCERS: usize = 4;
const NUM_WORKERS: usize = 4;
const QUEUE_CAPACITY: usize = 65536; // Must be power of 2 for optimal ring-buffer performance
const RUN_DURATION: Duration = Duration::from_secs(5);

// --- DATA STRUCTURES ---
/// Stack-allocated message. Bypasses the heap completely to prevent GC/allocator pauses.
#[derive(Clone, Copy)]
pub struct Message {
    pub id: u64,
    pub route_key: u32,
    pub payload: [u8; 32],      // Inline payload data
    pub timestamp: Instant,     // Ingress timestamp for latency monitoring
}

/// Metrics snapshot sent periodically from worker threads to the metrics collector.
pub struct ThreadMetrics {
    pub worker_id: usize,
    pub processed_count: u64,
    pub latency_hist: Histogram<u64>,
}

fn main() {
    println!("Starting high-frequency router simulation...");
    let running = Arc::new(AtomicBool::new(true));

    // Create channels for routing.
    // Each worker has its own dedicated input queue to prevent lock contention.
    let mut worker_txs = Vec::with_capacity(NUM_WORKERS);
    let mut worker_rxs = Vec::with_capacity(NUM_WORKERS);

    for _ in 0..NUM_WORKERS {
        let (tx, rx) = bounded::<Message>(QUEUE_CAPACITY);
        worker_txs.push(tx);
        worker_rxs.push(rx);
    }

    // Channel to aggregate metrics off the critical path
    let (metrics_tx, metrics_rx) = bounded::<ThreadMetrics>(NUM_WORKERS * 2);

    // 1. START WORKERS (Egress / Processing)
    let mut worker_handles = Vec::new();
    for worker_id in 0..NUM_WORKERS {
        let rx = worker_rxs[worker_id].clone();
        let m_tx = metrics_tx.clone();
        let running_flag = running.clone();

        let handle = thread::spawn(move || {
            // High-precision tracking: 1 microsecond to 10 seconds range, 3 significant figures
            let mut hist = Histogram::<u64>::new_with_bounds(1, 10_000_000, 3).unwrap();
            let mut processed_count = 0u64;
            let mut last_flush = Instant::now();

            while running_flag.load(Ordering::Relaxed) || !rx.is_empty() {
                // Non-blocking try_recv keeps latency spikes low under extreme loads
                if let Ok(msg) = rx.try_recv() {
                    let elapsed_us = msg.timestamp.elapsed().as_micros() as u64;

                    // Record latency to thread-local histogram (Zero Lock Contention)
                    let _ = hist.record(elapsed_us);
                    processed_count += 1;

                    // Do some simulated work on payload (e.g., CRC check)
                    std::hint::black_box(msg.payload); 
                } else {
                    // Backoff to prevent 100% CPU utilization when queues are starved
                    thread::yield_now();
                }

                // Periodically ship metrics off-thread to keep critical path clean
                if last_flush.elapsed() >= Duration::from_millis(500) {
                    let _ = m_tx.send(ThreadMetrics {
                        worker_id,
                        processed_count,
                        latency_hist: hist.clone(),
                    });
                    last_flush = Instant::now();
                }
            }

            // Final flush
            let _ = m_tx.send(ThreadMetrics {
                worker_id,
                processed_count,
                latency_hist: hist,
            });
        });
        worker_handles.push(handle);
    }

    // 2. START PRODUCERS (Ingress / Network Simulation)
    let mut producer_handles = Vec::new();
    let producer_txs = worker_txs.clone(); // Clone sending handles to route directly

    for prod_id in 0..NUM_PRODUCERS {
        let txs = producer_txs.clone();
        let running_flag = running.clone();

        let handle = thread::spawn(move || {
            let mut msg_id = 0u64;
            let dummy_payload = [0u8; 32];

            while running_flag.load(Ordering::Relaxed) {
                // Create stack-allocated message
                let msg = Message {
                    id: (prod_id as u64 * 10_000_000) + msg_id,
                    route_key: msg_id as u32,
                    payload: dummy_payload,
                    timestamp: Instant::now(), // Start latency timer
                };

                // Route message using basic hash routing (Modulo)
                let destination_worker = (msg.route_key as usize) % NUM_WORKERS;

                // Low-latency send. If buffer is full, drop or yield (backpressure)
                match txs[destination_worker].try_send(msg) {
                    Ok(_) => msg_id += 1,
                    Err(_) => {
                        // Queue full: Apply backpressure (yield) to prevent OOM / packet loss
                        thread::yield_now();
                    }
                }
            }
        });
        producer_handles.push(handle);
    }

    // 3. START METRICS MONITORING THREAD
    // This thread runs in the background, aggregating metrics without blocking routing
    let monitor_running = running.clone();
    let monitor_handle = thread::spawn(move || {
        let mut global_hist = Histogram::<u64>::new_with_bounds(1, 10_000_000, 3).unwrap();
        let mut worker_totals = vec![0u64; NUM_WORKERS];
        let mut last_report = Instant::now();

        while monitor_running.load(Ordering::Relaxed) {
            // Collect all pending metric updates
            while let Ok(metrics) = metrics_rx.try_recv() {
                worker_totals[metrics.worker_id] = metrics.processed_count;
                global_hist.merge(&metrics.latency_hist).unwrap();
            }

            let elapsed = last_report.elapsed();
            if elapsed >= Duration::from_secs(1) {
                let total_processed: u64 = worker_totals.iter().sum();
                let throughput = total_processed as f64 / elapsed.as_secs_f64();

                if total_processed > 0 {
                    println!("--- SYSTEM MONITOR ---");
                    println!("Throughput: {:.2} Million msgs/sec", throughput / 1_000_000.0);
                    println!("Latencies:");
                    println!("  p50  (Median):  {:>6} µs", global_hist.value_at_quantile(0.50));
                    println!("  p90  (High):    {:>6} µs", global_hist.value_at_quantile(0.90));
                    println!("  p99  (Tail):    {:>6} µs", global_hist.value_at_quantile(0.99));
                    println!("  p99.9 (Extreme):{:>6} µs", global_hist.value_at_quantile(0.999));
                    println!("----------------------\n");
                }

                // Clear the sliding window histogram for the next interval
                global_hist.reset();
                last_report = Instant::now();
            }
            thread::sleep(Duration::from_millis(200));
        }
    });

    // Run the system for the configured duration
    thread::sleep(RUN_DURATION);
    println!("Stopping threads...");
    running.store(false, Ordering::SeqCst);

    // Join all threads
    for handle in producer_handles {
        handle.join().unwrap();
    }
    for handle in worker_handles {
        handle.join().unwrap();
    }
    monitor_handle.join().unwrap();
    println!("Shutdown clean.");
}
