```rust
use crossbeam_channel::{bounded, Receiver, Sender};
use hdrhistogram::Histogram;
use minstant::Instant;
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::Arc;
use std::thread;
use std::time::Duration;

// --- CONFIGURATION ---
const NUM_WORKERS: usize = 4;
const CHANNEL_CAPACITY: usize = 524_288; // 2^19 (Ring buffer power of 2)
const BATCH_SIZE: usize = 128;

// --- DATA STRUCTURES ---
#[derive(Debug, Clone, Copy)]
pub struct Message {
    pub id: u64,
    pub route_key: u32,
    pub payload: [u8; 32],      // Fixed size prevents heap allocation during transit
    pub timestamp: Instant,     // High-resolution ingress timestamp
}

// Thread-safe metrics reporter
pub struct WorkerMetrics {
    pub worker_id: usize,
    pub total_processed: u64,
    pub histogram: Histogram<u64>,
}

fn main() {
    println!("Starting High-Frequency Message Router...");
    let running = Arc::new(AtomicBool::new(true));

    // 1. Setup Channels (Lock-Free, Bounded)
    // Ingress Channel: Producer -> Router
    let (ingress_tx, ingress_rx) = bounded::<Message>(CHANNEL_CAPACITY);

    // Egress Channels: Router -> Workers
    let mut worker_txs = Vec::with_capacity(NUM_WORKERS);
    let mut worker_rxs = Vec::with_capacity(NUM_WORKERS);
    for _ in 0..NUM_WORKERS {
        let (tx, rx) = bounded::<Message>(CHANNEL_CAPACITY);
        worker_txs.push(tx);
        worker_rxs.push(rx);
    }

    // Thread handles
    let mut join_handles = Vec::new();
    let mut metrics_receivers = Vec::new();

    // 2. Spawn Worker Threads (Egress & Latency Tracking)
    for worker_id in 0..NUM_WORKERS {
        let rx = worker_rxs[worker_id].clone();
        let running_clone = running.clone();

        // Channel to send metrics back to monitor thread
        let (metric_tx, metric_rx) = bounded::<WorkerMetrics>(1);
        metrics_receivers.push(metric_rx);

        let handle = thread::Builder::new()
            .name(format!("worker-{}", worker_id))
            .spawn(move || {
                // Initialize low-overhead histogram (1ns to 10s range, 3 decimal places)
                let mut hist = Histogram::<u64>::new_with_bounds(1, 10_000_000_000, 3).unwrap();
                let mut count = 0u64;
                let mut batch = Vec::with_capacity(BATCH_SIZE);

                while running_clone.load(Ordering::Relaxed) {
                    // Batch-read messages to minimize synchronization overhead
                    let mut read_count = 0;
                    while read_count < BATCH_SIZE {
                        if let Ok(msg) = rx.try_recv() {
                            batch.push(msg);
                            read_count += 1;
                        } else {
                            break;
                        }
                    }

                    if batch.is_empty() {
                        // Yield CPU briefly if no messages, avoiding 100% spinlock CPU usage
                        thread::yield_now();
                        continue;
                    }

                    for msg in batch.drain(..) {
                        // Latency calculation (Ingress to Egress finish)
                        let elapsed_ns = msg.timestamp.elapsed().as_nanos() as u64;
                        let _ = hist.record(elapsed_ns);
                        count += 1;

                        // [ACTUAL MESSAGE ROUTING WORK / BUSINESS LOGIC GOES HERE]
                        // Black_box used to prevent compiler from optimizing away the write
                        std::hint::black_box(msg.payload);
                    }
                }

                // Send final metrics before exiting
                let _ = metric_tx.send(WorkerMetrics {
                    worker_id,
                    total_processed: count,
                    histogram: hist,
                });
            })
            .unwrap();
        join_handles.push(handle);
    }

    // 3. Spawn Router Thread (Core Routing Logic)
    let running_router = running.clone();
    let router_handle = thread::Builder::new()
        .name("router".to_string())
        .spawn(move || {
            while running_router.load(Ordering::Relaxed) {
                // Read from Ingress Channel
                if let Ok(msg) = ingress_rx.try_recv() {
                    // O(1) Routing Logic: Consistent hashing / Modulo routing
                    let destination_worker = (msg.route_key as usize) % NUM_WORKERS;

                    // Route message. If channel is full, we block (backpressure)
                    if let Err(e) = worker_txs[destination_worker].send(msg) {
                        eprintln!("Router failed to forward message: {:?}", e);
                    }
                } else {
                    thread::yield_now();
                }
            }
        })
        .unwrap();
    join_handles.push(router_handle);

    // 4. Spawn Producer Thread (Simulating Millions of Messages)
    let running_producer = running.clone();
    let producer_handle = thread::Builder::new()
        .name("producer".to_string())
        .spawn(move || {
            let mut id = 0u64;
            let payload = [0u8; 32]; // Mock data payload

            while running_producer.load(Ordering::Relaxed) {
                // Pre-allocate timestamp immediately on ingress
                let msg = Message {
                    id,
                    route_key: id as u32,
                    payload,
                    timestamp: Instant::now(), // Fast hardware TSC read
                };

                // Push to router. If buffer is full, spin or yield (backpressure)
                while ingress_tx.send(msg).is_err() {
                    if !running_producer.load(Ordering::Relaxed) {
                        break;
                    }
                    thread::yield_now();
                }
                id += 1;
            }
        })
        .unwrap();

    // 5. Run system for 5 seconds, monitor, and output metrics
    thread::sleep(Duration::from_secs(5));

    // Stop system execution
    running.store(false, Ordering::SeqCst);

    // Rejoin producer/router first to flush worker queues
    let _ = producer_handle.join();
    let _ = join_handles.pop().unwrap().join();

    // Rejoin workers to fetch final state
    for handle in join_handles {
        let _ = handle.join();
    }

    // 6. Aggregate and Display Latency Report
    println!("\n============= LATENCY REPORT =============");
    let mut combined_hist = Histogram::<u64>::new_with_bounds(1, 10_000_000_000, 3).unwrap();
    let mut grand_total = 0;

    for rx in metrics_receivers {
        if let Ok(worker_metric) = rx.recv() {
            grand_total += worker_metric.total_processed;
            combined_hist.add(&worker_metric.histogram).unwrap();
            println!(
                "Worker {}: Processed {} messages",
                worker_metric.worker_id, worker_metric.total_processed
            );
        }
    }

    println!("------------------------------------------");
    println!("Total Routed Messages: {}", grand_total);
    println!("Throughput:            {:.2} million msg/sec", (grand_total as f64 / 5.0) / 1_000_000.0);
    println!("Avg Latency:           {:.2} μs", combined_hist.mean() as f64 / 1000.0);
    println!("Min Latency:           {:.2} μs", combined_hist.min() as f64 / 1000.0);
    println!("P50 Latency:           {:.2} μs", combined_hist.value_at_quantile(0.50) as f64 / 1000.0);
    println!("P90 Latency:           {:.2} μs", combined_hist.value_at_quantile(0.90) as f64 / 1000.0);
    println!("P99 Latency:           {:.2} μs", combined_hist.value_at_quantile(0.99) as f64 / 1000.0);
    println!("P99.9 Latency:         {:.2} μs", combined_hist.value_at_quantile(0.999) as f64 / 1000.0);
    println!("==========================================");
}
```

