use crossbeam_channel::{bounded, Receiver, Sender};
use hdrhistogram::Histogram;
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::Arc;
use std::thread;
use std::time::{Duration, Instant};

// --- CONFIGURATION ---
const MSG_BATCH_SIZE: usize = 10_000_000; // Total messages to route in benchmark
const QUEUE_CAPACITY: usize = 65_536;     // Ring buffer size (must be power of 2 for optimization)
const NUM_ROUTES: usize = 4;              // Number of destination routes/workers

// --- DATA STRUCTURES ---

/// Represents our high-frequency message.
/// Crucial: No heap allocations (No String, No Vec). Entirely on-stack/fixed size.
#[derive(Clone, Copy)]
pub struct Message {
    pub id: u64,
    pub route_id: u16,
    pub payload: [u8; 32], // 32 bytes of inline data
    pub timestamp: Instant, // Captured at the exact ingestion point
}

/// Thread-safe Latency Recorder using an HDR Histogram
pub struct LatencyMonitor {
    // We use parking_lot::Mutex because it is significantly faster than std::sync::Mutex
    histogram: parking_lot::Mutex<Histogram<u64>>,
}

impl LatencyMonitor {
    pub fn new() -> Self {
        Self {
            // Record latencies from 1 nanosecond to 10 seconds, with 3 decimal places of precision
            histogram: parking_lot::Mutex::new(Histogram::<u64>::new_with_bounds(1, 10_000_000_000, 3).unwrap()),
        }
    }

    pub fn record(&self, latency_ns: u64) {
        let mut hist = self.histogram.lock();
        let _ = hist.record(latency_ns);
    }

    pub fn print_stats(&self) {
        let hist = self.histogram.lock();
        if hist.len() == 0 { return; }
        println!(
            "Latency Profile (ns): Min: {}ns | P50: {}ns | P90: {}ns | P99: {}ns | P99.9: {}ns | Max: {}ns | Total Messages: {}",
            hist.min(),
            hist.value_at_quantile(0.50),
            hist.value_at_quantile(0.90),
            hist.value_at_quantile(0.99),
            hist.value_at_quantile(0.999),
            hist.max(),
            hist.len()
        );
    }
}

// --- SYSTEM ENGINE ---

fn main() {
    let running = Arc::new(AtomicBool::new(true));

    // Ingestion queue: where upstream producers write messages
    let (ingest_tx, ingest_rx) = bounded::<Message>(QUEUE_CAPACITY);

    // Route queues: where the Router distributes messages
    let mut route_txs = Vec::with_capacity(NUM_ROUTES);
    let mut route_rxs = Vec::with_capacity(NUM_ROUTES);
    for _ in 0..NUM_ROUTES {
        let (tx, rx) = bounded::<Message>(QUEUE_CAPACITY);
        route_txs.push(tx);
        route_rxs.push(rx);
    }

    // Shared thread-safe latency monitor
    let latency_monitor = Arc::new(LatencyMonitor::new());

    // 1. START CONSUMERS (Egress Workers)
    let mut worker_handles = Vec::new();
    for (route_idx, rx) in route_rxs.into_iter().enumerate() {
        let monitor = Arc::clone(&latency_monitor);
        let run_flag = Arc::clone(&running);

        let handle = thread::spawn(move || {
            // Pinning threads to dedicated cores (using `core_affinity`) is recommended in prod.
            println!("Worker thread for Route {} initialized.", route_idx);

            while run_flag.load(Ordering::Relaxed) || !rx.is_empty() {
                // Low-latency non-blocking / spin-lock style read
                if let Ok(msg) = rx.try_recv() {
                    let duration = msg.timestamp.elapsed().as_nanos() as u64;
                    monitor.record(duration);

                    // Simulating lightweight processing (e.g., writing to NIC / ring-buffer)
                    let _payload_sum = msg.payload.iter().fold(0u8, |acc, &x| acc.wrapping_add(x));
                } else {
                    // Back off slightly to avoid 100% CPU starvation when idle
                    thread::yield_now();
                }
            }
        });
        worker_handles.push(handle);
    }

    // 2. START THE DISPATCHER (Router)
    // Consumes from ingestion queue and routes to appropriate route queues.
    let router_run_flag = Arc::clone(&running);
    let router_handle = thread::spawn(move || {
        println!("Router thread initialized.");
        while router_run_flag.load(Ordering::Relaxed) || !ingest_rx.is_empty() {
            if let Ok(msg) = ingest_rx.try_recv() {
                let target_route = (msg.route_id as usize) % NUM_ROUTES;
                // Non-blocking send. If queue is full, drop or apply backpressure.
                if let Err(e) = route_txs[target_route].try_send(msg) {
                    // In a production system, you would log a dropped packet metric here
                    eprintln!("Queue overflow on route {}: message dropped", target_route);
                }
            } else {
                thread::yield_now();
            }
        }
    });

    // 3. START HIGH-FREQUENCY INGESTION SIMULATOR (Producer)
    let producer_handle = thread::spawn(move || {
        println!("Starting ingestion of {} messages...", MSG_BATCH_SIZE);
        let start_time = Instant::now();

        let mut msg_template = Message {
            id: 0,
            route_id: 0,
            payload: [42u8; 32],
            timestamp: Instant::now(),
        };

        for i in 0..MSG_BATCH_SIZE {
            msg_template.id = i as u64;
            msg_template.route_id = (i % NUM_ROUTES) as u16;
            msg_template.timestamp = Instant::now(); // Capture time immediately before enqueueing

            // Spin-lock push backpressure strategy
            loop {
                if ingest_tx.try_send(msg_template).is_ok() {
                    break;
                }
                // Queue full, yield CPU briefly and retry
                thread::yield_now();
            }
        }

        let duration = start_time.elapsed();
        let throughput = MSG_BATCH_SIZE as f64 / duration.as_secs_f64();
        println!(
            "Ingestion Completed. Produced {} messages in {:?}. Avg Throughput: {:.2} million msgs/sec",
            MSG_BATCH_SIZE,
            duration,
            throughput / 1_000_000.0
        );
    });

    // Wait for the ingestion simulator to finish producing
    producer_handle.join().unwrap();

    // Allow queues to drain
    while !ingest_tx.is_empty() {
        thread::sleep(Duration::from_millis(10));
    }

    // Stop the running loops
    running.store(false, Ordering::SeqCst);

    // Wait for routing & consumption to finish
    router_handle.join().unwrap();
    for handle in worker_handles {
        handle.join().unwrap();
    }

    // Print out the absolute latency profiles
    println!("\n=== LATENCY MONITORING REPORT ===");
    latency_monitor.print_stats();
}
