use std::cell::UnsafeCell;
use std::sync::atomic::{AtomicU64, AtomicUsize, Ordering};
use std::sync::Arc;
use std::thread;
use std::time::{Duration, Instant};

// --- CONFIGURATION ---
const QUEUE_CAPACITY: usize = 1048576; // Power of 2 (1,048,576) for fast bitwise modulo
const MSG_PAYLOAD_SIZE: usize = 32;
const NUM_CONSUMERS: usize = 2;
const TEST_DURATION_SECS: u64 = 5;

// --- STRUCTURES ---

#[derive(Clone, Copy)]
#[repr(C)]
struct Message {
    id: u64,
    route_key: u32,
    timestamp_ns: u64,
    payload: [u8; MSG_PAYLOAD_SIZE],
}

impl Default for Message {
    fn default() -> Self {
        Self {
            id: 0,
            route_key: 0,
            timestamp_ns: 0,
            payload: [0; MSG_PAYLOAD_SIZE],
        }
    }
}

// Prevent false sharing by aligning atomic indexes to CPU Cache Lines (64 bytes)
#[repr(align(64))]
struct CacheAlignedAtomicUsize(AtomicUsize);

/// A high-performance, lock-free, SPSC (Single Producer Single Consumer) Ring Buffer.
pub struct SPSCQueue<T, const N: usize> {
    buffer: Vec<UnsafeCell<T>>,
    head: CacheAlignedAtomicUsize,
    tail: CacheAlignedAtomicUsize,
}

unsafe impl<T, const N: usize> Sync for SPSCQueue<T, N> {}

impl<T: Default + Copy, const N: usize> SPSCQueue<T, N> {
    pub fn new() -> Self {
        assert!(N.is_power_of_two(), "Capacity must be a power of two");
        let mut buffer = Vec::with_capacity(N);
        for _ in 0..N {
            buffer.push(UnsafeCell::new(T::default()));
        }
        Self {
            buffer,
            head: CacheAlignedAtomicUsize(AtomicUsize::new(0)),
            tail: CacheAlignedAtomicUsize(AtomicUsize::new(0)),
        }
    }

    #[inline(always)]
    pub fn try_push(&self, value: T) -> Result<(), T> {
        let tail = self.tail.0.load(Ordering::Relaxed);
        let head = self.head.0.load(Ordering::Acquire);

        if tail - head == N {
            return Err(value); // Queue is full
        }

        unsafe {
            let ptr = self.buffer[tail & (N - 1)].get();
            ptr.write(value);
        }
        self.tail.0.store(tail + 1, Ordering::Release);
        Ok(())
    }

    #[inline(always)]
    pub fn try_pop(&self) -> Option<T> {
        let head = self.head.0.load(Ordering::Relaxed);
        let tail = self.tail.0.load(Ordering::Acquire);

        if head == tail {
            return None; // Queue is empty
        }

        let value = unsafe { self.buffer[head & (N - 1)].get().read() };
        self.head.0.store(head + 1, Ordering::Release);
        Some(value)
    }
}

// --- LATENCY MONITORING (LOCKLESS HISTOGRAM) ---

struct LatencyMonitor {
    // High-resolution latency buckets in nanoseconds:
    // <250ns, <500ns, <1us, <2us, <5us, <10us, <50us, <100us, <1ms, 1ms+
    buckets: [AtomicU64; 10],
    total_messages: AtomicU64,
}

impl LatencyMonitor {
    fn new() -> Self {
        Self {
            buckets: Default::default(),
            total_messages: AtomicU64::new(0),
        }
    }

    #[inline(always)]
    fn record_latency(&self, latency_ns: u64) {
        let bucket_idx = if latency_ns < 250 { 0 }
        else if latency_ns < 500 { 1 }
        else if latency_ns < 1000 { 2 }
        else if latency_ns < 2000 { 3 }
        else if latency_ns < 5000 { 4 }
        else if latency_ns < 10000 { 5 }
        else if latency_ns < 50000 { 6 }
        else if latency_ns < 100000 { 7 }
        else if latency_ns < 1000000 { 8 }
        else { 9 };

        self.buckets[bucket_idx].fetch_add(1, Ordering::Relaxed);
        self.total_messages.fetch_add(1, Ordering::Relaxed);
    }

    fn print_report(&self, elapsed_secs: f64) {
        let total = self.total_messages.load(Ordering::Relaxed);
        if total == 0 { return; }

        let throughput = total as f64 / elapsed_secs;
        println!("\n================ TELEMETRY REPORT ================");
        println!("Elapsed Time:       {:.2}s", elapsed_secs);
        println!("Total Processed:    {}", total);
        println!("Throughput:         {:.2} Million Msgs/sec", throughput / 1_000_000.0);
        println!("--------------------------------------------------");
        println!("Latency Distribution:");

        let mut cumulative = 0;
        let labels = [
            "< 250ns", "< 500ns", "<   1µs", "<   2µs", "<   5µs", 
            "<  10µs", "<  50µs", "< 100µs", "<   1ms", ">=  1ms"
        ];

        for i in 0..10 {
            let count = self.buckets[i].load(Ordering::Relaxed);
            cumulative += count;
            let percent = (count as f64 / total as f64) * 100.0;
            let cum_percent = (cumulative as f64 / total as f64) * 100.0;
            println!("{: <10} : {: >10} msgs ({: >5.2}%) | Cumulative: {: >5.2}%", labels[i], count, percent, cum_percent);
        }
        println!("==================================================");
    }
}

// --- HIGH-RESOLUTION TIMER ---
#[inline(always)]
fn get_time_ns() -> u64 {
    // In actual HFT, we'd use CPU instruction TSC (Time Stamp Counter) e.g., `_rdtsc()` via core::arch::x86_64
    // Standard Instant::now() uses vDSO which is highly optimized on Linux.
    let duration = Instant::now().elapsed();
    duration.as_nanos() as u64
}

// --- MAIN RUNTIME ---

fn main() {
    println!("Starting High-Frequency Router demo...");

    // Shared Ring Buffers
    // Input queue: Producer -> Router
    let input_queue = Arc::new(SPSCQueue::<Message, QUEUE_CAPACITY>::new());

    // Output queues: Router -> Consumers
    let mut to_consumers = Vec::new();
    for _ in 0..NUM_CONSUMERS {
        to_consumers.push(Arc::new(SPSCQueue::<Message, QUEUE_CAPACITY>::new()));
    }

    let telemetry = Arc::new(LatencyMonitor::new());

    // 1. Start Consumer Threads
    let mut consumer_handles = Vec::new();
    for i in 0..NUM_CONSUMERS {
        let queue = to_consumers[i].clone();
        let tel = telemetry.clone();

        let handle = thread::spawn(move || {
            let mut backoff = 0;
            while tel.total_messages.load(Ordering::Relaxed) < 100_000_000 { // Keep running
                if let Some(msg) = queue.try_pop() {
                    let now = get_time_ns();
                    // Handle overflow wrapping safely
                    if now >= msg.timestamp_ns {
                        let latency = now - msg.timestamp_ns;
                        tel.record_latency(latency);
                    }
                    backoff = 0;
                } else {
                    // CPU Backoff to prevent 100% core saturation during starvation
                    if backoff < 10 {
                        backoff += 1;
                    } else if backoff < 20 {
                        thread::yield_now();
                        backoff += 1;
                    } else {
                        thread::sleep(Duration::from_nanos(50));
                    }
                }
            }
        });
        consumer_handles.push(handle);
    }

    // 2. Start Router Thread (Dispatches to Consumers based on Route Key)
    let r_input = input_queue.clone();
    let r_outputs = to_consumers.clone();
    let r_tel = telemetry.clone();

    let router_handle = thread::spawn(move || {
        let mut backoff = 0;
        while r_tel.total_messages.load(Ordering::Relaxed) < 100_000_000 {
            if let Some(msg) = r_input.try_pop() {
                // Route Evaluation: fast modulo mapping to target queue
                let dest_idx = (msg.route_key as usize) % NUM_CONSUMERS;
                let out_queue = &r_outputs[dest_idx];

                // Spin-wait if destination queue is temporarily full to preserve messages
                while out_queue.try_push(msg).is_err() {
                    core::hint::spin_loop();
                }
                backoff = 0;
            } else {
                if backoff < 10 {
                    backoff += 1;
                } else {
                    thread::yield_now();
                }
            }
        }
    });

    // 3. Start Producer Thread (Generates high frequency stream of messages)
    let p_queue = input_queue.clone();
    let start_time = Instant::now();

    let producer_handle = thread::spawn(move || {
        let mut msg_id = 0;
        let mut route_generator: u32 = 0;
        let stop_duration = Duration::from_secs(TEST_DURATION_SECS);

        while start_time.elapsed() < stop_duration {
            let msg = Message {
                id: msg_id,
                route_key: route_generator,
                timestamp_ns: get_time_ns(),
                payload: [0xAA; MSG_PAYLOAD_SIZE],
            };

            // Attempt to write to input queue; Spin-wait (or drop/yield) if busy
            while p_queue.try_push(msg).is_err() {
                core::hint::spin_loop();
            }

            msg_id += 1;
            route_generator = route_generator.wrapping_add(1);
        }
    });

    // Wait for the Producer to complete the timed run
    producer_handle.join().unwrap();
    let actual_duration = start_time.elapsed().as_secs_f64();

    // Print results
    telemetry.print_report(actual_duration);

    // Force system shutdown (kills infinite spinning consumers gracefully)
    std::process::exit(0);
}
```

### Performance Characteristics Explained

1. **Lock-Free Concurrency (`SPSCQueue`)**: The hot path bypasses mutexes entirely. Threads communicate via an atomic SPSC ring buffer. CPU execution context remains in user-space, avoiding costly OS kernel transitions.
2. **Memory Layout Protection (`CacheAlignedAtomicUsize`)**: High-throughput queues suffer heavily from **false sharing** (where different CPU cores attempt to write to adjacent variables on the same cache line). Adding `#[repr(align(64))]` pins the atomic values to distinct L1/L2 cache boundaries.
3. **Optimistic Telemetry**: Latency is computed on the consuming thread, completely decoupled from the producer/routing phase. By categorizing latencies directly into **atomic array buckets** using light branches, we bypass heavy array tracking or serialization bottlenecks. 
4. **Busy-Wait and Backoff**: Rather than parking threads when queues are temporarily empty, we use `core::hint::spin_loop()` and `thread::yield_now()`, keeping the physical CPU core awake and responsive within the sub-microsecond range.

