Replace the contents of `src/main.rs` with the following highly optimized code:

```rust
use crossbeam_channel::{bounded, Receiver, Sender};
use hdrhistogram::Histogram;
use std::sync::atomic::{AtomicBool, AtomicU64, Ordering};
use std::sync::Arc;
use std::thread;
use std::time::{Duration, Instant};

// Configuration
const QUEUE_CAPACITY: usize = 1_024_000;
const NUM_CONSUMERS: usize = 4;
const PAYLOAD_SIZE: usize = 32;

// The Message layout is compact and kept small (64 bytes) to maximize CPU L1/L2 cache locality.
#[derive(Clone)]
struct Message {
    id: u64,
    route_key: u32,
    payload: [u8; PAYLOAD_SIZE],
    timestamp: Instant, // Set at creation to monitor total pipeline latency
}

// Global atomic counters for low-overhead throughput monitoring
struct GlobalMetrics {
    routed_count: AtomicU64,
    consumed_count: AtomicU64,
}

static METRICS: GlobalMetrics = GlobalMetrics {
    routed_count: AtomicU64::new(0),
    consumed_count: AtomicU64::new(0),
};

fn main() {
    let running = Arc::new(AtomicBool::new(true));

    // 1. Initialize Channels (Lock-free bounded queues)
    let (producer_tx, router_rx) = bounded::<Message>(QUEUE_CAPACITY);

    let mut consumer_txs = Vec::new();
    let mut consumer_rxs = Vec::new();
    for _ in 0..NUM_CONSUMERS {
        let (tx, rx) = bounded::<Message>(QUEUE_CAPACITY);
        consumer_txs.push(tx);
        consumer_rxs.push(rx);
    }

    println!("Starting High-Frequency Router with {} consumers...", NUM_CONSUMERS);

    // 2. Spawn Consumers
    // Each consumer maintains its own thread-local latency histogram to avoid global locking.
    let mut consumer_handles = Vec::new();
    let mut shared_histograms = Vec::new();

    for (id, rx) in consumer_rxs.into_iter().enumerate() {
        let running_clone = running.clone();
        // Dynamic Range Histogram: Track latency from 1 microsecond to 10 seconds with 3 significant figures
        let mut hist = Histogram::<u64>::new_with_bounds(1, 10_000_000, 3).unwrap();

        // We use a shared thread-safe pointer to expose the latency data to the monitor
        let hist_shared = Arc::new(std::sync::Mutex::new(hist.clone()));
        shared_histograms.push(hist_shared.clone());

        let handle = thread::spawn(move || {
            let mut local_counter = 0;
            while running_clone.load(Ordering::Relaxed) {
                if let Ok(msg) = rx.try_recv() {
                    let elapsed = msg.timestamp.elapsed().as_micros() as u64;
                    // Record latency in microseconds (clamp to bounds)
                    let _ = hist.record(elapsed.max(1).min(9_999_999));

                    local_counter += 1;
                    if local_counter % 100_000 == 0 {
                        METRICS.consumed_count.fetch_add(100_000, Ordering::Relaxed);
                        // Periodically publish thread-local metrics to the shared monitor
                        if let Ok(mut shared) = hist_shared.try_lock() {
                            *shared = hist.clone();
                        }
                    }
                } else {
                    // Backoff slightly if queue is empty to prevent 100% CPU starvation
                    thread::yield_now();
                }
            }
        });
        consumer_handles.push(handle);
    }

    // 3. Spawn Router Thread
    // Acts as the dispatcher. Evaluates route keys and dispatches to appropriate consumer queue.
    let running_router = running.clone();
    let router_handle = thread::spawn(move || {
        let mut local_routed = 0;
        while running_router.load(Ordering::Relaxed) {
            if let Ok(msg) = router_rx.try_recv() {
                // Route message using deterministic modulo hash on route_key
                let target_consumer = (msg.route_key as usize) % NUM_CONSUMERS;

                // Non-blocking send. If consumer queues are full, drop or block depending on backpressure strategy
                if consumer_txs[target_consumer].try_send(msg).is_ok() {
                    local_routed += 1;
                    if local_routed % 100_000 == 0 {
                        METRICS.routed_count.fetch_add(100_000, Ordering::Relaxed);
                    }
                }
            } else {
                thread::yield_now();
            }
        }
    });

    // 4. Spawn Producer Thread
    // Generates millions of dummy messages with monotonically increasing sequence numbers.
    let running_producer = running.clone();
    let producer_handle = thread::spawn(move || {
        let mut seq = 0u64;
        let payload = [0u8; PAYLOAD_SIZE];

        while running_producer.load(Ordering::Relaxed) {
            let msg = Message {
                id: seq,
                route_key: (seq % 100) as u32, // Rotate through 100 routing keys
                payload,
                timestamp: Instant::now(),
            };

            // Non-blocking send. Apply backpressure if the router queue is completely full.
            while producer_tx.try_send(msg.clone()).is_err() {
                if !running_producer.load(Ordering::Relaxed) {
                    return;
                }
                thread::yield_now(); // Backpressure
            }
            seq += 1;
        }
    });

    // 5. Monitor Thread
    // Calculates system throughput and latency metrics every second
    let running_monitor = running.clone();
    let monitor_handle = thread::spawn(move || {
        let mut last_routed = 0;
        let mut last_consumed = 0;
        let mut last_time = Instant::now();

        while running_monitor.load(Ordering::Relaxed) {
            thread::sleep(Duration::from_secs(1));

            let current_time = Instant::now();
            let elapsed_sec = current_time.duration_since(last_time).as_secs_f64();

            let cur_routed = METRICS.routed_count.load(Ordering::Relaxed);
            let cur_consumed = METRICS.consumed_count.load(Ordering::Relaxed);

            let throughput_routed = ((cur_routed - last_routed) as f64 / elapsed_sec) / 1_000_000.0;
            let throughput_consumed = ((cur_consumed - last_consumed) as f64 / elapsed_sec) / 1_000_000.0;

            // Merge consumer latency histograms
            let mut merged_hist = Histogram::<u64>::new_with_bounds(1, 10_000_000, 3).unwrap();
            for shared_hist in &shared_histograms {
                if let Ok(hist) = shared_hist.lock() {
                    merged_hist.add(&hist).unwrap();
                }
            }

            println!("--------------------------------------------------");
            println!("Throughput (Routed)  : {:.2} Million msgs/sec", throughput_routed);
            println!("Throughput (Consumed): {:.2} Million msgs/sec", throughput_consumed);
            println!(
                "Latency Profiling (Pipeline Transit Time): \n\
                 |  P50  : {:>5} µs |\n\
                 |  P90  : {:>5} µs |\n\
                 |  P99  : {:>5} µs |\n\
                 |  P99.9: {:>5} µs |\n\
                 |  Max  : {:>5} µs |",
                merged_hist.value_at_quantile(0.50),
                merged_hist.value_at_quantile(0.90),
                merged_hist.value_at_quantile(0.99),
                merged_hist.value_at_quantile(0.999),
                merged_hist.max()
            );

            last_routed = cur_routed;
            last_consumed = cur_consumed;
            last_time = current_time;
        }
    });

    // Run for 10 seconds, then exit
    thread::sleep(Duration::from_secs(10));
    println!("Stopping system...");
    running.store(false, Ordering::Relaxed);

    // Join threads
    let _ = producer_handle.join();
    let _ = router_handle.join();
    for handle in consumer_handles {
        let _ = handle.join();
    }
    let _ = monitor_handle.join();
}
