### 2. The Implementation (`src/main.rs`)

```rust
use crossbeam_channel::{bounded, Receiver, Sender};
use hdrhistogram::Histogram;
use std::thread;
use std::time::{Duration, Instant};

// 1. Define a compact, stack-allocated message structure to avoid heap allocations.
#[derive(Clone, Copy)]
struct Message {
    id: u64,
    route_key: u32,
    timestamp: Instant, // Ingestion timestamp for microsecond tracking
    payload: [u8; 32],  // 32-byte static payload
}

// Stats message passed from workers to the Monitor thread (off the hot path)
struct WorkerStats {
    worker_id: usize,
    messages_processed: u64,
    latency_hist: Histogram<u64>,
}

fn main() {
    // Configuration
    const NUM_WORKERS: usize = 4;
    const QUEUE_CAPACITY: usize = 65536; // Bounded capacity to prevent memory bloat
    const RUN_DURATION: Duration = Duration::from_secs(5);

    println!("Starting High-Frequency Router with {} workers...", NUM_WORKERS);

    // 2. Channels setup
    // Ingestion queue (Producer -> Router)
    let (ingest_tx, ingest_rx) = bounded::<Message>(QUEUE_CAPACITY);

    // Worker queues (Router -> Workers)
    let mut worker_txs = Vec::new();
    let mut worker_rxs = Vec::new();
    for _ in 0..NUM_WORKERS {
        let (tx, rx) = bounded::<Message>(QUEUE_CAPACITY);
        worker_txs.push(tx);
        worker_rxs.push(rx);
    }

    // Diagnostics channel (Workers -> Monitor)
    let (stats_tx, stats_rx) = bounded::<WorkerStats>(128);

    // --- PRODUCER THREAD ---
    // Generates messages as fast as physically possible
    let prod_handle = thread::spawn(move || {
        let mut id = 0u64;
        let payload = [42u8; 32];
        let start = Instant::now();

        while start.elapsed() < RUN_DURATION {
            let msg = Message {
                id,
                route_key: (id % 100) as u32, // simulated route key
                timestamp: Instant::now(),
                payload,
            };

            // If the buffer is full, block (backpressure propagation)
            if ingest_tx.send(msg).is_err() {
                break;
            }
            id += 1;
        }
    });

    // --- ROUTER THREAD ---
    // Reads from ingest_rx, routes messages using thread-affinity hashing
    let router_handle = thread::spawn(move || {
        while let Ok(msg) = ingest_rx.recv() {
            // Consistent hashing route selection
            let worker_idx = (msg.route_key as usize) % NUM_WORKERS;
            if worker_txs[worker_idx].send(msg).is_err() {
                break;
            }
        }
    });

    // --- WORKER THREADS (Consumers) ---
    // Processes messages and tracks latencies locally to prevent synchronization locks.
    let mut worker_handles = Vec::new();
    for worker_id in 0..NUM_WORKERS {
        let rx = worker_rxs[worker_id].clone();
        let stats_tx = stats_tx.clone();

        let handle = thread::spawn(move || {
            // High dynamic range histogram (1 microsecond to 10 seconds tracking)
            let mut hist = Histogram::<u64>::new_with_bounds(1, 10_000_000, 3).unwrap();
            let mut count = 0u64;
            let mut last_flush = Instant::now();

            while let Ok(msg) = rx.recv() {
                // Calculate latency in microseconds
                let latency = msg.timestamp.elapsed().as_micros() as u64;
                let _ = hist.record(latency);
                count += 1;

                // Push statistics every 100,000 messages to the monitor thread 
                // to completely isolate monitoring from the fast routing path.
                if count % 100_000 == 0 && last_flush.elapsed() >= Duration::from_millis(100) {
                    let _ = stats_tx.send(WorkerStats {
                        worker_id,
                        messages_processed: count,
                        latency_hist: hist.clone(),
                    });
                    hist.reset();
                    count = 0;
                    last_flush = Instant::now();
                }
            }
        });
        worker_handles.push(handle);
    }

    // --- MONITOR THREAD ---
    // Receives telemetry off-path and prints aggregated statistical distributions
    let monitor_handle = thread::spawn(move || {
        let mut total_messages = 0u64;
        let start_time = Instant::now();
        let mut global_hist = Histogram::<u64>::new_with_bounds(1, 10_000_000, 3).unwrap();

        while let Ok(stats) = stats_rx.recv() {
            total_messages += stats.messages_processed;
            let _ = global_hist.add(&stats.latency_hist);

            let elapsed = start_time.elapsed().as_secs_f64();
            if elapsed >= 1.0 {
                let throughput = total_messages as f64 / elapsed;
                println!(
                    "Throughput: {:.2} M/s | p50: {}μs | p90: {}μs | p99: {}μs | p99.9: {}μs | Max: {}μs",
                    throughput / 1_000_000.0,
                    global_hist.value_at_quantile(0.50),
                    global_hist.value_at_quantile(0.90),
                    global_hist.value_at_quantile(0.99),
                    global_hist.value_at_quantile(0.999),
                    global_hist.max()
                );
            }
        }
    });

    // Run the system
    let _ = prod_handle.join();
    let _ = router_handle.join();
    for h in worker_handles {
        let _ = h.join();
    }
    drop(stats_tx); // Closes monitor channel when all workers exit
    let _ = monitor_handle.join();
}
```

