### 2. The Code (`src/main.rs`)
Replace the contents of `src/main.rs` with the following optimized implementation:

```rust
use crossbeam_channel::{bounded, Receiver, Sender};
use std::sync::atomic::{AtomicU64, Ordering};
use std::sync::Arc;
use std::thread;
use std::time::{Duration, Instant};

// Configuration
const NUM_PRODUCERS: usize = 4;
const NUM_CONSUMERS: usize = 4;
const CHANNEL_CAPACITY: usize = 65_536; // Keep in L3 cache if possible
const METRICS_BATCH_SIZE: u64 = 8192;   // Flush metrics to global counters every N messages

// Simple, copyable message payload to avoid heap allocation in the hot path
#[derive(Clone, Copy)]
struct Message {
    id: u64,
    route_key: u32,
    creation_time: Instant,
    payload: [u8; 16],
}

// Latency monitoring buckets: Microsecond resolution up to 2,000 microseconds (2ms)
const MAX_LATENCY_US: usize = 2000;
struct GlobalMetrics {
    total_routed: AtomicU64,
    // Buckets for lock-free latency tracking
    latency_buckets: [AtomicU64; MAX_LATENCY_US],
}

impl GlobalMetrics {
    const fn new() -> Self {
        // Initialize an array of AtomicU64s safely
        #[allow(clippy::declare_interior_mutable_const)]
        const ATOMIC_ZERO: AtomicU64 = AtomicU64::new(0);
        Self {
            total_routed: AtomicU64::new(0),
            latency_buckets: [ATOMIC_ZERO; MAX_LATENCY_US],
        }
    }
}

// Global metrics instance shared across threads
static METRICS: GlobalMetrics = GlobalMetrics::new();

fn main() {
    println!("Starting High-Frequency Message Router Demo...");
    println!("Producers: {}, Consumers: {}", NUM_PRODUCERS, NUM_CONSUMERS);

    // Create bounded channels for routing
    let mut senders = Vec::new();
    let mut receivers = Vec::new();

    for _ in 0..NUM_CONSUMERS {
        let (s, r) = bounded::<Message>(CHANNEL_CAPACITY);
        senders.push(s);
        receivers.push(r);
    }

    // Wrap senders in Arc to share among producers
    let senders = Arc::new(senders);

    // 1. Spawn Consumers
    for i in 0..NUM_CONSUMERS {
        let rx = receivers[i].clone();
        thread::Builder::new()
            .name(format!("consumer-{}", i))
            .spawn(move || consumer_loop(rx))
            .unwrap();
    }

    // 2. Spawn Producers
    for i in 0..NUM_PRODUCERS {
        let senders_clone = Arc::clone(&senders);
        thread::Builder::new()
            .name(format!("producer-{}", i))
            .spawn(move || producer_loop(i, senders_clone))
            .unwrap();
    }

    // 3. Spawn Monitor Thread
    thread::Builder::new()
        .name("monitor".to_string())
        .spawn(|| monitor_loop())
        .unwrap();

    // Prevent main thread from exiting
    loop {
        thread::sleep(Duration::from_secs(60));
    }
}

// Producers generate messages as fast as possible and route to target queues
fn producer_loop(producer_id: usize, senders: Arc<Vec<Sender<Message>>>) {
    let mut msg_id = 0u64;
    let num_routes = senders.len();

    loop {
        msg_id += 1;
        // Simple hash/round-robin routing key
        let route_key = (producer_id as u32).wrapping_add(msg_id as u32);
        let target_queue = (route_key as usize) % num_routes;

        let msg = Message {
            id: msg_id,
            route_key,
            creation_time: Instant::now(), // Low overhead time call (vDSO)
            payload: [0xAA; 16],
        };

        // Send blocks if the channel is full (applying natural backpressure)
        if senders[target_queue].send(msg).is_err() {
            break;
        }
    }
}

// Consumers process incoming messages, calculate latency, and record metrics
fn consumer_loop(rx: Receiver<Message>) {
    let mut local_buckets = [0u64; MAX_LATENCY_US];
    let mut local_count = 0u64;

    while let Ok(msg) = rx.recv() {
        // Calculate latency in microseconds
        let elapsed_us = msg.creation_time.elapsed().as_micros() as usize;

        // Clamp to max index (any latency >= 2ms ends up in the last bucket)
        let bucket_idx = elapsed_us.min(MAX_LATENCY_US - 1);
        local_buckets[bucket_idx] += 1;
        local_count += 1;

        // Flush local metrics to global metrics in batches to avoid CPU cache thrashing
        if local_count >= METRICS_BATCH_SIZE {
            METRICS.total_routed.fetch_add(local_count, Ordering::Relaxed);
            for (i, val) in local_buckets.iter_mut().enumerate() {
                if *val > 0 {
                    METRICS.latency_buckets[i].fetch_add(*val, Ordering::Relaxed);
                    *val = 0; // Reset local bucket
                }
            }
            local_count = 0;
        }
    }
}

// Background monitor thread that collects, resets, and prints metrics every second
fn monitor_loop() {
    loop {
        thread::sleep(Duration::from_secs(1));

        // Read and swap the global routed count to get throughput per second
        let count = METRICS.total_routed.swap(0, Ordering::Relaxed);

        // Take a snapshot of the latency buckets and clear them for the next window
        let mut snapshots = [0u64; MAX_LATENCY_US];
        let mut total_samples = 0u64;
        let mut sum_latency_us = 0u64;

        for i in 0..MAX_LATENCY_US {
            let val = METRICS.latency_buckets[i].swap(0, Ordering::Relaxed);
            snapshots[i] = val;
            total_samples += val;
            sum_latency_us += val * (i as u64);
        }

        if total_samples > 0 {
            let avg_latency = sum_latency_us as f64 / total_samples as f64;

            // Calculate percentiles (p50, p90, p99, p99.9)
            let p50_target = (total_samples as f64 * 0.50) as u64;
            let p90_target = (total_samples as f64 * 0.90) as u64;
            let p99_target = (total_samples as f64 * 0.99) as u64;
            let p999_target = (total_samples as f64 * 0.999) as u64;

            let mut running_sum = 0u64;
            let (mut p50, mut p90, mut p99, mut p999) = (0, 0, 0, 0);

            for (i, &count) in snapshots.iter().enumerate() {
                running_sum += count;
                if p50 == 0 && running_sum >= p50_target { p50 = i; }
                if p90 == 0 && running_sum >= p90_target { p90 = i; }
                if p99 == 0 && running_sum >= p99_target { p99 = i; }
                if p999 == 0 && running_sum >= p999_target { p999 = i; }
            }

            println!(
                "Throughput: {:.3}M msgs/sec | Avg Latency: {:.2}µs | p50: {}µs | p90: {}µs | p99: {}µs | p99.9: {}µs",
                (count as f64) / 1_000_000.0,
                avg_latency,
                p50,
                p90,
                p99,
                p999
            );
        } else {
            println!("Warmup phase or zero message activity.");
        }
    }
}
```

