#include <linux/bpf.h>
#include <linux/if_ether.h>
#include <linux/ip.h>
#include <linux/udp.h>
#include <bpf/bpf_helpers.h>

// Byte-swapping macro for network byte order (Big Endian)
#define bpf_htons(x) __builtin_bswap16(x)

SEC("xdp")
int xdp_packet_processor(struct xdp_md *ctx) {
    // 1. Set up pointers to the start and end of the packet data
    void *data = (void *)(long)ctx->data;
    void *data_end = (void *)(long)ctx->data_end;

    // 2. Parse Ethernet Header
    struct ethhdr *eth = data;
    // BPF Verifier requirement: Always check packet boundaries before accessing memory
    if ((void *)(eth + 1) > data_end) {
        return XDP_PASS;
    }

    // Only process IPv4 traffic, pass everything else to the OS kernel
    if (eth->h_proto != bpf_htons(ETH_P_IP)) {
        return XDP_PASS;
    }

    // 3. Parse IPv4 Header
    struct iphdr *iph = (void *)(eth + 1);
    if ((void *)(iph + 1) > data_end) {
        return XDP_PASS;
    }

    // Only process UDP traffic
    if (iph->protocol != IPPROTO_UDP) {
        return XDP_PASS;
    }

    // 4. Parse UDP Header
    struct udphdr *udph = (void *)(iph + 1);
    if ((void *)(udph + 1) > data_end) {
        return XDP_PASS;
    }

    // Read destination port (in Network Byte Order)
    __u16 dest_port = udph->dest;

    // --- FILTER RULE ---
    // If packet is destined for port 9999, drop it immediately (Ultra-low-latency discard)
    if (dest_port == bpf_htons(9999)) {
        return XDP_DROP; 
    }

    // --- FORWARDING/REDIRECT RULE ---
    // If packet is destined for port 8888, swap headers and bounce it back to the sender
    if (dest_port == bpf_htons(8888)) {

        // Swap MAC addresses (Ethernet Layer)
        __u8 tmp_mac[ETH_ALEN];
        __builtin_memcpy(tmp_mac, eth->h_dest, ETH_ALEN);
        __builtin_memcpy(eth->h_dest, eth->h_source, ETH_ALEN);
        __builtin_memcpy(eth->h_source, tmp_mac, ETH_ALEN);

        // Swap IP addresses (IP Layer)
        __be32 tmp_ip = iph->daddr;
        iph->daddr = iph->saddr;
        iph->saddr = tmp_ip;

        // Swap UDP Ports (Transport Layer)
        __be16 tmp_port = udph->dest;
        udph->dest = udph->source;
        udph->source = tmp_port;

        /* 
         * Note on checksums:
         * Because we only swapped the source and destination fields, the 1's complement 
         * sum of the IP and UDP headers remains mathematically identical. 
         * Thus, we do not need to recompute checksums, saving CPU cycles!
         */

        // Forward the packet back out of the network interface it came from
        return XDP_TX;
    }

    // Pass all other UDP traffic to the Linux kernel network stack
    return XDP_PASS;
}

