### 1. The Kernel-Space Engine: `xdp_filter.c`

```c
#include <linux/bpf.h>
#include <linux/if_ether.h>
#include <linux/ip.h>
#include <linux/udp.h>
#include <bpf/bpf_helpers.h>
#include <bpf/bpf_endian.h>

#define TARGET_PORT 9999

// Helper function to update the IP checksum incrementally (for ULL)
static inline void update_iph_checksum(struct iphdr *iph) {
    iph->check = 0;
    __u32 sum = 0;
    __u16 *next_iph_u16 = (__u16 *)iph;

    #pragma clang loop unroll(full)
    for (int i = 0; i < (sizeof(*iph) >> 1); i++) {
        sum += next_iph_u16[i];
    }

    while (sum >> 16) {
        sum = (sum & 0xFFFF) + (sum >> 16);
    }
    iph->check = ~sum;
}

SEC("xdp_packet_processor")
int xdp_packet_handler(struct xdp_md *ctx) {
    void *data_end = (void *)(long)ctx->data_end;
    void *data = (void *)(long)ctx->data;

    // 1. Parse & validate Ethernet Header
    struct ethhdr *eth = data;
    if ((void *)(eth + 1) > data_end) {
        return XDP_PASS; // Pass malformed packets to kernel stack
    }

    // Filter: Only handle IPv4 traffic
    if (eth->h_proto != bpf_htons(ETH_P_IP)) {
        return XDP_PASS;
    }

    // 2. Parse & validate IP Header
    struct iphdr *iph = (void *)(eth + 1);
    if ((void *)(iph + 1) > data_end) {
        return XDP_PASS;
    }

    // Filter: Only handle UDP traffic
    if (iph->protocol != IPPROTO_UDP) {
        return XDP_PASS;
    }

    // 3. Parse & validate UDP Header
    struct udphdr *udph = (void *)(iph + 1);
    if ((void *)(udph + 1) > data_end) {
        return XDP_PASS;
    }

    // Filter: Target port 9999
    if (udph->dest == bpf_htons(TARGET_PORT)) {

        /* ------------------ FORWARDING (HAIRPIN / ECHO) ------------------ */

        // Swap Ethernet Source and Destination MAC addresses
        __u8 tmp_mac[ETH_ALEN];
        __builtin_memcpy(tmp_mac, eth->h_source, ETH_ALEN);
        __builtin_memcpy(eth->h_source, eth->h_dest, ETH_ALEN);
        __builtin_memcpy(eth->h_dest, tmp_mac, ETH_ALEN);

        // Swap IP Source and Destination addresses
        __be32 tmp_ip = iph->saddr;
        iph->saddr = iph->daddr;
        iph->daddr = tmp_ip;

        // Swap UDP Source and Destination ports
        __be16 tmp_port = udph->source;
        udph->source = udph->dest;
        udph->dest = tmp_port;

        // Recalculate checksum for the modified IP header
        update_iph_checksum(iph);

        // In production, UDP checksum calculation is offloaded to the NIC hardware.
        // We set it to 0 (disabled for IPv4) to avoid calculation latency overhead.
        udph->check = 0; 

        // Crucial ULL Instruction: TX (transmit) the modified packet straight 
        // back out the RX ring buffer of the network card interface.
        return XDP_TX; 
    }

    // All other traffic passes through normally to the OS kernel
    return XDP_PASS;
}

