### 2. The Control Plane Loader: `loader.c`

This program runs in user-space to load the bytecode, bind it to an interface, and keep it active.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <net/if.h>
#include <bpf/libbpf.h>
#include <bpf/bpf.h>

int main(int argc, char **argv) {
    if (argc < 3) {
        fprintf(stderr, "Usage: %s <interface_name> <bpf_obj_file>\n", argv[0]);
        return 1;
    }

    const char *if_name = argv[1];
    const char *file_path = argv[2];

    // Get interface index
    unsigned int ifindex = if_nametoindex(if_name);
    if (ifindex == 0) {
        perror("Failed to locate interface index");
        return 1;
    }

    // Load eBPF/XDP object file
    struct bpf_object *obj = bpf_object__open_file(file_path, NULL);
    if (libbpf_get_error(obj)) {
        fprintf(stderr, "Error: Failed to open BPF object file.\n");
        return 1;
    }

    if (bpf_object__load(obj)) {
        fprintf(stderr, "Error: Failed to load BPF object to kernel.\n");
        return 1;
    }

    // Find the XDP program inside the object file
    struct bpf_program *prog = bpf_object__find_program_by_name(obj, "xdp_packet_handler");
    if (!prog) {
        fprintf(stderr, "Error: Failed to find program 'xdp_packet_handler'.\n");
        return 1;
    }

    int prog_fd = bpf_program__fd(prog);

    // Attach to network interface using XDP DRV mode (driver level - ULL)
    // Falls back to SKB mode (generic) if the NIC driver doesn't support native XDP.
    __u32 flags = XDP_FLAGS_DRV_MODE; 
    printf("Attaching XDP program to interface %s (index %d)...\n", if_name, ifindex);

    int err = bpf_xdp_attach(ifindex, prog_fd, flags, NULL);
    if (err < 0) {
        printf("Native driver mode unsupported, falling back to Generic SKB mode...\n");
        flags = XDP_FLAGS_SKB_MODE;
        err = bpf_xdp_attach(ifindex, prog_fd, flags, NULL);
        if (err < 0) {
            fprintf(stderr, "Error: Failed to attach XDP program.\n");
            return 1;
        }
    }

    printf("Successfully attached ULL engine! Press Ctrl+C to detach and exit.\n");
    while (1) {
        sleep(1);
    }

    // Detach cleanup
    bpf_xdp_detach(ifindex, flags, NULL);
    return 0;
}
