### Part 1: The Data Plane (XDP Program in C)
Save this file as `xdp_filter_forward.c`. This code runs in the kernel at the driver level.

```c
#include <linux/bpf.h>
#include <linux/if_ether.h>
#include <linux/ip.h>
#include <linux/udp.h>
#include <linux/in.h>
#include <bpf/bpf_helpers.h>

// Define a BPF map to hold the blacklisted IPv4 addresses (Filtering)
struct {
    __uint(type, BPF_MAP_TYPE_HASH);
    __type(key, __u32);   // IP Address
    __type(value, __u8);  // Dummy value (1 = blocked)
    __uint(max_entries, 10240);
} blacklist_map SEC(".maps");

// Helper function to swap MAC addresses for forwarding
static __always_inline void swap_mac(struct ethhdr *eth) {
    __u8 tmp[ETH_ALEN];
    __builtin_memcpy(tmp, eth->h_dest, ETH_ALEN);
    __builtin_memcpy(eth->h_dest, eth->h_source, ETH_ALEN);
    __builtin_memcpy(eth->h_source, tmp, ETH_ALEN);
}

// Helper function to swap IP addresses for forwarding
static __always_inline void swap_ip(struct iphdr *iph) {
    __be32 tmp = iph->saddr;
    iph->saddr = iph->daddr;
    iph->daddr = tmp;
}

SEC("xdp")
int xdp_packet_processor(struct xdp_md *ctx) {
    // Pointers to the start and end of the raw packet data
    void *data_end = (void *)(long)ctx->data_end;
    void *data = (void *)(long)ctx->data;

    // 1. Parse Ethernet Header
    struct ethhdr *eth = data;
    if ((void *)(eth + 1) > data_end) {
        return XDP_PASS; // Packet too small, let kernel handle it
    }

    // We only care about IPv4 traffic
    if (eth->h_proto != __constant_htons(ETH_P_IP)) {
        return XDP_PASS;
    }

    // 2. Parse IP Header
    struct iphdr *iph = (void *)(eth + 1);
    if ((void *)(iph + 1) > data_end) {
        return XDP_PASS;
    }

    // --- FILTERING STEP ---
    // Check if the source IP is in our blacklist map
    __u32 src_ip = iph->saddr;
    __u8 *blocked = bpf_map_lookup_elem(&blacklist_map, &src_ip);
    if (blocked && *blocked == 1) {
        // Ultra-low-latency drop: packet is discarded immediately at the NIC
        return XDP_DROP;
    }

    // 3. Parse UDP Header
    if (iph->protocol == IPPROTO_UDP) {
        struct udphdr *udph = (void *)(iph + 1);
        if ((void *)(udph + 1) > data_end) {
            return XDP_PASS;
        }

        // --- FORWARDING STEP ---
        // Example: If packet is sent to UDP port 9999, swap addresses and send it back
        if (udph->dest == __constant_htons(9999)) {
            // Swap MAC and IP addresses (hairpin forwarding)
            swap_mac(eth);
            swap_ip(iph);

            // Recompute a basic IP checksum (in production, use incremental updates)
            iph->check = 0;
            // Simplistic checksum calculation for XDP
            __u32 csum = 0;
            __u16 *next_iph_u16 = (__u16 *)iph;
            #pragma clang loop unroll(full)
            for (int i = 0; i < 10; i++) {
                csum += next_iph_u16[i];
            }
            iph->check = ~((csum & 0xffff) + (csum >> 16));

            // XDP_TX sends the packet back out of the same NIC interface it arrived on
            return XDP_TX;
        }
    }

    // Pass all other traffic to the normal Linux network stack
    return XDP_PASS;
}

