### The Code: `xdp_filter.c`

This program inspects incoming packets:
1. **Filters** out anything that isn't IPv4 UDP.
2. **Drops** packets coming from a specific blocked IP address (firewall).
3. **Forwards** packets aimed at UDP port `9999` back out of the same network interface (`XDP_TX`) after swapping the source/destination MAC and IP addresses (hairpin/reflection forwarding).
4. **Passes** all other traffic safely up to the standard Linux OS kernel network stack (`XDP_PASS`).

```c
#include <linux/bpf.h>
#include <linux/if_ether.h>
#include <linux/ip.h>
#include <linux/udp.h>
#include <bpf/bpf_helpers.h>
#include <bpf/bpf_endian.h>

#define TARGET_PORT 9999
#define BLOCKED_IP 0xC0A80164 // 192.168.1.100 in Hex (Big Endian)

SEC("xdp")
int xdp_packet_handler(struct xdp_md *ctx) {
    // Pointers to the start and end of packet data in the NIC ring buffer
    void *data_end = (void *)(long)ctx->data_end;
    void *data     = (void *)(long)ctx->data;

    // 1. Parse Ethernet Header
    struct ethhdr *eth = data;
    if ((void *)(eth + 1) > data_end) {
        return XDP_PASS; // Fail-safe: packet is malformed/too short
    }

    // Only process IPv4 traffic
    if (eth->h_proto != bpf_htons(ETH_P_IP)) {
        return XDP_PASS;
    }

    // 2. Parse IP Header
    struct iphdr *iph = (void *)(eth + 1);
    if ((void *)(iph + 1) > data_end) {
        return XDP_PASS;
    }

    // Filter: Drop packets from our blacklisted IP (192.168.1.100)
    if (iph->saddr == bpf_htonl(BLOCKED_IP)) {
        return XDP_DROP; // Packet is instantly dropped at the NIC level
    }

    // Only process UDP traffic
    if (iph->protocol != IPPROTO_UDP) {
        return XDP_PASS;
    }

    // 3. Parse UDP Header
    struct udphdr *udph = (void *)(iph + 1);
    if ((void *)(udph + 1) > data_end) {
        return XDP_PASS;
    }

    // 4. Packet-Level Filtering & Forwarding
    if (udph->dest == bpf_htons(TARGET_PORT)) {

        // Swap Source and Destination MAC addresses
        unsigned char tmp_mac[ETH_ALEN];
        __builtin_memcpy(tmp_mac, eth->h_dest, ETH_ALEN);
        __builtin_memcpy(eth->h_dest, eth->h_source, ETH_ALEN);
        __builtin_memcpy(eth->h_source, tmp_mac, ETH_ALEN);

        // Swap Source and Destination IP addresses
        __u32 tmp_ip = iph->daddr;
        iph->daddr = iph->saddr;
        iph->saddr = tmp_ip;

        // Note: For ultra-low-latency, we bypass deep checksum re-calculations.
        // For UDP, we can set checksum to 0 (disabled) to save CPU cycles,
        // which is standard practice in low-latency systems where upper layers handle integrity.
        udph->check = 0;

        // Forward the modified packet back out of the exact interface it arrived on
        return XDP_TX;
    }

    // Pass everything else to the normal Linux TCP/IP stack
    return XDP_PASS;
}

