#include <linux/if_ether.h>
#include <linux/ip.h>
#include <linux/udp.h>
#include <bpf/bpf_helpers.h>
#include <bpf/bpf_endian.h>

// Helper to swap MAC addresses
static __always_inline void swap_mac(struct ethhdr *eth) {
    __u8 tmp[ETH_ALEN];
    __builtin_memcpy(tmp, eth->h_source, ETH_ALEN);
    __builtin_memcpy(eth->h_source, eth->h_dest, ETH_ALEN);
    __builtin_memcpy(eth->h_dest, tmp, ETH_ALEN);
}

// Helper to swap IP addresses
static __always_inline void swap_ip(struct iphdr *iph) {
    __be32 tmp = iph->saddr;
    iph->saddr = iph->daddr;
    iph->daddr = tmp;
}

SEC("xdp")
int xdp_packet_processor(struct xdp_md *ctx) {
    // Memory boundaries of the raw packet
    void *data_end = (void *)(long)ctx->data_end;
    void *data = (void *)(long)ctx->data;

    // 1. Parse Ethernet Header
    struct ethhdr *eth = data;
    if ((void *)(eth + 1) > data_end) {
        return XDP_PASS; // Packet too small, let kernel handle it
    }

    // Only process IPv4 traffic
    if (eth->h_proto != bpf_htons(ETH_P_IP)) {
        return XDP_PASS;
    }

    // 2. Parse IP Header
    struct iphdr *iph = (void *)(eth + 1);
    if ((void *)(iph + 1) > data_end) {
        return XDP_PASS;
    }

    // Only process UDP traffic
    if (iph->protocol != IPPROTO_UDP) {
        return XDP_PASS;
    }

    // 3. Parse UDP Header
    struct udphdr *udph = (void *)(iph + 1);
    if ((void *)(udph + 1) > data_end) {
        return XDP_PASS;
    }

    // --- FILTERING LOGIC ---
    // If packet matches port 9999, drop it instantly.
    // This happens before the CPU allocates OS socket memory.
    if (udph->dest == bpf_htons(9999)) {
        return XDP_DROP;
    }

    // --- FORWARDING/REFLECTION LOGIC ---
    // If packet is destined for port 8888, swap headers and bounce it back.
    if (udph->dest == bpf_htons(8888)) {
        swap_mac(eth);
        swap_ip(iph);

        // Note: Because we only swapped source/destination IPs, 
        // the IPv4 checksum remains mathematically identical. No recalculation needed!

        // Swap UDP ports to send it back to the sender's source port
        __be16 temp_port = udph->source;
        udph->source = udph->dest;
        udph->dest = temp_port;

        // Force UDP checksum to 0 (optional/disabled checksum) to avoid recalculation overhead
        udph->check = 0; 

        // Send packet back out of the exact same network interface it entered
        return XDP_TX;
    }

    // Allow all other traffic (SSH, TCP, other UDP) to flow to the OS normal stack
    return XDP_PASS;
}

