### 1. The XDP Kernel Code (`xdp_fw.c`)

Save this file as `xdp_fw.c`. This code runs directly inside the network driver kernel space.

```c
#include <linux/bpf.h>
#include <linux/if_ether.h>
#include <linux/ip.h>
#include <linux/udp.h>
#include <bpf/bpf_helpers.h>

// Helper to convert 16-bit integers from network-to-host byte order
#define SEC(NAME) __attribute__((section(NAME), used))

SEC("xdp")
int xdp_filter_forward(struct xdp_md *ctx) {
    void *data_end = (void *)(long)ctx->data_end;
    void *data = (void *)(long)ctx->data;

    // 1. Parse Ethernet Header
    struct ethhdr *eth = data;
    if ((void *)(eth + 1) > data_end) {
        return XDP_PASS; // Pass packet if boundary check fails
    }

    // Only process IPv4 packets
    if (eth->h_proto != __constant_htons(ETH_P_IP)) {
        return XDP_PASS;
    }

    // 2. Parse IP Header
    struct iphdr *iph = (void *)(eth + 1);
    if ((void *)(iph + 1) > data_end) {
        return XDP_PASS;
    }

    // Only process UDP packets
    if (iph->protocol != IPPROTO_UDP) {
        return XDP_PASS;
    }

    // 3. Parse UDP Header
    struct udphdr *udph = (void *)(iph + 1);
    if ((void *)(udph + 1) > data_end) {
        return XDP_PASS;
    }

    // Read the destination port (Network Byte Order conversion)
    __u16 dest_port = __constant_ntohs(udph->dest);

    // --- RULE 1: FILTERING (Drop port 9999) ---
    if (dest_port == 9999) {
        return XDP_DROP; // Packet discarded at the NIC driver level
    }

    // --- RULE 2: FORWARDING / HAIRPIN (Forward port 8888) ---
    if (dest_port == 8888) {
        // Swap MAC addresses
        __u8 tmp_mac[ETH_ALEN];
        __builtin_memcpy(tmp_mac, eth->h_dest, ETH_ALEN);
        __builtin_memcpy(eth->h_dest, eth->h_source, ETH_ALEN);
        __builtin_memcpy(eth->h_source, tmp_mac, ETH_ALEN);

        // Swap IP addresses
        __be32 tmp_ip = iph->daddr;
        iph->daddr = iph->saddr;
        iph->saddr = tmp_ip;

        // Recalculate trivial checksums (or let NIC handle checksum offloading)
        // In ultra-low latency, hardware checksum offloading is preferred.
        iph->check = 0; // Simple clear to force driver re-evaluation if supported

        // XDP_TX bounces the packet back out of the same interface it came in
        return XDP_TX;
    }

    // Pass all other traffic to the standard Linux network stack
    return XDP_PASS;
}

