#include <linux/ip.h>
#include <linux/udp.h>
#include <bpf/bpf_helpers.h>

// Standard helper for networking byte order (big endian to little endian)
#ifndef htons
#define htons(n) __constant_htons(n)
#endif

SEC("xdp")
int xdp_filter_forward(struct xdp_md *ctx) {
    // Pointers to the start and end of the raw packet data
    void *data_end = (void *)(long)ctx->data_end;
    void *data     = (void *)(long)ctx->data;

    // 1. Parse Ethernet Header
    struct ethhdr *eth = data;
    if ((void *)(eth + 1) > data_end) {
        return XDP_PASS; // Out of bounds safety check
    }

    // Only process IPv4 traffic
    if (eth->h_proto != htons(ETH_P_IP)) {
        return XDP_PASS;
    }

    // 2. Parse IP Header
    struct iphdr *iph = (void *)(eth + 1);
    if ((void *)(iph + 1) > data_end) {
        return XDP_PASS;
    }

    // Only process UDP traffic
    if (iph->protocol != IPPROTO_UDP) {
        return XDP_PASS;
    }

    // 3. Parse UDP Header
    struct udphdr *udph = (void *)(iph + 1);
    if ((void *)(udph + 1) > data_end) {
        return XDP_PASS;
    }

    // 4. Filtering Logic: Match destination port 9999
    if (udph->dest == htons(9999)) {

        // 5. Forwarding Logic: Swap MAC addresses to send the packet back to sender
        __u8 tmp_mac[ETH_ALEN];
        __builtin_memcpy(tmp_mac, eth->h_dest, ETH_ALEN);
        __builtin_memcpy(eth->h_dest, eth->h_source, ETH_ALEN);
        __builtin_memcpy(eth->h_source, tmp_mac, ETH_ALEN);

        // Optionally swap IPs as well to make it a true loopback
        __be32 tmp_ip = iph->daddr;
        iph->daddr = iph->saddr;
        iph->saddr = tmp_ip;

        // XDP_TX tells the NIC to transmit the modified packet straight back out
        return XDP_TX;
    }

    // Allow all other traffic to proceed to the OS network stack
    return XDP_PASS;
}

