#include <linux/bpf.h>
#include <linux/if_ether.h>
#include <linux/ip.h>
#include <linux/udp.h>
#include <bpf/bpf_helpers.h>

// Helper to swap MAC addresses
static __always_inline void swap_mac(struct ethhdr *eth) {
    __u8 tmp[ETH_ALEN];
    __builtin_memcpy(tmp, eth->h_dest, ETH_ALEN);
    __builtin_memcpy(eth->h_dest, eth->h_source, ETH_ALEN);
    __builtin_memcpy(eth->h_source, tmp, ETH_ALEN);
}

// Helper to swap IP addresses
static __always_inline void swap_ip(struct iphdr *iph) {
    __be32 tmp = iph->daddr;
    iph->daddr = iph->saddr;
    iph->saddr = tmp;
}

SEC("xdp")
int xdp_prog(struct xdp_md *ctx) {
    // Pointers to the start and end of packet data in the NIC ring buffer
    void *data_end = (void *)(long)ctx->data_end;
    void *data = (void *)(long)ctx->data;

    // 1. Parse Ethernet Header
    struct ethhdr *eth = data;
    if ((void *)(eth + 1) > data_end) {
        return XDP_PASS; // Packet too small, let kernel handle it
    }

    // Only process IPv4 traffic
    if (eth->h_proto != __constant_htons(ETH_P_IP)) {
        return XDP_PASS;
    }

    // 2. Parse IP Header
    struct iphdr *iph = (void *)(eth + 1);
    if ((void *)(iph + 1) > data_end) {
        return XDP_PASS;
    }

    // Only process UDP traffic
    if (iph->protocol != IPPROTO_UDP) {
        return XDP_PASS;
    }

    // 3. Parse UDP Header
    struct udphdr *udph = (void *)(iph + 1);
    if ((void *)(udph + 1) > data_end) {
        return XDP_PASS;
    }

    // Define our target ports (Network Byte Order)
    __u16 filter_port = __constant_htons(12345);
    __u16 forward_port = __constant_htons(9999);

    // --- FILTER ACTION ---
    if (udph->dest == filter_port) {
        // Drop the packet instantly at the driver level (firewall)
        return XDP_DROP;
    }

    // --- FORWARD ACTION ---
    if (udph->dest == forward_port) {
        // Swap MACs and IPs to route back to the sender
        swap_mac(eth);
        swap_ip(iph);

        // Swap UDP ports so it goes back to sender's source port
        __be16 tmp_port = udph->dest;
        udph->dest = udph->source;
        udph->source = tmp_port;

        // Clear IP checksum for hardware recalculation
        iph->check = 0; 

        // XDP_TX sends the modified packet back out the same NIC interface it arrived on
        return XDP_TX; 
    }

    // Pass all other packets to the normal Linux networking stack
    return XDP_PASS;
}

