use std::env;
use std::io;
use std::mem;
use std::os::unix::io::RawFd;

// Constants for packet parsing (Network Byte Order / Big Endian)
const ETH_P_ALL: u16 = 0x0003; // Capture all packets
const ETHERTYPE_IPV4: u16 = 0x0800;
const IPPROTO_UDP: u8 = 17;
const TARGET_PORT: u16 = 9999; // Filter: only forward UDP packets targeting port 9999

fn main() -> io::Result<()> {
    let args: Vec<String> = env::args().collect();
    if args.len() < 3 {
        eprintln!("Usage: {} <ingress_interface> <egress_interface>", args[0]);
        std::process::exit(1);
    }

    let ingress_if = &args[1];
    let egress_if = &args[2];

    println!("Starting latency-optimized engine...");
    println!("Filtering UDP Port {} on {} -> Forwarding to {}", TARGET_PORT, ingress_if, egress_if);

    // 1. Get interface indices
    let ingress_idx = get_interface_index(ingress_if)?;
    let egress_idx = get_interface_index(egress_if)?;

    // 2. Create raw sockets for zero-copy packet capture and injection
    let rx_sock = create_raw_socket(ingress_idx)?;
    let tx_sock = create_raw_socket(egress_idx)?;

    // 3. Pre-allocate packet buffer on the STACK (Zero-allocation in hot path)
    // MTU is typically 1500, 2048 bytes is plenty. No heap allocation.
    let mut buffer = [0u8; 2048];

    // Prepare TX sockaddr structure once to avoid rebuilding it in the loop
    let mut tx_addr: libc::sockaddr_ll = unsafe { mem::zeroed() };
    tx_addr.sll_family = libc::AF_PACKET as u16;
    tx_addr.sll_ifindex = egress_idx as i32;
    tx_addr.sll_halen = 6; // Ethernet MAC address length

    loop {
        // --- READ PATH ---
        let n = unsafe {
            libc::recv(
                rx_sock,
                buffer.as_mut_ptr() as *mut libc::c_void,
                buffer.len(),
                0,
            )
        };

        if n < 0 {
            let err = io::Error::last_os_error();
            if err.kind() == io::ErrorKind::WouldBlock {
                continue;
            }
            eprintln!("Recv error: {}", err);
            continue;
        }

        let packet_len = n as usize;
        let packet = &mut buffer[..packet_len];

        // --- FILTER PATH (Zero-copy parsing) ---
        if let Some(payload_offset) = should_forward(packet) {
            // OPTIONAL: Modify packet headers here (e.g., rewriting MAC addresses)
            // For low latency, we perform minimal mutations.

            // --- FORWARD PATH ---
            let sent = unsafe {
                libc::sendto(
                    tx_sock,
                    packet.as_ptr() as *const libc::c_void,
                    packet_len,
                    0,
                    &tx_addr as *const libc::sockaddr_ll as *const libc::sockaddr,
                    mem::size_of::<libc::sockaddr_ll>() as libc::socklen_t,
                )
            };

            if sent < 0 {
                eprintln!("Forwarding failed: {}", io::Error::last_os_error());
            }
        }
    }
}

/// Zero-copy packet parser. 
/// Returns `Some(payload_offset)` if the packet passes filters, `None` to drop.
#[inline(always)]
fn should_forward(packet: &[u8]) -> Option<usize> {
    // 1. Parse Ethernet Header (Min 14 bytes)
    if packet.len() < 14 { return None; }
    let ethertype = u16::from_be_bytes([packet[12], packet[13]]);
    if ethertype != ETHERTYPE_IPV4 { return None; }

    // 2. Parse IPv4 Header (Min 20 bytes)
    let ip_start = 14;
    if packet.len() < ip_start + 20 { return None; }

    let ihl = (packet[ip_start] & 0x0F) as usize * 4; // IP Header Length
    let protocol = packet[ip_start + 9];
    if protocol != IPPROTO_UDP { return None; }

    // 3. Parse UDP Header (8 bytes)
    let udp_start = ip_start + ihl;
    if packet.len() < udp_start + 8 { return None; }

    let dst_port = u16::from_be_bytes([packet[udp_start + 2], packet[udp_start + 3]]);

    // Filter condition: target UDP port matches
    if dst_port == TARGET_PORT {
        Some(udp_start + 8) // Return offset to actual UDP data payload
    } else {
        None
    }
}

/// Creates and binds a raw AF_PACKET socket to a specific interface index
fn create_raw_socket(interface_index: u32) -> io::Result<RawFd> {
    unsafe {
        // Create socket to bypass TCP/IP stack
        let sock = libc::socket(
            libc::AF_PACKET,
            libc::SOCK_RAW,
            (ETH_P_ALL as u16).to_be() as libc::c_int,
        );
        if sock < 0 {
            return Err(io::Error::last_os_error());
        }

        // Bind socket directly to the hardware/virtual interface
        let mut saddr: libc::sockaddr_ll = mem::zeroed();
        saddr.sll_family = libc::AF_PACKET as u16;
        saddr.sll_protocol = (ETH_P_ALL as u16).to_be();
        saddr.sll_ifindex = interface_index as i32;

        let res = libc::bind(
            sock,
            &saddr as *const libc::sockaddr_ll as *const libc::sockaddr,
            mem::size_of::<libc::sockaddr_ll>() as libc::socklen_t,
        );

        if res < 0 {
            libc::close(sock);
            return Err(io::Error::last_os_error());
        }

        // Enable socket performance optimizations (Increase Ring Buffer sizes)
        let rcvbuf_size: libc::c_int = 1024 * 1024 * 8; // 8MB Buffer
        libc::setsockopt(
            sock,
            libc::SOL_SOCKET,
            libc::SO_RCVBUFFORCE,
            &rcvbuf_size as *const libc::c_int as *const libc::c_void,
            mem::size_of::<libc::c_int>() as libc::socklen_t,
        );

        Ok(sock)
    }
}

/// Resolves string interface name (like "eth0") to kernel OS index
fn get_interface_index(name: &str) -> io::Result<u32> {
    let c_name = std::ffi::CString::new(name)?;
    let idx = unsafe { libc::if_nametoindex(c_name.as_ptr()) };
    if idx == 0 {
        return Err(io::Error::last_os_error());
    }
    Ok(idx)
}
