#include <iostream>
#include <cstring>
#include <string>
#include <vector>
#include <thread>
#include <sched.h>
#include <unistd.h>
#include <sys/socket.h>
#include <sys/ioctl.h>
#include <netpacket/packet.h>
#include <net/ethernet.h>
#include <netinet/ip.h>
#include <netinet/udp.h>
#include <net/if.h>
#include <arpa/inet.h>

// Helper to pin the current thread to a specific CPU core
bool pin_to_core(int core_id) {
    cpu_set_set_t cpuset;
    CPU_ZERO(&cpuset);
    CPU_SET(core_id, &cpuset);
    pthread_t current_thread = pthread_self();
    return pthread_setaffinity_np(current_thread, sizeof(cpu_set_t), &cpuset) == 0;
}

// Helper to create and bind a raw socket to a specific interface
int create_raw_socket(const std::string& interface_name) {
    // SOCK_RAW allows us to get the raw Ethernet frame (including MAC headers)
    int sock = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
    if (sock < 0) {
        perror("Socket creation failed");
        return -1;
    }

    // Get the interface index
    struct ifreq ifr;
    std::memset(&ifr, 0, sizeof(ifr));
    std::strncpy(ifr.ifr_name, interface_name.c_str(), IFNAMSIZ - 1);
    if (ioctl(sock, SIOCGIFINDEX, &ifr) < 0) {
        perror("Failed to get interface index");
        close(sock);
        return -1;
    }

    // Bind socket to the interface
    struct sockaddr_ll sll;
    std::memset(&sll, 0, sizeof(sll));
    sll.sll_family = AF_PACKET;
    sll.sll_ifindex = ifr.ifr_ifindex;
    sll.sll_protocol = htons(ETH_P_ALL);

    if (bind(sock, (struct sockaddr*)&sll, sizeof(sll)) < 0) {
        perror("Failed to bind socket");
        close(sock);
        return -1;
    }

    // Set socket to non-blocking for busy-polling
    int flags = fcntl(sock, F_GETFL, 0);
    fcntl(sock, F_SETFL, flags | O_NONBLOCK);

    return sock;
}

int main(int argc, char* argv[]) {
    if (argc < 4) {
        std::cerr << "Usage: " << argv[0] << " <ingress_if> <egress_if> <cpu_core_id>\n";
        return 1;
    }

    std::string ingress_if = argv[1];
    std::string egress_if = argv[2];
    int core_id = std::stoi(argv[3]);

    // 1. Pin to dedicated CPU core for deterministic execution times
    if (pin_to_core(core_id)) {
        std::cout << "[INFO] Successfully pinned thread to CPU Core " << core_id << "\n";
    } else {
        std::cerr << "[WARNING] Failed to pin thread to CPU Core " << core_id << "\n";
    }

    // 2. Initialize Ingress and Egress sockets
    int rx_sock = create_raw_socket(ingress_if);
    int tx_sock = create_raw_socket(egress_if);

    if (rx_sock < 0 || tx_sock < 0) {
        return 1;
    }

    std::cout << "[INFO] Listening on " << ingress_if << ", forwarding matching traffic to " << egress_if << "...\n";

    // 3. Align buffer to 64-byte boundary (CPU Cache Line) to prevent false sharing/cache misses
    alignas(64) uint8_t packet_buffer[2048]; 

    // Target filter: UDP Port 9999
    constexpr uint16_t TARGET_PORT = 9999;

    // 4. Fast-Path Packet Loop (Busy-Poll)
    while (true) {
        // Non-blocking read (Zero Context Switch)
        ssize_t packet_len = recv(rx_sock, packet_buffer, sizeof(packet_buffer), MSG_DONTWAIT);

        if (packet_len < 0) [[likely]] {
            if (errno == EAGAIN || errno == EWOULDBLOCK) {
                // Socket empty; spin immediately to minimize latency
                continue; 
            }
            perror("Recv error");
            break;
        }

        // --- Start Zero-Copy Packet Parsing ---
        if (packet_len < (ssize_t)(sizeof(struct ethhdr) + sizeof(struct iphdr))) [[unlikely]] {
            continue; // Runt packet, drop
        }

        // Cast Ethernet Header
        auto* eth = reinterpret_cast<struct ethhdr*>(packet_buffer);

        // Filter 1: IP Packets only
        if (ntohs(eth->h_proto) == ETH_P_IP) {
            auto* ip = reinterpret_cast<struct iphdr*>(packet_buffer + sizeof(struct ethhdr));

            // Filter 2: UDP Packets only
            if (ip->protocol == IPPROTO_UDP) {
                // Calculate IP header offset (handles variable header sizes)
                uint32_t ip_header_len = ip->ihl * 4;
                auto* udp = reinterpret_cast<struct udphdr*>(packet_buffer + sizeof(struct ethhdr) + ip_header_len);

                uint16_t dest_port = ntohs(udp->dest);

                // Filter 3: Match destination port 9999
                if (dest_port == TARGET_PORT) [[unlikely]] {

                    // --- Forward Packet ---
                    // Send out raw packet unmodified to the egress socket
                    ssize_t sent = send(tx_sock, packet_buffer, packet_len, MSG_DONTWAIT);

                    if (sent < 0) [[unlikely]] {
                        // In high-throughput, drop packets if egress ring buffer is full
                        continue; 
                    }
                }
            }
        }
    }

    close(rx_sock);
    close(tx_sock);
    return 0;
}
```

