use byteorder::{BigEndian, ByteOrder};
use std::io::{self, Cursor, Read, Write};

const BUFFER_CAPACITY: usize = 65536; // 64 KB fixed buffer

/// A zero-copy, streaming frame reader.
pub struct ZeroCopyFrameReader<R: Read> {
    reader: R,
    buffer: Vec<u8>,
    head: usize, // Pointer to the start of unparsed data in the buffer
    tail: usize, // Pointer to the end of valid data in the buffer
    eof: bool,   // Track if the underlying reader hit EOF
}

impl<R: Read> ZeroCopyFrameReader<R> {
    pub fn new(reader: R) -> Self {
        Self {
            reader,
            buffer: vec![0u8; BUFFER_CAPACITY],
            head: 0,
            tail: 0,
            eof: false,
        }
    }

    /// Pulls the next frame from the stream.
    /// Returns `Ok(Some(payload))` pointing directly to the internal buffer,
    /// `Ok(None)` on clean EOF, or an error.
    pub fn next_frame(&mut self) -> io::Result<Option<&[u8]>> {
        loop {
            let available = self.tail - self.head;

            // 1. We need at least 4 bytes to read the frame length (u32)
            if available >= 4 {
                let frame_len = BigEndian::read_u32(&self.buffer[self.head..self.head + 4]) as usize;
                let total_record_len = 4 + frame_len;

                // Ensure a single record isn't larger than our buffer safety limit
                if total_record_len > self.buffer.len() {
                    return Err(io::Error::new(
                        io::ErrorKind::InvalidData,
                        "Frame size exceeds maximum buffer capacity",
                    ));
                }

                // 2. Check if the entire frame payload is in the buffer
                if available >= total_record_len {
                    let start = self.head + 4;
                    let end = self.head + total_record_len;
                    self.head = end; // Advance head pointer
                    return Ok(Some(&self.buffer[start..end]));
                }
            }

            // If we've reached EOF and don't have enough bytes for a full frame, it's an error
            if self.eof {
                if available == 0 {
                    return Ok(None); // Clean EOF
                } else {
                    return Err(io::Error::new(
                        io::ErrorKind::UnexpectedEof,
                        "Incomplete frame at end of stream",
                    ));
                }
            }

            // 3. Compact buffer: Shift remaining bytes to the beginning of the buffer
            if self.head > 0 {
                self.buffer.copy_within(self.head..self.tail, 0);
                self.tail -= self.head;
                self.head = 0;
            }

            // 4. Fill the remaining space in the buffer from the reader
            let bytes_read = self.reader.read(&mut self.buffer[self.tail..])?;
            if bytes_read == 0 {
                self.eof = true;
            } else {
                self.tail += bytes_read;
            }
        }
    }
}

