    /// This callback-based design bypasses Rust borrow-checker limitations 
    /// with streaming iterators, allowing ultra-fast zero-copy loops.
    pub fn parse_all<F>(&mut self, mut handler: F) -> io::Result<()>
    where
        F: FnMut(Record<'_>),
    {
