                let id = u64::from_be_bytes(available[4..12].try_into().unwrap());
                let timestamp = u64::from_be_bytes(available[12..20].try_into().unwrap());
                let value = f64::from_be_bytes(available[20..28].try_into().unwrap());
                let payload_len = u32::from_be_bytes(available[28..32].try_into().unwrap()) as usize;

                let total_record_size = 32 + payload_len;

                if available.len() >= total_record_size {
                    // We have the full payload in memory! Yield the record.
                    let payload_start = self.cursor + 32;
                    let payload_end = self.cursor + total_record_size;

                    let record = Record {
                        id,
                        timestamp,
                        value,
                        payload: &self.buffer[payload_start..payload_end],
                    };

                    handler(record);

                    // Advance cursor past this record
                    self.cursor += total_record_size;
