        let mut parts = line.splitn(3, |&b| b == b',');

        let timestamp_raw = parts.next()?;
        let level_raw = parts.next()?;
        let message_raw = parts.next()?;

        // Perform zero-copy conversion to UTF-8
        let timestamp = std::str::from_utf8(timestamp_raw).ok()?;
        let level = std::str::from_utf8(level_raw).ok()?;
        let message = std::str::from_utf8(message_raw).ok()?;

        Some(Record {
            timestamp,
            level,
            message,
        })
    }
