/// High-throughput streaming parser
pub struct ZeroCopyStreamParser<R> {
    reader: R,
    buffer: Vec<u8>,
}

impl<R: Read> ZeroCopyStreamParser<R> {
    /// Creates a parser with a fixed-size buffer (e.g., 64KB)
    pub fn new(reader: R, buffer_size: usize) -> Self {
        Self {
            reader,
            buffer: vec![0; buffer_size],
        }
    }

    /// Parses the stream, executing the callback for each parsed record.
    pub fn parse_all<F>(&mut self, mut callback: F) -> io::Result<()>
    where
        F: FnMut(Record<'_>),
    {
        let mut write_pos = 0; // Where to write new bytes from stream
        let mut read_pos = 0;  // Start of the current unparsed data

        loop {
            // 1. Shift remaining unparsed data to the beginning of the buffer
            if read_pos > 0 {
                self.buffer.copy_within(read_pos..write_pos, 0);
                write_pos -= read_pos;
                read_pos = 0;
            }

            // 2. Read new chunk from stream into remaining buffer space
            let bytes_read = self.reader.read(&mut self.buffer[write_pos..])?;
            if bytes_read == 0 {
                // EOF reached: parse any trailing data without a trailing newline
                if write_pos > read_pos {
                    if let Some(record) = Record::parse(&self.buffer[read_pos..write_pos]) {
                        callback(record);
                    }
                }
                break;
            }
            write_pos += bytes_read;

            // 3. Scan buffer for delimiters ('\n')
            let mut scan_pos = read_pos;
            while scan_pos < write_pos {
                if self.buffer[scan_pos] == b'\n' {
                    let line = &self.buffer[read_pos..scan_pos];
                    if let Some(record) = Record::parse(line) {
                        callback(record);
                    }
                    read_pos = scan_pos + 1;
                }
                scan_pos += 1;
            }

            // 4. Handle buffer overflow safety (prevents memory inflation)
            if read_pos == 0 && write_pos == self.buffer.len() {
                return Err(io::Error::new(
                    io::ErrorKind::InvalidData,
                    "Line size exceeded maximum buffer capacity",
                ));
            }
        }

        Ok(())
    }
}

