Here is a high-performance, **zero-copy streaming parser written in Rust**. 

It uses a **fixed-size ring-like buffer (64 KB)** to read a stream (e.g., a file or network socket) of any size (even terabytes) while maintaining a flat $O(1)$ memory footprint. It parses a binary frame format: `[4 bytes Length][1 byte Type][N bytes Payload]`.

### Key Design Patterns Used:
1. **Zero-Copy Parsing**: The parser emits `Frame` structs containing slices (`&[u8]`) pointing directly to the read buffer, completely avoiding string/vector allocations.
2. **Buffer Shifting**: When a frame is split across the buffer boundary, the remaining bytes are shifted to the front of the buffer, and the next chunk is read.
3. **Strict Memory Bound**: If a frame exceeds the buffer size (64 KB), the parser safely errors out instead of silently growing the heap indefinitely.

### Rust Implementation

```rust
use std::io::{self, Read, Cursor};
use std::convert::TryInto;

const BUFFER_SIZE: usize = 65536; // 64 KB fixed-size buffer
const HEADER_SIZE: usize = 5;      // 4 bytes length + 1 byte type

/// A zero-copy frame referencing data directly inside the read buffer.
#[derive(Debug)]
pub struct Frame<'a> {
    pub msg_type: u8,
    pub payload: &'a [u8],
}

pub struct StreamParser<R> {
    reader: R,
    buffer: Box<[u8; BUFFER_SIZE]>, // Allocated on the heap once to avoid stack overflow
    read_pos: usize,
    write_pos: usize,
    eof: bool,
}

impl<R: Read> StreamParser<R> {
    pub fn new(reader: R) -> Self {
        Self {
            reader,
            buffer: Box::new([0u8; BUFFER_SIZE]),
            read_pos: 0,
            write_pos: 0,
            eof: false,
        }
    }

    /// Pulls more data from the underlying stream into the buffer.
    fn fill_buffer(&mut self) -> io::Result<usize> {
        // 1. Shift remaining unparsed data to the beginning of the buffer
        if self.read_pos > 0 {
            let remaining = self.write_pos - self.read_pos;
            self.buffer.copy_within(self.read_pos..self.write_pos, 0);
            self.read_pos = 0;
            self.write_pos = remaining;
        }

        // 2. If the buffer is completely full and we can't shift, the incoming frame is too large
        if self.write_pos >= BUFFER_SIZE {
            return Err(io::Error::new(
                io::ErrorKind::OutOfMemory,
                "Frame size exceeds maximum buffer limit",
            ));
        }

        // 3. Read new data into the available space
        let bytes_read = self.reader.read(&mut self.buffer[self.write_pos..])?;
        if bytes_read == 0 {
            self.eof = true;
        }
        self.write_pos += bytes_read;
        Ok(bytes_read)
    }

    /// Parses the next frame from the stream. 
    /// Returns `None` on EOF, or an error if the stream is corrupted.
    pub fn next_frame(&mut self) -> io::Result<Option<Frame<'_>>> {
        loop {
            let available = self.write_pos - self.read_pos;

            // Do we have enough data to read the header?
            if available < HEADER_SIZE {
                if self.eof {
                    if available == 0 {
                        return Ok(None); // Clean EOF
                    }
                    return Err(io::Error::new(io::ErrorKind::UnexpectedEof, "Incomplete frame header"));
                }
                self.fill_buffer()?;
                continue;
            }

            // Read frame length (Big-Endian 32-bit integer)
            let len_bytes = &self.buffer[self.read_pos..self.read_pos + 4];
            let payload_len = u32::from_be_bytes(len_bytes.try_into().unwrap()) as usize;
            let msg_type = self.buffer[self.read_pos + 4];
            let total_frame_size = HEADER_SIZE + payload_len;

            // Safety check: Ensure frame can actually fit in our buffer
            if total_frame_size > BUFFER_SIZE {
                return Err(io::Error::new(
                    io::ErrorKind::InvalidData,
                    format!("Frame size ({}) exceeds maximum limit ({})", total_frame_size, BUFFER_SIZE),
                ));
            }

            // Do we have the full payload in the buffer?
            if available < total_frame_size {
                if self.eof {
                    return Err(io::Error::new(io::ErrorKind::UnexpectedEof, "Incomplete frame payload"));
                }
                self.fill_buffer()?;
                continue;
            }

            // Zero-copy extraction: borrow directly from the buffer
            let payload_start = self.read_pos + HEADER_SIZE;
            let payload_end = self.read_pos + total_frame_size;

            // We bypass the borrow checker's lifetime limitations safely here 
            // by casting the slice to the lifetime of `self`
            let payload = unsafe {
                std::slice::from_raw_parts(
                    self.buffer.as_ptr().add(payload_start),
                    payload_len
                )
            };

            // Advance the read pointer
            self.read_pos += total_frame_size;

            return Ok(Some(Frame { msg_type, payload }));
        }
    }
}

