use std::io::{self, Read, Cursor};
use std::str;

// Bounded buffer size (256 KB). Memory overhead is strictly capped here.
const BUFFER_SIZE: usize = 256 * 1024; 
const HEADER_SIZE: usize = 4 + 8 + 2; // ID (4) + Timestamp (8) + Len (2) = 14 bytes

/// A structured zero-copy representation of a parsed record.
/// The `payload` field holds a reference pointing directly to the streaming buffer.
#[derive(Debug)]
pub struct Record<'a> {
    pub id: u32,
    pub timestamp: u64,
    pub payload: &'a str,
}

pub struct StreamParser<R: Read> {
    reader: R,
    buffer: Vec<u8>,
    cursor: usize, // Current read position in the buffer
    limit: usize,  // End of valid data in the buffer
}

impl<R: Read> StreamParser<R> {
    pub fn new(reader: R) -> Self {
        Self {
            reader,
            buffer: vec![0; BUFFER_SIZE],
            cursor: 0,
            limit: 0,
        }
    }

    /// Parses the stream and executes a callback on each parsed record.
    /// Using a callback allows Rust's borrow checker to enforce that zero-copy
    /// references cannot outlive the buffer segment they point to.
    pub fn parse_stream<F>(&mut self, mut on_record: F) -> io::Result<()>
    where
        F: FnMut(Record<'_>),
    {
        loop {
            // 1. Shift remaining unparsed bytes to the beginning of the buffer
            if self.cursor > 0 {
                self.buffer.copy_within(self.cursor..self.limit, 0);
                self.limit -= self.cursor;
                self.cursor = 0;
            }

            // 2. Read new data from the stream to fill the buffer
            let bytes_read = self.reader.read(&mut self.buffer[self.limit..])?;
            if bytes_read == 0 && self.limit == 0 {
                // EOF reached and buffer is empty
                break;
            }
            self.limit += bytes_read;

            // 3. Parse as many records as possible from the buffer
            let mut progress = false;
            while self.cursor + HEADER_SIZE <= self.limit {
                // Peak at header to find the payload length
                let header_start = self.cursor;
                let payload_len = u16::from_be_bytes([
                    self.buffer[header_start + 12],
                    self.buffer[header_start + 13],
                ]) as usize;

                let record_total_size = HEADER_SIZE + payload_len;

                // Check if the entire record is loaded into the buffer
                if self.cursor + record_total_size > self.limit {
                    // Incomplete record: break inner loop to fetch more bytes
                    break;
                }

                // 4. Zero-copy parsing of fields
                let id = u32::from_be_bytes(
                    self.buffer[header_start..header_start + 4].try_into().unwrap()
                );
                let timestamp = u64::from_be_bytes(
                    self.buffer[header_start + 4..header_start + 12].try_into().unwrap()
                );

                // Slice the payload directly from the buffer without copying
                let payload_bytes = &self.buffer[header_start + HEADER_SIZE..header_start + record_total_size];

                // Convert bytes to string slice (zero-copy validation)
                let payload = match str::from_utf8(payload_bytes) {
                    Ok(s) => s,
                    Err(e) => return Err(io::Error::new(io::ErrorKind::InvalidData, e)),
                };

                // Trigger the callback
                on_record(Record { id, timestamp, payload });

                // Advance the cursor
                self.cursor += record_total_size;
                progress = true;
            }

            // Safety check: if we filled the buffer but made zero progress, the record is too big
            if !progress && self.limit == BUFFER_SIZE && self.cursor == 0 {
                return Err(io::Error::new(
                    io::ErrorKind::OutOfMemory,
                    "Record size exceeds stream parser buffer capacity",
                ));
            }

            // If we hit EOF and can't complete the current record
            if bytes_read == 0 && self.cursor < self.limit {
                return Err(io::Error::new(
                    io::ErrorKind::UnexpectedEof,
                    "Incomplete record trailing at end of stream",
                ));
            }
        }

        Ok(())
    }
}

