use std::io::{self, Read};
use std::str;

// Constant buffer size. Memory footprint is tied strictly to this size.
const BUFFER_SIZE: usize = 64 * 1024; // 64 KB

#[derive(Debug)]
pub struct Record<'a> {
    pub timestamp: &'a str,
    pub level: &'a str,
    pub message: &'a str,
}

#[derive(Debug)]
pub enum ParserError {
    Io(io::Error),
    RecordTooLong,
    Utf8Error(str::Utf8Error),
    InvalidFormat,
}

pub struct ZeroCopyStreamParser<R> {
    reader: R,
    buffer: Vec<u8>,
    read_pos: usize,  // Pointer to where unparsed data starts
    write_pos: usize, // Pointer to where valid data ends
    eof: bool,
}

impl<R: Read> ZeroCopyStreamParser<R> {
    pub fn new(reader: R) -> Self {
        Self {
            reader,
            // Pre-allocate the entire buffer once. No dynamic allocations occur during streaming.
            buffer: vec![0; BUFFER_SIZE],
            read_pos: 0,
            write_pos: 0,
            eof: false,
        }
    }

    /// Pulls data from the reader, shifting unparsed data to the front of the buffer if necessary.
    fn fill_buffer(&mut self) -> Result<usize, ParserError> {
        if self.read_pos > 0 {
            // Shift unparsed data back to the beginning of the buffer
            let remaining = self.write_pos - self.read_pos;
            self.buffer.copy_within(self.read_pos..self.write_pos, 0);
            self.read_pos = 0;
            self.write_pos = remaining;
        }

        if self.write_pos >= self.buffer.len() {
            // If the buffer is full and we can't shift, the single record is larger than our buffer.
            return Err(ParserError::RecordTooLong);
        }

        // Read directly into the unused space of our buffer
        let bytes_read = self
            .reader
            .read(&mut self.buffer[self.write_pos..])
            .map_err(ParserError::Io)?;

        self.write_pos += bytes_read;
        if bytes_read == 0 {
            self.eof = true;
        }

        Ok(bytes_read)
    }

    /// Zero-copy parser: Extracts fields directly as slices of the stream buffer
    fn parse_fields<'a>(&self, raw_line: &'a [u8]) -> Result<Record<'a>, ParserError> {
        let line_str = str::from_utf8(raw_line).map_err(ParserError::Utf8Error)?;

        let mut parts = line_str.splitn(3, '|');
        let timestamp = parts.next().ok_or(ParserError::InvalidFormat)?;
        let level = parts.next().ok_or(ParserError::InvalidFormat)?;
        let message = parts.next().ok_or(ParserError::InvalidFormat)?;

        Ok(Record {
            timestamp,
            level,
            message,
        })
