/// Lifetimes ('a) ensure these slices cannot outlive the buffer they point to.
#[derive(Debug)]
pub struct LogRecord<'a> {
    pub timestamp: &'a str,
    pub level: &'a str,
    pub message: &'a str,
}

pub struct StreamingParser<R> {
    reader: R,
    buffer: Vec<u8>,
    write_pos: usize, // Index where next read bytes should be written
    read_pos: usize,  // Index where parsing should resume
}

impl<R: Read> StreamingParser<R> {
    /// Creates a parser with a fixed buffer size. Memory footprint is strictly bounded
    /// to this size (e.g., 64 KB) regardless of input size.
    pub fn new(reader: R, buffer_size: usize) -> Self {
        Self {
            reader,
            buffer: vec![0; buffer_size],
            write_pos: 0,
            read_pos: 0,
        }
    }

    /// Parses the stream and executes a callback on each parsed record.
    /// This design avoids heap allocations per record and satisfies the borrow checker.
    pub fn parse_stream<F>(&mut self, mut on_record: F) -> io::Result<()>
    where
        F: FnMut(LogRecord) -> Result<(), &'static str>,
    {
        loop {
            // 1. Shift remaining unparsed data to the beginning of the buffer
            if self.read_pos > 0 {
                self.buffer.copy_within(self.read_pos..self.write_pos, 0);
                self.write_pos -= self.read_pos;
                self.read_pos = 0;
            }

            // 2. Read next chunk from the source into the remaining buffer space
            let bytes_read = self.reader.read(&mut self.buffer[self.write_pos..])?;
            if bytes_read == 0 {
                // End of stream. Check if there's a trailing record without a newline.
                if self.write_pos > self.read_pos {
                    let remaining = &self.buffer[self.read_pos..self.write_pos];
                    if let Ok(line) = str::from_utf8(remaining) {
                        let _ = self.parse_line(line, &mut on_record);
                    }
                }
                break;
            }
            self.write_pos += bytes_read;

            // 3. Scan the buffer for lines
            while let Some(newline_idx) = self.buffer[self.read_pos..self.write_pos]
                .iter()
                .position(|&b| b == b'\n')
            {
                let absolute_newline_idx = self.read_pos + newline_idx;

                // Extract the line slice (excluding the newline character)
                let line_bytes = &self.buffer[self.read_pos..absolute_newline_idx];

                // Advance read pointer past the newline character
                self.read_pos = absolute_newline_idx + 1;

                // Parse the line
                if let Ok(line_str) = str::from_utf8(line_bytes) {
                    if let Err(err) = self.parse_line(line_str, &mut on_record) {
                        eprintln!("Warning: parsing error: {}", err);
                    }
                }
            }

            // Safety check: If the buffer is full and we haven't found a single newline,
            // the record is larger than our buffer. We must error out to prevent memory blowup.
            if self.read_pos == 0 && self.write_pos == self.buffer.len() {
                return Err(io::Error::new(
                    io::ErrorKind::InvalidData,
                    "Record size exceeds allocated buffer size",
                ));
            }
        }
        Ok(())
    }

    /// Fast, zero-copy inline parser for our specific metric format
    #[inline(always)]
    fn parse_line<F>(&self, line: &str, on_record: &mut F) -> Result<(), &'static str>
    where
        F: FnMut(LogRecord) -> Result<(), &'static str>,
    {
