        let timestamp = parts.next().ok_or("Missing timestamp")?;
        let level = parts.next().ok_or("Missing level")?;
        let message = parts.next().ok_or("Missing message")?;

        let record = LogRecord {
            timestamp,
            level,
            message,
        };

        on_record(record)
    }
