use std::io::{self, Read};
use std::str;

// Bounded buffer size (e.g., 64 KB). Memory footprint will never exceed this.
const BUFFER_SIZE: usize = 64 * 1024;

/// Represents a parsed log record.
/// Lifetimes ('a) ensure all fields are references to the read buffer, requiring 0 allocations.
#[derive(Debug)]
pub struct LogRecord<'a> {
    pub timestamp: &'a str,
    pub level: &'a str,
    pub message: &'a str,
}

/// Zero-copy parsing of a line.
/// Expected format: "TIMESTAMP|LEVEL|MESSAGE"
#[inline(always)]
fn parse_line(line: &[u8]) -> Option<LogRecord<'_>> {
    // Convert the raw byte slice to a UTF-8 string slice without copying.
    // If invalid UTF-8, we skip the line.
    let line_str = str::from_utf8(line).ok()?;

    let mut parts = line_str.split('|');

    let timestamp = parts.next()?;
    let level = parts.next()?;
    let message = parts.next()?;

    Some(LogRecord {
        timestamp: timestamp.trim(),
        level: level.trim(),
        message: message.trim(),
    })
}

/// Streams data from a reader, parses it, and invokes a callback for each parsed record.
pub fn stream_parse<R, F>(mut reader: R, mut on_record: F) -> io::Result<()>
where
    R: Read,
    F: FnMut(LogRecord<'_>),
{
    // Allocate the buffer once on the heap.
    let mut buffer = vec![0u8; BUFFER_SIZE];

    let mut buffer_valid_len = 0; // How much valid data is in the buffer
    let mut parse_start = 0;      // Index pointing to the start of the next unparsed line

    loop {
        // 1. Shift unparsed trailing data to the beginning of the buffer
        if parse_start > 0 {
            buffer.copy_within(parse_start..buffer_valid_len, 0);
            buffer_valid_len -= parse_start;
            parse_start = 0;
        }

        // 2. Read new chunk from stream into the remaining space of the buffer
        let bytes_read = reader.read(&mut buffer[buffer_valid_len..])?;
        if bytes_read == 0 {
            // EOF reached. Process any remaining data left in the buffer.
            let remaining = &buffer[parse_start..buffer_valid_len];
            if !remaining.is_empty() {
                if let Some(record) = parse_line(remaining) {
                    on_record(record);
                }
            }
            break;
        }
        buffer_valid_len += bytes_read;

        // 3. Scan and parse complete lines using rapid byte scanning
        while let Some(newline_offset) = buffer[parse_start..buffer_valid_len]
            .iter()
            .position(|&b| b == b'\n') 
        {
            let newline_index = parse_start + newline_offset;
            let line = &buffer[parse_start..newline_index];

            // Strip trailing carriage return if dealing with Windows CRLF
            let trimmed_line = if line.ends_with(b"\r") {
                &line[..line.len() - 1]
            } else {
                line
            };

            if let Some(record) = parse_line(trimmed_line) {
                on_record(record);
            }

            parse_start = newline_index + 1;
        }

        // Safety valve: If a single line is larger than our buffer, we must error out
        // to prevent an infinite loop/buffer overflow.
        if parse_start == 0 && buffer_valid_len == BUFFER_SIZE {
            return Err(io::Error::new(
                io::ErrorKind::InvalidData,
                "Single record size exceeds buffer capacity",
            ));
        }
    }

    Ok(())
}

fn main() -> io::Result<()> {
    // Let's simulate a massive streaming input (e.g., gigabytes of logs)
    let raw_input = "2023-10-27T10:00:00Z|INFO|System initialized\n\
