```rust
use std::io::{self, Read};
use std::str;

// Bounded buffer size. 64KB is optimal for fitting inside CPU L1/L2 caches.
const BUFFER_SIZE: usize = 64 * 1024; 

/// A zero-copy representation of a log record.
/// The lifetimes ('a) tie these fields directly to the sliding window buffer.
#[derive(Debug)]
pub struct LogRecord<'a> {
    pub timestamp: u64,
    pub level: &'a str,
    pub service: &'a str,
    pub message: &'a str,
}

pub struct StreamingParser<R> {
    reader: R,
    buffer: Vec<u8>,
}

impl<R: Read> StreamingParser<R> {
    pub fn new(reader: R) -> Self {
        Self {
            reader,
            // Pre-allocate the static buffer. 
            // This is the primary memory overhead of the entire process.
            buffer: vec![0u8; BUFFER_SIZE],
        }
    }

    /// Parses the stream and executes a callback for every parsed record.
    /// Utilizing a callback avoids lifetime conflicts inherent to standard Iterators.
    pub fn parse_stream<F>(&mut self, mut handle_record: F) -> io::Result<()>
    where
        F: FnMut(LogRecord<'_>),
    {
        let mut leftover_len = 0;

        loop {
            // 1. Move leftover bytes from the previous read to the start of the buffer.
            if leftover_len > 0 {
                self.buffer.copy_within(self.buffer.len() - leftover_len.., 0);
            }

            // 2. Read from the stream into the empty portion of our buffer.
            let read_target = &mut self.buffer[leftover_len..];
            if read_target.is_empty() {
                return Err(io::Error::new(
                    io::ErrorKind::OutOfMemory,
                    "A single line exceeded the allocated buffer capacity.",
                ));
            }

            let bytes_read = self.reader.read(read_target)?;
            if bytes_read == 0 {
                // End of file (EOF). Process remaining trailing bytes if any.
                if leftover_len > 0 {
                    let last_line = &self.buffer[..leftover_len];
                    if let Some(record) = Self::parse_line(last_line) {
                        handle_record(record);
                    }
                }
                break;
            }

            let total_valid_bytes = leftover_len + bytes_read;
            let mut current_slice = &self.buffer[..total_valid_bytes];
            let mut consumed = 0;

            // 3. Scan for newlines using Rust's optimized, vectorized byte scanner.
            while let Some(pos) = current_slice.iter().position(|&b| b == b'\n') {
                let mut line = &current_slice[..pos];

                // Strip Windows carriage returns (\r) if present
                if line.ends_with(b"\r") {
                    line = &line[..line.len() - 1];
                }

                if !line.is_empty() {
                    if let Some(record) = Self::parse_line(line) {
                        handle_record(record);
                    }
                }

                let advance = pos + 1;
                current_slice = &current_slice[advance..];
                consumed += advance;
            }

            // Record how many bytes must slide to the next iteration
            leftover_len = total_valid_bytes - consumed;
        }

        Ok(())
    }

    /// Fast, zero-copy line parser. 
    /// No memory is allocated; we slice string references directly from raw bytes.
    #[inline(always)]
    fn parse_line(line: &[u8]) -> Option<LogRecord<'_>> {
        let mut parts = line.splitn(4, |&b| b == b' ');

        let timestamp_bytes = parts.next()?;
        let level_bytes = parts.next()?;
        let service_bytes = parts.next()?;
        let message_bytes = parts.next()?;

        // Convert byte slices to UTF-8 &str safely (zero-copy)
        let timestamp_str = str::from_utf8(timestamp_bytes).ok()?;
        let timestamp = timestamp_str.parse::<u64>().ok()?;

        let level = str::from_utf8(level_bytes).ok()?;
        let service = str::from_utf8(service_bytes).ok()?;
        let message = str::from_utf8(message_bytes).ok()?;

        Some(LogRecord {
            timestamp,
            level,
            service,
            message,
        })
    }
}
