```rust
use std::io::{self, Cursor, Read, Write};

const BUFFER_SIZE: usize = 64 * 1024; // 64 KB fixed-size buffer

struct StreamParser<R: Read> {
    reader: R,
    buffer: Vec<u8>,
    write_pos: usize, // Index where new data is written
}

impl<R: Read> StreamParser<R> {
    fn new(reader: R) -> Self {
        Self {
            reader,
            // Pre-allocate a single, fixed-size buffer on the heap
            buffer: vec![0; BUFFER_SIZE],
            write_pos: 0,
        }
    }

    /// Pulls more data from the underlying reader into the remaining buffer space.
    fn fill_buffer(&mut self) -> io::Result<bool> {
        if self.write_pos >= BUFFER_SIZE {
            return Err(io::Error::new(
                io::ErrorKind::OutOfMemory,
                "Frame size exceeds maximum buffer capacity",
            ));
        }

        let bytes_read = self.reader.read(&mut self.buffer[self.write_pos..])?;
        self.write_pos += bytes_read;

        // Return true if we hit End-Of-Stream (0 bytes read)
        Ok(bytes_read == 0)
    }

    /// Parses the stream and yields zero-copy views (`&[u8]`) to the handler.
    fn parse_stream<F>(&mut self, mut handler: F) -> io::Result<()>
    where
        F: FnMut(&[u8]),
    {
        let mut is_eof = false;

        loop {
            // 1. If buffer is empty, pull data
            if self.write_pos == 0 && !is_eof {
                is_eof = self.fill_buffer()?;
            }

            let mut read_pos = 0;

            // 2. Parse as many complete frames as possible from the active buffer window
            while read_pos + 5 <= self.write_pos {
                // Parse Header: Magic Byte (1B) + Payload Length (4B)
                if self.buffer[read_pos] != b'F' {
                    return Err(io::Error::new(
                        io::ErrorKind::InvalidData,
                        "Corrupted stream: Invalid magic byte",
                    ));
                }

                let len_bytes: [u8; 4] = self.buffer[read_pos + 1..read_pos + 5]
                    .try_into()
                    .unwrap();
                let payload_len = u32::from_be_bytes(len_bytes) as usize;

                // Check if the entire payload is present in the buffer
                if read_pos + 5 + payload_len > self.write_pos {
                    // Frame is incomplete, break loop to read more data
                    break;
                }

                // ZERO-COPY BORROW: Slice pointing directly into our pre-allocated buffer
                let payload = &self.buffer[read_pos + 5 .. read_pos + 5 + payload_len];

                // Execute user logic
                handler(payload);

                // Advance read pointer
                read_pos += 5 + payload_len;
            }

            // 3. Slide remaining unparsed data (partial frames) to the front of the buffer
            if read_pos > 0 {
                self.buffer.copy_within(read_pos..self.write_pos, 0);
                self.write_pos -= read_pos;
            }

            // 4. Handle End-Of-File conditions
            if is_eof {
                if self.write_pos > 0 {
                    return Err(io::Error::new(
                        io::ErrorKind::UnexpectedEof,
                        "Incomplete frame remaining at end of stream",
                    ));
                }
                break; // Stream successfully parsed and ended
            }

            // 5. Fill buffer up again for the next cycle
            is_eof = self.fill_buffer()?;
        }

        Ok(())
    }
}

