struct ZeroCopyReader<R: Read> {
    reader: R,
    buf: Vec<u8>,
    pos: usize, // Current read position in the buffer
    cap: usize, // Amount of valid data currently in the buffer
}

impl<R: Read> ZeroCopyReader<R> {
    fn new(reader: R, buffer_size: usize) -> Self {
        Self {
            reader,
            buf: vec![0; buffer_size],
            pos: 0,
            cap: 0,
        }
    }

    /// Process the stream. Using a closure (`F`) bypasses Rust's lifetime
    /// checker issues when returning references to internal buffers.
    fn parse_all<F>(&mut self, mut f: F) -> io::Result<()>
    where
        F: FnMut(LogRecord<'_>),
    {
        loop {
            // 1. If buffer is half-empty, shift unparsed data to the beginning
            if self.pos > self.buf.len() / 2 {
                self.buf.copy_within(self.pos..self.cap, 0);
                self.cap -= self.pos;
                self.pos = 0;
            }

            // 2. Read new data into the remaining space
            let bytes_read = self.reader.read(&mut self.buf[self.cap..])?;
