                if self.pos < self.cap {
                    if let Some(record) = parse_line(&self.buf[self.pos..self.cap]) {
                        f(record);
                    }
                }
                break;
            }
            self.cap += bytes_read;

            // 3. Scan for line delimiters and parse in-place
            while let Some(relative_nl) = self.buf[self.pos..self.cap]
                .iter()
                .position(|&b| b == b'\n')
