                        f(record);
                    }
                }
                self.pos = nl_pos + 1;
            }

            // Safety check: Prevent infinite loops on lines larger than the buffer
            if self.pos == 0 && self.cap == self.buf.len() {
                return Err(io::Error::new(
                    io::ErrorKind::OutOfMemory,
                    "Single line exceeds the buffer size limit",
