                    let payload_index = self.state - 4;
                    if payload_index < payload_len as usize {
                        buf[written] = b'A';
                        self.state += 1;
                        written += 1;
                    } else {
                        self.state = 0; // Reset state for next record
                    }
                }
            }
        }

        self.bytes_generated += written;
        Ok(written)
    }
