        let mut parts = line.splitn(3, |&b| b == b',');

        // Extract fields and perform zero-cost UTF-8 validation
        let timestamp = std::str::from_utf8(parts.next()?).ok()?;
        let level = std::str::from_utf8(parts.next()?).ok()?;
        let message = std::str::from_utf8(parts.next()?).ok()?;

        Some(LogRecord { timestamp, level, message })
    }
}

fn process_log_file<P: AsRef<Path>>(path: P) -> io::Result<()> {
    let file = File::open(path)?;
