    let mut reader = BufReader::with_capacity(64 * 1024, file);

    // Reusable byte buffer. This single buffer is allocated once on the heap
    // and cleared on each iteration, keeping memory overhead completely flat.
    let mut line_buffer = Vec::with_capacity(1024); 

    let mut total_lines = 0;
    let mut error_count = 0;

    loop {
        line_buffer.clear();

        // Read until newline into our reusable buffer
        let bytes_read = reader.read_until(b'\n', &mut line_buffer)?;
        if bytes_read == 0 {
            break; // EOF reached
        }

        total_lines += 1;

