    // Parses a line without copying data. Lifetimes bind the return values
    // directly to the input string slice.
    fn parse(line: &'a str) -> Option<Self> {
        let mut parts = line.splitn(4, ',');

        let id = parts.next()?.parse::<u64>().ok()?;
        let timestamp = parts.next()?.parse::<u64>().ok()?;
        let level = parts.next()?;
        let message = parts.next()?;

        Some(LogRecord {
            id,
            timestamp,
            level,
            message,
        })
    }
}

fn process_large_file(path: &str) -> io::Result<()> {
    let file = File::open(path)?;

    // Use a large internal capacity (128 KB) to minimize syscalls
    let mut reader = BufReader::with_capacity(128 * 1024, file);

    // The critical optimization: Allocate ONE string buffer outside the loop.
    // This buffer will grow to the size of the longest single line (a few KB max)
    // and then perform ZERO heap allocations for the rest of the gigabytes of data.
    let mut line_buffer = String::new();

    // Aggregates (Minimal state kept in memory)
    let mut total_records = 0u64;
    let mut error_count = 0u64;
    let mut warning_count = 0u64;

    let start_time = Instant::now();

    loop {
        // Clear the buffer length but retain the underlying allocated memory capacity
        line_buffer.clear();

        // Read the next line directly into our reusable buffer
        let bytes_read = reader.read_line(&mut line_buffer)?;
        if bytes_read == 0 {
            break; // End of File (EOF)
        }

        let trimmed = line_buffer.trim_end();
        if trimmed.is_empty() {
            continue;
        }

        // Parse the line. 'record' holds references directly into 'line_buffer'
        if let Some(record) = LogRecord::parse(trimmed) {
            total_records += 1;
            match record.level {
                "ERROR" => error_count += 1,
                "WARN" => warning_count += 1,
                _ => {}
            }
        }
    }

    let duration = start_time.elapsed();
    println!("Processed {} records in {:?}", total_records, duration);
    println!("Errors: {}, Warnings: {}", error_count, warning_count);

    Ok(())
}

fn main() -> io::Result<()> {
    let filename = "large_dataset.log";

    // 1. Generate dummy data for testing if it doesn't exist
    if !std::path::Path::new(filename).exists() {
        println!("Generating a dummy 1.2 GB log file...");
        generate_dummy_file(filename, 20_000_000)?; // 20 Million records
    }

    // 2. Run the high-throughput parser
    println!("Parsing starts...");
    process_large_file(filename)?;

    Ok(())
}

