use std::fs::{self, File, OpenOptions};
use std::io::{self, Read, Write, Seek, SeekFrom};
use std::path::{Path, PathBuf};
use std::thread;
use std::time::Duration;

struct RotationConfig {
    log_file_path: PathBuf,
    max_size_bytes: u64,
    max_backups: u32,
    poll_interval: Duration,
    use_copy_truncate: bool, // true = safe for apps that keep file handle open
}

fn main() {
    // Daemon Configuration
    let config = RotationConfig {
        log_file_path: PathBuf::from("app.log"),
        max_size_bytes: 10 * 1024 * 1024, // 10 Megabytes
        max_backups: 5,
        poll_interval: Duration::from_secs(10),
        use_copy_truncate: true, 
    };

    println!("Log rotation daemon started. Target: {:?}", config.log_file_path);

    loop {
        if let Err(e) = check_and_rotate(&config) {
            eprintln!("[Error] Rotation failed: {}", e);
        }
        thread::sleep(config.poll_interval);
    }
}

fn check_and_rotate(config = &RotationConfig) -> io::Result<()> {
    let metadata = match fs::metadata(&config.log_file_path) {
        Ok(meta) => meta,
        Err(ref e) if e.kind() == io::ErrorKind::NotFound => {
            return Ok(()); // File doesn't exist yet, wait for next cycle
        }
        Err(e) => return Err(e),
    };

    if metadata.len() >= config.max_size_bytes {
        println!(
            "Log file reaches {} bytes (Limit: {}). Rotating...",
            metadata.len(),
            config.max_size_bytes
        );
        perform_rotation(config)?;
    }

    Ok(())
}

fn perform_rotation(config: &RotationConfig) -> io::Result<()> {
    let backup_1 = get_backup_path(&config.log_file_path, 1);

    if config.use_copy_truncate {
        // Safe for active writers: copy contents to .1, then truncate original to 0.
        // Uses a fixed-size stack buffer to ensure memory usage does NOT scale with file size.
        copy_and_truncate(&config.log_file_path, &backup_1)?;
    } else {
        // Standard Rename: App must support reopening log files on rotation.
        shift_backups(config)?;
        fs::rename(&config.log_file_path, &backup_1)?;
        File::create(&config.log_file_path)?; // Recreate empty file
    }

    // Shift the remaining older backups
    shift_backups(config)?;

    println!("Rotation successful.");
    Ok(())
}

/// Shifts older backups (e.g., .1 -> .2, .2 -> .3)
fn shift_backups(config: &RotationConfig) -> io::Result<()> {
    // 1. Delete the oldest backup file if it exists
    let oldest_path = get_backup_path(&config.log_file_path, config.max_backups);
    if oldest_path.exists() {
        fs::remove_file(&oldest_path)?;
    }

    // 2. Shift files down (from max-1 down to 1)
    for i in (1..config.max_backups).rev() {
        let src = get_backup_path(&config.log_file_path, i);
        if src.exists() {
            let dst = get_backup_path(&config.log_file_path, i + 1);
            fs::rename(src, dst)?;
        }
    }
    Ok(())
}

/// Copies log content to the backup path and truncates the source file to 0.
/// Crucial for memory constraints: reads in chunks using a fixed stack-allocated buffer.
fn copy_and_truncate(src_path: &Path, dst_path: &Path) -> io::Result<()> {
    let mut src = OpenOptions::new().read(true).write(true).open(src_path)?;
    let mut dst = File::create(dst_path)?;

    // 8 KB stack buffer. This ensures memory consumption is flat,
    // whether the log file is 10 Megabytes or 10 Gigabytes.
    let mut buffer = [0u8; 8192]; 

    loop {
        let bytes_read = src.read(&mut buffer)?;
        if bytes_read == 0 {
            break;
        }
        dst.write_all(&buffer[..bytes_read])?;
    }

    // Atomically truncate original file to 0 bytes
    src.set_len(0)?;
    src.seek(SeekFrom::Start(0))?;
    Ok(())
}

/// Helper to generate the backup path name (e.g., "app.log" -> "app.log.1")
/// Minimizes heap allocations by modifying the path extension in-place.
fn get_backup_path(base: &Path, index: u32) -> PathBuf {
    let mut ext = base
        .extension()
        .map(|s| s.to_string_lossy().into_owned())
        .unwrap_or_default();

    if !ext.is_empty() {
        ext.push_str(&format!(".{}", index));
    } else {
        ext = index.to_string();
    }
    base.with_extension(ext)
}
