use std::fs;
use std::path::Path;
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::Arc;
use std::thread;
use std::time::Duration;
use std::fmt::Write;

// Configuration options
struct Config {
    log_file_path: &'static str,
    max_size_bytes: u64,
    max_backups: usize,
    check_interval: Duration,
}

const CONFIG: Config = Config {
    log_file_path: "/var/log/app.log",
    max_size_bytes: 10 * 1024 * 1024, // 10 MB
    max_backups: 5,
    check_interval: Duration::from_secs(10),
};

fn main() {
    // Register shutdown signals (SIGINT/SIGTERM) to exit cleanly
    let running = Arc::new(AtomicBool::new(true));
    let r = running.clone();
    ctrlc::set_handler(move || {
        r.store(false, Ordering::SeqCst);
    }).expect("Error setting signal handler");

    println!("Log rotation daemon started for: {}", CONFIG.log_file_path);

    // Pre-allocate path buffers on the heap *once* during startup.
    // This ensures ZERO heap allocations during the active loop.
    let mut src_buffer = String::with_capacity(512);
    let mut dst_buffer = String::with_capacity(512);

    while running.load(Ordering::SeqCst) {
        if let Err(e) = check_and_rotate(&CONFIG, &mut src_buffer, &mut dst_buffer) {
            eprintln!("[ERROR] Log rotation failed: {}", e);
        }
        thread::sleep(CONFIG.check_interval);
    }

    println!("Daemon stopped cleanly.");
}

/// Checks the file size and rotates if it exceeds the limit.
/// Reuses pre-allocated String buffers to prevent heap allocation churn.
fn check_and_rotate(
    config: &Config,
    src_buf: &mut String,
    dst_buf: &mut String,
) -> Result<(), std::io::Error> {
    let path = Path::new(config.log_file_path);

    // 1. Check if the file exists
    if !path.exists() {
        return Ok(());
    }

    // 2. Query file metadata (cheap system call)
    let metadata = fs::metadata(path)?;
    if metadata.len() < config.max_size_bytes {
        return Ok(()); // File is still under limit
    }

    println!(
        "Log file matches or exceeds limit ({}/{} bytes). Rotating...",
        metadata.len(),
        config.max_size_bytes
    );

    // 3. Rotate older backups: log.4 -> log.5, log.3 -> log.4, etc.
    for i in (1..config.max_backups).rev() {
        // Format paths into pre-allocated buffers
        format_backup_path(src_buf, config.log_file_path, i)?;
        format_backup_path(dst_buf, config.log_file_path, i + 1)?;

        let src = Path::new(src_buf);
        if src.exists() {
            let dst = Path::new(dst_buf);
            fs::rename(src, dst)?;
        }
    }

    // 4. Rename active log to log.1
    format_backup_path(dst_buf, config.log_file_path, 1)?;
    fs::rename(path, Path::new(dst_buf))?;

    // 5. Recreate the active log file (with write permissions)
    fs::OpenOptions::new()
        .write(true)
        .create(true)
        .truncate(true)
        .open(path)?;

    Ok(())
}

/// Formats a backup file path into a pre-allocated String buffer without allocating memory.
fn format_backup_path(
    buf: &mut String,
    base_path: &str,
    index: usize,
) -> Result<(), std::io::Error> {
    buf.clear(); // Keeps capacity, resets length to 0
    write!(buf, "{}.{}", base_path, index)
        .map_err(|_| std::io::Error::new(std::io::ErrorKind::Other, "Path buffer overflow"))
}
```

### Why this implementation is memory-efficient:

1. **Zero-Allocation Loop:** Inside the `while running` loop, no `String`s, `Vec`s, or dynamic paths are allocated. The `src_buf` and `dst_buf` strings are allocated once at startup. `buf.clear()` resets the string length to zero but retains its allocated capacity, avoiding subsequent heap allocations.
2. **Deterministic Destructors:** Rust immediately drops files and metadata handles as soon as they go out of scope, guaranteeing that memory is reclaimed immediately and preventing spikes.
3. **No External Dependencies:** The binary links only against the standard library (`std`) and `ctrlc` (for safe Unix signal handling), keeping the binary extremely lean.

