use std::alloc::System;
use std::fs::{self, File, OpenOptions};
use std::io::{self, Read, Write};
use std::path::{Path, PathBuf};
use std::thread;
use std::time::Duration;

// Force Rust to use the system allocator instead of jemalloc/mimalloc.
// This reduces the baseline idle memory overhead of the binary.
#[global_allocator]
static A: System = System;

// CONFIGURATION (In a production app, these would be read from a lightweight config file)
const TARGET_LOG: &str = "/var/log/app.log";
const MAX_SIZE_BYTES: u64 = 10 * 1024 * 1024; // 10 MB
const BACKLOG_LIMIT: usize = 5;               // Keep 5 rotated logs
const CHECK_INTERVAL_SECS: u64 = 10;          // Check every 10 seconds

fn main() {
    let target_path = Path::new(TARGET_LOG);
    println!("Starting minirotate daemon for: {:?}", target_path);

    loop {
        if let Err(e) = check_and_rotate(target_path) {
            eprintln!("[ERROR] Rotation failed: {}", e);
        }
        // Sleep the thread, yielding CPU and keeping memory completely idle
        thread::sleep(Duration::from_secs(CHECK_INTERVAL_SECS));
    }
}

fn check_and_rotate(target: &Path) -> io::Result<()> {
    // 1. Check if file exists and exceeds size limit
    let metadata = match fs::metadata(target) {
        Ok(m) => m,
        Err(ref e) if e.kind() == io::ErrorKind::NotFound => return Ok(()), // Log file doesn't exist yet
        Err(e) => return Err(e),
    };

    if metadata.len() < MAX_SIZE_BYTES {
        return Ok(()); // No rotation needed
    }

    println!("Log size ({} bytes) exceeded threshold. Rotating...", metadata.len());

    // 2. Immediate Rotation
    // Create a temporary staging name for rotation to free up the target path immediately.
    let mut temp_target = target.to_path_buf();
    temp_target.set_extension("log.tmp");

    // Atomically rename active log to the temp target.
    // The logging application will now write to the renamed file descriptor or wait.
    fs::rename(target, &temp_target)?;

    // Immediately recreate the original empty log file so the logging application
    // can continue writing to the standard path without blocking.
    {
        let _new_file = OpenOptions::new()
            .create(true)
            .write(true)
            .truncate(true)
            .open(target)?;
    } // File descriptor closed immediately here

    // 3. Compress the Temp Log
    // This is wrapped in a helper function to ensure file handles are closed *before* cleaning up.
    let compressed_path = compress_file(&temp_target)?;

    // Clean up the uncompressed temporary file
    fs::remove_file(&temp_target)?;

    // 4. Manage Backlog (Retention policy)
    housekeep_backlog(target, &compressed_path)?;

    Ok(())
}

/// Compresses a file using Gzip with a strictly bounded 8KB RAM buffer.
fn compress_file(source_path: &Path) -> io::Result<PathBuf> {
    use flate2::write::GzEncoder;
    use flate2::Compression;

    let mut dest_path = source_path.to_path_buf();
    // Generate timestamp for unique naming: app.log.<timestamp>.gz
    let timestamp = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs();
    dest_path.set_extension(format!("{}.gz", timestamp));

    let source_file = File::open(source_path)?;
    let dest_file = File::create(&dest_path)?;

    // Use default compression level, mapping directly to the output file wrapper
    let mut encoder = GzEncoder::new(dest_file, Compression::default());
    let mut reader = io::BufReader::new(source_file);

    // FIXED STACK BUFFER: Strictly limits RAM usage. Only 8 KB of heap/stack
    // is allocated for transit, regardless of whether the log file is 10MB or 10GB.
    let mut buffer = [0u8; 8192]; 

    loop {
        let bytes_read = reader.read(&mut buffer)?;
        if bytes_read == 0 {
            break; // EOF reached
        }
        encoder.write_all(&buffer[..bytes_read])?;
    }

    // Explicitly finish compression and flush to disk
    encoder.finish()?;

    println!("Compressed log saved to: {:?}", dest_path);
    Ok(dest_path)
}

/// Keeps only the most recent N compressed logs, deleting older ones.
fn housekeep_backlog(base_path: &Path, newly_created: &Path) -> io::Result<()> {
    let parent_dir = base_path.parent().unwrap_or_else(|| Path::new("."));
    let file_name_lossy = base_path.file_name().unwrap_or_default().to_string_lossy();

    let mut rotated_files = Vec::new();

    // Read directory to find matches
    for entry in fs::read_dir(parent_dir)? {
        let entry = entry?;
        let path = entry.path();
        if path.is_file() {
            if let Some(name) = path.file_name().and_then(|n| n.to_str()) {
                // Look for rotated files matching "app.log.<timestamp>.gz"
                if name.starts_with(&*file_name_lossy) && name.ends_with(".gz") {
                    // Fetch modification time to sort accurately
                    let metadata = entry.metadata()?;
                    let modified = metadata.modified().unwrap_or(std::time::SystemTime::UNIX_EPOCH);
                    rotated_files.push((path, modified));
                }
            }
        }
    }

    // Sort files by modification time (oldest first)
    rotated_files.sort_by_key(|&(_, time)| time);

    // If we exceed our limit, delete the oldest files
    if rotated_files.len() > BACKLOG_LIMIT {
        let delete_count = rotated_files.len() - BACKLOG_LIMIT;
        for i in 0..delete_count {
            let (path_to_delete, _) = &rotated_files[i];
            // Safety check: Never delete the file we just created
            if path_to_delete != newly_created {
                fs::remove_file(path_to_delete)?;
                println!("Deleted old backup: {:?}", path_to_delete);
            }
        }
    }

    Ok(())
}
