use std::time::Duration;

// Use the system allocator to avoid jemalloc/mimalloc memory caching bloat
#[global_allocator]
static A: System = System;

struct Config {
    log_file: PathBuf,
    max_size_bytes: u64,
    max_backups: u32,
    check_interval: Duration,
