            // Write to stderr; in production, this goes to systemd-journald
            eprintln!("Rotation error: {}", e);
        }
        thread::sleep(config.check_interval);
    }
}

fn process_rotation(config: &Config) -> std::io::Result<()> {
    // 1. Check if the active log file exists and get size
    let metadata = match fs::metadata(&config.log_file) {
        Ok(m) => m,
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => return Ok(()), // Nothing to do
        Err(e) => return Err(e),
    };

    if metadata.len() < config.max_size_bytes {
        return Ok(()); // Size limit not reached
    }

    println!("Log file {:?} reached limit. Rotating...", config.log_file);

    // 2. Rotate older backups (e.g., log.4 -> log.5)
    for i in (1..config.max_backups).rev() {
        let src = get_backup_path(&config.log_file, i);
        let dst = get_backup_path(&config.log_file, i + 1);
        if src.exists() {
            safe_move(&src, &dst)?;
        }
    }

    // 3. Move active log to log.1
    let first_backup = get_backup_path(&config.log_file, 1);
    safe_move(&config.log_file, &first_backup)?;

    // 4. Recreate the empty active log file
    fs::File::create(&config.log_file)?;

    Ok(())
}

/// Constructs backup paths (e.g., "app.log" -> "app.log.1")
/// Keeps allocation localized and minimal.
fn get_backup_path(base: &Path, index: u32) -> PathBuf {
    let mut filename = base.file_name().unwrap_or_default().to_os_string();
    filename.push(format!(".{}", index));
    base.with_file_name(filename)
}

/// Moves a file safely.
/// Tries `fs::rename` first (metadata-only, fast, zero-memory).
/// Falls back to a chunked stream copy if cross-device boundaries are crossed (EXDEV).
fn safe_move(src: &Path, dst: &Path) -> std::io::Result<()> {
    if fs::rename(src, dst).is_ok() {
        return Ok(());
    }

    // Fallback: Stream copy with strict memory limits (8KB buffer on the stack)
    let mut reader = fs::File::open(src)?;
    let mut writer = fs::File::create(dst)?;
    let mut buffer = [0u8; 8192]; // Fixed 8KB stack allocation

    loop {
        let bytes_read = reader.read(&mut buffer)?;
        if bytes_read == 0 {
            break;
        }
        writer.write_all(&buffer[..bytes_read])?;
    }

    // Truncate or remove the original file
