```rust
use std::fs;
use std::path::{Path, PathBuf};
use std::thread;
use std::time::Duration;

// Hardcoded limits to avoid parsing overhead. 
// In production, these can be passed via environment variables during startup.
struct Config {
    log_file_path: &'static str,
    max_size_bytes: u64,
    max_backups: usize,
    poll_interval_secs: u64,
}

const CONFIG: Config = Config {
    log_file_path: "/var/log/my_app.log",
    max_size_bytes: 10 * 1024 * 1024, // 10 MB
    max_backups: 5,
    poll_interval_secs: 10,
};

fn main() {
    let target_path = Path::new(CONFIG.log_file_path);

    // Pre-allocate path buffers to guarantee zero heap allocations during the main loop
    let mut src_buffer = PathBuf::with_capacity(256);
    let mut dst_buffer = PathBuf::with_capacity(256);

    eprintln!("[INFO] Log rotation daemon started for {}", CONFIG.log_file_path);

    loop {
        if let Err(e) = check_and_rotate(target_path, &mut src_buffer, &mut dst_buffer) {
            // Write to stderr (systemd/syslog will capture this). 
            // Do NOT write to the log file we are rotating!
            eprintln!("[ERROR] Rotation failed: {}", e);
        }

        thread::sleep(Duration::from_secs(CONFIG.poll_interval_secs));
    }
}

fn check_and_rotate(
    target: &Path, 
    src_buf: &mut PathBuf, 
    dst_buf: &mut PathBuf
) -> std::io::Result<()> {
    // 1. Check file size using metadata (O(1) memory, does not read file contents)
    let metadata = match fs::metadata(target) {
        Ok(meta) => meta,
        Err(ref e) if e.kind() == std::io::ErrorKind::NotFound => {
            // File doesn't exist yet, nothing to do
            return Ok(());
        }
        Err(e) => return Err(e),
    };

    if metadata.len() < CONFIG.max_size_bytes {
        return Ok(()); // Limit not reached
    }

    eprintln!("[INFO] Log limit exceeded. Rotating...");

    // 2. Rotate older backups (e.g., log.4 -> log.5, log.3 -> log.4)
    for i in (1..CONFIG.max_backups).rev() {
        build_path(target, i, src_buf);
        build_path(target, i + 1, dst_buf);

        if src_buf.exists() {
            fs::rename(&src_buf, &dst_buf)?;
        }
    }

    // 3. Rotate the current active log to log.1
    build_path(target, 1, dst_buf);
    fs::rename(target, dst_buf)?;

    // 4. Create a new empty log file to replace the old one
    fs::File::create(target)?;

    eprintln!("[INFO] Rotation complete.");
    Ok(())
}

/// Helper function to build backup paths without dynamic heap allocations.
/// Reuses the existing capacity of the provided PathBuf.
fn build_path(base: &Path, index: usize, buf: &mut PathBuf) {
    buf.clear();
    buf.push(base);

    // Convert index to string safely using a small stack-allocated buffer
    let mut num_buf = [0u8; 16];
    let num_str = format_index(index, &mut num_buf);

    // Push the extension (e.g., "/var/log/my_app.log.1")
    let mut os_str = base.os_str().to_os_string();
    os_str.push(".");
    os_str.push(num_str);

    buf.set_file_name(os_str);
}

/// Formats an integer into a stack-allocated byte buffer to avoid string allocations.
fn format_index(mut val: usize, buf: &mut [u8; 16]) -> &str {
    if val == 0 {
        return "0";
    }
    let mut pos = 16;
    while val > 0 {
        pos -= 1;
        buf[pos] = b'0' + (val % 10) as u8;
        val /= 10;
    }
    std::str::from_utf8(&buf[pos..]).unwrap_or("0")
}
