### The Rust Implementation (`main.rs`)

```rust
use std::fs;
use std::io::{self, Write};
use std::path::Path;
use std::thread;
use std::time::Duration;

const TARGET_FILE: &str = "app.log";
const MAX_SIZE_BYTES: u64 = 10 * 1024 * 1024; // 10 MB limit
const MAX_BACKUPS: usize = 5;                  // Keep up to app.log.5
const CHECK_INTERVAL: Duration = Duration::from_secs(10);

fn main() {
    println!("Daemon started. Monitoring '{}'...", TARGET_FILE);

    loop {
        if let Err(e) = check_and_rotate(TARGET_FILE, MAX_SIZE_BYTES, MAX_BACKUPS) {
            // In a production daemon, log to syslog/stderr
            eprintln!("[ERROR] Log rotation failed: {:?}", e);
        }
        thread::sleep(CHECK_INTERVAL);
    }
}

fn check_and_rotate(target: &str, max_size: u64, max_backups: usize) -> io::Result<()> {
    let path = Path::new(target);

    // 1. Check if target file exists
    if !path.exists() {
        return Ok(());
    }

    // 2. Query file size (Metadata uses OS syscalls, no heap allocation)
    let metadata = fs::metadata(path)?;
    if metadata.len() < max_size {
        return Ok(());
    }

    println!(
        "Log '{}' reached {} bytes. Rotating...", 
        target, metadata.len()
    );

    // Stack buffers for formatting file paths without heap allocation
    let mut buf_src = [0u8; 256];
    let mut buf_dst = [0u8; 256];

    // 3. Shift older backups (e.g., app.log.4 -> app.log.5)
    for i in (1..max_backups).rev() {
        let src_str = format_path_on_stack(&mut buf_src, target, i)?;
        let dst_str = format_path_on_stack(&mut buf_dst, target, i + 1)?;

        let src_path = Path::new(src_str);
        if src_path.exists() {
            fs::rename(src_path, Path::new(dst_str))?;
        }
    }

    // 4. Rename current log to .1 (e.g., app.log -> app.log.1)
    let first_backup_str = format_path_on_stack(&mut buf_src, target, 1)?;
    fs::rename(path, Path::new(first_backup_str))?;

    // 5. Create new empty log file (releasing the file handle immediately)
    fs::File::create(path)?;

    Ok(())
}

/// Helper to format a file path with an index on the stack.
/// Avoids the heap allocation of standard `format!("{}.{}", base, index)`.
fn format_path_on_stack<'a>(
    buf: &'a mut [u8], 
    base: &str, 
    index: usize
) -> io::Result<&'a str> {
    let mut cursor = io::Cursor::new(buf);

    // Write directly into the stack buffer
    write!(cursor, "{}.{}", base, index)
        .map_err(|e| io::Error::new(io::ErrorKind::Other, e))?;

    let len = cursor.position() as usize;
    let written_bytes = &cursor.into_inner()[..len];

    std::str::from_utf8(written_bytes)
        .map_err(|e| io::Error::new(io::ErrorKind::InvalidData, e))
}
```

