### The Rust Implementation (`main.rs`)

```rust
use std::fs;
use std::path::Path;
use std::thread;
use std::time::Duration;
use std::fmt::Write; // Import for in-place string formatting

// Configuration
const TARGET_LOG: &str = "test.log";
const MAX_SIZE_BYTES: u64 = 10 * 1024; // 10 KB (For demonstration purposes)
const MAX_BACKUPS: u32 = 5;            // Retain up to test.log.5
const CHECK_INTERVAL: Duration = Duration::from_secs(5);

fn main() {
    println!("Daemon started. Monitoring '{}'...", TARGET_LOG);

    // Pre-allocate path buffers once to prevent memory allocations in the loop
    let mut current_path_buf = String::with_capacity(TARGET_LOG.len() + 5);
    let mut next_path_buf = String::with_capacity(TARGET_LOG.len() + 5);

    loop {
        if let Err(e) = check_and_rotate(TARGET_LOG, MAX_SIZE_BYTES, MAX_BACKUPS, &mut current_path_buf, &mut next_path_buf) {
            eprintln!("[ERROR] Rotation failed: {}", e);
        }
        thread::sleep(CHECK_INTERVAL);
    }
}

fn check_and_rotate(
    filepath: &str,
    max_size: u64,
    max_backups: u32,
    cur_buf: &mut String,
    next_buf: &mut String,
) -> std::io::Result<()> {
    let path = Path::new(filepath);

    // 1. Check if the target log file exists
    if !path.exists() {
        return Ok(()); // Nothing to rotate
    }

    // 2. Query file size (metadata call, zero memory read of file contents)
    let metadata = fs::metadata(path)?;
    if metadata.len() < max_size {
        return Ok(()); // Size limit not reached
    }

    println!(
        "Log '{}' size is {} bytes (limit {}). Rotating...",
        filepath,
        metadata.len(),
        max_size
    );

    // 3. Shift older backups (e.g., test.log.4 -> test.log.5)
    for i in (1..max_backups).rev() {
        cur_buf.clear();
        next_buf.clear();

        // Safe, allocation-free string formatting using pre-allocated buffers
        write!(cur_buf, "{}.{}", filepath, i).unwrap();
        write!(next_buf, "{}.{}", filepath, i + 1).unwrap();

        let old_path = Path::new(cur_buf);
        if old_path.exists() {
            fs::rename(old_path, Path::new(next_buf))?;
        }
    }

    // 4. Rename current log to log.1
    cur_buf.clear();
    write!(cur_buf, "{}.1", filepath).unwrap();
    fs::rename(path, Path::new(cur_buf))?;

    // 5. Re-create the empty target log file
    fs::File::create(path)?;

    println!("Rotation complete.");
    Ok(())
}
```

