const MONITOR_INTERVAL_SECS: u64 = 5;       // Poll every 5 seconds

struct MonitorDaemon {
    sys: System,
}

impl MonitorDaemon {
    fn new() -> Self {
        // Initialize the system struct, only loading what we need to maximize performance
        let mut sys = System::new();
        sys.refresh_cpu();
        sys.refresh_memory();
        Self { sys }
    }

    /// Primary execution loop of the daemon
    async fn run(&mut self) {
        info!("System daemon started. Monitoring interval: {}s", MONITOR_INTERVAL_SECS);

        let mut interval = tokio::time::interval(Duration::from_secs(MONITOR_INTERVAL_SECS));

        loop {
            // Wait for the next tick of our interval
            interval.tick().await;

            // Perform metrics refresh
            self.sys.refresh_cpu();
            self.sys.refresh_memory();

            self.analyze_cpu();
            self.analyze_memory();
        }
    }

    /// Monitors CPU usage
    fn analyze_cpu(&self) {
        let global_cpu = self.sys.global_cpu_info().cpu_usage();
        info!("Global CPU Usage: {:.2}%", global_cpu);

        if global_cpu > 90.0 {
            warn!("High CPU usage detected: {:.2}%", global_cpu);
        }
    }

    /// Monitors Memory usage and takes corrective actions if thresholds are crossed
    fn analyze_memory(&mut self) {
        let total_mem = self.sys.total_memory() as f32;
        let used_mem = self.sys.used_memory() as f32;
        let mem_pct = (used_mem / total_mem) * 100.0;

        info!("Memory Usage: {:.2}% ({:.2} GB / {:.2} GB)", 
