use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::mpsc::{channel, RecvTimeoutError};
use std::sync::Arc;
use std::time::Duration;
use sysinfo::{CpuRefreshKind, ProcessRefreshKind, RefreshKind, System};

// Configuration Constants
const MEMORY_THRESHOLD_PERCENT: f32 = 80.0;
const MONITOR_INTERVAL_SECS: u64 = 2;

fn main() -> Result<(), Box<dyn std::error::Error>> {
    println!("Starting High-Performance System Daemon...");

    // 1. Setup graceful shutdown signaling
    let term = Arc::new(AtomicBool::new(false));
    signal_hook::flag::register(signal_hook::consts::SIGTERM, Arc::clone(&term))?;
    signal_hook::flag::register(signal_hook::consts::SIGINT, Arc::clone(&term))?;

    // Create a channel to allow the signal thread to interrupt our sleep loop instantly
    let (tx, rx) = channel();
    let term_thread = Arc::clone(&term);
    std::thread::spawn(move || {
        while !term_thread.load(Ordering::Relaxed) {
            std::thread::sleep(Duration::from_millis(100));
        }
        let _ = tx.send(()); // Signal the main loop to exit
    });

    // 2. Initialize Sysinfo System object
    // Performance Optimization: Only refresh what we actually need (CPU and Memory status)
    let mut sys = System::new_with_specifics(
        RefreshKind::new()
            .with_memory()
            .with_cpu(CpuRefreshKind::everything()),
    );

    println!("Daemon running. Monitoring system resources...");

    // 3. Main Event Loop
    loop {
        // High-Performance Sleep: Wait 2 seconds, or exit instantly if SIGTERM/SIGINT is received
        match rx.recv_timeout(Duration::from_secs(MONITOR_INTERVAL_SECS)) {
            Ok(_) | Err(RecvTimeoutError::Disconnected) => {
                println!("Termination signal received. Cleaning up...");
                break;
            }
            Err(RecvTimeoutError::Timeout) => {
                // Timeout reached, execute monitoring tick
            }
        }

        // Refresh only Memory and CPU metrics (ultra-fast)
        sys.refresh_memory();
        sys.refresh_cpu_all();

        let total_mem = sys.total_memory() as f32;
        let used_mem = sys.used_memory() as f32;
        let mem_usage_pct = (used_mem / total_mem) * 100.0;
        let global_cpu = sys.global_cpu_info().cpu_usage();

        println!(
            "[MONITOR] CPU: {:.1}% | Memory: {:.1}% ({:.2} GB / {:.2} GB)",
            global_cpu,
            mem_usage_pct,
            used_mem / 1024.0 / 1024.0 / 1024.0,
            total_mem / 1024.0 / 1024.0 / 1024.0
        );

        // 4. Resource Management Threshold Check
        if mem_usage_pct > MEMORY_THRESHOLD_PERCENT {
            eprintln!(
                "[WARNING] Memory usage exceeded threshold ({:.1}% > {:.1}%)!",
                mem_usage_pct, MEMORY_THRESHOLD_PERCENT
            );

            // Execute mitigation
            manage_high_memory_usage(&mut sys);
        }
    }

    println!("Daemon stopped successfully.");
    Ok(())
}

/// Scans the process tree, finds the offending process, and manages it.
fn manage_high_memory_usage(sys: &mut System) {
    println!("[MANAGE] Scanning system processes...");

    // Performance Optimization: Only refresh processes when the threshold is hit
    sys.refresh_processes_specifics(ProcessRefreshKind::new().with_memory());

    // Find the process utilizing the most memory
    let mut top_process: Option<(&sysinfo::Pid, &sysinfo::Process)> = None;

    for (pid, process) in sys.processes() {
        if let Some((_, current_top)) = top_process {
            if process.memory() > current_top.memory() {
                top_process = Some((pid, process));
            }
        } else {
            top_process = Some((pid, process));
        }
    }

    if let Some((pid, proc)) = top_process {
        let proc_mem_gb = proc.memory() as f32 / 1024.0 / 1024.0 / 1024.0;
        eprintln!(
            "[ACTION REQUIRED] Top consumer: PID {} ({}) using {:.2} GB of memory.",
            pid, proc.name(), proc_mem_gb
        );

        // --- MANAGEMENT ACTION ---
        // In a real-world scenario, you could choose to:
        // 1. Terminate the process: `proc.kill();`
        // 2. Reduce priority (renice).
        // 3. Send an alert payload to a webhook.
        // For safety, we will just log the simulated intervention:
        println!("[ACTION] Sent notification payload for PID {}.", pid);
    }
}
