            );

            // Resource Management (Mitigation Phase)
            manage_high_memory(&mut sys, &config);
        }

        // Calculate sleep time to account for processing latency (drift prevention)
        let elapsed = start_time.elapsed();
        if elapsed < config.tick_interval {
            thread::sleep(config.tick_interval - elapsed);
        }
    }

    println!("[INFO] Received shutdown signal. Cleaning up and exiting daemon safely.");
    Ok(())
}

/// Identifies top memory-consuming processes and simulates mitigation steps (or logs actions)
fn manage_high_memory(sys: &mut System, config: &DaemonConfig) {
    let mut processes: Vec<(&Pid, &sysinfo::Process)> = sys.processes().iter().collect();

    // Sort processes by memory usage in descending order
    // Uses unstable sort (faster, zero allocation) because stability doesn't matter here
    processes.sort_unstable_by(|a, b| b.1.memory().cmp(&a.1.memory()));

    println!("[INFO] Top Memory Offenders:");
    for (i, (pid, process)) in processes.iter().take(HIGH_MEM_PROCESS_LIMIT).enumerate() {
        let mem_mb = process.memory() as f64 / 1_048_576.0; // Convert to MB
        println!(
            "  [{}] PID: {} | Name: {} | Memory: {:.2} MB",
            i + 1,
            pid,
            process.name(),
            mem_mb
        );

        // Management Logic:
        // In a real-world scenario, you could kill, renice, or trigger alerts.
        // Here, we log a simulated action for the top offender if memory is critically low.
        if i == 0 && config.mem_threshold_pct > 95.0 {
            eprintln!(
                "[CRITICAL] [ACTION REQUIRED] Top offender '{}' (PID {}) is consuming excessive RAM. Simulation: Sending SIGTERM.",
                process.name(),
                pid
            );
            // To actually kill the process, you would uncomment the following line:
            // process.kill();
        }
    }
}
