use std::sync::Arc;
use std::sync::atomic::{AtomicU32, AtomicU64, Ordering};
use std::time::Duration;
use tokio::fs;
use tokio::io::{AsyncReadExt, AsyncWriteExt};
use tokio::net::UnixListener;
use tokio::signal::unix::{signal, SignalKind};
use sysinfo::{System, CpuRefreshKind, MemoryRefreshKind, RefreshKind};

const SOCKET_PATH: &str = "/tmp/sys_resource_daemon.sock";

/// Thread-safe, lock-free metrics store for high-frequency reads/writes.
struct SystemMetrics {
    cpu_usage: AtomicU32,     // Stored as f32 bits
    used_memory: AtomicU64,   // Bytes
    total_memory: AtomicU64,  // Bytes
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    println!("Starting High-Performance System Daemon...");

    // Initialize lock-free state
    let metrics = Arc::new(SystemMetrics {
        cpu_usage: AtomicU32::new(0f32.to_bits()),
        used_memory: AtomicU64::new(0),
        total_memory: AtomicU64::new(0),
    });

    // 1. Spawn the Background Resource Monitoring Loop
    let monitor_metrics = Arc::clone(&metrics);
    let monitor_handle = tokio::spawn(async move {
        // Initialize sysinfo only with the features we need for speed and low memory
        let mut sys = System::new_with_specifics(
            RefreshKind::new()
                .with_cpu(CpuRefreshKind::everything())
                .with_memory(MemoryRefreshKind::everything())
        );

        let mut interval = tokio::time::interval(Duration::from_millis(1000));
        loop {
            interval.tick().await;

            sys.refresh_cpu_all();
            sys.refresh_memory();

            let cpu = sys.global_cpu_info().cpu_usage();
            let used_mem = sys.used_memory();
            let total_mem = sys.total_memory();

            // Lock-free atomic writes
            monitor_metrics.cpu_usage.store(cpu.to_bits(), Ordering::Relaxed);
            monitor_metrics.used_memory.store(used_mem, Ordering::Relaxed);
            monitor_metrics.total_memory.store(total_mem, Ordering::Relaxed);
        }
    });

    // 2. Spawn the Management IPC Server (Unix Domain Socket)
    let ipc_metrics = Arc::clone(&metrics);
    // Remove stale socket if it exists from a previous run
    let _ = fs::remove_file(SOCKET_PATH).await;
    let listener = UnixListener::bind(SOCKET_PATH)?;
    println!("IPC management interface listening on: {}", SOCKET_PATH);

    let ipc_handle = tokio::spawn(async move {
        loop {
            match listener.accept().await {
                Ok((mut socket, _)) => {
                    let client_metrics = Arc::clone(&ipc_metrics);
                    tokio::spawn(async move {
                        let mut buf = [0; 256];
                        if let Ok(n) = socket.read(&mut buf).await {
                            if n == 0 { return; }
                            let command = String::from_utf8_lossy(&buf[..n]).trim().to_uppercase();

                            let response = match command.as_str() {
                                "GET_STATS" => {
                                    let cpu = f32::from_bits(client_metrics.cpu_usage.load(Ordering::Relaxed));
                                    let used = client_metrics.used_memory.load(Ordering::Relaxed);
                                    let total = client_metrics.total_memory.load(Ordering::Relaxed);
                                    format!(
                                        "{{\"status\":\"ok\",\"cpu_usage_pct\":{:.2},\"used_mem_bytes\":{},\"total_mem_bytes\":{}}}\n",
                                        cpu, used, total
                                    )
                                }
                                "OPTIMIZE_MEM" => {
                                    // A simulated management command. 
                                    // In a real application, you could trigger glibc's malloc_trim(),
                                    // clear page cache, or adjust cgroup memory limits here.
                                    eprintln!("[ACTION] Running memory optimization routines...");
                                    "{\"status\":\"success\",\"action\":\"memory_optimization_triggered\"}\n".to_string()
                                }
                                _ => "{\"status\":\"error\",\"message\":\"unknown command\"}\n".to_string()
                            };

                            let _ = socket.write_all(response.as_bytes()).await;
                        }
                    });
                }
                Err(e) => eprintln!("IPC Connection error: {}", e),
            }
        }
    });

    // 3. Graceful Shutdown Handlers (Unix SIGINT / SIGTERM)
    let mut sigterm = signal(SignalKind::terminate())?;
    let mut sigint = signal(SignalKind::interrupt())?;

    tokio::select! {
        _ = sigterm.recv() => println!("\nReceived SIGTERM. Shutting down gracefully..."),
        _ = sigint.recv() => println!("\nReceived SIGINT (Ctrl+C). Shutting down gracefully..."),
    }

    // Cleanup tasks
    monitor_handle.abort();
    ipc_handle.abort();
    let _ = fs::remove_file(SOCKET_PATH).await;
    println!("Cleaned up Unix sockets. Exiting.");

    Ok(())
}
```

