### 2. The Daemon Implementation (`src/main.rs`)

This daemon monitors CPU and memory usage every 2 seconds. If memory usage exceeds 90%, it triggers a simulated "mitigation action" (a placeholder where you could clear OS caches, restart services, or kill rogue processes).

```rust
use std::fs::File;
use std::io::{Read, Seek, SeekFrom};
use std::sync::atomic::{AtomicBool, Ordering};
use std::thread;
use std::time::{Duration, Instant};

// Global flag to handle graceful shutdown
static RUNNING: AtomicBool = AtomicBool::new(true);

// POSIX Signal Handler
extern "C" fn handle_signal(sig: libc::c_int) {
    if sig == libc::SIGTERM || sig == libc::SIGINT {
        RUNNING.store(false, Ordering::SeqCst);
    }
}

// Register system signals
fn setup_signal_handlers() {
    unsafe {
        libc::signal(libc::SIGTERM, handle_signal as libc::sighandler_t);
        libc::signal(libc::SIGINT, handle_signal as libc::sighandler_t);
    }
}

struct CpuSample {
    active: u64,
    total: u64,
}

struct SystemMonitor {
    proc_stat: File,
    proc_meminfo: File,
    buffer: String,
    last_cpu: CpuSample,
}

impl SystemMonitor {
    fn new() -> std::io::Result<Self> {
        let mut monitor = Self {
            proc_stat: File::open("/proc/stat")?,
            proc_meminfo: File::open("/proc/meminfo")?,
            // Pre-allocate buffer to prevent heap allocations during runtime
            buffer: String::with_capacity(4096),
            last_cpu: CpuSample { active: 0, total: 0 },
        };

        // Initialize CPU values
        monitor.last_cpu = monitor.sample_cpu()?;
        Ok(monitor)
    }

    // High-performance CPU parser: reads /proc/stat without memory allocations
    fn sample_cpu(&mut self) -> std::io::Result<CpuSample> {
        self.proc_stat.seek(SeekFrom::Start(0))?;
        self.buffer.clear();
        self.proc_stat.read_to_string(&mut self.buffer)?;

        // Find the first line starting with "cpu "
        let first_line = self.buffer.lines().next().unwrap_or("");
        let mut parts = first_line.split_whitespace().skip(1); // skip "cpu"

        let mut user = 0u64;
        let mut nice = 0u64;
        let mut system = 0u64;
        let mut idle = 0u64;
        let mut iowait = 0u64;
        let mut irq = 0u64;
        let mut softirq = 0u64;
        let mut steal = 0u64;

        if let Some(val) = parts.next() { user = val.parse().unwrap_or(0); }
        if let Some(val) = parts.next() { nice = val.parse().unwrap_or(0); }
        if let Some(val) = parts.next() { system = val.parse().unwrap_or(0); }
        if let Some(val) = parts.next() { idle = val.parse().unwrap_or(0); }
        if let Some(val) = parts.next() { iowait = val.parse().unwrap_or(0); }
        if let Some(val) = parts.next() { irq = val.parse().unwrap_or(0); }
        if let Some(val) = parts.next() { softirq = val.parse().unwrap_or(0); }
        if let Some(val) = parts.next() { steal = val.parse().unwrap_or(0); }

        let idle_time = idle + iowait;
        let active_time = user + nice + system + irq + softirq + steal;
        let total_time = active_time + idle_time;

        Ok(CpuSample {
            active: active_time,
            total: total_time,
        })
    }

    // High-performance Memory parser: reads /proc/meminfo
    fn get_memory_usage(&mut self) -> std::io::Result<f32> {
        self.proc_meminfo.seek(SeekFrom::Start(0))?;
        self.buffer.clear();
        self.proc_meminfo.read_to_string(&mut self.buffer)?;

        let mut mem_total: u64 = 0;
        let mut mem_available: u64 = 0;

        for line in self.buffer.lines() {
            if line.starts_with("MemTotal:") {
                mem_total = parse_kb(line);
            } else if line.starts_with("MemAvailable:") {
                mem_available = parse_kb(line);
            }
            if mem_total > 0 && mem_available > 0 {
                break;
            }
        }

        if mem_total == 0 {
            return Ok(0.0);
        }

        let used = mem_total - mem_available;
        Ok((used as f32 / mem_total as f32) * 100.0)
    }

    fn monitor_tick(&mut self) {
        // 1. Calculate CPU Usage
        if let Ok(current_cpu) = self.sample_cpu() {
            let total_diff = current_cpu.total.saturating_sub(self.last_cpu.total) as f32;
            let active_diff = current_cpu.active.saturating_sub(self.last_cpu.active) as f32;

            let cpu_usage = if total_diff > 0.0 {
                (active_diff / total_diff) * 100.0
            } else {
                0.0
            };

            self.last_cpu = current_cpu;

            // 2. Calculate Memory Usage
            if let Ok(mem_usage) = self.get_memory_usage() {
                println!(
                    "[{:?}] CPU: {:.2}% | MEM: {:.2}%", 
                    Instant::now(), cpu_usage, mem_usage
                );

                // 3. Resource Management Action (Mitigation)
                if mem_usage > 90.0 {
                    eprintln!("WARNING: Memory utilization exceeds critical limit (90%)! Triggering mitigation...");
                    self.mitigate_high_memory();
                }
            }
        }
    }

    // Placeholder for resource management action
    fn mitigate_high_memory(&self) {
        // Real-world daemon would clear OS pagecache, send alert, 
        // or signal systemd to restart memory-heavy target units.
        #[cfg(target_os = "linux")]
        {
            println!("Mitigation: Instructing OS to drop page cache...");
            // Example write to /proc/sys/vm/drop_caches (requires root)
            if let Err(e) = std::fs::write("/proc/sys/vm/drop_caches", "1") {
                eprintln!("Mitigation failed: {}", e);
            }
        }
    }
}

// Helper to extract kilobytes from /proc/meminfo lines
fn parse_kb(line: &str) -> u64 {
    line.split_whitespace()
        .nth(1)
        .and_then(|val| val.parse::<u64>().ok())
        .unwrap_or(0)
}

fn main() {
    setup_signal_handlers();
    println!("System Monitoring Daemon started successfully.");

    let mut monitor = match SystemMonitor::new() {
        Ok(m) => m,
        Err(e) => {
            eprintln!("Failed to initialize OS metrics reader: {}", e);
            std::process::exit(1);
        }
    };

    // Daemon loop (runs until SIGINT/SIGTERM received)
    while RUNNING.load(Ordering::SeqCst) {
        monitor.monitor_tick();
        thread::sleep(Duration::from_secs(2));
    }

    println!("Graceful shutdown complete.");
}
```

