### The Daemon Implementation (`src/main.rs`)

Replace the contents of `src/main.rs` with the following implementation:

```rust
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::Arc;
use std::thread;
use std::time::Duration;
use sysinfo::{Pid, ProcessExt, System, SystemExt};

// Configuration constants
const MEMORY_THRESHOLD_PCT: f32 = 90.0; // Trigger mitigation at 90% memory usage
const POLL_INTERVAL_SECS: u64 = 2;       // Poll OS metrics every 2 seconds

fn main() {
    // 1. Initialize high-performance logger (writes to stdout, captured by journald)
    env_logger::Builder::from_env(env_logger::Env::default().default_filter_or("info")).init();
    log::info!("Starting resourced daemon...");

    // 2. Set up graceful shutdown handling using atomic flags
    let term_signal = Arc::new(AtomicBool::new(false));
    register_signal_handlers(Arc::clone(&term_signal))?;

    // 3. Initialize the OS metrics collector
    // We only load what we need to minimize memory footprint and CPU overhead.
    let mut sys = System::new_all();
    sys.refresh_memory();

    log::info!(
        "Monitoring started. Total Memory: {} MB. Threshold: {}%",
        sys.total_memory() / 1024 / 1024,
        MEMORY_THRESHOLD_PCT
    );

    // 4. Main Event Loop
    while !term_signal.load(Ordering::Relaxed) {
        // Refresh only memory and process list (high performance, avoids disk/network overhead)
        sys.refresh_memory();

        let total_mem = sys.total_memory() as f32;
        let used_mem = sys.used_memory() as f32;
        let mem_usage_pct = (used_mem / total_mem) * 100.0;

        log::debug!("Current memory utilization: {:.2}%", mem_usage_pct);

        if mem_usage_pct > MEMORY_THRESHOLD_PCT {
            log::warn!(
                "Memory usage critical: {:.2}%! Initiating mitigation protocols...",
                mem_usage_pct
            );

            // Refresh processes to find the offending process
            sys.refresh_processes();
            if let Some((pid, name, mem_kb)) = find_top_memory_consumer(&sys) {
                mitigate_oom_threat(pid, &name, mem_kb);
            }
        }

        // High-performance sleep: yields the thread to the OS scheduler
        thread::sleep(Duration::from_secs(POLL_INTERVAL_SECS));
    }

    log::info!("Shutdown signal received. Cleaning up resources...");
    log::info!("resourced daemon stopped successfully.");
    Ok(())
}

/// Scans the OS process table and returns the PID, Name, and RSS memory (in KB) of the top consumer.
fn find_top_memory_consumer(sys: &System) -> Option<(Pid, String, u64)> {
    sys.processes()
        .iter()
        .map(|(pid, process)| (*pid, process.name().to_string(), process.memory()))
        .max_by_key(|&(_, _, mem)| mem)
}

/// Resource Management Action: Mitigates out-of-memory threats.
/// In a production environment, this would send SIGTERM/SIGKILL or adjust cgroup limits.
fn mitigate_oom_threat(pid: Pid, proc_name: &str, mem_kb: u64) {
    let mem_mb = mem_kb / 1024;
    log::error!(
        "CRITICAL: Process '{}' (PID: {}) is consuming {} MB of memory.",
        proc_name,
        pid,
        mem_mb
    );

    // CRITICAL ACTION (Simulated):
    // Under real production environments, you might do:
    // std::process::Command::new("kill").arg("-9").arg(pid.to_string()).spawn();
    log::warn!(
        "[MITIGATION] Action required: Sent simulation event to terminate PID {} ({})",
        pid,
        proc_name
    );
}

/// Registers OS signals for graceful termination.
fn register_signal_handlers(term_signal: Arc<AtomicBool>) -> Result<(), std::io::Error> {
    use signal_hook::consts::signal::*;
    use signal_hook::flag;

    // Map SIGTERM and SIGINT to set our atomic boolean to true
    flag::register(SIGTERM, Arc::clone(&term_signal))?;
    flag::register(SIGINT, term_signal)?;
    Ok(())
}
```

