```rust
use std::time::Duration;
use sysinfo::{CpuRefreshKind, MemoryRefreshKind, ProcessRefreshKind, System};
use tokio::signal::unix::{signal, SignalKind};
use tracing::{error, info, warn, Level};
use tracing_subscriber::FmtSubscriber;

// Configuration Thresholds
const MEMORY_THRESHOLD_PERCENT: f32 = 80.0;
const MONITOR_INTERVAL_SECS: u64 = 2;

struct Daemon {
    sys: System,
}

impl Daemon {
    fn new() -> Self {
        // Initialize sysinfo. We only enable memory and CPU tracking to keep overhead minimal.
        let mut sys = System::new();
        sys.refresh_cpu_specifics(CpuRefreshKind::nothing().with_cpu_usage());
        sys.refresh_memory_limits();
        Self { sys }
    }

    /// Primary monitoring loop
    async fn run(&mut self) {
        let mut interval = tokio::time::interval(Duration::from_secs(MONITOR_INTERVAL_SECS));

        info!("System daemon started. Monitoring resources...");

        loop {
            tokio::select! {
                _ = interval.tick() => {
                    self.tick().await;
                }
                _ = self.handle_shutdown() => {
                    info!("Shutdown signal received. Exiting gracefully.");
                    break;
                }
            }
        }
    }

    /// A single monitoring and management iteration
    async fn tick(&mut self) {
        // 1. HIGH PERFORMANCE: Refresh ONLY what we need. Avoids disk/network I/O overhead.
        self.sys.refresh_memory_only();
        self.sys.refresh_cpu_specifics(CpuRefreshKind::nothing().with_cpu_usage());

        // 2. Extract Memory Metrics
        let total_mem = self.sys.total_memory() as f32;
        let used_mem = self.sys.used_memory() as f32;
        let mem_usage_pct = (used_mem / total_mem) * 100.0;

        // 3. Extract CPU Metrics
        let global_cpu_usage = self.sys.global_cpu_info().cpu_usage();

        info!(
            "Metrics - CPU: {:.1}%, RAM: {:.1}% ({:.2} GB / {:.2} GB)",
            global_cpu_usage,
            mem_usage_pct,
            used_mem / 1_073_741_824.0, // Convert Bytes to GB
            total_mem / 1_073_741_824.0
        );

        // 4. RESOURCE MANAGEMENT (Policy Engine)
        // If memory usage exceeds our limit, identify the culprit and mitigate.
        if mem_usage_pct > MEMORY_THRESHOLD_PERCENT {
            warn!(
                "Memory threshold exceeded ({:.1}% > {:.1}%)! Initiating mitigation...",
                mem_usage_pct, MEMORY_THRESHOLD_PERCENT
            );
            self.mitigate_high_memory();
        }
    }

    /// Scan processes, find the offender, and manage the resource allocation.
    fn mitigate_high_memory(&mut self) {
        // Refresh only process memory usage
        self.sys.refresh_processes_specifics(ProcessRefreshKind::nothing().with_memory());

        // Find the process utilizing the most physical memory (RSS)
        let mut processes: Vec<_> = self.sys.processes().values().collect();
        processes.sort_by_key(|p| p.memory());

        if let Some(top_offender) = processes.last() {
            let pid = top_offender.pid();
            let name = top_offender.name();
            let mem_mb = top_offender.memory() / 1_048_576; // Convert Bytes to MB

            warn!(
                "CRITICAL: Process '{}' [PID {}] is consuming {} MB of RAM.",
                name, pid, mem_mb
            );

            // MANAGEMENT ACTION: In a production daemon, you could:
            // 1. Lower its priority (renice) using libc syscalls.
            // 2. Kill the process if it's an unapproved runaway.
            // 3. Send a SIGUSR1 to force it to release memory.
            // Here, we simulate management by signaling the anomaly:
            warn!("Management action: Dispatched warning/mitigation command for PID {}", pid);
        }
    }

    /// Non-blocking wait for OS termination signals (SIGINT / SIGTERM)
    async fn handle_shutdown(&self) {
        let mut sigterm = signal(SignalKind::terminate()).expect("Failed to register SIGTERM handler");
        let mut sigint = signal(SignalKind::interrupt()).expect("Failed to register SIGINT handler");

        tokio::select! {
            _ = sigterm.recv() => {},
            _ = sigint.recv() => {},
        }
    }
}

#[tokio::main]
async fn main() {
    // High-performance structured logging to stdout/journald
    let subscriber = FmtSubscriber::builder()
        .with_max_level(Level::INFO)
        .with_target(false)
        .finish();

    tracing::subscriber::set_global_default(subscriber)
        .expect("Failed to set up logging subscriber");

    // Start daemon
    let mut daemon = Daemon::new();
    daemon.run().await;
}
```

### Why this implementation is high-performance:
1. **Explicit, Selective Allocation:** Inside the `tick()` function, we do *not* call a generic `sys.refresh_all()`. We specifically query only Memory and CPU. The `sysinfo` crate utilizes native `/proc` parsing on Linux and microkernel system calls on macOS.
2. **Asynchronous / Non-Blocking:** We use `tokio::select!` for multiplexing the sleep timer with incoming OS interrupt signals. The daemon has a virtually zero-percent idle CPU footprint.
3. **No Garbage Collection Latency:** Rust manages memory deterministically via scope. There are no sudden pauses or unpredictable latency spikes.

