use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::Arc;
use std::thread;
use std::time::Duration;
use sysinfo::{CpuExt, ProcessExt, System, SystemExt};

// Configuration Constants
const TICK_INTERVAL: Duration = Duration::from_secs(5); // Run check every 5 seconds
const MEMORY_THRESHOLD_PCT: f32 = 85.0;                // Threshold to trigger management actions
const CPU_THRESHOLD_PCT: f32 = 90.0;                   // CPU alert threshold

fn main() {
    // 1. Initialize Logger (Outputs to stdout/stderr for systemd journald to capture)
    env_logger::Builder::from_env(env_logger::Env::default().default_filter_or("info")).init();
    log::info!("Starting High-Performance System Daemon...");

    // 2. Setup Graceful Shutdown Signal Handlers
    // Using atomic booleans allows lock-free, safe signal handling across threads
    let term_signal = Arc::new(AtomicBool::new(false));
    signal_hook::flag::register(signal_hook::consts::SIGTERM, Arc::clone(&term_signal))
        .expect("Failed to register SIGTERM handler");
    signal_hook::flag::register(signal_hook::consts::SIGINT, Arc::clone(&term_signal))
        .expect("Failed to register SIGINT handler");

    // 3. Initialize System Information State
    // We only load CPU and memory details initially to save memory.
    let mut sys = System::new();
    sys.refresh_cpu();
    sys.refresh_memory();

    log::info!(
        "Daemon initialized. Total Memory: {} MB",
        sys.total_memory() / 1024 / 1024
    );

    // 4. Main Daemon Loop
    while !term_signal.load(Ordering::Relaxed) {
        // High Performance: Refresh ONLY CPU and Memory metrics to avoid kernel polling overhead
        sys.refresh_cpu();
        sys.refresh_memory();

        // Perform Monitoring Checks
        check_memory(&mut sys);
        check_cpu(&sys);

        // Sleep until next tick, polling the shutdown flag frequently to ensure snappy shutdown
        for _ in 0..(TICK_INTERVAL.as_millis() / 100) {
            if term_signal.load(Ordering::Relaxed) {
                break;
            }
            thread::sleep(Duration::from_millis(100));
        }
    }

    log::info!("Shutdown signal received. Cleaning up resources and exiting daemon gracefully.");
}

