use std::time::Duration;
use sysinfo::{CpuRefreshKind, MemoryRefreshKind, ProcessRefreshKind, System};
use tokio::signal::unix::{signal, SignalKind};
use tokio::time::interval;
use tracing::{error, info, warn};

// Configuration Constants
const TICK_INTERVAL_SECS: u64 = 5;
const MEMORY_THRESHOLD_BYTES: u64 = 1 * 1024 * 1024 * 1024; // 1 GB Alert/Mitigation limit

struct DaemonState {
    sys: System,
}

impl DaemonState {
    fn new() -> Self {
        // Initialize with empty state. We will selectively refresh what we need.
        Self {
            sys: System::new_with_specifics(
                sysinfo::RefreshKind::new()
                    .with_cpu(CpuRefreshKind::new().with_cpu_usage())
                    .with_memory(MemoryRefreshKind::new().with_ram()),
            ),
        }
    }

    /// High-performance monitoring step.
    /// Only refreshes RAM and CPU usage, avoiding heavy disk/network queries.
    fn monitor_system(&mut self) {
        self.sys.refresh_memory();
        self.sys.refresh_cpu_usage();

        let total_mem = self.sys.total_memory();
        let used_mem = self.sys.used_memory();
        let mem_usage_pct = (used_mem as f64 / total_mem as f64) * 100.0;
        let global_cpu = self.sys.global_cpu_info().cpu_usage();

        info!(
            "System Stats -> CPU: {:.2}%, RAM: {:.2}% ({:.2} GB / {:.2} GB)",
            global_cpu,
            mem_usage_pct,
            used_mem as f64 / 1_073_741_824.0,
            total_mem as f64 / 1_073_741_824.0
        );
    }

    /// Management step: Scans processes and mitigates resource hogs.
    fn manage_resources(&mut self) {
        // Refresh process list with only memory and CPU stats
        self.sys.refresh_processes_specifics(
            ProcessRefreshKind::new()
                .with_memory()
                .with_cpu(),
        );

        for (pid, process) in self.sys.processes() {
            let mem_usage = process.memory();

            // Mitigation Rule: If a process exceeds the RAM threshold
            if mem_usage > MEMORY_THRESHOLD_BYTES {
                warn!(
                    "RESOURCE ALERT: Process [{}] (PID: {}) is using {:.2} MB!",
                    process.name(),
                    pid,
                    mem_usage as f64 / 1_048_576.0
                );

                // --- MITIGATION ACTION ---
                // In a real-world production daemon, you might:
                // 1. Lower its priority: `nix::sys::resource::setpriority(...)`
                // 2. Kill it: `process.kill()`
                // For safety in this initial demo, we just log a warning.
                info!("Mitigation action triggered for PID {}.", pid);
            }
        }
    }
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    // Initialize high-performance structured logging
    tracing_subscriber::fmt()
        .with_env_filter(tracing_subscriber::EnvFilter::from_default_env().or_else(|_| {
            // Default to 'info' logging level if not specified by RUST_LOG env var
            Ok(tracing_subscriber::EnvFilter::new("info"))
        })?)
        .init();

    info!("Initializing Resource Monitoring Daemon...");

    let mut daemon = DaemonState::new();
    let mut ticker = interval(Duration::from_secs(TICK_INTERVAL_SECS));

    // Setup UNIX OS Signal listeners for graceful shutdown
    let mut sigterm = signal(SignalKind::terminate())?;
    let mut sigint = signal(SignalKind::interrupt())?;

    info!("Daemon running. Monitoring intervals: {}s", TICK_INTERVAL_SECS);

    // Main Daemon Event Loop
    loop {
        tokio::select! {
            // Periodic tick for monitoring and resource management
            _ = ticker.tick() => {
                daemon.monitor_system();
                daemon.manage_resources();
            }

            // Graceful Shutdown on SIGTERM (e.g. `systemctl stop`)
            _ = sigterm.recv() => {
                warn!("Received SIGTERM signal. Initiating graceful shutdown...");
                break;
            }

            // Graceful Shutdown on SIGINT (e.g. Ctrl+C)
            _ = sigint.recv() => {
                warn!("Received SIGINT signal. Initiating graceful shutdown...");
                break;
            }
        }
    }

    // Cleanup logic goes here
    info!("Daemon successfully stopped. Cleaning up resources.");
    Ok(())
}
```

