    while running.load(Ordering::SeqCst) {
        let start_time = Instant::now();

        match get_memory_utilization() {
            Ok(mem_util) => {
                if mem_util >= MEM_THRESHOLD_PERCENT {
                    trigger_memory_mitigation(mem_util);
                } else {
                    println!(
                        "[MONITOR] RAM Usage: {:.2}% | Status: OK",
                        mem_util
                    );
                }
            }
            Err(e) => eprintln!("[ERROR] Failed to read system memory: {}", e),
        }

        // Calculate sleep time, subtracting the time spent parsing/executing
        let elapsed = start_time.elapsed();
        let sleep_duration = Duration::from_millis(POLL_INTERVAL_MS).saturating_sub(elapsed);

        // Sleep in small chunks to remain highly responsive to shutdown signals
        let chunk = Duration::from_millis(100);
        let mut slept = Duration::ZERO;
        while slept < sleep_duration && running.load(Ordering::SeqCst) {
            thread::sleep(chunk);
            slept += chunk;
        }
    }

    println!("[INFO] Daemon stopped cleanly. Releasing resources.");
    Ok(())
}

/// Parses `/proc/meminfo` to calculate memory utilization.
/// This approach is highly efficient as it reads the virtual file directly into memory 
/// and parses only the lines needed, bypassing heavy libraries.
fn get_memory_utilization() -> Result<f64, std::io::Error> {
    let file = File::open("/proc/meminfo")?;
    let reader = BufReader::new(file);

    let mut mem_total: u64 = 0;
    let mut mem_available: u64 = 0;

    for line in reader.lines() {
        let line = line?;
        if line.starts_with("MemTotal:") {
            mem_total = parse_kb(&line);
        } else if line.starts_with("MemAvailable:") {
            mem_available = parse_kb(&line);
        }

        // Exit file read early once we have both metrics
        if mem_total > 0 && mem_available > 0 {
            break;
        }
    }

    if mem_total == 0 {
        return Err(std::io::Error::new(
            std::io::ErrorKind::InvalidData,
            "Could not parse total memory",
        ));
    }

    // Calculation: Used Memory = Total - Available
    let mem_used = mem_total - mem_available;
    let utilization = (mem_used as f64 / mem_total as f64) * 100.0;

    Ok(utilization)
}

/// Helper function to extract the numerical value (in KB) from `/proc/meminfo` fields.
fn parse_kb(line: &str) -> u64 {
    line.split_whitespace()
        .nth(1)
        .and_then(|val| val.parse::<u64>().ok())
        .unwrap_or(0)
}

/// Represents the management action triggered when resource limits are breached.
fn trigger_memory_mitigation(current_usage: f64) {
    eprintln!(
        "[WARN] MEMORY EXCEEDED THRESHOLD: {:.2}% (Limit: {}%)",
        current_usage, MEM_THRESHOLD_PERCENT
    );

    // Low-level resource management: Triggering mitigation.
    // Real-world examples of action:
    // 1. Send warning to centralized logging/monitoring (syslog/metrics server).
    // 2. Clear page cache (requires root): std::fs::write("/proc/sys/vm/drop_caches", "3");
    // 3. Kill/restart leaking target processes based on cgroup constraints.
    eprintln!("[ACTION] Purging inactive cache pools / Sending notifications...");
}

