use std::fs::File;
use std::io::{Read, Seek, SeekFrom};
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::Arc;
use std::thread;
use std::time::Duration;

// Threshold for resource management action
const CPU_THRESHOLD_PERCENT: f64 = 80.0;
const CHECK_INTERVAL_SECS: u64 = 1;

#[derive(Default, Debug, Clone, Copy)]
struct CpuStats {
    user: u64,
    nice: u64,
    system: u64,
    idle: u64,
    iowait: u64,
    irq: u64,
    softirq: u64,
    steal: u64,
}

impl CpuStats {
    fn total(&self) -> u64 {
        self.user + self.nice + self.system + self.idle + self.iowait + self.irq + self.softirq + self.steal
    }

    fn idle(&self) -> u64 {
        self.idle + self.iowait
    }
}

// Parses /proc/stat into CpuStats without allocating dynamic memory
fn parse_cpu_stats(file: &mut File, buffer: &mut String) -> Result<CpuStats, std::io::Error> {
    file.seek(SeekFrom::Start(0))?;
    buffer.clear();
    file.read_to_string(buffer)?;

    let first_line = buffer.lines().next().ok_or_else(|| {
        std::io::Error::new(std::io::ErrorKind::InvalidData, "Empty /proc/stat")
    })?;

    let mut parts = first_line.split_whitespace();
    if parts.next() != Some("cpu") {
        return Err(std::io::Error::new(
            std::io::ErrorKind::InvalidData,
            "Invalid CPU data format",
        ));
    }

    let parse_next = |parts: &mut std::str::SplitWhitespace| -> u64 {
        parts.next().and_then(|val| val.parse().ok()).unwrap_or(0)
    };

    Ok(CpuStats {
        user: parse_next(&mut parts),
        nice: parse_next(&mut parts),
        system: parse_next(&mut parts),
        idle: parse_next(&mut parts),
        iowait: parse_next(&mut parts),
        irq: parse_next(&mut parts),
        softirq: parse_next(&mut parts),
        steal: parse_next(&mut parts),
    })
}

fn calculate_cpu_usage(prev: &CpuStats, curr: &CpuStats) -> f64 {
    let prev_idle = prev.idle();
    let curr_idle = curr.idle();

    let prev_total = prev.total();
    let curr_total = curr.total();

    let total_diff = curr_total.saturating_sub(prev_total);
    let idle_diff = curr_idle.saturating_sub(prev_idle);

    if total_diff == 0 {
        0.0
    } else {
        ((total_diff - idle_diff) as f64 / total_diff as f64) * 100.0
    }
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    println!("[INFO] Starting High-Performance System Monitor Daemon...");

    // 1. Setup Signal Handling for Graceful Shutdown (SIGTERM/SIGINT)
    let running = Arc::new(AtomicBool::new(true));
    let r = running.clone();
    ctrlc::set_handler(move || {
        println!("[INFO] Received termination signal. Stopping daemon...");
        r.store(false, Ordering::SeqCst);
    })?;

    // 2. Initialize Resources (Reused to prevent heap allocations in loop)
    let mut stat_file = File::open("/proc/stat")?;
    let mut buffer = String::with_capacity(1024);
    let mut prev_stats = parse_cpu_stats(&mut stat_file, &mut buffer)?;

    println!("[INFO] Daemon is running and monitoring system resources...");

    // 3. Main Monitor & Manage Loop
    while running.load(Ordering::SeqCst) {
        thread::sleep(Duration::from_secs(CHECK_INTERVAL_SECS));

        match parse_cpu_stats(&mut stat_file, &mut buffer) {
            Ok(curr_stats) => {
                let cpu_usage = calculate_cpu_usage(&prev_stats, &curr_stats);
                println!("[METRIC] CPU Usage: {:.2}%", cpu_usage);

                // 4. Resource Management Threshold Action
                if cpu_usage > CPU_THRESHOLD_PERCENT {
                    eprintln!(
                        "[WARN] Alert! CPU usage ({:.2}%) exceeded safety threshold ({:.2}%). Triggering mitigation action!",
                        cpu_usage, CPU_THRESHOLD_PERCENT
                    );
                    // REAL-WORLD ACTION: At this point, you could write to cgroups, 
                    // kill runaway processes, log to syslog, or send a webhook alert.
                }

                prev_stats = curr_stats;
            }
            Err(e) => {
                eprintln!("[ERROR] Failed to read CPU stats: {}", e);
            }
        }
    }

    println!("[INFO] Daemon stopped cleanly.");
    Ok(())
}
