use std::fs::File;
use std::io::{self, BufRead, BufReader};
use std::sync::Arc;
use std::sync::atomic::{AtomicBool, Ordering};
use std::thread;
use std::time::Duration;

// Set memory threshold to 85% for demonstration
const MEM_THRESHOLD_PERCENT: f64 = 85.0;
const TICK_INTERVAL: Duration = Duration::from_secs(2);

struct CpuTicks {
    idle: u64,
    total: u64,
}

fn main() -> io::Result<()> {
    println!("[INFO] Starting System Monitor Daemon...");

    // 1. Setup Signal Handling for Graceful Shutdown (SIGTERM/SIGINT)
    let term = Arc::new(AtomicBool::new(false));
    for sig in signal_hook::consts::TERM_SIGNALS {
        signal_hook::flag::register(*sig, Arc::clone(&term))?;
    }

    // 2. Initialize CPU monitoring (requires two samples to calculate delta)
    let mut last_cpu = get_cpu_ticks()?;

    // 3. Main Daemon Loop
    while !term.load(Ordering::Relaxed) {
        thread::sleep(TICK_INTERVAL);

        // --- Memory Monitoring ---
        match get_mem_usage() {
            Ok((total, available)) => {
                let used = total - available;
                let percent_used = (used as f64 / total as f64) * 100.0;

                println!("[INFO] Memory Usage: {:.2}% ({}/{} MB)", percent_used, used / 1024, total / 1024);

                // Management Action: If memory usage exceeds threshold
                if percent_used > MEM_THRESHOLD_PERCENT {
                    handle_high_memory(percent_used);
                }
            }
            Err(e) => eprintln!("[ERROR] Failed to read memory info: {}", e),
        }

        // --- CPU Monitoring ---
        match get_cpu_ticks() {
            Ok(current_cpu) => {
                let idle_delta = current_cpu.idle as f64 - last_cpu.idle as f64;
                let total_delta = current_cpu.total as f64 - last_cpu.total as f64;

                if total_delta > 0.0 {
                    let cpu_usage = (1.0 - (idle_delta / total_delta)) * 100.0;
                    println!("[INFO] CPU Usage: {:.2}%", cpu_usage);
                }
                last_cpu = current_cpu;
            }
            Err(e) => eprintln!("[ERROR] Failed to read CPU info: {}", e),
        }
    }

    println!("[INFO] Daemon stopped gracefully.");
    Ok(())
}

/// Parses `/proc/meminfo` to get Total and Available memory in KB.
fn get_mem_usage() -> io::Result<(u64, u64)> {
    let file = File::open("/proc/meminfo")?;
    let reader = BufReader::new(file);
    let mut mem_total = 0;
    let mut mem_avail = 0;

    for line in reader.lines() {
        let line = line?;
        if line.starts_with("MemTotal:") {
            mem_total = parse_kb_value(&line);
        } else if line.starts_with("MemAvailable:") {
            mem_avail = parse_kb_value(&line);
        }
        if mem_total > 0 && mem_avail > 0 {
            break;
        }
    }
    Ok((mem_total, mem_avail))
}

/// Parses `/proc/stat` to get aggregate CPU ticks.
fn get_cpu_ticks() -> io::Result<CpuTicks> {
    let file = File::open("/proc/stat")?;
    let mut reader = BufReader::new(file);
    let mut first_line = String::new();
    reader.read_line(&mut first_line)?;

    let parts: Vec<&str> = first_line.split_whitespace().collect();
    if parts.len() < 5 || parts[0] != "cpu" {
        return Err(io::Error::new(io::ErrorKind::InvalidData, "Invalid /proc/stat format"));
    }

    // Index mapping for /proc/stat:
    // user: 1, nice: 2, system: 3, idle: 4, iowait: 5, irq: 6, softirq: 7, steal: 8
    let user: u64 = parts[1].parse().unwrap_or(0);
    let nice: u64 = parts[2].parse().unwrap_or(0);
    let system: u64 = parts[3].parse().unwrap_or(0);
    let idle: u64 = parts[4].parse().unwrap_or(0);
    let iowait: u64 = parts[5].parse().unwrap_or(0);
    let irq: u64 = parts[6].parse().unwrap_or(0);
    let softirq: u64 = parts[7].parse().unwrap_or(0);
    let steal: u64 = parts[8].parse().unwrap_or(0);

    let idle_ticks = idle + iowait;
    let non_idle_ticks = user + nice + system + irq + softirq + steal;
    let total_ticks = idle_ticks + non_idle_ticks;

    Ok(CpuTicks {
        idle: idle_ticks,
        total: total_ticks,
    })
}

/// Helper to parse numeric values from /proc/meminfo lines.
fn parse_kb_value(line: &str) -> u64 {
    line.split_whitespace()
        .nth(1)
        .and_then(|val| val.parse::<u64>().ok())
        .unwrap_or(0)
}

/// Management logic triggered when OS resources are strained.
fn handle_high_memory(usage: f64) {
    eprintln!(
        "[WARNING] ALERT: Memory usage is at {:.2}%! Performing OS resource management action...",
        usage
    );
    // Real-world examples of actions here:
    // 1. Command systemd to restart a bloated service: `std::process::Command::new("systemctl").args(["restart", "apache2"]).spawn();`
    // 2. Trigger kernel cache dropping (requires root): `std::fs::write("/proc/sys/vm/drop_caches", "3");`
    // 3. Send an alert webhook.
}
