### 2. The Daemon Code (`src/main.rs`)

Replace the contents of `src/main.rs` with the following code. It uses an atomic flag for safe, lock-free shutdown coordination and the `sysinfo` crate for low-overhead kernel querying.

```rust
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::Arc;
use std::thread;
use std::time::Duration;
use sysinfo::{CpuRefreshKind, MemoryRefreshKind, System};

// Memory limit threshold (e.g., 85% usage) to trigger management action
const MEMORY_THRESHOLD_PCT: f32 = 85.0;
const TICK_INTERVAL: Duration = Duration::from_secs(2);

fn main() -> Result<(), Box<dyn std::error::Error>> {
    println!("[INFO] Starting system-daemon...");

    // 1. Setup Signal Handling for Graceful Shutdown
    // This allows systemd to stop the daemon cleanly via SIGTERM (exit code 0)
    let term = Arc::new(AtomicBool::new(false));
    signal_hook::flag::register(signal_hook::consts::SIGTERM, Arc::clone(&term))?;
    signal_hook::flag::register(signal_hook::consts::SIGINT, Arc::clone(&term))?;

    // 2. Initialize the System monitor (queries memory and CPU only, reducing overhead)
    let mut sys = System::new_with_specifics(
        sysinfo::RefreshKind::new()
            .with_memory(MemoryRefreshKind::everything())
            .with_cpu(CpuRefreshKind::everything()),
    );

    println!("[INFO] Daemon running. Monitoring system resources...");

    // 3. Main Event Loop
    while !term.load(Ordering::Relaxed) {
        // Refresh system metrics
        sys.refresh_memory();
        sys.refresh_cpu_all();

        // Calculate Memory Metrics
        let total_mem = sys.total_memory() as f32;
        let used_mem = sys.used_memory() as f32;
        let mem_usage_pct = (used_mem / total_mem) * 100.0;

        // Calculate CPU Metrics (average across all cores)
        let global_cpu_usage = sys.global_cpu_info().cpu_usage();

        // Print/log metrics (in a production daemon, this could write to journald or a TSDB)
        println!(
            "[MONITOR] CPU Usage: {:.1}% | Memory Usage: {:.1}% ({:.2} GB / {:.2} GB)",
            global_cpu_usage,
            mem_usage_pct,
            used_mem / 1_073_741_824.0, // Convert bytes to GiB
            total_mem / 1_073_741_824.0
        );

        // 4. Resource Management / Mitigation Action
        if mem_usage_pct > MEMORY_THRESHOLD_PCT {
            eprintln!(
                "[WARN] Memory usage {:.1}% exceeded threshold of {:.1}%!",
                mem_usage_pct, MEMORY_THRESHOLD_PCT
            );
            take_mitigation_action(&mut sys);
        }

        // Sleep until next tick (checking for shutdown signal periodically)
        thread::sleep(TICK_INTERVAL);
    }

    println!("[INFO] Graceful shutdown complete. Exiting.");
    Ok(())
}

// Simulated management action (e.g., finding and killing memory-hogging processes)
fn take_mitigation_action(sys: &mut System) {
    println!("[MANAGE] Scanning for high-memory processes to mitigate pressure...");

    // Refresh process list to find the culprit
    sys.refresh_processes();

    let mut processes: Vec<_> = sys.processes().values().collect();
    // Sort processes by memory usage descending
    processes.sort_by(|a, b| b.memory().cmp(&a.memory()));

    if let Some(top_hog) = processes.first() {
        println!(
            "[MANAGE] Action Recommended: Process '{}' (PID: {}) is using {:.2} MB",
            top_hog.name(),
            top_hog.pid(),
            top_hog.memory() as f32 / 1_048_576.0
        );
        // In a real daemon, you would use top_hog.kill() here if authorized
    }
}
