```rust
use ahash::RandomState;
use crossbeam_channel::{bounded, Receiver, Sender};
use dashmap::DashMap;
use pcap::{Active, Capture, Precision};
use std::net::Ipv4Addr;
use std::sync::atomic::{AtomicU64, Ordering};
use std::sync::Arc;
use std::thread;
use std::time::{Duration, Instant};

// --- Data Structures ---

#[derive(Hash, PartialEq, Eq, Clone, Copy, Debug)]
struct FlowKey {
    src_ip: u32,
    dst_ip: u32,
    src_port: u16,
    dst_port: u16,
    proto: u8,
}

#[derive(Clone, Copy, Debug)]
struct FlowStats {
    packets: u64,
    bytes: u64,
    first_seen: Instant,
    last_seen: Instant,
}

// Fixed-size message sent from Capture Thread -> Worker Threads
struct PacketUpdate {
    key: FlowKey,
    len: u32,
}

// Global Performance Counters
struct Metrics {
    processed_packets: AtomicU64,
    processed_bytes: AtomicU64,
    dropped_packets: AtomicU64,
}

lazy_static::lazy_static! {
    static ref METRICS: Metrics = Metrics {
        processed_packets: AtomicU64::new(0),
        processed_bytes: AtomicU64::new(0),
        dropped_packets: AtomicU64::new(0),
    };
}

// --- High-Performance Parsing ---

#[inline(always)]
fn parse_packet_metadata(packet: &[u8]) -> Option<(FlowKey, u32)> {
    // 1. Ethernet Header (14 bytes)
    if packet.len() < 14 { return None; }
    let ether_type = u16::from_be_bytes([packet[12], packet[13]]);
    if ether_type != 0x0800 { // IPv4 Only for this demo
        return None; 
    }

    // 2. IPv4 Header (min 20 bytes)
    let ip_start = 14;
    if packet.len() < ip_start + 20 { return None; }

    let ihl = (packet[ip_start] & 0x0F) as usize * 4;
    if packet.len() < ip_start + ihl { return None; }

    let total_len = u16::from_be_bytes([packet[ip_start + 2], packet[ip_start + 3]]) as u32;
    let proto = packet[ip_start + 9];

    let src_ip = u32::from_be_bytes([
        packet[ip_start + 12], packet[ip_start + 13],
        packet[ip_start + 14], packet[ip_start + 15]
    ]);
    let dst_ip = u32::from_be_bytes([
        packet[ip_start + 16], packet[ip_start + 17],
        packet[ip_start + 18], packet[ip_start + 19]
    ]);

    // 3. Transport Layer Header (TCP / UDP / ICMP)
    let transport_start = ip_start + ihl;
    let (src_port, dst_port) = match proto {
        6 | 17 => { // TCP or UDP
            if packet.len() < transport_start + 4 { return None; }
            let src_p = u16::from_be_bytes([packet[transport_start], packet[transport_start + 1]]);
            let dst_p = u16::from_be_bytes([packet[transport_start + 2], packet[transport_start + 3]]);
            (src_p, dst_p)
        }
        _ => (0, 0), // Non-port protocols (like ICMP)
    };

    Some((
        FlowKey { src_ip, dst_ip, src_port, dst_port, proto },
        total_len
    ))
}

// --- Main Runner ---

fn main() {
    // 1. Initialize network device for capture
    let device = Device::lookup().expect("No default device found").unwrap();
    println!("Capturing on device: {}", device.name);

    let mut cap = Capture::from_device(device)
        .unwrap()
        .promisc(true)
        .snaplen(96) // Capture only headers (truncates payload to save memory bandwidth)
        .buffer_size(32 * 1024 * 1024) // 32MB Kernel ring-buffer to prevent packet drops
        .immediate_mode(true)
        .precision(Precision::Nano)
        .open()
        .expect("Failed to initialize capture handle");

    // Filter to capture only IP traffic
    cap.filter("ip", true).unwrap();

    // 2. Instantiate Concurrent Flow Table (using high-speed non-cryptographic hashing)
    let flow_table: Arc<DashMap<FlowKey, FlowStats, RandomState>> = Arc::new(DashMap::with_hasher(RandomState::new()));

    // 3. Create lock-free MPMC queue to distribute parsed packets to workers
    let (tx, rx): (Sender<PacketUpdate>, Receiver<PacketUpdate>) = bounded(100_000);

    // 4. Spawn Worker Threads
    let num_workers = num_cpus::get().saturating_sub(2).max(1); // Leave 1 core for Capture, 1 for Metrics
    println!("Spawning {} worker threads...", num_workers);
    for _ in 0..num_workers {
        let rx_clone = rx.clone();
        let flow_table_clone = flow_table.clone();
        thread::spawn(move || {
            while let Ok(update) = rx_clone.recv() {
                let now = Instant::now();
                flow_table_clone
                    .entry(update.key)
                    .and_modify(|stats| {
                        stats.packets += 1;
                        stats.bytes += update.len as u64;
                        stats.last_seen = now;
                    })
                    .or_insert(FlowStats {
                        packets: 1,
                        bytes: update.len as u64,
                        first_seen: now,
                        last_seen: now,
                    });
            }
        });
    }

    // 5. Spawn Async Metrics/Reporter Thread
    let flow_table_metrics = flow_table.clone();
    thread::spawn(move || {
        let mut last_packets = 0;
        let mut last_bytes = 0;
        loop {
            thread::sleep(Duration::from_secs(1));

            let current_pkts = METRICS.processed_packets.load(Ordering::Relaxed);
            let current_bytes = METRICS.processed_bytes.load(Ordering::Relaxed);
            let dropped = METRICS.dropped_packets.load(Ordering::Relaxed);

            let pps = current_pkts - last_packets;
            let bps = (current_bytes - last_bytes) * 8; // bits per second
            let active_flows = flow_table_metrics.len();

            println!(
                "[STATS] Active Flows: {:<8} | PPS: {:<10} | Throughput: {:<7.2} Mbps | Drops: {}",
                active_flows,
                pps,
                (bps as f64) / 1_000_000.0,
                dropped
            );

            last_packets = current_pkts;
            last_bytes = current_bytes;
        }
    });

    // 6. Execute Main Capture Loop (Runs on its own dedicated core)
    println!("Analyzer running. Press Ctrl+C to terminate...");
    loop {
        match cap.next_packet() {
            Ok(packet) => {
                if let Some((key, len)) = parse_packet_metadata(packet.data) {
                    let update = PacketUpdate { key, len };

                    // Non-blocking try_send to avoid stalling the capture loop if workers are busy
                    if tx.try_send(update).is_ok() {
                        METRICS.processed_packets.fetch_add(1, Ordering::Relaxed);
                        METRICS.processed_bytes.fetch_add(len as u64, Ordering::Relaxed);
                    } else {
                        METRICS.dropped_packets.fetch_add(1, Ordering::Relaxed);
                    }
                }
            }
            Err(pcap::Error::TimeoutExpired) => continue,
            Err(e) => {
                eprintln!("PCAP Error: {:?}", e);
                break;
            }
        }
    }
}
```

