```rust
use crossbeam_channel::{bounded, Receiver, Sender};
use dashmap::DashMap;
use lazy_static::lazy_static;
use pcap::{Capture, Device};
use std::net::IpAddr;
use std::sync::Arc;
use std::thread;
use std::time::{Duration, Instant};

// Max size of an Ethernet frame (MTU 1500 + headers)
const MAX_PACKET_SIZE: usize = 1600;
const BUFFER_POOL_SIZE: usize = 200_000; // Keep 200k packets pre-allocated in RAM

// --- Data Structures ---

#[derive(Hash, PartialEq, Eq, Clone, Copy, Debug)]
pub struct FlowKey {
    pub src_ip: IpAddr,
    pub dst_ip: IpAddr,
    pub src_port: u16,
    pub dst_port: u16,
    pub protocol: u8,
}

#[derive(Clone, Debug)]
pub struct FlowStats {
    pub packet_count: u64,
    pub byte_count: u64,
    pub first_seen: Instant,
    pub last_seen: Instant,
}

// Pre-allocated reusable packet container to avoid allocator churn
pub struct PacketBuffer {
    pub data: Vec<u8>,
    pub len: usize,
    pub timestamp: Instant,
}

lazy_static! {
    // Sharded concurrent hashmap to hold flow records
    static ref FLOW_TABLE: Arc<DashMap<FlowKey, FlowStats>> = Arc::new(DashMap::with_shard_amount(256));
}

fn main() {
    // Select the first active network interface
    let device = Device::lookup().expect("No active interface found").expect("No device found");
    println!("Monitoring interface: {}", device.name);

    // Channels for the lock-free pipeline
    // tx_analysis: sends filled packets to worker threads
    // tx_recycle: sends empty buffers back to the capture thread
    let (tx_analysis, rx_analysis) = bounded::<PacketBuffer>(BUFFER_POOL_SIZE);
    let (tx_recycle, rx_recycle) = bounded::<PacketBuffer>(BUFFER_POOL_SIZE);

    // Pre-populate the recycler pool with pre-allocated buffers
    for _ in 0..BUFFER_POOL_SIZE {
        tx_recycle
            .send(PacketBuffer {
                data: vec![0u8; MAX_PACKET_SIZE],
                len: 0,
                timestamp: Instant::now(),
            })
            .unwrap();
    }

    // 1. Spawn Packet Capture Thread (Pinned to a single core in production)
    let capture_handle = thread::spawn({
        let device_name = device.name.clone();
        move || {
            capture_packets(&device_name, tx_analysis, rx_recycle);
        }
    });

    // 2. Spawn Worker Threads for processing and parsing
    let num_workers = num_cpus::get().saturating_sub(2).max(1);
    let mut worker_handles = vec![];
    for _ in 0..num_workers {
        let rx_analysis_clone = rx_analysis.clone();
        let tx_recycle_clone = tx_recycle.clone();
        let handle = thread::spawn(move || {
            worker_loop(rx_analysis_clone, tx_recycle_clone);
        });
        worker_handles.push(handle);
    }

    // 3. Spawn Statistics Reporter Thread
    let reporter_handle = thread::spawn(|| {
        reporter_loop();
    });

    // Wait for shutdown (Ctrl+C not explicitly handled here for simplicity)
    capture_handle.join().unwrap();
    for handle in worker_handles {
        handle.join().unwrap();
    }
    reporter_handle.join().unwrap();
}

// --- Capture Logic ---
fn capture_packets(
    device_name: &str,
    tx_analysis: Sender<PacketBuffer>,
    rx_recycle: Receiver<PacketBuffer>,
) {
    // Configure pcap for maximum performance
    let mut cap = Capture::from_device(device_name)
        .unwrap()
        .promisc(true)
        .snaplen(MAX_PACKET_SIZE as i32)
        .buffer_size(64 * 1024 * 1024) // 64MB kernel-space buffer to prevent packet drops
        .timeout(1) // Non-blocking/immediate dispatch
        .open()
        .unwrap();

    println!("Capture engine running...");

    loop {
        match cap.next_packet() {
            Ok(packet) => {
                // Grab an empty buffer from the recycle pool (Zero-Allocation path)
                if let Ok(mut buf) = rx_recycle.try_recv() {
                    let length = packet.data.len().min(MAX_PACKET_SIZE);
                    buf.data[..length].copy_from_slice(&packet.data[..length]);
                    buf.len = length;
                    buf.timestamp = Instant::now();

                    // Send to workers. If queue is full, drop to prevent backpressure latency
                    if let Err(_) = tx_analysis.try_send(buf) {
                        // Queue full, packet dropped (increment an atomic counter here in production)
                    }
                }
            }
            Err(pcap::Error::TimeoutExpired) => continue,
            Err(e) => {
                eprintln!("Capture error: {:?}", e);
                break;
            }
        }
    }
}

// --- Processing Logic ---
fn worker_loop(rx_analysis: Receiver<PacketBuffer>, tx_recycle: Sender<PacketBuffer>) {
    while let Ok(buf) = rx_analysis.recv() {
        // Zero-copy parse of the packet headers
        if let Some((flow_key, payload_len)) = parse_packet_zero_copy(&buf.data[..buf.len]) {
            // Update the Flow Table
            let mut entry = FLOW_TABLE.entry(flow_key).or_insert(FlowStats {
                packet_count: 0,
                byte_count: 0,
                first_seen: buf.timestamp,
                last_seen: buf.timestamp,
            });

            entry.packet_count += 1;
            entry.byte_count += payload_len as u64;
            entry.last_seen = buf.timestamp;
        }

        // Return the buffer to the pool for reuse
        let _ = tx_recycle.send(buf);
    }
}

// --- High Performance Zero-Copy Parser ---
#[inline(always)]
fn parse_packet_zero_copy(packet_data: &[u8]) -> Option<(FlowKey, usize)> {
    // Minimum Ethernet frame length is 14 bytes
    if packet_data.len() < 14 {
        return None;
    }

    let ether_type = u16::from_be_bytes([packet_data[12], packet_data[13]]);
    let mut offset = 14;

    match ether_type {
        0x0800 => {
            // IPv4
            if packet_data.len() < offset + 20 {
                return None;
            }
            let ip_header = &packet_data[offset..offset + 20];
            let ihl = (ip_header[0] & 0x0F) as usize * 4;
            let total_len = u16::from_be_bytes([ip_header[2], ip_header[3]]) as usize;
            let protocol = ip_header[9];

            let src_ip = IpAddr::V4(std::net::Ipv4Addr::new(
                ip_header[12],
                ip_header[13],
                ip_header[14],
                ip_header[15],
            ));
            let dst_ip = IpAddr::V4(std::net::Ipv4Addr::new(
                ip_header[16],
                ip_header[17],
                ip_header[18],
                ip_header[19],
            ));

            offset += ihl;
            if packet_data.len() < offset + 4 {
                return None;
            }

            // Extract UDP/TCP Ports
            let src_port = u16::from_be_bytes([packet_data[offset], packet_data[offset + 1]]);
            let dst_port = u16::from_be_bytes([packet_data[offset + 2], packet_data[offset + 3]]);

            Some((
                FlowKey {
                    src_ip,
                    dst_ip,
                    src_port,
                    dst_port,
                    protocol,
                },
                total_len,
            ))
        }
        0x86DD => {
            // IPv6
            if packet_data.len() < offset + 40 {
                return None;
            }
            let ip_header = &packet_data[offset..offset + 40];
            let payload_len = u16::from_be_bytes([ip_header[4], ip_header[5]]) as usize;
            let protocol = ip_header[6]; // Next Header

            let mut src_bytes = [0u8; 16];
            src_bytes.copy_from_slice(&ip_header[8..24]);
            let src_ip = IpAddr::V6(std::net::Ipv6Addr::from(src_bytes));

            let mut dst_bytes = [0u8; 16];
            dst_bytes.copy_from_slice(&ip_header[24..40]);
            let dst_ip = IpAddr::V6(std::net::Ipv6Addr::from(dst_bytes));

            offset += 40;
            if packet_data.len() < offset + 4 {
                return None;
            }

            let src_port = u16::from_be_bytes([packet_data[offset], packet_data[offset + 1]]);
            let dst_port = u16::from_be_bytes([packet_data[offset + 2], packet_data[offset + 3]]);

            Some((
                FlowKey {
                    src_ip,
                    dst_ip,
                    src_port,
                    dst_port,
                    protocol,
                },
                payload_len + 40,
            ))
        }
        _ => None, // Ignore Non-IP (ARP, etc.)
    }
}

// --- Stats Exporter ---
fn reporter_loop() {
    loop {
        thread::sleep(Duration::from_secs(5));

        println!("\n=== ACTIVE FLOWS REPORT (Last 5 Seconds) ===");
        let mut total_packets = 0;
        let mut total_bytes = 0;

        for entry in FLOW_TABLE.iter() {
            let (key, stats) = entry.pair();
            total_packets += stats.packet_count;
            total_bytes += stats.byte_count;

            // Only print high throughput flows to prevent console flooding
            if stats.packet_count > 100 {
                println!(
                    "[{:?}] {}:{} -> {}:{} | Packets: {}, Bytes: {}",
                    key.protocol,
                    key.src_ip,
                    key.src_port,
                    key.dst_ip,
                    key.dst_port,
                    stats.packet_count,
                    stats.byte_count
                );
            }
        }

        let throughput_mbps = (total_bytes * 8) as f64 / 5_000_000.0;
        println!("-------------------------------------------");
        println!(
            "Total Monitored Traffic: {:.2} Mbps | Packets/sec: {}",
            throughput_mbps,
            total_packets / 5
        );
        println!("===========================================\n");
    }
}
