use crossbeam_channel::{bounded, Receiver, Sender};
use etherparse::SlicedPacket;
use fxhash::FxHashMap;
use pcap::{Capture, Device};
use std::hash::{Hash, Hasher};
use std::net::IpAddr;
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::Arc;
use std::thread;
use std::time::{Duration, Instant};

// 5-Tuple representation of a network flow
#[derive(Hash, PartialEq, Eq, Debug, Clone, Copy)]
struct FlowKey {
    src_ip: IpAddr,
    dst_ip: IpAddr,
    src_port: u16,
    dst_port: u16,
    protocol: u8,
}

// Flow statistics
#[derive(Debug, Clone)]
struct FlowStats {
    packet_count: u64,
    byte_count: u64,
    first_seen: Instant,
    last_seen: Instant,
}

// Message format passed from the capturing thread to worker threads
struct PacketMetrics {
    flow_key: FlowKey,
    len: u32,
}

#[derive(Parser, Debug)]
#[command(author, version, about = "High-performance Gigabit Flow Analyzer")]
struct Args {
    #[arg(short, long, default_value = "eth0")]
    interface: String,

    #[arg(short, long, default_value_t = 4)]
    workers: usize,
}

fn main() {
    let args = Args::parse();
    let running = Arc::new(AtomicBool::new(true));
    let r = running.clone();

    // Handle Ctrl+C gracefully to print final stats
    ctrlc::set_handler(move || {
        r.store(false, Ordering::SeqCst);
    }).expect("Error setting Ctrl-C handler");

    println!("Starting analyzer on interface: {} with {} workers...", args.interface, args.workers);

    // Create bounded lock-free channels for each worker
    let mut senders = Vec::with_capacity(args.workers);
    let mut worker_handles = Vec::with_capacity(args.workers);

    for worker_id in 0..args.workers {
        // Queue size of 65,536 prevents worker starvation without exhausting RAM
        let (tx, rx): (Sender<PacketMetrics>, Receiver<PacketMetrics>) = bounded(65536);
        senders.push(tx);

        let running_t = running.clone();
        let handle = thread::spawn(move || {
            run_worker(worker_id, rx, running_t);
        });
        worker_handles.push(handle);
    }

    // Initialize Packet Capture (with optimized kernel settings)
    let device = Device::list()
        .unwrap()
        .into_iter()
        .find(|d| d.name == args.interface)
        .expect("Network interface not found");

    let mut cap = Capture::from_device(device)
        .unwrap()
        .promisc(true)
        .snaplen(96) // Capture only headers (64-96 bytes) to maximize throughput
        .buffer_size(128 * 1024 * 1024) // 128 MB ring-buffer to absorb micro-bursts
        .immediate_mode(true)
        .open()
        .unwrap();

    // Statistics tracking for the main thread
    let mut total_packets: u64 = 0;
    let mut total_bytes: u64 = 0;
    let mut last_report = Instant::now();

    println!("Capture loop active. Analyzing traffic...");

    while running.load(Ordering::Relaxed) {
        // Zero-copy read from the kernel-allocated ring buffer
        match cap.next_packet() {
            Ok(packet) => {
                total_packets += 1;
                total_bytes += packet.header.len as u64;

                // Zero-copy header parsing
                if let Some(flow_key) = parse_packet_headers(&packet.data) {
                    // Consistently hash the flow key to select the target worker thread
                    let mut hasher = fxhash::FxHasher::default();
                    flow_key.hash(&mut hasher);
                    let worker_idx = (hasher.finish() as usize) % args.workers;

                    // Send metrics to worker. Use non-blocking try_send to avoid stalling the capture thread
                    let metrics = PacketMetrics {
                        flow_key,
                        len: packet.header.len,
                    };
                    if let Err(_) = senders[worker_idx].try_send(metrics) {
                        // In production, log drops to a dedicated atomic counter
                        // Epoll/ring-buffer is full; dropping packet downstream to save CPU
                    }
                }

                // Performance Reporting every 1 second
                if last_report.elapsed() >= Duration::from_secs(1) {
                    let elapsed = last_report.elapsed().as_secs_f64();
                    let throughput_gbps = (total_bytes * 8) as f64 / elapsed / 1_000_000_000.0;
                    let pps = total_packets as f64 / elapsed;

                    println!(
                        "Capture Rate: {:.2} Mpps | Throughput: {:.2} Gbps",
                        pps / 1_000_000.0,
                        throughput_gbps
                    );

                    total_packets = 0;
                    total_bytes = 0;
                    last_report = Instant::now();
                }
            }
            Err(pcap::Error::TimeoutExpired) => continue,
            Err(e) => {
                eprintln!("PCAP Error: {:?}", e);
                break;
            }
        }
    }

    // Clean up threads
    drop(senders);
    for handle in worker_handles {
        let _ = handle.join();
    }
    println!("Analyzer stopped cleanly.");
}

// Zero-copy parsing of Ethernet, IP, and TCP/UDP headers
#[inline(always)]
fn parse_packet_headers(data: &[u8]) -> Option<FlowKey> {
    let sliced = SlicedPacket::from_ethernet(data).ok()?;

    // Extract IP layer (supports IPv4 & IPv6 natively)
    let (src_ip, dst_ip, protocol) = match sliced.ip? {
        etherparse::InternetSlice::Ipv4(ipv4, _) => {
            let header = ipv4.to_header();
            (
                IpAddr::V4(header.source.into()),
                IpAddr::V4(header.destination.into()),
                header.protocol.0,
            )
        }
        etherparse::InternetSlice::Ipv6(ipv6, _) => {
            let header = ipv6.to_header();
            (
                IpAddr::V6(header.source.into()),
                IpAddr::V6(header.destination.into()),
                header.next_header.0,
            )
        }
    };

    // Extract Transport layer
    let (src_port, dst_port) = match sliced.transport? {
        etherparse::TransportSlice::Tcp(tcp) => (tcp.source_port(), tcp.destination_port()),
        etherparse::TransportSlice::Udp(udp) => (udp.source_port(), udp.destination_port()),
        _ => return None, // Ignore ICMP/RAW protocols for flow tracking in this example
    };

    Some(FlowKey {
        src_ip,
        dst_ip,
        src_port,
        dst_port,
        protocol,
    })
}

// Worker thread: manages isolated flow states
fn run_worker(id: usize, rx: Receiver<PacketMetrics>, running: Arc<AtomicBool>) {
    // FxHashMap is up to 3x faster than standard std::collections::HashMap
    let mut flow_table: FxHashMap<FlowKey, FlowStats> = FxHashMap::default();
    let mut last_cleanup = Instant::now();

    while running.load(Ordering::Relaxed) || !rx.is_empty() {
        // Receive metric blocks with timeout to allow periodic cleanup
        if let Ok(metrics) = rx.recv_timeout(Duration::from_millis(100)) {
            let now = Instant::now();
            flow_table
                .entry(metrics.flow_key)
                .and_modify(|stats| {
                    stats.packet_count += 1;
                    stats.byte_count += metrics.len as u64;
                    stats.last_seen = now;
                })
                .or_insert(FlowStats {
                    packet_count: 1,
                    byte_count: metrics.len as u64,
                    first_seen: now,
                    last_seen: now,
                });
        }

        // Garbage collect expired flows (idle for > 30 seconds) to prevent memory leak
        if last_cleanup.elapsed() >= Duration::from_secs(10) {
            let now = Instant::now();
            let initial_len = flow_table.len();
            flow_table.retain(|_, stats| now.duration_since(stats.last_seen) < Duration::from_secs(30));

            if flow_table.len() != initial_len {
                println!(
                    "[Worker {}] Cleaned up {} idle flows. Active tracking table: {} flows.",
                    id,
                    initial_len - flow_table.len(),
                    flow_table.len()
                );
            }
            last_cleanup = Instant::now();
        }
    }
}
