use crossbeam_channel::{unbounded, Receiver, Sender};
use fxhash::FxHashMap;
use pcap::{Active, Capture, Device};
use std::net::Ipv4Addr;
use std::thread;
use std::time::{Duration, Instant};

// 1. Compact 5-Tuple representation (13 bytes total)
// Deriving Hash, Eq, and PartialEq for ultra-fast O(1) map lookups.
#[derive(Debug, Copy, Clone, PartialEq, Eq, Hash)]
struct FlowKey {
    src_ip: u32,
    dst_ip: u32,
    src_port: u16,
    dst_port: u16,
    proto: u8,
}

// Stats tracked per flow
#[derive(Debug, Clone)]
struct FlowStats {
    packet_count: u64,
    byte_count: u64,
    first_seen: Instant,
    last_seen: Instant,
}

// 2. Zero-Copy Packet Parser
// Directly reads slices from the raw network interface buffer. No allocations.
struct PacketParser;

impl PacketParser {
    #[inline(always)]
    fn parse_ipv4_5tuple(packet_data: &[u8]) -> Option<(FlowKey, usize)> {
        // Ethernet Header is 14 bytes
        if packet_data.len() < 14 { return None; }

        let eth_type = u16::from_be_bytes([packet_data[12], packet_data[13]]);
        if eth_type != 0x0800 { // Check if IPv4 (0x0800)
            return None; 
        }

        // IPv4 Header starts at byte 14
        let ipv4_start = 14;
        if packet_data.len() < ipv4_start + 20 { return None; }

        let ihl = (packet_data[ipv4_start] & 0x0F) as usize * 4; // IP Header Length
        let proto = packet_data[ipv4_start + 9];

        // Extract IPs
        let src_ip = u32::from_be_bytes([
            packet_data[ipv4_start + 12],
            packet_data[ipv4_start + 13],
            packet_data[ipv4_start + 14],
            packet_data[ipv4_start + 15],
        ]);
        let dst_ip = u32::from_be_bytes([
            packet_data[ipv4_start + 16],
            packet_data[ipv4_start + 17],
            packet_data[ipv4_start + 18],
            packet_data[ipv4_start + 19],
        ]);

        // Transport Layer Header starts at 14 + IHL
        let l4_start = ipv4_start + ihl;
        if packet_data.len() < l4_start + 4 { return None; }

        // Support TCP (6) and UDP (17)
        let (src_port, dst_port) = match proto {
            6 | 17 => {
                let src = u16::from_be_bytes([packet_data[l4_start], packet_data[l4_start + 1]]);
                let dst = u16::from_be_bytes([packet_data[l4_start + 2], packet_data[l4_start + 3]]);
                (src, dst)
            }
            _ => (0, 0), // Default ports for other protocols
        };

        let key = FlowKey {
            src_ip,
            dst_ip,
            src_port,
            dst_port,
            proto,
        };

        Some((key, packet_data.len()))
    }
}

// 3. Worker Thread logic (Shared-Nothing Architecture)
// Each worker manages its own flow table. Zero locks required on the hot path.
fn run_worker(id: usize, rx: Receiver<(FlowKey, usize)>) {
    // FxHashMap is significantly faster than standard HashMap for integer keys
    let mut flow_table: FxHashMap<FlowKey, FlowStats> = FxHashMap::default();
    let mut last_cleanup = Instant::now();
    let idle_timeout = Duration::from_secs(30);

    println!("Worker thread {} started.", id);

    while let Ok((key, packet_len)) = rx.recv() {
        let now = Instant::now();

        // Insert or update flow metrics
        flow_table
            .entry(key)
            .and_modify(|stats| {
                stats.packet_count += 1;
                stats.byte_count += packet_len as u64;
                stats.last_seen = now;
            })
            .or_insert(FlowStats {
                packet_count: 1,
                byte_count: packet_len as u64,
                first_seen: now,
                last_seen: now,
            });

        // Periodically evict inactive flows to prevent memory exhaustion
        if now.duration_since(last_cleanup) > Duration::from_secs(10) {
            let initial_size = flow_table.len();
            flow_table.retain(|_, stats| now.duration_since(stats.last_seen) < idle_timeout);
            let evicted = initial_size - flow_table.len();
            if evicted > 0 {
                println!(
                    "[Worker {}] Evicted {} expired flows. Active flows: {}",
                    id, evicted, flow_table.len()
                );
            }
            last_cleanup = now;
        }
    }
}

fn main() {
    // Select the default network interface
    let device = Device::lookup()
        .expect("Failed to lookup default device")
        .expect("No default device found");
    println!("Capturing on device: {}", device.name);

    // Tune PCAP ring buffer for gigabit scale (32MB ring buffer)
    let mut cap = Capture::from_device(device)
        .unwrap()
        .promisc(true)
        .snaplen(65535) // Capture full packet length
        .buffer_size(32 * 1024 * 1024) // 32 MB ring buffer to absorb spikes
        .immediate_mode(true)
        .open()
        .unwrap();

    // Spawn 4 worker threads
    let num_workers = 4;
    let mut senders = Vec::with_capacity(num_workers);

    for i in 0..num_workers {
        let (tx, rx) = unbounded();
        senders.push(tx);
        thread::spawn(move || run_worker(i, rx));
    }

    println!("Flow Analyzer started. Processing packets...");

    let mut packet_count: u64 = 0;
    let start_time = Instant::now();

    // Hot Loop: Capture and dispatch
    while let Ok(packet) = cap.next_packet() {
        if let Some((key, len)) = PacketParser::parse_ipv4_5tuple(packet.data) {
            // SIMD-like Hash-based dispatching (simulating RSS)
            // Use the flow key's hash to determine which thread processes the flow
            let hash = fxhash::hash64(&key);
            let worker_idx = (hash % num_workers as u64) as usize;

            // Non-blocking send to the worker
            let _ = senders[worker_idx].send((key, len));
        }

        packet_count += 1;
        if packet_count % 1_000_000 == 0 {
            let elapsed = start_time.elapsed().as_secs_f64();
            println!(
                "Processed {:.2} Million Packets (~{:.0} Packets/sec)",
                (packet_count as f64 / 1_000_000.0),
                packet_count as f64 / elapsed
            );
        }
    }
}
```

### Why this design achieves Gigabit-Scale throughput:

1. **Stack Allocation Only**: The `FlowKey` struct contains no heap-allocated data (like vectors or strings). It is a pure 13-byte contiguous stack segment.
2. **Inlined Parser**: The parser function is annotated with `#[inline(always)]`, which prompts the compiler to dump the parsing instructions directly into the packet-capturing hot loop. This avoids the CPU register-saving overhead of function calls.
3. **Lock-Free Concurrency**: Standard multi-threaded flow analyzers run into lock contention as threads struggle to update a shared `Mutex<HashMap>`. In this code, workers never share memory. Packets are partitioned by hashing the 5-tuple, meaning a specific connection is *always* routed to the same thread, allowing completely lock-free updates.
4. **Memory Leak Prevention**: The active retention block (`flow_table.retain(...)`) prevents the analyzer from crashing due to Out-Of-Memory (OOM) situations caused by long-duration runs.

