### Implementation (`src/main.rs`)

```rust
use std::net::IpAddr;
use std::collections::HashMap;
use std::sync::Arc;
use std::thread;
use std::time::{Instant, Duration};
use etherparse::{PacketHeaders, IpHeader, TransportHeader};
use pcap::{Capture, Device, Active};
use ahash::RandomState;
use crossbeam_channel::{unbounded, Sender, Receiver};
use thread_priority::*;

/// Symmetric 5-Tuple representing a bidirectional network flow.
/// We sort IPs and Ports to ensure both directions of a flow map to the same key.
#[derive(Debug, Clone, Hash, PartialEq, Eq)]
pub struct FlowKey {
    pub ip_low: IpAddr,
    pub ip_high: IpAddr,
    pub port_low: u16,
    pub port_high: u16,
    pub protocol: u8,
}

impl FlowKey {
    #[inline(always)]
    pub fn new(src_ip: IpAddr, dst_ip: IpAddr, src_port: u16, dst_port: u16, protocol: u8) -> Self {
        let (ip_low, ip_high) = if src_ip < dst_ip { (src_ip, dst_ip) } else { (dst_ip, src_ip) };
        let (port_low, port_high) = if src_port < dst_port { (src_port, dst_port) } else { (dst_port, src_port) };

        Self {
            ip_low,
            ip_high,
            port_low,
            port_high,
            protocol,
        }
    }
}

/// Statistics kept for each flow.
#[derive(Debug, Clone)]
pub struct FlowStats {
    pub first_seen: Instant,
    pub last_seen: Instant,
    pub bytes_sent_low_to_high: u64,
    pub bytes_sent_high_to_low: u64,
    pub packet_count_low_to_high: u64,
    pub packet_count_high_to_low: u64,
}

/// Raw packet structure sent from the capture thread to the worker threads.
/// Pre-allocating capacity avoids allocations on the hot path.
pub struct RawPacket {
    pub data: Vec<u8>,
    pub len: u32,
    pub timestamp: Instant,
}

fn main() {
    // 1. Find the active network interface
    let device = Device::lookup().expect("No active interface found").expect("No default device");
    println!("Capturing on interface: {}", device.name);

    // 2. Configure PCAP with high-performance parameters
    let mut cap = Capture::from_device(device)
        .unwrap()
        .promisc(true)
        .snaplen(128) // Capture only headers (128 bytes is enough for Eth+IP+TCP), saving massive memory bus bandwidth
        .buffer_size(64 * 1024 * 1024) // 64 MB kernel ring buffer to absorb spikes
        .timeout(1) // Non-blocking/low timeout
        .open()
        .unwrap();

    // Compile and apply a BPF filter to only capture IP traffic (TCP/UDP)
    cap.filter("ip or ip6", true).unwrap();

    // 3. Spawning worker thread with dedicated Flow Table
    // In a multi-gigabit setup, you would spawn one thread per CPU core (e.g., 4 to 16 threads).
    let (tx, rx): (Sender<RawPacket>, Receiver<RawPacket>) = unbounded();

    let worker_handle = thread::spawn(move || {
        // Pin worker thread to core 1 and set to high priority
        let core_id = CoreId(1);
        set_thread_priority_and_pin(core_id);

        // Use `ahash` instead of standard hashing for 3-5x faster lookups
        let mut flow_table: HashMap<FlowKey, FlowStats, RandomState> = HashMap::with_hasher(RandomState::new());
        let mut parsed_packets: u64 = 0;
        let mut last_report = Instant::now();

        println!("Worker thread started on Core 1.");

        while let Ok(packet) = rx.recv() {
            parsed_packets += 1;

            // Zero-copy parsing of the packet headers
            if let Ok(headers) = PacketHeaders::from_ethernet_slice(&packet.data[..packet.len as usize]) {
                let mut src_ip = None;
                let mut dst_ip = None;
                let mut proto = 0;

                if let Some(ip) = headers.ip {
                    match ip {
                        IpHeader::Version4(ipv4, _) => {
                            src_ip = Some(IpAddr::V4(ipv4.source.into()));
                            dst_ip = Some(IpAddr::V4(ipv4.destination.into()));
                            proto = ipv4.protocol.0;
                        }
                        IpHeader::Version6(ipv6, _) => {
                            src_ip = Some(IpAddr::V6(ipv6.source.into()));
                            dst_ip = Some(IpAddr::V6(ipv6.destination.into()));
                            proto = ipv6.next_header.0;
                        }
                    }
                }

                if let (Some(s_ip), Some(d_ip)) = (src_ip, dst_ip) {
                    let mut src_port = 0;
                    let mut dst_port = 0;

                    if let Some(transport) = headers.transport {
                        match transport {
                            TransportHeader::Tcp(tcp) => {
                                src_port = tcp.source_port;
                                dst_port = tcp.destination_port;
                            }
                            TransportHeader::Udp(udp) => {
                                src_port = udp.source_port;
                                dst_port = udp.destination_port;
                            }
                            _ => {}
                        }
                    }

                    // Create the symmetric key
                    let key = FlowKey::new(s_ip, d_ip, src_port, dst_port, proto);
                    let direction_low_to_high = s_ip < d_ip;

                    // Update flow stats inside our lock-free thread-local map
                    let entry = flow_table.entry(key).or_insert_with(|| FlowStats {
                        first_seen: packet.timestamp,
                        last_seen: packet.timestamp,
                        bytes_sent_low_to_high: 0,
                        bytes_sent_high_to_low: 0,
                        packet_count_low_to_high: 0,
                        packet_count_high_to_low: 0,
                    });

                    entry.last_seen = packet.timestamp;
                    if direction_low_to_high {
                        entry.bytes_sent_low_to_high += packet.len as u64;
                        entry.packet_count_low_to_high += 1;
                    } else {
                        entry.bytes_sent_high_to_low += packet.len as u64;
                        entry.packet_count_high_to_low += 1;
                    }
                }
            }

            // Periodically report stats (e.g., every 5 seconds)
            if last_report.elapsed() >= Duration::from_secs(5) {
                println!(
                    "[Worker] Packets processed: {}, Active Flows in Table: {}",
                    parsed_packets,
                    flow_table.len()
                );
                // In production, you would sweep and flush expired (idle) flows to a database here.
                last_report = Instant::now();
            }
        }
    });

    // 4. Capture Thread Loop (Reads from network ring-buffer)
    // Pin capture thread to Core 0
    let _ = thread::spawn(move || {
        let core_id = CoreId(0);
        set_thread_priority_and_pin(core_id);

        println!("Capture thread started on Core 0.");

        loop {
            match cap.next_packet() {
                Ok(packet) => {
                    // Send to worker via lock-free channel. 
                    // Allocating raw data onto the heap; in hyper-performance, use a pre-allocated pool of buffers.
                    let raw = RawPacket {
                        data: packet.data.to_vec(),
                        len: packet.header.caplen,
                        timestamp: Instant::now(),
                    };
                    let _ = tx.send(raw);
                }
                Err(pcap::Error::TimeoutExpired) => continue,
                Err(e) => {
                    eprintln!("Capture error: {:?}", e);
                    break;
                }
            }
        }
    });

    worker_handle.join().unwrap();
}

struct CoreId(usize);

fn set_thread_priority_and_pin(core: CoreId) {
    // Pin execution to a specific hardware CPU core to maximize CPU cache locality (L1/L2 Cache)
    #[cfg(target_os = "linux")]
    unsafe {
        let mut set: libc::cpu_set_t = std::mem::zeroed();
        libc::CPU_SET(core.0, &mut set);
        libc::pthread_setaffinity_np(libc::pthread_self(), std::mem::size_of::<libc::cpu_set_t>(), &set);
    }

    // Elevate thread priority to Realtime/Extremely High
    let _ = set_sub_thread_priority(ThreadPriority::Max);
}
