### The Implementation (`src/main.rs`)

```rust
use std::net::Ipv4Addr;
use std::hash::{Hash, Hasher};
use std::time::{Instant, Duration};
use std::thread;
use rustc-hash::FxHashMap;
use crossbeam_channel::{unbounded, Sender, Receiver};

// --- CONSTANTS ---
const ETHER_TYPE_IPV4: u16 = 0x0800;
const PROTO_TCP: u8 = 6;
const PROTO_UDP: u8 = 17;

// --- DATA STRUCTURES ---

// 5-Tuple Key representing a unique network flow
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub struct FlowKey {
    pub src_ip: u32,
    pub dst_ip: u32,
    pub src_port: u16,
    pub dst_port: u16,
    pub proto: u8,
}

// Metrics tracked per network flow
#[derive(Debug, Clone, Copy)]
pub struct FlowMetrics {
    pub packet_count: u64,
    pub byte_count: u64,
    pub start_time: Instant,
    pub last_seen: Instant,
}

// Flow record exported from workers to the aggregation thread
pub struct FlowRecord {
    pub key: FlowKey,
    pub metrics: FlowMetrics,
}

// --- ZERO-COPY PACKET PARSING ---

#[inline(always)]
fn parse_flow_key(packet: &[u8]) -> Option<(FlowKey, usize)> {
    // 1. Ethernet Header (14 bytes)
    if packet.len() < 14 { return None; }
    let ether_type = u16::from_be_bytes([packet[12], packet[13]]);
    if ether_type != ETHER_TYPE_IPV4 {
        return None; // Skip non-IPv4 for this performance example
    }

    // 2. IP Header (Starts at offset 14, min 20 bytes)
    let ip_start = 14;
    if packet.len() < ip_start + 20 { return None; }

    let ihl = packet[ip_start] & 0x0F;
    let ip_len = (ihl as usize) * 4;
    let total_len = u16::from_be_bytes([packet[ip_start + 2], packet[ip_start + 3]]) as usize;
    let proto = packet[ip_start + 9];

    let src_ip = u32::from_be_bytes([
        packet[ip_start + 12], packet[ip_start + 13], 
        packet[ip_start + 14], packet[ip_start + 15]
    ]);
    let dst_ip = u32::from_be_bytes([
        packet[ip_start + 16], packet[ip_start + 17], 
        packet[ip_start + 18], packet[ip_start + 19]
    ]);

    // 3. Layer 4 Header (TCP or UDP)
    let l4_start = ip_start + ip_len;
    if packet.len() < l4_start + 4 { return None; }

    let src_port = u16::from_be_bytes([packet[l4_start], packet[l4_start + 1]]);
    let dst_port = u16::from_be_bytes([packet[l4_start + 2], packet[l4_start + 3]]);

    if proto == PROTO_TCP || proto == PROTO_UDP {
        Some((
            FlowKey { src_ip, dst_ip, src_port, dst_port, proto },
            total_len + 14 // total L2 frame size
        ))
    } else {
        None
    }
}

// --- WORKER THREAD ---

fn run_worker(
    device_name: String, 
    tx: Sender<FlowRecord>
) {
    // Configure pcap handle for high throughput
    let mut cap = pcap::Capture::from_device(device_name.as_str())
        .unwrap()
        .promisc(true)
        .snaplen(65535)
        .buffer_size(32 * 1024 * 1024) // 32MB buffer to prevent kernel packet drops
        .timeout(1)
        .open()
        .unwrap();

    // High performance configurations: nonblock and raw FD optimizations
    cap.set_nonblock().unwrap();

    // Thread-local hash map - avoids lock contention completely!
    let mut local_flow_table: FxHashMap<FlowKey, FlowMetrics> = FxHashMap::default();
    let mut last_flush = Instant::now();
    const FLUSH_INTERVAL: Duration = Duration::from_secs(1);

    println!("[Worker] Started capture on interface: {}", device_name);

    loop {
        match cap.next_packet() {
            Ok(packet) => {
                let now = Instant::now();
                if let Some((key, wire_len)) = parse_flow_key(packet.data) {
                    // Fast insert/update in thread-local storage
                    let metrics = local_flow_table.entry(key).or_insert_with(|| FlowMetrics {
                        packet_count: 0,
                        byte_count: 0,
                        start_time: now,
                        last_seen: now,
                    });

                    metrics.packet_count += 1;
                    metrics.byte_count += wire_len as u64;
                    metrics.last_seen = now;
                }
            }
            Err(pcap::Error::TimeoutExpired) => {}
            Err(e) => {
                eprintln!("[Worker] Capture error: {:?}", e);
                break;
            }
        }

        // Periodically flush local flows to the aggregator to free memory
        // and report state changes
        if last_flush.elapsed() >= FLUSH_INTERVAL {
            let now = Instant::now();
            // Retain active flows locally but send snapshot, or evict idle flows
            local_flow_table.retain(|&key, &mut metrics| {
                let is_idle = now.duration_since(metrics.last_seen) > Duration::from_secs(15);

                // Export flow to aggregator
                let _ = tx.send(FlowRecord { key, metrics });

                // Keep active flows in local cache to maintain delta counters,
                // evict idle ones to prevent memory exhaustion
                !is_idle
            });
            last_flush = now;
        }
    }
}

// --- AGGREGATOR THREAD ---

fn run_aggregator(rx: Receiver<FlowRecord>) {
    let mut global_flow_table: FxHashMap<FlowKey, FlowMetrics> = FxHashMap::default();
    let mut last_report = Instant::now();

    println!("[Aggregator] Started.");

    for record in rx {
        // Merge updates from various worker threads
        let entry = global_flow_table.entry(record.key).or_insert_with(|| record.metrics);
        if record.metrics.start_time < entry.start_time {
            entry.start_time = record.metrics.start_time;
        }
        if record.metrics.last_seen > entry.last_seen {
            entry.last_seen = record.metrics.last_seen;
            // Aggregate metrics
            entry.packet_count += record.metrics.packet_count;
            entry.byte_count += record.metrics.byte_count;
        }

        // Print statistics every 5 seconds
        if last_report.elapsed() >= Duration::from_secs(5) {
            println!("\n=== ACTIVE FLOW REPORT (Total Flows: {}) ===", global_flow_table.len());

            // Show top 5 flows by bytes
            let mut flows: Vec<(&FlowKey, &FlowMetrics)> = global_flow_table.iter().collect();
            flows.sort_unaligned_by(|a, b| b.1.byte_count.cmp(&a.1.byte_count));

            for (key, metrics) in flows.iter().take(5) {
                let src_ip = Ipv4Addr::from(key.src_ip);
                let dst_ip = Ipv4Addr::from(key.dst_ip);
                let duration = metrics.last_seen.duration_since(metrics.start_time).as_secs_f64();
                let bps = if duration > 0.0 { (metrics.byte_count * 8) as f64 / duration } else { 0.0 };

                println!(
                    "[{:?}] {}:{} -> {}:{} | Pkts: {} | Bytes: {} | Speed: {:.2} Mbps",
                    key.proto,
                    src_ip, key.src_port,
                    dst_ip, key.dst_port,
                    metrics.packet_count,
                    metrics.byte_count,
                    bps / 1_000_000.0
                );
            }
            println!("============================================");

            // Clean up stale flows in global aggregator
            let now = Instant::now();
            global_flow_table.retain(|_, metrics| {
                now.duration_since(metrics.last_seen) < Duration::from_secs(30)
            });

            last_report = now;
        }
    }
}

// --- ENTRYPOINT ---

fn main() {
    // Use an interface from your local machine (e.g., "eth0", "enp3s0", "any")
    let target_interface = std::env::args()
        .nth(1)
        .unwrap_or_else(|| "eth0".to_string());

    let (tx, rx) = unbounded();

    // Set real-time scheduler for the main threads to prevent OS scheduling jitter
    set_thread_priority();

    // Spawn Aggregator Thread
    let agg_thread = thread::spawn(move || {
        run_aggregator(rx);
    });

    // Spawn Worker Thread (For true multi-gigabit, scale by spawning multiple workers,
    // each bound to a specific NIC ring-buffer queue)
    let worker_thread = thread::spawn(move || {
        run_worker(target_interface, tx);
    });

    worker_thread.join().unwrap();
    agg_thread.join().unwrap();
}

// Set real-time thread priority (on Linux)
fn set_thread_priority() {
    #[cfg(target_os = "linux")]
    unsafe {
        let thread_id = libc::pthread_self();
        let mut param: libc::sched_param = std::mem::zeroed();
        param.sched_priority = 80; // High priority RT scheduling
        let result = libc::pthread_setschedparam(thread_id, libc::SCHED_FIFO, &param);
        if result == 0 {
            println!("[System] Thread scheduled with Real-Time FIFO priority.");
        } else {
            println!("[System] Warning: Could not set RT scheduling. Run with sudo/CAP_SYS_NICE.");
        }
    }
}
