```rust
use std::net::{IpAddr, Ipv4Addr};
use std::thread;
use std::time::{Duration, Instant};
use crossbeam_channel::{bounded, Receiver, Sender};
use fxhash::FxHashMap;
use pcap::{Capture, Device};

// --- 1. DATA STRUCTURES ---

/// Represents a unique 5-tuple network flow.
/// We implement custom sorting to ensure symmetric hashing (bidirectional traffic maps to the same key).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
struct FlowKey {
    src_ip: IpAddr,
    dst_ip: IpAddr,
    src_port: u16,
    dst_port: u16,
    protocol: u8,
}

impl FlowKey {
    /// Generates a symmetric FlowKey where the direction of the flow does not change the key.
    #[inline(always)]
    fn new_symmetric(src_ip: IpAddr, dst_ip: IpAddr, src_port: u16, dst_port: u16, protocol: u8) -> Self {
        if src_ip < dst_ip || (src_ip == dst_ip && src_port < dst_port) {
            FlowKey { src_ip, dst_ip, src_port, dst_port, protocol }
        } else {
            FlowKey {
                src_ip: dst_ip,
                dst_ip: src_ip,
                src_port: dst_port,
                dst_port: src_port,
                protocol,
            }
        }
    }
}

/// Statistics collected per network flow.
struct FlowStats {
    packet_count: u64,
    byte_count: u64,
    first_seen: Instant,
    last_seen: Instant,
}

/// Lightweight message sent from the receiver thread to worker threads.
/// Keeping this struct small (24 bytes) avoids memory copy overhead.
struct ParsedPacket {
    flow_key: FlowKey,
    payload_len: u32,
}

// --- 2. ZERO-COPY PROTOCOL PARSER ---

/// High-performance, zero-copy packet parser.
/// Parses Ethernet, IPv4, and TCP/UDP headers using fast bit shifts.
#[inline(always)]
fn parse_packet(packet_data: &[u8]) -> Option<ParsedPacket> {
    // 1. Parse Ethernet Header (14 bytes)
    if packet_data.len() < 14 { return None; }
    let ether_type = u16::from_be_bytes([packet_data[12], packet_data[13]]);

    // Check for IPv4 (0x0800)
    if ether_type != 0x0800 {
        return None; // Skip IPv6/ARP for brevity in this implementation
    }

    // 2. Parse IPv4 Header (Minimum 20 bytes)
    let ip_start = 14;
    if packet_data.len() < ip_start + 20 { return None; }

    let ihl = (packet_data[ip_start] & 0x0F) as usize * 4;
    let protocol = packet_data[ip_start + 9];
    let total_len = u16::from_be_bytes([packet_data[ip_start + 2], packet_data[ip_start + 3]]) as u32;

    let src_ip = IpAddr::V4(Ipv4Addr::new(
        packet_data[ip_start + 12], packet_data[ip_start + 13],
        packet_data[ip_start + 14], packet_data[ip_start + 15]
    ));
    let dst_ip = IpAddr::V4(Ipv4Addr::new(
        packet_data[ip_start + 16], packet_data[ip_start + 17],
        packet_data[ip_start + 18], packet_data[ip_start + 19]
    ));

    // 3. Parse L4 Header (TCP = 6, UDP = 17)
    let l4_start = ip_start + ihl;
    if packet_data.len() < l4_start + 4 { return None; }

    let src_port = u16::from_be_bytes([packet_data[l4_start], packet_data[l4_start + 1]]);
    let dst_port = u16::from_be_bytes([packet_data[l4_start + 2], packet_data[l4_start + 3]]);

    if protocol == 6 || protocol == 17 {
        Some(ParsedPacket {
            flow_key: FlowKey::new_symmetric(src_ip, dst_ip, src_port, dst_port, protocol),
            payload_len: total_len,
        })
    } else {
        None
    }
}

// --- 3. WORKER THREAD (FLOW AGGREGATOR) ---

/// Each worker maintains its own isolated Flow Table. No locks are required during the hot path.
fn start_worker_thread(id: usize, rx: Receiver<ParsedPacket>) {
    thread::spawn(move || {
        // FxHashMap is vastly faster than standard std::collections::HashMap for integer/tuple keys
        let mut flow_table: FxHashMap<FlowKey, FlowStats> = FxHashMap::with_capacity_and_hasher(
            50_000, 
            fxhash::FxBuildHasher::default()
        );
        let mut last_cleanup = Instant::now();
        let cleanup_interval = Duration::from_secs(10);

        println!("[Worker {}] Started.", id);

        while let Ok(packet) = rx.recv() {
            let now = Instant::now();

            // Insert or update the flow entry
            flow_table.entry(packet.flow_key)
                .and_modify(|stats| {
                    stats.packet_count += 1;
                    stats.byte_count += packet.payload_len as u64;
                    stats.last_seen = now;
                })
                .or_insert(FlowStats {
                    packet_count: 1,
                    byte_count: packet.payload_len as u64,
                    first_seen: now,
                    last_seen: now,
                });

            // Periodically clean up expired inactive flows to prevent memory exhaustion
            if last_cleanup.elapsed() >= cleanup_interval {
                let active_before = flow_table.len();
                flow_table.retain(|_, stats| now.duration_since(stats.last_seen) < Duration::from_secs(30));
                let active_after = flow_table.len();
                if active_before != active_after {
                    println!(
                        "[Worker {}] Swept inactive flows. Active: {} (Pruned {})", 
                        id, active_after, active_before - active_after
                    );
                }
                last_cleanup = Instant::now();
            }
        }
    });
}

// --- 4. MAIN CAPTURE & DISPATCH LOOP ---

fn main() {
    // Determine the number of worker cores to spawn (reserve 1 core for parsing/dispatching)
    let num_workers = num_cpus::get().saturating_sub(1).max(1);
    println!("Initializing flow analyzer with {} worker threads...", num_workers);

    // Create high-capacity lock-free channels to buffer bursts without blocking the receiver
    let mut senders = Vec::with_capacity(num_workers);
    for idx in 0..num_workers {
        let (tx, rx) = bounded::<ParsedPacket>(100_000);
        senders.push(tx);
        start_worker_thread(idx, rx);
    }

    // Set up standard network interface packet capture.
    // NOTE: For true production 10Gbps+ environments, swap this step out with AF_XDP or DPDK.
    let device = Device::lookup().expect("Failed to find default network device").expect("No device found");
    println!("Listening on device: {}", device.name);

    let mut cap = Capture::from_device(device)
        .unwrap()
        .promisc(true)
        .snaplen(65535)
        .timeout(1) // Low timeout for high-throughput polling
        .buffer_size(64 * 1024 * 1024) // 64MB kernel ring buffer to prevent packet drops
        .open()
        .expect("Failed to open capture handle");

    let mut total_packets = 0u64;
    let start_time = Instant::now();

    println!("Flow analyzer running. Press Ctrl+C to terminate...");

    // Hot Loop
    loop {
        match cap.next_packet() {
            Ok(packet) => {
                total_packets += 1;

                // Fast parse (Zero-copy)
                if let Some(parsed) = parse_packet(packet.data) {
                    // Compute a fast symmetric hash to distribute flows to workers
                    let hash = fxhash::hash64(&parsed.flow_key);
                    let worker_idx = (hash as usize) % num_workers;

                    // Dispatch to worker thread (Non-blocking send)
                    if let Err(_) = senders[worker_idx].try_send(parsed) {
                        // Channel full - shows up if a worker falls behind
                        eprintln!("[Warning] Worker {} input queue is full! Packet dropped.", worker_idx);
                    }
                }
            }
            Err(pcap::Error::TimeoutExpired) => continue,
            Err(e) => {
                eprintln!("Capture Error: {:?}", e);
                break;
            }
        }

        // Print basic throughput metrics every 5 million packets
        if total_packets % 5_000_000 == 0 {
            let elapsed = start_time.elapsed().as_secs_f64();
            println!("Processed {} packets. Average Rate: {:.2} Mpps", 
                     total_packets, (total_packets as f64 / elapsed) / 1_000_000.0);
        }
    }
}
```

