use fxhash::FxHashMap;
use pcap::{Capture, Device};
use std::convert::TryInto;
use std::net::Ipv4Addr;
use std::time::{Duration, Instant};

// 5-Tuple Key representing a unique network flow
#[derive(Hash, PartialEq, Eq, Debug, Clone, Copy)]
pub struct FlowKey {
    pub src_ip: Ipv4Addr,
    pub dst_ip: Ipv4Addr,
    pub src_port: u16,
    pub dst_port: u16,
    pub proto: u8,
}

// Stats tracked per flow
#[derive(Debug)]
pub struct FlowStats {
    pub packet_count: u64,
    pub byte_count: u64,
    pub first_seen: Instant,
    pub last_seen: Instant,
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    // 1. Select the default network interface
    let device = Device::lookup()?
        .ok_or("No default network interface found")?;
    println!("Monitoring interface: {}", device.name);

    // 2. Configure high-performance packet capture
    let mut cap = Capture::from_device(device)?
        .promisc(true)                  // Promiscuous mode
        .snaplen(64)                    // Capture only headers (64 bytes) to save PCIe bandwidth
        .buffer_size(128 * 1024 * 1024) // 128 MB ring buffer to prevent packet drops
        .timeout(1)                     // 1ms timeout for responsive batching
        .immediate_mode(true)           // Deliver packets immediately
        .open()?;

    // Map to store aggregated flow statistics
    let mut flow_table: FxHashMap<FlowKey, FlowStats> = FxHashMap::default();
    let mut last_report = Instant::now();
    let mut total_packets: u64 = 0;

    println!("Starting packet capture... Press Ctrl+C to stop.");

    // 3. High-Performance Packet Processing Loop
    loop {
        // Fetch the next raw packet from the ring buffer
        if let Ok(packet) = cap.next_packet() {
            total_packets += 1;
            let data = packet.data;
            let len = packet.header.len as u64;

            // Parse packet (Zero-copy)
            if let Some(key) = parse_5tuple(data) {
                // Update or insert flow stats in O(1) time
                let now = Instant::now();
                flow_table.entry(key)
                    .and_modify(|stats| {
                        stats.packet_count += 1;
                        stats.byte_count += len;
                        stats.last_seen = now;
                    })
                    .or_insert(FlowStats {
                        packet_count: 1,
                        byte_count: len,
                        first_seen: now,
                        last_seen: now,
                    });
            }
        }

        // Periodic report (every 5 seconds) without blocking the hot path
        if last_report.elapsed() >= Duration::from_secs(5) {
            println!("\n--- [FLOW REPORT] ---");
            println!("Total Packets Processed: {}", total_packets);
            println!("Active Flows in Table: {}", flow_table.len());

            // Print top 5 active flows sorted by volume
            let mut flows: Vec<(&FlowKey, &FlowStats)> = flow_table.iter().collect();
            flows.sort_unstable_by(|a, b| b.1.byte_count.cmp(&a.1.byte_count));

            for (key, stats) in flows.iter().take(5) {
                println!(
                    "{:15}:{:5} -> {:15}:{:5} | Proto: {:3} | Packets: {:8} | Bytes: {:10}",
                    key.src_ip, key.src_port, key.dst_ip, key.dst_port, key.proto, stats.packet_count, stats.byte_count
                );
            }

            // Prune old flows to prevent memory leaks (simple aging)
            let now = Instant::now();
            flow_table.retain(|_, stats| now.duration_since(stats.last_seen) < Duration::from_secs(30));

            last_report = Instant::now();
        }
    }
}

/// Zero-copy, high-speed protocol parser
/// Highly optimized to avoid bounds check overheads where possible
#[inline(always)]
fn parse_5tuple(packet: &[u8]) -> Option<FlowKey> {
    // 1. Parse Ethernet Header (Must be at least 14 bytes)
    if packet.len() < 14 { return None; }
    let ether_type = u16::from_be_bytes([packet[12], packet[13]]);

    // Check if IPv4 (0x0800)
    if ether_type != 0x0800 { return None; }

    // 2. Parse IPv4 Header
    let ip_start = 14;
    if packet.len() < ip_start + 20 { return None; }

    let version_ihl = packet[ip_start];
    let ihl = (version_ihl & 0x0F) as usize * 4; // IP Header Length
    let proto = packet[ip_start + 9];

    // Read Source and Destination IPs
    let src_ip_bytes: [u8; 4] = packet[ip_start + 12..ip_start + 16].try_into().ok()?;
    let dst_ip_bytes: [u8; 4] = packet[ip_start + 16..ip_start + 20].try_into().ok()?;

    let src_ip = Ipv4Addr::from(src_ip_bytes);
    let dst_ip = Ipv4Addr::from(dst_ip_bytes);

    // 3. Parse L4 Header (TCP = 6, UDP = 17)
    let l4_start = ip_start + ihl;
    if packet.len() < l4_start + 4 { return None; } // Need at least 4 bytes for ports

    let src_port = u16::from_be_bytes([packet[l4_start], packet[l4_start + 1]]);
    let dst_port = u16::from_be_bytes([packet[l4_start + 2], packet[l4_start + 3]]);

    if proto == 6 || proto == 17 {
        Some(FlowKey {
            src_ip,
            dst_ip,
            src_port,
            dst_port,
            proto,
        })
    } else {
        None
    }
}
```

### Why this code is optimized for Gigabit-scale:

1. **Snaplen Configuration (`snaplen(64)`)**: We configure the driver to only copy the first 64 bytes of each packet. This prevents copying payloads (like video/file transfer data) over the PCIe bus to RAM, freeing up massive amounts of memory bandwidth.
2. **Zero-Copy Slicing**: The `parse_5tuple` function borrows references (`&[u8]`) directly from the OS ring buffer instead of copying data to a struct.
3. **`#[inline(always)]`**: Inlining hints tell the LLVM compiler to embed the parsing steps directly inside the main loop, eliminating the call-stack overhead for every packet.
4. **`FxHashMap`**: Rust's standard hash map uses SIPHash 1-3 to prevent DoS attacks. However, SIPHash is too slow for 10Gbps+ links. We use `FxHash` (Firefox's non-cryptographic hash), which performs highly optimized multiplications to hash 5-tuples in single-digit nanoseconds.
5. **Flow Aging**: A built-in pruning mechanism runs periodically to remove stale flows, keeping memory allocation static and predictable.

