use fxhash::FxHashMap;
use pcap::{Active, Capture, Device};
use std::convert::TryInto;
use std::net::Ipv4Addr;
use std::time::{Instant, Duration};

// 5-Tuple representation of a Network Flow
#[derive(Hash, PartialEq, Eq, Clone, Copy, Debug)]
struct FlowKey {
    src_ip: [u8; 4],
    dst_ip: [u8; 4],
    src_port: u16,
    dst_port: u16,
    proto: u8,
}

// Flow metrics we want to track
struct FlowStats {
    packet_count: u64,
    byte_count: u64,
    first_seen: Instant,
    last_seen: Instant,
}

fn main() {
    // 1. Select the network interface (e.g., the first active interface)
    let device = Device::lookup()
        .expect("Failed to find default device")
        .expect("No default device found");

    println!("Monitoring traffic on interface: {}", device.name);

    // 2. High-performance handle configuration
    let mut cap = Capture::from_device(device)
        .unwrap()
        .promisc(true)                    // Capture all traffic on wire
        .snaplen(64)                      // Only capture headers (massive speedup)
        .buffer_size(16 * 1024 * 1024)    // 16MB ring buffer to absorb kernel spikes
        .immediate_mode(false)            // Let driver batch packets
        .open()
        .unwrap();

    // Only capture IPv4 TCP and UDP traffic to minimize processing
    cap.filter("ip proto \\tcp or ip proto \\udp", true)
        .expect("Failed to apply BPF filter");

    // 3. Thread-local flow state (No locks, highly cache-friendly)
    // FxHashMap is dramatically faster than the standard HashMap for numeric keys
    let mut flow_table: FxHashMap<FlowKey, FlowStats> = FxHashMap::default();

    let mut total_packets: u64 = 0;
    let mut last_report = Instant::now();

    println!("Analyzer started. Processing packets...");

    // 4. Infinite packet capture loop (The Hot Path)
    loop {
        match cap.next_packet() {
            Ok(packet) => {
                total_packets += 1;
                let raw_data = packet.data;
                let cap_len = packet.header.caplen as u64;

                // Zero-copy parsing
                if let Some(key) = parse_packet(raw_data) {
                    let now = Instant::now();

                    // Upsert flow table in O(1) time
                    flow_table.entry(key)
                        .and_modify(|stats| {
                            stats.packet_count += 1;
                            stats.byte_count += cap_len;
                            stats.last_seen = now;
                        })
                        .or_insert(FlowStats {
                            packet_count: 1,
                            byte_count: cap_len,
                            first_seen: now,
                            last_seen: now,
                        });
                }

                // Periodically dump metrics without impacting the hot path
                if total_packets % 1_000_000 == 0 {
                    let elapsed = last_report.elapsed();
                    if elapsed >= Duration::from_secs(1) {
                        print_stats(&flow_table, total_packets, elapsed);
                        last_report = Instant::now();
                    }
                }
            }
            Err(pcap::Error::TimeoutExpired) => continue,
            Err(e) => {
                eprintln!("Error reading packet: {:?}", e);
                break;
            }
        }
    }
}

/// Zero-copy network parser.
/// Takes a raw byte slice directly from the NIC ring buffer and extracts 
/// the 5-tuple key without any heap allocation.
#[inline(always)]
fn parse_packet(packet: &[u8]) -> Option<FlowKey> {
    // Ethernet header is always 14 bytes
    if packet.len() < 14 { return None; }

    // Verify EtherType is IPv4 (0x0800)
    let ether_type = u16::from_be_bytes([packet[12], packet[13]]);
    if ether_type != 0x0800 { return None; }

    // Start parsing IPv4 (starts at byte 14)
    let ip_start = 14;
    if packet.len() < ip_start + 20 { return None; }

    // Extract IP Header Length (IHL) from lower 4 bits of the first byte
    let ip_header_len = ((packet[ip_start] & 0x0F) * 4) as usize;
    if packet.len() < ip_start + ip_header_len { return None; }

    let proto = packet[ip_start + 9];

    // Extract IPs securely via slice-to-array casting (zero copy)
    let src_ip: [u8; 4] = packet[ip_start + 12..ip_start + 16].try_into().ok()?;
    let dst_ip: [u8; 4] = packet[ip_start + 16..ip_start + 20].try_into().ok()?;

    // Determine Transport Layer offsets
    let l4_start = ip_start + ip_header_len;
    if packet.len() < l4_start + 4 { return None; }

    let (src_port, dst_port) = match proto {
        6 | 17 => { // TCP (6) or UDP (17)
            let src = u16::from_be_bytes([packet[l4_start], packet[l4_start + 1]]);
            let dst = u16::from_be_bytes([packet[l4_start + 2], packet[l4_start + 3]]);
            (src, dst)
        }
        _ => return None, // Ignore other protocols (ICMP, etc.)
    };

    Some(FlowKey {
        src_ip,
        dst_ip,
        src_port,
        dst_port,
        proto,
    })
}

/// Prints high-level flow table statistics to the console.
fn print_stats(flow_table: &FxHashMap<FlowKey, FlowStats>, total: u64, elapsed: Duration) {
    let pps = total as f64 / elapsed.as_secs_f64();
    println!("\n--- [System Metrics] ---");
    println!("Throughput: {:.2} Packets/Sec", pps);
    println!("Total Active Flows tracked: {}", flow_table.len());

    // Show top 3 heaviest active flows
    let mut flows: Vec<(&FlowKey, &FlowStats)> = flow_table.iter().collect();
    flows.sort_unstable_by_key(|f| std::cmp::Reverse(f.1.byte_count));

    println!("Top Active Flows:");
    for (k, v) in flows.iter().take(3) {
        let src_ip = Ipv4Addr::from(k.src_ip);
        let dst_ip = Ipv4Addr::from(k.dst_ip);
        let proto_str = if k.proto == 6 { "TCP" } else { "UDP" };
        println!(
            "  [{}] {}:{} -> {}:{} | Packets: {} | Bytes: {}",
            proto_str, src_ip, k.src_port, dst_ip, k.dst_port, v.packet_count, v.byte_count
        );
    }
}
