```rust
use dashmap::DashMap;
use fxhash::FxBuildHasher;
use pcap::{Capture, Device};
use std::hash::BuildHasherDefault;
use std::net::Ipv4Addr;
use std::sync::Arc;
use std::time::{Instant, Duration};
use std::thread;

// 1. Thread-safe, stack-allocated Flow Key (No Heap Allocation)
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
struct FlowKey {
    src_ip: [u8; 4],
    dst_ip: [u8; 4],
    src_port: u16,
    dst_port: u16,
    proto: u8,
}

// 2. Metrics tracked per flow
#[derive(Debug, Clone, Copy)]
struct FlowMetrics {
    packet_count: u64,
    byte_count: u64,
    first_seen: Instant,
    last_seen: Instant,
}

// Type alias for our high-speed concurrent flow table
type FastHasher = BuildHasherDefault<fxhash::FxHasher>;
type FlowTable = Arc<DashMap<FlowKey, FlowMetrics, FastHasher>>;

fn main() {
    // Find the default active network interface
    let device = Device::lookup().expect("No active network interface found").unwrap();
    println!("Monitoring traffic on interface: {}", device.name);

    // Configure high-performance packet capture settings
    let mut cap = Capture::from_device(device)
        .unwrap()
        .promisc(true)                  // Promiscuous mode
        .snaplen(64)                    // Only capture headers (64 bytes) to save PCIe bandwidth
        .timeout(1)                     // Low timeout (1ms) for fast batch processing
        .buffer_size(16 * 1024 * 1024)  // 16MB ring buffer to prevent drops under spikes
        .open()
        .unwrap();

    // Set filter to process only IPv4 TCP/UDP traffic
    cap.filter("ip and (tcp or udp)", true).unwrap();

    // Use FxHasher (3x faster than default SipHash) and sharded DashMap
    let flow_table: FlowTable = Arc::new(DashMap::with_hasher(FastHasher::default()));

    // Spawn a background thread to periodically report performance statistics
    let stats_table = Arc::clone(&flow_table);
    thread::spawn(move || {
        let mut last_report = Instant::now();
        loop {
            thread::sleep(Duration::from_secs(5));
            let duration = last_report.elapsed().as_secs_f64();
            last_report = Instant::now();

            let total_flows = stats_table.len();
            let total_packets: u64 = stats_table.iter().map(|r| r.value().packet_count).sum();

            println!(
                "[STATS] Active Flows: {} | Avg Packets/Sec: {:.2}",
                total_flows,
                (total_packets as f64) / duration
            );
        }
    });

    println!("Flow analyzer running. Press Ctrl+C to stop...");

    // Packet Processing Loop (The Hot Path)
    loop {
        match cap.next_packet() {
            Ok(packet) => {
                let data = packet.data;
                let len = packet.header.len as u64;

                // 3. ZERO-COPY MANUAL PARSING (Strictly slice manipulation, 0 allocations)
                if data.len() < 34 { continue; } // Drop malformed packets (Ethernet 14 + Min IP 20)

                // Verify Ethernet payload is IPv4 (0x0800 at offset 12)
                let eth_proto = u16::from_be_bytes([data[12], data[13]]);
                if eth_proto != 0x0800 { continue; }

                // Parse IPv4 Header
                let ip_proto = data[23];
                let src_ip: [u8; 4] = [data[26], data[27], data[28], data[29]];
                let dst_ip: [u8; 4] = [data[30], data[31], data[32], data[33]];

                let ip_header_len = ((data[14] & 0x0F) * 4) as usize;
                let l4_offset = 14 + ip_header_len;

                if data.len() < l4_offset + 4 { continue; } // Check for L4 header existence

                // Parse TCP/UDP Ports
                let src_port = u16::from_be_bytes([data[l4_offset], data[l4_offset + 1]]);
                let dst_port = u16::from_be_bytes([data[l4_offset + 2], data[l4_offset + 3]]);

                // Construct stack-allocated key
                let key = FlowKey {
                    src_ip,
                    dst_ip,
                    src_port,
                    dst_port,
                    proto: ip_proto,
                };

                // 4. Thread-safe lock-striped table update
                let now = Instant::now();
                flow_table.entry(key)
                    .and_modify(|metrics| {
                        metrics.packet_count += 1;
                        metrics.byte_count += len;
                        metrics.last_seen = now;
                    })
                    .or_insert(FlowMetrics {
                        packet_count: 1,
                        byte_count: len,
                        first_seen: now,
                        last_seen: now,
                    });
            }
            Err(pcap::Error::TimeoutExpired) => continue,
            Err(e) => {
                eprintln!("Error reading packet: {:?}", e);
                break;
            }
        }
    }
}
