```rust
use crossbeam_channel::{bounded, Receiver, Sender};
use dashmap::DashMap;
use pcap::{Active, Capture, Device};
use std::net::Ipv4Addr;
use std::sync::Arc;
use std::thread;
use std::time::{Duration, Instant};

// 1. Lightweight, stack-allocated key to uniquely identify a network flow (5-tuple)
#[derive(Hash, PartialEq, Eq, Clone, Debug)]
struct FlowKey {
    src_ip: Ipv4Addr,
    dst_ip: Ipv4Addr,
    src_port: u16,
    dst_port: u16,
    proto: u8, // 6 for TCP, 17 for UDP
}

// Stats collected per flow
struct FlowStats {
    packet_count: u64,
    byte_count: u64,
    first_seen: Instant,
    last_seen: Instant,
}

// Lightweight message sent across threads (Zero Heap Allocation)
struct PacketEvent {
    key: FlowKey,
    len: usize,
}

fn main() {
    // Select the default network interface
    let device = Device::lookup()
        .expect("No default device found")
        .expect("Device lookup failed");

    println!("Capturing on interface: {}", device.name);

    // 2. High-performance PCAP Configuration
    let mut cap = Capture::from_device(device)
        .unwrap()
        .promisc(true)
        .snaplen(64) // Capture only headers (64 bytes is enough for Eth + IP + TCP/UDP)
        .buffer_size(16 * 1024 * 1024) // 16MB kernel ring-buffer to prevent packet drops
        .timeout(1) // Low timeout for real-time responsiveness
        .open()
        .expect("Failed to open device");

    // Bounded lock-free channel to pipe events to the analyzer thread
    let (tx, rx): (Sender<PacketEvent>, Receiver<PacketEvent>) = bounded(100_000);

    // Shared thread-safe, sharded hash map for storing flow states
    let flow_table = Arc::new(DashMap::new());
    let flow_table_clone = Arc::clone(&flow_table);

    // --- THREAD 1: Analyzer Thread ---
    thread::spawn(move || {
        analyze_packets(rx, flow_table_clone);
    });

    // --- THREAD 2: Reporter Thread (Prints stats every 3 seconds) ---
    let flow_table_reporter = Arc::clone(&flow_table);
    thread::spawn(move || loop {
        thread::sleep(Duration::from_secs(3));
        print_active_flows(&flow_table_reporter);
    });

    // --- MAIN THREAD: Fast Capture & Parse Loop ---
    println!("Parser running. Press Ctrl+C to stop...");
    let mut packet_count = 0u64;
    let start_time = Instant::now();

    while let Ok(packet) = cap.next_packet() {
        packet_count += 1;

        // Zero-copy header parsing
        if let Some(key) = parse_packet_headers(&packet.data) {
            let event = PacketEvent {
                key,
                len: packet.header.len as usize,
            };
            // Non-blocking send to avoid stalling the capture loop if queue is full
            let _ = tx.try_send(event);
        }

        if packet_count % 500_000 == 0 {
            let pps = packet_count as f64 / start_time.elapsed().as_secs_f64();
            println!("[Capture Node] Current capture rate: {:.2} Packets/Sec", pps);
        }
    }
}

// 3. Ultra-Fast Zero-Copy Packet Parsing
#[inline(always)]
fn parse_packet_headers(packet: &[u8]) -> Option<FlowKey> {
    // 14 bytes Ethernet Header
    if packet.len() < 14 { return None; }
    let eth_type = u16::from_be_bytes([packet[12], packet[13]]);
    if eth_type != 0x0800 { return None; } // Only process IPv4

    // IPv4 Header
    let ip_start = 14;
    if packet.len() < ip_start + 20 { return None; }
    let ihl = (packet[ip_start] & 0x0F) as usize * 4; // IP Header Length
    let proto = packet[ip_start + 9];

    // Read IPs directly from raw bytes without allocations
    let src_ip = Ipv4Addr::new(packet[ip_start+12], packet[ip_start+13], packet[ip_start+14], packet[ip_start+15]);
    let dst_ip = Ipv4Addr::new(packet[ip_start+16], packet[ip_start+17], packet[ip_start+18], packet[ip_start+19]);

    // Layer 4 Headers (TCP or UDP)
    let l4_start = ip_start + ihl;
    if packet.len() < l4_start + 4 { return None; }
    let src_port = u16::from_be_bytes([packet[l4_start], packet[l4_start + 1]]);
    let dst_port = u16::from_be_bytes([packet[l4_start + 2], packet[l4_start + 3]]);

    if proto == 6 || proto == 17 { // TCP or UDP
        Some(FlowKey {
            src_ip,
            dst_ip,
            src_port,
            dst_port,
            proto,
        })
    } else {
        None
    }
}

// 4. Thread-Safe Flow State Aggregation
fn analyze_packets(rx: Receiver<PacketEvent>, flow_table: Arc<DashMap<FlowKey, FlowStats>>) {
    while let Ok(event) = rx.recv() {
        let now = Instant::now();
        // Insert or update flow records safely across threads
        flow_table
            .entry(event.key)
            .and_modify(|stats| {
                stats.packet_count += 1;
                stats.byte_count += event.len as u64;
                stats.last_seen = now;
            })
            .or_insert(FlowStats {
                packet_count: 1,
                byte_count: event.len as u64,
                first_seen: now,
                last_seen: now,
            });
    }
}

// 5. Reporting Pipeline
fn print_active_flows(flow_table: &DashMap<FlowKey, FlowStats>) {
    if flow_table.is_empty() { return; }

    println!("\n--- ACTIVE FLOWS (Top 5 by Volume) ---");
    let mut flows: Vec<_> = flow_table.iter().collect();

    // Sort by byte volume descending
    flows.sort_by(|a, b| b.value().byte_count.cmp(&a.value().byte_count));

    for entry in flows.iter().take(5) {
        let (key, stats) = (entry.key(), entry.value());
        let duration = stats.last_seen.duration_since(stats.first_seen).as_secs_f64();
        let proto_str = if key.proto == 6 { "TCP" } else { "UDP" };

        println!(
            "{:5} | {} : {} -> {} : {} | Packets: {:8} | Bytes: {:10} | Dur: {:.2}s",
            proto_str, key.src_ip, key.src_port, key.dst_ip, key.dst_port,
            stats.packet_count, stats.byte_count, duration
        );
    }
    println!("------------------------------------\n");
}
```

### Why this design hits gigabit performance:

1. **Snaplen Tuning (`snaplen(64)`):** A network flow analyzer only needs header data, not the application payload. By slicing the capture at 64 bytes, we drastically reduce PCIe bus transfer latency from the NIC to host memory.
2. **Ring Buffer Expansion (`16MB`):** Prevents packet drops inside the Linux kernel during intense processing bursts or context switching.
3. **No Garbage Collection:** Rust handles memory deallocations deterministically when packets drop out of scope. There is absolutely zero jitter.
4. **Zero-Copy Parsing (`parse_packet_headers`):** Raw byte slices (`&[u8]`) are converted into IP configurations and port integers directly via pointer manipulation, without copying the underlying slice to new memory locations. 
5. **No Queue Allocation:** The `PacketEvent` sent through the `crossbeam-channel` is a pure value struct allocated on the stack. The channel handles this using a ring-buffer pipeline without triggering memory allocations.

To handle gigabit-scale traffic (which can exceed **1.4 million packets per second** at line rate for small packets), a network flow analyzer must avoid the two greatest performance killers: **kernel-to-user memory copying** and **dynamic memory allocations in the packet-processing hot path**.

