use fxhash::FxHashMap;
use pcap::{Capture, Device};
use std::net::Ipv4Addr;
use std::time::{Duration, Instant};

// 1. Define a lightweight, 13-byte Flow Key. 
// We derive Hash and Eq for fast lookup in our map.
#[derive(Hash, PartialEq, Eq, Debug, Clone, Copy)]
struct FlowKey {
    src_ip: Ipv4Addr,
    dst_ip: Ipv4Addr,
    src_port: u16,
    dst_port: u16,
    proto: u8,
}

// 2. Define the flow metrics we want to track.
struct FlowStats {
    packet_count: u64,
    byte_count: u64,
    first_seen: Instant,
    last_seen: Instant,
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    // Select the default network interface
    let device = Device::lookup()?
        .ok_or("No default device found. Run as root/administrator.")?;
    println!("Capturing on device: {}", device.name);

    // 3. Configure the packet capture handle for high throughput.
    let mut cap = Capture::from_device(device)?
        .promisc(true)
        // CRITICAL: Set snaplen to 128 bytes. We only need headers (Ethernet + IP + TCP/UDP).
        // Truncating the packet at 128 bytes dramatically reduces PCIe and memory bus pressure.
        .snaplen(128)
        // CRITICAL: Set a massive 16MB kernel ring-buffer. 
        // This prevents packet drops during CPU scheduling jitters.
        .buffer_size(16 * 1024 * 1024)
        .timeout(1) // 1ms timeout to keep processing reactive
        .open()?;

    // Using FxHashMap to avoid SipHash overhead in the hot path.
    let mut flow_table: FxHashMap<FlowKey, FlowStats> = FxHashMap::default();

    let mut total_packets: u64 = 0;
    let mut total_bytes: u64 = 0;
    let mut last_report = Instant::now();

    println!("Flow Analyzer started. Processing traffic...");

    // Main packet processing loop
    loop {
        // Zero-copy read from the pcap ring buffer
        if let Ok(packet) = cap.next_packet() {
            let data = packet.data;
            let len = packet.header.len as u64; // Actual on-the-wire length

            total_packets += 1;
            total_bytes += len;

            // 4. Zero-Copy Header Parsing (No heap allocations)
            if data.len() < 34 { continue; } // Must be at least Eth (14) + IPv4 (20)

            // Parse Ethernet Type (Bytes 12-13)
            let eth_type = u16::from_be_bytes([data[12], data[13]]);
            if eth_type != 0x0800 { 
                continue; // Skip non-IPv4 traffic for this minimal example
            }

            // Parse IPv4 Header
            let ip_header = &data[14..];
            let ihl = (ip_header[0] & 0x0F) as usize * 4; // Internet Header Length
            if ip_header.len() < ihl { continue; }

            let proto = ip_header[9];
            if proto != 6 && proto != 17 { 
                continue; // Skip if not TCP (6) or UDP (17)
            }

            // Extract IPs
            let src_ip = Ipv4Addr::new(ip_header[12], ip_header[13], ip_header[14], ip_header[15]);
            let dst_ip = Ipv4Addr::new(ip_header[16], ip_header[17], ip_header[18], ip_header[19]);

            // Parse Layer 4 Ports
            if ip_header.len() < ihl + 4 { continue; }
            let l4_header = &ip_header[ihl..];
            let src_port = u16::from_be_bytes([l4_header[0], l4_header[1]]);
            let dst_port = u16::from_be_bytes([l4_header[2], l4_header[3]]);

            // Create Flow Key
            let key = FlowKey {
                src_ip,
                dst_ip,
                src_port,
                dst_port,
                proto,
            };

            // 5. High-performance Map Insertion
            let now = Instant::now();
            flow_table.entry(key)
                .and_modify(|stats| {
                    stats.packet_count += 1;
                    stats.byte_count += len;
                    stats.last_seen = now;
                })
                .or_insert(FlowStats {
                    packet_count: 1,
                    byte_count: len,
                    first_seen: now,
                    last_seen: now,
                });
        }

        // 6. Non-blocking periodic reporting (every 5 seconds)
        if last_report.elapsed() >= Duration::from_secs(5) {
            println!("\n=== Flow Report ===");
            println!("Total Volume: {:.2} MB ({} packets)", total_bytes as f64 / 1_048_576.0, total_packets);
            println!("Active Concurrent Flows: {}", flow_table.len());

            // Print the top 5 heaviest flows
            let mut flows: Vec<(&FlowKey, &FlowStats)> = flow_table.iter().collect();
            flows.sort_unstable_by_key(|(_, stats)| std::cmp::Reverse(stats.byte_count));

            for (key, stats) in flows.iter().take(5) {
                let proto_str = match key.proto {
                    6 => "TCP",
                    17 => "UDP",
                    _ => "OTHER",
                };
                println!(
                    "  {}:{} -> {}:{} [{}] | {} pkts | {} bytes",
                    key.src_ip, key.src_port, key.dst_ip, key.dst_port, proto_str, stats.packet_count, stats.byte_count
                );
            }

            // Housekeeping: Clear flow table to prevent memory exhaustion in this demo
            flow_table.clear();
            last_report = Instant::now();
        }
    }
}
