### 1. Data Processing Module (`filter.h` & `filter.c`)
This module handles the smoothing of noisy sensor data using a low-pass filter.

```c
// filter.h
#ifndef FILTER_H
#define FILTER_H

typedef struct {
    float alpha;      // Smoothing factor (0.0 to 1.0). Lower = smoother but slower response.
    float filtered_val;
    int is_initialized;
} EMAFilter_t;

void Filter_Init(EMAFilter_t *filter, float alpha);
float Filter_Update(EMAFilter_t *filter, float input);

#endif // FILTER_H
```

```c
// filter.c
#include "filter.h"

void Filter_Init(EMAFilter_t *filter, float alpha) {
    filter->alpha = alpha;
    filter->filtered_val = 0.0f;
    filter->is_initialized = 0;
}

float Filter_Update(EMAFilter_t *filter, float input) {
    if (!filter->is_initialized) {
        filter->filtered_val = input;
        filter->is_initialized = 1;
    } else {
        // Exponential Moving Average Formula: Y[n] = α * X[n] + (1 - α) * Y[n-1]
        filter->filtered_val = (filter->alpha * input) + ((1.0f - filter->alpha) * filter->filtered_val);
    }
    return filter->filtered_val;
}
