```cpp
#include <Wire.h> // Standard I2C library

// --- CONFIGURATION CONSTANTS ---
#define SENSOR_I2C_ADDR     0x40       // Example I2C Address of the sensor
#define REG_TEMP_DATA       0x05       // Register address for temperature data
#define FILTER_ALPHA        0.2f       // Filter coefficient (0.0 to 1.0). Lower = smoother but slower response.
#define TEMP_THRESHOLD      45.0f      // Over-temperature threshold in Celsius
#define SAMPLE_INTERVAL_MS  100        // Read sensor every 100ms (10Hz)

// --- PIN DEFINITIONS ---
#define LED_ALERT_PIN       2          // Onboard LED for visual alarm
#define ERROR_LED_PIN       4          // System error indicator

// --- SIGNAL PROCESSING CLASS ---
class LowPassFilter {
private:
    float m_filteredValue;
    float m_alpha;
    bool m_isInitialized;

public:
    LowPassFilter(float alpha) : m_alpha(alpha), m_filteredValue(0.0f), m_isInitialized(false) {}

    float filter(float newValue) {
        if (!m_isInitialized) {
            // Warm up the filter with the first reading
            m_filteredValue = newValue;
            m_isInitialized = true;
        } else {
            // Exponential Moving Average (EMA) Formula: 
            // Y[n] = alpha * X[n] + (1 - alpha) * Y[n-1]
            m_filteredValue = (m_alpha * newValue) + ((1.0f - m_alpha) * m_filteredValue);
        }
        return m_filteredValue;
    }

    void reset() {
        m_isInitialized = false;
    }
};

// --- SYSTEM STATES ---
enum SystemState {
    SYSTEM_OK,
    SYSTEM_WARNING,
    SYSTEM_ERROR
};

// --- GLOBAL VARIABLES ---
LowPassFilter tempFilter(FILTER_ALPHA);
SystemState currentState = SYSTEM_OK;
unsigned long lastSampleTime = 0;

// --- HARDWARE INTERFACE FUNCTIONS ---

// Initializes the I2C peripheral and GPIOs
void initHardware() {
    Wire.begin(); // Join I2C bus as Master

    pinMode(LED_ALERT_PIN, OUTPUT);
    pinMode(ERROR_LED_PIN, OUTPUT);
    digitalWrite(LED_ALERT_PIN, LOW);
    digitalWrite(ERROR_LED_PIN, LOW);
}

// Reads 16-bit raw data from the I2C sensor and converts it to Celsius
bool readSensorTemperature(float &temperature) {
    Wire.beginTransmission(SENSOR_I2C_ADDR);
    Wire.write(REG_TEMP_DATA);

    if (Wire.endTransmission() != 0) {
        // I2C Transmission failed (Sensor disconnected or bus error)
        return false; 
    }

    // Request 2 bytes of data
    Wire.requestFrom(SENSOR_I2C_ADDR, 2);
    if (Wire.available() == 2) {
        uint8_t msb = Wire.read();
        uint8_t lsb = Wire.read();

        // Combine bytes into a 16-bit raw value
        int16_t rawVal = (msb << 8) | lsb;

        // Example ADC conversion formula (specific to sensor datasheet)
        // e.g., Temp = (Raw * 175.72 / 65536) - 46.85
        temperature = ((float)rawVal * 175.72f / 65536.0f) - 46.85f;
        return true;
    }

    return false; // Timeout/Incomplete read
}

// --- MAIN FIRMWARE SETUP ---
void setup() {
    Serial.begin(115200);
    while(!Serial) { ; } // Wait for serial port to connect (debug only)

    Serial.println("[SYSTEM INIT] Starting Firmware...");
    initHardware();
    Serial.println("[SYSTEM INIT] Hardware Initialized.");
}

// --- MAIN FIRMWARE LOOP ---
void loop() {
    unsigned long currentTime = millis();

    // Non-blocking execution loop running at 10Hz
    if (currentTime - lastSampleTime >= SAMPLE_INTERVAL_MS) {
        lastSampleTime = currentTime;

        float rawTemperature = 0.0f;

        // 1. Read Sensor Data
        if (readSensorTemperature(rawTemperature)) {
            // Clear error state if communication is restored
            if (currentState == SYSTEM_ERROR) {
                currentState = SYSTEM_OK;
                digitalWrite(ERROR_LED_PIN, LOW);
                tempFilter.reset();
                Serial.println("[SYSTEM INFO] Sensor reconnected.");
            }

            // 2. Process Data (Apply Digital Filter)
            float filteredTemperature = tempFilter.filter(rawTemperature);

            // Print telemetry data for plotting/debugging
            Serial.print("Raw_Temp:");
            Serial.print(rawTemperature);
            Serial.print(",Filtered_Temp:");
            Serial.println(filteredTemperature);

            // 3. Act on Data (Threshold Monitoring)
            if (filteredTemperature >= TEMP_THRESHOLD) {
                currentState = SYSTEM_WARNING;
                digitalWrite(LED_ALERT_PIN, HIGH); // Turn on Over-Temp Alert LED
                Serial.print("[WARNING] Over-temperature detected! Temp: ");
                Serial.println(filteredTemperature);
            } else {
                currentState = SYSTEM_OK;
                digitalWrite(LED_ALERT_PIN, LOW);  // Clear Warning
            }

        } else {
            // Handle sensor read failure
            currentState = SYSTEM_ERROR;
            digitalWrite(ERROR_LED_PIN, HIGH);  // Turn on Error LED
            digitalWrite(LED_ALERT_PIN, LOW);   // Disable warning LED in error state
            Serial.println("[ERROR] Failed to read from I2C sensor!");
        }
    }

    // Microcontroller can perform other tasks here (low-power modes, RF transmission, etc.)
}
```

### Key Firmware Best Practices Implemented:
* **No `delay()` calls:** Uses non-blocking scheduling based on `millis()`. This prevents the MCU from freezing and allows other routines (like communication or safety interrupts) to run concurrently.
* **Low Memory DSP:** The Exponential Moving Average (EMA) filter only requires holding **one** float variable in memory, unlike a standard moving average which requires a massive circular buffer array.
* **Fail-Safe Design:** If the sensor's physical wire is disconnected, the firmware catches the I2C failure immediately, enters a `SYSTEM_ERROR` state, lights up an error LED, and gracefully resets the filters once connection is restored.
* **Separation of Concerns:** Hardware interactions (I2C), signal processing (EMA), and state actions (LED trigger) are strictly separated into dedicated functions and classes.

