```cpp
#include <Arduino.h>

// ==========================================
// CONFIGURATION & PIN DEFINITIONS
// ==========================================
const int SENSOR_PIN = A0;          // Analog pin connected to the sensor
const int ALERT_LED_PIN = 13;       // Onboard LED used for over-temperature alert

// Timing configuration (Non-blocking)
const uint32_t SAMPLE_INTERVAL_MS = 100; // Read sensor at 10 Hz (every 100ms)
const uint32_t Serial_DEBUG_INTERVAL_MS = 1000; // Print data every 1 second

// Sensor calibration constants (e.g., for TMP36 sensor)
const float ADC_RESOLUTION = 1024.0; // 10-bit ADC
const float SYSTEM_VOLTAGE = 5.0;    // 5V system (use 3.3 for ESP32/ARM)
const float TEMP_OFFSET = 0.5;       // TMP36 offset is 500mV
const float TEMP_SCALE = 100.0;      // TMP36 scale is 10mV/°C (100°C/V)

// DSP / Processing Parameters
const float FILTER_ALPHA = 0.15;     // EMA filter smoothing factor (0.0 to 1.0)
                                     // Lower = smoother but slower response.
const float TEMP_ALERT_THRESHOLD = 37.5; // Alert threshold in Celsius

// ==========================================
// CLASS DEFINITIONS (Encapsulation)
// ==========================================

// Simple Low-Pass Exponential Moving Average (EMA) Filter
class LowPassFilter {
private:
    float m_alpha;
    float m_filteredValue;
    bool m_isInitialized;

public:
    LowPassFilter(float alpha) : m_alpha(alpha), m_filteredValue(0.0f), m_isInitialized(false) {}

    float filter(float input) {
        if (!m_isInitialized) {
            m_filteredValue = input; // Initialize filter with first reading
            m_isInitialized = true;
        } else {
            // Formula: Y(n) = α * X(n) + (1 - α) * Y(n-1)
            m_filteredValue = (m_alpha * input) + ((1.0f - m_alpha) * m_filteredValue);
        }
        return m_filteredValue;
    }
};

// ==========================================
// GLOBAL STATE VARIABLES
// ==========================================
LowPassFilter tempFilter(FILTER_ALPHA);

uint32_t lastSampleTime = 0;
uint32_t lastLogTime = 0;
float currentFilteredTemp = 0.0;

// ==========================================
// HELPER FUNCTIONS
// ==========================================

/**
 * Reads the analog pin multiple times (oversampling) 
 * to reduce random thermal noise.
 */
int readOversampledADC(int pin, int samples = 8) {
    uint32_t sum = 0;
    for (int i = 0; i < samples; i++) {
        sum += analogRead(pin);
        delayMicroseconds(50); // Small delay to let ADC sample-and-hold capacitor settle
    }
    return sum / samples;
}

/**
 * Converts raw ADC steps to Temperature in Celsius.
 */
float rawToCelsius(int rawAdc) {
    float voltage = (rawAdc / ADC_RESOLUTION) * SYSTEM_VOLTAGE;
    float tempC = (voltage - TEMP_OFFSET) * TEMP_SCALE;
    return tempC;
}

// ==========================================
// MAIN FIRMWARE SETUP & LOOP
// ==========================================

void setup() {
    // Initialize hardware peripherals
    Serial.begin(115200);
    pinMode(ALERT_LED_PIN, OUTPUT);
    digitalWrite(ALERT_LED_PIN, LOW);

    Serial.println("--- Firmware Initialized ---");
    Serial.print("Target Temp Threshold: ");
    Serial.print(TEMP_ALERT_THRESHOLD);
    Serial.println(" C");
}

void loop() {
    uint32_t currentTime = millis();

    // Task 1: Read and Process Sensor Data (at 10Hz)
    if (currentTime - lastSampleTime >= SAMPLE_INTERVAL_MS) {
        lastSampleTime = currentTime;

        // 1. Read Raw Data (with Oversampling)
        int rawAdcValue = readOversampledADC(SENSOR_PIN);

        // 2. Convert to Engineering Units (Celsius)
        float rawTemp = rawToCelsius(rawAdcValue);

        // 3. Process Data (Digital Filtering)
        currentFilteredTemp = tempFilter.filter(rawTemp);

        // 4. Act on Processed Data (Threshold Comparison)
        if (currentFilteredTemp >= TEMP_ALERT_THRESHOLD) {
            digitalWrite(ALERT_LED_PIN, HIGH); // Trigger Alert
        } else {
            digitalWrite(ALERT_LED_PIN, LOW);  // Safe
        }
    }

    // Task 2: Log Data (at 1Hz) - Keeps Serial bus efficient
    if (currentTime - lastLogTime >= Serial_DEBUG_INTERVAL_MS) {
        lastLogTime = currentTime;

        // Output raw vs filtered data (Format compatible with Arduino Serial Plotter)
        Serial.print("Filtered_Temp:");
        Serial.print(currentFilteredTemp);
        Serial.print(",Threshold:");
        Serial.print(TEMP_ALERT_THRESHOLD);
        Serial.print(",Alert_Active:");
        Serial.println(currentFilteredTemp >= TEMP_ALERT_THRESHOLD ? 40 : 20); // visual offset for plot
    }
}
```

### Why this code is optimized for microcontrollers:

1. **Non-Blocking Architecture:** Instead of using `delay()`, which halts the CPU, the code uses `millis()` time-checks. This allows you to easily add other tasks (like handling button interrupts, updating an LCD display, or listening to incoming Serial commands) without lag.
2. **Oversampling (`readOversampledADC`):** Microcontroller ADCs can be noisy. Taking the average of 8 quick samples stabilizes the signal before processing.
3. **Low-Pass Filtering Class:** Raw sensors fluctuate due to environmental electrical noise. The Exponential Moving Average (EMA) filter mathematically smooths out spikes without requiring large memory arrays (unlike a standard "mean" filter which requires storing a massive array of past readings).
4. **Encapsulation:** The filter is written as a C++ object (`LowPassFilter`), meaning if you add a second sensor, you can easily create `LowPassFilter pressureFilter(0.1);` without duplicating filter variables.

