// SENSOR PROCESSING FUNCTIONS
// ==========================================

/**
 * @brief Convert raw ADC value to physical temperature in Celsius
 */
float ConvertRawToCelsius(float adc_val) {
    // Voltage = (ADC_Val / Max_Steps) * V_Ref
    float voltage = (adc_val / ADC_MAX_STEPS) * ADC_REFERENCE_VOLTAGE;
    // Temp (°C) = Voltage / Sensitivity
    return voltage / SENSOR_SENSITIVITY_V_C;
}

/**
 * @brief Reads, filters, and processes sensor data
 */
void Sensor_Update(SensorData_t *sensor) {
    // 1. Read raw value from Analog Pin 0
    sensor->raw_adc = HAL_ADC_ReadChannel(0);

    // 2. Process: Apply Exponential Moving Average (EMA) filter to remove noise
    // Formula: Y[n] = (Alpha * X[n]) + ((1 - Alpha) * Y[n-1])
    sensor->filtered_adc = (EMA_ALPHA * (float)sensor->raw_adc) + 
                           ((1.0f - EMA_ALPHA) * sensor->filtered_adc);

    // 3. Convert filtered ADC value to actual Temperature
    sensor->temperature_c = ConvertRawToCelsius(sensor->filtered_adc);
}

