    uint32_t last_poll_time = 0;

    // Seed the filter with an initial raw read so it doesn't start from 0
    temp_sensor.raw_adc = HAL_ADC_ReadChannel(0);
    temp_sensor.filtered_adc = (float)temp_sensor.raw_adc;

    // Super Loop (Infinite Main Loop)
    while (1) {
        uint32_t current_time = HAL_GetTick();

        // Non-blocking timer check
        if (current_time - last_poll_time >= SENSOR_POLL_INTERVAL_MS) {
            last_poll_time = current_time;

