    Hardware_Init();

    // 2. Initialize our sensor data structure
    Sensor_Init(&g_temp_sensor);

    uint32_t last_sample_time = 0;

    // 3. Super Loop (Main Program Loop)
    while (1) {
        uint32_t current_time = HAL_GetTick();

        // Non-blocking timing: Sample the sensor every 100ms
        if ((current_time - last_sample_time) >= SAMPLING_RATE_MS) {
            last_sample_time = current_time;

            // Trigger and read ADC
            Sensor_Update(&g_temp_sensor);

            // Filter raw data and convert to Celsius
            Sensor_Process(&g_temp_sensor);

            // Send processed data over Serial/UART for telemetry
            Log_Data(&g_temp_sensor);
        }

        // Other low-priority background tasks can go here
    }
}

/* --- Function Implementations --- */

/**
 * @brief Initializes the sensor data structure with safe default values.
 */
void Sensor_Init(SensorData_t *sensor) {
    sensor->raw_adc = 0;
    sensor->filtered_adc = 0.0f;
    sensor->voltage_mv = 0.0f;
    sensor->temperature_c = 0.0f;
}

/**
 * @brief Triggers the hardware ADC and reads the raw sensor value.
 */
void Sensor_Update(SensorData_t *sensor) {
    ADC_Start_Conversion();

    // Wait for conversion (In safety-critical firmware, add a timeout here)
    while (!ADC_Is_Conversion_Complete());

    sensor->raw_adc = ADC_Get_Value();
}

/**
 * @brief Applies DSP filtering and converts raw data to engineering units.
 */
void Sensor_Process(SensorData_t *sensor) {
    // Initialize filter on the very first run to prevent a slow ramp-up from 0
    if (sensor->filtered_adc == 0.0f) {
        sensor->filtered_adc = (float)sensor->raw_adc;
    }

    // 1. DSP: Exponential Moving Average (EMA) Low-Pass Filter
    // Formula: Y[n] = Alpha * X[n] + (1 - Alpha) * Y[n-1]
    sensor->filtered_adc = (FILTER_ALPHA * (float)sensor->raw_adc) + 
                           ((1.0f - FILTER_ALPHA) * sensor->filtered_adc);

    // 2. Convert filtered ADC steps to millivolts
    sensor->voltage_mv = (sensor->filtered_adc * (float)V_REF_MV) / (float)ADC_MAX_VALUE;

    // 3. Convert millivolts to Temperature (Celsius)
    sensor->temperature_c = sensor->voltage_mv / (float)SENSOR_SENSITIVITY;
}

/**
 * @brief Helper function to format and transmit data over UART (Serial).
 */
void Log_Data(const SensorData_t *sensor) {
    char tx_buffer[64];

    // Convert floats to integers for safe and fast printing in embedded systems
    int temp_whole = (int)sensor->temperature_c;
    int temp_fraction = (int)((sensor->temperature_c - temp_whole) * 100);
    if (temp_fraction < 0) temp_fraction = -temp_fraction;

    // Format: "RAW: 2048 | Temp: 25.42 C\r\n"
    // Using custom formatting to avoid heavy standard library sprintf if memory is tight
    __builtin_sprintf(tx_buffer, "RAW: %lu | Temp: %d.%02d C\r\n", 
                      sensor->raw_adc, temp_whole, temp_fraction);

    USART_Transmit_String(tx_buffer);
}
