#include <Wire.h> // Standard Arduino I2C library

// Configuration Constants
const uint8_t SENSOR_I2C_ADDR = 0x68;     // Example I2C address (e.g., MPU6050)
const unsigned long SAMPLE_INTERVAL_MS = 10; // 100 Hz sampling rate
const float FILTER_ALPHA = 0.2f;          // Filter coefficient (0.0 to 1.0). Lower = smoother but slower response.
const float ACCEL_THRESHOLD = 2.5f;       // G-force threshold for anomaly detection

// Structure to hold 3-axis sensor data
struct AccelData {
    float x;
    float y;
    float z;
};

// Class to handle low-pass filtering of sensor data
class LowPassFilter {
private:
    float alpha;
    AccelData filteredData;
    bool isInitialized;

public:
    LowPassFilter(float cutoffAlpha) : alpha(cutoffAlpha), isInitialized(false) {
        filteredData = {0.0f, 0.0f, 0.0f};
    }

    // Applies Exponential Moving Average: Y[n] = alpha * X[n] + (1 - alpha) * Y[n-1]
    AccelData process(const AccelData& raw) {
        if (!isInitialized) {
            filteredData = raw;
            isInitialized = true;
            return filteredData;
        }

        filteredData.x = (alpha * raw.x) + ((1.0f - alpha) * filteredData.x);
        filteredData.y = (alpha * raw.y) + ((1.0f - alpha) * filteredData.y);
        filteredData.z = (alpha * raw.z) + ((1.0f - alpha) * filteredData.z);

        return filteredData;
    }
};

// Class to interface with the physical Sensor
class IMUSensor {
private:
    uint8_t i2cAddress;

public:
    IMUSensor(uint8_t address) : i2cAddress(address) {}

    bool begin() {
        Wire.begin();

        // Verify sensor connection
        Wire.beginTransmission(i2cAddress);
        if (Wire.endTransmission() != 0) {
            return false; // Sensor not found
        }

        // Initialize sensor registers (Generic setup example)
        Wire.beginTransmission(i2cAddress);
        Wire.write(0x6B); // Power Management Register
        Wire.write(0x00); // Wake up sensor
        Wire.endTransmission();

        return true;
    }

    bool readRawData(AccelData& outData) {
        // Request 6 bytes of data from the sensor (2 bytes per axis: X, Y, Z)
        Wire.beginTransmission(i2cAddress);
        Wire.write(0x3B); // Register containing X-axis high byte
        if (Wire.endTransmission() != 0) return false;

        Wire.requestFrom(i2cAddress, (uint8_t)6);
        if (Wire.available() < 6) return false;

        // Read and combine MSB/LSB, converting to dynamic float values (Gs)
        int16_t rawX = (Wire.read() << 8) | Wire.read();
        int16_t rawY = (Wire.read() << 8) | Wire.read();
        int16_t rawZ = (Wire.read() << 8) | Wire.read();

        // Sensitivity scale factor (e.g., for +/- 2g range, LSB/g is 16384)
        const float LSB_PER_G = 16384.0f;
        outData.x = (float)rawX / LSB_PER_G;
        outData.y = (float)rawY / LSB_PER_G;
        outData.z = (float)rawZ / LSB_PER_G;

        return true;
    }
};

// Global Object Instantiations
IMUSensor sensor(SENSOR_I2C_ADDR);
LowPassFilter filter(FILTER_ALPHA);

unsigned long lastSampleTime = 0;

// Setup Routine: Executes once on boot
void setup() {
    Serial.begin(115200);
    while (!Serial) { ; } // Wait for serial port connection (USB)

    Serial.println("[SYSTEM] Initializing firmware...");

    if (!sensor.begin()) {
        Serial.println("[ERROR] Sensor initialization failed! Halting system.");
        while (1) { 
            // Blink onboard LED fast to signal critical error
            digitalWrite(LED_BUILTIN, !digitalRead(LED_BUILTIN));
            delay(100);
        }
    }

    Serial.println("[SYSTEM] Sensor found and initialized successfully.");
}

// Main Execution Loop: Runs continuously
void loop() {
    unsigned long currentTime = millis();

    // Non-blocking timing: process data precisely every 10 milliseconds
    if (currentTime - lastSampleTime >= SAMPLE_INTERVAL_MS) {
        lastSampleTime = currentTime;

        AccelData rawData;

        // 1. Read raw sensor data
        if (sensor.readRawData(rawData)) {

            // 2. Process data (Apply Low-Pass Filter)
            AccelData processedData = filter.process(rawData);

            // 3. Analyze processed data for anomalies
            bool anomalyDetected = (abs(processedData.x) > ACCEL_THRESHOLD || 
                                    abs(processedData.y) > ACCEL_THRESHOLD || 
                                    abs(processedData.z) > ACCEL_THRESHOLD);

            // 4. Output/React
            if (anomalyDetected) {
                Serial.print("[ALERT] High G-Force Detected! ");
                Serial.print("X: "); Serial.print(processedData.x, 2);
                Serial.print(" Y: "); Serial.print(processedData.y, 2);
                Serial.print(" Z: "); Serial.println(processedData.z, 2);

