                Serial.print(" Y: "); Serial.print(processedData.y, 2);
                Serial.print(" Z: "); Serial.println(processedData.z, 2);
            }

        } else {
            Serial.println("[WARNING] Sensor read timeout/communication failure.");
        }
    }

    // You can safely perform other, non-blocking background tasks here
}
