#define SENSOR_I2C_ADDR       0x48      // Standard 7-bit I2C address for LM75/TMP102
#define REG_TEMP              0x00      // Temperature register address
#define REG_CONFIG            0x01      // Configuration register address

#define SAMPLE_RATE_MS        100       // Sample every 100ms (10 Hz)
#define FILTER_ALPHA          0.2f      // Smoothing factor for EMA filter (0.0 to 1.0)
#define TEMP_THRESHOLD_HIGH   45.0f     // Alert threshold in Celsius

// ==========================================
// MOCK HARDWARE ABSTRACATION LAYER (HAL)
// (In a real system, these link to your MCU SDK)
// ==========================================
typedef enum { HAL_OK = 0, HAL_ERROR = 1 } HAL_Status;

extern HAL_Status HAL_I2C_Write(uint8_t dev_addr, uint8_t reg, uint8_t *data, uint16_t len);
extern HAL_Status HAL_I2C_Read(uint8_t dev_addr, uint8_t reg, uint8_t *data, uint16_t len);
extern void HAL_UART_Transmit(const char *message);
extern void HAL_Delay_Ms(uint32_t ms);
extern void HAL_GPIO_Write_Pin_Alarm(bool state);

