// ==========================================
typedef struct {
    float raw_temperature;
    float filtered_temperature;
    bool alarm_active;
} SensorData_t;

// Global system state
static SensorData_t g_sensor_state = {0};

// ==========================================
// DRIVER & PROCESSING FUNCTIONS
// ==========================================

/**
 * @brief Initializes the temperature sensor.
 * @return true if initialization succeeded, false otherwise.
 */
bool Sensor_Init(void) {
    uint8_t config_data = 0x00; // Normal operation mode, 12-bit resolution

    // Write configuration to sensor
    if (HAL_I2C_Write(SENSOR_I2C_ADDR, REG_CONFIG, &config_data, 1) != HAL_OK) {
        HAL_UART_Transmit("Error: Failed to initialize sensor over I2C.\r\n");
        return false;
    }
    HAL_UART_Transmit("Sensor initialized successfully.\r\n");
    return true;
}

/**
 * @brief Reads raw 12-bit temperature from I2C and processes it to Celsius.
 * @param[out] temp_c Pointer to store the calculated temperature.
 * @return HAL_Status success or error code.
 */
HAL_Status Sensor_Read_Temp(float *temp_c) {
    uint8_t raw_bytes[2] = {0};

    // Read 2 bytes from the temperature register
    if (HAL_I2C_Read(SENSOR_I2C_ADDR, REG_TEMP, raw_bytes, 2) != HAL_OK) {
        return HAL_ERROR;
    }

    // Convert the two 8-bit registers into a single 12-bit signed integer
    // The TMP102 stores data left-aligned: MSB (8 bits) | LSB (upper 4 bits)
    int16_t raw_12bit = (raw_bytes[0] << 4) | (raw_bytes[1] >> 4);

    // Handle negative temperatures (Sign extension for 12-bit two's complement)
    if (raw_12bit & (1 << 11)) {
        raw_12bit |= 0xF000; // Fill upper 4 bits with 1s for proper negative representation
    }

    // Convert to Celsius (Resolution is 0.0625°C per LSB)
    *temp_c = (float)raw_12bit * 0.0625f;

    return HAL_OK;
}

/**
 * @brief Applies an Exponential Moving Average (EMA) Filter to smooth raw data.
 * Formula: Y[n] = Alpha * X[n] + (1 - Alpha) * Y[n-1]
 */
float Processing_Apply_Filter(float current_val, float previous_filtered_val) {
    // On the very first run, previous_filtered_val will be 0. Avoid lag by detecting this.
    if (previous_filtered_val == 0.0f) {
        return current_val;
    }
    return (FILTER_ALPHA * current_val) + ((1.0f - FILTER_ALPHA) * previous_filtered_val);
}

/**
 * @brief Evaluates system state and drives hardware safety actuators.
 */
void Safety_Check(const SensorData_t *state) {
    if (state->filtered_temperature > TEMP_THRESHOLD_HIGH) {
        if (!state->alarm_active) {
            HAL_GPIO_Write_Pin_Alarm(true); // Turn on physical alarm LED/Buzzer
            HAL_UART_Transmit("WARNING: High temperature threshold exceeded!\r\n");
        }
    } else {
        if (state->alarm_active) {
            HAL_GPIO_Write_Pin_Alarm(false); // Clear alarm
            HAL_UART_Transmit("INFO: Temperature returned to normal.\r\n");
        }
    }
}

