    HAL_UART_Transmit("Booting Firmware...\r\n");

    // 2. Initialize external sensors
    if (!Sensor_Init()) {
        // Safe state: Lock up system or trigger watchdog if critical sensor is missing
        while(1) {
            HAL_GPIO_Write_Pin_Alarm(true); // Flash alarm to indicate hardware failure
            HAL_Delay_Ms(500);
            HAL_GPIO_Write_Pin_Alarm(false);
            HAL_Delay_Ms(500);
        }
    }

    // 3. Super Loop (Main Execution)
    while (1) {
        float raw_temp_reading = 0.0f;

        // Step A: Read sensor data
        if (HAL_I2C_Read(SENSOR_I2C_ADDR, REG_TEMP, (uint8_t*)&raw_temp_reading, 2) == HAL_OK) {

            if (Sensor_Read_Temp(&raw_temp_reading) == HAL_OK) {
                g_sensor_state.raw_temperature = raw_temp_reading;

                // Step B: Process data (Low-pass filter to remove sensor/electrical noise)
                g_sensor_state.filtered_temperature = Processing_Apply_Filter(
                    g_sensor_state.raw_temperature, 
                    g_sensor_state.filtered_temperature
                );

                // Step C: Act on the processed data (Safety monitoring)
                Safety_Check(&g_sensor_state);
            } else {
                HAL_UART_Transmit("Error: Failed to process sensor read.\r\n");
            }
        } else {
            HAL_UART_Transmit("Error: Sensor disconnected or I2C bus error.\r\n");
        }

        // Step D: Delay to maintain a fixed execution interval (10 Hz)
        HAL_Delay_Ms(SAMPLE_RATE_MS);
    }

    return 0; // Should never be reached in bare-metal embedded systems
}
