class LowPassFilter {
private:
    float alpha; // Smoothing factor (0.0 to 1.0). Lower = smoother but slower response.
    float prev_output;
    bool is_initialized;

public:
    LowPassFilter(float smoothing_factor) 
        : alpha(smoothing_factor), prev_output(0.0f), is_initialized(false) {}

    float filter(float input) {
        if (!is_initialized) {
            prev_output = input;
            is_initialized = true;
            return input;
        }
        // Exponential Moving Average formula: y[n] = α * x[n] + (1 - α) * y[n-1]
        float current_output = (alpha * input) + ((1.0f - alpha) * prev_output);
        prev_output = current_output;
        return current_output;
    }

    void reset() {
        is_initialized = false;
    }
};

