Here is a minimal, production-ready version of microcontroller firmware written in <language>C++</language> using the popular Arduino framework. 

This firmware reads an analog sensor, processes the signal using a **digital low-pass filter** (specifically, an Exponential Moving Average) to remove high-frequency noise, and triggers an LED alarm if the processed value exceeds a safety threshold.

### The Code

```cpp
#include <Arduino.h>

// --- Configuration ---
const int SENSOR_PIN = A0;      // Hardware ADC pin connected to the sensor
const int ALARM_PIN = 13;       // Built-in LED pin for physical feedback
const float ADC_REF_VOLTS = 5.0f; // MCU operating voltage (usually 5.0V or 3.3V)
const int ADC_RESOLUTION = 1023;  // 10-bit ADC resolution (2^10 - 1)

// --- DSP Processing Parameters ---
// Filter coefficient (0.0 < ALPHA <= 1.0). 
// Lower values = smoother data but slower response time.
const float ALPHA = 0.15f; 
const float TEMP_THRESHOLD = 37.5f; // Threshold in Degrees Celsius to trigger alarm

// --- State Variables ---
float filteredTemperature = 0.0f;

// Helper function to convert raw ADC bits to Temperature (Celsius)
// Assuming an analog sensor like the LM35 (10mV per Degree Celsius)
float convertToCelsius(int rawADC) {
    float voltage = (rawADC * ADC_REF_VOLTS) / ADC_RESOLUTION;
    return voltage * 100.0f; // 10mV/C means 1V = 100C
}

void setup() {
    // Initialize hardware peripherals
    Serial.begin(115200);
    pinMode(SENSOR_PIN, INPUT);
    pinMode(ALARM_PIN, OUTPUT);

    // Seed the filter with an initial reading to avoid a slow ramp-up at startup
    int initialRaw = analogRead(SENSOR_PIN);
    filteredTemperature = convertToCelsius(initialRaw);
}

void loop() {
    // 1. READ: Sample the sensor via the Analog-to-Digital Converter
    int rawReading = analogRead(SENSOR_PIN);
    float currentTemperature = convertToCelsius(rawReading);

    // 2. PROCESS: Apply Exponential Moving Average (EMA) filter
    // Formula: y[n] = α * x[n] + (1 - α) * y[n-1]
    filteredTemperature = (ALPHA * currentTemperature) + ((1.0f - ALPHA) * filteredTemperature);

    // 3. ACT: Threshold monitoring (Safety Interlock)
    if (filteredTemperature > TEMP_THRESHOLD) {
        digitalWrite(ALARM_PIN, HIGH); // Turn on warning LED
    } else {
        digitalWrite(ALARM_PIN, LOW);  // Reset warning LED
    }

    // 4. OUTPUT: Telemetry output for debugging or a host PC
    // Format optimized for the Arduino IDE "Serial Plotter"
    Serial.print("Raw_Temp_C:");
    Serial.print(currentTemperature, 2);
    Serial.print(",Filtered_Temp_C:");
    Serial.println(filteredTemperature, 2);

    // 5. TIMING: Deterministic sampling rate (100Hz / every 10 milliseconds)
    delay(10);
}
```

