}

/**
 * Converts raw ADC values to Celsius.
 * Formula based on LM35 sensor: Output is 10mV per degree Celsius.
 */
float convertToCelsius(float rawAdcVal) {
    // Step 1: Convert ADC value (0-1023) to Voltage (0-5V)
    float voltage = (rawAdcVal / ADC_RESOLUTION) * REFERENCE_VOLTAGE;

    // Step 2: Convert Voltage to Celsius (LM35 output is 10mV/°C, or 0.01V/°C)
