        float rawTemp = readSensorTempCelsius();

        // 2. PROCESS: Apply Exponential Moving Average (EMA) Low-Pass Filter
        filteredValue = applyLowPassFilter(rawTemp, filteredValue);

        // 3. OUTPUT/RESPOND: Log data and trigger hardware interrupts/GPIO
        Serial.print("Raw_Temp_C:");
        Serial.print(rawTemp);
        Serial.print(",");
        Serial.print("Filtered_Temp_C:");
        Serial.println(filteredValue);

        // Threshold detection (overtemperature protection)
        if (filteredValue > TEMP_THRESHOLD) {
            digitalWrite(ALERT_LED_PIN, HIGH); // Turn on warning LED
        } else {
            digitalWrite(ALERT_LED_PIN, LOW);  // Turn off warning LED
        }
    }
}

/**
 * Reads the analog pin and converts raw ADC steps into Celsius.
 * (Assumes a 10-bit ADC, 5V reference, and a TMP36 temperature sensor)
 */
float readSensorTempCelsius() {
    int rawAdc = analogRead(SENSOR_PIN);
    float voltage = (rawAdc * 5.0) / 1023.0; // Convert 0-1023 ADC to 0.0V - 5.0V
    float temperatureC = (voltage - 0.5) * 100.0; // TMP36 sensor scaling formula
    return temperatureC;
}

/**
 * Appliess an Exponential Moving Average (EMA) filter.
 * Formula: Y[n] = (Alpha * X[n]) + ((1 - Alpha) * Y[n-1])
 */
float applyLowPassFilter(float rawValue, float previousFilteredValue) {
    return (FILTER_ALPHA * rawValue) + ((1.0 - FILTER_ALPHA) * previousFilteredValue);
}
```

