    filtered_value = initial_raw;

    Serial.println("System Initialized. Sampling started...");
}

void loop() {
    unsigned long current_time = millis();

    // Deterministic Timing Loop (Non-blocking)
    if (current_time - last_sample_time >= SAMPLE_INTERVAL_MS) {
        last_sample_time = current_time;

        // Step 1: Read Sensor Data
        float raw_voltage = read_sensor_voltage(SENSOR_PIN);

        // Step 2: Process Data (Apply Low-Pass Filter)
        filtered_value = low_pass_filter(raw_voltage, filtered_value, FILTER_ALPHA);

        // Step 3: Output/Transmit Data
