        Serial.print("Raw_V:");
        Serial.print(raw_voltage, 3);
        Serial.print(",");
        Serial.print("Filtered_V:");
        Serial.println(filtered_value, 3);
    }
}

/**
 * Reads the ADC and converts the digital value to voltage.
 * Assuming a 10-bit ADC (0-1023) and a 3.3V reference voltage.
 */
float read_sensor_voltage(int pin) {
    int raw_adc = analogRead(pin); 
    float voltage = (raw_adc / 1023.0f) * 3.3f; 
    return voltage;
}

/**
 * Exponential Moving Average (EMA) Low-Pass Filter.
 * Formula: y[n] = alpha * x[n] + (1 - alpha) * y[n-1]
 */
float low_pass_filter(float raw_input, float current_state, float alpha) {
    return (alpha * raw_input) + ((1.0f - alpha) * current_state);
}
```

