const int SENSOR_PIN = A0;             // ADC pin for the sensor
const unsigned long SAMPLE_INTERVAL_MS = 10; // 100 Hz sampling rate
const float FILTER_ALPHA = 0.1f;       // Smoothing factor (0.0 to 1.0)

