This code implements a complete, self-contained simulation of a **self-balancing robot (1D inverted pendulum)**. It demonstrates the core components of a real-time robotics controller:
1. **Deterministic Timing:** A fixed 100 Hz loop using `<chrono>` to prevent timing drift.
2. **Sensor Fusion:** A Complementary Filter fusing high-speed, drifting Gyroscope data with noisy, slow Accelerometer data.
3. **Motor Control:** A PID (Proportional-Integral-Derivative) controller calculating corrective motor outputs.
4. **Hardware Simulation:** A simple physics model showing how the motor output affects the robot's state in real-time.

### C++ Code Implementation

```cpp
#include <iostream>
#include <chrono>
#include <thread>
#include <cmath>
#include <random>
#include <iomanip>
#include <atomic>
#include <csignal>

// Global flag to cleanly exit the control loop on Ctrl+C
std::atomic<bool> keep_running(true);
void signal_handler(int signum) {
    keep_running = false;
}

// ============================================================================
// PHYSICS SIMULATION (Simulating the physical robot and hardware)
// ============================================================================
struct PhysicalRobot {
    double angle = 12.0;           // Actual physical angle (degrees)
    double angular_velocity = 0.0; // Actual physical speed (deg/s)

    // Simulates physics step: gravity pulls it down, motor torque pushes it back
    void step(double motor_effort, double dt) {
        constexpr double gravity_constant = 40.0; // Amplified for simulation speed
        constexpr double motor_strength = 2.0;

        // Gravity accelerates rotation away from 0 degrees
        double gravity_torque = sin(angle * M_PI / 180.0) * gravity_constant;
        // Motor output creates counter-torque
        double motor_torque = motor_effort * motor_strength;

        double angular_acceleration = gravity_torque + motor_torque;
        angular_velocity += angular_acceleration * dt;
        angle += angular_velocity * dt;
    }
};

// ============================================================================
// SENSOR FUSION: Complementary Filter
// ============================================================================
class ComplementaryFilter {
private:
    double alpha; // High-pass vs Low-pass weight (typically 0.95 to 0.98)
    double fused_angle;
    bool initialized;

public:
    ComplementaryFilter(double alpha_val) 
        : alpha(alpha_val), fused_angle(0.0), initialized(false) {}

    double update(double gyro_rate, double accel_angle, double dt) {
        if (!initialized) {
            fused_angle = accel_angle;
            initialized = true;
            return fused_angle;
        }
        // Fused Angle = Alpha * (Previous Angle + Gyro Integration) + (1 - Alpha) * Accelerometer
        // Gyro handles fast, dynamic changes; Accel prevents long-term drift.
        fused_angle = alpha * (fused_angle + gyro_rate * dt) + (1.0 - alpha) * accel_angle;
        return fused_angle;
    }
};

// ============================================================================
// MOTOR CONTROL: PID Controller
// ============================================================================
class PIDController {
private:
    double kp, ki, kd;
    double integral = 0.0;
    double prev_error = 0.0;
    double max_output;

public:
    PIDController(double p, double i, double d, double max_out) 
        : kp(p), ki(i), kd(d), max_output(max_out) {}

    double compute(double setpoint, double current_value, double dt) {
        double error = setpoint - current_value;

        // Proportional
        double P = kp * error;

        // Integral (with basic windup protection)
        integral += error * dt;
        double I = ki * integral;
        if (I > max_output) I = max_output;
        if (I < -max_output) I = -max_output;

        // Derivative (on measurement to avoid derivative kick)
        double D = kd * (error - prev_error) / dt;
        prev_error = error;

        double output = P + I + D;

        // Saturate output to physical limits
        if (output > max_output) output = max_output;
        if (output < -max_output) output = -max_output;

        return output;
    }
};

// ============================================================================
// MAIN REAL-TIME CONTROL LOOP
// ============================================================================
int main() {
    std::signal(SIGINT, signal_handler);

    // Instantiate hardware simulation, filter, and controller
    PhysicalRobot robot;
    ComplementaryFilter sensor_fusion(0.96); // 96% Gyro weight, 4% Accel weight
    PIDController pid(8.5, 1.5, 0.4, 100.0); // Kp, Ki, Kd, Max PWM (100%)

    // Timing configurations
    constexpr int loop_frequency_hz = 100; 
    constexpr auto loop_period = std::chrono::microseconds(1000000 / loop_frequency_hz);
    constexpr double dt = 1.0 / loop_frequency_hz; // 0.01 seconds

    // Setup noise generator for realistic sensor simulation
    std::default_random_engine generator;
    std::normal_distribution<double> accel_noise(0.0, 1.5); // Accel is noisy
    std::normal_distribution<double> gyro_drift(0.1, 0.05); // Gyro drifts over time

    // Get current time point
    auto next_loop_time = std::chrono::steady_clock::now();

    std::cout << std::fixed << std::setprecision(2);
    std::cout << "Starting real-time control loop at " << loop_frequency_hz << "Hz...\n";
    std::cout << "Target Angle: 0.0° (Balancing vertical)\n\n";
    std::cout << "Time(s) | Real Ang | Accel Ang | Gyro Rate | Fused Ang | Motor PWM\n";
    std::cout << "------------------------------------------------------------------\n";

    double elapsed_time = 0.0;

    while (keep_running) {
        // Calculate the next wake-up time before doing work to maintain determinism
        next_loop_time += loop_period;

        // --------------------------------------------------------------------
        // 1. READ SENSORS (Simulated Hardware Read via SPI/I2C)
        // --------------------------------------------------------------------
        // Gyro measures velocity, but has systemic bias (drift)
        double raw_gyro_rate = robot.angular_velocity + gyro_drift(generator);
        // Accelerometer measures gravity vector directly, but is very noisy
        double raw_accel_angle = robot.angle + accel_noise(generator);

        // --------------------------------------------------------------------
        // 2. SENSOR FUSION (State Estimation)
        // --------------------------------------------------------------------
        double fused_angle = sensor_fusion.update(raw_gyro_rate, raw_accel_angle, dt);

        // --------------------------------------------------------------------
        // 3. CONTROL LAW (PID computation)
        // --------------------------------------------------------------------
        double target_angle = 0.0; // Vertically balanced
        // If fused_angle is positive, we are falling forward. 
        // PID output will be negative (motor drives forward to catch the fall)
        double motor_effort = pid.compute(target_angle, fused_angle, dt);

        // --------------------------------------------------------------------
        // 4. ACTUATION (Write PWM value to physical motor drivers)
        // --------------------------------------------------------------------
        // physical_write_to_h_bridge(motor_effort); 
        robot.step(motor_effort, dt); // Step the simulated physical world

        // --------------------------------------------------------------------
        // REAL-TIME LOGGING (Note: Keep this fast! Don't use heavy I/O in RTOS production)
        // --------------------------------------------------------------------
        static int log_divider = 0;
        if (log_divider++ % 10 == 0) { // Log at 10Hz to prevent terminal flooding
            std::cout << std::setw(7) << elapsed_time << " | "
                      << std::setw(8) << robot.angle << " | "
                      << std::setw(9) << raw_accel_angle << " | "
                      << std::setw(9) << raw_gyro_rate << " | "
                      << std::setw(9) << fused_angle << " | "
                      << std::setw(8) << motor_effort << "%\n";
        }

        elapsed_time += dt;

        // --------------------------------------------------------------------
        // 5. DETERMINISTIC SLEEP (Yields CPU, wakes up precisely at next frame)
        // --------------------------------------------------------------------
        std::this_thread::sleep_until(next_loop_time);
    }

    std::cout << "\nLoop stopped safely. Disarming motor actuators.\n";
    return 0;
}
```

### Key Real-Time Design Patterns Used:

1. **`std::chrono::steady_clock`**: Unlike `system_clock` (which can change if the system time is updated via NTP), `steady_clock` is monotonic and acts as a high-resolution hardware tick timer.
2. **`sleep_until(next_loop_time)`**: Rather than sleeping for a generic `10ms`, we calculate the absolute end-time of the frame beforehand. This guarantees that even if our calculation code takes 2ms or 4ms, the loop rate remains precisely 100 Hz.
3. **Sensor Fusion Balance**: If you look at the logs, the raw Accelerometer reads (`Accel Ang`) jump around erratically due to noise. The `Fused Ang` remains incredibly smooth and accurately tracks the `Real Ang`, demonstrating how the complementary filter combines the best of both sensors.
4. **No Dynamic Memory Allocation**: There are no `new` or `malloc` calls inside the `while` loop. Memory allocation triggers system calls, which can cause unpredictable latency spikes (violating real-time constraints).

