                      << " | Fused Angle: " << fused_angle 
                      << " | Target: " << TARGET_ANGLE << "\n";
        }

        // --- REAL-TIME SCHEDULING ---
        // Sleep until the exact time the next loop should start.
        // This mitigates execution time variance (jitter).
        std::this_thread::sleep_until(next_loop_time);
    }

    return 0;
}
