#include <random>

// ==========================================
// 1. PID CONTROLLER (With Anti-Windup)
// ==========================================
class PIDController {
public:
    PIDController(double kp, double ki, double kd, double max_output)
        : kp_(kp), ki_(ki), kd_(kd), max_output_(max_output), 
          integral_(0.0), prev_error_(0.0) {}

    double calculate(double setpoint, double measurement, double dt) {
        if (dt <= 0.0) return 0.0;

        double error = setpoint - measurement;

        // Proportional term
        double P = kp_ * error;

        // Integral term (with trapezoidal integration)
        integral_ += error * dt;
        double I = ki_ * integral_;

        // Derivative term
        double derivative = (error - prev_error_) / dt;
        double D = kd_ * derivative;

        double output = P + I + D;

        // Anti-windup clamping
        if (output > max_output_) {
            output = max_output_;
            integral_ -= error * dt; // Undo integration if saturated
        } else if (output < -max_output_) {
            output = -max_output_;
            integral_ -= error * dt;
        }

        prev_error_ = error;
        return output;
    }

    void reset() {
        integral_ = 0.0;
        prev_error_ = 0.0;
    }

private:
    double kp_, ki_, kd_;
    double max_output_;
    double integral_;
    double prev_error_;
};

// ==========================================
// 2. SENSOR FUSION (Complementary Filter)
// ==========================================
class ComplementaryFilter {
public:
    // alpha closer to 1 trusts the Gyroscope (low-pass filter on Accel, high-pass on Gyro)
    ComplementaryFilter(double alpha) : alpha_(alpha), angle_(0.0) {}

    // Fuses Gyro rate (rad/s) and Accel tilt (rad)
    double update(double gyro_rate, double accel_angle, double dt) {
        angle_ = alpha_ * (angle_ + gyro_rate * dt) + (1.0 - alpha_) * accel_angle;
        return angle_;
    }

private:
    double alpha_;
    double angle_;
};

// ==========================================
// 3. HARDWARE INTERFACE (Mocked)
