        double accel_angle = simulated_pitch_ + noise(gen);
        double gyro_rate = (simulated_pitch_ - last_pitch_) / 0.01 + noise(gen);

        last_pitch_ = simulated_pitch_;

        // In a real system, you would read SPI/I2C registers here
        return IMUData{gyro_rate, cos(simulated_pitch_) * 9.81, sin(simulated_pitch_) * 9.81};
    }

    void writeMotors(double effort) {
        // In a real system, you would write to a PWM register or CAN bus
        // Simulating the physical response of the motor pushing the robot back up
        simulated_pitch_ -= effort * 0.05; 

        // Add random gravity disturbance
        simulated_pitch_ += 0.005; 
    }

private:
    std::random_device rd;
    std::mt19937 gen;
    std::normal_distribution<> noise;
    double simulated_pitch_;
    double last_pitch_ = 0.1;
};

