    constexpr std::chrono::milliseconds loop_duration(10);
    constexpr double dt = 0.01; // dt in seconds

    RobotHardware robot;
    ComplementaryFilter filter(0.98); // 98% Gyro, 2% Accel
    PIDController pid(15.0, 0.5, 1.2, 100.0); // Kp, Ki, Kd, Max PWM/Effort

    double target_angle = 0.0; // Desired pitch (0.0 rad = perfectly upright)

    // Set high-priority scheduling for the thread if operating on RTOS/Real-time Linux
    // (Requires root privileges on Linux: e.g., pthread_setschedparam)
    std::cout << "Starting real-time control loop at 100Hz..." << std::endl;

    auto next_wakeup = std::chrono::steady_clock::now();
    int iteration = 0;

    while (iteration < 200) { // Run for 2 seconds (200 frames)
        next_wakeup += loop_duration;

        // 1. Read Sensors (Hardware Access)
        IMUData imu = robot.readIMU();

        // Calculate Accel Angle: theta = atan2(accel_x, accel_z)
        double accel_angle = std::atan2(imu.accel_x, imu.accel_z);

        // 2. Sensor Fusion (Deterministic mathematical estimation)
        double fused_pitch = filter.update(imu.gyro_y, accel_angle, dt);

        // 3. Compute Control Action (PID)
        double motor_effort = pid.calculate(target_angle, fused_pitch, dt);

        // 4. Actuate (Write to Motors)
        robot.writeMotors(motor_effort);

        // Throttled logging (Avoid console I/O every loop, as I/O blocks and destroys real-time execution)
        if (iteration % 10 == 0) {
            std::cout << "Time: " << iteration * dt << "s | "
                      << "Raw Accel Ang: " << accel_angle << " rad | "
                      << "Fused Pitch: " << fused_pitch << " rad | "
                      << "Motor Command: " << motor_effort << "%" << std::endl;
        }

        iteration++;

        // 5. Precise Real-Time Sleep
        // sleep_until guarantees we wake up at exact boundaries, preventing drift from processing time.
        std::this_thread::sleep_until(next_wakeup);
    }

    std::cout << "Control loop finished smoothly." << std::endl;
    return 0;
}
