// 1. PID Controller Class
// ==========================================
class PIDController {
private:
    double kp_, ki_, kd_;
    double prev_error_ = 0.0;
    double integral_ = 0.0;
    double max_integral_ = 10.0; // Prevent integral windup

public:
    PIDController(double kp, double ki, double kd) : kp_(kp), ki_(ki), kd_(kd) {}

    double calculate(double setpoint, double measurement, double dt) {
        double error = setpoint - measurement;

        // Proportional term
        double p_out = kp_ * error;

        // Integral term (with windup protection)
        integral_ += error * dt;
        integral_ = std::clamp(integral_, -max_integral_, max_integral_);
        double i_out = ki_ * integral_;

        // Derivative term
        double derivative = (error - prev_error_) / dt;
        double d_out = kd_ * derivative;

        prev_error_ = error;

        return p_out + i_out + d_out;
    }
};

