        constexpr double gravity_constant = 9.81;
        constexpr double inertia = 0.1;

        double gravity_torque = gravity_constant * std::sin(angle * M_PI / 180.0);
        double net_torque = motor_torque - gravity_torque;

        double angular_acceleration = net_torque / inertia;
        angular_velocity += angular_acceleration * DT;
        angle += angular_velocity * DT;

        // Add a bit of random wind disturbance
        static std::default_random_engine generator;
        static std::normal_distribution<double> noise(0.0, 0.5);
        angle += noise(generator) * DT;
    }
};

// --- REAL-TIME SENSOR FUSION ---
class ComplementaryFilter {
private:
    double fused_angle = 0.0;
    const double alpha = 0.98; // Trust factor: 98% Gyro (short-term), 2% Accel (long-term)

public:
    explicit ComplementaryFilter(double initial_angle) : fused_angle(initial_angle) {}

    // Fuses high-frequency gyro rate with stable accel angle
    double update(double accel_angle, double gyro_rate) {
        fused_angle = alpha * (fused_angle + gyro_rate * DT) + (1.0 - alpha) * accel_angle;
        return fused_angle;
    }
};

// --- MOTOR CONTROLLER (PD) ---
