```cpp
#include <iostream>
#include <chrono>
#include <thread>
#include <random>
#include <cmath>
#include <iomanip>

// ==========================================
// 1. SENSOR FUSION: Complementary Filter
// ==========================================
class ComplementaryFilter {
private:
    double alpha; // Filter coefficient (weight given to gyro vs accel)
    double fused_angle = 0.0;

public:
    explicit ComplementaryFilter(double filter_coefficient) : alpha(filter_coefficient) {}

    double update(double accel_angle, double gyro_rate, double dt) {
        // High-pass filter on Gyro (integrating velocity) + Low-pass filter on Accel
        fused_angle = alpha * (fused_angle + gyro_rate * dt) + (1.0 - alpha) * accel_angle;
        return fused_angle;
    }
};

// ==========================================
// 2. MOTOR CONTROL: PID Controller
// ==========================================
class PIDController {
private:
    double kp, ki, kd;
    double integral = 0.0;
    double prev_error = 0.0;
    double limit; // Max motor control output (e.g., PWM limit)

public:
    PIDController(double p, double i, double d, double output_limit)
        : kp(p), ki(i), kd(d), limit(output_limit) {}

    double calculate(double setpoint, double process_value, double dt) {
        double error = setpoint - process_value;

        // Proportional term
        double p_out = kp * error;

        // Integral term (with anti-windup clamping)
        integral += error * dt;
        double i_out = ki * integral;
        if (i_out > limit) i_out = limit;
        if (i_out < -limit) i_out = -limit;

        // Derivative term
        double derivative = (error - prev_error) / dt;
        double d_out = kd * derivative;

        prev_error = error;

        // Total output clamped to limits
        double output = p_out + i_out + d_out;
        if (output > limit) return limit;
        if (output < -limit) return -limit;
        return output;
    }
};

// ==========================================
// 3. HARDWARE EMULATION (Physics & Sensors)
// ==========================================
struct PhysicsPlant {
    double angle = 15.0;      // Robot starts tilted at 15 degrees
    double velocity = 0.0;    // Angular velocity

    // Simulates the physical effect of torque (motor) and gravity on the robot
    void step(double motor_torque, double dt) {
        constexpr double gravity = 9.81;
        constexpr double damping = 0.1;

        // Simplified physical model: angular acceleration
        double acceleration = (motor_torque * 2.0) + (gravity * std::sin(angle * M_PI / 180.0)) - (damping * velocity);
        velocity += acceleration * dt;
        angle += velocity * dt;
    }
};

// Generates simulated sensor readings with Gaussian noise
struct HardwareSensors {
    std::default_random_engine generator;
    std::normal_distribution<double> accel_noise{0.0, 1.5}; // Accel is noisy
    std::normal_distribution<double> gyro_noise{0.0, 0.1};  // Gyro has low noise but drifts

    double read_accelerometer_angle(double true_angle) {
        return true_angle + accel_noise(generator);
    }

    double read_gyroscope_rate(double true_velocity) {
        return true_velocity + gyro_noise(generator);
    }
};

void write_motor_pwm(double command) {
    // In a real system, this writes to register-mapped I/O, SPI, or CAN Bus.
    // Here we just print the command.
    std::cout << " [Motor PWM: " << std::setw(6) << std::fixed << std::setprecision(1) << command << "%]";
}

// ==========================================
// 4. REAL-TIME CONTROL LOOP
// ==========================================
int main() {
    // Target state: stand perfectly upright (0 degrees)
    const double target_angle = 0.0; 

    // Instantiate components
    ComplementaryFilter filter(0.98); // 98% Gyro trust, 2% Accel trust
    PIDController pid(15.0, 0.5, 3.0, 100.0); // Kp, Ki, Kd, Max PWM (100%)
    PhysicsPlant robot;
    HardwareSensors sensors;

    // Time step configuration (100 Hz frequency = 10ms loop time)
    constexpr std::chrono::milliseconds loop_interval(10);
    constexpr double dt = 0.01; // dt in seconds

    std::cout << "Starting real-time control loop at 100Hz...\n";
    std::cout << "Target: " << target_angle << " degrees. Initial Angle: " << robot.angle << " degrees.\n\n";

    auto next_loop_time = std::chrono::steady_clock::now();

    // Run control loop for 150 iterations (1.5 seconds)
    for (int i = 0; i < 150; ++i) {
        next_loop_time += loop_interval;

        // --- 1. SENSOR READ (I/O) ---
        double raw_accel = sensors.read_accelerometer_angle(robot.angle);
        double raw_gyro  = sensors.read_gyroscope_rate(robot.velocity);

        // --- 2. SENSOR FUSION ---
        double fused_angle = filter.update(raw_accel, raw_gyro, dt);

        // --- 3. CONTROLLER CALCULATIONS ---
        double motor_command = pid.calculate(target_angle, fused_angle, dt);

        // --- 4. ACTUATION (Write to Hardware) ---
        write_motor_pwm(motor_command);

        // --- 5. PLANT PHYSICS UPDATE (Emulation only) ---
        robot.step(motor_command / 100.0, dt); // Scale 100% command to torque units

        // Log telemetry
        std::cout << " | True Angle: " << std::setw(5) << std::fixed << std::setprecision(2) << robot.angle 
                  << " | Fused Angle: " << std::setw(5) << fused_angle
                  << " | Raw Accel: " << std::setw(5) << raw_accel << "\n";

        // --- 6. REAL-TIME DETERMINISTIC SLEEP ---
        // Sleep until the exact time the next loop is scheduled.
        // This mitigates execution jitter caused by varying CPU workloads.
        std::this_thread::sleep_until(next_loop_time);
    }

    std::cout << "\nControl loop finished. Robot angle stabilized near 0.0 degrees.\n";
    return 0;
}
