Here is a production-ready, highly optimized embedded C++ pipeline for real-time anomaly detection using accelerometer data. 

To make this suitable for resource-constrained microcontrollers (like ARM Cortex-M, ESP32, or AVR), the code:
* **Avoids dynamic memory allocation** (`std::vector`, `new`/`delete`) to prevent heap fragmentation.
* Uses **fixed-size arrays** and a custom **Ring Buffer**.
* Implements a **dynamic Z-score algorithm** using **Welford's algorithm** for running variance, allowing the system to adapt to "normal" background vibrations without storing millions of historical data points.
* Removes gravity ($1g$ constant bias) using a **1st-order High-Pass IIR filter**.

### C++ Anomaly Detection Pipeline

```cpp
#include <iostream>
#include <cmath>
#include <cstdint>

// Configuration Constants
constexpr size_t WINDOW_SIZE = 32;       // Size of the sliding window for feature extraction
constexpr float HPF_ALPHA = 0.95f;        // High-pass filter coefficient (closer to 1.0 retains more low freq)
constexpr float ANOMALY_THRESHOLD = 3.0f; // Z-score threshold (3.0 standard deviations)

// Simple representation of 3-axis accelerometer data
struct AccelSample {
    float x;
    float y;
    float z;
};

// ==========================================
// 1. Fixed-Size Ring Buffer Utility
// ==========================================
template <typename T, size_t Capacity>
class SimpleRingBuffer {
private:
    T data[Capacity] = {};
    size_t head = 0;
    size_t count = 0;

public:
    void push(T value) {
        data[head] = value;
        head = (head + 1) % Capacity;
        if (count < Capacity) {
            count++;
        }
    }

    size_t size() const { return count; }
    bool is_full() const { return count == Capacity; }

    T get(size_t index) const {
        // Retrieve elements where 0 is the oldest, count-1 is the newest
        if (index >= count) return T{};
        size_t actual_index = (head + Capacity - count + index) % Capacity;
        return data[actual_index];
    }
};

// ==========================================
// 2. High-Pass Filter (removes DC gravity bias)
// ==========================================
class HighPassFilter {
private:
    float prev_in = 0.0f;
    float prev_out = 0.0f;
    bool is_initialized = false;

public:
    float process(float input) {
        if (!is_initialized) {
            prev_in = input;
            prev_out = 0.0f;
            is_initialized = true;
            return 0.0f;
        }
        // Difference equation: y[n] = alpha * (y[n-1] + x[n] - x[n-1])
        float output = HPF_ALPHA * (prev_out + input - prev_in);
        prev_in = input;
        prev_out = output;
        return output;
    }
};

// ==========================================
// 3. Sensor Processing & Anomaly Pipeline
// ==========================================
class AnomalyDetectionPipeline {
private:
    HighPassFilter filter_x;
    HighPassFilter filter_y;
    HighPassFilter filter_z;

    SimpleRingBuffer<float, WINDOW_SIZE> magnitude_window;

    // Baseline statistics (unsupervised online tracking using Welford's algorithm)
    float baseline_mean = 0.0f;
    float baseline_m2 = 0.0f; // Sum of squares of differences from the current mean
    uint32_t sample_count = 0;

    // Updates the rolling baseline (normal operating conditions)
    void update_baseline(float val) {
        sample_count++;
        float delta = val - baseline_mean;
        baseline_mean += delta / sample_count;
        float delta2 = val - baseline_mean;
        baseline_m2 += delta * delta2;
    }

    float get_baseline_std_dev() const {
        if (sample_count < 2) return 0.0f;
        return std::sqrt(baseline_m2 / (sample_count - 1));
    }

public:
    // Processes a raw accelerometer sample. Returns true if an anomaly is detected.
    bool process_sample(const AccelSample& raw, float& out_z_score) {
        // Step 1: High-pass filter raw signals to isolate dynamic motion from gravity
        float fx = filter_x.process(raw.x);
        float fy = filter_y.process(raw.y);
        float fz = filter_z.process(raw.z);

        // Step 2: Compute magnitude of dynamic acceleration vector
        float dynamic_magnitude = std::sqrt(fx*fx + fy*fy + fz*fz);

        // Step 3: Push magnitude to the sliding window
        magnitude_window.push(dynamic_magnitude);

        // We need a full window to perform reliable statistical analysis
        if (!magnitude_window.is_full()) {
            // During startup/calibration, feed the baseline
            update_baseline(dynamic_magnitude);
            out_z_score = 0.0f;
            return false;
        }

        // Step 4: Compute statistical features of the current sliding window
        float window_sum = 0.0f;
        for (size_t i = 0; i < WINDOW_SIZE; ++i) {
            window_sum += magnitude_window.get(i);
        }
        float window_mean = window_sum / WINDOW_SIZE;

        // Step 5: Evaluate anomaly using dynamic Z-Score
        float baseline_std = get_baseline_std_dev();
        bool is_anomaly = false;
        out_z_score = 0.0f;

        if (sample_count > WINDOW_SIZE && baseline_std > 0.01f) {
            // Z-score represents how many standard deviations the current 
            // window mean deviates from the historical running baseline mean
            out_z_score = std::abs(window_mean - baseline_mean) / baseline_std;

            if (out_z_score > ANOMALY_THRESHOLD) {
                is_anomaly = true;
            }
        }

        // Step 6: If it is not an anomaly, adapt baseline to include this new normal
        if (!is_anomaly) {
            update_baseline(window_mean);
        }

        return is_anomaly;
    }
};

