constexpr float ANOMALY_K = 3.0f;    // Threshold multiplier (Z-score). 3.0 = 99.7% confidence limit.

// Fixed-size Circular Buffer to avoid dynamic allocation on MCUs
class CircularBuffer {
private:
    float buffer[WINDOW_SIZE] = {0.0f};
    size_t head = 0;
    size_t count = 0;
    double sum = 0.0;
    double sq_sum = 0.0; // Keep track of sum of squares for fast StdDev calculation

public:
    void push(float value) {
        if (count == WINDOW_SIZE) {
