            float oldest = buffer[head];
            sum -= oldest;
            sq_sum -= (oldest * oldest);

            // Overwrite oldest
            buffer[head] = value;
            head = (head + 1) % WINDOW_SIZE;
        } else {
            // Buffer not yet full
            buffer[(head + count) % WINDOW_SIZE] = value;
            count++;
        }

        // Add new value to running statistics
        sum += value;
        sq_sum += (value * value);
    }

    bool isFull() const {
        return count == WINDOW_SIZE;
    }

    // Computes Mean and Standard Deviation in O(1) time
    void getStats(float& mean, float& stdDev) const {
        if (count == 0) {
            mean = 0.0f;
            stdDev = 0.0f;
            return;
        }
        mean = static_cast<float>(sum / count);
        double variance = (sq_sum / count) - (mean * mean);

        // Prevent negative variance due to floating-point precision issues
        stdDev = static_cast<float>(std::sqrt(variance > 0.0 ? variance : 0.0));
    }
};

