    CircularBuffer history;
    float ema_gravity = 0.0f;
    bool is_initialized = false;

    // High-pass filter to remove gravity (constant 1g)
    float highPassFilter(float raw_magnitude) {
        if (!is_initialized) {
            ema_gravity = raw_magnitude;
            is_initialized = true;
            return 0.0f;
        }
        // Exponential Moving Average (EMA) low-pass
        ema_gravity = (FILTER_ALPHA * raw_magnitude) + ((1.0f - FILTER_ALPHA) * ema_gravity);

        // Subtract gravity component to get dynamic acceleration (high-pass)
        return raw_magnitude - ema_gravity;
    }

public:
    // Process a new IMU sample. Returns true if an anomaly is detected.
    bool processSample(float ax, float ay, float az) {
        // Step 1: Calculate vector magnitude (orientation-invariant)
        float raw_magnitude = std::sqrt(ax*ax + ay*ay + az*az);

        // Step 2: Remove gravity/DC bias
        float dynamic_accel = std::abs(highPassFilter(raw_magnitude));

        // Step 3: Check for Anomaly if our window is populated
        bool is_anomaly = false;
        if (history.isFull()) {
            float mean = 0.0f;
            float std_dev = 0.0f;
            history.getStats(mean, std_dev);

            // Minimum variance guard: prevents division by zero / hypersensitivity in silent environments
            if (std_dev < 0.05f) { 
                std_dev = 0.05f; 
            }

            // Calculate Z-Score
            float z_score = (dynamic_accel - mean) / std_dev;
            if (z_score > ANOMALY_K) {
                is_anomaly = true;
            }
        }

        // Step 4: Update sliding window
        history.push(dynamic_accel);

        return is_anomaly;
    }
};

