#include <stdint.h>
#include <math.h>

// --- Configuration Constants ---
#define WINDOW_SIZE          32      // Size of sliding window (approx. 0.3 seconds at 100Hz)
#define CALIBRATION_SAMPLES  200     // Number of samples to establish normal baseline
#define ANOMALY_THRESHOLD_Z  4.0f    // Z-score threshold (e.g., 4 standard deviations)
#define EMA_ALPHA            0.2f    // Filter smoothing factor (0.0 < alpha <= 1.0)
#define GRAVITY              9.81f   // Nominal gravity (m/s^2)

// --- Simple Fixed-Size Circular Buffer ---
class CircularBuffer {
private:
    float data[WINDOW_SIZE];
    uint16_t head = 0;
    uint16_t count = 0;

public:
    void push(float value) {
        data[head] = value;
        head = (head + 1) % WINDOW_SIZE;
        if (count < WINDOW_SIZE) {
            count++;
        }
    }

    bool is_full() const {
        return count == WINDOW_SIZE;
    }

    // Calculates mean and standard deviation of the window
    void get_stats(float& mean, float& std_dev) const {
        if (count == 0) {
            mean = 0.0f;
            std_dev = 0.0f;
            return;
        }

        // Calculate Mean
        float sum = 0.0f;
        for (uint16_t i = 0; i < count; i++) {
            sum += data[i];
        }
        mean = sum / count;

        // Calculate Variance / Std Dev
        float variance_sum = 0.0f;
        for (uint16_t i = 0; i < count; i++) {
            float diff = data[i] - mean;
            variance_sum += diff * diff;
        }
        std_dev = sqrtf(variance_sum / count);
    }
};

// --- Pipeline State Machine ---
enum PipelineState {
    STATE_CALIBRATING,
    STATE_MONITORING
};

// --- Anomaly Detection Pipeline ---
class AnomalyDetectionPipeline {
private:
    CircularBuffer window;
    PipelineState state = STATE_CALIBRATING;

    // Filtering State
    float filtered_magnitude = 0.0f;
    bool is_first_sample = true;

    // Calibration Variables
    uint32_t calibration_count = 0;
    float calibration_sum_std_dev = 0.0f;

    // Learned Baseline Thresholds
    float baseline_mean_std_dev = 0.0f;

public:
    AnomalyDetectionPipeline() {}

    // Process a single 3-axis sample. Returns true if an anomaly is detected.
    bool process_sample(float ax, float ay, float az) {
        // Step 1: Calculate vector magnitude (makes algorithm rotation-invariant)
        float raw_magnitude = sqrtf(ax * ax + ay * ay + az * az);

        // Remove static gravity vector (assuming sensor is mostly stationary during calibration)
        float dynamic_acceleration = fabs(raw_magnitude - GRAVITY);

        // Step 2: Exponential Moving Average (EMA) Low-Pass Filter
        if (is_first_sample) {
            filtered_magnitude = dynamic_acceleration;
            is_first_sample = false;
        } else {
            filtered_magnitude = (EMA_ALPHA * dynamic_acceleration) + ((1.0f - EMA_ALPHA) * filtered_magnitude);
        }

        // Step 3: Slide into window buffer
        window.push(filtered_magnitude);

        // We need a full window to perform accurate statistical analysis
        if (!window.is_full()) {
            return false; 
        }

        // Step 4: Extract current statistical features
        float current_mean = 0.0f;
        float current_std_dev = 0.0f;
        window.get_stats(current_mean, current_std_dev);

        // Step 5: State Machine logic
        switch (state) {
            case STATE_CALIBRATING:
                calibration_sum_std_dev += current_std_dev;
                calibration_count++;

                if (calibration_count >= CALIBRATION_SAMPLES) {
                    // Calculate average normal vibration (standard deviation)
                    baseline_mean_std_dev = calibration_sum_std_dev / CALIBRATION_SAMPLES;
                    state = STATE_MONITORING;
                    // Trigger some hardware indicator (e.g., turn off yellow LED, turn on green LED)
                }
                return false;

            case STATE_MONITORING:
                // Step 6: Classification (Anomaly detection)
                // If the current vibration level is significantly higher than baseline, flag anomaly
                if (current_std_dev > (baseline_mean_std_dev * ANOMALY_THRESHOLD_Z)) {
                    return true; // Anomaly detected!
                }
                break;
        }

        return false;
    }

    PipelineState get_state() const { return state; }
    float get_baseline() const { return baseline_mean_std_dev; }
};

