#include <cmath>
#include <cstdint>

// Fixed-size Circular Buffer to avoid dynamic memory allocation on embedded systems
template <typename T, size_t MaxSize>
class CircularBuffer {
private:
    T buffer[MaxSize];
    size_t head = 0;
    size_t tail = 0;
    size_t count = 0;

public:
    void push(T item) {
        buffer[head] = item;
        head = (head + 1) % MaxSize;
        if (count < MaxSize) {
            count++;
        } else {
            tail = (tail + 1) % MaxSize; // Overwrite oldest data
        }
    }

    size_t size() const { return count; }

    T get(size_index_t index) const {
        return buffer[(tail + index) % MaxSize];
    }

    void clear() {
        head = 0;
        tail = 0;
        count = 0;
    }
};

// Struct to represent raw accelerometer reading
struct AccelData {
    float x;
    float y;
    float z;
};

// The Anomaly Detection Pipeline Class
class AnomalyDetectionPipeline {
private:
    static constexpr size_t WINDOW_SIZE = 50; // History window (e.g., 50 samples @ 50Hz = 1 second)
    static constexpr float Z_SCORE_THRESHOLD = 3.0f; // Anomaly threshold (standard deviations)
    static constexpr float MIN_STD_DEV = 0.05f;      // Prevents division by zero/false alarms when static

    CircularBuffer<float, WINDOW_SIZE> magnitudeHistory;

    // Helper: Compute 3D vector magnitude
    float computeMagnitude(const AccelData& data) {
        return std::sqrt(data.x * data.x + data.y * data.y + data.z * data.z);
    }

public:
    // Processes a single accelerometer sample and returns true if an anomaly is detected
    bool processSample(const AccelData& rawData, float& outMagnitude, float& outZScore) {
        // Stage 1 & 2: Data Acquisition & Preprocessing (Magnitude calculation)
        float magnitude = computeMagnitude(rawData);
        outMagnitude = magnitude;

        // If we don't have enough history, just populate the buffer and return false
        if (magnitudeHistory.size() < WINDOW_SIZE) {
            magnitudeHistory.push(magnitude);
            outZScore = 0.0f;
            return false;
        }

        // Stage 3: Feature Extraction (Calculate Mean and Standard Deviation of historical window)
        float sum = 0.0f;
        for (size_t i = 0; i < magnitudeHistory.size(); ++i) {
            sum += magnitudeHistory.get(i);
        }
        float mean = sum / magnitudeHistory.size();

        float varianceSum = 0.0f;
        for (size_t i = 0; i < magnitudeHistory.size(); ++i) {
            float diff = magnitudeHistory.get(i) - mean;
            varianceSum += diff * diff;
        }
        float variance = varianceSum / magnitudeHistory.size();
        float stdDev = std::sqrt(variance);

        // Ensure stdDev is not too close to zero to avoid noise-triggered false positives when still
        if (stdDev < MIN_STD_DEV) {
            stdDev = MIN_STD_DEV;
        }

        // Stage 4: Classification (Calculate Z-Score for the current sample)
        float zScore = std::abs(magnitude - mean) / stdDev;
        outZScore = zScore;

        // Slide the window forward
        magnitudeHistory.push(magnitude);

        // Anomaly Detection decision
        return (zScore > Z_SCORE_THRESHOLD);
    }
};

