#include <iostream>
#include <cmath>
#include <cstdint>
#include <array>

// Configuration Constants
constexpr size_t WINDOW_SIZE = 50;       // 1 second of data at 50Hz
constexpr float LPF_ALPHA = 0.2f;        // Low-pass filter coefficient (0.0 to 1.0)
constexpr float ANOMALY_THRESHOLD = 3.0f; // Z-Score threshold (3 sigma)
constexpr float MIN_STD_DEV = 0.05f;     // Prevents division by zero in dead-still environments

// Structure to hold raw 3-axis accelerometer data
struct AccelData {
    float x;
    float y;
    float z;
};

// Simple Fixed-Size Circular Buffer for Embedded Systems
template <typename T, size_t N>
class CircularBuffer {
private:
    std::array<T, N> buffer{};
    size_t head = 0;
    size_t count = 0;

public:
    void push(T value) {
        buffer[head] = value;
        head = (head + 1) % N;
        if (count < N) {
            count++;
        }
    }

    size_t size() const { return count; }
    bool is_full() const { return count == N; }

    // Access elements from oldest (0) to newest (N-1)
    T operator[](size_t index) const {
        if (index >= count) return T{};
        size_t actual_index = (head - count + index + N) % N;
        return buffer[actual_index];
    }
};

// The Sensor Processing Pipeline Class
class AnomalyDetectionPipeline {
private:
    CircularBuffer<float, WINDOW_SIZE> window;
    float filtered_magnitude = 1.0f; // Initialized to 1G (gravity)

    // Stage 1: Calculate vector magnitude (makes the algorithm orientation-invariant)
    float calculate_magnitude(const AccelData& raw) {
        return std::sqrt(raw.x * raw.x + raw.y * raw.y + raw.z * raw.z);
    }

    // Stage 2: Exponential Moving Average (EMA) Low-Pass Filter
    float low_pass_filter(float raw_mag) {
        filtered_magnitude = (LPF_ALPHA * raw_mag) + ((1.0f - LPF_ALPHA) * filtered_magnitude);
        return filtered_magnitude;
    }

public:
    // Processes a single sensor sample and returns true if an anomaly is detected
    bool process_sample(const AccelData& sample, float& out_z_score) {
        // 1. Convert 3D vector to 1D scalar magnitude
        float mag = calculate_magnitude(sample);

        // 2. Filter out high-frequency noise
        float filtered_mag = low_pass_filter(mag);

        // 3. Add to rolling history window
        window.push(filtered_mag);

        // We need a full window before we can reliably detect anomalies
        if (!window.is_full()) {
            out_z_score = 0.0f;
            return false;
        }

        // 4. Calculate Mean of the window
        float sum = 0.0f;
        for (size_t i = 0; i < WINDOW_SIZE; ++i) {
            sum += window[i];
        }
        float mean = sum / WINDOW_SIZE;

        // 5. Calculate Standard Deviation
        float variance_sum = 0.0f;
        for (size_t i = 0; i < WINDOW_SIZE; ++i) {
            float diff = window[i] - mean;
            variance_sum += diff * diff;
        }
        float std_dev = std::sqrt(variance_sum / WINDOW_SIZE);

        // Enforce a minimum standard deviation to prevent division by zero/noise amplification
        if (std_dev < MIN_STD_DEV) {
            std_dev = MIN_STD_DEV;
        }

        // 6. Calculate Z-Score for the LATEST sample
        // (How many standard deviations is the current sample from the recent mean)
        out_z_score = std::abs(filtered_mag - mean) / std_dev;

        // 7. Decision
        return (out_z_score > ANOMALY_THRESHOLD);
    }
};

