public:
    explicit LpfFilter(float smoothingFactor) 
        : alpha(smoothingFactor), prevValue(0.0f), isInitialized(false) {}

    float update(float input) {
        if (!isInitialized) {
            prevValue = input;
            isInitialized = true;
            return input;
        }
        // Exponential Moving Average (EMA) Formula
        float filtered = (alpha * input) + ((1.0f - alpha) * prevValue);
        prevValue = filtered;
        return filtered;
    }
};

// ==========================================
// STAGE 2: ANOMALY DETECTION
// ==========================================
class ZScoreAnomalyDetector {
private:
    const uint32_t calibrationSamples;
    const float thresholdZ; // Number of standard deviations to trigger anomaly

    // Welford's algorithm variables for running mean and variance
    uint32_t count;
    float mean;
    float M2; // Sum of squares of differences from the current mean

public:
    ZScoreAnomalyDetector(uint32_t calibrationWindow, float zThreshold)
        : calibrationSamples(calibrationWindow), thresholdZ(zThreshold), 
          count(0), mean(0.0f), M2(0.0f) {}

    // Processes a new magnitude reading and returns true if an anomaly is detected
    bool update(float magnitude) {
        count++;

        // 1. Calculate running statistics using Welford's algorithm
        float delta = magnitude - mean;
        mean += delta / static_cast<float>(count);
        float delta2 = magnitude - mean;
        M2 += delta * delta2;

        // Warm-up/calibration phase: do not flag anomalies
        if (count < calibrationSamples) {
            return false; 
        }

        // 2. Compute standard deviation
        float variance = M2 / static_cast<float>(count - 1);
        float stdDev = std::sqrt(variance);

        // Prevent division by zero/extremely low noise variance issues
        if (stdDev < 0.001f) {
            return false;
        }

        // 3. Compute Z-Score
        float zScore = std::fabs(magnitude - mean) / stdDev;

        // If Z-Score exceeds threshold, we have an anomaly
        return (zScore > thresholdZ);
    }

    float getMean() const { return mean; }
};

// ==========================================
// PIPELINE MANAGER
// ==========================================
class SensorProcessingPipeline {
private:
    LpfFilter filter;
    ZScoreAnomalyDetector detector;

public:
    // Parameters: EMA filter alpha, calibration size, anomaly threshold
    SensorProcessingPipeline() 
        : filter(0.25f), detector(50, 3.0f) {}

    // Process a raw sensor frame. Returns true if anomalous.
    bool processSample(const AccelerometerData& rawData) {
        // 1. Compute magnitude: sqrt(x^2 + y^2 + z^2)
        float rawMagnitude = std::sqrt(rawData.x * rawData.x + 
                                       rawData.y * rawData.y + 
                                       rawData.z * rawData.z);

        // 2. Filter the signal to remove vibration spikes
        float filteredMagnitude = filter.update(rawMagnitude);

        // 3. Evaluate anomaly
        return detector.update(filteredMagnitude);
    }
};

