```cpp
#include <cmath>
#include <cstdint>

// Representation of a 3-axis accelerometer sample
struct AccelSample {
    float x;
    float y;
    float z;
};

// 1. Fixed-size Circular Buffer (No Heap Allocation)
template <typename T, size_t Capacity>
class CircularBuffer {
private:
    T buffer[Capacity];
    size_t head = 0;
    size_t count = 0;

public:
    void push(T value) {
        buffer[head] = value;
        head = (head + 1) % Capacity;
        if (count < Capacity) {
            count++;
        }
    }

    size_t size() const { return count; }
    bool is_full() const { return count == Capacity; }

    // Calculate mean of the buffer
    float get_mean() const {
        if (count == 0) return 0.0f;
        float sum = 0.0f;
        for (size_t i = 0; i < count; ++i) {
            sum += buffer[i];
        }
        return sum / count;
    }

    // Calculate standard deviation of the buffer
    float get_std_dev(float mean) const {
        if (count < 2) return 0.0f;
        float sum_sq_diff = 0.0f;
        for (size_t i = 0; i < count; ++i) {
            float diff = buffer[i] - mean;
            sum_sq_diff += diff * diff;
        }
        return std::sqrt(sum_sq_diff / (count - 1)); // Sample standard deviation
    }
};

// 2. Exponential Moving Average (EMA) Filter
class LowPassFilter {
private:
    float alpha; // Smoothing factor (0.0 < alpha <= 1.0)
    float prev_output;
    bool initialized = false;

public:
    LowPassFilter(float smoothing_factor) : alpha(smoothing_factor), prev_output(0.0f) {}

    float filter(float input) {
        if (!initialized) {
            prev_output = input;
            initialized = true;
            return input;
        }
        float output = (alpha * input) + ((1.0f - alpha) * prev_output);
        prev_output = output;
        return output;
    }
};

// 3. Sensor Processing Pipeline
class AnomalyDetectionPipeline {
private:
    static constexpr size_t WINDOW_SIZE = 32; // 32 samples (e.g., 640ms at 50Hz)

    LowPassFilter lpf;
    CircularBuffer<float, WINDOW_SIZE> window;

    float sensitivity;      // Z-score threshold (typically 2.5 to 4.0)
    float min_std_dev;      // Noise floor (prevents false positives when perfectly still)

public:
    // sensitivity: How many standard deviations away from the mean constitutes an anomaly
    // noise_floor: Minimum standard deviation to prevent division-by-zero/hyper-sensitivity
    AnomalyDetectionPipeline(float filter_alpha, float sensitivity, float noise_floor)
        : lpf(filter_alpha), sensitivity(sensitivity), min_std_dev(noise_floor) {}

    /**
     * @brief Process a new accelerometer sample.
     * @param sample Raw X, Y, Z data in Gs or m/s^2.
     * @param out_filtered_mag Output parameter containing the filtered magnitude.
     * @return true if an anomaly is detected, false otherwise.
     */
    bool process_sample(const AccelSample& sample, float& out_filtered_mag) {
        // Step 1: Compute Vector Magnitude (Rotation Invariant)
        float raw_magnitude = std::sqrt(sample.x * sample.x + 
                                        sample.y * sample.y + 
                                        sample.z * sample.z);

        // Step 2: Low-pass filter to remove sensor jitter/noise
        out_filtered_mag = lpf.filter(raw_magnitude);

        // If window isn't full yet, populate it and return false
        if (!window.is_full()) {
            window.push(out_filtered_mag);
            return false;
        }

        // Step 3: Get rolling statistics from window (excluding current sample)
        float mean = window.get_mean();
        float std_dev = window.get_std_dev(mean);

        // Enforce a minimum noise floor
        if (std_dev < min_std_dev) {
            std_dev = min_std_dev;
        }

        // Step 4: Calculate Z-score for the current sample
        float deviation = std::abs(out_filtered_mag - mean);
        bool is_anomaly = (deviation > (sensitivity * std_dev));

        // Step 5: Slide the window forward by adding the new sample
        window.push(out_filtered_mag);

        return is_anomaly;
    }
};
