### The Code (`Pipeline.hpp` & `main.cpp`)

```cpp
#include <iostream>
#include <array>
#include <cmath>
#include <numeric>

// Configuration Constants
constexpr size_t WINDOW_SIZE = 32;       // Size of sliding window (must be power of 2 for optimization)
constexpr float ANOMALY_THRESHOLD_Z = 3.0f; // Number of standard deviations to trigger anomaly
constexpr float MIN_STD_DEV = 0.05f;     // Prevents division by zero/noise amplification in static state

// Struct to hold raw accelerometer data
struct AccelData {
    float x;
    float y;
    float z;
};

// Fixed-size Circular Buffer for memory-safe embedded execution
template <typename T, size_t N>
class CircularBuffer {
private:
    std::array<T, N> _buffer{};
    size_t _head = 0;
    size_t _count = 0;

public:
    void push(T item) {
        _buffer[_head] = item;
        _head = (_head + 1) % N;
        if (_count < N) {
            _count++;
        }
    }

    size_t size() const { return _count; }
    bool is_full() const { return _count == N; }

    // Computes Mean and Standard Deviation of the buffer
    void get_stats(float& mean, float& std_dev) const {
        if (_count == 0) {
            mean = 0.0f;
            std_dev = 0.0f;
            return;
        }

        // Calculate Mean
        float sum = 0.0f;
        for (size_t i = 0; i < _count; ++i) {
            sum += _buffer[i];
        }
        mean = sum / static_cast<float>(_count);

        // Calculate Variance
        float variance_sum = 0.0f;
        for (size_t i = 0; i < _count; ++i) {
            float diff = _buffer[i] - mean;
            variance_sum += diff * diff;
        }

        float variance = variance_sum / static_cast<float>(_count);
        std_dev = std::sqrt(variance);

        // Floor the standard deviation to avoid noise issues when completely still
        if (std_dev < MIN_STD_DEV) {
            std_dev = MIN_STD_DEV;
        }
    }
};

// Embedded Sensor Processing Pipeline
class AnomalyDetectionPipeline {
private:
    CircularBuffer<float, WINDOW_SIZE> _history;
    float _current_mean = 0.0f;
    float _current_std_dev = 0.0f;

    // Helper: Compute vector magnitude to make algorithm orientation-independent
    float compute_magnitude(const AccelData& data) {
        // sqrtf is faster on embedded systems with single-precision FPUs
        return std::sqrtf(data.x * data.x + data.y * data.y + data.z * data.z);
    }

public:
    // Processes a new sensor reading. Returns true if anomaly detected.
    bool process_sample(const AccelData& sample, float& out_z_score) {
        float magnitude = compute_magnitude(sample);
        out_z_score = 0.0f;

        // If we don't have enough history, just fill the buffer and return false
        if (!_history.is_full()) {
            _history.push(magnitude);
            return false;
        }

        // Get statistical baseline of the "recent past"
        _history.get_stats(_current_mean, _current_std_dev);

        // Calculate Z-Score: how many standard deviations is this sample from the mean?
        out_z_score = std::fabs(magnitude - _current_mean) / _current_std_dev;

        // Slide the window forward
        _history.push(magnitude);

        // Check against threshold
        return (out_z_score > ANOMALY_THRESHOLD_Z);
    }
};

