### C++ Implementation

```cpp
#include <cmath>
#include <cstdint>

// Pipeline Configuration
template <size_t WindowSize>
class AnomalyDetectionPipeline {
public:
    struct AccelerometerData {
        float x;
        float y;
        float z;
    };

    struct PipelineResult {
        float filtered_magnitude;
        float z_score;
        bool is_anomaly;
    };

    /**
     * @param lpf_alpha Low-pass filter coefficient (0.0 to 1.0). Lower = more smoothing.
     * @param z_threshold Number of standard deviations to trigger an anomaly (e.g., 3.0).
     */
    AnomalyDetectionPipeline(float lpf_alpha = 0.2f, float z_threshold = 3.0f)
        : alpha_(lpf_alpha), 
          z_threshold_(z_threshold), 
          last_filtered_value_(0.0f), 
          is_initialized_(false),
          buffer_index_(0),
          buffer_filled_(false) {

        for (size_t i = 0; i < WindowSize; ++i) {
            history_buffer_[i] = 0.0f;
        }
    }

    /**
     * Push a raw accelerometer sample through the pipeline.
     * @return PipelineResult containing filtered value, calculated Z-score, and anomaly status.
     */
    PipelineResult process_sample(const AccelerometerData& raw) {
        // Step 1: Calculate vector magnitude (orientation invariant)
        float magnitude = std::sqrt(raw.x * raw.x + raw.y * raw.y + raw.z * raw.z);

        // Step 2: Exponential Moving Average (Low Pass Filter)
        if (!is_initialized_) {
            last_filtered_value_ = magnitude;
            is_initialized_ = true;
        } else {
            last_filtered_value_ = (alpha_ * magnitude) + ((1.0f - alpha_) * last_filtered_value_);
        }

        float current_filtered = last_filtered_value_;

        // Step 3: Check for anomalies using historical statistics before adding the new sample
        float z_score = 0.0f;
        bool anomaly_detected = false;

        if (buffer_filled_) {
            float mean = calculate_mean();
            float std_dev = calculate_std_dev(mean);

            // Avoid division by zero if standard deviation is incredibly small
            if (std_dev > 0.001f) {
                z_score = std::abs(current_filtered - mean) / std_dev;
                if (z_score > z_threshold_) {
                    anomaly_detected = true;
                }
            }
        }

        // Step 4: Update sliding history ring buffer
        push_to_buffer(current_filtered);

        return PipelineResult{current_filtered, z_score, anomaly_detected};
    }

private:
    // Pipeline parameters
    const float alpha_;
    const float z_threshold_;

    // Filter state
    float last_filtered_value_;
    bool is_initialized_;

    // Static circular buffer variables (No dynamic heap allocation)
    float history_buffer_[WindowSize];
    size_t buffer_index_;
    bool buffer_filled_;

    void push_to_buffer(float val) {
        history_buffer_[buffer_index_] = val;
        buffer_index_ = (buffer_index_ + 1) % WindowSize;
        if (buffer_index_ == 0) {
            buffer_filled_ = true;
        }
    }

    float calculate_mean() const {
        float sum = 0.0f;
        for (size_t i = 0; i < WindowSize; ++i) {
            sum += history_buffer_[i];
        }
        return sum / static_cast<float>(WindowSize);
    }

    float calculate_std_dev(float mean) const {
        float variance_sum = 0.0f;
        for (size_t i = 0; i < WindowSize; ++i) {
            float diff = history_buffer_[i] - mean;
            variance_sum += diff * diff;
        }
        float variance = variance_sum / static_cast<float>(WindowSize);
        return std::sqrt(variance);
    }
};

