#include <iostream>
#include <cmath>
#include <cstdint>

// Configuration Constants
constexpr size_t WINDOW_SIZE = 32;       // Size of sliding window for baseline statistics
constexpr float ANOMALY_THRESHOLD = 3.0f; // Z-score threshold (3 standard deviations)
constexpr float ALPHA_LPF = 0.2f;         // Low-pass filter coefficient (0.0 to 1.0)

// Simple representation of raw 3-axis accelerometer data
struct AccelData {
    float x;
    float y;
    float z;
};

// Fixed-size Ring Buffer for embedded systems (zero heap allocation)
template <typename T, size_t N>
class RingBuffer {
private:
    T data[N] = {};
    size_t head = 0;
    size_t count = 0;

public:
    void push(T value) {
        data[head] = value;
        head = (head + 1) % N;
        if (count < N) {
            count++;
        }
    }

    size_t size() const { return count; }
    bool is_full() const { return count == N; }

    // Calculate mean of the buffer
    float get_mean() const {
        if (count == 0) return 0.0f;
        float sum = 0.0f;
        for (size_t i = 0; i < count; ++i) {
            sum += data[i];
        }
        return sum / count;
    }

    // Calculate standard deviation of the buffer
    float get_std_dev(float mean) const {
        if (count < 2) return 0.0f;
        float sum_sq_diff = 0.0f;
        for (size_t i = 0; i < count; ++i) {
            float diff = data[i] - mean;
            sum_sq_diff += diff * diff;
        }
        return std::sqrt(sum_sq_diff / (count - 1));
    }
};

// The Sensor Processing Pipeline
class AnomalyDetectionPipeline {
private:
    float filtered_x = 0.0f;
    float filtered_y = 0.0f;
    float filtered_z = 1.0f; // Assume ~1G on Z-axis at rest

    RingBuffer<float, WINDOW_SIZE> magnitude_history;

    // 1. Exponential Moving Average Low-Pass Filter (removes high-frequency noise)
    void low_pass_filter(const AccelData& raw) {
        filtered_x = (ALPHA_LPF * raw.x) + ((1.0f - ALPHA_LPF) * filtered_x);
        filtered_y = (ALPHA_LPF * raw.y) + ((1.0f - ALPHA_LPF) * filtered_y);
        filtered_z = (ALPHA_LPF * raw.z) + ((1.0f - ALPHA_LPF) * filtered_z);
    }

    // 2. Compute Euclidean Magnitude (makes detection orientation-independent)
    float compute_magnitude() const {
        return std::sqrt(filtered_x * filtered_x + 
                         filtered_y * filtered_y + 
                         filtered_z * filtered_z);
    }

public:
    // Processes a single sensor sample. Returns true if an anomaly is detected.
    bool process_sample(const AccelData& raw_sample, float& out_magnitude) {
        // Step 1: Filter raw data
        low_pass_filter(raw_sample);

        // Step 2: Compute vector magnitude
        out_magnitude = compute_magnitude();

        bool is_anomaly = false;

        // Step 3: Statistical Anomaly Detection (Z-Score)
        if (magnitude_history.is_full()) {
            float mean = magnitude_history.get_mean();
            float std_dev = magnitude_history.get_std_dev(mean);

            // Avoid division by zero if variance is extremely low
            if (std_dev > 0.001f) {
                float z_score = std::abs(out_magnitude - mean) / std_dev;
                if (z_score > ANOMALY_THRESHOLD) {
                    is_anomaly = true;
                }
            }
        }

        // Step 4: Update baseline history with the current sample
        magnitude_history.push(out_magnitude);

        return is_anomaly;
    }
};

