// Preprocessor definitions for hardware-specific actions
#define ANOMALY_LED_PIN 13 // Example GPIO pin for visual alert

class AnomalyDetector {
private:
    static const uint16_t WINDOW_SIZE = 32; // Size of rolling window (must be power of 2 for optimization)
    float buffer[WINDOW_SIZE] = {0.0f};
    uint16_t write_index = 0;
    uint16_t count = 0;
    const float z_threshold; // Number of standard deviations to trigger anomaly

    // Helper to calculate variance and mean statically to avoid float drift
    void calculate_stats(float& out_mean, float& out_std_dev) {
        float sum = 0.0f;
        for (uint16_t i = 0; i < count; i++) {
            sum += buffer[i];
        }
        out_mean = sum / count;

        float sum_sq_diff = 0.0f;
        for (uint16_t i = 0; i < count; i++) {
            float diff = buffer[i] - out_mean;
            sum_sq_diff += diff * diff;
        }

        // Variance = sum of squared differences / N
        float variance = sum_sq_diff / count;

        // Avoid division by zero for completely static sensors
        out_std_dev = sqrtf(variance);
        if (out_std_dev < 0.01f) {
            out_std_dev = 0.01f; 
        }
    }

public:
    // Constructor (Default threshold of 3.0 standard deviations)
    AnomalyDetector(float threshold = 3.0f) : z_threshold(threshold) {}

    /**
     * @brief Processes a single 3-axis accelerometer sample.
     * @return true if anomaly detected, false otherwise.
     */
    bool process_sample(float ax, float ay, float az) {
        // Step 1: Feature Extraction (Calculate Vector Magnitude)
        // This isolates motion from the orientation of the sensor relative to gravity.
        float magnitude = sqrtf(ax*ax + ay*ay + az*az);

        // If buffer is not yet full, just populate it and return false
        if (count < WINDOW_SIZE) {
            buffer[write_index] = magnitude;
            write_index = (write_index + 1) % WINDOW_SIZE;
            count++;
            return false; 
        }

        // Step 2: Compute baseline statistics of the moving window
        float mean = 0.0f;
        float std_dev = 0.0f;
        calculate_stats(mean, std_dev);

        // Step 3: Classification (Z-Score calculation)
        float z_score = fabsf(magnitude - mean) / std_dev;
        bool is_anomaly = (z_score > z_threshold);

        // Step 4: Update the rolling circular buffer (FIFO replacement)
        buffer[write_index] = magnitude;
        write_index = (write_index + 1) % WINDOW_SIZE;

        return is_anomaly;
    }
};

