#include <iostream>
#include <cmath>
#include <array>

// --- EMBEDDED-FRIENDLY CONSTANTS ---
constexpr size_t WINDOW_SIZE = 10;        // Size of the sliding window for feature extraction
constexpr float ANOMALY_THRESHOLD = 1.5f; // Variance threshold to trigger an anomaly (m/s² squared)

// Standard struct to hold 3-axis accelerometer data
struct AccelData {
    float x;
    float y;
    float z;
};

// --- STATIC RING BUFFER FOR WINDOWING ---
// Zero heap-allocation circular buffer optimized for microcontrollers
template <typename T, size_t N>
class StaticRingBuffer {
private:
    std::array<T, N> buffer{};
    size_t head = 0;
    size_t count = 0;

public:
    void push(T value) {
        buffer[head] = value;
        head = (head + 1) % N;
        if (count < N) {
            count++;
        }
    }

    size_t size() const { return count; }

    T operator[](size_t index) const {
        // Resolve logical index to physical ring buffer index (oldest to newest)
        size_t physical_idx = (head - count + index + N) % N;
        return buffer[physical_idx];
    }
};

// --- ANOMALY DETECTION PIPELINE ---
class AnomalyDetector {
private:
    StaticRingBuffer<float, WINDOW_SIZE> mag_window;

public:
    // Processes a raw sample and returns true if an anomaly is detected
    bool process_sample(const AccelData& sample) {
        // 1. Feature Extraction: Calculate Euclidean Magnitude ||a|| = sqrt(x² + y² + z²)
        float magnitude = std::sqrt(sample.x * sample.x + sample.y * sample.y + sample.z * sample.z);

        // 2. Windowing: Push magnitude into our rolling window
        mag_window.push(magnitude);

        // Do not make a decision until the window is fully primed with data
        if (mag_window.size() < WINDOW_SIZE) {
            return false; 
        }

        // 3. Statistical Processing: Compute rolling mean
        float sum = 0.0f;
        for (size_t i = 0; i < WINDOW_SIZE; ++i) {
            sum += mag_window[i];
        }
        float mean = sum / WINDOW_SIZE;

        // 4. Statistical Processing: Compute variance (Standard Deviation squared)
        // We use variance to avoid calling std::sqrt() again, saving CPU cycles.
        float sum_sq_diff = 0.0f;
        for (size_t i = 0; i < WINDOW_SIZE; ++i) {
            float diff = mag_window[i] - mean;
            sum_sq_diff += diff * diff;
        }
        float variance = sum_sq_diff / WINDOW_SIZE;

        // 5. Threshold-based Anomaly Detection
        // If variance is abnormally high, we are experiencing erratic motion/impact
        return (variance > ANOMALY_THRESHOLD);
    }
};

