```cpp
#include <iostream>
#include <cmath>

// Struct to represent 3-axis accelerometer data
struct AccelData {
    float x;
    float y;
    float z;
};

// 1. DIGITAL SIGNAL PROCESSING: Low Pass Filter (Exponential Moving Average)
class LowPassFilter {
private:
    float alpha; // Smoothing factor (0.0 < alpha <= 1.0)
    AccelData filteredData;
    bool isInitialized;

public:
    LowPassFilter(float smoothingFactor) 
        : alpha(smoothingFactor), filteredData{0, 0, 0}, isInitialized(false) {}

    AccelData filter(const AccelData& raw) {
        if (!isInitialized) {
            filteredData = raw;
            isInitialized = true;
            return filteredData;
        }
        filteredData.x = alpha * raw.x + (1.0f - alpha) * filteredData.x;
        filteredData.y = alpha * raw.y + (1.0f - alpha) * filteredData.y;
        filteredData.z = alpha * raw.z + (1.0f - alpha) * filteredData.z;
        return filteredData;
    }
};

// 2. FEATURE EXTRACTION: Calculates vector magnitude (total acceleration)
float calculateMagnitude(const AccelData& data) {
    return std::sqrt(data.x * data.x + data.y * data.y + data.z * data.z);
}

// 3. ANOMALY DETECTOR: Dynamic Z-score thresholding using Welford's Algorithm
// This allows memory-efficient, real-time statistics tracking in O(1) space.
class ZScoreAnomalyDetector {
private:
    float threshold;      // Standard deviation multiplier (e.g., 3.0)
    uint32_t warmupSamples; // Number of samples to collect before active alerting

    // Welford's algorithm variables
    uint32_t count;
    float mean;
    float M2; 

public:
    ZScoreAnomalyDetector(float zThreshold, uint32_t warmup) 
        : threshold(zThreshold), warmupSamples(warmup), count(0), mean(0.0f), M2(0.0f) {}

    bool updateAndDetect(float val) {
        count++;

        // Welford's math for online variance tracking
        float delta = val - mean;
        mean += delta / count;
        float delta2 = val - mean;
        M2 += delta * delta2;

        // Skip detection during warmup phase to establish baseline stddev
        if (count < warmupSamples) {
            return false; 
        }

        float variance = (count > 1) ? (M2 / (count - 1)) : 0.0f;
        float stddev = std::sqrt(variance);

        // Avoid division by zero if stddev is negligible
        if (stddev < 0.01f) stddev = 0.01f; 

        // Anomaly condition: absolute difference exceeds threshold * stddev
        float deviation = std::abs(val - mean);
        if (deviation > (threshold * stddev)) {
            return true; // Anomaly detected
        }

        return false;
    }

    float getMean() const { return mean; }
};

// 4. THE PIPELINE: Chains stages together
class SensorPipeline {
private:
    LowPassFilter filter;
    ZScoreAnomalyDetector detector;

public:
    SensorPipeline() : filter(0.2f), detector(3.0f, 10) {} // 3.0 Sigma, 10-sample warmup

    void processSample(const AccelData& raw) {
        // Step 1: Filter noise
        AccelData smoothed = filter.filter(raw);

        // Step 2: Feature extraction (Calculate G-force magnitude)
        float magnitude = calculateMagnitude(smoothed);

        // Step 3: Check for anomalies
        bool isAnomaly = detector.updateAndDetect(magnitude);

        // Step 4: Act (Output to Serial / Set Pin High)
        std::cout << "Mag: " << magnitude 
                  << " \t| Baseline Mean: " << detector.getMean();

        if (isAnomaly) {
            std::cout << " \t>>> [ANOMALY DETECTED!] <<<" << std::endl;
            // On a real MCU, you would call: digitalWrite(ALARM_LED_PIN, HIGH);
        } else {
            std::cout << "\t| Normal" << std::endl;
        }
    }
};

// --- SIMULATION ---
