        {-0.2, 0.2, 9.7},
        {0.0, 0.0, 9.9},
        {0.1, -0.1, 9.8},
        {-0.1, 0.1, 9.7},
        {0.0, 0.2, 9.8},
        {0.2, -0.2, 9.9},
        {-0.1, 0.0, 9.7},
        {0.1, 0.1, 9.8},
        {0.0, 0.0, 9.8},   // End of warmup

        {0.1, 0.1, 9.9},   // Normal operation
        {0.0, -0.1, 9.8},  // Normal operation

        {15.2, 22.4, 35.1}, // Shock anomaly (e.g., device dropped!)

        {-0.1, 0.2, 9.7},  // Recovery
        {0.0, 0.0, 9.8}    // Normal operation
    };

    std::cout << "Starting Embedded Sensor Pipeline Processing...\n";
    for (const auto& sample : dataset) {
        pipeline.processSample(sample);
    }

    return 0;
}
