#include <iostream>
#include <cmath>
#include <stdint.h>

// Simple representation of 3-axis accelerometer reading
struct AccelData {
    float x; // in g
    float y;
    float z;
};

class AnomalyDetector {
private:
    // Pipeline hyperparameters
    const float alpha;       // Smoothing factor for EMA (0 < alpha < 1)
    const float k_threshold; // Number of standard deviations to trigger anomaly

    // Pipeline state (occupies minimal RAM, static allocation)
    float mean_magnitude;
    float var_magnitude;
    bool is_initialized;

public:
    // Constructor (usually initialized with experimental tuning parameters)
    constexpr AnomalyDetector(float filter_alpha = 0.1f, float threshold_sigma = 3.0f)
        : alpha(filter_alpha),
          k_threshold(threshold_sigma),
          mean_magnitude(0.0f),
          var_magnitude(0.0f),
          is_initialized(false) {}

    // Process a single accelerometer sample and return true if anomaly detected
    bool process_sample(const AccelData& sample) {
        // 1. Calculate vector magnitude (orientation-independent feature)
        // Note: sqrtf is hardware-accelerated on most modern MCUs (ARM Cortex-M4/M7)
        float magnitude = std::sqrt(sample.x * sample.x + sample.y * sample.y + sample.z * sample.z);

        if (!is_initialized) {
            // Warm up the filter on the first sample
            mean_magnitude = magnitude;
            var_magnitude = 0.01f; // Small non-zero default variance
            is_initialized = true;
            return false;
        }

        // 2. Anomaly Detection Logic
        // Calculate the difference from the running average
        float diff = magnitude - mean_magnitude;
        float diff_sq = diff * diff;

        // Check if current deviation exceeds dynamic threshold
        // We compare squared values to avoid computing a costly square root of variance
        float threshold = (k_threshold * k_threshold) * var_magnitude;
        bool is_anomaly = (diff_sq > threshold);

        // 3. Update filter state (Welford's-like method for Exponential Moving Variance)
        mean_magnitude = (alpha * magnitude) + ((1.0f - alpha) * mean_magnitude);
        var_magnitude  = (alpha * diff_sq) + ((1.0f - alpha) * var_magnitude);

        return is_anomaly;
    }
};

