To keep this code runnable on any computer while remaining highly representative of an embedded environment, it uses a **Mock Sensor** (which simulates normal gravitational noise and occasional shock anomalies) and avoids any dynamic memory allocation (`new`, `delete`, or `std::vector`) to ensure deterministic execution.

The pipeline processes 3-axis data, calculates the vector magnitude (making it orientation-independent), applies an **Exponential Moving Average (EMA) filter** to smooth high-frequency noise, and uses a **rolling Z-score algorithm** (statistical thresholding) to detect anomalies.

### C++ Sensor-Processing Pipeline

```cpp
#include <iostream>
#include <cmath>
#include <array>
#include <random>

// Configuration Constants
constexpr size_t WINDOW_SIZE = 20;       // Size of the rolling statistical window
constexpr float EMA_ALPHA = 0.3f;        // Filter coefficient (0.0 to 1.0). Lower = smoother.
constexpr float ANOMALY_THRESHOLD = 3.0f; // Number of standard deviations to trigger anomaly

// Data structure representing raw accelerometer readings (in Gs or m/s^2)
struct AccelData {
    float x;
    float y;
    float z;
};

// --- 1. MOCK SENSOR ---
// Simulates an I2C/SPI accelerometer.
class MockAccelerometer {
private:
    std::default_random_engine generator;
    std::normal_distribution<float> noise;
    int step = 0;

public:
    MockAccelerometer() : noise(0.0f, 0.05f) {} // Noise standard dev of 0.05G

    AccelData read() {
        step++;
        AccelData data;
        // Simulate gravity on Z-axis (approx 1.0G) + noise on all axes
        data.x = noise(generator);
        data.y = noise(generator);
        data.z = 1.0f + noise(generator);

        // Inject an anomaly (sudden impact/shake) every 30 samples
        if (step % 30 == 0) {
            data.x += 1.8f; // Major sudden spike
            data.y -= 1.2f;
        }
        return data;
    }
};

// --- 2. SIGNAL FILTER ---
// Exponential Moving Average (EMA) filter to smooth out sensor noise.
class EmaFilter {
private:
    float prev_value = 0.0f;
    bool initialized = false;

public:
    float filter(float input) {
        if (!initialized) {
            prev_value = input;
            initialized = true;
            return input;
        }
        float filtered = (EMA_ALPHA * input) + ((1.0f - EMA_ALPHA) * prev_value);
        prev_value = filtered;
        return filtered;
    }
};

// --- 3. ANOMALY DETECTOR ---
// Uses a fixed-size ring buffer to calculate running mean and standard deviation.
// Detects anomalies based on the current value's Z-Score deviation.
class StatisticalAnomalyDetector {
private:
    std::array<float, WINDOW_SIZE> buffer = {0.0f};
    size_t index = 0;
    size_t count = 0;

    void insert(float val) {
        buffer[index] = val;
        index = (index + 1) % WINDOW_SIZE;
        if (count < WINDOW_SIZE) count++;
    }

    // Calculates mean and standard deviation of current window
    void get_statistics(float& mean, float& std_dev) {
        float sum = 0.0f;
        for (size_t i = 0; i < count; ++i) {
            sum += buffer[i];
        }
        mean = sum / count;

        float variance_sum = 0.0f;
        for (size_t i = 0; i < count; ++i) {
            variance_sum += std::pow(buffer[i] - mean, 2);
        }
        // Avoid division by zero
        float variance = (count > 1) ? (variance_sum / (count - 1)) : 0.001f;
        std_dev = std::sqrt(variance);
    }

public:
    // Returns true if an anomaly is detected
    bool process_and_detect(float current_val) {
        if (count < WINDOW_SIZE) {
            // Warm up the statistical buffer
            insert(current_val);
            return false; 
        }

        float mean = 0.0f;
        float std_dev = 0.0f;
        get_statistics(mean, std_dev);

        // Calculate Z-score (how many standard deviations away from the mean)
        float z_score = std::abs(current_val - mean) / (std_dev < 0.01f ? 0.01f : std_dev);

        // Update baseline with current value for adaptability
        insert(current_val);

        // If current value is statistically abnormal, flag it
        return z_score > ANOMALY_THRESHOLD;
    }
};

// --- 4. PIPELINE COORDINATOR ---
class SensorPipeline {
private:
    EmaFilter filter;
    StatisticalAnomalyDetector detector;

public:
    void run_cycle(const AccelData& raw_data) {
        // Step A: Convert 3D vector to a single scalar magnitude (orientation invariant)
        float raw_magnitude = std::sqrt(raw_data.x * raw_data.x + 
                                        raw_data.y * raw_data.y + 
                                        raw_data.z * raw_data.z);

        // Step B: Smooth the magnitude using the EMA filter
        float filtered_magnitude = filter.filter(raw_magnitude);

        // Step C: Check for statistical anomaly
        bool is_anomaly = detector.process_and_detect(filtered_magnitude);

        // Step D: Output results
        std::cout << "Raw Mag: " << raw_magnitude 
                  << " | Filtered Mag: " << filtered_magnitude;

        if (is_anomaly) {
            std::cout << " --> [!!! ANOMALY DETECTED !!!]\n";
        } else {
            std::cout << " --> [Normal]\n";
        }
    }
};

// --- MAIN EXECUTION LOOP ---
int main() {
    MockAccelerometer sensor;
    SensorPipeline pipeline;

    std::cout << "Initializing Sensor Pipeline. Warming up statistical baseline...\n";

    // Run pipeline for 60 ticks
    for (int tick = 1; tick <= 60; ++tick) {
        std::cout << "Tick " << tick << " | ";
        AccelData sample = sensor.read();
        pipeline.run_cycle(sample);
    }

    return 0;
}
```

### Why this is highly suitable for Embedded Devices:

1. **Deterministic Memory Footprint:** The algorithm relies on standard C++ stack allocation. There are no calls to `std::vector` or `std::malloc`/`new`. The data buffer is statically allocated inside `std::array<float, WINDOW_SIZE>` at compile time, preventing memory fragmentation and ensuring consistent execution speed.
2. **Orientation Invariance:** The pipeline first reduces the $x, y, z$ inputs into a single magnitude scalar ($\sqrt{x^2+y^2+z^2}$). This means the anomaly detector functions perfectly regardless of how the physical device is mounted or rotated.
3. **Low Latency / Constant Time $O(1)$ Operations:** The Exponential Moving Average (EMA) filter only requires saving one previous step's data and performs a single multiplication and addition—making it significantly faster than FIR/IIR filters on microcontrollers lacking hardware floating-point units (FPUs).
4. **Adaptive Thresholding:** Instead of using hardcoded limits (which fail if the machine the sensor is mounted on naturally vibrates more or less over time), the rolling Z-score adapts to the current environmental noise floor.

