```rust
#![no_std] // Disables the Rust standard library; compiles directly to bare metal.

/// An Exponential Moving Average (EMA) filter using integer math.
/// Ideal for resource-constrained systems as it only requires storing 1 historical state.
pub struct EmaFilter {
    alpha_scaled: u32, // Scale factor (0 to 256, representing 0.0 to 1.0)
    state: u32,        // Current filtered value (scaled by 256 internally)
    is_initialized: bool,
}

impl EmaFilter {
    /// Creates a new filter. `alpha_percent` (0 to 100) dictates responsiveness.
    /// Higher = responsive but noisy. Lower = smooth but introduces latency.
    pub const fn new(alpha_percent: u32) -> Self {
        // We scale alpha to 0-256 to allow fast division via bit-shifting (>> 8)
        let alpha_scaled = (alpha_percent * 256) / 100;
        Self {
            alpha_scaled,
            state: 0,
            is_initialized: false,
        }
    }

    /// Filters an incoming raw sensor reading and returns the smoothed value.
    pub fn filter(&mut self, raw_sample: u32) -> u32 {
        if !self.is_initialized {
            self.state = raw_sample << 8; // Scale up raw reading to match internal representation
            self.is_initialized = true;
            return raw_sample;
        }

        // Fixed-point EMA formula: State = (alpha * sample) + ((1 - alpha) * State)
        let sample_scaled = raw_sample << 8;
        self.state = ((self.alpha_scaled * sample_scaled) 
            + ((256 - self.alpha_scaled) * self.state)) >> 8;

        // Scale back down to return the actual value
        self.state >> 8
    }
}

/// Represents the states of our physical actuator (e.g., a cooling fan or valve).
#[derive(Copy, Clone, PartialEq, Eq, Debug)]
pub enum ActuatorState {
    Off,
    On,
}

/// Manages an actuator based on sensor limits, utilizing hysteresis.
pub struct ActuatorController {
    low_threshold: u32,  // Deactivation threshold
    high_threshold: u32, // Activation threshold
    current_state: ActuatorState,
}

impl ActuatorController {
    pub const fn new(low_threshold: u32, high_threshold: u32) -> Self {
        Self {
            low_threshold,
            high_threshold,
            current_state: ActuatorState::Off,
        }
    }

    /// Evaluates the filtered value and decides whether to toggle the actuator.
    /// Returns `Some(new_state)` if a change occurred, otherwise `None`.
    pub fn update(&mut self, filtered_value: u32) -> Option<ActuatorState> {
        let previous_state = self.current_state;

        match self.current_state {
            ActuatorState::Off => {
                // Turn ON only if we exceed the high threshold
                if filtered_value >= self.high_threshold {
                    self.current_state = ActuatorState::On;
                }
            }
            ActuatorState::On => {
                // Turn OFF only if we drop below the low threshold (Hysteresis)
                if filtered_value <= self.low_threshold {
                    self.current_state = ActuatorState::Off;
                }
            }
        }

        if self.current_state != previous_state {
            Some(self.current_state)
        } else {
            None
        }
    }
}
```

