#![no_std] // Instructs the compiler not to link the standard library (for bare-metal/edge)

/// An Exponential Moving Average (EMA) filter.
/// Highly optimized for resource-constrained systems as it requires zero memory allocation
/// and maintains its entire state in a single f32 variable (4 bytes of RAM).
pub struct EmaFilter {
    alpha: f32, // Smoothing factor: 1.0 = no filtering, 0.0 = infinite filtering
    state: Option<f32>,
}

impl EmaFilter {
    /// Creates a new filter. `alpha` must be between 0.0 and 1.0.
    pub const fn new(alpha: f32) -> Self {
        Self { alpha, state: None }
    }

    /// Feeds a raw sensor reading into the filter and returns the filtered value.
    pub fn update(&mut self, input: f32) -> f32 {
        let current_state = match self.state {
            Some(prev_state) => (self.alpha * input) + ((1.0 - self.alpha) * prev_state),
            None => input, // Initialize filter state with the very first reading
        };
        self.state = Some(current_state);
        current_state
    }
}

/// Commands to control a physical actuator.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ActuatorCommand {
    TurnOn,
    TurnOff,
    NoChange,
}

/// Manages a cooling fan actuator based on temperature inputs.
/// Features hysteresis to protect physical hardware from rapid oscillations.
pub struct CoolingSystem {
    target_threshold: f32, // Temperature threshold to trigger cooling
    hysteresis: f32,       // Safe range to prevent actuator chattering
    is_active: bool,       // Track current state of the physical actuator
}

impl CoolingSystem {
    pub const fn new(target_threshold: f32, hysteresis: f32) -> Self {
        Self {
            target_threshold,
            hysteresis,
            is_active: false,
        }
    }

    /// Evaluates the filtered sensor data and returns a command for the physical actuator.
    pub fn process_temperature(&mut self, filtered_temp: f32) -> ActuatorCommand {
        let high_limit = self.target_threshold + self.hysteresis;
        let low_limit = self.target_threshold - self.hysteresis;

        if self.is_active && filtered_temp < low_limit {
            self.is_active = false;
            ActuatorCommand::TurnOff
        } else if !self.is_active && filtered_temp > high_limit {
            self.is_active = true;
            ActuatorCommand::TurnOn
        } else {
            ActuatorCommand::NoChange
        }
    }
}

