#![no_std] // Ensures no standard library (OS) dependency; suitable for bare-metal.

/// An Exponential Moving Average (EMA) filter.
/// Perfect for edge devices: requires zero dynamic memory allocation
/// and retains only a single state value in memory.
pub struct EmaFilter {
    alpha: f32,          // Smoothing factor between 0.0 and 1.0 (lower = smoother/slower)
    stored_value: Option<f32>,
}

impl EmaFilter {
    /// Creates a new filter. 
    /// `alpha` defines the cutoff frequency behavior.
    pub const fn new(alpha: f32) -> Self {
        // Ensure alpha is bounded between 0.0 and 1.0 in application logic
        Self {
            alpha,
            stored_value: None,
        }
    }

    /// Filters the incoming noisy signal.
    pub fn filter(&mut self, input: f32) -> f32 {
        let current = match self.stored_value {
            Some(prev) => (self.alpha * input) + ((1.0 - self.alpha) * prev),
