uint16_t HAL_ADC_Read(uint8_t channel) {
    // Simulates a 12-bit ADC (0 to 4095).
    // Let's simulate a physical temperature rising from 35C to 45C with heavy high-frequency noise.
    static float simulated_real_temp = 35.0f;
    simulated_real_temp += 0.5f; 
    if (simulated_real_temp > 48.0f) {
        simulated_real_temp = 35.0f; // Reset loop
    }

    // Add +/- 3.5 degrees of random sensor noise
    float noise = (((float)rand() / (float)RAND_MAX) * 7.0f) - 3.5f;
    float noisy_temp = simulated_real_temp + noise;

    // Map 0.0C - 100.0C to 0 - 4095 ADC counts
    if (noisy_temp < 0.0f) noisy_temp = 0.0f;
    if (noisy_temp > 100.0f) noisy_temp = 100.0f;
    return (uint16_t)((noisy_temp / 100.0f) * 4095.0f);
}

void HAL_GPIO_Write(uint8_t pin, bool state) {
    // In a real system, this toggles a transistor, relay, or gate driver.
    printf("   >>> [HAL GPIO Write] Pin %d -> %s\n", pin, state ? "HIGH (ON)" : "LOW (OFF)");
}

/* --- Core Edge System Logic --- */

// Convert raw 12-bit ADC value to degrees Celsius
float adc_to_temperature(uint16_t adc_val) {
    return ((float)adc_val / 4095.0f) * 100.0f;
}

/**
 * Exponential Moving Average (EMA) Filter
 * Formula: Y[n] = (Alpha * X[n]) + ((1 - Alpha) * Y[n-1])
 * 
 * Why this filter is ideal for constrained edge devices:
 * 1. O(1) Time Complexity: Requires only 1 multiplication and 1 addition per step.
 * 2. O(1) Space Complexity: Requires only 4 bytes (1 float) of persistent state memory.
 *    Traditional moving averages require a large circular buffer array.
 */
float apply_ema_filter(float input, float previous_filtered) {
    return (FILTER_ALPHA * input) + ((1.0f - FILTER_ALPHA) * previous_filtered);
}

