    printf("Initializing Edge Node Sensor Filter & Actuator Controller...\n\n");

    // Simulating 25 execution ticks of our control loop (typically run inside a 10Hz timer ISR or RTOS task)
    for (int tick = 0; tick < 25; tick++) {
        // 1. Acquisition: Read sensor from ADC
        uint16_t raw_adc = HAL_ADC_Read(SENSOR_ADC_CHANNEL);
        float raw_temp = adc_to_temperature(raw_adc);

        // 2. Processing: Apply low-pass filter to remove sensor noise
        if (is_first_run) {
            filtered_temp = raw_temp; // Prevent filter wind-up on startup
            is_first_run = false;
        } else {
            filtered_temp = apply_ema_filter(raw_temp, filtered_temp);
        }

        // 3. Control: Actuator Logic with Hysteresis
        // Prevents rapid actuator switching ("chattering") when noisy data hovers around the threshold.
        bool old_state = actuator_state;
        if (filtered_temp >= TEMP_THRESHOLD_HIGH) {
