        } else if (filtered_temp <= TEMP_THRESHOLD_LOW) {
            actuator_state = false;
        }

        // Only write to GPIO if state has changed, saving processor cycles/power
        if (actuator_state != old_state) {
            HAL_GPIO_Write(ACTUATOR_GPIO_PIN, actuator_state);
        }

