/**
 * @brief Exponential Moving Average (EMA) Low-Pass Filter.
 * Memory footprint: 12 bytes (2 floats, 1 bool).
 * Computational complexity: O(1) time complexity.
 */
class LowPassFilter {
private:
    float alpha;          // Smoothing factor (0.0 < alpha <= 1.0). Lower = smoother but slower.
    float filtered_value; // Previous filtered state
    bool is_initialized;

public:
    constexpr LowPassFilter(float smoothing_factor) 
        : alpha(smoothing_factor), filtered_value(0.0f), is_initialized(false) {}

    float update(float raw_input) {
        if (!is_initialized) {
            filtered_value = raw_input;
            is_initialized = true;
        } else {
            // EMA Formula: Y[n] = alpha * X[n] + (1 - alpha) * Y[n-1]
            filtered_value = (alpha * raw_input) + ((1.0f - alpha) * filtered_value);
        }
        return filtered_value;
    }

    float get_value() const { return filtered_value; }
};

/**
 * @brief Actuator Controller with Hysteresis.
 * Memory footprint: 9 bytes (2 floats, 1 bool).
 * Prevents actuator wear caused by high-frequency noise.
 */
class ActuatorController {
private:
    float low_threshold;   // Turn OFF threshold
    float high_threshold;  // Turn ON threshold
    bool is_active;

public:
    constexpr ActuatorController(float low, float high) 
        : low_threshold(low), high_threshold(high), is_active(false) {}

    // Processes the filtered data and manages physical state transitions
    bool update(float filtered_value) {
        if (is_active) {
            // If active, stay active until reading falls below the low threshold
            if (filtered_value < low_threshold) {
                is_active = false;
                execute_hardware_write(false);
            }
        } else {
            // If inactive, stay inactive until reading exceeds the high threshold
            if (filtered_value > high_threshold) {
                is_active = true;
                execute_hardware_write(true);
            }
        }
        return is_active;
    }

    bool get_state() const { return is_active; }

private:
    // Low-level Hardware Abstraction Layer (HAL) write
    inline void execute_hardware_write(bool state) {
        // In actual hardware, this would write directly to a GPIO register.
        // e.g., *GPIO_ODR |= (1 << PIN_NUM);
    }
};

