/* --- SYSTEM FUNCTIONS --- */

/**
 * Initializes the sensor filter state.
 */
void filter_init(SensorFilter_t *filter) {
    filter->last_filtered_value = 0;
    filter->is_initialized = false;
}

/**
 * Low-overhead Exponential Moving Average (EMA) Digital Filter.
 * Math: Y[n] = alpha * X[n] + (1 - alpha) * Y[n-1]
 * Optimized using bitwise shifts (no floating-point division required).
 */
uint16_t filter_update(SensorFilter_t *filter, uint16_t raw_sample) {
    if (!filter->is_initialized) {
        filter->last_filtered_value = raw_sample;
        filter->is_initialized = true;
        return raw_sample;
    }

    uint32_t prev = filter->last_filtered_value;
    uint32_t current = raw_sample;

    // Y[n] = (X[n] >> Shift) + Y[n-1] - (Y[n-1] >> Shift)
    filter->last_filtered_value = (current >> EMA_ALPHA_SHIFT) + (prev - (prev >> EMA_ALPHA_SHIFT));

    return filter->last_filtered_value;
}

/**
 * Manages actuators based on filtered inputs and hysteresis safety rules.
 */
void actuator_control(ActuatorSystem_t *actuators, uint16_t filtered_temp) {
    if (actuators->cooling_fan == ACTUATOR_OFF) {
        // Trigger fan if temperature exceeds threshold
        if (filtered_temp >= TEMP_THRESHOLD_HIGH) {
            actuators->cooling_fan = ACTUATOR_ON;
            // Hardware-level pin control would go here:
            // e.g., GPIO_WritePin(FAN_GPIO_PORT, FAN_PIN, HIGH);
            printf("[FAN -> ON]\n");
        } else {
            printf("[FAN -> OFF (idle)]\n");
        }
    } else {
        // Turn off fan only if temperature drops below (Threshold - Hysteresis)
        if (filtered_temp < (TEMP_THRESHOLD_HIGH - TEMP_HYSTERESIS)) {
            actuators->cooling_fan = ACTUATOR_OFF;
            // e.g., GPIO_WritePin(FAN_GPIO_PORT, FAN_PIN, LOW);
            printf("[FAN -> OFF]\n");
        } else {
            printf("[FAN -> ON (cooling...)]\n");
        }
    }
}
