/**
 * @brief Convert raw ADC integer value to physical unit (Celsius).
 * Highly optimized, avoids expensive library calls.
 */
float convert_raw_to_temperature(uint16_t raw_adc) {
    // Example linear calibration: 0 ADC = 0°C, 4095 ADC = 100°C
    return ((float)raw_adc / 4095.0f) * 100.0f;
}

/**
 * @brief Infinite Impulse Response (IIR) / Exponential Moving Average (EMA) Filter.
 * Formula: Y[n] = (Alpha * X[n]) + ((1 - Alpha) * Y[n-1])
 * Requires O(1) time complexity and only 5 bytes of RAM.
 */
float filter_sensor_data(EmaFilter_t *filter, float raw_val) {
    if (!filter->is_initialized) {
        filter->filtered_value = raw_val;
        filter->is_initialized = true;
    } else {
        filter->filtered_value = (FILTER_ALPHA * raw_val) + 
                                 ((1.0f - FILTER_ALPHA) * filter->filtered_value);
    }
    return filter->filtered_value;
}

/**
 * @brief Bang-bang controller with hysteresis to manage actuator state.
 * Prevents rapid oscillation (chattering) around the threshold limit.
 */
void manage_actuator(ActuatorDevice_t *actuator, float current_temp) {
    ActuatorState_t previous_state = actuator->state;

    if (actuator->state == ACTUATOR_OFF) {
        if (current_temp > TEMP_THRESHOLD_HIGH) {
            actuator->state = ACTUATOR_ON;
        }
    } else { // ACTUATOR_ON
        if (current_temp < TEMP_THRESHOLD_LOW) {
            actuator->state = ACTUATOR_OFF;
        }
    }

    // Only write to hardware and log if state actually changes (saves CPU cycles/power)
    if (actuator->state != previous_state) {
        mock_hardware_write_gpio(actuator->state);
        actuator->toggle_count++;
    }
}

