// ==========================================
// 1. Memory-Efficient EMA Filter
// ==========================================
class EMAFilter {
private:
    float m_alpha;       // Smoothing factor (0.0 < alpha <= 1.0). Lower = smoother but slower.
    float m_filteredValue;
    bool m_isInitialized;

public:
    // Constexpr constructor allows compile-time initialization where possible
    constexpr EMAFilter(float alpha) 
        : m_alpha(alpha), m_filteredValue(0.0f), m_isInitialized(false) {}

    float filter(float input) {
        if (!m_isInitialized) {
            m_filteredValue = input;
            m_isInitialized = true;
        } else {
            // Formula: Y(n) = alpha * X(n) + (1 - alpha) * Y(n-1)
            m_filteredValue = (m_alpha * input) + ((1.0f - m_alpha) * m_filteredValue);
        }
        return m_filteredValue;
    }

    float getValue() const { return m_filteredValue; }
};

// ==========================================
// 2. Actuator Manager (with Hysteresis)
