class Actuator {
public:
    enum State : uint8_t {
        OFF = 0,
        ON = 1
    };

private:
    State m_state;
    const float m_highThreshold; // Turn ON above this
    const float m_lowThreshold;  // Turn OFF below this

public:
    constexpr Actuator(float lowThresh, float highThresh)
        : m_state(OFF), m_highThreshold(highThresh), m_lowThreshold(lowThresh) {}

    // Updates actuator state based on filtered input and returns the current state
    State update(float filteredValue) {
        if (m_state == OFF && filteredValue > m_highThreshold) {
            m_state = ON;
            hardwareWrite(ON);
        } else if (m_state == ON && filteredValue < m_lowThreshold) {
            m_state = OFF;
            hardwareWrite(OFF);
        }
        return m_state;
    }

    State getState() const { return m_state; }

private:
