```cpp
#include <stdint.h>

// --- CONFIGURATION CONSTANTS ---
// Hardware Pins (Target-dependent)
const uint8_t SENSOR_PIN = A0;
const uint8_t ACTUATOR_PIN = 9;

// Timing Constraints
const uint32_t SAMPLE_INTERVAL_MS = 10;   // Read sensor at 100Hz
const uint32_t TELEMETRY_INTERVAL_MS = 500; // Output data at 2Hz

// Filter Settings
// Alpha determines smoothing: 1.0 = no filter, 0.01 = heavy filtering
const float FILTER_ALPHA = 0.15f; 

// Actuator Hysteresis Thresholds
const float THRESHOLD_HIGH = 650.0f; // Turn actuator ON above this
const float THRESHOLD_LOW  = 550.0f; // Turn actuator OFF below this

// --- CLASS DEFINITIONS ---

/**
 * @brief A lightweight, O(1) space complexity Low-Pass Filter.
 * Uses Exponential Moving Average (EMA).
 */
class ExponentialFilter {
private:
    float m_alpha;
    float m_filteredValue;
    bool m_initialized;

public:
    explicit ExponentialFilter(float alpha) 
        : m_alpha(alpha), m_filteredValue(0.0f), m_initialized(false) {}

    float filter(float rawInput) {
        if (!m_initialized) {
            m_filteredValue = rawInput;
            m_initialized = true;
        } else {
            // Formula: y[n] = alpha * x[n] + (1 - alpha) * y[n-1]
            m_filteredValue = (m_alpha * rawInput) + ((1.0f - m_alpha) * m_filteredValue);
        }
        return m_filteredValue;
    }

    float getValue() const { return m_filteredValue; }
};

/**
 * @brief Manages actuator state using hysteresis.
 */
class ActuatorController {
private:
    uint8_t m_pin;
    bool m_isActive;

public:
    explicit ActuatorController(uint8_t pin) : m_pin(pin), m_isActive(false) {}

    void init() {
        pinMode(m_pin, OUTPUT);
        writeState(false);
    }

    // Update actuator state based on filtered inputs (Hysteresis)
    void update(float currentValue) {
        if (!m_isActive && (currentValue > THRESHOLD_HIGH)) {
            writeState(true);
        } 
        else if (m_isActive && (currentValue < THRESHOLD_LOW)) {
            writeState(false);
        }
    }

    bool isActive() const { return m_isActive; }

private:
    void writeState(bool state) {
        m_isActive = state;
        digitalWrite(m_pin, m_isActive ? HIGH : LOW);
    }
};

// --- SYSTEM INITIALIZATION ---

// Static allocation of objects (Zero Heap Usage)
ExponentialFilter sensorFilter(FILTER_ALPHA);
ActuatorController actuator(ACTUATOR_PIN);

uint32_t lastSampleTime = 0;
uint32_t lastTelemetryTime = 0;

void setup() {
    // Initialize Hardware Serial for telemetry (debugging)
    Serial.begin(115200);

    // Initialize Actuator
    actuator.init();

    // Configure sensor pin
    pinMode(SENSOR_PIN, INPUT);
}

void loop() {
    uint32_t currentTime = millis();

    // Task 1: Sample Sensor and Update Actuator (100 Hz)
    if (currentTime - lastSampleTime >= SAMPLE_INTERVAL_MS) {
        lastSampleTime = currentTime;

        // 1. Read Raw Sensor Data (ADC conversion)
        int16_t rawAdc = analogRead(SENSOR_PIN);

        // 2. Filter data in real-time
        float filteredValue = sensorFilter.filter(static_cast<float>(rawAdc));

        // 3. Manage Actuator based on filtered value
        actuator.update(filteredValue);
    }

    // Task 2: Telemetry Output (2 Hz) - Non-blocking
    if (currentTime - lastTelemetryTime >= TELEMETRY_INTERVAL_MS) {
        lastTelemetryTime = currentTime;

        Serial.print("RAW:");
        Serial.print(analogRead(SENSOR_PIN));
        Serial.print(",FILT:");
        Serial.print(sensorFilter.getValue());
        Serial.print(",ACTUATOR:");
        Serial.println(actuator.isActive() ? 1000 : 0); // Visualized scale
    }
}
```

