// In a real embedded system, you would use `#![no_std]` to exclude the standard library.
// For this runnable demo, we use a few standard utilities to simulate time and I/O.

/// A lightweight, O(1) memory Exponential Moving Average (Low-Pass) Filter.
/// Ideal for resource-constrained systems to smooth out high-frequency sensor noise.
struct EmaFilter {
    alpha: f32, // Smoothing factor between 0.0 and 1.0 (lower = smoother, but slower response)
    prev_filtered: Option<f32>,
}

impl EmaFilter {
    const fn new(alpha: f32) -> Self {
        Self {
            alpha,
            prev_filtered: None,
        }
    }

    /// Filters the incoming raw sensor reading.
    fn filter(&mut self, raw_value: f32) -> f32 {
        let filtered = match self.prev_filtered {
            Some(prev) => (self.alpha * raw_value) + ((1.0 - self.alpha) * prev),
            None => raw_value, // Initialize with the first reading
        };
        self.prev_filtered = Some(filtered);
        filtered
    }
}

