        Self {
            state: ActuatorState::Off,
        }
    }

    /// Updates physical hardware pins based on the desired state.
    /// In a real system, this writes to GPIO registers.
    fn set_state(&mut self, target_state: ActuatorState) {
        if self.state != target_state {
            self.state = target_state;
            // Simulated register write
            println!("   [ACTUATOR] Hardware state changed to: {:?}", self.state);
        }
    }
}

/// Simulated noisy temperature sensor (reads from hardware ADC).
