    tick: usize,
}

impl TempSensor {
    const fn new() -> Self {
        Self { tick: 0 }
    }

    /// Simulates reading an ADC register. 
    /// Generates a base sine wave temperature signal with added high-frequency noise.
    fn read_raw(&mut self) -> f32 {
        self.tick += 1;
        let base_temp = 22.0 + (self.tick as f32 * 0.2).sin() * 5.0; // Slow ambient drift
        let noise = ((self.tick * 7) % 10) as f32 * 0.15 - 0.75;    // Simulated high-frequency electrical noise
        base_temp + noise
    }
}

fn main() {
    // 1. Initialize hardware drivers and filters (allocated on the stack, 0 bytes heap)
    let mut sensor = TempSensor::new();
    let mut filter = EmaFilter::new(0.25); // 25% new data, 75% history
    let mut actuator = ThermalActuator::new();

