// --- 1. SENSOR FILTER (DSP) ---
// Exponential Moving Average (EMA) filter. 
// Uses only 8 bytes of RAM (one f32 for alpha, one f32 for state).
pub struct EmaFilter {
    alpha: f32, // Smoothing factor (0.0 to 1.0). Lower = smoother but slower response.
    stored_value: Option<f32>,
}

impl EmaFilter {
    pub const fn new(alpha: f32) -> Self {
        Self {
            alpha,
            stored_value: None,
        }
    }

    /// Filters the incoming noisy raw sensor data.
    pub fn update(&mut self, raw_input: f32) -> f32 {
        let filtered = match self.stored_value {
            Some(prev_filtered) => {
                // Formula: Y[n] = (α * X[n]) + ((1 - α) * Y[n-1])
                (self.alpha * raw_input) + ((1.0 - self.alpha) * prev_filtered)
            }
            None => raw_input, // Initialize with the first reading
        };
        self.stored_value = Some(filtered);
        filtered
    }
}

