/// An Exponential Moving Average (EMA) filter.
/// This filter is highly resource-efficient because it only needs to store 
/// a single historical data point (`previous_value`).
struct EmaFilter {
    alpha: f32, // Smoothing factor (0.0 to 1.0). Lower = smoother, but slower response.
    previous_value: Option<f32>,
}

impl EmaFilter {
    const fn new(alpha: f32) -> Self {
        Self {
            alpha,
            previous_value: None,
        }
    }

