// In a real bare-metal embedded system, you would uncomment the next line:
// #![no_std] 

/// A lightweight Low-Pass Filter (Exponential Moving Average).
/// It requires zero heap allocation and only 8 bytes of RAM.
struct LowPassFilter {
    alpha: f32, // Smoothing factor (0.0 to 1.0). Lower = smoother but slower response.
    state: Option<f32>,
}

impl LowPassFilter {
    const fn new(alpha: f32) -> Self {
        Self { alpha, state: None }
    }

    /// Filters a new sample. O(1) execution time.
    fn filter(&mut self, sample: f32) -> f32 {
        let filtered = match self.state {
            Some(prev) => (self.alpha * sample) + ((1.0 - self.alpha) * prev),
            None => sample, // Initialize with the first sample
        };
        self.state = Some(filtered);
        filtered
    }
}

/// Representation of a physical GPIO-controlled Actuator (e.g., a cooling valve).
struct CoolantValve {
    is_open: bool,
}

impl CoolantValve {
    const fn new() -> Self {
        Self { is_open: false }
    }

    /// Safely changes the actuator state. 
    /// On real hardware, this would write directly to a GPIO register.
    fn set_state(&mut self, open: bool) {
        if self.is_open != open {
            self.is_open = open;
            // Simulated hardware output
            if open {
                println!("[ACTUATOR] >>> VALVE OPENED (Cooling active) <<<");
            } else {
                println!("[ACTUATOR] >>> VALVE CLOSED <<<");
            }
        }
    }
}

/// Simulated Sensor. In a real system, this would read from I2C/SPI or an ADC register.
struct SimulatedTemperatureSensor {
    step: usize,
}

impl SimulatedTemperatureSensor {
    const fn new() -> Self {
        Self { step: 0 }
    }

    /// Simulates a temperature sensor rising from 18°C to 24°C with heavy high-frequency noise.
    fn read_celsius(&mut self) -> f32 {
        self.step += 1;
        let base_temp = 18.0 + (self.step as f32 * 0.3); // Gradually heating up

        // Pseudo-random noise generator using simple deterministic math (no std::rand needed)
        let noise = (((self.step * 101) % 10) as f32 * 0.4) - 2.0; // Noise between -2.0°C and +2.0°C

        base_temp + noise
    }
}

fn main() {
    // 1. Initialize our system components statically on the stack (No Heap Allocation)
    let mut sensor = SimulatedTemperatureSensor::new();
    let mut filter = LowPassFilter::new(0.2); // Smooths out 80% of high-frequency noise
    let mut valve = CoolantValve::new();

    const TRIGGER_TEMP: f32 = 22.0; // Trigger threshold in Celsius

    println!("Starting Edge Control Loop (Threshold: {:.1}°C)...", TRIGGER_TEMP);
    println!("--------------------------------------------------");

    // 2. Control Loop (Simulating 20 iterations/sensor polls)
    for _ in 0..20 {
        // Step A: Read raw data from hardware
        let raw_temp = sensor.read_celsius();

        // Step B: Filter noise
        let filtered_temp = filter.filter(raw_temp);

        // Step C: Print telemetry (Simulated edge logging)
        println!(
            "Sensor: {:5.2}°C | Filtered: {:5.2}°C | Valve: {}",
            raw_temp,
            filtered_temp,
            if valve.is_open { "ON " } else { "OFF" }
        );

        // Step D: Actuator Logic (Hysteresis or simple threshold)
        if filtered_temp > TRIGGER_TEMP {
            valve.set_state(true);  // Turn on cooling
        } else {
            valve.set_state(false); // Turn off cooling
        }

        // Simulating a real-world delay between sensor samples (e.g., 100ms)
        std::thread::sleep(std::time::Duration::from_millis(100));
    }
}
```

### Why this is highly optimized for resource-constrained edge systems:

1. **Zero Heap Allocations (`#![no_std]` ready):**
   The program allocates all structures (`LowPassFilter`, `CoolantValve`, `SimulatedTemperatureSensor`) directly on the CPU stack. It does not use `Vec`, `Box`, or any dynamic memory allocation, eliminating the risk of Out-Of-Memory (OOM) crashes and heap fragmentation.
2. **Minimal Memory Footprint:**
   The entire state of this system fits into less than **32 bytes** of RAM:
   * `LowPassFilter`: 8 bytes (`f32` alpha + `Option<f32>` state).
   * `CoolantValve`: 1 byte (`bool` state).
   * `SimulatedTemperatureSensor`: 8 bytes (`usize` step count).
3. **Deterministic Performance ($O(1)$ Execution):**
   The Exponential Moving Average (EMA) algorithm requires only **one multiplication, one subtraction, and one addition** per sample. This executes in nanoseconds on modern microcontrollers and has a perfectly predictable execution time, which is critical for real-time actuator control.
4. **No Dangling Pointers or Race Conditions:**
   Rust's ownership model guarantees that the valve and sensor states cannot be accessed concurrently in an unsafe manner, preventing race conditions if you were to move the sensor reading to a DMA (Direct Memory Access) interrupt.

