        width: 800,
        height: 600,
        physics: {
            default: 'arcade', // Lightweight, fast AABB 2D physics
            arcade: {
                gravity: { y: 1000 }, // Realistic downward gravity
                debug: false // Set to true to see collision boxes
            }
        },
        scene: {
            preload: preload,
            create: create,
            update: update
        }
    };

    const game = new Phaser.Game(config);
    let player;
    let platforms;
    let cursors;

    // --- 1. PRELOAD ASSETS ---
    function preload() {
        // Generate our sprite sheet and inject it into Phaser's cache
        const playerCanvas = createProceduralSpritesheet();
        this.textures.addSpriteSheetFromRaster('hero', { 
            data: playerCanvas, 
            frameWidth: 32, 
            frameHeight: 32 
        });
    }

    // --- 2. CREATE GAME WORLD & PHYSICS ---
    function create() {
        // Add a simple sky blue background
        this.cameras.main.setBackgroundColor('#87CEEB');

        // Create a static group for platforms (things that don't move when hit)
        platforms = this.physics.add.staticGroup();

        // Generate level design using colored rectangles
        // Ground
        let ground = this.add.rectangle(400, 568, 800, 64, 0x4d2912);
        let grass = this.add.rectangle(400, 540, 800, 8, 0x228B22);
        platforms.add(ground);
        platforms.add(grass);

        // Floating platforms
        const platCoords = [
            {x: 600, y: 400, w: 200, h: 20},
            {x: 150, y: 250, w: 200, h: 20},
            {x: 400, y: 150, w: 150, h: 20},
            {x: 350, y: 330, w: 100, h: 20}
        ];

        platCoords.forEach(p => {
            let plat = this.add.rectangle(p.x, p.y, p.w, p.h, 0x666666);
            platforms.add(plat);
        });

        // --- PLAYER CREATION & PHYSICS ---
        player = this.physics.add.sprite(100, 450, 'hero');

        // Physics settings
        player.setBounce(0.1); // Small bounce on landing
        player.setCollideWorldBounds(true); // Don't fall off screen limits

        // --- SPRITE ANIMATION SETUP ---
        this.anims.create({
            key: 'walk',
            frames: this.anims.generateFrameNumbers('hero', { start: 0, end: 3 }),
            frameRate: 10,
            repeat: -1 // Loop infinitely
        });

        this.anims.create({
            key: 'idle',
            frames: [ { key: 'hero', frame: 0 } ],
            frameRate: 20
        });

        // --- COLLISION RESOLUTION ---
        // Tells physics system to stop player from falling through platforms
        this.physics.add.collider(player, platforms);

        // --- INPUTS ---
        cursors = this.input.keyboard.createCursorKeys();

        // Add Instructions Text on screen
        this.add.text(16, 16, 'Use Arrow Keys: Left / Right to Move, UP to Jump', {
            fontSize: '18px',
            fill: '#000'
        });
    }

    // --- 3. GAME LOOP (60 FPS) ---
    function update() {
        const speed = 200;
        const jumpForce = -500;

        // Move Left
        if (cursors.left.isDown) {
            player.setVelocityX(-speed);
            player.flipX = true; // Flip sprite horizontally to face left
            player.anims.play('walk', true);
        }
        // Move Right
        else if (cursors.right.isDown) {
            player.setVelocityX(speed);
            player.flipX = false; // Face right
            player.anims.play('walk', true);
        }
        // Idle (No movement)
        else {
            player.setVelocityX(0);
            player.anims.play('idle');
        }

        // Jump (Only if touching the ground/platform)
        if (cursors.up.isDown && player.body.touching.down) {
            player.setVelocityY(jumpForce);
        }
    }
</script>

