        // 2. Create static physics group for platforms
        platforms = this.physics.add.staticGroup();

        // Create the ground platform (tiled texture)
        // Static bodies do not move or react to gravity
        platforms.create(400, 568, 'platform').setScale(2).refreshBody();

        // Create some floating ledges
        platforms.create(600, 400, 'platform');
        platforms.create(50, 250, 'platform');
        platforms.create(750, 220, 'platform');
        platforms.create(400, 150, 'platform');

        // 3. Create Player (Dynamic Physics Body)
        // Dynamic bodies react to gravity, velocity, and collisions
        player = this.physics.add.sprite(100, 450, 'playerSheet');
        player.setBounce(0.15); // Adds a slight bounce on landing
        player.setCollideWorldBounds(true); // Prevent player from falling off screen

