            frames: [
                { key: 'playerSheet', frame: 1 },
                { key: 'playerSheet', frame: 0 },
                { key: 'playerSheet', frame: 2 },
                { key: 'playerSheet', frame: 0 }
            ],
            frameRate: 10,
            repeat: -1 // Loop infinitely
        });

        this.anims.create({
            key: 'jump',
            frames: [{ key: 'playerSheet', frame: 3 }],
            frameRate: 10
        });

