            } else {
                // Player is stationary
                player.anims.play('idle', true);
            }
        }
    }

    // --- PROCEDURAL CANVAS GENERATION ---
    // This helper draws the game textures dynamically in-memory
    function createProceduralTextures(scene) {
        // 1. Generate Platform Texture (400x32 pixels)
        const platCanvas = document.createElement('canvas');
        platCanvas.width = 400;
        platCanvas.height = 32;
        const pCtx = platCanvas.getContext('2d');
        pCtx.fillStyle = '#8B5A2B'; // Brown dirt
        pCtx.fillRect(0, 0, 400, 32);
        pCtx.fillStyle = '#229954'; // Green grass top
        pCtx.fillRect(0, 0, 400, 8);
        scene.textures.addCanvas('platform', platCanvas);

        // 2. Generate Player Sprite Sheet (128x48 total, containing 4 frames of 32x48)
        const playCanvas = document.createElement('canvas');
        playCanvas.width = 128;
        playCanvas.height = 48;
        const ctx = playCanvas.getContext('2d');

        // Helper function to draw frame elements
        function drawPlayerFrame(frameIdx, legOffset, armsUp) {
            const x = frameIdx * 32;

            // Character body (Red suit)
            ctx.fillStyle = '#E74C3C';
            ctx.fillRect(x + 8, 14, 16, 20);

            // Head (Yellow skin)
            ctx.fillStyle = '#F5B041';
            ctx.beginPath();
            ctx.arc(x + 16, 10, 6, 0, Math.PI * 2);
            ctx.fill();

            // Eyes (Blue glasses)
            ctx.fillStyle = '#2471A3';
            ctx.fillRect(x + 12, 7, 4, 3);
            ctx.fillRect(x + 17, 7, 4, 3);

            // Legs (Blue pants / shoes)
            ctx.strokeStyle = '#2E4053';
            ctx.lineWidth = 3;
            if (legOffset === 0) { // Standing legs
                ctx.beginPath();
                ctx.moveTo(x + 12, 34); ctx.lineTo(x + 12, 46);
                ctx.moveTo(x + 20, 34); ctx.lineTo(x + 20, 46);
                ctx.stroke();
            } else if (legOffset === 1) { // Walking Frame 1
                ctx.beginPath();
                ctx.moveTo(x + 12, 34); ctx.lineTo(x + 8, 46);
                ctx.moveTo(x + 20, 34); ctx.lineTo(x + 24, 46);
                ctx.stroke();
            } else if (legOffset === 2) { // Walking Frame 2
                ctx.beginPath();
                ctx.moveTo(x + 12, 34); ctx.lineTo(x + 16, 46);
                ctx.moveTo(x + 20, 34); ctx.lineTo(x + 16, 46);
                ctx.stroke();
            }

            // Arms
            ctx.strokeStyle = '#F5B041';
            ctx.lineWidth = 3;
            ctx.beginPath();
            if (armsUp) { // Jump pose
                ctx.moveTo(x + 8, 18); ctx.lineTo(x + 4, 8);
                ctx.moveTo(x + 24, 18); ctx.lineTo(x + 28, 8);
            } else { // Neutral pose
                ctx.moveTo(x + 8, 18); ctx.lineTo(x + 4, 26);
                ctx.moveTo(x + 24, 18); ctx.lineTo(x + 28, 26);
            }
            ctx.stroke();
        }

        // Draw individual frames to our horizontal canvas strip
        drawPlayerFrame(0, 0, false); // Frame 0: Idle
        drawPlayerFrame(1, 1, false); // Frame 1: Walk Step A
        drawPlayerFrame(2, 2, false); // Frame 2: Walk Step B
        drawPlayerFrame(3, 0, true);  // Frame 3: Jump

        // Convert the canvas elements into Phaser-usable Textures
        scene.textures.addCanvas('playerCanvas', playCanvas);

        // Slice the raw Canvas texture into a sprite sheet of 32x48 frames
        scene.textures.addSpriteSheetFromTexture('playerSheet', {
            name: 'playerCanvas',
            frameWidth: 32,
            frameHeight: 48
        });
    }
</script>

