        // 5. Add Collisions
        // Tells the physics engine to make the player stand on platforms instead of falling through
        this.physics.add.collider(player, platforms);

        // 6. Set up keyboard inputs
        cursors = this.input.keyboard.createCursorKeys();
    }

    // --- GAME LOOP (Runs ~60 times per second) ---
    function update() {
        // Left movement
        if (cursors.left.isDown) {
            player.setVelocityX(-160); // Apply negative horizontal velocity
            player.anims.play('left', true); // Play "left" sprite animation
        }
        // Right movement
        else if (cursors.right.isDown) {
            player.setVelocityX(160); // Apply positive horizontal velocity
            player.anims.play('right', true); // Play "right" sprite animation
        }
        // Idle (No input)
        else {
            player.setVelocityX(0); // Stop horizontal movement
            player.anims.play('turn'); // Play "turn/idle" sprite animation
        }

        // Jumping Physics
        // Player can only jump if they are pressing the UP key AND touching a surface (floor/platform)
        if (cursors.up.isDown && player.body.touching.down) {
            player.setVelocityY(-350); // Apply upward vertical velocity (combating gravity)
        }
    }
</script>

