    const canvas = document.createElement('canvas');
    const ctx = canvas.getContext('2d');

    // Create Player Sprite Sheet (4 frames: Frame 0=Idle, 1&2=Run, 3=Jump)
    canvas.width = 128; // 4 frames x 32px
    canvas.height = 32;

    const drawPlayerFrame = (frame, legOffset, isJumping) => {
        const x = frame * 32;
        // Head & Body (Red coat)
        ctx.fillStyle = '#e74c3c';
        ctx.fillRect(x + 8, 6, 16, 16);
