        ctx.fillStyle = '#ffdbac';
        ctx.fillRect(x + 16, 8, 8, 6);
        // Eye
        ctx.fillStyle = '#2c3e50';
        ctx.fillRect(x + 20, 9, 2, 2);
        // Pants (Blue)
        ctx.fillStyle = '#2980b9';
        ctx.fillRect(x + 8, 22, 16, 4);

        // Legs (Dynamic movement based on frame type)
        ctx.fillStyle = '#2c3e50';
        if (isJumping) {
            ctx.fillRect(x + 8, 26, 4, 3);
            ctx.fillRect(x + 20, 26, 4, 3);
        } else {
            // Alternating legs for run cycle
            ctx.fillRect(x + 10, 26, 4, 6 - legOffset);
            ctx.fillRect(x + 18, 26, 4, 6 - (4 - legOffset));
        }
    };

    drawPlayerFrame(0, 2, false); // Frame 0: Idle
    drawPlayerFrame(1, 0, false); // Frame 1: Run step A
    drawPlayerFrame(2, 4, false); // Frame 2: Run step B
    drawPlayerFrame(3, 2, true);  // Frame 3: Jump

    const playerURL = canvas.toDataURL();

    // Create Platform Texture (Green grass top, brown dirt bottom)
    canvas.width = 32;
    canvas.height = 32;
    ctx.fillStyle = '#8e44ad'; // Purple/Grey dirt blocks
    ctx.fillRect(0, 0, 32, 32);
    ctx.fillStyle = '#2ecc71'; // Green grass top
    ctx.fillRect(0, 0, 32, 6);

    const platformURL = canvas.toDataURL();

    return { playerURL, platformURL };
}

