function create() {
    // Background Sky
    this.cameras.main.setBackgroundColor('#3498db');

    // 1. PHYSICS STATIC PLATFORMS
    platforms = this.physics.add.staticGroup();

    // Create ground platform (repeating the 32x32 texture)
    for (let x = 16; x < 800; x += 32) {
        platforms.create(x, 584, 'platform');
    }

    // Floating Ledges
    platforms.create(600, 450, 'platform');
    platforms.create(632, 450, 'platform');
    platforms.create(664, 450, 'platform');

    platforms.create(300, 350, 'platform');
    platforms.create(332, 350, 'platform');
    platforms.create(364, 350, 'platform');

    platforms.create(150, 200, 'platform');
    platforms.create(182, 200, 'platform');

    // 2. PLAYER CREATION & PHYSICS SETUP
    player = this.physics.add.sprite(100, 450, 'player');
    player.setBounce(0.1); // Slightly bouncy landing
    player.setCollideWorldBounds(true); // Prevent falling off-screen

    // Adjust player physics hitbox for tighter platforming collision
    player.body.setSize(18, 30);
    player.body.setOffset(7, 2);

    // 3. COLLISION RULES
    this.physics.add.collider(player, platforms);

    // 4. SPRITE ANIMATIONS
    this.anims.create({
        key: 'idle',
        frames: [{ key: 'player', frame: 0 }],
        frameRate: 10
    });

    this.anims.create({
        key: 'run',
        frames: this.anims.generateFrameNumbers('player', { start: 1, end: 2 }),
        frameRate: 10,
        repeat: -1 // Loop infinitely
    });

    this.anims.create({
        key: 'jump',
        frames: [{ key: 'player', frame: 3 }],
        frameRate: 10
    });

    // 5. INPUT CONTROLS
    cursors = this.input.keyboard.createCursorKeys();
    wasd = this.input.keyboard.addKeys({
        up: Phaser.Input.Keyboard.KeyCodes.W,
        left: Phaser.Input.Keyboard.KeyCodes.A,
        right: Phaser.Input.Keyboard.KeyCodes.D
    });
}

function update() {
    // 1. HORIZONTAL PHYSICS (Input Handling & Friction)
    const speed = 200;

    if (cursors.left.isDown || wasd.left.isDown) {
        player.setVelocityX(-speed); // Move Left
        player.flipX = true; // Flip sprite graphics to face left
    } 
    else if (cursors.right.isDown || wasd.right.isDown) {
        player.setVelocityX(speed); // Move Right
        player.flipX = false; // Normal sprite graphics facing right
    } 
    else {
        player.setVelocityX(0); // Friction: Stop moving when no keys pressed
    }

    // 2. VERTICAL PHYSICS (Jumping)
    const isJumpingPressed = cursors.up.isDown || wasd.up.isDown || cursors.space.isDown;
    const isGrounded = player.body.touching.down;

    if (isJumpingPressed && isGrounded) {
        player.setVelocityY(-480); // Apply upward velocity
    }

    // 3. ANIMATION STATE MACHINE
    if (!isGrounded) {
        player.anims.play('jump', true); // In air, show jump sprite
    } else if (player.body.velocity.x !== 0) {
        player.anims.play('run', true);  // Moving on ground, run animation
    } else {
        player.anims.play('idle', true); // Idle on ground
    }
}
</script>

</body>
</html>
