4. Use **Arrow Keys / WASD** to move and **Spacebar / Up Arrow** to jump.

```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>2D Platformer - Physics & Sprite Animation</title>
    <style>
        body {
            background-color: #1e1e1e;
            color: #ffffff;
            font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            height: 100vh;
            margin: 0;
            overflow: hidden;
        }
        h1 { margin-bottom: 5px; font-size: 24px; }
        p { margin: 0 0 15px 0; color: #aaaaaa; }
        canvas {
            border: 4px solid #3e3e3e;
            background-color: #87CEEB; /* Sky blue */
            box-shadow: 0 10px 30px rgba(0,0,0,0.5);
        }
    </style>
</head>
<body>

    <h1>2D Platformer Demo</h1>
    <p>Controls: WASD / Arrow Keys to Move | Space to Jump</p>
    <canvas id="gameCanvas" width="800" height="480"></canvas>

<script>
const canvas = document.getElementById('gameCanvas');
const ctx = canvas.getContext('2d');

// ==========================================
// 1. PROCEDURAL SPRITE SHEET GENERATION
// ==========================================
// We dynamically paint a sprite sheet in memory so we don't need external image files.
const spriteSheet = document.createElement('canvas');
spriteSheet.width = 128; // 4 frames of 32x32 pixels
spriteSheet.height = 32;
const sCtx = spriteSheet.getContext('2d');

function drawSpriteFrame(frameIdx, legState, isJumping) {
    const ox = frameIdx * 32; // Offset X

    // Draw Head (Red Helmet)
    sCtx.fillStyle = '#E74C3C';
    sCtx.fillRect(ox + 10, 2, 12, 10);
    sCtx.fillStyle = '#2C3E50'; // Visor
    sCtx.fillRect(ox + 16, 4, 6, 3);

    // Draw Torso (Blue Suit)
    sCtx.fillStyle = '#3498DB';
    sCtx.fillRect(ox + 8, 12, 16, 12);

    // Draw Legs & Shoes (Animated)
    sCtx.strokeStyle = '#2C3E50';
    sCtx.lineWidth = 3;

    if (isJumping) {
        // Legs tucked in
        sCtx.strokeRect(ox + 10, 24, 2, 2);
        sCtx.strokeRect(ox + 20, 24, 2, 2);
    } else if (legState === 'idle') {
        // Straight down
        sCtx.beginPath();
        sCtx.moveTo(ox + 11, 24); sCtx.lineTo(ox + 11, 30);
        sCtx.moveTo(ox + 21, 24); sCtx.lineTo(ox + 21, 30);
        sCtx.stroke();
    } else if (legState === 'walk1') {
        // Left leg forward, right leg back
        sCtx.beginPath();
        sCtx.moveTo(ox + 11, 24); sCtx.lineTo(ox + 7, 30);
        sCtx.moveTo(ox + 21, 24); sCtx.lineTo(ox + 25, 30);
        sCtx.stroke();
    } else if (legState === 'walk2') {
        // Right leg forward, left leg back
        sCtx.beginPath();
        sCtx.moveTo(ox + 11, 24); sCtx.lineTo(ox + 15, 30);
        sCtx.moveTo(ox + 21, 24); sCtx.lineTo(ox + 17, 30);
        sCtx.stroke();
    }
}

// Render our 4 animation frames onto our hidden canvas sheet
drawSpriteFrame(0, 'idle', false);   // Frame 0: Idle
drawSpriteFrame(1, 'walk1', false);  // Frame 1: Walk Frame A
drawSpriteFrame(2, 'walk2', false);  // Frame 2: Walk Frame B
drawSpriteFrame(3, 'idle', true);    // Frame 3: Jump/Airborne

// ==========================================
// 2. PHYSICS ENGINE & GAME CONFIGURATION
// ==========================================
const GRAVITY = 0.5;
const FRICTION = 0.85;

const keys = {};
window.addEventListener('keydown', e => keys[e.code] = true);
window.addEventListener('keyup', e => keys[e.code] = false);

// Platforms (Level geometry)
const platforms = [
    { x: 0, y: 440, width: 800, height: 40 },   // Ground
    { x: 150, y: 330, width: 120, height: 20 }, // Low Platform
    { x: 350, y: 240, width: 150, height: 20 }, // Mid Platform
    { x: 580, y: 180, width: 120, height: 20 }, // High Platform
    { x: 50, y: 150, width: 100, height: 20 }   // Upper-Left Platform
];

const player = {
    x: 100,
    y: 300,
    width: 32,
    height: 32,
    vx: 0,
    vy: 0,
    speed: 1.2,
    jumpForce: -11,
    grounded: false,
    facingLeft: false,

    // Sprite animation variables
    animState: 'idle', // 'idle', 'run', 'jump'
    animTimer: 0,
    currentFrame: 0,

    update() {
        // --- Input Handling ---
        if (keys['KeyD'] || keys['ArrowRight']) {
            this.vx += this.speed;
            this.facingLeft = false;
        }
        if (keys['KeyA'] || keys['ArrowLeft']) {
            this.vx -= this.speed;
            this.facingLeft = true;
        }
        if ((keys['Space'] || keys['KeyW'] || keys['ArrowUp']) && this.grounded) {
            this.vy = this.jumpForce;
            this.grounded = false;
        }

        // --- Apply Physics ---
        this.vy += GRAVITY;       // Apply Gravity
        this.vx *= FRICTION;      // Apply Horizontal Drag

        // --- Axis-Separated Collision Resolution (AABB) ---

        // 1. Resolve Horizontal Movement & Collisions
        this.x += this.vx;
        this.checkCollisions('horizontal');

        // 2. Resolve Vertical Movement & Collisions
        this.y += this.vy;
        this.grounded = false; // Reset grounded before checks
        this.checkCollisions('vertical');

        // Prevent falling out of screen bounds
        if (this.x < 0) this.x = 0;
        if (this.x + this.width > canvas.width) this.x = canvas.width - this.width;

        // --- Animation State Machine ---
        if (!this.grounded) {
            this.animState = 'jump';
            this.currentFrame = 3; // Jump Frame
        } else if (Math.abs(this.vx) > 0.5) {
            this.animState = 'run';
            // Cycle through walk frames 1 and 2
            this.animTimer++;
            if (this.animTimer % 8 === 0) { // Change frame every 8 updates
                this.currentFrame = this.currentFrame === 1 ? 2 : 1;
            }
        } else {
            this.animState = 'idle';
            this.currentFrame = 0; // Idle Frame
        }
    },

    checkCollisions(direction) {
        for (let plat of platforms) {
            // Check Box vs Box intersection
            if (this.x < plat.x + plat.width &&
                this.x + this.width > plat.x &&
                this.y < plat.y + plat.height &&
                this.y + this.height > plat.y) {

                if (direction === 'horizontal') {
                    // If moving right, push out left. If moving left, push out right.
                    if (this.vx > 0) this.x = plat.x - this.width;
                    if (this.vx < 0) this.x = plat.x + plat.width;
                    this.vx = 0;
                } else if (direction === 'vertical') {
                    // If falling down, land on top. If moving up, bump head underneath.
                    if (this.vy > 0) {
                        this.y = plat.y - this.height;
                        this.grounded = true;
                        this.vy = 0;
                    } else if (this.vy < 0) {
                        this.y = plat.y + plat.height;
                        this.vy = 0;
                    }
                }
            }
        }
    },

    draw() {
        ctx.save();
        if (this.facingLeft) {
            // Mirror image horizontally if facing left
            ctx.scale(-1, 1);
            // After scaling, coordinates are inverted on the X-axis
            ctx.drawImage(
                spriteSheet, 
                this.currentFrame * 32, 0, 32, 32, // Source dimensions (clipped frame)
                -this.x - this.width, this.y, 32, 32 // Destination dimensions
            );
        } else {
            ctx.drawImage(
                spriteSheet, 
                this.currentFrame * 32, 0, 32, 32, 
                this.x, this.y, 32, 32
            );
        }
        ctx.restore();
    }
};

// ==========================================
// 3. MAIN GAME LOOP
// ==========================================
function gameLoop() {
    // Clear the screen (Sky blue color reset)
    ctx.fillStyle = '#87CEEB';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // Draw Background Decor (Simple Clouds & Hills)
    ctx.fillStyle = '#7BCD7B'; // Back hills
    ctx.beginPath(); ctx.arc(200, 440, 150, Math.PI, 0); ctx.fill();
    ctx.beginPath(); ctx.arc(600, 440, 200, Math.PI, 0); ctx.fill();

    // Update Player Physics
    player.update();

    // Draw Level Platforms
    ctx.fillStyle = '#2E7D32'; // Grass Top
    for (let plat of platforms) {
        ctx.fillRect(plat.x, plat.y, plat.width, plat.height);
        // Soil underneath
        ctx.fillStyle = '#8D6E63';
        ctx.fillRect(plat.x, plat.y + 5, plat.width, plat.height - 5);
        ctx.fillStyle = '#2E7D32';
    }

    // Draw Animated Player
    player.draw();

    // Loop
    requestAnimationFrame(gameLoop);
}

// Start Game
gameLoop();
</script>
</body>
</html>
```

### Key Architectural Concepts Demonstrated:
1. **Euler Integration:** The core physics updates positions based on velocity and accumulates acceleration (`this.vy += GRAVITY`).
2. **Axis-Separated Collisions (AABB):** Standard 2D engine math dictates resolving horizontal movement and collisions *separately* from vertical ones. This prevents the player from getting stuck on corner edges of platforms.
3. **Sprite-Sheet Clipping:** Uses `ctx.drawImage` with 9 arguments to grab a specific $32 \times 32$ sub-region from the generated master sprite sheet, flipping it horizontally on-the-fly using canvas context matrices (`ctx.scale(-1, 1)`).

