    sCtx.fillRect(18, 24, 4, 8); // Leg 2

    // Frame 1: Walk Cycle 1 (Left foot forward, right foot back)
    drawBody(32, 0, '#e74c3c');
    sCtx.fillStyle = '#95a5a6';
    sCtx.fillRect(32 + 6, 24, 4, 8); 
    sCtx.fillRect(32 + 18, 24, 4, 8);

    // Frame 2: Walk Cycle 2 (Legs crossed/together)
    drawBody(64, 0, '#e74c3c');
    sCtx.fillStyle = '#95a5a6';
    sCtx.fillRect(64 + 14, 24, 4, 8);

    // Frame 3: Walk Cycle 3 (Right foot forward, left foot back)
    drawBody(96, 0, '#e74c3c');
    sCtx.fillStyle = '#95a5a6';
    sCtx.fillRect(96 + 10, 24, 4, 8);
    sCtx.fillRect(96 + 22, 24, 4, 8);

    // Frame 4: Jump (Legs bent and tucked up)
    drawBody(128, -2, '#e74c3c'); // Draw slightly higher
    sCtx.fillStyle = '#95a5a6';
    sCtx.fillRect(128 + 10, 22, 4, 6);
    sCtx.fillRect(128 + 18, 22, 4, 6);
}
generateSprites();

// ==========================================
// 2. PHYSICS ENGINE & WORLD DEFINITION
// ==========================================
const GRAVITY = 0.5;
const FRICTION = 0.85;

const player = {
    x: 100,
    y: 300,
    width: 32,
    height: 32,
    vx: 0,
    vy: 0,
    speed: 0.8,
    maxSpeed: 5,
    jumpForce: -11,
    onGround: false,
    facingLeft: false,

    // Animation variables
    animTimer: 0,
    animFrame: 0,
    state: 'idle' // 'idle', 'walk', 'jump'
};

const platforms = [
    { x: 0, y: 400, w: 800, h: 50 },     // Ground floor
    { x: 150, y: 300, w: 150, h: 20 },   // Floating platform 1
    { x: 400, y: 220, w: 180, h: 20 },   // Floating platform 2
    { x: 630, y: 130, w: 120, h: 20 },   // Floating platform 3
    { x: 50, y: 180, w: 150, h: 20 }     // Floating platform 4
];

// Input handling
const keys = {};
window.addEventListener('keydown', e => keys[e.code] = true);
window.addEventListener('keyup', e => keys[e.code] = false);

// AABB Collision utility
function rectCollision(r1, r2) {
    return r1.x < r2.x + r2.w &&
           r1.x + r1.width > r2.x &&
           r1.y < r2.y + r2.h &&
           r1.y + r1.height > r2.y;
}

// ==========================================
// 3. GAME LOOP & STATE MACHINES
// ==========================================
function update() {
    // Horizontal Movement Input
    if (keys['ArrowRight'] || keys['KeyD']) {
        player.vx += player.speed;
        player.facingLeft = false;
    } else if (keys['ArrowLeft'] || keys['KeyA']) {
        player.vx -= player.speed;
        player.facingLeft = true;
    }

    // Jump Input (Only if grounded)
    if ((keys['ArrowUp'] || keys['KeyW'] || keys['Space']) && player.onGround) {
        player.vy = player.jumpForce;
        player.onGround = false;
    }

    // Apply Physics forces
    player.vy += GRAVITY;
    player.vx *= FRICTION;

    // Clamp velocity
    if (player.vx > player.maxSpeed) player.vx = player.maxSpeed;
    if (player.vx < -player.maxSpeed) player.vx = -player.maxSpeed;

    // --- Split-Axis Collision Resolution ---

    // 1. Resolve X Axis
    player.x += player.vx;
    for (let p of platforms) {
        if (rectCollision(player, p)) {
            if (player.vx > 0) player.x = p.x - player.width; // Collide Right
            if (player.vx < 0) player.x = p.x + p.w;          // Collide Left
            player.vx = 0;
        }
    }

    // 2. Resolve Y Axis
    player.y += player.vy;
    player.onGround = false;
    for (let p of platforms) {
        if (rectCollision(player, p)) {
            if (player.vy > 0) { // Colliding downward (landing)
                player.y = p.y - player.height;
                player.vy = 0;
                player.onGround = true;
            } else if (player.vy < 0) { // Colliding upward (ceiling collision)
                player.y = p.y + p.h;
                player.vy = 0;
            }
        }
    }

    // Boundary constraints
    if (player.x < 0) player.x = 0;
    if (player.x > canvas.width - player.width) player.x = canvas.width - player.width;

    // --- Sprite Animation State Machine ---
    if (!player.onGround) {
        player.state = 'jump';
        player.animFrame = 4; // Jump frame (constant frame)
    } else if (Math.abs(player.vx) > 0.1) {
        player.state = 'walk';
        player.animTimer++;
        if (player.animTimer > 6) { // Speed of frame switches
            player.animFrame = (player.animFrame % 3) + 1; // Cycle through frames 1, 2, 3
            player.animTimer = 0;
        }
    } else {
        player.state = 'idle';
        player.animFrame = 0; // Frame 0
    }
}

function draw() {
    // Clear Screen
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Draw Platforms
    ctx.fillStyle = '#4a4e69';
    for (let p of platforms) {
        ctx.fillRect(p.x, p.y, p.w, p.h);
        // Draw a light accent top edge to make them look nice
        ctx.fillStyle = '#9a8c98';
        ctx.fillRect(p.x, p.y, p.w, 4);
        ctx.fillStyle = '#4a4e69';
    }

    // Draw Sprite Animation
    ctx.save();

    // Position handling for flipping sprites
    if (player.facingLeft) {
        ctx.translate(player.x + player.width, player.y);
        ctx.scale(-1, 1); // Flip horizontally
        ctx.drawImage(spriteSheet, player.animFrame * 32, 0, 32, 32, 0, 0, player.width, player.height);
    } else {
        ctx.translate(player.x, player.y);
        ctx.drawImage(spriteSheet, player.animFrame * 32, 0, 32, 32, 0, 0, player.width, player.height);
    }

    ctx.restore();
}

function loop() {
    update();
    draw();
    requestAnimationFrame(loop);
}

// Start Game Loop
loop();
</script>

</body>
</html>
```

