            }
        } 
        else if (cursors.right.isDown) {
            player.setVelocityX(250);  // Move Right
            player.flipX = false;      // Don't flip sprite
            if (player.body.touching.down) {
                player.anims.play('walk', true);
            }
        } 
        else {
            player.setVelocityX(0);    // Stop moving horizontal
            if (player.body.touching.down) {
