        Use <b>A/D</b> or <b>Left/Right Arrows</b> to Move. Press <b>Space</b> or <b>W</b> to Jump.
    </div>

<script>
const canvas = document.getElementById('gameCanvas');
const ctx = canvas.getContext('2d');

// --- INPUT HANDLING ---
const keys = {};
window.addEventListener('keydown', e => keys[e.code] = true);
window.addEventListener('keyup', e => keys[e.code] = false);

// --- PHYSICS CONFIGURATION ---
const PHYSICS = {
    gravity: 0.6,
    friction: 0.82,
    acceleration: 0.8,
    maxSpeed: 6,
    jumpForce: -12
};

// --- WORLD DATA ---
const platforms = [
    // Ground
    { x: 0, y: 400, width: 800, height: 50, color: '#0f3460' },
    // Floating platforms
    { x: 150, y: 300, width: 150, height: 20, color: '#e94560' },
    { x: 450, y: 250, width: 200, height: 20, color: '#e94560' },
    { x: 100, y: 180, width: 120, height: 20, color: '#e94560' },
    { x: 350, y: 120, width: 100, height: 20, color: '#e94560' }
];

// --- PLAYER OBJECT ---
const player = {
    x: 100,
    y: 300,
    width: 32,
    height: 48,
    vx: 0,
    vy: 0,
    grounded: false,
    facingLeft: false,

    // Animation State Machine
    anim: {
        state: 'idle', // 'idle', 'run', 'jump'
        frame: 0,
        tick: 0,
        ticksPerFrame: 8 // Control speed of animation
    }
};

// --- SPRITE ANIMATOR (Procedural Sprites) ---
// Since we don't have external assets, this draws the frames dynamically 
// simulating a sprite sheet.
function drawPlayerSprite(ctx, x, y, width, height, state, frame, facingLeft) {
    ctx.save();

    // Flip sprite if facing left
    if (facingLeft) {
        ctx.translate(x + width, y);
        ctx.scale(-1, 1);
    } else {
        ctx.translate(x, y);
    }

    // Core Colors
    const skinColor = '#ffb4a2';
    const shirtColor = '#e94560';
    const pantsColor = '#4e89ae';

    // Body dimensions relative to width/height
    const headSize = 14;
    const bodyY = headSize;
    const bodyHeight = 20;

    // Draw Legs (Animated)
    ctx.fillStyle = pantsColor;
    let leftLegOffset = 0;
    let rightLegOffset = 0;

    if (state === 'run') {
        // Swing legs back and forth based on frame index
        if (frame === 0) { leftLegOffset = -6; rightLegOffset = 6; }
        else if (frame === 1) { leftLegOffset = 0; rightLegOffset = 0; }
        else if (frame === 2) { leftLegOffset = 6; rightLegOffset = -6; }
        else if (frame === 3) { leftLegOffset = 0; rightLegOffset = 0; }
    } else if (state === 'jump') {
        leftLegOffset = -3; // Tuck legs up slightly
        rightLegOffset = 3;
    }

    // Left Leg
    ctx.fillRect(6, bodyY + bodyHeight, 6, height - (bodyY + bodyHeight) + (state === 'jump' ? -4 : 0));
    // Right Leg
    ctx.fillRect(width - 12, bodyY + bodyHeight, 6, height - (bodyY + bodyHeight) + (state === 'jump' ? -4 : 0));

    // Draw Torso
    ctx.fillStyle = shirtColor;
    let torsoSquish = 0;
    if (state === 'idle' && frame === 1) torsoSquish = 2; // Breathing effect
    ctx.fillRect(4, bodyY + torsoSquish, width - 8, bodyHeight - torsoSquish);

    // Draw Arms
    ctx.fillStyle = shirtColor;
    if (state === 'run') {
        // Swing arms opposite to legs
        if (frame === 0) ctx.fillRect(width - 4, bodyY + 4, 4, 12);
        else if (frame === 2) ctx.fillRect(0, bodyY + 4, 4, 12);
    } else {
        // Arms down at sides
        ctx.fillRect(1, bodyY + 4, 3, 12);
        ctx.fillRect(width - 4, bodyY + 4, 3, 12);
    }

    // Draw Head
    ctx.fillStyle = skinColor;
    ctx.fillRect(width/2 - headSize/2, torsoSquish, headSize, headSize);

    // Draw Eyes (Directional look)
    ctx.fillStyle = '#000000';
    ctx.fillRect(width/2 + 2, torsoSquish + 4, 2, 3); // Eye
    ctx.fillStyle = '#55e6c1'; // Hair/Cap decoration
    ctx.fillRect(width/2 - headSize/2, torsoSquish, headSize, 3);

    ctx.restore();
}

// --- COLLISION RESOLUTION (AABB) ---
function checkCollision(rect1, rect2) {
    return rect1.x < rect2.x + rect2.width &&
           rect1.x + rect1.width > rect2.x &&
           rect1.y < rect2.y + rect2.height &&
           rect1.y + rect1.height > rect2.y;
}

// --- GAME LOOP ---
function update() {
    // 1. INPUT PROCESSING
    if (keys['ArrowLeft'] || keys['KeyA']) {
        player.vx -= PHYSICS.acceleration;
        if (player.vx < -PHYSICS.maxSpeed) player.vx = -PHYSICS.maxSpeed;
        player.facingLeft = true;
    } else if (keys['ArrowRight'] || keys['KeyD']) {
        player.vx += PHYSICS.acceleration;
        if (player.vx > PHYSICS.maxSpeed) player.vx = PHYSICS.maxSpeed;
        player.facingLeft = false;
    } else {
        player.vx *= PHYSICS.friction; // Apply deceleration
        if (Math.abs(player.vx) < 0.1) player.vx = 0;
    }

    if ((keys['Space'] || keys['KeyW'] || keys['ArrowUp']) && player.grounded) {
        player.vy = PHYSICS.jumpForce;
        player.grounded = false;
    }

    // Apply Gravity
    player.vy += PHYSICS.gravity;

    // 2. PHYSICS RESOLUTION (Separated Axes to prevent wall clipping)

    // Move Horizontally
    player.x += player.vx;
    for (let platform of platforms) {
        if (checkCollision(player, platform)) {
            // Colliding from left
            if (player.vx > 0) {
                player.x = platform.x - player.width;
            }
            // Colliding from right
            else if (player.vx < 0) {
                player.x = platform.x + platform.width;
            }
            player.vx = 0;
        }
    }

    // Move Vertically
    player.grounded = false;
    player.y += player.vy;
    for (let platform of platforms) {
        if (checkCollision(player, platform)) {
            // Falling down onto platform
            if (player.vy > 0) {
                player.y = platform.y - player.height;
                player.vy = 0;
                player.grounded = true;
            }
            // Jumping up into ceiling
            else if (player.vy < 0) {
                player.y = platform.y + platform.height;
                player.vy = 0;
            }
        }
    }

    // Prevent player from falling off screen boundaries
    if (player.x < 0) player.x = 0;
    if (player.x + player.width > canvas.width) player.x = canvas.width - player.width;
    if (player.y > canvas.height) { // Respawn
        player.x = 100;
        player.y = 100;
        player.vx = 0;
        player.vy = 0;
    }

    // 3. ANIMATION STATE MACHINE UPDATE
    if (!player.grounded) {
        player.anim.state = 'jump';
        player.anim.frame = 0;
    } else if (Math.abs(player.vx) > 0.5) {
        player.anim.state = 'run';
    } else {
        player.anim.state = 'idle';
    }

    // Increment Animation Frames
    player.anim.tick++;
    if (player.anim.tick >= player.anim.ticksPerFrame) {
        player.anim.tick = 0;
        player.anim.frame++;

        // Define animation loops
        if (player.anim.state === 'idle') {
            if (player.anim.frame >= 2) player.anim.frame = 0; // 2 idle frames
        } else if (player.anim.state === 'run') {
            if (player.anim.frame >= 4) player.anim.frame = 0; // 4 run frames
        } else if (player.anim.state === 'jump') {
            player.anim.frame = 0; // 1 static jump frame
        }
    }

    // 4. RENDERING
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Draw Platforms
    for (let platform of platforms) {
        ctx.fillStyle = platform.color;
        ctx.fillRect(platform.x, platform.y, platform.width, platform.height);

        // Draw 3D-ish edge highlight
        ctx.fillStyle = 'rgba(255, 255, 255, 0.1)';
        ctx.fillRect(platform.x, platform.y, platform.width, 4);
    }

    // Draw Player
    drawPlayerSprite(
        ctx, 
        player.x, 
        player.y, 
        player.width, 
        player.height, 
        player.anim.state, 
        player.anim.frame, 
        player.facingLeft
    );

    // Request next frame
    requestAnimationFrame(update);
}

// Start Game Loop
update();
</script>
</body>
</html>
