                vec3 colorA = vec3(0.0, 0.8, 1.0); // Cyan
                vec3 colorB = vec3(0.8, 0.0, 1.0); // Magenta
                vec3 dynamicBase = mix(colorA, colorB, sin(uTime + vUv.x * 6.28) * 0.5 + 0.5);

