                vec3 finalColor = mix(dynamicBase, uGlowColor, fresnel * 0.5) + (vec3(fresnel) * 1.2);

                // Make the center slightly semi-transparent, and edges highly opaque
                float alpha = clamp(fresnel + 0.3, 0.0, 1.0);

