                vec3 displacedPosition = position;
                float wave = sin(position.x * 2.0 + uTime * 3.0) * 0.15;
                wave += cos(position.y * 2.0 + uTime * 2.0) * 0.15;
                displacedPosition += normal * wave;

                // 2. Transform normals and positions to World Space
                vNormal = normalize(normalMatrix * normal);
                vec4 worldPos = modelMatrix * vec4(displacedPosition, 1.0);
                vWorldPosition = worldPos.xyz;

                // 3. Project positions to screen space
                gl_Position = projectionMatrix * viewMatrix * worldPos;
            }
        `;

        // Fragment Shader: Implements dynamic lighting equations (Phong Model)
        const fragmentShaderCode = `
            uniform vec3 uLightPos;
            uniform vec3 uLightColor;
            uniform vec3 uAmbientColor;
            uniform vec3 uBaseColor;

            varying vec3 vNormal;
            varying vec3 vWorldPosition;

            void main() {
                vec3 normal = normalize(vNormal);

                // 1. Calculate Vector Directions
                vec3 lightDir = normalize(uLightPos - vWorldPosition);
                vec3 viewDir = normalize(cameraPosition - vWorldPosition);
                vec3 reflectDir = reflect(-lightDir, normal);

                // 2. Ambient Term
                vec3 ambient = uAmbientColor * uBaseColor;

                // 3. Diffuse Term (Lambertian Reflection)
                float diff = max(dot(normal, lightDir), 0.0);
                vec3 diffuse = diff * uLightColor * uBaseColor;

                // 4. Specular Term (Phong Glossy Highlights)
                float shininess = 64.0;
                float spec = pow(max(dot(viewDir, reflectDir), 0.0), shininess);
                vec3 specular = spec * vec3(1.0); // White specular highlight

                // 5. Light Distance Attenuation
                float dist = length(uLightPos - vWorldPosition);
                float attenuation = 1.0 / (1.0 + 0.1 * dist + 0.05 * (dist * dist));

                // 6. Combine all components
                vec3 finalColor = ambient + (diffuse + specular) * attenuation;

                gl_FragColor = vec4(finalColor, 1.0);
            }
        `;

        // --- APPLICATION SETUP ---

        // 1. Scene, Camera, and Renderer setup
        const scene = new THREE.Scene();
        const camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 100);
        camera.position.set(0, 0, 5);

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
        document.body.appendChild(renderer.domElement);

        // 2. Add Orbit Controls
        const controls = new OrbitControls(camera, renderer.domElement);
        controls.enableDamping = true;
        controls.dampingFactor = 0.05;

        // 3. Define Shader Uniforms
        const shaderUniforms = {
            uTime: { value: 0.0 },
            uLightPos: { value: new THREE.Vector3(0, 0, 0) },
            uLightColor: { value: new THREE.Color(0x00ffcc) }, // Cyan dynamic light
            uAmbientColor: { value: new THREE.Color(0x111122) }, // Dark blue-gray ambient
            uBaseColor: { value: new THREE.Color(0x4433aa) } // Base Royal Purple mesh color
        };

        // 4. Create Material using the Custom Shaders
        const customShaderMaterial = new THREE.ShaderMaterial({
            vertexShader: vertexShaderCode,
            fragmentShader: fragmentShaderCode,
            uniforms: shaderUniforms,
            side: THREE.DoubleSide
        });

        // 5. Create Scene Meshes
        // Main Mesh: Complex geometry to show off light gradients
        const geometry = new THREE.TorusKnotGeometry(1, 0.35, 150, 20);
        const torusKnot = new THREE.Mesh(geometry, customShaderMaterial);
        scene.add(torusKnot);

        // Dynamic Light Visualizer (Sphere representing the light source)
        const lightVisualizerGeo = new THREE.SphereGeometry(0.1, 16, 16);
        const lightVisualizerMat = new THREE.MeshBasicMaterial({ color: 0xffffff });
        const lightVisualizer = new THREE.Mesh(lightVisualizerGeo, lightVisualizerMat);
        scene.add(lightVisualizer);

        // --- ANIMATION LOOP ---

        const clock = new THREE.Clock();

        function animate() {
            requestAnimationFrame(animate);

            const elapsedTime = clock.getElapsedTime();

            // 1. Update Shader Time uniform
            shaderUniforms.uTime.value = elapsedTime;

            // 2. Animate Dynamic Light position in orbit
            const radius = 3.5;
            const lightX = Math.cos(elapsedTime * 1.5) * radius;
            const lightY = Math.sin(elapsedTime * 1.0) * (radius * 0.5);
            const lightZ = Math.sin(elapsedTime * 1.5) * radius;

            const lightPos = new THREE.Vector3(lightX, lightY, lightZ);
            shaderUniforms.uLightPos.value.copy(lightPos);
            lightVisualizer.position.copy(lightPos); // Move the physical sphere with the shader light position

            // 3. Keep light color shifting slightly for visual interest
            shaderUniforms.uLightColor.value.setHSL((elapsedTime * 0.05) % 1.0, 1.0, 0.5);
            lightVisualizer.material.color.copy(shaderUniforms.uLightColor.value);

            // 4. Update Camera controls
            controls.update();

            // 5. Render Scene
            renderer.render(scene, camera);
        }

        // --- WINDOW RESIZING ---

        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        // Start loop
        animate();
    </script>
