        import * as THREE from 'three';
        import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

        // --- GLSL SHADERS ---

        const vertexShader = `
            uniform float uTime;
            varying vec3 vWorldNormal;
            varying vec3 vWorldPosition;

            void main() {
                // Procedural wave displacement effect (Shader Effect)
                float displacement = sin(position.x * 3.0 + uTime * 2.0) 
                                   * cos(position.y * 3.0 + uTime * 2.0) * 0.15;

                // Displace along the vertex normal
                vec3 displacedPosition = position + (normal * displacement);

                // Calculate world space positions
                vec4 worldPosition = modelMatrix * vec4(displacedPosition, 1.0);
                vWorldPosition = worldPosition.xyz;

                // Pass transformed normal to fragment shader
                vWorldNormal = normalize(mat3(modelMatrix) * normal);

                gl_Position = projectionMatrix * viewMatrix * worldPosition;
            }
