        const fragmentShader = `
            uniform vec3 uLightPosition;
            uniform vec3 uCameraPosition;
            uniform float uTime;

            varying vec3 vWorldNormal;
            varying vec3 vWorldPosition;

            void main() {
                vec3 N = normalize(vWorldNormal);
                vec3 V = normalize(uCameraPosition - vWorldPosition);
                vec3 L = normalize(uLightPosition - vWorldPosition);
                vec3 H = normalize(L + V); // Halfway vector for Blinn-Phong

                // 1. Procedural Iridescent Base Color (Dynamic effect)
                vec3 colorA = vec3(0.1, 0.8, 0.9); // Cyan
                vec3 colorB = vec3(0.9, 0.1, 0.6); // Magenta
                float mixFactor = sin(vWorldPosition.y * 2.0 + uTime) * 0.5 + 0.5;
                vec3 baseColor = mix(colorA, colorB, mixFactor);

                // 2. Fresnel Effect (Outer rim glow)
                float fresnel = pow(1.0 - max(dot(N, V), 0.0), 3.0);
                vec3 rimColor = vec3(0.0, 1.0, 0.8) * fresnel * 0.8;

                // 3. Dynamic Ambient Lighting
                vec3 ambient = vec3(0.05, 0.05, 0.08) * baseColor;

                // 4. Dynamic Diffuse Lighting (Warm yellow-white light)
                float diff = max(dot(N, L), 0.0);
                vec3 lightColor = vec3(1.0, 0.9, 0.7);
                vec3 diffuse = diff * baseColor * lightColor;

                // 5. Dynamic Specular Highlights (Blinn-Phong)
                float shininess = 64.0;
                float spec = pow(max(dot(N, H), 0.0), shininess);
                vec3 specular = spec * vec3(1.0) * 0.6; // White specular

                // Combine lighting components
                vec3 finalColor = ambient + diffuse + specular + rimColor;

                // Simple tone-mapping and Gamma correction
                finalColor = finalColor / (finalColor + vec3(1.0)); // Reinhard tonemapping
                finalColor = pow(finalColor, vec3(1.0 / 2.2));     // Gamma Correction

                gl_FragColor = vec4(finalColor, 1.0);
            }
        `;

