        const controls = new OrbitControls(camera, renderer.domElement);
        controls.enableDamping = true;
        controls.dampingFactor = 0.05;
        controls.maxPolarAngle = Math.PI / 2 - 0.05; // Don't let camera go below ground

        // ============================================================================
        // 2. DYNAMIC LIGHTS & ENVIRONMENT
        // ============================================================================
        // Soft ambient light
        const ambientLight = new THREE.AmbientLight(0x111827, 0.5);
        scene.add(ambientLight);

        // Moving Point Light (Casts shadows)
        const pointLight = new THREE.PointLight(0xffaa44, 15, 30, 1.5);
        pointLight.castShadow = true;
        pointLight.shadow.mapSize.width = 1024;
        pointLight.shadow.mapSize.height = 1024;
        pointLight.shadow.bias = -0.005;
        scene.add(pointLight);

        // Visual helper representation of the moving light
        const lightHelperGeo = new THREE.SphereGeometry(0.15, 16, 16);
        const lightHelperMat = new THREE.MeshBasicMaterial({ color: 0xffaa44 });
        const lightHelper = new THREE.Mesh(lightHelperGeo, lightHelperMat);
        scene.add(lightHelper);

        // Static Ground Plane (Reacts to the moving shadow)
        const floorGeo = new THREE.PlaneGeometry(50, 50);
        const floorMat = new THREE.MeshStandardMaterial({ 
            color: 0x1f2937, 
            roughness: 0.8, 
            metalness: 0.2 
        });
        const floor = new THREE.Mesh(floorGeo, floorMat);
        floor.rotation.x = -Math.PI / 2;
        floor.position.y = -2;
        floor.receiveShadow = true;
        scene.add(floor);

        // Grid helper to show spatial orientation
        const grid = new THREE.GridHelper(40, 40, 0x374151, 0x1f2937);
        grid.position.y = -1.99;
        scene.add(grid);

        // ============================================================================
        // 3. CUSTOM GLSL SHADER EFFECT
        // ============================================================================
        const customShaderUniforms = {
            uTime: { value: 0.0 },
            uLightPos: { value: new THREE.Vector3() }
        };

        const customShaderMaterial = new THREE.ShaderMaterial({
            uniforms: customShaderUniforms,

            // --- VERTEX SHADER ---
            // Handles geometry. Distorts the shape dynamically over time.
            vertexShader: `
                uniform float uTime;
                varying vec3 vNormal;
                varying vec3 vViewPosition;
                varying vec3 vWorldPosition;

                void main() {
                    // Pass normals to fragment shader
                    vNormal = normalize(normalMatrix * normal);

                    // Wave deformation logic based on position and time
                    vec3 pos = position;
                    float wave = sin(pos.x * 3.0 + uTime * 2.0) * cos(pos.y * 3.0 + uTime * 2.0) * 0.15;
                    pos += normal * wave; // Push vertex out along its normal vector

                    vec4 mvPosition = modelViewMatrix * vec4(pos, 1.0);
                    vViewPosition = -mvPosition.xyz;
                    vWorldPosition = (modelMatrix * vec4(pos, 1.0)).xyz;

                    gl_Position = projectionMatrix * mvPosition;
                }
            `,

            // --- FRAGMENT SHADER ---
            // Handles pixels. Renders moving dynamic colors, dynamic diffuse lighting, and Fresnel glow.
            fragmentShader: `
                uniform float uTime;
                uniform vec3 uLightPos;
                varying vec3 vNormal;
                varying vec3 vViewPosition;
                varying vec3 vWorldPosition;

                void main() {
                    vec3 normal = normalize(vNormal);
                    vec3 viewDir = normalize(vViewPosition);
                    vec3 lightDir = normalize(uLightPos - vWorldPosition);

                    // 1. Dynamic light calculation (Diffuse)
                    float diffuse = max(dot(normal, lightDir), 0.0);

                    // 2. Custom holographic/iridescent base coloring cycling over time
                    vec3 baseColor = 0.5 + 0.5 * cos(uTime + normal.xyx + vec3(0.0, 2.0, 4.0));

                    // 3. Fresnel (rim lighting) calculation for glowing outlines
                    float rim = 1.0 - max(dot(normal, vec3(0.0, 0.0, 1.0)), 0.0);
                    rim = pow(rim, 3.0); // Sharpen rim effect
                    vec3 rimColor = vec3(0.0, 0.8, 1.0) * rim * (sin(uTime * 4.0) * 0.3 + 0.7);

                    // Combine calculations
                    vec3 finalColor = baseColor * (diffuse + 0.25) + rimColor;

                    gl_FragColor = vec4(finalColor, 1.0);
                }
            `
        });

        // Instantiate Mesh (Torus Knot geometry shows off lighting and shadows very well)
        const geometry = new THREE.TorusKnotGeometry(1, 0.35, 150, 20);
        const customMesh = new THREE.Mesh(geometry, customShaderMaterial);
        customMesh.castShadow = true;
        customMesh.receiveShadow = true;
        scene.add(customMesh);

        // ============================================================================
        // 4. ANIMATION LOOP & WINDOW RESIZING
        // ============================================================================
        const clock = new THREE.Clock();

        function animate() {
            requestAnimationFrame(animate);

            const elapsedTime = clock.getElapsedTime();

            // 1. Update Shader Uniforms
            customShaderUniforms.uTime.value = elapsedTime;

            // 2. Animate Point Light Position in a circular orbit
            const lightX = Math.sin(elapsedTime * 0.8) * 4.5;
            const lightZ = Math.cos(elapsedTime * 0.8) * 4.5;
            const lightY = 1.5 + Math.sin(elapsedTime * 1.5) * 0.5; // subtle bobbing up and down

            pointLight.position.set(lightX, lightY, lightZ);
            lightHelper.position.set(lightX, lightY, lightZ); // align helper visual with actual light source

            // Pass the updated light position to our custom shader
            customShaderUniforms.uLightPos.value.copy(pointLight.position);

            // 3. Rotate the main 3D Mesh
            customMesh.rotation.y = elapsedTime * 0.15;
            customMesh.rotation.x = elapsedTime * 0.05;

            // 4. Update Camera controls & Render Scene
            controls.update();
            renderer.render(scene, camera);
        }

        // Handle window scaling gracefully
        window.addEventListener('resize', onWindowResize, false);
        function onWindowResize() {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        }

        // Run application loop
        animate();
    </script>
</body>
</html>
