To write a custom physics plugin that is highly performant and compatible with major commercial engines (like Unity, Godot, or Unreal), the best approach is to write a **Native C++ Plugin with a C-compatible ABI (Application Binary Interface)**. 

This approach allows you to compile the physics engine into a dynamic library (`.dll` on Windows, `.dylib` on macOS, `.so` on Linux) that can be loaded by any engine.

Below is the complete code for a 3D particle/sphere physics engine plugin featuring:
1. **Semi-Implicit Euler Integration** (for stable velocity/position calculation).
2. **Floor Collision & Restitution** (bounciness).
3. **C-Linkage Exports** (so Unity/C# or Godot can easily call it).

---

### Part 1: The Native C++ Physics Plugin (`CustomPhysicsPlugin.cpp`)

This is the core physics engine. It defines 3D vectors, a physics body, a physical world, and exposes flat C-style functions for the game engine to call.

```cpp
#include <vector>
#include <cmath>

// Define platform-specific import/export macros
#if defined(_MSC_VER) // Windows / MSVC
    #define EXPORT_API __declspec(dllexport)
#else // Linux/macOS / GCC/Clang
    #define EXPORT_API __attribute__((visibility("default")))
#endif

// Simple 3D Vector structure
struct Vec3 {
    float x, y, z;

    Vec3 operator+(const Vec3& other) const { return {x + other.x, y + other.y, z + other.z}; }
    Vec3 operator*(float scalar) const { return {x * scalar, y * scalar, z * scalar}; }
    Vec3& operator+=(const Vec3& other) { x += other.x; y += other.y; z += other.z; return *this; }
};

// Physics Body Representation
struct PhysicsBody {
    int id;
    Vec3 position;
    Vec3 velocity;
    Vec3 force;
    float mass;
    float inverseMass;
    float radius;
    float bounciness; // Restitution coefficient (0.0 = no bounce, 1.0 = perfect bounce)

    PhysicsBody(int _id, Vec3 pos, Vec3 vel, float m, float r, float bounce)
        : id(_id), position(pos), velocity(vel), mass(m), radius(r), bounciness(bounce) {
        inverseMass = (m > 0.0f) ? (1.0f / m) : 0.0f; // 0 mass represents static object
        force = {0.0f, 0.0f, 0.0f};
    }
};

// Physics World Container
class PhysicsWorld {
public:
    Vec3 gravity = {0.0f, -9.81f, 0.0f};
    std::vector<PhysicsBody> bodies;
    int nextId = 0;

    int AddBody(Vec3 pos, Vec3 vel, float mass, float radius, float bounciness) {
        bodies.emplace_back(nextId, pos, vel, mass, radius, bounciness);
        return nextId++;
    }

    void Step(float dt) {
        if (dt <= 0.0f) return;

        for (auto& body : bodies) {
            if (body.inverseMass == 0.0f) continue; // Skip static objects

            // 1. Accumulate forces (Gravity: F = m * g)
            Vec3 gravityForce = body.gravity * body.mass; // (Simplifies out, but good practice)
            body.force += body.gravity * body.mass;

            // 2. Integrate Velocity: v = v + (F / m) * dt
            Vec3 acceleration = body.force * body.inverseMass;
            body.velocity += acceleration * dt;

            // 3. Integrate Position: p = p + v * dt
            body.position += body.velocity * dt;

            // 4. Clear forces for next frame
            body.force = {0.0f, 0.0f, 0.0f};

            // 5. Collision with Floor (Plane at Y = 0)
            float floorLevel = 0.0f;
            if (body.position.y - body.radius < floorLevel) {
                // Resolve interpenetration (push back above floor)
                body.position.y = floorLevel + body.radius;

                // Reflect velocity on Y axis and apply bounciness
                body.velocity.y = -body.velocity.y * body.bounciness;

                // Simple friction on X and Z axis upon floor impact
                body.velocity.x *= 0.9f;
                body.velocity.z *= 0.9f;
            }
        }
    }
};

// ==========================================
// C-LINKAGE INTERFACE (API FOR GAME ENGINES)
// ==========================================
extern "C" {

    // Instantiates the physics world and returns an opaque pointer
    EXPORT_API void* CreatePhysicsWorld() {
        return reinterpret_cast<void*>(new PhysicsWorld());
    }

    // Destroys the physics world to prevent memory leaks
    EXPORT_API void DestroyPhysicsWorld(void* worldPtr) {
        delete reinterpret_cast<PhysicsWorld*>(worldPtr);
    }

    // Configures gravity
    EXPORT_API void SetGravity(void* worldPtr, float x, float y, float z) {
        auto* world = reinterpret_cast<PhysicsWorld*>(worldPtr);
        world->gravity = {x, y, z};
    }

    // Spawns a physical body in the world and returns its unique ID
    EXPORT_API int CreateBody(void* worldPtr, float px, float py, float pz, 
                              float vx, float vy, float vz, 
                              float mass, float radius, float bounciness) {
        auto* world = reinterpret_cast<PhysicsWorld*>(worldPtr);
        return world->AddBody({px, py, pz}, {vx, vy, vz}, mass, radius, bounciness);
    }

    // Updates the physics simulation by delta time (dt)
    EXPORT_API void UpdatePhysics(void* worldPtr, float dt) {
        auto* world = reinterpret_cast<PhysicsWorld*>(worldPtr);
        world->Step(dt);
    }

    // Retrieves a body's position (so the game engine can update the visual mesh)
    EXPORT_API void GetBodyPosition(void* worldPtr, int bodyId, float* outX, float* outY, float* outZ) {
        auto* world = reinterpret_cast<PhysicsWorld*>(worldPtr);
        for (const auto& body : world->bodies) {
            if (body.id == bodyId) {
                *outX = body.position.x;
                *outY = body.position.y;
                *outZ = body.position.z;
                return;
            }
        }
    }
}
```

