### Part 2: Unity Integration Script (`CustomPhysicsComponent.cs`)

Once you compile the C++ code into a library (e.g., `CustomPhysicsPlugin.dll` on Windows), place it in the `Assets/Plugins/` folder of your **Unity** project. 

Here is the C# script that binds to the C++ plugin using P/Invoke, runs the physics update, and moves Unity GameObjects accordingly.

```csharp
using System;
using System.Runtime.InteropServices;
using UnityEngine;

public class CustomPhysicsComponent : MonoBehaviour
{
    // Define the name of the C++ plugin library
    private const string LIB_NAME = "CustomPhysicsPlugin";

    // P/Invoke bindings to the C++ dynamic library
    [DllImport(LIB_NAME)]
    private static extern IntPtr CreatePhysicsWorld();

    [DllImport(LIB_NAME)]
    private static extern void DestroyPhysicsWorld(IntPtr world);

    [DllImport(LIB_NAME)]
    private static extern void SetGravity(IntPtr world, float x, float y, float z);

    [DllImport(LIB_NAME)]
    private static extern int CreateBody(IntPtr world, float px, float py, float pz, 
                                         float vx, float vy, float vz, 
                                         float mass, float radius, float bounciness);

    [DllImport(LIB_NAME)]
    private static extern void UpdatePhysics(IntPtr world, float dt);

    [DllImport(LIB_NAME)]
    private static extern void GetBodyPosition(IntPtr world, int bodyId, out float x, out float y, out float z);

    // Instance variables
    private IntPtr m_physicsWorld;
    private int m_bodyId;

    [Header("Physics Settings")]
    public Vector3 initialVelocity = new Vector3(5f, 10f, 0f);
    public float mass = 1.0f;
    public float radius = 0.5f;
    [Range(0f, 1f)] public float bounciness = 0.75f;

    void Start()
    {
        // 1. Initialize the C++ physics world
        m_physicsWorld = CreatePhysicsWorld();
        SetGravity(m_physicsWorld, 0f, -9.81f, 0f);

        // 2. Synchronize visual size with the physics radius (diameter)
        transform.localScale = Vector3.one * (radius * 2f);

        // 3. Register our object with the native physics world
        Vector3 pos = transform.position;
        m_bodyId = CreateBody(
            m_physicsWorld, 
            pos.x, pos.y, pos.z, 
            initialVelocity.x, initialVelocity.y, initialVelocity.z, 
            mass, radius, bounciness
        );
    }

    void FixedUpdate()
    {
        if (m_physicsWorld == IntPtr.Zero) return;

        // 4. Update the physics simulation (FixedUpdate ensures deterministic delta time)
        UpdatePhysics(m_physicsWorld, Time.fixedDeltaTime);

        // 5. Query the new coordinates from the C++ plugin
        float px, py, pz;
        GetBodyPosition(m_physicsWorld, m_bodyId, out px, out py, out pz);

        // 6. Apply physics position to Unity transform
        transform.position = new Vector3(px, py, pz);
    }

    void OnDestroy()
    {
        // 7. Cleanup native memory allocated in C++ to prevent memory leaks
        if (m_physicsWorld != IntPtr.Zero)
        {
            DestroyPhysicsWorld(m_physicsWorld);
            m_physicsWorld = IntPtr.Zero;
        }
    }
}
