### Part 1: The C++ Native Plugin (`PhysicsPlugin.cpp`)
This is the high-performance C++ backend. It manages the simulation state and runs the physics calculations.

Save this file as `PhysicsPlugin.cpp`.

```cpp
#define EXPORT_API __declspec(dllexport) // For Windows
// For macOS/Linux, use: #define EXPORT_API __attribute__((visibility("default")))

#include <vector>
#include <cmath>

// Simple 3D Vector Math Struct
struct Vector3 {
    float x, y, z;

    Vector3 operator+(const Vector3& other) const { return { x + other.x, y + other.y, z + other.z }; }
    Vector3 operator-(const Vector3& other) const { return { x - other.x, y - other.y, z - other.z }; }
    Vector3 operator*(float scalar) const { return { x * scalar, y * scalar, z * scalar }; }
    Vector3& operator+=(const Vector3& other) { x += other.x; y += other.y; z += other.z; return *this; }
};

// Internal representation of a physical body
struct RigidBody {
    Vector3 position;
    Vector3 velocity;
    float mass;
    float radius;
    float restitution; // Bounciness (0.0 = no bounce, 1.0 = perfect bounce)
};

// Global state of the physics world
std::vector<RigidBody> g_Bodies;

extern "C" {

    // 1. Reset/Clear the physics world
    EXPORT_API void ClearWorld() {
        g_Bodies.clear();
    }

    // 2. Create a physical body and return its index
    EXPORT_API int CreateBody(float px, float py, float pz, float vx, float vy, float vz, float mass, float radius, float restitution) {
        RigidBody body;
        body.position = { px, py, pz };
        body.velocity = { vx, vy, vz };
        body.mass = mass;
        body.radius = radius;
        body.restitution = restitution;

        g_Bodies.push_back(body);
        return static_cast<int>(g_Bodies.size() - 1);
    }

    // 3. Step the simulation forward in time (Integration + Collision Resolution)
    EXPORT_API void StepSimulation(float deltaTime, float gravityX, float gravityY, float gravityZ) {
        Vector3 gravity = { gravityX, gravityY, gravityZ };

        for (auto& body : g_Bodies) {
            if (body.mass <= 0.0f) continue; // Static body

            // --- INTEGRATION (Euler) ---
            // Apply Gravity
            body.velocity += gravity * deltaTime;
            // Update Position
            body.position += body.velocity * deltaTime;

            // --- COLLISION DETECTION & RESOLUTION (Ground Plane at Y = 0) ---
            float floorLevel = 0.0f;
            if (body.position.y - body.radius < floorLevel) {
                // Positional correction (resolve penetration)
                body.position.y = floorLevel + body.radius;

                // Impulse response (reverse Y velocity scaled by restitution)
                if (body.velocity.y < 0.0f) {
                    body.velocity.y = -body.velocity.y * body.restitution;

                    // Friction/damping on X and Z axes upon contact
                    body.velocity.x *= 0.9f;
                    body.velocity.z *= 0.9f;
                }
            }
        }
    }

    // 4. Retrieve state back to the Game Engine
    EXPORT_API void GetBodyState(int id, float* outX, float* outY, float* outZ, float* outVx, float* outVy, float* outVz) {
        if (id >= 0 && id < static_cast<int>(g_Bodies.size())) {
            const auto& body = g_Bodies[id];
            *outX = body.position.x;
            *outY = body.position.y;
            *outZ = body.position.z;
            *outVx = body.velocity.x;
            *outVy = body.velocity.y;
            *outVz = body.velocity.z;
        }
    }
}
```

