    private static extern int CreateBody(float px, float py, float pz, float vx, float vy, float vz, float mass, float radius, float restitution);

    [DllImport(DLL_NAME)]
    private static extern void StepSimulation(float deltaTime, float gravityX, float gravityY, float gravityZ);

    [DllImport(DLL_NAME)]
    private static extern void GetBodyState(int id, out float px, out float py, out float pz, out float vx, out float vy, out float vz);

    // Track Unity GameObjects and their corresponding C++ physics IDs
    private struct PhysicsEntity
    {
        public Transform transform;
        public int physicsId;
    }

    public GameObject spherePrefab; // Assign a sphere prefab in the inspector
    public int spawnCount = 100;
    public Vector3 gravity = new Vector3(0, -9.81f, 0);

    private List<PhysicsEntity> _entities = new List<PhysicsEntity>();

    void Start()
    {
        ClearWorld();

        // Spawn spheres randomly and register them with the C++ plugin
        for (int i = 0; i < spawnCount; i++)
        {
            Vector3 randomPos = new Vector3(Random.Range(-5f, 5f), Random.Range(5f, 15f), Random.Range(-5f, 5f));
            Vector3 randomVelocity = new Vector3(Random.Range(-2f, 2f), 0f, Random.Range(-2f, 2f));
            float radius = 0.5f;

            // Create Unity GameObject
            GameObject go = Instantiate(spherePrefab, randomPos, Quaternion.identity);
            go.transform.localScale = Vector3.one * (radius * 2f); // Match visual scale with physics radius

            // Create body in C++ Physics engine
            int id = CreateBody(
                randomPos.x, randomPos.y, randomPos.z,
                randomVelocity.x, randomVelocity.y, randomVelocity.z,
                1.0f,       // mass
                radius,     // radius
                0.75f       // bounciness (75% energy retention)
            );

            _entities.Add(new PhysicsEntity { transform = go.transform, physicsId = id });
        }
    }

    void FixedUpdate()
    {
        // 1. Step the C++ physics simulation forward in time using Fixed Delta Time
        StepSimulation(Time.fixedDeltaTime, gravity.x, gravity.y, gravity.z);

        // 2. Fetch results back from C++ and update Unity Transforms
        for (int i = 0; i < _entities.Count; i++)
        {
            PhysicsEntity entity = _entities[i];

            float px, py, pz, vx, vy, vz;
            GetBodyState(entity.physicsId, out px, out py, out pz, out vx, out vy, out vz);

            // Directly update Unity position (skipping C# physics overhead)
            entity.transform.position = new Vector3(px, py, pz);
        }
    }

    private void OnDestroy()
    {
        ClearWorld();
    }
}
