### Part 1: The Native C++ Physics Engine (`SimplePhysics.cpp`)
This code defines a lightweight 3D physics solver. It handles gravity, linear integration, and a simple ground-plane collision response with energy loss (bouncing).

```cpp
// SimplePhysics.cpp
#include <vector>
#include <cmath>

#if defined(_WIN32) || defined(_WIN64)
#define EXPORT_API __declspec(dllexport)
#else
#define EXPORT_API __attribute__((visibility("default")))
#endif

// Structs aligned to match C# layout
struct Vector3 {
    float x, y, z;
};

struct RigidBody {
    int id;
    Vector3 position;
    Vector3 velocity;
    float mass;
    float radius;
    bool isStatic;
};

// The core C++ Physics World class
class PhysicsWorld {
public:
    std::vector<RigidBody> bodies;
    Vector3 gravity = { 0.0f, -9.81f, 0.0f };
    float restitution = 0.6f; // Bounciness

    void Step(float dt) {
        for (auto& body : bodies) {
            if (body.isStatic) continue;

            // 1. Apply gravity (acceleration)
            body.velocity.x += gravity.x * dt;
            body.velocity.y += gravity.y * dt;
            body.velocity.z += gravity.z * dt;

            // 2. Integrate position
            body.position.x += body.velocity.x * dt;
            body.position.y += body.velocity.y * dt;
            body.position.z += body.velocity.z * dt;

            // 3. Simple Collision: Ground plane at Y = 0 (taking radius into account)
            float floorLevel = body.radius;
            if (body.position.y < floorLevel) {
                body.position.y = floorLevel; // Resolve penetration
                body.velocity.y = -body.velocity.y * restitution; // Bounce

                // Apply simple friction on impact
                body.velocity.x *= 0.8f;
                body.velocity.z *= 0.8f;
            }
        }
    }
};

// --- C Linkage Interface for Game Engine Integration ---
extern "C" {

    EXPORT_API PhysicsWorld* CreatePhysicsWorld() {
        return new PhysicsWorld();
    }

    EXPORT_API void DestroyPhysicsWorld(PhysicsWorld* world) {
        delete world;
    }

    EXPORT_API int AddRigidBody(PhysicsWorld* world, Vector3 position, Vector3 velocity, float mass, float radius, bool isStatic) {
        if (!world) return -1;

        RigidBody body;
        body.id = static_cast<int>(world->bodies.size());
        body.position = position;
        body.velocity = velocity;
        body.mass = mass;
        body.radius = radius;
        body.isStatic = isStatic;

        world->bodies.push_back(body);
        return body.id;
    }

    EXPORT_API void StepSimulation(PhysicsWorld* world, float deltaTime) {
        if (world) {
            world->Step(deltaTime);
        }
    }

    EXPORT_API bool GetBodyTransform(PhysicsWorld* world, int bodyId, Vector3* outPosition) {
        if (!world || bodyId < 0 || bodyId >= world->bodies.size()) {
            return false;
        }
        *outPosition = world->bodies[bodyId].position;
        return true;
    }
}
