    }

    void Start()
    {
        // Find all spheres in our scene to simulate with our custom engine
        GameObject[] spheres = GameObject.FindGameObjectsWithTag("PhysicsSphere");

        foreach (var sphere in spheres)
        {
            float radius = sphere.GetComponent<SphereCollider>() ? sphere.GetComponent<SphereCollider>().radius * sphere.transform.localScale.x : 0.5f;

            // Register object into C++ engine
            int bodyId = AddRigidBody(
                nativeWorldPtr, 
                sphere.transform.position, 
                spawnVelocity, 
                1.0f, // Mass
                radius, 
                false // isStatic
            );

            if (bodyId != -1)
            {
                physicsObjects.Add(bodyId, sphere.transform);
            }
        }
    }

    void FixedUpdate()
    {
        if (nativeWorldPtr == IntPtr.Zero) return;

        // Step the C++ simulation in lockstep with Unity's physics tick
        StepSimulation(nativeWorldPtr, Time.fixedDeltaTime);

        // Retrieve updated data from C++ and apply it back to Unity GameObjects
        foreach (var kvp in physicsObjects)
        {
            int bodyId = kvp.Key;
            Transform targetTransform = kvp.Value;

            if (GetBodyTransform(nativeWorldPtr, bodyId, out Vector3 newPosition))
            {
                targetTransform.position = newPosition;
            }
        }
    }

    void OnDestroy()
    {
        // Crucial: Free the native memory allocated by C++ when the game stops
        if (nativeWorldPtr != IntPtr.Zero)
        {
            DestroyPhysicsWorld(nativeWorldPtr);
            nativeWorldPtr = IntPtr.Zero;
            Debug.Log("Native Physics Plugin successfully destroyed.");
        }
    }
