### Part 1: The Native C++ Plugin (`CustomPhysics.cpp`)

This code defines a lightweight 3D rigid body physics engine. It handles gravity, linear integration, sphere-to-sphere collision detection, and impulse-based collision resolution (bouncing and mass reaction).

```cpp
#include <vector>
#include <cmath>
#include <algorithm>

// Platform-independent DLL Export macro
#if defined(_MSC_VER)
    #define EXPORT __declspec(dllexport)
#else
    #define EXPORT __attribute__((visibility("default")))
#endif

// Simple 3D Vector Math Struct
struct Vector3 {
    float x, y, z;

    Vector3 operator+(const Vector3& v) const { return {x + v.x, y + v.y, z + v.z}; }
    Vector3 operator-(const Vector3& v) const { return {x - v.x, y - v.y, z - v.z}; }
    Vector3 operator*(float scalar) const { return {x * scalar, y * scalar, z * scalar}; }

    float Dot(const Vector3& v) const { return x * v.x + y * v.y + z * v.z; }
    float LengthSq() const { return x * x + y * y + z * z; }
    float Length() const { return std::sqrt(LengthSq()); }

    Vector3 Normalized() const {
        float len = Length();
        if (len > 0.0001f) return {x / len, y / len, z / len};
        return {0, 0, 0};
    }
};

// Rigid Body Structure
struct RigidBody {
    Vector3 position;
    Vector3 velocity;
    float radius;
    float mass;
    float invMass; // Precomputed for speed. 0 = Static (infinite mass)
    float restitution; // Bounciness (0.0 = no bounce, 1.0 = perfect elastic bounce)
};

// Physics World Container
struct PhysicsWorld {
    std::vector<RigidBody> bodies;
    Vector3 gravity = {0.0f, -9.81f, 0.0f};
};

// ==========================================
// C-LINKAGE EXPORTED API FOR GAME ENGINES
// ==========================================
extern "C" {

    // Lifecycle Management
    EXPORT PhysicsWorld* CreatePhysicsWorld() {
        return new PhysicsWorld();
    }

    EXPORT void DestroyPhysicsWorld(PhysicsWorld* world) {
        delete world;
    }

    // Body Management
    EXPORT int AddRigidBody(PhysicsWorld* world, float px, float py, float pz, float radius, float mass, float restitution) {
        if (!world) return -1;

        RigidBody body;
        body.position = {px, py, pz};
        body.velocity = {0, 0, 0};
        body.radius = radius;
        body.mass = mass;
        body.invMass = (mass > 0.0f) ? (1.0f / mass) : 0.0f; // Mass <= 0 means static object
        body.restitution = std::clamp(restitution, 0.0f, 1.0f);

        world->bodies.push_back(body);
        return static_cast<int>(world->bodies.size() - 1);
    }

    EXPORT void GetBodyTransform(PhysicsWorld* world, int bodyId, float* outX, float* outY, float* outZ) {
        if (!world || bodyId < 0 || bodyId >= world->bodies.size()) return;
        const auto& body = world->bodies[bodyId];
        *outX = body.position.x;
        *outY = body.position.y;
        *outZ = body.position.z;
    }

    EXPORT void SetBodyVelocity(PhysicsWorld* world, int bodyId, float vx, float vy, float vz) {
        if (!world || bodyId < 0 || bodyId >= world->bodies.size()) return;
        world->bodies[bodyId].velocity = {vx, vy, vz};
    }

    // Core Simulation Step (Euler Integration & Collision Resolution)
    EXPORT void StepSimulation(PhysicsWorld* world, float deltaTime) {
        if (!world || deltaTime <= 0.0f) return;

        size_t numBodies = world->bodies.size();

        // 1. Integrate Forces (Gravity) and Positions
        for (size_t i = 0; i < numBodies; ++i) {
            RigidBody& b = world->bodies[i];
            if (b.invMass == 0.0f) continue; // Skip static objects

            // Apply gravity: v = v + g * dt
            b.velocity = b.velocity + (world->gravity * deltaTime);
            // Apply velocity: p = p + v * dt
            b.position = b.position + (b.velocity * deltaTime);
        }

        // 2. Collision Detection and Resolution (Narrowphase Sphere-Sphere)
        for (size_t i = 0; i < numBodies; ++i) {
            for (size_t j = i + 1; j < numBodies; ++j) {
                RigidBody& bA = world->bodies[i];
                RigidBody& bB = world->bodies[j];

                // Skip if both are static
                if (bA.invMass == 0.0f && bB.invMass == 0.0f) continue;

                Vector3 delta = bB.position - bA.position;
                float distSq = delta.LengthSq();
                float minDist = bA.radius + bB.radius;

                if (distSq < minDist * minDist) {
                    float dist = std::sqrt(distSq);

                    // Prevent division by zero if objects are perfectly overlapping
                    Vector3 normal = (dist > 0.0f) ? delta.Normalized() : Vector3{0, 1, 0};
                    float penetration = minDist - dist;

                    // Positional Correction (Sinking prevention)
                    const float percent = 0.2f; // Penetration percentage to resolve per frame
                    const float slop = 0.01f;    // Penetration allowance
                    Vector3 correction = normal * (std::max(penetration - slop, 0.0f) / (bA.invMass + bB.invMass)) * percent;
                    bA.position = bA.position - (correction * bA.invMass);
                    bB.position = bB.position + (correction * bB.invMass);

                    // Impulse Physics Resolution (Elastic Bounce)
                    Vector3 relativeVelocity = bB.velocity - bA.velocity;
                    float velAlongNormal = relativeVelocity.Dot(normal);

                    // Do not resolve if velocities are already separating
                    if (velAlongNormal < 0) {
                        float e = std::min(bA.restitution, bB.restitution); // Coefficient of restitution

                        // Calculate Impulse Scalar
                        float jImpulse = -(1.0f + e) * velAlongNormal;
                        jImpulse /= (bA.invMass + bB.invMass);

                        // Apply Impulse to bodies
                        bA.velocity = bA.velocity - (normal * (jImpulse * bA.invMass));
                        bB.velocity = bB.velocity + (normal * (jImpulse * bB.invMass));
                    }
                }
            }
        }
    }
}
