### Part 1: The Native C++ Physics Engine (`NativePhysics.cpp`)

This code compiles into a dynamic library (`.dll` on Windows, `.dylib` on macOS, `.so` on Linux). It manages a simple rigid body simulation with gravity, force accumulation, and a simple ground-plane collision solver.

```cpp
// NativePhysics.cpp
#include <cmath>

#if defined(_MSC_VER) // Windows
    #define EXPORT_API __declspec(dllexport)
#else // macOS / Linux
    #define EXPORT_API __attribute__((visibility("default")))
#endif

// Simple 3D Vector struct matching Unity's memory layout
struct Vector3 {
    float x, y, z;
};

// The native representation of our Rigid Body
struct RigidBody {
    Vector3 position;
    Vector3 velocity;
    Vector3 force;
    float mass;
    float restitution; // Bounciness (0.0 = no bounce, 1.0 = perfect bounce)
    float radius;      // For simple sphere-to-ground collision
};

extern "C" {

    // 1. Instantiates a new rigid body in native memory
    EXPORT_API RigidBody* CreateRigidBody(float px, float py, float pz, float mass, float radius, float restitution) {
        RigidBody* body = new RigidBody();
        body->position = { px, py, pz };
        body->velocity = { 0.0f, 0.0f, 0.0f };
        body->force = { 0.0f, 0.0f, 0.0f };
        body->mass = mass > 0.0f ? mass : 1.0f;
        body->radius = radius;
        body->restitution = restitution;
        return body;
    }

    // 2. Safely deallocates native memory
    EXPORT_API void DestroyRigidBody(RigidBody* body) {
        if (body != nullptr) {
            delete body;
        }
    }

    // 3. Accumulates a force to be applied on the next step
    EXPORT_API void AddForce(RigidBody* body, float fx, float fy, float fz) {
        if (body == nullptr) return;
        body->force.x += fx;
        body->force.y += fy;
        body->force.z += fz;
    }

    // 4. The main physics update step (Symplectic Euler Integration)
    EXPORT_API void StepPhysics(RigidBody* body, float deltaTime, float gravityY) {
        if (body == nullptr || body->mass <= 0.0f) return;

        // Apply constant gravity force (F = m * g)
        body->force.y += gravityY * body->mass;

        // Acceleration = Force / Mass
        float ax = body->force.x / body->mass;
        float ay = body->force.y / body->mass;
        float az = body->force.z / body->mass;

        // Integrate velocity: v = v + a * dt
        body->velocity.x += ax * deltaTime;
        body->velocity.y += ay * deltaTime;
        body->velocity.z += az * deltaTime;

        // Integrate position: p = p + v * dt
        body->position.x += body->velocity.x * deltaTime;
        body->position.y += body->velocity.y * deltaTime;
        body->position.z += body->velocity.z * deltaTime;

        // Reset accumulated forces for next frame
        body->force = { 0.0f, 0.0f, 0.0f };

        // --- Basic Collision Solver: Ground Plane (Y = 0) ---
        float floorY = 0.0f;
        if (body->position.y - body->radius < floorY) {
            // Push object out of collision (Penetration resolution)
            body->position.y = floorY + body->radius;

            // Reverse velocity along collision normal (Y-axis) with bounciness
            if (body->velocity.y < 0.0f) {
                body->velocity.y = -body->velocity.y * body->restitution;
            }

            // Apply friction/drag on X and Z axis when contacting ground
            body->velocity.x *= 0.95f;
            body->velocity.z *= 0.95f;
        }
    }

    // 5. Exposes the position data to Unity
    EXPORT_API void GetPosition(RigidBody* body, float* outX, float* outY, float* outZ) {
        if (body == nullptr) return;
        *outX = body->position.x;
        *outY = body->position.y;
        *outZ = body->position.z;
    }
}
```

