public class CustomPhysicsBody : MonoBehaviour
{
    // Define the name of our C++ binary (excluding extension)
    private const string LIB_NAME = "NativePhysics";

    // P/Invoke Imports mapping to C++ functions
    [DllImport(LIB_NAME)]
    private static extern IntPtr CreateRigidBody(float px, float py, float pz, float mass, float radius, float restitution);

    [DllImport(LIB_NAME)]
    private static extern void DestroyRigidBody(IntPtr body);

    [DllImport(LIB_NAME)]
    private static extern void AddForce(IntPtr body, float fx, float fy, float fz);

    [DllImport(LIB_NAME)]
    private static extern void StepPhysics(IntPtr body, float deltaTime, float gravityY);

    [DllImport(LIB_NAME)]
    private static extern void GetPosition(IntPtr body, out float x, out float y, out float z);

    [Header("Physics Properties")]
    public float mass = 1.0f;
    public float radius = 0.5f;
    [Range(0f, 1f)] public float bounciness = 0.6f;
    public float gravity = -9.81f;

    private IntPtr nativeBodyPtr = IntPtr.Zero;

    void Start()
    {
        // 1. Initialize the physical representation in the Native Plugin
        Vector3 pos = transform.position;
        nativeBodyPtr = CreateRigidBody(pos.x, pos.y, pos.z, mass, radius, bounciness);
    }

