        if (nativeBodyPtr == IntPtr.Zero) return;

        // 2. Step the native simulation (typically inside FixedUpdate for physics consistency)
        StepPhysics(nativeBodyPtr, Time.fixedDeltaTime, gravity);

        // 3. Fetch the results from Native Memory
        float rx, ry, rz;
        GetPosition(nativeBodyPtr, out rx, out ry, out rz);

        // 4. Update the actual Unity Transform
        transform.position = new Vector3(rx, ry, rz);
    }

    // Public method to apply forces from Unity scripts (e.g., player inputs, explosions)
    public void ApplyForce(Vector3 force)
    {
        if (nativeBodyPtr != IntPtr.Zero)
        {
            AddForce(nativeBodyPtr, force.x, force.y, force.z);
        }
    }

    void OnDestroy()
    {
        // CRITICAL: Always release unmanaged memory allocated in C++ to prevent memory leaks!
        if (nativeBodyPtr != IntPtr.Zero)
        {
            DestroyRigidBody(nativeBodyPtr);
            nativeBodyPtr = IntPtr.Zero;
        }
    }

    // Visualizing the custom collider radius in Unity Editor
    private void OnDrawGizmosSelected()
    {
        Gizmos.color = Color.green;
        Gizmos.DrawWireSphere(transform.position, radius);
    }
