### Part 1: The Native C++ Plugin (`NativePhysicsPlugin.cpp`)

This code implements a simple 3D rigid-body/particle physics world with gravity, integration (movement), and basic floor collision resolution.

```cpp
// NativePhysicsPlugin.cpp
#include <vector>
#include <cmath>

#if defined(_MSC_VER)
    #define EXPORT_API __declspec(dllexport)
#else
    #define EXPORT_API __attribute__((visibility("default")))
#endif

extern "C" {

    // 1. Simple math structure matching Engine-side Vector3
    struct Vec3 {
        float x, y, z;
    };

    // 2. Rigid body state
    struct RigidBody {
        int id;
        Vec3 position;
        Vec3 velocity;
        Vec3 acceleration;
        float mass;
        float radius;
        float bounciness; // 0.0 (no bounce) to 1.0 (perfect elastic)
        bool isStatic;
    };

    // 3. Internal Physics World Representation
    struct PhysicsWorld {
        std::vector<RigidBody> bodies;
        Vec3 gravity = { 0.0f, -9.81f, 0.0f };
        int nextId = 0;
    };

    // --- API FUNCTIONS EXPOSED TO THE GAME ENGINE ---

    // Create and return a pointer to a new Physics World
    EXPORT_API PhysicsWorld* CreateWorld() {
        return new PhysicsWorld();
    }

    // Destroy the world and free native memory
    EXPORT_API void DestroyWorld(PhysicsWorld* world) {
        delete world;
    }

    // Configure global gravity settings
    EXPORT_API void SetGravity(PhysicsWorld* world, float gx, float gy, float gz) {
        if (!world) return;
        world->gravity = { gx, gy, gz };
    }

    // Add a physical body to the world and return its ID
    EXPORT_API int AddBody(PhysicsWorld* world, float px, float py, float pz, float radius, float mass, bool isStatic) {
        if (!world) return -1;

        RigidBody body;
        body.id = world->nextId++;
        body.position = { px, py, pz };
        body.velocity = { 0.0f, 0.0f, 0.0f };
        body.acceleration = { 0.0f, 0.0f, 0.0f };
        body.radius = radius;
        body.mass = mass;
        body.bounciness = 0.6f; // Default bounciness
        body.isStatic = isStatic;

        world->bodies.push_back(body);
        return body.id;
    }

    // Apply a direct force to a body
    EXPORT_API void ApplyForce(PhysicsWorld* world, int bodyId, float fx, float fy, float fz) {
        if (!world) return;
        for (auto& body : world->bodies) {
            if (body.id == bodyId && !body.isStatic) {
                // F = ma -> a = F/m
                body.acceleration.x += fx / body.mass;
                body.acceleration.y += fy / body.mass;
                body.acceleration.z += fz / body.mass;
                break;
            }
        }
    }

    // Get a body's current position (for syncing with the engine's transform)
    EXPORT_API bool GetBodyPosition(PhysicsWorld* world, int bodyId, Vec3* outPosition) {
        if (!world || !outPosition) return false;
        for (const auto& body : world->bodies) {
            if (body.id == bodyId) {
                *outPosition = body.position;
                return true;
            }
        }
        return false;
    }

    // Step the simulation forward by deltaTime (dt)
    EXPORT_API void StepWorld(PhysicsWorld* world, float dt) {
        if (!world || dt <= 0.0f) return;

        for (auto& body : world->bodies) {
            if (body.isStatic) continue;

            // 1. Semi-implicit Euler Integration
            body.velocity.x += (body.acceleration.x + world->gravity.x) * dt;
            body.velocity.y += (body.acceleration.y + world->gravity.y) * dt;
            body.velocity.z += (body.acceleration.z + world->gravity.z) * dt;

            body.position.x += body.velocity.x * dt;
            body.position.y += body.velocity.y * dt;
            body.position.z += body.velocity.z * dt;

            // Clear accumulated frame forces/acceleration
            body.acceleration = { 0.0f, 0.0f, 0.0f };

            // 2. Collision Detection & Resolution with a Ground Plane (Y = 0)
            float floorLevel = 0.0f + body.radius;
            if (body.position.y < floorLevel) {
                // Push out of collision
                body.position.y = floorLevel;

                // Reverse velocity along collision normal (upwards) and apply bounce
                body.velocity.y = -body.velocity.y * body.bounciness;

                // Apply simple kinetic friction to horizontal movements upon impact
                body.velocity.x *= 0.95f;
                body.velocity.z *= 0.95f;
            }
        }
    }
}
```

