// CustomPhysicsManager.cs
using System;
using System.Runtime.InteropServices;
using System.Collections.Generic;
using UnityEngine;

public class CustomPhysicsManager : MonoBehaviour
{
    // Define DLL Import bindings 
#if UNITY_IPHONE && !UNITY_EDITOR
    private const string DLL_NAME = "__Internal";
#else
    private const string DLL_NAME = "NativePhysicsPlugin";
#endif

    [StructLayout(LayoutKind.Sequential)]
    public struct Vec3 {
        public float x, y, z;
        public Vector3 ToVector3() => new Vector3(x, y, z);
    }

    [DllImport(DLL_NAME)]
    private static extern IntPtr CreateWorld();

    [DllImport(DLL_NAME)]
    private static extern void DestroyWorld(IntPtr world);

    [DllImport(DLL_NAME)]
    private static extern void SetGravity(IntPtr world, float gx, float gy, float gz);

    [DllImport(DLL_NAME)]
    private static extern int AddBody(IntPtr world, float px, float py, float pz, float radius, float mass, bool isStatic);

    [DllImport(DLL_NAME)]
    private static extern void ApplyForce(IntPtr world, int bodyId, float fx, float fy, float fz);

    [DllImport(DLL_NAME)]
    private static extern bool GetBodyPosition(IntPtr world, int bodyId, out Vec3 outPos);

    [DllImport(DLL_NAME)]
    private static extern void StepWorld(IntPtr world, float dt);

    // --- Unity Properties ---
    private IntPtr nativeWorldPtr;
    private Dictionary<int, Transform> physicsTransforms = new Dictionary<int, Transform>();

    [SerializeField] private GameObject ballPrefab;
    [SerializeField] private int spawnCount = 20;

    void Start()
    {
        // 1. Initialize custom native physics engine
        nativeWorldPtr = CreateWorld();
        SetGravity(nativeWorldPtr, 0.0f, -9.81f, 0.0f);

        // 2. Spawn and register physical bodies
        for (int i = 0; i < spawnCount; i++)
        {
            Vector3 spawnPos = new Vector3(UnityEngine.Random.Range(-5f, 5f), UnityEngine.Random.Range(5f, 15f), UnityEngine.Random.Range(-5f, 5f));
            GameObject go = Instantiate(ballPrefab, spawnPos, Quaternion.identity);

            float radius = go.transform.localScale.x / 2.0f;

            // Register body inside our C++ plugin
            int bodyId = AddBody(nativeWorldPtr, spawnPos.x, spawnPos.y, spawnPos.z, radius, 1.0f, false);

            physicsTransforms.Add(bodyId, go.transform);

            // Give them a small random starting push
            ApplyForce(nativeWorldPtr, bodyId, UnityEngine.Random.Range(-100f, 100f), 0, UnityEngine.Random.Range(-100f, 100f));
        }
    }

    void FixedUpdate()
    {
        if (nativeWorldPtr == IntPtr.Zero) return;

        // 3. Step the native simulation (Use FixedDeltaTime for consistency)
        StepWorld(nativeWorldPtr, Time.fixedDeltaTime);

        // 4. Update Game Engine GameObjects to reflect native simulation positions
        foreach (var pair in physicsTransforms)
        {
            int bodyId = pair.Key;
            Transform trans = pair.Value;

            if (GetBodyPosition(nativeWorldPtr, bodyId, out Vec3 nativePos))
            {
                trans.position = nativePos.ToVector3();
            }
        }
    }

    void OnDestroy()
    {
        // 5. Always clean up raw pointer allocations to prevent native memory leaks
        if (nativeWorldPtr != IntPtr.Zero)
        {
            DestroyWorld(nativeWorldPtr);
            nativeWorldPtr = IntPtr.Zero;
        }
    }
}
