### Phase 1: The Core Physics Engine (C++)

This is the high-performance C++ backend. Create two files: `CustomPhysics.h` and `CustomPhysics.cpp`.

#### `CustomPhysics.h`
```cpp
#pragma once

#ifdef _WIN32
    #define PHYSICS_API __declspec(dllexport)
#else
    #define PHYSICS_API __attribute__((visibility("default")))
#endif

extern "C" {

    struct Vec3 {
        float x, y, z;

        Vec3 operator+(const Vec3& other) const { return {x + other.x, y + other.y, z + other.z}; }
        Vec3 operator-(const Vec3& other) const { return {x - other.x, y - other.y, z - other.z}; }
        Vec3 operator*(float scalar) const { return {x * scalar, y * scalar, z * scalar}; }
        float Dot(const Vec3& other) const { return x * other.x + y * other.y + z * other.z; }
        float MagnitudeSq() const { return Dot(*this); }

        Vec3 Normalized() const {
            float lenSq = MagnitudeSq();
            if (lenSq < 0.0001f) return {0, 0, 0};
            float invLen = 1.0f / __builtin_sqrtf(lenSq); // Or std::sqrt
            return *this * invLen;
        }
    };

    struct RigidBody {
        int id;
        Vec3 position;
        Vec3 velocity;
        Vec3 force;
        float mass;
        float invMass;
        float radius;       // Used for sphere bounding-volume collision
        float restitution;  // Bounciness (0.0 = no bounce, 1.0 = perfect bounce)
    };

    // Opaque pointer to the physics world instance
    typedef void* PhysicsWorldHandle;

    // Plugin API
    PHYSICS_API PhysicsWorldHandle CreatePhysicsWorld(float gravityX, float gravityY, float gravityZ);
    PHYSICS_API void DestroyPhysicsWorld(PhysicsWorldHandle worldHandle);
    PHYSICS_API int AddRigidBody(PhysicsWorldHandle worldHandle, Vec3 pos, Vec3 vel, float mass, float radius, float restitution);
    PHYSICS_API void StepSimulation(PhysicsWorldHandle worldHandle, float deltaTime);
    PHYSICS_API bool GetBodyState(PhysicsWorldHandle worldHandle, int bodyId, RigidBody* outBody);

}
```

#### `CustomPhysics.cpp`
```cpp
#include "CustomPhysics.h"
#include <vector>
#include <cmath>
#include <algorithm>

class PhysicsWorldInternal {
public:
    Vec3 gravity;
    std::vector<RigidBody> bodies;
    int nextId = 0;

    PhysicsWorldInternal(Vec3 g) : gravity(g) {}

    void Step(float dt) {
        if (dt <= 0.0f) return;

        // 1. Integrate Forces & Velocities (Semi-Implicit Euler)
        for (auto& body : bodies) {
            if (body.invMass == 0.0f) continue; // Static body (infinite mass)

            // Apply gravity
            body.velocity = body.velocity + (gravity * dt);
            // Apply external forces
            body.velocity = body.velocity + (body.force * body.invMass * dt);
            // Integrate position
            body.position = body.position + (body.velocity * dt);
            // Clear forces for next frame
            body.force = {0, 0, 0};
        }

        // 2. Collision Detection & Resolution (O(N^2) Narrowphase for simplicity)
        for (size_t i = 0; i < bodies.size(); ++i) {
            for (size_t j = i + 1; j < bodies.size(); ++j) {
                ResolveCollision(bodies[i], bodies[j]);
            }
        }
    }

private:
    void ResolveCollision(RigidBody& a, RigidBody& b) {
        Vec3 delta = b.position - a.position;
        float distSq = delta.MagnitudeSq();
        float radiusSum = a.radius + b.radius;

        // Check if spheres overlap
        if (distSq >= radiusSum * radiusSum) return;

        float dist = std::sqrt(distSq);
        Vec3 normal = (dist == 0.0f) ? Vec3{0, 1, 0} : delta.Normalized();
        float penetration = radiusSum - dist;

        // Relative velocity along collision normal
        Vec3 relativeVel = b.velocity - a.velocity;
        float velAlongNormal = relativeVel.Dot(normal);

        // Do not resolve if objects are already moving apart
        if (velAlongNormal > 0) return;

        // Calculate Impulse Scalar (j)
        float e = std::min(a.restitution, b.restitution);
        float impulseScalar = -(1.0f + e) * velAlongNormal;
        impulseScalar /= (a.invMass + b.invMass);

        // Apply impulse
        Vec3 impulse = normal * impulseScalar;
        a.velocity = a.velocity - (impulse * a.invMass);
        b.velocity = b.velocity + (impulse * b.invMass);

        // Positional Correction (prevents sinking/clipping)
        const float percent = 0.4f; // Penetration percentage to resolve per frame
        const float slop = 0.01f;    // Penetration allowance
        Vec3 correction = normal * (std::max(penetration - slop, 0.0f) / (a.invMass + b.invMass) * percent);
        a.position = a.position - (correction * a.invMass);
        b.position = b.position + (correction * b.invMass);
    }
};

// C-API Implementation bindings
extern "C" {

    PHYSICS_API PhysicsWorldHandle CreatePhysicsWorld(float gravityX, float gravityY, float gravityZ) {
        return reinterpret_cast<PhysicsWorldHandle>(new PhysicsWorldInternal({gravityX, gravityY, gravityZ}));
    }

    PHYSICS_API void DestroyPhysicsWorld(PhysicsWorldHandle worldHandle) {
        delete reinterpret_cast<PhysicsWorldInternal*>(worldHandle);
    }

    PHYSICS_API int AddRigidBody(PhysicsWorldHandle worldHandle, Vec3 pos, Vec3 vel, float mass, float radius, float restitution) {
        auto* world = reinterpret_cast<PhysicsWorldInternal*>(worldHandle);
        RigidBody body;
        body.id = world->nextId++;
        body.position = pos;
        body.velocity = vel;
        body.force = {0, 0, 0};
        body.mass = mass;
        body.invMass = (mass > 0.0f) ? 1.0f / mass : 0.0f; // Mass 0 = Static
        body.radius = radius;
        body.restitution = restitution;

        world->bodies.push_back(body);
        return body.id;
    }

    PHYSICS_API void StepSimulation(PhysicsWorldHandle worldHandle, float deltaTime) {
        reinterpret_cast<PhysicsWorldInternal*>(worldHandle)->Step(deltaTime);
    }

    PHYSICS_API bool GetBodyState(PhysicsWorldHandle worldHandle, int bodyId, RigidBody* outBody) {
        auto* world = reinterpret_cast<PhysicsWorldInternal*>(worldHandle);
        for (const auto& body : world->bodies) {
            if (body.id == bodyId) {
                *outBody = body;
                return true;
            }
        }
        return false;
    }
}
```

