### Part 1: The C++ Native Core (`CustomPhysics.cpp`)

This code handles the heavy math and memory layouts. It compiles into a native binary (`CustomPhysics.dll` on Windows, `.so` on Linux, or `.dylib` on macOS).

```cpp
#include <vector>
#include <cmath>
#include <algorithm>

// Define platform-specific DLL export macro
#if defined(_MSC_VER)
    #define EXPORT_API __declspec(dllexport)
#else
    #define EXPORT_API __attribute__((visibility("default")))
#endif

// Math structures matching engine formats (e.g., Unity's Vector3)
struct Vector3 {
    float x, y, z;

    Vector3 operator+(const Vector3& o) const { return {x + o.x, y + o.y, z + o.z}; }
    Vector3 operator-(const Vector3& o) const { return {x - o.x, y - o.y, z - o.z}; }
    Vector3 operator*(float s) const { return {x * s, y * s, z * s}; }
    Vector3& operator+=(const Vector3& o) { x += o.x; y += o.y; z += o.z; return *this; }
    Vector3& operator-=(const Vector3& o) { x -= o.x; y -= o.y; z -= o.z; return *this; }

    float Dot(const Vector3& o) const { return x * o.x + y * o.y + z * o.z; }
    float LengthSq() const { return Dot(*this); }
    float Length() const { return std::sqrt(LengthSq()); }
    Vector3 Normalized() const {
        float len = Length();
        return len > 0.0f ? *this * (1.0f / len) : Vector3{0, 0, 0};
    }
};

// Rigid Body structure
struct RigidBody {
    int id;
    Vector3 position;
    Vector3 velocity;
    float mass;
    float invMass; // Cached for performance (1/mass)
    float radius;
    bool isStatic;

    void Initialize(int bodyId, Vector3 pos, Vector3 vel, float m, float r, bool isStat) {
        id = bodyId;
        position = pos;
        velocity = vel;
        mass = m;
        invMass = isStat ? 0.0f : (1.0f / m);
        radius = r;
        isStatic = isStat;
    }
};

// Main Physics World context
class PhysicsWorld {
public:
    std::vector<RigidBody> bodies;
    Vector3 gravity = { 0.0f, -9.81f, 0.0f };
    float restitution = 0.5f; // Bounciness (0 = slide, 1 = perfect bounce)

    void Step(float dt) {
        if (dt <= 0.0f) return;

        // 1. Integrate Forces & Velocities
        for (auto& body : bodies) {
            if (body.isStatic) continue;
            // Semi-implicit Euler
            body.velocity += gravity * dt;
            body.position += body.velocity * dt;
        }

        // 2. Detect & Resolve Collisions (Naive O(N^2) for simplicity; BVH recommended for production)
        for (size_t i = 0; i < bodies.size(); ++i) {
            for (size_t j = i + 1; j < bodies.size(); ++j) {
                ResolveCollision(bodies[i], bodies[j]);
            }
        }
    }

private:
    void ResolveCollision(RigidBody& a, RigidBody& b) {
        Vector3 delta = b.position - a.position;
        float distSq = delta.LengthSq();
        float radiusSum = a.radius + b.radius;

        if (distSq >= radiusSum * radiusSum) return; // No collision

        float dist = std::sqrt(distSq);
        Vector3 normal = (dist > 0.0f) ? delta * (1.0f / dist) : Vector3{0, 1, 0};
        float penetration = radiusSum - dist;

        // --- 1. Positional Correction (Sinking prevention) ---
        const float percent = 0.2f; // Penetration percentage to resolve per frame
        const float slop = 0.01f;     // Penetration allowance
        Vector3 correction = normal * (std::max(penetration - slop, 0.0f) / (a.invMass + b.invMass) * percent);
        if (!a.isStatic) a.position -= correction * a.invMass;
        if (!b.isStatic) b.position += correction * b.invMass;

        // --- 2. Impulse Resolution (Velocities) ---
        Vector3 relativeVel = b.velocity - a.velocity;
        float velAlongNormal = relativeVel.Dot(normal);

        if (velAlongNormal > 0) return; // Moving apart already

        float impulseScalar = -(1.0f + restitution) * velAlongNormal;
        impulseScalar /= (a.invMass + b.invMass);

        Vector3 impulse = normal * impulseScalar;
        if (!a.isStatic) a.velocity -= impulse * a.invMass;
        if (!b.isStatic) b.velocity += impulse * b.invMass;
    }
};

// --- Flat C API for engine marshaling ---
extern "C" {
    EXPORT_API PhysicsWorld* CreatePhysicsWorld() {
        return new PhysicsWorld();
    }

    EXPORT_API void DestroyPhysicsWorld(PhysicsWorld* world) {
        delete world;
    }

    EXPORT_API int AddRigidBody(PhysicsWorld* world, Vector3 pos, Vector3 vel, float mass, float radius, bool isStatic) {
        int id = static_cast<int>(world->bodies.size());
        RigidBody body;
        body.Initialize(id, pos, vel, mass, radius, isStatic);
        world->bodies.push_back(body);
        return id;
    }

    EXPORT_API void StepSimulation(PhysicsWorld* world, float dt) {
        world->Step(dt);
    }

    EXPORT_API void GetBodyTransform(PhysicsWorld* world, int id, Vector3* outPos, Vector3* outVel) {
        if (id >= 0 && id < world->bodies.size()) {
            *outPos = world->bodies[id].position;
            *outVel = world->bodies[id].velocity;
        }
    }
}
