    [DllImport(DLL_NAME)]
    private static extern void StepSimulation(IntPtr world, float dt);

    [DllImport(DLL_NAME)]
    private static extern void GetBodyTransform(IntPtr world, int id, out NativeVector3 outPos, out NativeVector3 outVel);

    // Engine Variables
    private IntPtr nativeWorld;

    [System.Serializable]
    public struct PhysicsObject
    {
        public GameObject unityObject;
        public float mass;
        public float radius;
        public bool isStatic;
        public Vector3 initialVelocity;
        [HideInInspector] public int nativeId;
    }

    public List<PhysicsObject> physicsObjects = new List<PhysicsObject>();

    void Awake()
    {
        // 1. Initialize native physics world
        nativeWorld = CreatePhysicsWorld();

        // 2. Register all scene objects inside the native solver
        for (int i = 0; i < physicsObjects.Count; i++)
        {
            var obj = physicsObjects[i];
            NativeVector3 pos = new NativeVector3(obj.unityObject.transform.position);
            NativeVector3 vel = new NativeVector3(obj.initialVelocity);

            obj.nativeId = AddRigidBody(nativeWorld, pos, vel, obj.mass, obj.radius, obj.isStatic);
            physicsObjects[i] = obj; // Save ID
        }
    }

    void FixedUpdate()
    {
        if (nativeWorld == IntPtr.Zero) return;

        // 3. Step the native C++ physics simulation matching Unity's physics timestep
        StepSimulation(nativeWorld, Time.fixedDeltaTime);

        // 4. Extract updated coordinates and apply them to Unity visuals
        foreach (var obj in physicsObjects)
