#ifdef _WIN32
    #define EXPORT_API __declspec(dllexport)
#else
    #define EXPORT_API __attribute__((visibility("default")))
#endif

extern "C" {

    // Simple 3D Vector matching game engine layouts
    struct Vector3D {
        float x, y, z;
    };

    // Representation of a spherical rigid body
    struct RigidBody {
        int id;
        Vector3D position;
        Vector3D velocity;
        float mass;
        float radius;
        float restitution; // Bounciness (0.0 = no bounce, 1.0 = perfect bounce)
        bool isStatic;
    };

    // Plugin Lifecycle
    EXPORT_API void* CreatePhysicsWorld(Vector3D gravity);
    EXPORT_API void DestroyPhysicsWorld(void* worldPtr);

    // Body Management
    EXPORT_API int AddRigidBody(void* worldPtr, Vector3D position, float mass, float radius, float restitution, bool isStatic);
    EXPORT_API bool GetBodyState(void* worldPtr, int bodyId, RigidBody& outBody);
    EXPORT_API void ApplyForce(void* worldPtr, int bodyId, Vector3D force);

    // Simulation Step
    EXPORT_API void StepSimulation(void* worldPtr, float deltaTime);

}
```

#### `PhysicsPlugin.cpp` (Physics Solver Implementation)
```cpp
#include "PhysicsPlugin.h"
#include <vector>
#include <unordered_map>
#include <algorithm>

class PhysicsWorld {
public:
    Vector3D gravity;
    std::vector<RigidBody> bodies;
    std::vector<Vector3D> accumulatedForces;
    int nextId = 0;

    PhysicsWorld(Vector3D g) : gravity(g) {}

    int AddBody(Vector3D pos, float mass, float radius, float restitution, bool isStatic) {
        RigidBody body;
        body.id = nextId++;
        body.position = pos;
        body.velocity = {0.0f, 0.0f, 0.0f};
        body.mass = mass;
        body.radius = radius;
        body.restitution = restitution;
        body.isStatic = isStatic;

        bodies.push_back(body);
        accumulatedForces.push_back({0.0f, 0.0f, 0.0f});
        return body.id;
    }

    void Step(float dt) {
        if (dt <= 0.0f) return;

        for (size_t i = 0; i < bodies.size(); ++i) {
            auto& body = bodies[i];
            if (body.isStatic) continue;

            // 1. Integrate Forces (Gravity + User Forces)
            float invMass = 1.0f / body.mass;
            body.velocity.x += (gravity.x + accumulatedForces[i].x * invMass) * dt;
            body.velocity.y += (gravity.y + accumulatedForces[i].y * invMass) * dt;
            body.velocity.z += (gravity.z + accumulatedForces[i].z * invMass) * dt;

            // 2. Integrate Position
            body.position.x += body.velocity.x * dt;
            body.position.y += body.velocity.y * dt;
            body.position.z += body.velocity.z * dt;

            // Clear accumulated forces
            accumulatedForces[i] = {0.0f, 0.0f, 0.0f};

            // 3. Simple Collision Resolution: Ground Plane (y = 0)
            float floorLevel = 0.0f;
            if (body.position.y - body.radius < floorLevel) {
                // Positional correction (prevent sinking)
                body.position.y = floorLevel + body.radius;

                // Bounce calculation (reverse Y velocity based on restitution)
                if (body.velocity.y < 0.0f) {
                    body.velocity.y = -body.velocity.y * body.restitution;

                    // Friction damping on X and Z axes upon contact
                    body.velocity.x *= 0.9f; 
                    body.velocity.z *= 0.9f;
                }
            }
        }
    }
};

// C-API Wrappers (maps the C interface to the C++ OOP instance)

void* CreatePhysicsWorld(Vector3D gravity) {
    return reinterpret_cast<void*>(new PhysicsWorld(gravity));
}

void DestroyPhysicsWorld(void* worldPtr) {
    delete reinterpret_cast<PhysicsWorld*>(worldPtr);
}

int AddRigidBody(void* worldPtr, Vector3D position, float mass, float radius, float restitution, bool isStatic) {
    auto* world = reinterpret_cast<PhysicsWorld*>(worldPtr);
    return world->AddBody(position, mass, radius, restitution, isStatic);
}

bool GetBodyState(void* worldPtr, int bodyId, RigidBody& outBody) {
    auto* world = reinterpret_cast<PhysicsWorld*>(worldPtr);
    auto it = std::find_if(world->bodies.begin(), world->bodies.end(), [bodyId](const RigidBody& b) {
        return b.id == bodyId;
    });
    if (it != world->bodies.end()) {
        outBody = *it;
        return true;
    }
    return false;
}

void ApplyForce(void* worldPtr, int bodyId, Vector3D force) {
    auto* world = reinterpret_cast<PhysicsWorld*>(worldPtr);
    for (size_t i = 0; i < world->bodies.size(); ++i) {
        if (world->bodies[i].id == bodyId) {
            world->accumulatedForces[i].x += force.x;
            world->accumulatedForces[i].y += force.y;
            world->accumulatedForces[i].z += force.z;
            break;
        }
    }
}

void StepSimulation(void* worldPtr, float deltaTime) {
    auto* world = reinterpret_cast<PhysicsWorld*>(worldPtr);
    world->Step(deltaTime);
}
```

