using System.Runtime.InteropServices;
using UnityEngine;

public class CustomPhysicsEngine : MonoBehaviour
{
    // 1. Define DLL Imports (matches the C++ API)
#if UNITY_IPHONE && !UNITY_EDITOR
    private const string DLL_NAME = "__Internal";
#else
    private const string DLL_NAME = "PhysicsPlugin"; // Loads PhysicsPlugin.dll or libPhysicsPlugin.so
#endif

    [StructLayout(LayoutKind.Sequential)]
    public struct Vector3D
    {
        public float x, y, z;
        public Vector3D(Vector3 v) { x = v.x; y = v.y; z = v.z; }
        public Vector3 ToUnity() => new Vector3(x, y, z);
    }

    [StructLayout(LayoutKind.Sequential)]
    public struct RigidBodyData
    {
        public int id;
        public Vector3D position;
        public Vector3D velocity;
        public float mass;
        public float radius;
        public float restitution;
        public bool isStatic;
    }

    [DllImport(DLL_NAME)]
    private static extern IntPtr CreatePhysicsWorld(Vector3D gravity);

    [DllImport(DLL_NAME)]
    private static extern void DestroyPhysicsWorld(IntPtr worldPtr);

    [DllImport(DLL_NAME)]
    private static extern int AddRigidBody(IntPtr worldPtr, Vector3D position, float mass, float radius, float restitution, bool isStatic);

    [DllImport(DLL_NAME)]
    private static extern bool GetBodyState(IntPtr worldPtr, int bodyId, ref RigidBodyData outBody);

    [DllImport(DLL_NAME)]
    private static extern void ApplyForce(IntPtr worldPtr, int bodyId, Vector3D force);

    [DllImport(DLL_NAME)]
    private static extern void StepSimulation(IntPtr worldPtr, float deltaTime);

    // 2. Component Logic
    private IntPtr _worldPtr;

    [Header("Engine Settings")]
    public Vector3 gravity = new Vector3(0, -9.81f, 0);

    [Header("Spawn Ball Settings")]
    public GameObject ballPrefab;
    public float bounciness = 0.7f;
    public float radius = 0.5f;

    private int _spawnedBodyId;
    private GameObject _spawnedBallInstance;

    void Awake()
    {
        // Initialize the Native C++ Physics World
        _worldPtr = CreatePhysicsWorld(new Vector3D(gravity));
    }

    void Start()
    {
        if (ballPrefab != null)
        {
            // Spawn visual object in Unity
            Vector3 spawnPos = new Vector3(0, 10.0f, 0);
            _spawnedBallInstance = Instantiate(ballPrefab, spawnPos, Quaternion.identity);
            _spawnedBallInstance.transform.localScale = Vector3.one * (radius * 2);

            // Register body inside our C++ physics engine
            _spawnedBodyId = AddRigidBody(
                _worldPtr, 
                new Vector3D(spawnPos), 
                mass: 1.0f, 
                radius: radius, 
                restitution: bounciness, 
                isStatic: false
            );
        }
    }

    void FixedUpdate()
    {
        if (_worldPtr == IntPtr.Zero) return;

        // Step the C++ Physics world using the physics timestep (e.g., 0.02s)
        StepSimulation(_worldPtr, Time.fixedDeltaTime);

        // Fetch physics data from Native C++ memory back to Managed C# memory
        RigidBodyData bodyData = new RigidBodyData();
        if (GetBodyState(_worldPtr, _spawnedBodyId, ref bodyData))
        {
            // Update visual transform in Unity
            if (_spawnedBallInstance != null)
            {
                _spawnedBallInstance.transform.position = bodyData.position.ToUnity();
            }
        }
    }

    // Triggered by Unity UI or input to apply custom force
    public void PushBall()
    {
        if (_worldPtr != IntPtr.Zero)
        {
            ApplyForce(_worldPtr, _spawnedBodyId, new Vector3D(new Vector3(5.0f, 5.0f, 0)));
        }
    }

    void OnDestroy()
    {
        // Crucial: Free the C++ memory allocation when stopping the game
        if (_worldPtr != IntPtr.Zero)
        {
            DestroyPhysicsWorld(_worldPtr);
            _worldPtr = IntPtr.Zero;
        }
    }
}
```

