```cpp
// NativePhysics.cpp
#if defined(_WIN32)
#define EXPORT_API __declspec(dllexport)
#else
#define EXPORT_API __attribute__((visibility("default")))
#endif

// A simple physics representation of a spherical body
struct Particle {
    float x, y, z;       // Position
    float vx, vy, vz;    // Velocity
    float radius;
    float elasticity;    // Bounciness (0.0 to 1.0)
};

extern "C" {

    // Instantiates a particle on the native heap
    EXPORT_API Particle* CreateParticle(float x, float y, float z, float radius, float elasticity) {
        return new Particle{ x, y, z, 0.0f, 0.0f, 0.0f, radius, elasticity };
    }

    // Explicitly deallocates native memory to prevent leaks
    EXPORT_API void DestroyParticle(Particle* particle) {
        delete particle;
    }

    // Steps the physics simulation forward (semi-implicit Euler integration)
    EXPORT_API void StepSimulation(Particle* p, float deltaTime, float gravityY, float floorY) {
        if (!p) return;

        // 1. Apply gravity (Acceleration -> Velocity)
        p->vy += gravityY * deltaTime;

        // 2. Apply integration (Velocity -> Position)
        p->x += p->vx * deltaTime;
        p->y += p->vy * deltaTime;
        p->z += p->vz * deltaTime;

        // 3. Simple Collision: Check against horizontal floor plane
        float collisionThreshold = floorY + p->radius;
        if (p->y < collisionThreshold) {
            p->y = collisionThreshold;             // Resolve penetration
            p->vy = -p->vy * p->elasticity;        // Bounce (reverse velocity & apply energy loss)

            // Apply simple friction/damping while on the ground
            p->vx *= 0.95f; 
            p->vz *= 0.95f;
        }
    }

    // Read-only getter for the engine to retrieve positions safely
    EXPORT_API void GetParticlePosition(Particle* p, float* outX, float* outY, float* outZ) {
        if (p) {
            *outX = p->x;
            *outY = p->y;
            *outZ = p->z;
        }
    }
}
```

