```cpp
// physics_solver.cpp

#if defined(_WIN32)
    #define EXPORT_API __declspec(dllexport)
#else
    #define EXPORT_API __attribute__((visibility("default")))
#endif

// Blit-compatible 3D Vector matching Unity's memory layout
struct Vector3 {
    float x;
    float y;
    float z;
};

extern "C" {

    /// Steps a sphere's physics using basic Symplectic Euler integration
    /// and resolves a simple collision against a flat ground plane (Y = 0).
    EXPORT_API void StepPhysics(
        Vector3* position, 
        Vector3* velocity, 
        const float gravity, 
        const float bounciness, 
        const float radius, 
        const float dt
    ) {
        if (!position || !velocity) return;

        // 1. Apply Gravity Acceleration
        velocity->y += gravity * dt;

        // 2. Integrate Position
        position->x += velocity->x * dt;
        position->y += velocity->y * dt;
        position->z += velocity->z * dt;

        // 3. Collision Detection with Ground Plane (Y = 0)
        float floorLevel = 0.0f + radius;
        if (position->y < floorLevel) {
            // Collision Resolution (Position correction)
            position->y = floorLevel; 

            // Collision Response (Bounce velocity reflection)
            velocity->y = -velocity->y * bounciness; 

            // Friction (Dampen horizontal movement on contact)
            velocity->x *= 0.95f;
            velocity->z *= 0.95f;
        }
    }
}
```

