### Part 1: The Native C++ Physics Plugin (`CustomPhysics.cpp`)

This code defines a simple 3D physics world, a rigid body representation, and an integration step. Save this file as `CustomPhysics.cpp`.

```cpp
#include <vector>
#include <cmath>

// Define platform-specific DLL export macros
#if defined(_MSC_VER) // Windows
    #define EXPORT_API __declspec(dllexport)
#else // macOS / Linux
    #define EXPORT_API __attribute__((visibility("default")))
#endif

// A simple 3D Vector
struct Vector3 {
    float x, y, z;
};

// A minimal RigidBody representation
struct RigidBody {
    int id;
    Vector3 position;
    Vector3 velocity;
    float mass;
    bool isStatic;
};

// The Physics World containing all bodies
class PhysicsWorld {
public:
    std::vector<RigidBody> bodies;
    Vector3 gravity = { 0.0f, -9.81f, 0.0f };
    int nextId = 0;

    int AddBody(float x, float y, float z, float mass, bool isStatic) {
        RigidBody body;
        body.id = nextId++;
        body.position = { x, y, z };
        body.velocity = { 0.0f, 0.0f, 0.0f };
        body.mass = mass;
        body.isStatic = isStatic;
        bodies.push_back(body);
        return body.id;
    }

    void Step(float deltaTime) {
        for (auto& body : bodies) {
            if (body.isStatic) continue;

            // 1. Integrate Gravity (Acceleration -> Velocity)
            body.velocity.x += gravity.x * deltaTime;
            body.velocity.y += gravity.y * deltaTime;
            body.velocity.z += gravity.z * deltaTime;

            // 2. Integrate Position (Velocity -> Position)
            body.position.x += body.velocity.x * deltaTime;
            body.position.y += body.velocity.y * deltaTime;
            body.position.z += body.velocity.z * deltaTime;

            // 3. Simple Collision Resolution: Ground plane (Y = 0)
            const float floorHeight = 0.5f; // half-extent of a default cube
            if (body.position.y < floorHeight) {
                body.position.y = floorHeight;
                // Bounce with energy loss (coefficient of restitution = 0.5)
                body.velocity.y = -body.velocity.y * 0.5f; 

                // Friction
                body.velocity.x *= 0.9f;
                body.velocity.z *= 0.9f;
            }
        }
    }
};

// --- C-Linkage Interface for Game Engine Integration ---
extern "C" {

    EXPORT_API PhysicsWorld* CreateWorld() {
        return new PhysicsWorld();
    }

    EXPORT_API void DestroyWorld(PhysicsWorld* world) {
        delete world;
    }

    EXPORT_API int AddRigidBody(PhysicsWorld* world, float x, float y, float z, float mass, bool isStatic) {
        if (!world) return -1;
        return world->AddBody(x, y, z, mass, isStatic);
    }

    EXPORT_API void StepWorld(PhysicsWorld* world, float deltaTime) {
        if (world) {
            world->Step(deltaTime);
        }
    }

    EXPORT_API void GetBodyPosition(PhysicsWorld* world, int bodyId, float* outX, float* outY, float* outZ) {
        if (!world) return;
        for (const auto& body : world->bodies) {
            if (body.id == bodyId) {
                *outX = body.position.x;
                *outY = body.position.y;
                *outZ = body.position.z;
                return;
            }
        }
    }
}
```

