This minimal plugin moves a sphere under the influence of gravity and bounces it when it hits a floor plane ($y = 0$).

---

### Part 1: The Native Code (<language>C++</language>)

This is the core physics engine. It defines a data structure representing a physical body and updates its state every frame.

Save this file as **`SimplePhysicsPlugin.cpp`**:

```cpp
// SimplePhysicsPlugin.cpp

#if defined(_MSC_VER)
    // Windows
    #define EXPORT_API __declspec(dllexport)
#else
    // macOS / Linux / iOS / Android
    #define EXPORT_API __attribute__((visibility("default")))
#endif

extern "C" {
    // A representation of a Rigid Body optimized for cache-locality.
    // Must match the C# struct layout exactly.
    struct RigidBodyState {
        float px, py, pz;     // Position
        float vx, vy, vz;     // Velocity
        float mass;
        float gravity;        // Downward acceleration (e.g., -9.81)
        float restitution;    // Bounciness (0.0 = no bounce, 1.0 = perfect bounce)
    };

    // The physics integration step.
    EXPORT_API void StepPhysics(RigidBodyState* body, float dt) {
        if (!body || dt <= 0.0f) return;

        // 1. Apply Gravity to Vertical Velocity (vy)
        body->vy += body->gravity * dt;

        // 2. Integrate Position (Euler Method)
        body->px += body->vx * dt;
        body->py += body->vy * dt;
        body->pz += body->vz * dt;

        // 3. Simple Ground Collision Resolution (Floor at y = 0)
        const float groundHeight = 0.0f;
        if (body->py < groundHeight) {
            // Move body back to surface to resolve penetration
            body->py = groundHeight; 

            // Reverse velocity along the Y axis and apply bounciness (restitution)
            body->vy = -body->vy * body->restitution;

            // Stop micro-bounces (resting contact threshold)
            if (body->vy < 0.2f && body->vy > -0.2f) {
                body->vy = 0.0f;
            }
        }
    }
}
```

---

### Part 2: The Engine Bridge (<language>C#</language>)

This Unity component acts as the interface. It maps the Unity Transform to the native C++ physics state, sends it to the plugin to be solved, and updates the GameObject's position.

Save this file as **`PhysicsBody.cs`**:

```csharp
// PhysicsBody.cs
using System;
using System.Runtime.InteropServices;
using UnityEngine;

public class PhysicsBody : MonoBehaviour
{
    // Replicate the C++ struct structure using Sequential layout
    [StructLayout(LayoutKind.Sequential)]
    public struct RigidBodyState
    {
        public float px, py, pz;
        public float vx, vy, vz;
        public float mass;
        public float gravity;
        public float restitution;
    }

    // Link the native C++ function from the compiled library
    #if UNITY_IPHONE && !UNITY_EDITOR
        [DllImport("__Internal")]
    #else
        [DllImport("SimplePhysicsPlugin", CallingConvention = CallingConvention.Cdecl)]
    #endif
    private static extern void StepPhysics(ref RigidBodyState body, float dt);

    [Header("Initial Physics State")]
    public Vector3 initialVelocity = new Vector3(2.0f, 10.0f, 0.0f);
    public float mass = 1.0f;
    public float gravityAcceleration = -9.81f;
    [Range(0f, 1f)] public float bounciness = 0.75f;

    private RigidBodyState _state;

    void Start()
    {
        // Copy Unity transform data to our custom C++ physics state structure
        _state = new RigidBodyState
        {
            px = transform.position.x,
            py = transform.position.y,
            pz = transform.position.z,
            vx = initialVelocity.x,
            vy = initialVelocity.y,
            vz = initialVelocity.z,
            mass = mass,
            gravity = gravityAcceleration,
            restitution = bounciness
        };
    }

    void FixedUpdate()
    {
        // Pass the state by reference ('ref') to the C++ plugin.
        // This avoids memory allocation and executes directly in C++ speed.
        StepPhysics(ref _state, Time.fixedDeltaTime);

        // Apply the resolved physics state back to the Unity GameObject
        transform.position = new Vector3(_state.px, _state.py, _state.pz);
    }
}
```

