To create a custom physics plugin, we will implement a hybrid architecture: a **high-performance native C++ core** that handles the physics calculations, and a **C# wrapper** to integrate it into a commercial game engine (**Unity**).

This minimal working version implements:
1. **Euler Integration** (gravity and velocity).
2. **Sphere-vs-Floor Collision Detection**.
3. **Impulse Resolution** (bounciness/restitution).

---

### Part 1: The Native C++ Physics Core (`CustomPhysics.cpp`)

This code compiles into a dynamic library (`.dll` on Windows, `.dylib` on macOS, `.so` on Linux). It uses a clean C-compatible interface (`extern "C"`) so the game engine can call it without C++ name-mangling issues.

```cpp
// CustomPhysics.cpp
#if defined(_WIN32)
#define EXPORT_API __declspec(dllexport)
#else
#define EXPORT_API __attribute__((visibility("default")))
#endif

extern "C" {

    // Simple 3D Vector struct matching Unity's Vector3 layout
    struct Vector3 {
        float x, y, z;
    };

    // Representation of a physical rigid body
    struct PhysicsBody {
        Vector3 position;
        Vector3 velocity;
        float mass;
        float radius;
        float restitution; // Bounciness (0.0 = no bounce, 1.0 = perfect bounce)
    };

    // API: Initialize a new physics body
    EXPORT_API PhysicsBody* CreatePhysicsBody(float x, float y, float z, float mass, float radius, float restitution) {
        PhysicsBody* body = new PhysicsBody();
        body->position = { x, y, z };
        body->velocity = { 0.0f, 0.0f, 0.0f };
        body->mass = mass;
        body->radius = radius;
        body->restitution = restitution;
        return body;
    }

    // API: Destroy a physics body to prevent memory leaks
    EXPORT_API void DestroyPhysicsBody(PhysicsBody* body) {
        if (body != nullptr) {
            delete body;
        }
    }

    // API: Step the physics simulation for a single body
    EXPORT_API void StepSimulation(PhysicsBody* body, float deltaTime, float gravity) {
        if (body == nullptr) return;

        // 1. Integrate Forces (Apply Gravity)
        body->velocity.y += gravity * deltaTime;

        // 2. Integrate Velocities (Apply Velocity to Position)
        body->position.x += body->velocity.x * deltaTime;
        body->position.y += body->velocity.y * deltaTime;
        body->position.z += body->velocity.z * deltaTime;

        // 3. Collision Detection & Resolution (Simple Ground Plane at Y = 0)
        float floorY = 0.0f;
        float penetration = floorY - (body->position.y - body->radius);

        if (penetration > 0.0f) {
            // Positional Correction (prevents sinking)
            body->position.y = floorY + body->radius;

            // Impulse Resolution (Bounce)
            // If moving downwards, invert and scale Y velocity by restitution
            if (body->velocity.y < 0.0f) {
                body->velocity.y = -body->velocity.y * body->restitution;
            }
        }
    }
}
```

#### How to Compile:
*   **Windows (MSVC via Developer Command Prompt):**
    `cl /LD /O2 CustomPhysics.cpp /Fe:CustomPhysics.dll`
*   **macOS (Clang):**
    `clang++ -dynamiclib -O3 CustomPhysics.cpp -o CustomPhysics.dylib`
*   **Linux (GCC):**
    `g++ -shared -fPIC -O3 CustomPhysics.cpp -o libCustomPhysics.so`

---

### Part 2: Unity Engine Integration (C# Wrapper)

Place the compiled library (`CustomPhysics.dll`/`dylib`/`so`) inside your Unity project's `Assets/Plugins/` folder. 

Then, create this C# script and attach it to a Unity Sphere GameObject.

```csharp
// CustomPhysicsComponent.cs
using System;
using System.Runtime.InteropServices;
using UnityEngine;

public class CustomPhysicsComponent : MonoBehaviour
{
    // Name of the native library file (without extension)
    private const string LIB_NAME = "CustomPhysics";

    // Mirror the C++ structs exactly in memory
    [StructLayout(LayoutKind.Sequential)]
    private struct NativeVector3
    {
        public float x, y, z;
    }

    [StructLayout(LayoutKind.Sequential)]
    private struct NativePhysicsBody
    {
        public NativeVector3 position;
        public NativeVector3 velocity;
        public float mass;
        public float radius;
        public float restitution;
    }

    // Import the C++ DLL functions
    [DllImport(LIB_NAME, EntryPoint = "CreatePhysicsBody")]
    private static extern IntPtr CreatePhysicsBody(float x, float y, float z, float mass, float radius, float restitution);

    [DllImport(LIB_NAME, EntryPoint = "DestroyPhysicsBody")]
    private static extern void DestroyPhysicsBody(IntPtr body);

    [DllImport(LIB_NAME, EntryPoint = "StepSimulation")]
    private static extern void StepSimulation(IntPtr body, float deltaTime, float gravity);

    [Header("Physics Settings")]
    public float mass = 1.0f;
    public float radius = 0.5f;
    [Range(0f, 1f)] public float bounciness = 0.75f;
    public float gravity = -9.81f;

    private IntPtr _nativeBodyPtr = IntPtr.Zero;

    void Start()
    {
        // 1. Set Unity Transform scale to match our radius
        transform.localScale = Vector3.one * (radius * 2f);

        // 2. Instantiate the physics body in the native C++ engine
        Vector3 pos = transform.position;
        _nativeBodyPtr = CreatePhysicsBody(pos.x, pos.y, pos.z, mass, radius, bounciness);
    }

    void FixedUpdate()
    {
        if (_nativeBodyPtr == IntPtr.Zero) return;

        // 3. Step the simulation in native C++
        StepSimulation(_nativeBodyPtr, Time.fixedDeltaTime, gravity);

        // 4. Retrieve the updated data from C++ memory
        NativePhysicsBody body = Marshal.PtrToStructure<NativePhysicsBody>(_nativeBodyPtr);

        // 5. Update the Unity GameObject's position
        transform.position = new Vector3(body.position.x, body.position.y, body.position.z);
    }

    void OnDestroy()
    {
        // 6. ALWAYS free native memory when the object is destroyed
        if (_nativeBodyPtr != IntPtr.Zero)
        {
            DestroyPhysicsBody(_nativeBodyPtr);
            _nativeBodyPtr = IntPtr.Zero;
        }
    }
}
```

### How to Test This Plugin:
1. Create a new 3D Scene in Unity.
2. Create a **Plane** at position `(0, 0, 0)` to act as a visual floor.
3. Create a **Sphere** at position `(0, 10, 0)`. Remove its default `Rigidbody` and `Sphere Collider` components.
4. Attach the `CustomPhysicsComponent` script to the Sphere.
5. Press **Play**. 

The sphere will fall under the custom gravity, collide perfectly with the $Y = 0$ floor plane, and bounce repeatedly, decreasing in height each time based on the `bounciness` variable—all calculated inside your custom C++ native library.

