// Simple 2D Vector math helper
struct Vec2 {
    float x = 0.0f;
    float y = 0.0f;

    Vec2() = default;
    Vec2(float x, float y) : x(x), y(y) {}

    Vec2 operator+(const Vec2& v) const { return {x + v.x, y + v.y}; }
    Vec2 operator-(const Vec2& v) const { return {x - v.x, y - v.y}; }
    Vec2 operator*(float s) const { return {x * s, y * s}; }
    Vec2 operator/(float s) const { return {x / s, y / s}; }
    void operator+=(const Vec2& v) { x += v.x; y += v.y; }
    void operator-=(const Vec2& v) { x -= v.x; y -= v.y; }

    float Dot(const Vec2& v) const { return x * v.x + y * v.y; }
    float Cross(const Vec2& v) const { return x * v.y - y * v.x; }
    Vec2 Cross(float s) const { return {s * y, -s * x}; } // Vector cross scalar

    float LengthSq() const { return x * x + y * y; }
    float Length() const { return std::sqrt(LengthSq()); }

    Vec2 Normalize() const {
        float len = Length();
        return len > 0.0001f ? *this / len : Vec2{0.0f, 0.0f};
    }
};

inline Vec2 operator*(float s, const Vec2& v) { return v * s; }
inline Vec2 Cross(float s, const Vec2& v) { return {-s * v.y, s * v.x}; } // Scalar cross vector

// Rigid Body definition
struct RigidBody {
    Vec2 position;
    Vec2 velocity;
    float angle = 0.0f;          // in radians
    float angularVelocity = 0.0f;

    float mass = 1.0f;
    float invMass = 1.0f;
    float inertia = 1.0f;        // Moment of inertia
    float invInertia = 1.0f;

    float radius = 1.0f;         // Circular shape simplifier
    float restitution = 0.6f;    // Bounciness (0 = clay, 1 = superball)
    float staticFriction = 0.4f;
    float dynamicFriction = 0.2f;

    Vec2 force{0.0f, 0.0f};
    float torque = 0.0f;

    RigidBody(Vec2 pos, float r, float m) : position(pos), radius(r), mass(m) {
        if (m > 0.0f) {
            invMass = 1.0f / m;
            // Moment of inertia for solid cylinder/disk: I = 0.5 * m * r^2
            inertia = 0.5f * m * r * r;
            invInertia = 1.0f / inertia;
        } else {
            // Static/infinite mass object
            invMass = 0.0f;
            inertia = 0.0f;
            invInertia = 0.0f;
        }
    }

    void ApplyForce(const Vec2& f, const Vec2& contactPoint) {
        force += f;
        // Torque = r x F
        Vec2 r = contactPoint - position;
        torque += r.Cross(f);
    }

    void Integrate(float dt) {
        if (invMass == 0.0f) return; // Static object

        // Semi-implicit Euler
        velocity += (force * invMass) * dt;
        position += velocity * dt;

        angularVelocity += (torque * invInertia) * dt;
        angle += angularVelocity * dt;

        // Clear accumulators
        force = {0.0f, 0.0f};
        torque = 0.0f;
    }
};

// Manifold for tracking collision contacts
struct ContactManifold {
    RigidBody* bodyA;
    RigidBody* bodyB;
    Vec2 normal;          // Direction from A to B
    float penetration;    // Overlap depth
    Vec2 contactPoint;
};

// Simple 2D Physics World
class PhysicsWorld {
private:
    std::vector<RigidBody> bodies;
    Vec2 gravity{0.0f, 9.81f};

    void DetectCollisions(std::vector<ContactManifold>& contacts) {
        // Broad phase (O(N^2) for simplicity, can be optimized with Spatial Partitioning)
        for (size_t i = 0; i < bodies.size(); ++i) {
            for (size_t j = i + 1; j < bodies.size(); ++j) {
                RigidBody& A = bodies[i];
                RigidBody& B = bodies[j];

                if (A.invMass == 0.0f && B.invMass == 0.0f) continue;

                // Circle vs Circle Narrow Phase
                Vec2 ab = B.position - A.position;
                float distSq = ab.LengthSq();
                float radiusSum = A.radius + B.radius;

                if (distSq < radiusSum * radiusSum) {
                    float dist = std::sqrt(distSq);
                    ContactManifold contact;
                    contact.bodyA = &A;
                    contact.bodyB = &B;
                    contact.normal = dist > 0.001f ? ab / dist : Vec2{0.0f, 1.0f};
                    contact.penetration = radiusSum - dist;
                    contact.contactPoint = A.position + contact.normal * A.radius;
                    contacts.push_back(contact);
                }
            }
        }
    }

    void ResolveCollisions(std::vector<ContactManifold>& contacts) {
        for (auto& contact : contacts) {
            RigidBody& A = *contact.bodyA;
            RigidBody& B = *contact.bodyB;
            Vec2 normal = contact.normal;

            // 1. Resolve Penetration (Position Correction to prevent sinking)
            const float percent = 0.4f; // Penetration percentage to resolve per frame
            const float slop = 0.01f;    // Penetration allowance
            Vec2 correction = std::max(contact.penetration - slop, 0.0f) / (A.invMass + B.invMass) * percent * normal;
            A.position -= correction * A.invMass;
            B.position += correction * B.invMass;

            // 2. Resolve Velocities (Impulse Method)
            Vec2 rA = contact.contactPoint - A.position;
            Vec2 rB = contact.contactPoint - B.position;

            // Relative velocity
            Vec2 vA = A.velocity + Cross(A.angularVelocity, rA);
            Vec2 vB = B.velocity + Cross(B.angularVelocity, rB);
            Vec2 rv = vB - vA;

            float velAlongNormal = rv.Dot(normal);
            if (velAlongNormal > 0) continue; // Moving apart already

            // Calculate Restitution
            float e = std::min(A.restitution, B.restitution);

            // Calculate normal impulse scalar
            float rACrossN = rA.Cross(normal);
            float rBCrossN = rB.Cross(normal);
            float invMassSum = A.invMass + B.invMass + 
                               (rACrossN * rACrossN) * A.invInertia + 
                               (rBCrossN * rBCrossN) * B.invInertia;

            float j = -(1.0f + e) * velAlongNormal / invMassSum;

            // Apply normal impulse
            Vec2 impulse = j * normal;
            A.velocity -= impulse * A.invMass;
            A.angularVelocity -= A.invInertia * rA.Cross(impulse);
            B.velocity += impulse * B.invMass;
            B.angularVelocity += B.invInertia * rB.Cross(impulse);

            // 3. Friction Impulse
            vA = A.velocity + Cross(A.angularVelocity, rA);
            vB = B.velocity + Cross(B.angularVelocity, rB);
            rv = vB - vA;

            Vec2 tangent = rv - (rv.Dot(normal) * normal);
            tangent = tangent.Normalize();

            float vt = rv.Dot(tangent);
            float rACrossT = rA.Cross(tangent);
            float rBCrossT = rB.Cross(tangent);
            float invMassSumT = A.invMass + B.invMass + 
                                (rACrossT * rACrossT) * A.invInertia + 
                                (rBCrossT * rBCrossT) * B.invInertia;

            float jt = -vt / invMassSumT;

            // Clamp friction using Coulomb's Law
            float mu = std::sqrt(A.staticFriction * B.staticFriction);
            float dynamicMu = std::sqrt(A.dynamicFriction * B.dynamicFriction);

            Vec2 frictionImpulse;
            if (std::abs(jt) < j * mu) {
                frictionImpulse = jt * tangent;
            } else {
                frictionImpulse = -j * dynamicMu * tangent;
            }

            // Apply friction impulse
            A.velocity -= frictionImpulse * A.invMass;
            A.angularVelocity -= A.invInertia * rA.Cross(frictionImpulse);
            B.velocity += frictionImpulse * B.invMass;
            B.angularVelocity += B.invInertia * rB.Cross(frictionImpulse);
        }
    }

public:
    void AddBody(const RigidBody& body) {
        bodies.push_back(body);
    }

    void Step(float dt) {
        // Apply Gravity and integrate forces
        for (auto& body : bodies) {
            if (body.invMass > 0.0f) {
                body.velocity += gravity * dt;
            }
        }

        // Collision Pipeline
        std::vector<ContactManifold> contacts;
        DetectCollisions(contacts);
        ResolveCollisions(contacts);

        // Movement Integration
        for (auto& body : bodies) {
            body.Integrate(dt);
        }
    }

    const std::vector<RigidBody>& GetBodies() const { return bodies; }
};

// ASCII Terminal Renderer
void Render(const PhysicsWorld& world, int width, int height) {
    // Write directly to an off-screen buffer first (avoids flickering)
    std::vector<std::string> screen(height, std::string(width, ' '));

    // Render Box Borders
    for (int x = 0; x < width; ++x) {
        screen[0][x] = '#';
        screen[height - 1][x] = '#';
    }
    for (int y = 0; y < height; ++y) {
        screen[y][0] = '#';
        screen[y][width - 1] = '#';
    }

    // Render Rigid Bodies
    for (const auto& body : world.GetBodies()) {
        int cx = static_cast<int>(std::round(body.position.x));
        int cy = static_cast<int>(std::round(body.position.y));
        int r = static_cast<int>(std::round(body.radius));

        // Draw basic circle shape
        for (int y = -r; y <= r; ++y) {
            for (int x = -r; x <= r; ++x) {
                if (x*x + y*y <= r*r + 1) {
                    int px = cx + x;
                    int py = cy + y;
                    if (px > 0 && px < width - 1 && py > 0 && py < height - 1) {
                        // Mark orientation inside the body using rotational vector mapping
                        float angleOffset = std::atan2(static_cast<float>(y), static_cast<float>(x));
                        float diff = std::fmod(angleOffset - body.angle, 2.0f * 3.14159f);
                        if (std::abs(diff) < 0.3f && (x*x + y*y > (r-1)*(r-1))) {
                            screen[py][px] = '*'; // Orientation needle
                        } else {
                            screen[py][px] = body.invMass == 0.0f ? '=' : 'O';
                        }
                    }
                }
            }
        }
    }

    // ANSI escape code to jump cursor to top-left of terminal (flicker-free rendering)
    std::cout << "\033[H"; 
    for (const auto& row : screen) {
        std::cout << row << "\n";
    }
    std::cout.flush();
}

