    auto currentTime = high_resolution_clock::now();
    double accumulator = 0.0;

    std::cout << "Simulation running. Press Ctrl+C to exit.\n";

    while (true) {
        auto newTime = high_resolution_clock::now();
        double frameTime = duration<double>(newTime - currentTime).count();
        currentTime = newTime;

        // Prevent "spiral of death" during heavy lag spikes
        if (frameTime > 0.25) {
            frameTime = 0.25;
        }

        accumulator += frameTime;

        // Fixed Timestep Accumulator: Keeps physics running deterministically
        while (accumulator >= dt) {
            world.Step(static_cast<float>(dt));
            accumulator -= dt;
