        // Render at frame-rate limit
        Render(world, screenWidth, screenHeight);

        // Calculate sleep time to free CPU cycles while respecting the frame rate constraint
        auto loopEndTime = high_resolution_clock::now();
        double elapsed = duration<double>(loopEndTime - currentTime).count();
        double sleepTarget = dt - elapsed;

        if (sleepTarget > 0.0) {
            std::this_thread::sleep_for(duration<double>(sleepTarget));
        }
    }

    return 0;
}
