#include <iostream>
#include <vector>
#include <chrono>
#include <thread>
#include <cmath>
#include <algorithm>

// Simple 2D Vector Helper
struct Vector2 {
    float x, y;
    Vector2() : x(0.0f), y(0.0f) {}
    Vector2(float x, float y) : x(x), y(y) {}

    Vector2 operator+(const Vector2& v) const { return Vector2(x + v.x, y + v.y); }
    Vector2 operator-(const Vector2& v) const { return Vector2(x - v.x, y - v.y); }
    Vector2 operator*(float scalar) const { return Vector2(x * scalar, y * scalar); }
    Vector2 operator/(float scalar) const { return Vector2(x / scalar, y / scalar); }

    float dot(const Vector2& v) const { return x * v.x + y * v.y; }
    float lengthSquared() const { return x * x + y * y; }
    float length() const { return std::sqrt(lengthSquared()); }
    Vector2 normalized() const {
        float len = length();
        return (len > 0.0f) ? *this / len : Vector2(0.0f, 0.0f);
    }
};

// Rigid Body definition
struct RigidBody {
    Vector2 position;
    Vector2 velocity;
    float mass;
    float invMass;
    float radius;
    float restitution; // Bounciness (0.0 = no bounce, 1.0 = perfect bounce)
    char symbol;       // For terminal rendering

    RigidBody(Vector2 pos, Vector2 vel, float m, float r, float e, char s)
        : position(pos), velocity(vel), mass(m), radius(r), restitution(e), symbol(s) {
        invMass = (m > 0.0f) ? 1.0f / m : 0.0f; // Static objects have 0 mass (infinite mass)
    }
};

// Global Simulation Constants
const Vector2 GRAVITY(0.0f, -9.81f);
const float WIDTH = 40.0f;   // Simulation area width
const float HEIGHT = 20.0f;  // Simulation area height

// Resolves collision between two circle rigid bodies (Impulse Physics)
void ResolveCollision(RigidBody& a, RigidBody& b) {
    Vector2 relative_pos = b.position - a.position;
    float distance = relative_pos.length();
    float radius_sum = a.radius + b.radius;

    // Check for overlap
    if (distance >= radius_sum) return;

    // Contact normal
    Vector2 normal = (distance == 0.0f) ? Vector2(0, 1) : relative_pos / distance;

    // Relative velocity along the normal
    Vector2 relative_vel = b.velocity - a.velocity;
    float vel_along_normal = relative_vel.dot(normal);

    // Do not resolve if velocities are separating
    if (vel_along_normal > 0) return;

    // Calculate restitution (elasticity)
    float e = std::min(a.restitution, b.restitution);

    // Calculate impulse scalar
    float j = -(1.0f + e) * vel_along_normal;
    j /= (a.invMass + b.invMass);

    // Apply impulse to velocities
    Vector2 impulse = normal * j;
    a.velocity = a.velocity - impulse * a.invMass;
    b.velocity = b.velocity + impulse * b.invMass;

    // Positional correction to prevent objects from sinking/sticking together
    const float percent = 0.4f; // Penetration percentage to correct
    const float slop = 0.01f;    // Penetration allowance
    float penetration = radius_sum - distance;
    Vector2 correction = normal * (std::max(penetration - slop, 0.0f) / (a.invMass + b.invMass) * percent);
    a.position = a.position - correction * a.invMass;
    b.position = b.position + correction * b.invMass;
}

// Resolves boundaries (Collision with walls)
void ResolveBoundaries(RigidBody& body) {
    // Left & Right walls
    if (body.position.x - body.radius < 0.0f) {
        body.position.x = body.radius;
        body.velocity.x = -body.velocity.x * body.restitution;
    } else if (body.position.x + body.radius > WIDTH) {
        body.position.x = WIDTH - body.radius;
        body.velocity.x = -body.velocity.x * body.restitution;
    }

    // Floor & Ceiling
    if (body.position.y - body.radius < 0.0f) {
        body.position.y = body.radius;
        body.velocity.y = -body.velocity.y * body.restitution;
    } else if (body.position.y + body.radius > HEIGHT) {
        body.position.y = HEIGHT - body.radius;
        body.velocity.y = -body.velocity.y * body.restitution;
    }
}

// Integrates forces and updates body positions
void Integrate(RigidBody& body, float dt) {
    if (body.invMass == 0.0f) return; // Skip static bodies

    // Semi-Implicit Euler integration
    body.velocity = body.velocity + (GRAVITY * dt);
    body.position = body.position + (body.velocity * dt);
}

// The Physics Step logic loop
void PhysicsStep(std::vector<RigidBody>& bodies, float dt) {
    // 1. Integrate forces (gravity/motion)
    for (auto& body : bodies) {
        Integrate(body, dt);
    }

    // 2. Pairwise rigid body collisions
    for (size_t i = 0; i < bodies.size(); ++i) {
        for (size_t j = i + 1; j < bodies.size(); ++j) {
            ResolveCollision(bodies[i], bodies[j]);
        }
    }

    // 3. Boundary constraints
    for (auto& body : bodies) {
        ResolveBoundaries(body);
    }
}

// Simple ASCII Renderer
void Render(const std::vector<RigidBody>& bodies) {
    // Initialize empty text screen buffer
    std::vector<std::string> screen(static_cast<int>(HEIGHT), std::string(static_cast<int>(WIDTH), ' '));

    // Draw rigid bodies onto the screen buffer
    for (const auto& body : bodies) {
        int cx = static_cast<int>(body.position.x);
        int cy = static_cast<int>(body.position.y);

        // Render simple circle outline/point based on radius
        for (int y = -static_cast<int>(body.radius); y <= static_cast<int>(body.radius); ++y) {
            for (int x = -static_cast<int>(body.radius); x <= static_cast<int>(body.radius); ++x) {
                if (x*x + y*y <= body.radius * body.radius) {
                    int screenX = cx + x;
                    int screenY = cy + y;
                    // Y-axis inverted because terminals print from top-to-bottom
                    int invertedY = static_cast<int>(HEIGHT) - 1 - screenY;

                    if (screenX >= 0 && screenX < WIDTH && invertedY >= 0 && invertedY < HEIGHT) {
                        screen[invertedY][screenX] = body.symbol;
                    }
                }
            }
        }
    }

    // ANSI escape sequence to clear console screens cleanly (prevents flickering)
    std::cout << "\x1B[2J\x1B[H";

    // Print ASCII borders and content
    std::cout << std::string(WIDTH + 2, '#') << "\n";
    for (const auto& row : screen) {
        std::cout << '#' << row << "#\n";
    }
    std::cout << std::string(WIDTH + 2, '#') << "\n";
}

int main() {
    // Instantiate bodies with (Position, Velocity, Mass, Radius, Restitution, Symbol)
    std::vector<RigidBody> bodies = {
        RigidBody(Vector2(5.0f, 15.0f),  Vector2(12.0f, 5.0f),  3.0f, 1.5f, 0.8f, '@'), // Heavy Bouncing Ball
        RigidBody(Vector2(35.0f, 12.0f), Vector2(-10.0f, 2.0f), 1.0f, 1.0f, 0.9f, 'O'), // Lighter Ball
        RigidBody(Vector2(20.0f, 4.0f),  Vector2(0.0f, 0.0f),   0.0f, 2.5f, 0.4f, '#')  // Giant Static Pillar (0 Mass)
    };

    // Frame-rate constraints parameters ("Fix Your Timestep")
    const double dt = 1.0 / 60.0; // 60 FPS physics logic step (0.01666 seconds)
    double accumulator = 0.0;

    auto previous_time = std::chrono::high_resolution_clock::now();

    std::cout << "Starting Simulation... Press Ctrl+C to stop.\n";
    std::this_thread::sleep_for(std::chrono::seconds(1));

    // Simulation Loop
    while (true) {
        auto current_time = std::chrono::high_resolution_clock::now();
        double frame_time = std::chrono::duration<double>(current_time - previous_time).count();
        previous_time = current_time;

        // Cap frame time to prevent "spiral of death" during lag spikes
        if (frame_time > 0.25) {
            frame_time = 0.25;
        }

        accumulator += frame_time;

        // Consume accumulator time in fixed fractions (dt).
        // This guarantees deterministic physics behavior regardless of frame rate drops.
        while (accumulator >= dt) {
            PhysicsStep(bodies, static_cast<float>(dt));
            accumulator -= dt;
        }

        // Render scene
        Render(bodies);

        // Sleep to throttle frame rate and prevent excessive CPU usage (aiming for roughly ~60 FPS renders)
        std::this_thread::sleep_for(std::chrono::milliseconds(16));
    }

    return 0;
}
