#include <iostream>
#include <vector>
#include <cmath>
#include <chrono>
#include <thread>
#include <algorithm>
#include <string>

// Simple 2D Vector mathematics
struct Vec2 {
    float x = 0.0f;
    float y = 0.0f;

    Vec2 operator+(const Vec2& v) const { return {x + v.x, y + v.y}; }
    Vec2 operator-(const Vec2& v) const { return {x - v.x, y - v.y}; }
    Vec2 operator*(float scalar) const { return {x * scalar, y * scalar}; }
    Vec2 operator/(float scalar) const { return {x / scalar, y / scalar}; }

    float lengthSq() const { return x * x + y * y; }
    float length() const { return std::sqrt(lengthSq()); }

    Vec2 normalized() const {
        float len = length();
        return len > 0.0f ? *this / len : Vec2{0.0f, 0.0f};
    }
};

float dot(const Vec2& a, const Vec2& b) {
    return a.x * b.x + a.y * b.y;
}

// Rigid Body definition
struct RigidBody {
    Vec2 position;
    Vec2 velocity;
    Vec2 force;
    float mass;
    float invMass;
    float radius;
    float restitution; // Bounciness coefficient: [0 = inelastic, 1 = perfectly elastic]

    RigidBody(Vec2 pos, Vec2 vel, float m, float r, float rest)
        : position(pos), velocity(vel), mass(m), radius(r), restitution(rest) {
        invMass = (m > 0.0f) ? 1.0f / m : 0.0f; // Static objects have 0 mass (infinite mass)
    }

    void applyForce(const Vec2& f) {
        if (invMass == 0.0f) return;
        force = force + f;
    }

    // Semi-Implicit Euler Integration (highly stable for real-time physics)
    void integrate(float dt) {
        if (invMass == 0.0f) return;

        // Update velocity: v = v + a * dt
        velocity = velocity + (force * invMass) * dt;

        // Update position: x = x + v * dt
        position = position + velocity * dt;

        // Clear forces for next frame
        force = {0.0f, 0.0f};
    }
};

// Physics Engine World State
class PhysicsWorld {
public:
    std::vector<RigidBody> bodies;
    Vec2 gravity = {0.0f, 9.81f}; // Downwards gravity
    float width;
    float height;

    PhysicsWorld(float w, float h) : width(w), height(h) {}

    void step(float dt) {
        // 1. Apply global forces (Gravity)
        for (auto& body : bodies) {
            body.applyForce(gravity * body.mass);
        }

        // 2. Resolve Dynamic-to-Dynamic (Circle to Circle) Collisions
        for (size_t i = 0; i < bodies.size(); ++i) {
            for (size_t j = i + 1; j < bodies.size(); ++j) {
                resolveCollision(bodies[i], bodies[j]);
            }
        }

        // 3. Resolve Boundary/Wall Collisions (Dynamic-to-Static)
        for (auto& body : bodies) {
            handleWallCollisions(body);
        }

        // 4. Integrate Equations of Motion
        for (auto& body : bodies) {
            body.integrate(dt);
        }
    }

private:
    void resolveCollision(RigidBody& a, RigidBody& b) {
        Vec2 relativePos = b.position - a.position;
        float distance = relativePos.length();
        float minDistance = a.radius + b.radius;

        if (distance >= minDistance) return; // No collision

        // Collision normal pointing from A to B
        Vec2 normal = (distance == 0.0f) ? Vec2{1.0f, 0.0f} : relativePos / distance;
        float penetration = minDistance - distance;

        // Relative velocity along collision normal
        Vec2 relativeVel = b.velocity - a.velocity;
        float velAlongNormal = dot(relativeVel, normal);

        // Do not resolve if velocities are already separating
        if (velAlongNormal > 0) return;

        // Calculate Impulse Scalar
        float e = std::min(a.restitution, b.restitution);
        float impulseScalar = -(1.0f + e) * velAlongNormal;
        impulseScalar /= (a.invMass + b.invMass);

        // Apply Impulse (equal and opposite reactions)
        Vec2 impulse = normal * impulseScalar;
        a.velocity = a.velocity - impulse * a.invMass;
        b.velocity = b.velocity + impulse * b.invMass;

        // Positional correction to prevent intersecting textures ("sinking" effect)
        const float percent = 0.4f; // penetration percentage to resolve
        const float slop = 0.01f;   // penetration allowance
        Vec2 correction = normal * (std::max(penetration - slop, 0.0f) / (a.invMass + b.invMass) * percent);
        a.position = a.position - correction * a.invMass;
        b.position = b.position + correction * b.invMass;
    }

    void handleWallCollisions(RigidBody& body) {
        // Floor constraint
        if (body.position.y + body.radius > height - 1) {
            body.position.y = height - 1 - body.radius;
            body.velocity.y = -body.velocity.y * body.restitution;
            body.velocity.x *= 0.95f; // Apply basic friction on the ground
        }
        // Ceiling constraint
        if (body.position.y - body.radius < 1) {
            body.position.y = 1 + body.radius;
            body.velocity.y = -body.velocity.y * body.restitution;
        }
        // Right wall constraint
        if (body.position.x + body.radius > width - 1) {
            body.position.x = width - 1 - body.radius;
            body.velocity.x = -body.velocity.x * body.restitution;
        }
        // Left wall constraint
        if (body.position.x - body.radius < 1) {
            body.position.x = 1 + body.radius;
            body.velocity.x = -body.velocity.x * body.restitution;
        }
    }
};

// ASCII Terminal Renderer
void render(const PhysicsWorld& world, int width, int height) {
    // Clear console using ANSI Escape Code (flicker-free standard console draw)
    std::cout << "\033[H";

    std::vector<std::string> screen(height, std::string(width, ' '));

    // Draw Box Boundaries
    for (int x = 0; x < width; ++x) {
        screen[0][x] = '#';
        screen[height - 1][x] = '#';
    }
    for (int y = 0; y < height; ++y) {
        screen[y][0] = '#';
        screen[y][width - 1] = '#';
    }

    // Draw Rigid Bodies (rendered as '@' or 'O')
    for (const auto& body : world.bodies) {
        int px = static_cast<int>(std::round(body.position.x));
        int py = static_cast<int>(std::round(body.position.y));

        if (px > 0 && px < width - 1 && py > 0 && py < height - 1) {
            screen[py][px] = '@';
        }
    }

    // Display visual output buffer
    std::string output = "";
    for (const auto& line : screen) {
        output += line + "\n";
    }
    std::cout << output << std::flush;
}

int main() {
    const int screenWidth = 80;
    const int screenHeight = 24;

    PhysicsWorld world(screenWidth, screenHeight);

    // Initialize rigid bodies: Position, Velocity, Mass, Radius, Restitution
    world.bodies.push_back(RigidBody({10.0f, 5.0f},  {15.0f, 0.0f},  2.0f, 1.0f, 0.8f));
    world.bodies.push_back(RigidBody({70.0f, 4.0f},  {-12.0f, 5.0f}, 3.0f, 1.2f, 0.7f));
    world.bodies.push_back(RigidBody({40.0f, 12.0f}, {5.0f, -8.0f},  1.5f, 0.8f, 0.9f));
    world.bodies.push_back(RigidBody({25.0f, 3.0f},  {-5.0f, 12.0f}, 4.0f, 1.5f, 0.6f));

    // TIMING AND FRAME-RATE CONSTRAINTS
    using Clock = std::chrono::high_resolution_clock;

    const double targetFPS = 60.0;
    const double targetFrameTime = 1.0 / targetFPS; // ~16.67ms
    const double dt = 0.01; // Fixed delta time for physics integration step (10ms)

    auto previousTime = Clock::now();
    double accumulator = 0.0;

    // Clear terminal screen once on start
    std::cout << "\033[2J";

    while (true) {
        auto currentTime = Clock::now();
        double elapsedTime = std::chrono::duration<double>(currentTime - previousTime).count();
        previousTime = currentTime;

        // Prevent "Spiral of Death" if system lags severely
        if (elapsedTime > 0.25) {
            elapsedTime = 0.25;
        }

        accumulator += elapsedTime;

        // Run as many physics steps as required to match elapsed time
        while (accumulator >= dt) {
            world.step(dt);
            accumulator -= dt;
        }

        // Render visual frame
        render(world, screenWidth, screenHeight);

        // Enforce maximum frame rate (Framerate Constraint)
        auto frameEndTime = Clock::now();
        double computeTime = std::chrono::duration<double>(frameEndTime - currentTime).count();

        if (computeTime < targetFrameTime) {
            // Precise sleep to yield CPU core until the next frame timing window
            auto sleepDuration = std::chrono::duration<double>(targetFrameTime - computeTime);
            std::this_thread::sleep_for(std::chrono::duration_cast<std::chrono::milliseconds>(sleepDuration));
        }
    }

    return 0;
}
