#include <iostream>
#include <vector>
#include <chrono>
#include <cmath>
#include <thread>
#include <algorithm>
#include <string>

// Simple 2D Vector Structure
struct Vec2 {
    double x, y;

    Vec2() : x(0), y(0) {}
    Vec2(double x, double y) : x(x), y(y) {}

    Vec2 operator+(const Vec2& v) const { return Vec2(x + v.x, y + v.y); }
    Vec2 operator-(const Vec2& v) const { return Vec2(x - v.x, y - v.y); }
    Vec2 operator*(double scalar) const { return Vec2(x * scalar, y * scalar); }
    Vec2 operator/(double scalar) const { return Vec2(x / scalar, y / scalar); }

    Vec2& operator+=(const Vec2& v) { x += v.x; y += v.y; return *this; }
    Vec2& operator-=(const Vec2& v) { x -= v.x; y -= v.y; return *this; }

    double lengthSq() const { return x * x + y * y; }
    double length() const { return std::sqrt(lengthSq()); }

    Vec2 normalized() const {
        double len = length();
        return len > 0.0001 ? Vec2(x / len, y / len) : Vec2(0, 0);
    }

    double dot(const Vec2& v) const { return x * v.x + y * v.y; }
};

// Rigid Body Representation
struct RigidBody {
    int id;
    Vec2 position;
    Vec2 velocity;
    Vec2 force;

    double mass;
    double invMass; // Cached for performance (division is slow)
    double radius;
    double restitution; // Bounciness (0.0 = clay, 1.0 = perfect elastic)

    RigidBody(int id, Vec2 pos, double r, double m, double rest)
        : id(id), position(pos), velocity(0, 0), force(0, 0), radius(r), restitution(rest) {
        mass = m;
        invMass = (m > 0.0) ? 1.0 / m : 0.0; // static object has 0 mass -> infinite mass -> invMass = 0
    }

    void applyForce(const Vec2& f) {
        force += f;
    }

    void integrate(double dt) {
        if (invMass == 0.0) return; // Static object

        // Semi-implicit Euler integration (more stable than Explicit Euler)
        velocity += (force * invMass) * dt;
        position += velocity * dt;

        // Clear forces for next step
        force = Vec2(0, 0);
    }
};

// Simple Engine to manage Physics Simulation and Frame Timing
class PhysicsEngine {
private:
    std::vector<RigidBody> bodies;
    Vec2 gravity;

    // World bounds
    double width, height;

public:
    PhysicsEngine(double w, double h) : gravity(0.0, 9.81), width(w), height(h) {}

    void addBody(const RigidBody& body) {
        bodies.push_back(body);
    }

    // Fixed timestep execution
    void step(double dt) {
        // 1. Apply Gravity
        for (auto& body : bodies) {
            if (body.invMass > 0.0) {
                body.applyForce(gravity * body.mass);
            }
        }

        // 2. Integrate Forces (predict motion)
        for (auto& body : bodies) {
            body.integrate(dt);
        }

        // 3. Detect and Resolve Collisions
        resolveCollisions();
    }

    const std::vector<RigidBody>& getBodies() const { return bodies; }
    double getWidth() const { return width; }
    double getHeight() const { return height; }

private:
    void resolveCollisions() {
        size_t size = bodies.size();

        // Object-to-Object Collisions
        for (size_t i = 0; i < size; ++i) {
            for (size_t j = i + 1; j < size; ++j) {
                RigidBody& A = bodies[i];
                RigidBody& B = bodies[j];

                if (A.invMass == 0.0 && B.invMass == 0.0) continue;

                // Distance vector between centers
                Vec2 normal = B.position - A.position;
                double distSq = normal.lengthSq();
                double radiusSum = A.radius + B.radius;

                if (distSq < radiusSum * radiusSum) {
                    double dist = std::sqrt(distSq);

                    // Prevent division by zero if objects are perfectly overlapping
                    normal = (dist != 0.0) ? normal / dist : Vec2(0, -1); 

                    // Relative velocity along the normal
                    Vec2 relativeVel = B.velocity - A.velocity;
                    double velAlongNormal = relativeVel.dot(normal);

                    // Do not resolve if velocities are separating
                    if (velAlongNormal < 0) {
                        // Calculate restitution
                        double e = std::min(A.restitution, B.restitution);

                        // Calculate impulse scalar
                        double impulseScalar = -(1.0 + e) * velAlongNormal;
                        impulseScalar /= (A.invMass + B.invMass);

                        // Apply impulse
                        Vec2 impulse = normal * impulseScalar;
                        A.velocity -= impulse * A.invMass;
                        B.velocity += impulse * B.invMass;

                        // Positional correction (prevents sinking/sticking due to floating point errors)
                        const double percent = 0.2; // penetration percentage to correct
                        const double slop = 0.01;   // penetration allowance
                        double penetration = radiusSum - dist;
                        Vec2 correction = normal * (std::max(penetration - slop, 0.0) / (A.invMass + B.invMass) * percent);
                        A.position -= correction * A.invMass;
                        B.position += correction * B.invMass;
                    }
                }
            }
        }

        // Object-to-Wall Collisions (World Boundaries)
        for (auto& A : bodies) {
            if (A.invMass == 0.0) continue;

            // X-axis collision (Left wall & Right wall)
            if (A.position.x - A.radius < 0.0) {
                A.position.x = A.radius;
                A.velocity.x = -A.velocity.x * A.restitution;
            } else if (A.position.x + A.radius > width) {
                A.position.x = width - A.radius;
                A.velocity.x = -A.velocity.x * A.restitution;
            }

            // Y-axis collision (Ceiling & Floor)
            if (A.position.y - A.radius < 0.0) {
                A.position.y = A.radius;
                A.velocity.y = -A.velocity.y * A.restitution;
            } else if (A.position.y + A.radius > height) {
                A.position.y = height - A.radius;
                A.velocity.y = -A.velocity.y * A.restitution;
                // Simple friction simulation on ground contact
                A.velocity.x *= 0.98; 
            }
        }
    }
};

// ASCII Renderer Class for Console Visuals
class ConsoleRenderer {
private:
    int cols, rows;
    std::string buffer;

public:
    ConsoleRenderer(int width, int height) : cols(width), rows(height) {
        // Hide console cursor
        std::cout << "\033[?25l";
    }

    ~ConsoleRenderer() {
        // Show console cursor again on exit
        std::cout << "\033[?25h";
    }

    void drawFrame(const PhysicsEngine& engine, double frameTime, double actualFps) {
        // Clear back-buffer string representation
        buffer.clear();
        std::vector<std::vector<char>> grid(rows, std::vector<char>(cols, ' '));

        // Draw boundaries
        for (int i = 0; i < cols; ++i) { grid[0][i] = '#'; grid[rows - 1][i] = '#'; }
        for (int i = 0; i < rows; ++i) { grid[i][0] = '#'; grid[i][cols - 1] = '#'; }

        // Rasterize circular bodies
        double worldWidth = engine.getWidth();
        double worldHeight = engine.getHeight();

        for (const auto& body : engine.getBodies()) {
            // Map physics coordinates to characters
            int cx = static_cast<int>((body.position.x / worldWidth) * (cols - 2)) + 1;
            int cy = static_cast<int>((body.position.y / worldHeight) * (rows - 2)) + 1;
            int r_char = static_cast<int>((body.radius / worldWidth) * cols);

            // Simple midpoint/box circle plotting
            for (int dy = -r_char; dy <= r_char; ++dy) {
                for (int dx = -r_char * 2; dx <= r_char * 2; ++dx) { // Console characters are taller than wide
                    int py = cy + dy;
                    int px = cx + dx;
                    if (py > 0 && py < rows - 1 && px > 0 && px < cols - 1) {
                        double normalized_dx = dx / 2.0;
                        if (normalized_dx * normalized_dx + dy * dy <= r_char * r_char) {
                            grid[py][px] = (body.invMass == 0.0) ? 'X' : ('0' + (body.id % 10));
                        }
                    }
                }
            }
        }

        // Write frame to the continuous string
        for (int y = 0; y < rows; ++y) {
            for (int x = 0; x < cols; ++x) {
                buffer += grid[y][x];
            }
            buffer += '\n';
        }

        // Move console cursor to (0,0) and output the screen buffer (eliminates flicker)
        std::cout << "\033[H";
        std::cout << buffer;
        std::cout << "--- REALTIME RIGID BODY PHYSICS ENGINE ---\n";
        std::cout << "Target Physics Update: 60Hz (dt = 16.67ms)\n";
        std::cout << "Render Frame Time    : " << (frameTime * 1000.0) << " ms\n";
        std::cout << "Effective Framerate  : " << actualFps << " FPS\n";
        std::cout << "Controls             : Press Ctrl+C to terminate.\n";
    }
};

