    engine.addBody(RigidBody(1, Vec2(3.0, 3.0), 1.2, 10.0, 0.7)); // Big bouncier ball
    engine.addBody(RigidBody(2, Vec2(10.0, 2.0), 0.8, 5.0, 0.4));  // Medium heavy ball
    engine.addBody(RigidBody(3, Vec2(15.0, 3.0), 0.6, 2.0, 0.9));  // Small, extremely bouncy ball
    engine.addBody(RigidBody(4, Vec2(6.0, 1.0), 0.7, 4.0, 0.5));

    // Add a static ground divider block (infinite mass/invMass = 0.0)
    engine.addBody(RigidBody(5, Vec2(10.0, 7.5), 2.2, 0.0, 0.1));

    // Initialize renderer (60 chars wide, 20 chars tall)
    ConsoleRenderer renderer(70, 20);

    // Setup Time Constraints
    const double dt = 1.0 / 60.0; // Strict fixed 60Hz physics timestep (0.016667 seconds)
    double accumulator = 0.0;

    auto clock = std::chrono::high_resolution_clock::now();
    bool running = true;

    while (running) {
        auto newClock = std::chrono::high_resolution_clock::now();
        double frameTime = std::chrono::duration<double>(newClock - clock).count();
        clock = newClock;

        // "Spiral of death" prevention: clamp maximum frame step to evaluate
        if (frameTime > 0.25) {
            frameTime = 0.25;
        }

        accumulator += frameTime;

        // Update physics loop using constant fixed time steps (maintains determinism & stability)
        while (accumulator >= dt) {
            engine.step(dt);
            accumulator -= dt;
        }

        // Render to Screen (Decoupled from physics rate)
        double fps = 1.0 / frameTime;
        renderer.drawFrame(engine, frameTime, fps);

        // Sleep briefly to yield CPU execution (Frame-rate constraint / Eco mode)
        // Helps avoid pinned thread usage when rendering frames exceeds display frequency.
        std::this_thread::sleep_for(std::chrono::milliseconds(8));
    }

    return 0;
}
