const Vec2 GRAVITY{0.0f, -9.81f};
const float WORLD_WIDTH = 40.0f;
const float WORLD_HEIGHT = 20.0f;

// Collide and resolve circles
void ResolveCollision(RigidBody& a, RigidBody& b) {
    Vec2 normal = b.position - a.position;
    float distSq = normal.lengthSq();
    float radiusSum = a.radius + b.radius;

    // Check if circles overlap
    if (distSq >= radiusSum * radiusSum) return;

    float dist = std::sqrt(distSq);
    if (dist == 0.0f) return; // Prevent division by zero

    normal = normal / dist; // Normalize

    // 1. Resolve Penetration (Positional Correction to stop "sinking")
    float penetration = radiusSum - dist;
    const float percent = 0.4f; // Penetration percentage to correct per frame
    const float slop = 0.01f;     // Penetration allowance
    Vec2 correction = normal * (std::max(penetration - slop, 0.0f) / (a.invMass + b.invMass) * percent);

    a.position -= correction * a.invMass;
    b.position += correction * b.invMass;

    // 2. Resolve Velocities (Impulse Resolution)
    Vec2 relativeVel = b.velocity - a.velocity;
    float velAlongNormal = Vec2::dot(relativeVel, normal);

    // Do not resolve if objects are already moving apart
    if (velAlongNormal > 0) return;

    // Calculate restitution (bounciness)
    float e = std::min(a.restitution, b.restitution);

    // Calculate impulse scalar
    float impulseScalar = -(1.0f + e) * velAlongNormal;
    impulseScalar /= (a.invMass + b.invMass);

    // Apply impulse
    Vec2 impulse = normal * impulseScalar;
    a.velocity -= impulse * a.invMass;
    b.velocity += impulse * b.invMass;
}

// Check and resolve boundary collisions (Walls)
void ResolveWallCollisions(RigidBody& body) {
    // Floor
    if (body.position.y - body.radius < 0.0f) {
        body.position.y = body.radius;
        body.velocity.y = -body.velocity.y * body.restitution;
    }
    // Ceiling
    if (body.position.y + body.radius > WORLD_HEIGHT) {
        body.position.y = WORLD_HEIGHT - body.radius;
        body.velocity.y = -body.velocity.y * body.restitution;
    }
    // Left Wall
    if (body.position.x - body.radius < 0.0f) {
        body.position.x = body.radius;
        body.velocity.x = -body.velocity.x * body.restitution;
    }
    // Right Wall
    if (body.position.x + body.radius > WORLD_WIDTH) {
        body.position.x = WORLD_WIDTH - body.radius;
        body.velocity.x = -body.velocity.x * body.restitution;
    }
}

// Single step integration (Semi-Implicit Euler)
void Integrate(RigidBody& body, float dt) {
    if (body.invMass == 0.0f) return; // Static object

    body.velocity += GRAVITY * dt;
    body.position += body.velocity * dt;
}

// Simple ASCII Renderer
void Render(const std::vector<RigidBody>& bodies) {
    const int screenWidth = 60;
    const int screenHeight = 22;
    std::vector<std::string> buffer(screenHeight, std::string(screenWidth, ' '));

    // Draw horizontal borders
    buffer[0] = std::string(screenWidth, '#');
    buffer[screenHeight - 1] = std::string(screenWidth, '#');

    // Draw vertical borders
    for (int y = 1; y < screenHeight - 1; ++y) {
        buffer[y][0] = '#';
        buffer[y][screenWidth - 1] = '#';
    }

    // Draw bodies
    for (const auto& body : bodies) {
        // Map world space to screen space
        int screenX = static_cast<int>((body.position.x / WORLD_WIDTH) * (screenWidth - 2)) + 1;
        // Invert Y-axis since terminal prints top-to-bottom, physics is bottom-to-top
        int screenY = (screenHeight - 2) - static_cast<int>((body.position.y / WORLD_HEIGHT) * (screenHeight - 2));

        if (screenX > 0 && screenX < screenWidth - 1 && screenY > 0 && screenY < screenHeight - 1) {
            buffer[screenY][screenX] = body.symbol;
        }
    }

    // Clear console using ANSI Escape Code (Fast and cross-platform)
    std::cout << "\033[H";
    for (const auto& line : buffer) {
        std::cout << line << "\n";
    }
    std::cout << std::flush;
}

int main() {
    // Setup initial rigid bodies
    std::vector<RigidBody> bodies;

    // Position, Velocity, Mass, Radius, Restitution, Symbol
    bodies.push_back(RigidBody({5.0f,  18.0f}, {15.0f, 0.0f},  1.0f, 1.0f, 0.8f, 'O'));
    bodies.push_back(RigidBody({35.0f, 15.0f}, {-10.0f, 0.0f}, 1.5f, 1.2f, 0.7f, '@'));
    bodies.push_back(RigidBody({20.0f, 5.0f},  {0.0f, 10.0f},  2.0f, 1.4f, 0.6f, 'X'));

    // Real-Time Frame-Rate Constraint Variables
    const double dt = 1.0 / 120.0; // Fixed physics step: 120Hz (8.33 ms)
    double accumulator = 0.0;

    auto currentTime = std::chrono::high_resolution_clock::now();
    bool running = true;

    // Clear console once at startup
    std::cout << "\033[2J";

    while (running) {
        auto newTime = std::chrono::high_resolution_clock::now();
        double frameTime = std::chrono::duration<double>(newTime - currentTime).count();
        currentTime = newTime;

        // Prevent "spiral of death" (if rendering slows down enormously)
        if (frameTime > 0.1) {
            frameTime = 0.1;
        }

        accumulator += frameTime;

        // --- FIXED TIMESTEP STEPPER ---
        // Runs as many physics steps as required to catch up with actual passed real-time
        while (accumulator >= dt) {
            // 1. Apply Integrator
            for (auto& body : bodies) {
                Integrate(body, static_cast<float>(dt));
            }

            // 2. Handle Object-to-Object Collisions
            for (size_t i = 0; i < bodies.size(); ++i) {
                for (size_t j = i + 1; j < bodies.size(); ++j) {
                    ResolveCollision(bodies[i], bodies[j]);
                }
            }

            // 3. Handle Object-to-Boundary Collisions
            for (auto& body : bodies) {
                ResolveWallCollisions(body);
            }

            accumulator -= dt;
        }

        // --- RENDERING ---
        Render(bodies);

        // Frame-rate limiting (to spare CPU cycles)
        // Aims for ~60 FPS draw cycles, even though physics ticks at 120 FPS
        auto frameEnd = std::chrono::high_resolution_clock::now();
        double actualFrameDuration = std::chrono::duration<double>(frameEnd - newTime).count();
        const double targetFrameDuration = 1.0 / 60.0; // 60 FPS target render rate

        if (actualFrameDuration < targetFrameDuration) {
            std::this_thread::sleep_for(std::chrono::duration<double>(targetFrameDuration - actualFrameDuration));
        }
    }

    return 0;
}
