#include <iostream>
#include <vector>
#include <chrono>
#include <thread>
#include <cmath>
#include <algorithm>

// Simple 2D Vector Class
struct Vec2 {
    float x = 0.0f;
    float y = 0.0f;

    Vec2 operator+(const Vec2& v) const { return {x + v.x, y + v.y}; }
    Vec2 operator-(const Vec2& v) const { return {x - v.x, y - v.y}; }
    Vec2 operator*(float scalar) const { return {x * scalar, y * scalar}; }
    Vec2 operator/(float scalar) const { return {x / scalar, y / scalar}; }

    Vec2& operator+=(const Vec2& v) { x += v.x; y += v.y; return *this; }
    Vec2& operator-=(const Vec2& v) { x -= v.x; y -= v.y; return *this; }

    float LengthSquared() const { return x * x + y * y; }
    float Length() const { return std::sqrt(LengthSquared()); }

    float Dot(const Vec2& v) const { return x * v.x + y * v.y; }
};

// Rigid Body definition
struct RigidBody {
    Vec2 position;
    Vec2 velocity;
    float mass;
    float invMass;
    float radius;
    float restitution; // Bounciness coefficient: [0 = no bounce, 1 = perfect elastic bounce]
    char symbol;       // Character for ASCII rendering

    RigidBody(Vec2 pos, Vec2 vel, float m, float r, float rest, char sym)
        : position(pos), velocity(vel), mass(m), radius(r), restitution(rest), symbol(sym) {
        invMass = (m > 0.0f) ? 1.0f / m : 0.0f; // Static bodies have 0 inverse mass
    }
};

// The Physics World Class
class PhysicsWorld {
private:
    std::vector<RigidBody> bodies;
    Vec2 gravity{0.0f, -9.81f}; // Standard Earth Gravity in m/s^2
    float width;
    float height;

public:
    PhysicsWorld(float w, float h) : width(w), height(h) {}

    void AddBody(const RigidBody& body) {
        bodies.push_back(body);
    }

    const std::vector<RigidBody>& GetBodies() const { return bodies; }

    // Resolve Collisions between Rigid Bodies (Circle vs Circle)
    void ResolveCollisions() {
        for (size_t i = 0; i < bodies.size(); ++i) {
            for (size_t j = i + 1; j < bodies.size(); ++j) {
                RigidBody& A = bodies[i];
                RigidBody& B = bodies[j];

                Vec2 normal = B.position - A.position;
                float distSq = normal.LengthSquared();
                float radiusSum = A.radius + B.radius;

                // Check if circles overlap
                if (distSq >= radiusSum * radiusSum) continue; 

                float dist = std::sqrt(distSq);
                if (dist == 0.0f) continue; // Prevent division by zero

                normal = normal / dist; // Normalize vector

                // Relative velocity along the collision normal
                Vec2 rv = B.velocity - A.velocity;
                float velAlongNormal = rv.Dot(normal);

                // Do not resolve if objects are already moving apart
                if (velAlongNormal > 0) continue;

                // Calculate restitution (bounciness)
                float e = std::min(A.restitution, B.restitution);

                // Calculate Impulse Scalar (Newtonian restitution equation)
                float jImpulse = -(1 + e) * velAlongNormal;
                jImpulse /= (A.invMass + B.invMass);

                // Apply impulse vector to each body
                Vec2 impulseVec = normal * jImpulse;
                A.velocity -= impulseVec * A.invMass;
                B.velocity += impulseVec * B.invMass;

                // Positional correction to prevent "sinking/overlap" (Sinking correction factor)
                const float percent = 0.2f; // Penetration percentage to correct per frame
                const float slop = 0.01f;    // Penetration allowance
                float penetration = radiusSum - dist;
                Vec2 correction = normal * (std::max(penetration - slop, 0.0f) / (A.invMass + B.invMass)) * percent;

                A.position -= correction * A.invMass;
                B.position += correction * B.invMass;
            }
        }
    }

    // Resolve Collisions against World Boundaries (Walls and Floor)
    void ResolveBoundaryCollisions() {
        for (auto& body : bodies) {
            float e = body.restitution;

            // Floor Collision (y = 0)
            if (body.position.y - body.radius < 0.0f) {
                body.position.y = body.radius;
                if (body.velocity.y < 0.0f) body.velocity.y = -body.velocity.y * e;
            }
            // Ceiling Collision (y = Height)
            if (body.position.y + body.radius > height) {
                body.position.y = height - body.radius;
                if (body.velocity.y > 0.0f) body.velocity.y = -body.velocity.y * e;
            }
            // Left Wall Collision (x = 0)
            if (body.position.x - body.radius < 0.0f) {
                body.position.x = body.radius;
                if (body.velocity.x < 0.0f) body.velocity.x = -body.velocity.x * e;
            }
            // Right Wall Collision (x = Width)
            if (body.position.x + body.radius > width) {
                body.position.x = width - body.radius;
                if (body.velocity.x > 0.0f) body.velocity.x = -body.velocity.x * e;
            }
        }
    }

    // Integrate forces, velocities and resolve collisions
    void Step(float dt) {
        // 1. Apply gravity & integrate velocities/positions (Symplectic Euler)
        for (auto& body : bodies) {
            if (body.invMass == 0.0f) continue; // Skip static objects

            body.velocity += gravity * dt;
            body.position += body.velocity * dt;
        }

        // 2. Resolve Collisions
        ResolveCollisions();
        ResolveBoundaryCollisions();
    }
};

