        for (const auto& body : world.GetBodies()) {
            // Normalize coordinate system [0, 1]
            float normX = body.position.x / simWidth;
            float normY = body.position.y / simHeight;

            // Map to Screen indexes (Y index is inverted because terminal prints top to bottom)
            int termX = static_cast<int>(normX * (screenWidth - 2)) + 1;
