            // Clamp positions to protect screen boundaries
            termX = std::max(1, std::min(screenWidth - 2, termX));
            termY = std::max(1, std::min(screenHeight - 2, termY));

            buffer[termY][termX] = body.symbol;
        }

        // Render buffer to stdout
        for (const auto& line : buffer) {
            std::cout << line << "\n";
        }
    }
};

