    world.AddBody(RigidBody({30.0f, 15.0f}, {-12.0f, -5.0f}, 5.0f,  1.0f, 0.6f, 'O')); // Lighter ball
    world.AddBody(RigidBody({20.0f, 5.0f},  {0.0f, 0.0f},    0.0f,  2.0f, 0.5f, 'X')); // Static Heavy Obstacle (Mass=0)

    // 3. Setup Renderer (Terminal size: 80 columns wide, 24 rows high)
    TerminalRenderer renderer(80, 24, worldWidth, worldHeight);

    // 4. Real-time Fixed Timestep Physics Loop (60Hz Physics Step)
    const double dt = 1.0 / 60.0; // Fixed timestep (16.67ms)
    double accumulator = 0.0;

    auto lastTime = std::chrono::high_resolution_clock::now();
    bool running = true;

    std::cout << "Simulation running. Press Ctrl+C to exit.\n";
    std::this_thread::sleep_for(std::chrono::seconds(1));

    while (running) {
        auto currentTime = std::chrono::high_resolution_clock::now();
        double frameTime = std::chrono::duration<double>(currentTime - lastTime).count();
        lastTime = currentTime;

        // Prevent "Spiral of Death" (cap excessive frame lag)
        if (frameTime > 0.1) {
            frameTime = 0.1;
        }

        accumulator += frameTime;

        // Step through physics at a constant, deterministic rate (dt)
        while (accumulator >= dt) {
