```cpp
#include <iostream>
#include <vector>
#include <chrono>
#include <thread>
#include <cmath>
#include <algorithm>

// --- MATH UTILITIES ---
struct Vec2 {
    float x = 0.0f;
    float y = 0.0f;

    Vec2 operator+(const Vec2& v) const { return {x + v.x, y + v.y}; }
    Vec2 operator-(const Vec2& v) const { return {x - v.x, y - v.y}; }
    Vec2 operator*(float s) const { return {x * s, y * s}; }
    Vec2& operator+=(const Vec2& v) { x += v.x; y += v.y; return *this; }
    Vec2& operator-=(const Vec2& v) { x -= v.x; y -= v.y; return *this; }

    float LengthSq() const { return x * x + y * y; }
    float Length() const { return std::sqrt(LengthSq()); }

    Vec2 Normalize() const {
        float len = Length();
        return len > 0.0f ? Vec2{x / len, y / len} : Vec2{0.0f, 0.0f};
    }

    static float Dot(const Vec2& a, const Vec2& b) {
        return a.x * b.x + a.y * b.y;
    }
};

// --- RIGID BODY REPRESENTATION ---
struct RigidBody {
    Vec2 position;
    Vec2 velocity;
    Vec2 force;

    float mass;
    float invMass;    // 0 for static/infinite mass objects
    float radius;     // Circular bounding volume
    float restitution;// Bounciness (0.0 = clay, 1.0 = perfect bounce)

    RigidBody(Vec2 pos, float r, float m, float rest)
        : position(pos), velocity({0, 0}), force({0, 0}), radius(r), restitution(rest) {
        mass = m;
        invMass = (m > 0.0f) ? 1.0f / m : 0.0f;
    }

    void ApplyForce(const Vec2& f) {
        if (invMass == 0.0f) return; // Static bodies don't move
        force += f;
    }
};

// --- COLLISION RESOLUTION ---
struct Manifold {
    RigidBody* bodyA;
    RigidBody* bodyB;
    Vec2 normal;
    float penetration;
};

// Detects collision between two circular rigid bodies
bool DetectCollision(RigidBody& a, RigidBody& b, Manifold& outManifold) {
    Vec2 relativePos = b.position - a.position;
    float distSq = relativePos.LengthSq();
    float radiusSum = a.radius + b.radius;

    if (distSq >= radiusSum * radiusSum) {
        return false; // No collision
    }

    float dist = std::sqrt(distSq);
    outManifold.bodyA = &a;
    outManifold.bodyB = &b;

    if (dist != 0.0f) {
        outManifold.penetration = radiusSum - dist;
        outManifold.normal = relativePos * (1.0f / dist); // Normalized
    } else {
        // Bodies are perfectly overlapping
        outManifold.penetration = a.radius;
        outManifold.normal = Vec2{1.0f, 0.0f};
    }
    return true;
}

// Resolves collision using impulse dynamics and positional correction
void ResolveCollision(Manifold& m) {
    RigidBody* a = m.bodyA;
    RigidBody* b = m.bodyB;

    // 1. Calculate relative velocity in normal direction
    Vec2 relativeVel = b->velocity - a->velocity;
    float velAlongNormal = Vec2::Dot(relativeVel, m.normal);

    // Do not resolve if velocities are separating
    if (velAlongNormal > 0) return;

    // 2. Calculate impulse scalar (restitution)
    float e = std::min(a->restitution, b->restitution);
    float j = -(1.0f + e) * velAlongNormal;
    j /= (a->invMass + b->invMass);

    // 3. Apply impulse
    Vec2 impulse = m.normal * j;
    a->velocity -= impulse * a->invMass;
    b->velocity += impulse * b->invMass;

    // 4. Positional correction (prevents sinking/clipping due to numerical drift)
    const float percent = 0.4f; // Penetration percentage to resolve per frame
    const float slop = 0.01f;    // Penetration allowance
    Vec2 correction = m.normal * (std::max(m.penetration - slop, 0.0f) / (a->invMass + b->invMass) * percent);
    a->position -= correction * a->invMass;
    b->position += correction * b->invMass;
}

// --- PHYSICS WORLD ---
class PhysicsWorld {
public:
    std::vector<RigidBody> bodies;
    Vec2 gravity = {0.0f, 9.81f}; // Standard downward gravity

    void Step(float dt) {
        // Phase 1: Integrate Forces (Semi-Implicit Euler)
        for (auto& body : bodies) {
            if (body.invMass == 0.0f) continue;

            body.ApplyForce(gravity * body.mass); // Apply gravity
            body.velocity += body.force * body.invMass * dt;
            body.position += body.velocity * dt;
            body.force = {0.0f, 0.0f}; // Reset forces
        }

        // Phase 2: Collision Detection and Resolution
        std::vector<Manifold> contacts;
        for (size_t i = 0; i < bodies.size(); ++i) {
            for (size_t j = i + 1; j < bodies.size(); ++j) {
                Manifold m;
                if (DetectCollision(bodies[i], bodies[j], m)) {
                    contacts.push_back(m);
                }
            }
        }

        // Phase 3: Solve Contacts
        for (auto& contact : contacts) {
            ResolveCollision(contact);
        }
    }
};

// --- REAL-TIME LOOP & TERMINAL RENDERER ---
const int SCREEN_WIDTH = 40;
const int SCREEN_HEIGHT = 20;

void Render(const PhysicsWorld& world) {
    // Clear console screen buffer
    std::cout << "\x1B[2J\x1B[H";

    // Initialize blank screen buffer
    char screen[SCREEN_HEIGHT][SCREEN_WIDTH];
    for (int y = 0; y < SCREEN_HEIGHT; ++y) {
