// --- MATH UTILITIES ---
struct Vec2 {
    float x, y;
    Vec2 operator+(const Vec2& v) const { return {x + v.x, y + v.y}; }
    Vec2 operator-(const Vec2& v) const { return {x - v.x, y - v.y}; }
    Vec2 operator*(float scalar) const { return {x * scalar, y * scalar}; }
    Vec2& operator+=(const Vec2& v) { x += v.x; y += v.y; return *this; }
    Vec2& operator-=(const Vec2& v) { x -= v.x; y -= v.y; return *this; }

    float Length() const { return std::sqrt(x * x + y * y); }
    Vec2 Normalized() const {
        float len = Length();
        return len > 0.0f ? Vec2{x / len, y / len} : Vec2{0.0f, 0.0f};
    }
    static float Dot(const Vec2& a, const Vec2& b) {
        return a.x * b.x + a.y * b.y;
    }
};

// --- RIGID BODY REPRESENTATION ---
struct RigidBody {
    int id;
    Vec2 position;
    Vec2 velocity;
    Vec2 force;

    float mass;
    float invMass; // Cached for performance (division is slow)
    float radius;
    float restitution; // Bounciness (0.0 = clay, 1.0 = perfect bounce)

    RigidBody(int id, Vec2 pos, Vec2 vel, float m, float rad, float rest)
        : id(id), position(pos), velocity(vel), force({0, 0}), mass(m), radius(rad), restitution(rest) {
        invMass = (m > 0.0f) ? 1.0f / m : 0.0f; // Infinite mass represented by 0
    }

    void ApplyForce(const Vec2& f) {
        if (invMass == 0.0f) return;
        force += f;
    }

    void Integrate(float dt) {
        if (invMass == 0.0f) return;
        // Semi-implicit Euler Integration (symplectic)
        velocity += (force * invMass) * dt;
        position += velocity * dt;
        force = {0.0f, 0.0f}; // Reset forces for next frame
    }
};

// --- PHYSICS ENGINE WORLD ---
class PhysicsWorld {
public:
    std::vector<RigidBody> bodies;
    Vec2 gravity = {0.0f, -9.81f}; // Gravity pulling downward

    // Boundary constraints (A box)
    float width = 40.0f;
    float height = 20.0f;

    void AddBody(const RigidBody& body) {
        bodies.push_back(body);
    }

    void Step(float dt) {
        // 1. Apply Global Forces
        for (auto& body : bodies) {
            body.ApplyForce(gravity * body.mass);
        }

        // 2. Integrate Forces into Velocities and Positions
        for (auto& body : bodies) {
            body.Integrate(dt);
        }

        // 3. Detect and Resolve Collisions
        ResolveCollisions();
    }

private:
    void ResolveCollisions() {
        // Pairwise Rigid Body Collisions
        for (size_t i = 0; i < bodies.size(); ++i) {
            for (size_t j = i + 1; j < bodies.size(); ++j) {
                RigidBody& A = bodies[i];
                RigidBody& B = bodies[j];

                Vec2 relativePos = B.position - A.position;
                float distance = relativePos.Length();
                float minDistance = A.radius + B.radius;

                if (distance < minDistance) {
                    Vec2 normal = relativePos.Normalized();
                    float penetration = minDistance - distance;

                    // A. Impulse Resolution (Velocities)
                    Vec2 relativeVel = B.velocity - A.velocity;
                    float velAlongNormal = Vec2::Dot(relativeVel, normal);

                    // Do not resolve if velocities are separating
                    if (velAlongNormal < 0) {
                        float e = std::min(A.restitution, B.restitution);
                        float impulseScalar = -(1.0f + e) * velAlongNormal;
                        impulseScalar /= (A.invMass + B.invMass);

                        Vec2 impulse = normal * impulseScalar;
                        A.velocity -= impulse * A.invMass;
                        B.velocity += impulse * B.invMass;
                    }

                    // B. Positional Correction (Sinking prevention)
                    const float percent = 0.4f; // Penetration percentage to correct
                    const float slop = 0.01f;    // Penetration allowance
                    Vec2 correction = normal * (std::max(penetration - slop, 0.0f) / (A.invMass + B.invMass)) * percent;
                    A.position -= correction * A.invMass;
                    B.position += correction * B.invMass;
                }
            }
        }

        // Boundary Collisions (Simple box constraint)
        for (auto& body : bodies) {
            // Floor
            if (body.position.y - body.radius < 0.0f) {
                body.position.y = body.radius;
                body.velocity.y = -body.velocity.y * body.restitution;
            }
            // Ceiling
            if (body.position.y + body.radius > height) {
                body.position.y = height - body.radius;
                body.velocity.y = -body.velocity.y * body.restitution;
            }
            // Left Wall
            if (body.position.x - body.radius < 0.0f) {
                body.position.x = body.radius;
                body.velocity.x = -body.velocity.x * body.restitution;
            }
            // Right Wall
            if (body.position.x + body.radius > width) {
                body.position.x = width - body.radius;
                body.velocity.x = -body.velocity.x * body.restitution;
            }
        }
    }
};

