    float y = 0.0f;

    Vec2() = default;
    Vec2(float x, float y) : x(x), y(y) {}

    Vec2 operator+(const Vec2& o) const { return {x + o.x, y + o.y}; }
    Vec2 operator-(const Vec2& o) const { return {x - o.x, y - o.y}; }
    Vec2 operator*(float scalar) const { return {x * scalar, y * scalar}; }
    Vec2& operator+=(const Vec2& o) { x += o.x; y += o.y; return *this; }
    Vec2& operator-=(const Vec2& o) { x -= o.x; y -= o.y; return *this; }

    float dot(const Vec2& o) const { return x * o.x + y * o.y; }
    float lengthSq() const { return x * x + y * y; }
    float length() const { return std::sqrt(lengthSq()); }

    Vec2 normalized() const {
        float len = length();
        return len > 0.0f ? Vec2(x / len, y / len) : Vec2(0.0f, 0.0f);
    }
};

// Rigid Body Structure (POD designed to be packed into contiguous memory)
struct RigidBody {
    Vec2 position;
    Vec2 velocity;
    Vec2 force;

    float mass = 1.0f;
    float invMass = 1.0f; // Cached 1/mass. Static bodies have mass = 0, invMass = 0.
    float radius = 1.0f;  // Circle collider representation
    float restitution = 0.6f; // Bounciness coefficient [0.0 (clay) to 1.0 (superball)]

    void setMass(float m) {
        mass = m;
        invMass = (m > 0.0f) ? (1.0f / m) : 0.0f;
    }

    void applyForce(const Vec2& f) {
        if (invMass > 0.0f) {
            force += f;
        }
    }
};

// Physics Engine World State
class PhysicsWorld {
private:
    std::vector<RigidBody> bodies;
    Vec2 gravity = {0.0f, -9.81f};

    // Resolves penetration and applies impulse-based response to colliding bodies
    void resolveCollisions() {
        size_t numBodies = bodies.size();

        for (size_t i = 0; i < numBodies; ++i) {
            // Collision with Ground (y = 0)
            RigidBody& b = bodies[i];
            float floorLevel = 0.0f;
            if (b.position.y - b.radius < floorLevel) {
                // Positional correction (prevents sinking into floor)
                float penetration = floorLevel - (b.position.y - b.radius);
                b.position.y += penetration;

                // Bounce impulse response
                if (b.velocity.y < 0.0f) {
                    b.velocity.y = -b.velocity.y * b.restitution;
                }
            }

            // Circle-to-Circle Collision Checks
            for (size_t j = i + 1; j < numBodies; ++j) {
                RigidBody& A = bodies[i];
                RigidBody& B = bodies[j];

                Vec2 relativePos = B.position - A.position;
                float distSq = relativePos.lengthSq();
                float minDist = A.radius + B.radius;

                if (distSq < minDist * minDist) {
                    float dist = std::sqrt(distSq);
                    Vec2 normal = (dist > 0.0f) ? (relativePos * (1.0f / dist)) : Vec2(0.0f, 1.0f);
                    float penetration = minDist - dist;

                    // 1. Positional Correction (Sinking prevention)
                    const float percent = 0.4f; // Penetration percentage to resolve per frame
                    const float slop = 0.01f;    // Penetration allowance
                    Vec2 correction = normal * (std::max(penetration - slop, 0.0f) / (A.invMass + B.invMass) * percent);
                    A.position -= correction * A.invMass;
                    B.position += correction * B.invMass;

                    // 2. Impulse Resolution
                    Vec2 relativeVel = B.velocity - A.velocity;
                    float velAlongNormal = relativeVel.dot(normal);

                    // Do not resolve if velocities are separating
                    if (velAlongNormal < 0) {
                        float e = std::min(A.restitution, B.restitution);
                        float impulseScalar = -(1.0f + e) * velAlongNormal;
                        impulseScalar /= (A.invMass + B.invMass);

                        Vec2 impulse = normal * impulseScalar;
                        A.velocity -= impulse * A.invMass;
                        B.velocity += impulse * B.invMass;
                    }
                }
            }
        }
    }

public:
    // Pre-allocating elements to satisfy memory performance constraints
    void reserve(size_t capacity) {
        bodies.reserve(capacity);
    }

    void addBody(const RigidBody& body) {
        bodies.push_back(body);
    }

    const std::vector<RigidBody>& getBodies() const { return bodies; }

    // Semi-Implicit Euler integration step (Symplectic Euler)
    void step(float dt) {
        for (auto& b : bodies) {
            if (b.invMass == 0.0f) continue; // Skip static objects

            // Apply gravity
            b.applyForce(gravity * b.mass);

            // Integrate velocity: v_new = v_old + (F / m) * dt
            b.velocity += b.force * b.invMass * dt;

            // Integrate position: x_new = x_old + v_new * dt
            b.position += b.velocity * dt;

            // Reset force accumulator
            b.force = {0.0f, 0.0f};
        }

        // Perform narrow-phase collision detection and constraint resolution
        resolveCollisions();
    }
};

int main() {
