    Vec2 normalized() const {
        float len = length();
        return len > 0.0001f ? *this * (1.0f / len) : Vec2{0.0f, 0.0f};
    }

    static float dot(const Vec2& a, const Vec2& b) {
        return a.x * b.x + a.y * b.y;
    }
};

// Rigid Body Structure
struct RigidBody {
    Vec2 position;
    Vec2 velocity;
    Vec2 force;

    float mass;
    float inv_mass; // Optimized cache: 1/mass. 0 for static/infinite mass.
    float radius;
    float restitution; // Bounciness (0.0 = no bounce, 1.0 = perfect elastic bounce)

    RigidBody(Vec2 pos, Vec2 vel, float m, float r, float rest)
        : position(pos), velocity(vel), force({0, 0}), mass(m), radius(r), restitution(rest) {
        inv_mass = (m > 0.0f) ? 1.0f / m : 0.0f;
    }

    void apply_force(const Vec2& f) {
        if (inv_mass == 0.0f) return;
        force += f;
    }

    void integrate_forces(float dt) {
        if (inv_mass == 0.0f) return;
        velocity += (force * inv_mass) * dt;
        force = {0.0f, 0.0f}; // Clear accumulator
    }

    void integrate_velocities(float dt) {
        if (inv_mass == 0.0f) return;
        position += velocity * dt;
    }
};

// Physics Simulation World
class PhysicsWorld {
public:
    std::vector<RigidBody> bodies;
    Vec2 gravity = {0.0f, -9.81f}; // Standard Earth gravity pointing downwards

    // Box constraints (Simulation Bounds)
    float width = 40.0f;
    float height = 20.0f;

    void step(float dt) {
        // 1. Apply Gravity
        for (auto& body : bodies) {
            body.apply_force(gravity * body.mass);
        }

        // 2. Integrate Forces (Update velocities)
        for (auto& body : bodies) {
            body.integrate_forces(dt);
        }

        // 3. Detect and Resolve Collisions
        resolve_collisions();

        // 4. Integrate Velocities (Update positions)
        for (auto& body : bodies) {
            body.integrate_velocities(dt);
        }
    }

private:
    void resolve_collisions() {
        size_t size = bodies.size();

        // Dynamic vs Dynamic (Circle-Circle Collision)
        for (size_t i = 0; i < size; ++i) {
            for (size_t j = i + 1; j < size; ++j) {
                RigidBody& a = bodies[i];
                RigidBody& b = bodies[j];

                Vec2 relative_pos = b.position - a.position;
                float dist_sq = relative_pos.length_sq();
                float min_dist = a.radius + b.radius;

                if (dist_sq < min_dist * min_dist) {
                    float dist = std::sqrt(dist_sq);
                    Vec2 normal = (dist > 0.0f) ? relative_pos / dist : Vec2{0.0f, 1.0f};
                    float penetration = min_dist - dist;

                    // Relative velocity along normal
                    Vec2 rel_vel = b.velocity - a.velocity;
                    float vel_along_normal = Vec2::dot(rel_vel, normal);

                    // Do not resolve if velocities are separating
                    if (vel_along_normal < 0) {
                        float e = std::min(a.restitution, b.restitution);
                        float j_scalar = -(1.0f + e) * vel_along_normal;
                        j_scalar /= (a.inv_mass + b.inv_mass);

                        Vec2 impulse = normal * j_scalar;
                        a.velocity -= impulse * a.inv_mass;
                        b.velocity += impulse * b.inv_mass;

                        // Positional correction (Sinking Prevention)
                        const float percent = 0.2f; // penetration percentage to correct
                        const float slop = 0.01f; // penetration allowance
                        Vec2 correction = normal * (std::max(penetration - slop, 0.0f) / (a.inv_mass + b.inv_mass) * percent);
                        a.position -= correction * a.inv_mass;
                        b.position += correction * b.inv_mass;
                    }
                }
            }
        }

        // Static Box Constraints Boundary Collisions
        for (auto& b : bodies) {
            if (b.inv_mass == 0.0f) continue;

            // Ground Floor (y = 0)
            if (b.position.y - b.radius < 0.0f) {
                b.position.y = b.radius;
                b.velocity.y = -b.velocity.y * b.restitution;
            }
            // Ceiling (y = height)
            if (b.position.y + b.radius > height) {
                b.position.y = height - b.radius;
                b.velocity.y = -b.velocity.y * b.restitution;
            }
            // Left Wall (x = 0)
            if (b.position.x - b.radius < 0.0f) {
                b.position.x = b.radius;
                b.velocity.x = -b.velocity.x * b.restitution;
            }
            // Right Wall (x = width)
            if (b.position.x + b.radius > width) {
                b.position.x = width - b.radius;
                b.velocity.x = -b.velocity.x * b.restitution;
            }
        }
    }
};

// Simple Console ASCII Renderer
void render(const PhysicsWorld& world) {
    int w = static_cast<int>(world.width);
    int h = static_cast<int>(world.height);

    // Initialize blank grid
    std::vector<std::string> grid(h, std::string(w, ' '));

    // Draw borders
    for (int x = 0; x < w; ++x) grid[0][x] = '#';
    for (int x = 0; x < w; ++x) grid[h - 1][x] = '#';
    for (int y = 0; y < h; ++y) {
        grid[y][0] = '#';
        grid[y][w - 1] = '#';
    }

    // Rasterize bodies (using '@' representing rigid bodies)
    for (const auto& body : world.bodies) {
        int cx = static_cast<int>(std::round(body.position.x));
        int cy = static_cast<int>(std::round(body.position.y));

        // Draw basic circle shape based on radius
        int r = static_cast<int>(std::round(body.radius));
        for (int dy = -r; dy <= r; ++dy) {
            for (int dx = -r; dx <= r; ++dx) {
                if (dx*dx + dy*dy <= r*r) {
                    int target_x = cx + dx;
                    // Invert Y coordinate because terminal graphics start at (0,0) on top-left
                    int target_y = (h - 1) - (cy + dy); 

                    if (target_x > 0 && target_x < w - 1 && target_y > 0 && target_y < h - 1) {
                        grid[target_y][target_x] = 'O';
                    }
                }
            }
        }
    }

    // Clear terminal screen using ANSI escape codes
    std::cout << "\033[H";
    for (const auto& line : grid) {
        std::cout << line << "\n";
    }
    std::cout << "Real-time physics active. Press Ctrl+C to exit.\n";
}

int main() {
    PhysicsWorld world;

    // Spawn rigid bodies (Circles with positions, velocities, mass, radius, and restitution)
    world.bodies.push_back(RigidBody({10.0f, 15.0f}, {15.0f, 0.0f},  3.0f, 1.5f, 0.8f));
    world.bodies.push_back(RigidBody({30.0f, 12.0f}, {-10.0f, 5.0f}, 2.0f, 1.0f, 0.7f));
    world.bodies.push_back(RigidBody({20.0f, 18.0f}, {2.0f, -8.0f},  5.0f, 2.0f, 0.6f));

    // Clear Screen at Startup
    std::cout << "\033[2J";

    // Timing Variables for the Frame-Rate loop
    using Clock = std::chrono::high_resolution_clock;
    auto previous_time = Clock::now();
    double accumulator = 0.0;

    // 60 Hz Physics Engine Timestep Target
    const double dt = 1.0 / 60.0; 
    const std::chrono::duration<double> target_frame_duration(1.0 / 60.0); // 60 FPS visual limit

    while (true) {
        auto current_time = Clock::now();
        std::chrono::duration<double> elapsed = current_time - previous_time;
        previous_time = current_time;

        double frame_time = elapsed.count();
        if (frame_time > 0.25) frame_time = 0.25; // Prevents "spiral of death" on lag spikes

        accumulator += frame_time;

        // Fixed-Timestep Physics Loop
        while (accumulator >= dt) {
            world.step(static_cast<float>(dt));
            accumulator -= dt;
        }

        // Render Frame
        render(world);

        // Frame-rate constraints (sleep if running faster than target frame rate)
        auto frame_end_time = Clock::now();
        std::chrono::duration<double> computation_time = frame_end_time - current_time;
        if (computation_time < target_frame_duration) {
            std::this_thread::sleep_for(target_frame_duration - computation_time);
        }
    }

    return 0;
}
