// Simple 2D Vector
struct Vec2 {
    float x, y;
    Vec2 operator+(const Vec2& o) const { return {x + o.x, y + o.y}; }
    Vec2 operator-(const Vec2& o) const { return {x - o.x, y - o.y}; }
    Vec2 operator*(float scalar) const { return {x * scalar, y * scalar}; }
    Vec2 operator/(float scalar) const { return {x / scalar, y / scalar}; }
    float dot(const Vec2& o) const { return x * o.x + y * o.y; }
    float length() const { return std::sqrt(x * x + y * y); }
    Vec2 normalize() const {
        float len = length();
        return len > 0.0001f ? *this / len : Vec2{0.0f, 0.0f};
    }
};

// Rigid Body definition
struct RigidBody {
    Vec2 position;
    Vec2 velocity;
    float radius;
    float mass;
    float invMass; // Precomputed for speed: 1/mass
    float restitution; // Bounciness (0.0 = clay, 1.0 = perfect bounce)
    char symbol;

    RigidBody(Vec2 pos, Vec2 vel, float r, float m, float e, char sym)
        : position(pos), velocity(vel), radius(r), mass(m), restitution(e), symbol(sym) {
        invMass = (m > 0.0f) ? 1.0f / m : 0.0f; // Static objects have 0 mass (invMass = 0)
    }
};

// World Dimensions
const int WIDTH = 80;
const int HEIGHT = 24;
const Vec2 GRAVITY = {0.0f, 15.0f}; // Downward gravity

// Resolve collision between two spheres
void ResolveCollision(RigidBody& a, RigidBody& b) {
    Vec2 normal = b.position - a.position;
    float dist = normal.length();
    float minDist = a.radius + b.radius;

    if (dist >= minDist) return; // No overlap

    normal = normal.normalize();

    // 1. Positional Correction (prevents sinking/clipping)
    float overlap = minDist - dist;
    const float percent = 0.4f; // Penetration percentage to resolve per frame
    const float slop = 0.01f;     // Penetration allowance
    Vec2 correction = normal * (std::max(overlap - slop, 0.0f) / (a.invMass + b.invMass)) * percent;
    a.position = a.position - correction * a.invMass;
    b.position = b.position + correction * b.invMass;

    // 2. Impulse Resolution (Velocity change)
    Vec2 relativeVel = b.velocity - a.velocity;
    float velAlongNormal = relativeVel.dot(normal);

    if (velAlongNormal > 0) return; // Moving apart already

    float e = std::min(a.restitution, b.restitution);
    float impulseScalar = -(1.0f + e) * velAlongNormal;
    impulseScalar /= (a.invMass + b.invMass);

    Vec2 impulse = normal * impulseScalar;
    a.velocity = a.velocity - impulse * a.invMass;
    b.velocity = b.velocity + impulse * b.invMass;
}

// Resolve collisions with screen boundaries
void ResolveBoundaryCollisions(RigidBody& body) {
    // Floor
    if (body.position.y + body.radius > HEIGHT) {
        body.position.y = HEIGHT - body.radius;
        body.velocity.y = -body.velocity.y * body.restitution;
    }
    // Ceiling
    if (body.position.y - body.radius < 0) {
        body.position.y = body.radius;
        body.velocity.y = -body.velocity.y * body.restitution;
    }
    // Left Wall
    if (body.position.x - body.radius < 0) {
        body.position.x = body.radius;
        body.velocity.x = -body.velocity.x * body.restitution;
    }
    // Right Wall
    if (body.position.x + body.radius > WIDTH) {
        body.position.x = WIDTH - body.radius;
        body.velocity.x = -body.velocity.x * body.restitution;
    }
}

// Draw the scene to the console using double buffering
void Render(const std::vector<RigidBody>& bodies) {
    std::vector<std::string> buffer(HEIGHT, std::string(WIDTH, ' '));

    // Draw rigid bodies
    for (const auto& body : bodies) {
        int cx = static_cast<int>(body.position.x);
        int cy = static_cast<int>(body.position.y);
        int r = static_cast<int>(body.radius);

        // Fill circle on the ASCII grid
        for (int y = -r; y <= r; ++y) {
            for (int x = -r; x <= r; ++x) {
                if (x*x + y*y <= r*r) {
                    int screenX = cx + x;
                    int screenY = cy + y;
                    if (screenX >= 0 && screenX < WIDTH && screenY >= 0 && screenY < HEIGHT) {
                        buffer[screenY][screenX] = body.symbol;
                    }
                }
            }
        }
    }

    // ANSI Escape Code to reset cursor to top-left (prevents flickering)
    std::cout << "\x1b[H"; 

    // Draw walls and buffer
    std::cout << std::string(WIDTH + 2, '#') << "\n";
    for (int y = 0; y < HEIGHT; ++y) {
        std::cout << '#' << buffer[y] << "#\n";
    }
    std::cout << std::string(WIDTH + 2, '#') << std::endl;
}

int main() {
    // Enable ANSI escape codes for Windows if necessary
#ifdef _WIN32
    system("cls");
#else
    std::cout << "\x1b[2J"; // Clear screen once
#endif

    // Setup physical rigid bodies
    std::vector<RigidBody> bodies;
    // Format: Position{x, y}, Velocity{x, y}, Radius, Mass, Restitution, Symbol
    bodies.push_back(RigidBody({15.0f, 5.0f},  {30.0f, 0.0f},  2.5f, 10.0f, 0.8f, '@'));
    bodies.push_back(RigidBody({65.0f, 5.0f},  {-20.0f, 0.0f}, 3.5f, 25.0f, 0.7f, 'O'));
    bodies.push_back(RigidBody({40.0f, 18.0f}, {0.0f, -10.0f}, 1.5f, 5.0f,  0.9f, '*'));

    // Real-Time Loop Settings
    const double dt = 0.01; // Fixed timestep: 10ms (100 physics updates per second)
    double accumulator = 0.0;

    auto currentTime = std::chrono::high_resolution_clock::now();

    while (true) {
        auto newTime = std::chrono::high_resolution_clock::now();
        double frameTime = std::chrono::duration<double>(newTime - currentTime).count();
        currentTime = newTime;

        // Prevent "Spiral of Death" (limit max frame processing time in case of lag spikes)
        if (frameTime > 0.25) {
            frameTime = 0.25;
        }

        accumulator += frameTime;

        // --- PHYSICS UPDATE LOOP (Deterministic Fixed-Timestep) ---
        while (accumulator >= dt) {
            for (size_t i = 0; i < bodies.size(); ++i) {
                // Apply Gravity and Euler-Cromer Integration
                bodies[i].velocity = bodies[i].velocity + GRAVITY * dt;
                bodies[i].position = bodies[i].position + bodies[i].velocity * dt;

                // Wall collisions
                ResolveBoundaryCollisions(bodies[i]);
            }

            // Resolve pairwise dynamic body-to-body collisions
            for (size_t i = 0; i < bodies.size(); ++i) {
                for (size_t j = i + 1; j < bodies.size(); ++j) {
                    ResolveCollision(bodies[i], bodies[j]);
                }
            }

            accumulator -= dt;
        }

        // --- RENDER (At the speed of the hardware) ---
        Render(bodies);

        // Throttle the loop slightly so it doesn't max out CPU cores unnecessarily
        std::this_thread::sleep_for(std::chrono::milliseconds(16)); // Target ~60 FPS
    }

    return 0;
}
