```cpp
#include <iostream>
#include <chrono>
#include <thread>
#include <vector>
#include <string>

// Physics Constants
const double GRAVITY = -15.0;      // m/s^2 (scaled for visual scale)
const double DT = 1.0 / 60.0;     // Fixed physics timestep (60 Hz)
const int ScreenWidth = 50;
const int ScreenHeight = 20;

struct RigidBody {
    double x, y;          // Position
    double vx, vy;        // Velocity
    double radius;        // Size
    double mass;          // Mass
    double restitution;   // Bounciness (0 = no bounce, 1 = perfect elastic bounce)
};

// Physics Integration: Semi-Implicit Euler (More stable than Explicit Euler)
void Integrate(RigidBody& body, double dt) {
    if (body.mass <= 0.0) return; // Static object

    // 1. Integrate forces to get velocity: v = v + a * dt
    body.vy += GRAVITY * dt;

    // 2. Integrate velocity to get position: x = x + v * dt
    body.x += body.vx * dt;
    body.y += body.vy * dt;
}

// Collision Resolution with Boundary Walls
void ResolveCollisions(RigidBody& body) {
    // Left & Right Walls
    double minX = body.radius;
    double maxX = ScreenWidth - body.radius;
    if (body.x < minX) {
        body.x = minX;
        body.vx = -body.vx * body.restitution;
    } else if (body.x > maxX) {
        body.x = maxX;
        body.vx = -body.vx * body.restitution;
    }

    // Floor & Ceiling
    double minY = body.radius;
    double maxY = ScreenHeight - body.radius;
    if (body.y < minY) {
        body.y = minY;
        body.vy = -body.vy * body.restitution;
    } else if (body.y > maxY) {
        body.y = maxY;
        body.vy = -body.vy * body.restitution;
    }
}

// Simple ASCII Renderer
void Render(const RigidBody& body) {
    // Clear the screen using ANSI escape codes (highly performant compared to system("cls"))
    std::cout << "\x1B[2J\x1B[H";

    // Create frame buffer
    std::vector<std::string> buffer(ScreenHeight, std::string(ScreenWidth, ' '));

    // Map physics world to screen coordinates (invert Y axis so Y=0 is bottom)
    int ballX = static_cast<int>(body.x);
    int ballY = ScreenHeight - 1 - static_cast<int>(body.y);

    // Draw the body in buffer boundaries
    if (ballX >= 0 && ballX < ScreenWidth && ballY >= 0 && ballY < ScreenHeight) {
        buffer[ballY][ballX] = 'O'; // 'O' represents our rigid body ball
    }

    // Render buffer to stdout
    std::string output = "+" + std::string(ScreenWidth, '-') + "+\n";
    for (const auto& row : buffer) {
        output += "|" + row + "|\n";
    }
    output += "+" + std::string(ScreenWidth, '-') + "+\n";

    std::cout << output;
    std::cout << "FPS Target: 60Hz | Physics Timestep: " << DT * 1000 << "ms\n";
    std::cout << "Pos: (" << body.x << ", " << body.y << ") | Vel: (" << body.vx << ", " << body.vy << ")\n";
}

int main() {
    // Initialize Rigid Body
    RigidBody ball;
    ball.x = 5.0;
    ball.y = 15.0;
    ball.vx = 25.0;       // Initial push to the right
    ball.vy = 5.0;        // Initial upward push
    ball.radius = 1.0;
    ball.mass = 1.0;
    ball.restitution = 0.85; // Loses 15% kinetic energy on impact

    // Timing Variables for the Frame-Rate/Physics Loop
    auto currentTime = std::chrono::high_resolution_clock::now();
    double accumulator = 0.0;
    bool running = true;

    while (running) {
        auto newTime = std::chrono::high_resolution_clock::now();
        double frameTime = std::chrono::duration<double>(newTime - currentTime).count();
        currentTime = newTime;

        // "Spiral of death" protection: clamp max frame time
        if (frameTime > 0.25) {
            frameTime = 0.25;
        }

        accumulator += frameTime;

        // Consistently update physics at the target DT (60Hz)
        while (accumulator >= DT) {
            Integrate(ball, DT);
            ResolveCollisions(ball);
            accumulator -= DT;
        }

        // Render the scene at the highest rate possible
        Render(ball);

        // Cap frame-rate/CPU usage by sleeping for the remainder of a frame (~16.6ms target)
        std::this_thread::sleep_for(std::chrono::milliseconds(16));
    }

    return 0;
}
