    float x = 0.0f;
    float y = 0.0f;

    Vec2 operator+(const Vec2& v) const { return {x + v.x, y + v.y}; }
    Vec2 operator-(const Vec2& v) const { return {x - v.x, y - v.y}; }
    Vec2 operator*(float scalar) const { return {x * scalar, y * scalar}; }
    Vec2& operator+=(const Vec2& v) { x += v.x; y += v.y; return *this; }

    float Dot(const Vec2& v) const { return x * v.x + y * v.y; }
    float Length() const { return std::sqrt(x * x + y * y); }
    Vec2 Normalize() const {
        float len = Length();
        return len > 0.0f ? Vec2{x / len, y / len} : Vec2{0.0f, 0.0f};
    }
};

// Rigid Body Representation
struct RigidBody {
    Vec2 position;
    Vec2 velocity;
    Vec2 force;
    float mass;
    float invMass;
    float radius;
    float restitution; // Bounciness [0 = no bounce, 1 = perfect bounce]

    RigidBody(Vec2 pos, float r, float m, float e) 
        : position(pos), radius(r), mass(m), restitution(e) {
        invMass = (m > 0.0f) ? 1.0f / m : 0.0f; // invMass = 0 represents static objects
        velocity = {0.0f, 0.0f};
        force = {0.0f, 0.0f};
    }

    void ApplyForce(const Vec2& f) {
        if (invMass == 0.0f) return;
        force += f;
    }
};

// Physics World Container
class PhysicsWorld {
public:
    Vec2 gravity = {0.0f, -9.81f};
    std::vector<RigidBody> bodies;

    // Boundaries of our simulation box
    float worldWidth = 40.0f;
    float worldHeight = 20.0f;

    void Step(float dt) {
        // 1. Force Integration (Semi-Implicit Euler)
        for (auto& body : bodies) {
            if (body.invMass == 0.0f) continue;

            body.ApplyForce(gravity * body.mass); // Apply gravity
            body.velocity += body.force * body.invMass * dt;
            body.position += body.velocity * dt;
            body.force = {0.0f, 0.0f}; // Reset forces
        }

        // 2. Collision Detection & Resolution (Ground & Walls)
        for (auto& body : bodies) {
            // Collision with Ground (y = 0)
            float floorLevel = body.radius;
            if (body.position.y < floorLevel) {
                ResolveBoundaryCollision(body, {0.0f, 1.0f}, floorLevel - body.position.y);
                body.position.y = floorLevel;
            }

            // Collision with Left Wall (x = 0)
            float leftWall = body.radius;
            if (body.position.x < leftWall) {
                ResolveBoundaryCollision(body, {1.0f, 0.0f}, leftWall - body.position.x);
                body.position.x = leftWall;
            }

            // Collision with Right Wall (x = worldWidth)
            float rightWall = worldWidth - body.radius;
            if (body.position.x > rightWall) {
                ResolveBoundaryCollision(body, {-1.0f, 0.0f}, body.position.x - rightWall);
                body.position.x = rightWall;
            }
        }
    }

private:
    void ResolveBoundaryCollision(RigidBody& body, const Vec2& normal, float penetration) {
        // Calculate relative velocity along the collision normal
        float velAlongNormal = body.velocity.Dot(normal);

        // Do not resolve if velocities are separating
        if (velAlongNormal > 0) return;

        // Calculate impulse scalar
        float j = -(1.0f + body.restitution) * velAlongNormal;
        j /= body.invMass; // Ground is static (infinite mass), so only body.invMass is used

        // Apply impulse
        body.velocity += normal * (j * body.invMass);

        // Positional correction to prevent sinking (using 80% correction)
        const float percent = 0.8f; 
        body.position += normal * (penetration * percent);
    }
};

// Simple ASCII Console Renderer
void Render(const PhysicsWorld& world) {
    const int screenWidth = 80;
    const int screenHeight = 22;
    char screen[screenHeight][screenWidth];

    // Initialize screen with empty space and borders
    for (int y = 0; y < screenHeight; ++y) {
        for (int x = 0; x < screenWidth; ++x) {
            if (y == screenHeight - 1) screen[y][x] = '_';
            else if (x == 0 || x == screenWidth - 1) screen[y][x] = '|';
            else screen[y][x] = ' ';
        }
    }

    // Map physics coordinate system to screen coordinate system
    for (const auto& body : world.bodies) {
        int screenX = static_cast<int>((body.position.x / world.worldWidth) * (screenWidth - 2)) + 1;
        // Flip Y because console coordinates start from top-left (0,0)
        int screenY = (screenHeight - 2) - static_cast<int>((body.position.y / world.worldHeight) * (screenHeight - 2));

        if (screenX > 0 && screenX < screenWidth - 1 && screenY >= 0 && screenY < screenHeight - 1) {
            screen[screenY][screenX] = 'O'; // 'O' represents our rigid ball
        }
    }

    // Clear screen (using ANSI escape codes for smooth drawing)
    std::cout << "\x1B[2J\x1B[H";
    for (int y = 0; y < screenHeight; ++y) {
        for (int x = 0; x < screenWidth; ++x) {
            std::cout << screen[y][x];
        }
        std::cout << '\n';
    }
    std::cout << "Controls: Watch the rigid body bounce under deterministic gravity physics.\n";
}

int main() {
    PhysicsWorld world;

    // Spawn a rigid body (Pos: x=5, y=18, Radius: 1.0, Mass: 1.0kg, Restitution: 0.8)
    RigidBody ball({5.0f, 18.0f}, 1.0f, 1.0f, 0.80f);
    // Give it some initial horizontal velocity
    ball.velocity = {15.0f, 5.0f};
    world.bodies.push_back(ball);

    // High-precision clock setup
    using Clock = std::chrono::high_resolution_clock;
    auto currentTime = Clock::now();
    double accumulator = 0.0;

    // Fixed physics timestep (100 Hz / 10ms steps)
    const double dt = 0.01; 

    // Target render framerate (60 FPS / ~16.6ms intervals)
    const std::chrono::milliseconds frameTargetDelay(16);

    bool running = true;
    int ticks = 0;

    while (running && ticks < 1000) { // Run for ~1000 simulation updates
        auto newTime = Clock::now();
        double frameTime = std::chrono::duration<double>(newTime - currentTime).count();
        currentTime = newTime;

        // Avoid "Spiral of Death" (cap maximum frame processing time)
        if (frameTime > 0.25) {
            frameTime = 0.25;
        }

        accumulator += frameTime;

        // --- Deterministic Physics Step ---
        while (accumulator >= dt) {
            world.Step(static_cast<float>(dt));
            accumulator -= dt;
            ticks++;
        }

        // --- Render Step ---
        Render(world);

        // Frame rate constraint: Sleep to throttle CPU usage to target frame rate (~60 FPS)
        std::this_thread::sleep_for(frameTargetDelay);
    }

    return 0;
}
