const int SCREEN_HEIGHT = 20;
const Vec2 GRAVITY = { 0.0, -9.81 }; // m/s^2 (downward)

// Physics update (Semi-Implicit Euler integration)
void PhysicsStep(RigidBody& body, double dt) {
    // 1. Integrate forces (Gravity) to update velocity
    body.velocity += GRAVITY * dt;

    // 2. Integrate velocity to update position
    body.position += body.velocity * dt;

    // 3. Collision Detection & Resolution (Static Boundaries)

    // Bottom Wall Collision
    double floorY = 0.5;
    if (body.position.y - body.radius < floorY) {
        body.position.y = floorY + body.radius;               // Positional Correction (prevents sinking)
        body.velocity.y = -body.velocity.y * body.restitution; // Impulse Resolution
    }

    // Left/Right Wall Collision
    double leftWallX = 0.5;
    double rightWallX = SCREEN_WIDTH - 0.5;
    if (body.position.x - body.radius < leftWallX) {
        body.position.x = leftWallX + body.radius;
        body.velocity.x = -body.velocity.x * body.restitution;
    } else if (body.position.x + body.radius > rightWallX) {
        body.position.x = rightWallX - body.radius;
        body.velocity.x = -body.velocity.x * body.restitution;
    }
}

