    float dot(const Vec2& o) const { return x * o.x + y * o.y; }
};

// Rigid Body Representation
struct RigidBody {
    Vec2 position;
    Vec2 velocity;
    float radius;
    float mass;
    float invMass;
    float restitution; // Bounciness [0.0 = clay, 1.0 = perfectly elastic]
    char symbol;       // Visual representation inside terminal

    RigidBody(Vec2 pos, Vec2 vel, float r, float m, float rest, char sym)
        : position(pos), velocity(vel), radius(r), mass(m), restitution(rest), symbol(sym) {
        invMass = (m > 0.0f) ? 1.0f / m : 0.0f; // Static objects have 0 mass -> infinite inverse mass
    }
};

// --- Physics Pipeline ---
void StepPhysics(std::vector<RigidBody>& bodies, float dt, float width, float height) {
    const Vec2 gravity{0.0f, 9.81f}; // Downward gravity force

    // 1. Integration (Symplectic Euler: update velocities, then positions)
    for (auto& body : bodies) {
        if (body.invMass > 0.0f) {
            body.velocity += gravity * dt;
        }
        body.position += body.velocity * dt;
    }

    // Define boundary play-area (accounting for ASCII wall thickness)
    const float left = 1.0f;
    const float right = width - 1.0f;
    const float top = 1.0f;
    const float bottom = height - 1.0f;

    // 2. Static Boundary Collision Detection and Resolution
    for (auto& body : bodies) {
        // Floor
        if (body.position.y + body.radius > bottom) {
            body.position.y = bottom - body.radius;
            body.velocity.y = -body.velocity.y * body.restitution;
        }
        // Ceiling
        if (body.position.y - body.radius < top) {
            body.position.y = top + body.radius;
            body.velocity.y = -body.velocity.y * body.restitution;
        }
        // Right wall
        if (body.position.x + body.radius > right) {
            body.position.x = right - body.radius;
            body.velocity.x = -body.velocity.x * body.restitution;
        }
        // Left wall
        if (body.position.x - body.radius < left) {
            body.position.x = left + body.radius;
            body.velocity.x = -body.velocity.x * body.restitution;
        }
    }

    // 3. Rigid Body vs Rigid Body Collision Detection (O(N^2) checks)
    for (size_t i = 0; i < bodies.size(); ++i) {
        for (size_t j = i + 1; j < bodies.size(); ++j) {
            RigidBody& A = bodies[i];
            RigidBody& B = bodies[j];

            Vec2 normal = B.position - A.position;
            float distSq = normal.lengthSq();
            float minDist = A.radius + B.radius;

            if (distSq < minDist * minDist) {
                float dist = std::sqrt(distSq);
                if (dist == 0.0f) {
                    dist = 0.1f;
                    normal = {1.0f, 0.0f};
                } else {
                    normal = normal / dist;
                }

                // Relative velocity
                Vec2 rv = B.velocity - A.velocity;
                float velAlongNormal = rv.dot(normal);

                // Only resolve if velocities are approaching
                if (velAlongNormal < 0.0f) {
                    // Calculate restitution coefficient
                    float e = std::min(A.restitution, B.restitution);

                    // Calculate impulse scalar
                    float jImpulse = -(1.0f + e) * velAlongNormal;
                    float totalInvMass = A.invMass + B.invMass;
                    jImpulse /= totalInvMass;

                    // Apply impulse to each body
                    Vec2 impulse = normal * jImpulse;
                    A.velocity -= impulse * A.invMass;
                    B.velocity += impulse * B.invMass;

                    // Positional Correction to prevent "sinking/sticking" (non-elastic overlap resolution)
                    const float percent = 0.8f; // Penetration percentage to fix per step
                    const float slop = 0.01f;   // Penetration allowance threshold
                    float penetration = minDist - dist;
                    if (totalInvMass > 0.0f) {
                        Vec2 correction = normal * (std::max(penetration - slop, 0.0f) / totalInvMass) * percent;
                        A.position -= correction * A.invMass;
                        B.position += correction * B.invMass;
                    }
                }
            }
        }
    }
}

