public class PaymentProcessingEngine {

    // --- 1. DOMAIN MODELS & VALUE OBJECTS ---

    public record PaymentRequest(
        String idempotencyKey,
        String sourceAccountId,
        String destinationAccountId,
        BigDecimal amount,
        String currency,
        CardDetails cardDetails // Sensitve data
    ) {
        public PaymentRequest {
            Objects.requireNonNull(idempotencyKey, "Idempotency key is required");
            Objects.requireNonNull(sourceAccountId, "Source account is required");
            Objects.requireNonNull(destinationAccountId, "Destination account is required");
            Objects.requireNonNull(amount, "Amount is required");
            Objects.requireNonNull(currency, "Currency is required");
            if (amount.compareTo(BigDecimal.ZERO) <= 0) {
                throw new IllegalArgumentException("Amount must be positive");
            }
            if (sourceAccountId.equals(destinationAccountId)) {
                throw new IllegalArgumentException("Source and destination accounts must be different");
            }
        }

        @Override
        public String toString() {
            return String.format("PaymentRequest[idempotencyKey=%s, source=%s, dest=%s, amount=%s %s, card=%s]",
                idempotencyKey, sourceAccountId, destinationAccountId, amount, currency, cardDetails);
        }
    }

    public record CardDetails(String holderName, String pan, String cvv, String expiry) {
