        }

        private static String maskPan(String pan) {
            if (pan == null || pan.length() < 4) return "****";
            return "****-****-****-" + pan.substring(pan.length() - 4);
        }
    }

    public enum TransactionStatus { SUCCESS, FAILED, PENDING }

    public record PaymentResponse(
        String transactionId,
        String idempotencyKey,
        TransactionStatus status,
        BigDecimal amount,
        String currency,
        Instant timestamp,
        String errorCode,
        String errorMessage
    ) {
        public static PaymentResponse success(String transactionId, PaymentRequest request) {
            return new PaymentResponse(transactionId, request.idempotencyKey(), TransactionStatus.SUCCESS,
                request.amount(), request.currency(), Instant.now(), null, null);
        }

        public static PaymentResponse failed(String transactionId, PaymentRequest request, String errorCode, String errorMessage) {
            return new PaymentResponse(transactionId, request.idempotencyKey(), TransactionStatus.FAILED,
                request.amount(), request.currency(), Instant.now(), errorCode, errorMessage);
        }
    }

    // --- 2. EXCEPTIONS ---

    public static class PaymentException extends RuntimeException {
        private final String errorCode;
        public PaymentException(String errorCode, String message) {
            super(message);
            this.errorCode = errorCode;
        }
        public String getErrorCode() { return errorCode; }
    }

    public static class InsufficientFundsException extends PaymentException {
        public InsufficientFundsException(String msg) { super("INSUFFICIENT_FUNDS", msg); }
    }

    public static class IdempotencyConflictException extends PaymentException {
        public IdempotencyConflictException(String msg) { super("IDEMPOTENCY_CONFLICT", msg); }
    }

    // --- 3. DATABASE SIMULATION (THREAD-SAFE) ---

    public static class Account {
        private final String accountId;
        private BigDecimal balance;
        private final ReentrantLock lock = new ReentrantLock(); // Simulates Row-Level Lock

        public Account(String accountId, BigDecimal initialBalance) {
            this.accountId = accountId;
            this.balance = initialBalance;
        }

        public String getAccountId() { return accountId; }
        public BigDecimal getBalance() { return balance; }
        public ReentrantLock getLock() { return lock; }

        public void debit(BigDecimal amount) {
            if (this.balance.compareTo(amount) < 0) {
                throw new InsufficientFundsException("Account " + accountId + " has insufficient funds.");
            }
            this.balance = this.balance.subtract(amount);
        }

        public void credit(BigDecimal amount) {
            this.balance = this.balance.add(amount);
        }
    }

    // --- 4. CORE PAYMENT SERVICE ---

    public static class PaymentProcessorService {
        // Simulating highly concurrent database tables
        private final Map<String, Account> accountDb = new ConcurrentHashMap<>();
        private final Map<String, PaymentResponse> idempotencyStore = new ConcurrentHashMap<>();
        private final Set<String> activeIdempotencyKeys = ConcurrentHashMap.newKeySet();

        public PaymentProcessorService() {
            // Seed the DB with some test accounts
            accountDb.put("ACC-DEBIT-123", new Account("ACC-DEBIT-123", new BigDecimal("1000.00")));
            accountDb.put("ACC-CREDIT-999", new Account("ACC-CREDIT-999", new BigDecimal("500.00")));
        }

        public PaymentResponse processPayment(PaymentRequest request) {
            logSecurely("Initiating transaction processing", request);

            // A. Check Idempotency (Strictly required for API safety)
            if (idempotencyStore.containsKey(request.idempotencyKey())) {
                logWarning("Duplicate request detected. Returning cached response for key: " + request.idempotencyKey());
                return idempotencyStore.get(request.idempotencyKey());
            }

            // Prevent concurrent identical requests using the same idempotency key
            if (!activeIdempotencyKeys.add(request.idempotencyKey())) {
                throw new IdempotencyConflictException("Transaction with this key is already in progress.");
            }

            String transactionId = "TXN-" + UUID.randomUUID().toString().substring(0, 8).toUpperCase();

            try {
                // Fetch accounts
                Account source = accountDb.get(request.sourceAccountId());
                Account dest = accountDb.get(request.destinationAccountId());

                if (source == null || dest == null) {
                    throw new PaymentException("INVALID_ACCOUNT", "One or both accounts do not exist.");
                }

                // B. Distributed Deadlock Avoidance (Consistent Lock Ordering)
                // Always lock the account with the lexicographically smaller ID first
                Account firstLock = source.getAccountId().compareTo(dest.getAccountId()) < 0 ? source : dest;
                Account secondLock = firstLock == source ? dest : source;

                firstLock.getLock().lock();
                try {
                    secondLock.getLock().lock();
                    try {
                        // C. Execution of the Acid-compliant Transaction
                        logInfo(String.format("[%s] Locks acquired. Executing ledger entry.", transactionId));

                        source.debit(request.amount());
                        dest.credit(request.amount());

                        logInfo(String.format("[%s] Successfully transferred %s %s from %s to %s", 
                            transactionId, request.amount(), request.currency(), source.getAccountId(), dest.getAccountId()));

                        PaymentResponse successResponse = PaymentResponse.success(transactionId, request);
                        idempotencyStore.put(request.idempotencyKey(), successResponse);
                        return successResponse;

                    } finally {
                        secondLock.getLock().unlock();
                    }
                } finally {
                    firstLock.getLock().unlock();
                }

            } catch (PaymentException ex) {
                logError(String.format("[%s] Business rule violation: %s", transactionId, ex.getMessage()));
                PaymentResponse failedResponse = PaymentResponse.failed(transactionId, request, ex.getErrorCode(), ex.getMessage());
                idempotencyStore.put(request.idempotencyKey(), failedResponse);
                return failedResponse;
            } catch (Exception ex) {
                logCritical(String.format("[%s] System error during transaction: %s", transactionId, ex.getMessage()));
                PaymentResponse failedResponse = PaymentResponse.failed(transactionId, request, "SYSTEM_ERROR", "Internal server error.");
                return failedResponse;
            } finally {
                // Clean up lock on key
                activeIdempotencyKeys.remove(request.idempotencyKey());
            }
        }

        public BigDecimal getBalance(String accountId) {
            return accountDb.get(accountId).getBalance();
        }

        // --- 5. SECURE LOGGING UTIL (PCI-DSS compliant) ---
        private void logSecurely(String message, PaymentRequest req) {
            // Replaces card details inside toString representation automatically
            System.out.printf("[SECURE LOG] %s - Request Details: %s%n", message, req);
        }

        private void logInfo(String message) {
            System.out.println("[INFO] " + Instant.now() + " - " + message);
        }

        private void logWarning(String message) {
            System.out.println("[WARN] " + Instant.now() + " - " + message);
        }

        private void logError(String message) {
            System.err.println("[ERROR] " + Instant.now() + " - " + message);
        }

        private void logCritical(String message) {
            System.err.println("[CRITICAL ALERT] " + Instant.now() + " - " + message);
        }
    }

    // --- 6. DEMO / SIMULATION RUNNER ---

    public static void main(String[] args) throws InterruptedException {
        PaymentProcessorService paymentService = new PaymentProcessorService();

        System.out.println("=================================================");
        System.out.println("  STARTING TRANSACTION ENGINE SIMULATION");
        System.out.println("=================================================");
        System.out.println("Initial Source Balance: $" + paymentService.getBalance("ACC-DEBIT-123"));
        System.out.println("Initial Dest Balance:   $" + paymentService.getBalance("ACC-CREDIT-999"));
        System.out.println("-------------------------------------------------");

        ExecutorService executor = Executors.newFixedThreadPool(4);

        // Simulation 1: A valid standard payment
        PaymentRequest req1 = new PaymentRequest(
            "IDEM-KEY-001", "ACC-DEBIT-123", "ACC-CREDIT-999", 
            new BigDecimal("150.00"), "USD", 
            new CardDetails("Jane Doe", "4111222233334444", "123", "12/29")
        );

        // Simulation 2: A duplicate payment with the identical Idempotency Key (Double-click attack)
        PaymentRequest req2 = new PaymentRequest(
            "IDEM-KEY-001", "ACC-DEBIT-123", "ACC-CREDIT-999", 
            new BigDecimal("150.00"), "USD", 
            new CardDetails("Jane Doe", "4111222233334444", "123", "12/29")
        );

        // Simulation 3: A payment that exceeds balance (Should gracefully fail with Insufficient Funds)
        PaymentRequest req3 = new PaymentRequest(
            "IDEM-KEY-002", "ACC-DEBIT-123", "ACC-CREDIT-999", 
            new BigDecimal("2000.00"), "USD", 
            new CardDetails("Jane Doe", "4111222233334444", "123", "12/29")
        );

        // Submitting transactions concurrently to mimic real-world bank traffic
        executor.submit(() -> {
            PaymentResponse res = paymentService.processPayment(req1);
            System.out.println("Result 1: Status = " + res.status() + ", TXN_ID = " + res.transactionId());
        });

        executor.submit(() -> {
            // Attempting to double charge instantly
            try { Thread.sleep(10); } catch (InterruptedException ignored) {}
            PaymentResponse res = paymentService.processPayment(req2);
            System.out.println("Result 2 (Duplicate Check): Status = " + res.status() + ", ErrorCode = " + res.errorCode());
        });

        executor.submit(() -> {
            try { Thread.sleep(50); } catch (InterruptedException ignored) {}
            PaymentResponse res = paymentService.processPayment(req3);
            System.out.println("Result 3 (Overdraft Check): Status = " + res.status() + ", ErrorCode = " + res.errorCode());
        });

        executor.shutdown();
        executor.awaitTermination(5, TimeUnit.SECONDS);

        System.out.println("-------------------------------------------------");
        System.out.println("Final Source Balance: $" + paymentService.getBalance("ACC-DEBIT-123"));
        System.out.println("Final Dest Balance:   $" + paymentService.getBalance("ACC-CREDIT-999"));
        System.out.println("=================================================");
    }
}
