```java
package com.institution.payment;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;
import javax.validation.Valid;
import javax.validation.constraints.*;
import java.math.BigDecimal;
import java.time.Instant;
import java.util.Map;
import java.util.UUID;
import java.util.concurrent.ConcurrentHashMap;

// =========================================================================
// 1. DOMAIN MODELS & DTOs
// =========================================================================

enum PaymentStatus {
    PENDING, SUCCESS, FAILED, DECLINED
}

/**
 * Payment Request DTO with strict JSR-380 validation.
 * In a real bank, we prefer Tokenized Cards over raw PANs, but we validate both.
 */
record PaymentRequest(
    @NotBlank(message = "Idempotency key is required")
    String idempotencyKey,

    @NotNull(message = "Amount is required")
    @DecimalMin(value = "0.01", message = "Amount must be positive")
    BigDecimal amount,

    @NotBlank(message = "Currency is required")
    @Size(min = 3, max = 3, message = "Currency must be 3-letter ISO code")
    String currency,

    @NotBlank(message = "Source account/token is required")
    String sourceToken,

    @NotBlank(message = "Destination account is required")
    String destinationAccountId
) {
    // Custom masking to prevent raw accounts/tokens leaking in logs (PCI-DSS Compliance)
    @Override
    public String toString() {
        return String.format(
            "PaymentRequest[idempotencyKey=%s, amount=%s %s, sourceToken=****-%s, destinationAccountId=****-%s]",
            idempotencyKey, amount, currency, 
            sourceToken.substring(Math.max(0, sourceToken.length() - 4)),
            destinationAccountId.substring(Math.max(0, destinationAccountId.length() - 4))
        );
    }
}

record PaymentResponse(
    String transactionId,
    PaymentStatus status,
    String errorCode,
    String errorMessage,
    Instant timestamp
) {}

// Custom Exception for business-level failures
class PaymentProcessingException extends RuntimeException {
    private final String errorCode;
    public PaymentProcessingException(String errorCode, String message) {
        super(message);
        this.errorCode = errorCode;
    }
    public String getErrorCode() { return errorCode; }
}

// =========================================================================
// 2. IDEMPOTENCY ENGINE (Critical for financial systems)
// =========================================================================

class IdempotencyRecord {
    private final Instant createdAt;
    private final PaymentResponse response;

    public IdempotencyRecord(PaymentResponse response) {
        this.createdAt = Instant.now();
        this.response = response;
    }
    public PaymentResponse getResponse() { return response; }
}

// In production, this would be backed by Redis or PostgreSQL with an index on idempotency_key
class IdempotencyRegistry {
    private final Map<String, IdempotencyRecord> cache = new ConcurrentHashMap<>();

    public boolean exists(String key) {
        return cache.containsKey(key);
    }

    public PaymentResponse get(String key) {
        return cache.get(key).getResponse();
    }

    public void save(String key, PaymentResponse response) {
        cache.put(key, new IdempotencyRecord(response));
    }
}

// =========================================================================
// 3. CORE SERVICE LAYER
// =========================================================================

interface PaymentService {
    PaymentResponse processPayment(PaymentRequest request);
}

@Service
class PaymentServiceImpl implements PaymentService {
    private static final Logger log = LoggerFactory.getLogger(PaymentServiceImpl.class);

    private final IdempotencyRegistry idempotencyRegistry = new IdempotencyRegistry();
    private final ExternalAcquirerConnector acquirerConnector = new ExternalAcquirerConnector();

    @Override
    // Spring @Transactional would go here in a real application to ensure DB consistency
    public synchronized PaymentResponse processPayment(PaymentRequest request) {
        log.info("Processing payment request: {}", request);

        // 1. Idempotency Check (Verify this isn't a duplicate click/retry)
        if (idempotencyRegistry.exists(request.idempotencyKey())) {
            log.warn("Duplicate request detected for key: {}. Returning cached response.", request.idempotencyKey());
            return idempotencyRegistry.get(request.idempotencyKey());
        }

        String transactionId = UUID.randomUUID().toString();
        PaymentResponse response;

        try {
            // 2. Business Validation (e.g., Sanction screening / Fraud check)
            runSanctionCheck(request);

            // 3. Call External Card Network/Clearing House (e.g., Visa, Mastercard, FedNow)
            AcquirerResponse acquirerResponse = acquirerConnector.routeToNetwork(transactionId, request);

            if (acquirerResponse.isSuccess()) {
                log.info("Payment successfully processed. Txn ID: {}", transactionId);
                response = new PaymentResponse(transactionId, PaymentStatus.SUCCESS, null, null, Instant.now());
            } else {
                log.error("Payment declined by card network. Reason: {}", acquirerResponse.reasonCode());
                response = new PaymentResponse(transactionId, PaymentStatus.DECLINED, acquirerResponse.reasonCode(), "Declined by network", Instant.now());
            }

        } catch (PaymentProcessingException ex) {
            log.error("Payment validation/fraud failure: {}", ex.getMessage());
            response = new PaymentResponse(transactionId, PaymentStatus.FAILED, ex.getErrorCode(), ex.getMessage(), Instant.now());
        } catch (Exception ex) {
            log.error("System error processing payment: {}", ex.getMessage(), ex);
            // Critical: Do NOT return raw system exceptions to clients
            response = new PaymentResponse(transactionId, PaymentStatus.FAILED, "SYSTEM_ERROR", "Internal server error occurred", Instant.now());
        }

        // 4. Save to Idempotency Registry before returning
        idempotencyRegistry.save(request.idempotencyKey(), response);
        return response;
    }

    private void runSanctionCheck(PaymentRequest request) {
        // OFAC/AML screening mock
        if (request.destinationAccountId().contains("BLOCKED")) {
            throw new PaymentProcessingException("AML_BLOCK", "Transaction blocked by compliance filter.");
        }
    }
}

// =========================================================================
// 4. EXTERNAL GATEWAY INTEGRATION
// =========================================================================

record AcquirerResponse(boolean isSuccess, String reasonCode) {}

class ExternalAcquirerConnector {
    private static final Logger log = LoggerFactory.getLogger(ExternalAcquirerConnector.class);

    public AcquirerResponse routeToNetwork(String txnId, PaymentRequest request) {
        log.info("Routing settlement for txn {} to Clearing Network", txnId);

        // Simulating network latency
        try { Thread.sleep(80); } catch (InterruptedException ignored) {}

        // Simulating potential card network decline (e.g., Insufficient Funds)
        if (request.amount().compareTo(new BigDecimal("10000.00")) > 0) {
            return new AcquirerResponse(false, "INSUFFICIENT_FUNDS");
        }

        return new AcquirerResponse(true, "00_APPROVED");
    }
}

// =========================================================================
// 5. REST CONTROLLER & EXCEPTION HANDLING (API Layer)
// =========================================================================

@RestController
@RequestMapping("/api/v1/payments")
class PaymentController {

    private final PaymentService paymentService = new PaymentServiceImpl();

    @PostMapping("/charge")
    public ResponseEntity<PaymentResponse> charge(@Valid @RequestBody PaymentRequest request) {
        PaymentResponse response = paymentService.processPayment(request);

        if (response.status() == PaymentStatus.SUCCESS) {
            return ResponseEntity.status(HttpStatus.CREATED).body(response);
        } else if (response.status() == PaymentStatus.DECLINED) {
            return ResponseEntity.status(HttpStatus.UNPROCESSABLE_ENTITY).body(response);
        } else {
            return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR).body(response);
        }
    }
}
```

### Key Architectural Highlights of this Code:

1. **Strict Thread Safety (`IdempotencyRegistry`)**: Uses a `ConcurrentHashMap` and thread-safe logic blocks to ensure that high volumes of parallel execution do not cause race conditions.
2. **Strict Idempotency**: If a network timeout occurs and a client resubmits the exact same transaction (using the `idempotencyKey`), the system immediately detects it and returns the cached result rather than hitting the database or the external acquirer twice.
3. **Log Sanitization (PCI-DSS compliance)**: The `PaymentRequest` class overrides `toString()` to mask sensitive details (e.g., masking bank accounts or source tokens to look like `****-1234`). This prevents developers from accidentally saving raw card numbers/tokens into application log files.
4. **Input Sanitization**: JSR-380 validation (`@NotBlank`, `@DecimalMin`, `@Size`) is enforced at the controller level to prevent injection attacks and illegal states (such as processing a charge of `$0.00` or negative values).
5. **Decoupled Failure Management**: System errors (unexpected runtime crashes) are caught, logged internally with full stack traces, and translated to a clean, non-revealing error code (`SYSTEM_ERROR`) for the end user to prevent leakage of the database structure.

