```java
package com.institution.payment.service;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.institution.payment.dto.PaymentRequest;
import com.institution.payment.dto.PaymentResponse;
import com.institution.payment.model.*;
import com.institution.payment.repository.*;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Isolation;
import org.springframework.transaction.annotation.Transactional;

import java.time.Instant;
import java.util.Optional;

@Service
@RequiredArgsConstructor
@Slf4j
public class PaymentService {

    private final AccountRepository accountRepository;
    private final TransactionRepository transactionRepository;
    private final IdempotencyRepository idempotencyRepository;
    private final ObjectMapper objectMapper;

    @Transactional(isolation = Isolation.READ_COMMITTED)
    public PaymentResponse processPayment(PaymentRequest request) {
        log.info("Processing payment request. Key: {}, From: {}, To: {}, Amount: {}", 
            request.idempotencyKey(), request.sourceAccountId(), request.destinationAccountId(), request.amount());

        // 1. Idempotency Check
        Optional<IdempotentRequest> existingRequest = idempotencyRepository.findById(request.idempotencyKey());
        if (existingRequest.isPresent()) {
            log.warn("Duplicate request detected for key: {}. Returning cached response.", request.idempotencyKey());
            return deserializeResponse(existingRequest.get().getResponseBody());
        }

        // 2. Prevent self-transfer
        if (request.sourceAccountId().equals(request.destinationAccountId())) {
            throw new IllegalArgumentException("Source and destination accounts must be different.");
        }

        try {
            // 3. Acquire locks in deterministic order to prevent deadlocks (Always lock lower account ID first)
            String firstLockId = request.sourceAccountId().compareTo(request.destinationAccountId()) < 0 
                ? request.sourceAccountId() : request.destinationAccountId();
            String secondLockId = firstLockId.equals(request.sourceAccountId()) 
                ? request.destinationAccountId() : request.sourceAccountId();

            Account firstAccount = accountRepository.findByIdForUpdate(firstLockId)
                .orElseThrow(() -> new AccountNotFoundException("Account not found: " + firstLockId));
            Account secondAccount = accountRepository.findByIdForUpdate(secondLockId)
                .orElseThrow(() -> new AccountNotFoundException("Account not found: " + secondLockId));

            Account source = firstAccount.getId().equals(request.sourceAccountId()) ? firstAccount : secondAccount;
            Account destination = source == firstAccount ? secondAccount : firstAccount;

            // 4. Validate Currencies
            if (!source.getCurrency().equals(request.currency()) || !destination.getCurrency().equals(request.currency())) {
                throw new CurrencyMismatchException("Currency mismatch in processing transaction");
            }

            // 5. Debit and Credit
            source.debit(request.amount());
            destination.credit(request.amount());

            // Save accounts
            accountRepository.save(source);
            accountRepository.save(destination);

            // 6. Record transaction ledger
            Transaction transaction = Transaction.builder()
                .idempotencyKey(request.idempotencyKey())
                .sourceAccountId(source.getId())
                .destinationAccountId(destination.getId())
                .amount(request.amount())
                .currency(request.currency())
                .status(Transaction.TransactionStatus.SUCCESS)
                .createdAt(Instant.now())
                .build();

            transactionRepository.save(transaction);

            PaymentResponse response = new PaymentResponse(
                transaction.getId(),
                "APPROVED",
                transaction.getAmount(),
                transaction.getCurrency(),
                transaction.getCreatedAt(),
                "Payment processed successfully."
            );

            // 7. Store response for idempotency
            saveIdempotencyKey(request.idempotencyKey(), response);

            return response;

        } catch (Exception e) {
            log.error("Payment failed for key: {}. Error: {}", request.idempotencyKey(), e.getMessage());
            // Record failed transaction for auditing
            recordFailedTransaction(request);
            throw e; 
        }
    }

    private void saveIdempotencyKey(String key, PaymentResponse response) {
        try {
            String jsonResponse = objectMapper.writeValueAsString(response);
            idempotencyRepository.save(new IdempotentRequest(key, jsonResponse, Instant.now()));
        } catch (Exception e) {
            log.error("Failed to save idempotency key metadata", e);
        }
    }

    private PaymentResponse deserializeResponse(String json) {
        try {
            return objectMapper.readValue(json, PaymentResponse.class);
        } catch (Exception e) {
            throw new RuntimeException("Error parsing cached transaction response", e);
        }
    }

    private void recordFailedTransaction(PaymentRequest request) {
        try {
            transactionRepository.save(Transaction.builder()
                .idempotencyKey(request.idempotencyKey())
                .sourceAccountId(request.sourceAccountId())
                .destinationAccountId(request.destinationAccountId())
                .amount(request.amount())
                .currency(request.currency())
                .status(Transaction.TransactionStatus.FAILED)
                .createdAt(Instant.now())
                .build());
        } catch (Exception e) {
            log.error("Could not write failed transaction audit ledger", e);
        }
    }
}
