```go
package main

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"log"
	"net/http"
	"os"
	"os/signal"
	"regexp"
	"strings"
	"sync"
	"syscall"
	"time"
)

// =========================================================================
// DOMAIN MODELS & TYPES
// =========================================================================

type TransactionStatus string

const (
	StatusSuccess TransactionStatus = "SUCCESS"
	StatusFailed  TransactionStatus = "FAILED"
)

// PaymentRequest represents the incoming API payload.
type PaymentRequest struct {
	SourceAccount string `json:"source_account"`
	TargetAccount string `json:"target_account"`
	Amount        int64  `json:"amount"`   // Represented in minor units (e.g., cents: $10.00 = 1000)
	Currency      string `json:"currency"` // ISO 4217 code (e.g., "USD")
}

// PaymentResponse represents the API response.
type PaymentResponse struct {
	TransactionID string            `json:"transaction_id"`
	Status        TransactionStatus `json:"status"`
	Amount        int64             `json:"amount"`
	Currency      string            `json:"currency"`
	Timestamp     time.Time         `json:"timestamp"`
	ErrorMessage  string            `json:"error_message,omitempty"`
}

// Account represents a bank account in our system.
type Account struct {
	ID       string
	Balance  int64
	Currency string
	Mu       sync.Mutex // Fine-grained lock per account
}

// =========================================================================
// DATABASE & IDEMPOTENCY STORE (Mock implementations)
// =========================================================================

type Ledger struct {
	accounts map[string]*Account
	mu       sync.RWMutex
}

type IdempotencyStore struct {
	cache map[string]*PaymentResponse
	mu    sync.RWMutex
}

var db = &Ledger{
	accounts: map[string]*Account{
		"ACC-12345-US": {ID: "ACC-12345-US", Balance: 500000, Currency: "USD"}, // $5,000.00
		"ACC-67890-US": {ID: "ACC-67890-US", Balance: 100000, Currency: "USD"}, // $1,000.00
	},
}

var idempotencyCache = &IdempotencyStore{
	cache: make(map[string]*PaymentResponse),
}

// =========================================================================
// BUSINESS LOGIC (Payment Service)
// =========================================================================

type PaymentService struct{}

func (s *PaymentService) ProcessTransfer(ctx context.Context, req *PaymentRequest) (*PaymentResponse, error) {
	// 1. Retrieve accounts
	db.mu.RLock()
	source, okSrc := db.accounts[req.SourceAccount]
	target, okTar := db.accounts[req.TargetAccount]
	db.mu.RUnlock()

	if !okSrc || !okTar {
		return nil, errors.New("one or both accounts do not exist")
	}

	if source.Currency != req.Currency || target.Currency != req.Currency {
		return nil, errors.New("currency mismatch across transaction entities")
	}

	// 2. Lock accounts to prevent race conditions and deadlocks.
	// Always lock the account with the lexicographically smaller ID first.
	if source.ID < target.ID {
		source.Mu.Lock()
		target.Mu.Lock()
		defer target.Mu.Unlock()
		defer source.Mu.Unlock()
	} else {
		target.Mu.Lock()
		source.Mu.Lock()
		defer source.Mu.Unlock()
		defer target.Mu.Unlock()
	}

	// 3. Business Rules Validation
	if source.Balance < req.Amount {
		return nil, errors.New("insufficient funds")
	}

	// 4. Execute atomic transfer (Debit/Credit)
	source.Balance -= req.Amount
	target.Balance += req.Amount

	txID := fmt.Sprintf("TX-%d", time.Now().UnixNano())
	log.Printf("[AUDIT] Successfully moved %d %s from %s to %s. TxID: %s",
		req.Amount, req.Currency, maskAccount(source.ID), maskAccount(target.ID), txID)

	return &PaymentResponse{
		TransactionID: txID,
		Status:        StatusSuccess,
		Amount:        req.Amount,
		Currency:      req.Currency,
		Timestamp:     time.Now().UTC(),
	}, nil
}

// =========================================================================
// API CONTROLLER / HANDLERS
// =========================================================================

type PaymentHandler struct {
	service *PaymentService
}

func (h *PaymentHandler) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")

	if r.Method != http.MethodPost {
		http.Error(w, `{"error": "Method not allowed"}`, http.StatusMethodNotAllowed)
		return
	}

	// 1. Idempotency Check
	idemKey := r.Header.Get("Idempotency-Key")
	if strings.TrimSpace(idemKey) == "" {
		http.Error(w, `{"error": "Idempotency-Key header is required"}`, http.StatusBadRequest)
		return
	}

	idempotencyCache.mu.RLock()
	cachedResponse, exists := idempotencyCache.cache[idemKey]
	idempotencyCache.mu.RUnlock()

	if exists {
		log.Printf("[INFO] Returning cached response for Idempotency-Key: %s", idemKey)
		w.WriteHeader(http.StatusOK)
		json.NewEncoder(w).Encode(cachedResponse)
		return
	}

	// 2. Decode & Validate Request
	var req PaymentRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, `{"error": "Malformed JSON payload"}`, http.StatusBadRequest)
		return
	}

	if err := validateRequest(&req); err != nil {
		http.Error(w, fmt.Sprintf(`{"error": "%s"}`, err.Error()), http.StatusUnprocessableEntity)
		return
	}

	// 3. Process Payment with context timeout (SLA protection)
	ctx, cancel := context.WithTimeout(r.Context(), 2500*time.Millisecond)
	defer cancel()

	resp, err := h.service.ProcessTransfer(ctx, &req)
	if err != nil {
		log.Printf("[ERROR] Transfer failed: %s", err.Error())
		failResp := &PaymentResponse{
			Status:       StatusFailed,
			ErrorMessage: err.Error(),
			Timestamp:    time.Now().UTC(),
		}
		w.WriteHeader(http.StatusPaymentRequired)
		json.NewEncoder(w).Encode(failResp)
		return
	}

	// 4. Save to Idempotency Store before responding
	idempotencyCache.mu.Lock()
	idempotencyCache.cache[idemKey] = resp
	idempotencyCache.mu.Unlock()

	w.WriteHeader(http.StatusOK)
	json.NewEncoder(w).Encode(resp)
}

// =========================================================================
// UTILITY FUNCTIONS & SECURITY
// =========================================================================

func validateRequest(req *PaymentRequest) error {
	if req.SourceAccount == "" || req.TargetAccount == "" {
		return errors.New("source and target accounts are required")
	}
	if req.SourceAccount == req.TargetAccount {
		return errors.New("source and target accounts must be different")
	}
	if req.Amount <= 0 {
		return errors.New("payment amount must be greater than zero")
	}
	if len(req.Currency) != 3 {
		return errors.New("currency must be a valid 3-letter ISO code")
	}
	return nil
}

// maskAccount obscures sensitive account data in logs to preserve PCI compliance
func maskAccount(accNum string) string {
	reg := regexp.MustCompile(`^ACC-(\d+)-(\w+)$`)
	if !reg.MatchString(accNum) {
		return "ACC-XXXXX"
	}
	matches := reg.FindStringSubmatch(accNum)
	digits := matches[1]
	currency := matches[2]
	if len(digits) > 4 {
		return fmt.Sprintf("ACC-***%s-%s", digits[len(digits)-4:], currency)
	}
	return "ACC-***-" + currency
}

// =========================================================================
// MAIN RUNTIME & GRACEFUL SHUTDOWN
// =========================================================================

func main() {
	mux := http.NewServeMux()
	handler := &PaymentHandler{service: &PaymentService{}}
	mux.Handle("/v1/payments", handler)

	server := &http.Server{
		Addr:         ":8080",
		Handler:      mux,
		ReadTimeout:  5 * time.Second,
		WriteTimeout: 10 * time.Second,
		IdleTimeout:  120 * time.Second,
	}

	// Run server in a goroutine
	go func() {
		log.Printf("[INFO] Payment processing engine running on port %s...", server.Addr)
		if err := server.ListenAndServe(); err != nil && err != http.ErrServerClosed {
			log.Fatalf("[CRITICAL] Server failed: %s", err)
		}
	}()

	// Listen for OS signals to execute a graceful shutdown
	stop := make(chan os.Signal, 1)
	signal.Notify(stop, os.Interrupt, syscall.SIGTERM)
	<-stop

	log.Println("[INFO] Shutting down payment engine gracefully...")
	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()

	if err := server.Shutdown(ctx); err != nil {
		log.Fatalf("[CRITICAL] Graceful shutdown failed: %s", err)
	}
	log.Println("[INFO] Server stopped safely.")
}
