package com.institution.payment;

import java.math.BigDecimal;
import java.time.Instant;
import java.util.Map;
import java.util.Objects;
import java.util.UUID;
import java.util.concurrent.*;
import java.util.concurrent.locks.ReentrantLock;
import java.util.logging.Logger;

public class PaymentProcessingSystem {

    private static final Logger logger = Logger.getLogger(PaymentProcessingSystem.class.getName());

    // --- DOMAIN MODELS ---

    public record PaymentRequest(
        String idempotencyKey,
        String sourceAccountId,
        String destinationAccountId,
        BigDecimal amount,
        String currency,
        String sensitiveCardPan // Primary Account Number (To be masked in logs)
    ) {
        public PaymentRequest {
            Objects.requireNonNull(idempotencyKey, "Idempotency key required");
            Objects.requireNonNull(sourceAccountId, "Source account required");
            Objects.requireNonNull(destinationAccountId, "Destination account required");
            Objects.requireNonNull(amount, "Amount required");
            if (amount.compareTo(BigDecimal.ZERO) <= 0) {
                throw new IllegalArgumentException("Amount must be positive");
            }
        }

        // PCI-DSS Compliance: Mask sensitive data before logging
        public String maskedPan() {
            if (sensitiveCardPan == null || sensitiveCardPan.length() < 4) return "****";
            return "****-****-****-" + sensitiveCardPan.substring(sensitiveCardPan.length() - 4);
        }
    }

    public enum TransactionStatus { SUCCESS, FAILED, PENDING }

    public record PaymentResponse(
        String transactionId,
        String idempotencyKey,
        TransactionStatus status,
        String errorCode,
        Instant timestamp
    ) {}

    public static class Account {
        private final String id;
        private BigDecimal balance;
        private final ReentrantLock lock = new ReentrantLock();

        public Account(String id, BigDecimal initialBalance) {
            this.id = id;
            this.balance = initialBalance;
        }

        public String getId() { return id; }
        public BigDecimal getBalance() { return balance; }
        public ReentrantLock getLock() { return lock; }

        public void debit(BigDecimal amount) {
            this.balance = this.balance.subtract(amount);
        }

        public void credit(BigDecimal amount) {
            this.balance = this.balance.add(amount);
        }
    }

    // --- CORE SERVICES ---

    /**
     * Ensures strict ACID compliance for ledger updates.
     */
    public static class LedgerService {
        private final Map<String, Account> accounts = new ConcurrentHashMap<>();

        public void addAccount(Account account) {
            accounts.put(account.getId(), account);
        }

        public Account getAccount(String id) {
            return accounts.get(id);
        }

        /**
         * Executes a dual-entry transfer. 
         * Uses ordered locking to prevent deadlocks under high concurrent loads.
         */
        public void transfer(String fromId, String toId, BigDecimal amount) throws Exception {
            Account from = accounts.get(fromId);
            Account to = accounts.get(toId);

            if (from == null || to == null) {
                throw new IllegalArgumentException("Invalid account details");
            }

            // Deadlock Prevention: Always acquire locks in a deterministic order (by hashcode/ID)
            Account firstLock = from.getId().compareTo(to.getId()) < 0 ? from : to;
            Account secondLock = firstLock == from ? to : from;

            firstLock.getLock().lock();
            try {
                secondLock.getLock().lock();
                try {
                    if (from.getBalance().compareTo(amount) < 0) {
                        throw new InsufficientFundsException("Insufficient funds in source account");
                    }
                    from.debit(amount);
                    to.credit(amount);
                } finally {
                    secondLock.getLock().unlock();
                }
            } finally {
                firstLock.getLock().unlock();
            }
        }
    }

    /**
     * Prevents double-charging by caching transaction results by Idempotency Key.
     */
    public static class IdempotencyManager {
        private final Map<String, PaymentResponse> cache = new ConcurrentHashMap<>();

        public PaymentResponse get(String key) {
            return cache.get(key);
        }

        public void save(String key, PaymentResponse response) {
            cache.put(key, response);
        }
    }

    /**
     * Orchestrates the payment flow.
     */
    public static class PaymentProcessor {
        private final LedgerService ledger;
        private final IdempotencyManager idempotency;

        public PaymentProcessor(LedgerService ledger, IdempotencyManager idempotency) {
            this.ledger = ledger;
            this.idempotency = idempotency;
        }

        public PaymentResponse process(PaymentRequest request) {
            logger.info(() -> String.format("Processing payment for request key [%s]. Card PAN: %s", 
                request.idempotencyKey(), request.maskedPan()));

            // 1. Idempotency Check
            PaymentResponse cachedResponse = idempotency.get(request.idempotencyKey());
            if (cachedResponse != null) {
                logger.warning(() -> "Duplicate transaction detected. Returning cached response for key: " + request.idempotencyKey());
                return cachedResponse;
            }

            String transactionId = UUID.randomUUID().toString();
            PaymentResponse response;

            try {
                // 2. Perform Atomic Ledger Transfer
                ledger.transfer(request.sourceAccountId(), request.destinationAccountId(), request.amount());

                response = new PaymentResponse(
                    transactionId,
                    request.idempotencyKey(),
                    TransactionStatus.SUCCESS,
                    null,
                    Instant.now()
                );
                logger.info(() -> "Payment successful. Txn ID: " + transactionId);

            } catch (InsufficientFundsException e) {
                logger.severe(() -> "Declined: Insufficient funds for txn key " + request.idempotencyKey());
                response = new PaymentResponse(transactionId, request.idempotencyKey(), TransactionStatus.FAILED, "INSUFFICIENT_FUNDS", Instant.now());
            } catch (Exception e) {
                logger.severe(() -> "System error during processing: " + e.getMessage());
                response = new PaymentResponse(transactionId, request.idempotencyKey(), TransactionStatus.FAILED, "SYSTEM_ERROR", Instant.now());
            }

            // 3. Save state to ensure future retries get the exact same response
            idempotency.save(request.idempotencyKey(), response);
            return response;
        }
    }

    // --- Custom Exceptions ---
    public static class InsufficientFundsException extends Exception {
        public InsufficientFundsException(String message) { super(message); }
    }

    // --- DEMONSTRATION HARNESS ---
    public static void main(String[] args) throws InterruptedException {
        LedgerService ledger = new LedgerService();
        IdempotencyManager idempotency = new IdempotencyManager();
        PaymentProcessor processor = new PaymentProcessor(ledger, idempotency);

        // Initialize Accounts
        Account accAlice = new Account("ACC-ALICE-123", new BigDecimal("1000.00"));
        Account accBob = new Account("ACC-BOB-456", new BigDecimal("500.00"));
        ledger.addAccount(accAlice);
        ledger.addAccount(accBob);

        // Setup high-concurrency simulation (using virtual-thread-like thread pool)
        ExecutorService executor = Executors.newFixedThreadPool(4);

        String sharedIdempotencyKey = "IDEM-KEY-77777";

        // 1. Simulate duplicate concurrent requests hitting the server at the exact same time
        PaymentRequest request1 = new PaymentRequest(sharedIdempotencyKey, "ACC-ALICE-123", "ACC-BOB-456", new BigDecimal("100.00"), "USD", "4111222233334444");
        PaymentRequest request2 = new PaymentRequest(sharedIdempotencyKey, "ACC-ALICE-123", "ACC-BOB-456", new BigDecimal("100.00"), "USD", "4111222233334444");

        logger.info("--- Initiating Concurrent Processing Test ---");
        executor.submit(() -> processor.process(request1));
        executor.submit(() -> processor.process(request2));

        executor.shutdown();
        executor.awaitTermination(2, TimeUnit.SECONDS);

        // Print final safe ledger states
        logger.info("--- Final Account Balances ---");
        logger.info("Alice Balance (Expected 900.00): $" + ledger.getAccount("ACC-ALICE-123").getBalance());
        logger.info("Bob Balance (Expected 600.00): $" + ledger.getAccount("ACC-BOB-456").getBalance());
    }
}
