### 4. Core Payment Service (The Engine)
This is where **ACID transactions** and **Idempotency** are strictly enforced. To prevent race conditions, database constraints are paired with pessimistic locking or transactional state checks.

```java
package com.institution.payment.service;

import com.institution.payment.client.PaymentGatewayClient;
import com.institution.payment.dto.PaymentRequest;
import com.institution.payment.dto.PaymentResponse;
import com.institution.payment.entity.Payment;
import com.institution.payment.entity.PaymentStatus;
import com.institution.payment.repository.PaymentRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.Optional;

@Slf4j
@Service
@RequiredArgsConstructor
public class PaymentService {

    private final PaymentRepository paymentRepository;
    private final PaymentGatewayClient gatewayClient;

    @Transactional
    public PaymentResponse processPayment(PaymentRequest request) {
        log.info("Processing payment request. Idempotency Key: {}", request.getIdempotencyKey());

        // 1. Idempotency Check (ACID compliant lookup)
        Optional<Payment> existingPayment = paymentRepository.findByIdempotencyKey(request.getIdempotencyKey());
        if (existingPayment.isPresent()) {
            log.warn("Duplicate request detected for idempotency key: {}", request.getIdempotencyKey());
            return mapToResponse(existingPayment.get());
        }

        // 2. Prepare Ledger Entry in PENDING status
        String maskedPan = maskCardNumber(request.getCardNumber());
        Payment payment = Payment.builder()
                .idempotencyKey(request.getIdempotencyKey())
                .amount(request.getAmount())
                .currency(request.getCurrency())
                .maskedPan(maskedPan)
                .status(PaymentStatus.PENDING)
                .build();

        // Save immediately to reserve the idempotency key lock in the database
        payment = paymentRepository.saveAndFlush(payment);

        try {
            // 3. Dispatch to External Acquiring Processor / Card Network
            log.info("Dispatching transaction to acquirer network...");
            PaymentGatewayClient.GatewayResult gatewayResult = gatewayClient.authorizeAndCapture(request);

            // 4. Handle Gateway Outcomes
            if (gatewayResult.isSuccess()) {
                payment.setStatus(PaymentStatus.SUCCESS);
                payment.setGatewayTransactionId(gatewayResult.getTransactionId());
                log.info("Payment SUCCESS. Transaction ID: {}", gatewayResult.getTransactionId());
            } else {
                payment.setStatus(PaymentStatus.FAILED);
                payment.setFailureReason(gatewayResult.getErrorMessage());
                log.warn("Payment FAILED. Reason: {}", gatewayResult.getErrorMessage());
            }
        } catch (Exception e) {
            log.error("System error communicating with Payment Gateway", e);
            payment.setStatus(PaymentStatus.FAILED);
            payment.setFailureReason("SYSTEM_TIMEOUT_OR_NETWORK_FAILURE");
            // In production, you would queue this for a 'reconciliation check' pattern instead of immediate failure
        }

        // 5. Update and Commit Transaction
        Payment savedPayment = paymentRepository.save(payment);
        return mapToResponse(savedPayment);
    }

    private String maskCardNumber(String rawCardNumber) {
        if (rawCardNumber == null || rawCardNumber.length() < 10) {
            return "************";
        }
        // Mask middle digits: 4111111111111111 -> 411111******1111
        return rawCardNumber.substring(0, 6) 
                + "*".repeat(rawCardNumber.length() - 10) 
                + rawCardNumber.substring(rawCardNumber.length() - 4);
    }

    private PaymentResponse mapToResponse(Payment payment) {
        return PaymentResponse.builder()
                .paymentId(payment.getId())
                .status(payment.getStatus().name())
                .amount(payment.getAmount())
                .currency(payment.getCurrency())
                .gatewayTransactionId(payment.getGatewayTransactionId())
                .failureReason(payment.getFailureReason())
                .createdAt(payment.getCreatedAt())
                .build();
    }
}
