// 1. DOMAIN MODELS & ENUMS
// ==========================================

enum PaymentStatus {
    PENDING, SUCCESS, FAILED, REJECTED
}

/**
 * Representing an incoming payment request.
 * Implements Immutable Pattern for thread-safety.
 */
record PaymentRequest(
    String idempotencyKey,
    BigDecimal amount,
    String currencyCode,
    String sourceAccountId,
    String destinationAccountId,
    String rawCardNumber // Sensitive data
) {
    public PaymentRequest {
        Objects.requireNonNull(idempotencyKey, "Idempotency key is required");
        Objects.requireNonNull(amount, "Amount is required");
        Objects.requireNonNull(currencyCode, "Currency is required");
        Objects.requireNonNull(sourceAccountId, "Source account is required");
        Objects.requireNonNull(destinationAccountId, "Destination account is required");
    }

    // Masks sensitive PAN data for logging (PCI-DSS compliance)
    public String maskedCardNumber() {
        if (rawCardNumber == null || rawCardNumber.length() < 4) return "INVALID";
        return "****-****-****-" + rawCardNumber.substring(rawCardNumber.length() - 4);
    }
}

/**
 * Immutable Payment Response representing the finalized transaction receipt.
 */
record PaymentResponse(
    String transactionId,
    String idempotencyKey,
    PaymentStatus status,
    BigDecimal amount,
    String currency,
    Instant timestamp,
    String errorCode,
    String errorMessage
) {
    public static PaymentResponse success(String transactionId, PaymentRequest request) {
        return new PaymentResponse(transactionId, request.idempotencyKey(), PaymentStatus.SUCCESS, 
                request.amount(), request.currencyCode(), Instant.now(), null, null);
    }

    public static PaymentResponse fail(String transactionId, PaymentRequest request, String errorCode, String errorMessage) {
        return new PaymentResponse(transactionId, request.idempotencyKey(), PaymentStatus.FAILED, 
                request.amount(), request.currencyCode(), Instant.now(), errorCode, errorMessage);
    }

    public static PaymentResponse reject(PaymentRequest request, String errorCode, String errorMessage) {
        return new PaymentResponse(null, request.idempotencyKey(), PaymentStatus.REJECTED, 
                request.amount(), request.currencyCode(), Instant.now(), errorCode, errorMessage);
    }
}

// ==========================================
// 2. CORE PAYMENT SERVICE IMPLEMENTATION
// ==========================================

class PaymentProcessorService {
    private static final Logger LOGGER = Logger.getLogger(PaymentProcessorService.class.getName());

    // In-memory simulators representing transactional databases (PostgreSQL/Oracle in production)
    private final Map<String, PaymentResponse> idempotencyStore = new ConcurrentHashMap<>();
    private final Map<String, PaymentResponse> transactionLedger = new ConcurrentHashMap<>();

    private static final Pattern CARD_PATTERN = Pattern.compile("^\\d{16}$");

    /**
     * Entrypoint for processing payments. Guaranteed to be idempotent and thread-safe.
     */
    public PaymentResponse processPayment(PaymentRequest request) {
        LOGGER.info(() -> String.format("[IDEMPOTENCY START] Checking key: %s for amount: %s", 
                request.idempotencyKey(), request.amount()));

        // 1. Enforce Idempotency (Strict double-charge prevention)
        if (idempotencyStore.containsKey(request.idempotencyKey())) {
            LOGGER.warning(() -> String.format("[IDEMPOTENCY HIT] Duplicate transaction blocked for key: %s", request.idempotencyKey()));
            return idempotencyStore.get(request.idempotencyKey());
        }

        // 2. Strict Payload Validation
        try {
            validateRequest(request);
        } catch (IllegalArgumentException e) {
            LOGGER.severe(() -> String.format("[VALIDATION FAILED] Key: %s. Reason: %s", request.idempotencyKey(), e.getMessage()));
            PaymentResponse rejectResponse = PaymentResponse.reject(request, "VAL_ERR_01", e.getMessage());
            idempotencyStore.put(request.idempotencyKey(), rejectResponse);
            return rejectResponse;
        }

        String transactionId = "TXN-" + UUID.randomUUID().toString().substring(0, 8).toUpperCase();
        LOGGER.info(() -> String.format("[PROCESSING] Auth initialised for Txn ID: %s, Card: %s", transactionId, request.maskedCardNumber()));

        // 3. Process Transaction (Simulating Ledger Updates/External Gateway Auth)
        PaymentResponse finalResponse = executeTransaction(transactionId, request);

        // 4. Atomic Persistence to Ledger & Idempotency Store
        transactionLedger.put(transactionId, finalResponse);
        idempotencyStore.put(request.idempotencyKey(), finalResponse);

        LOGGER.info(() -> String.format("[COMPLETED] Txn ID: %s finished with status: %s", transactionId, finalResponse.status()));
        return finalResponse;
    }

    private void validateRequest(PaymentRequest request) {
        if (request.amount().compareTo(BigDecimal.ZERO) <= 0) {
            throw new IllegalArgumentException("Transaction amount must be positive and greater than zero.");
        }
        try {
            Currency.getInstance(request.currencyCode());
        } catch (IllegalArgumentException e) {
            throw new IllegalArgumentException("Invalid ISO 4217 currency code.");
        }
        if (request.rawCardNumber() == null || !CARD_PATTERN.matcher(request.rawCardNumber()).matches()) {
            throw new IllegalArgumentException("PCI Compliance Failure: Invalid Card Format.");
        }
    }

    private PaymentResponse executeTransaction(String transactionId, PaymentRequest request) {
        // Simulating banking ledger logic (e.g., checking credit limits or simulating network timeouts)
        try {
            // Artificial latency mimicking connection to external clearing network (VISA/Mastercard network)
            Thread.sleep(150); 
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            return PaymentResponse.fail(transactionId, request, "SYS_ERR_500", "Internal processing interrupted.");
        }

        // Simulating a decline scenario for test purposes
        if (request.amount().compareTo(new BigDecimal("10000.00")) > 0) {
            return PaymentResponse.fail(transactionId, request, "LIMIT_EXCEEDED", "Transaction exceeds maximum transaction threshold.");
        }

        return PaymentResponse.success(transactionId, request);
    }
}

