package com.institution.payment;

import java.math.BigDecimal;
import java.time.Instant;
import java.util.Currency;
import java.util.Map;
import java.util.Optional;
import java.util.UUID;
import java.util.concurrent.*;
import java.util.logging.Logger;
import java.util.regex.Pattern;

// ============================================================================
// 1. DOMAIN MODELS & VALUE OBJECTS
// ============================================================================

enum PaymentStatus {
    PENDING, SUCCESS, FAILED, REVERSED
}

record CardDetails(String holderName, String pan, String expiry, String cvv) {
    // Mask PAN to maintain PCI-DSS compliance in memory/logs
    public String maskedPan() {
        if (pan == null || pan.length() < 10) return "****";
        return pan.substring(0, 6) + "******" + pan.substring(pan.length() - 4);
    }
}

record PaymentRequest(
    String idempotencyKey,
    BigDecimal amount,
    String currencyCode,
    String sourceAccountId,
    String targetAccountId,
    CardDetails cardDetails
) {}

record PaymentResponse(
    String transactionId,
    PaymentStatus status,
    String errorCode,
    String message,
    Instant timestamp
) {}

class TransactionRecord {
    private final String id;
    private final PaymentRequest request;
    private PaymentStatus status;
    private String failureReason;
    private final Instant createdAt;

    public TransactionRecord(String id, PaymentRequest request) {
        this.id = id;
        this.request = request;
        this.status = PaymentStatus.PENDING;
        this.createdAt = Instant.now();
    }

    public synchronized void transitionTo(PaymentStatus newStatus, String reason) {
        // Enforce valid state machine transitions
        if (this.status == PaymentStatus.SUCCESS || this.status == PaymentStatus.FAILED) {
            throw new IllegalStateException("Cannot transition from terminal state: " + this.status);
        }
        this.status = newStatus;
        this.failureReason = reason;
    }

    public String getId() { return id; }
    public PaymentRequest getRequest() { return request; }
    public synchronized PaymentStatus getStatus() { return status; }
    public synchronized String getFailureReason() { return failureReason; }
    public Instant getCreatedAt() { return createdAt; }
}

// ============================================================================
// 2. EXCEPTIONS
// ============================================================================
class PaymentValidationException extends Exception { public PaymentValidationException(String msg) { super(msg); }}
class LedgerException extends Exception { public LedgerException(String msg) { super(msg); }}
class AcquirerException extends Exception { public AcquirerException(String msg) { super(msg); }}

// ============================================================================
// 3. CORE SERVICES
// ============================================================================

/**
 * Simulates the Core Banking Ledger where customer account balances are held.
 * In a real environment, this would execute atomic database transactions.
 */
class LedgerService {
    private static final Logger LOGGER = Logger.getLogger(LedgerService.class.getName());

    public void reserveFunds(String accountId, BigDecimal amount, String currency, String txId) throws LedgerException {
        LOGGER.info(String.format("[Ledger] Reserving %s %s from account %s for Tx: %s", amount, currency, accountId, txId));
        // Simulate database lookup & balance check
        if (amount.compareTo(new BigDecimal("10000.00")) > 0) {
            throw new LedgerException("Insufficient funds / transaction limit exceeded");
        }
    }

    public void commitFunds(String txId) {
        LOGGER.info(String.format("[Ledger] Successfully committed funds for Tx: %s", txId));
    }

    public void releaseReservation(String txId, String reason) {
        LOGGER.warning(String.format("[Ledger] Releasing reservation for Tx: %s. Reason: %s", txId, reason));
    }
}

/**
 * Simulates integration with card networks (Visa/Mastercard/Amex) via an Acquirer.
 */
class AcquirerGateway {
    private static final Logger LOGGER = Logger.getLogger(AcquirerGateway.class.getName());

    public void processCardPayment(CardDetails card, BigDecimal amount, String currency, String txId) throws AcquirerException {
        LOGGER.info(String.format("[Acquirer] Routing card payment to Network. Card: %s, Tx: %s", card.maskedPan(), txId));

        // Simulate network latency
        try { Thread.sleep(100); } catch (InterruptedException ignored) {}

        // Simulate credit card fraud detection trigger
        if ("1234123412341234".equals(card.pan())) {
            throw new AcquirerException("DECLINED: Suspected Fraudulent Card Pattern");
        }
    }
}

