// 4. MAIN ORCHESTRATION SERVICE
// ============================================================================
class PaymentProcessingService {
    private static final Logger LOGGER = Logger.getLogger(PaymentProcessingService.class.getName());

    private final LedgerService ledgerService = new LedgerService();
    private final AcquirerGateway acquirerGateway = new AcquirerGateway();

    // Thread-safe in-memory datastores acting as the Database layer
    private final Map<String, PaymentResponse> idempotencyStore = new ConcurrentHashMap<>();
    private final Map<String, TransactionRecord> transactionDb = new ConcurrentHashMap<>();

    public PaymentResponse processPayment(PaymentRequest request) {
        String key = request.idempotencyKey();

        // 1. Strict Idempotency Check
        if (idempotencyStore.containsKey(key)) {
            LOGGER.warning("[Security] Duplicate transaction attempt detected for key: " + key);
            return idempotencyStore.get(key);
        }

        String transactionId = "TXN-" + UUID.randomUUID().toString();
        TransactionRecord transaction = new TransactionRecord(transactionId, request);
        transactionDb.put(transactionId, transaction);

        PaymentResponse response;
        try {
            // 2. Validation Stage
            validateRequest(request);

            // 3. Ledger Step (Reserve funds)
            ledgerService.reserveFunds(
                request.sourceAccountId(), request.amount(), request.currencyCode(), transactionId
            );

            try {
                // 4. External Card Network Authorization Step
                acquirerGateway.processCardPayment(
                    request.cardDetails(), request.amount(), request.currencyCode(), transactionId
                );

                // 5. Success Path: Commit transactions
                ledgerService.commitFunds(transactionId);
                transaction.transitionTo(PaymentStatus.SUCCESS, "Settled successfully");

                response = new PaymentResponse(transactionId, PaymentStatus.SUCCESS, null, "Approved", Instant.now());

            } catch (AcquirerException e) {
                // Fail Path: Rollback reserved ledger funds
                ledgerService.releaseReservation(transactionId, e.getMessage());
                transaction.transitionTo(PaymentStatus.FAILED, e.getMessage());

                response = new PaymentResponse(transactionId, PaymentStatus.FAILED, "ACQUIRER_DECLINE", e.getMessage(), Instant.now());
            }

        } catch (PaymentValidationException e) {
            LOGGER.severe("[Validation Failed] " + e.getMessage());
            transaction.transitionTo(PaymentStatus.FAILED, e.getMessage());
            response = new PaymentResponse(transactionId, PaymentStatus.FAILED, "VALIDATION_ERROR", e.getMessage(), Instant.now());

        } catch (LedgerException e) {
            LOGGER.severe("[Ledger Reservation Failed] Tx: " + transactionId + " - Error: " + e.getMessage());
            transaction.transitionTo(PaymentStatus.FAILED, e.getMessage());
            response = new PaymentResponse(transactionId, PaymentStatus.FAILED, "LEDGER_ERROR", e.getMessage(), Instant.now());
        }

        // Cache the result to guarantee idempotency on subsequent retries
        idempotencyStore.put(key, response);
        return response;
    }

    private void validateRequest(PaymentRequest request) throws PaymentValidationException {
        if (request.idempotencyKey() == null || request.idempotencyKey().isBlank()) {
            throw new PaymentValidationException("Missing Idempotency Key");
        }
        if (request.amount() == null || request.amount().compareTo(BigDecimal.ZERO) <= 0) {
            throw new PaymentValidationException("Invalid transaction amount");
        }
        try {
            Currency.getInstance(request.currencyCode());
        } catch (IllegalArgumentException e) {
            throw new PaymentValidationException("Invalid ISO 4217 Currency Code");
        }
        if (request.cardDetails() == null || !Pattern.matches("\\d{16}", request.cardDetails().pan())) {
            throw new PaymentValidationException("Invalid primary account number (PAN)");
        }
    }
}

