package com.institution.payment.repository;

import com.institution.payment.model.PaymentResponse;
import java.util.concurrent.ConcurrentHashMap;
import org.springframework.stereotype.Repository;

@Repository
public class PaymentRepository {
    // Stores idempotency keys mapped to their original responses
    private final ConcurrentHashMap<String, PaymentResponse> idempotencyStore = new ConcurrentHashMap<>();
    // Stores transaction history
    private final ConcurrentHashMap<String, PaymentResponse> transactionLedger = new ConcurrentHashMap<>();

    public boolean hasIdempotencyKey(String key) {
        return idempotencyStore.containsKey(key);
    }

    public PaymentResponse getByByIdempotencyKey(String key) {
        return idempotencyStore.get(key);
    }

    public void saveTransaction(String key, String transactionId, PaymentResponse response) {
        idempotencyStore.put(key, response);
        transactionLedger.put(transactionId, response);
    }
}
