#### 4. Payment Processor Engine

This service orchestrates the validation, checks idempotency, communicates with the payment gateway (simulated), and records the transaction ledger.

```java
package com.institution.payment.service;

import com.institution.payment.model.*;
import com.institution.payment.repository.PaymentRepository;
import com.institution.payment.util.SecurityUtils;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Service;

import java.math.BigDecimal;
import java.util.UUID;

@Service
public class PaymentProcessorService {

    private static final Logger logger = LoggerFactory.getLogger(PaymentProcessorService.class);
    private final PaymentRepository paymentRepository;

    public PaymentProcessorService(PaymentRepository paymentRepository) {
        this.paymentRepository = paymentRepository;
    }

    public PaymentResponse processPayment(String idempotencyKey, PaymentRequest request) {
        String maskedCard = SecurityUtils.maskCardNumber(request.cardNumber());
        logger.info("Received payment request. Amount: {} {}, Card: {}, IdempotencyKey: {}", 
                    request.amount(), request.currency(), maskedCard, idempotencyKey);

        // 1. Idempotency Check
        if (paymentRepository.hasIdempotencyKey(idempotencyKey)) {
            logger.warn("Duplicate request detected for IdempotencyKey: {}. Returning cached response.", idempotencyKey);
            return paymentRepository.getByByIdempotencyKey(idempotencyKey);
        }

        // 2. Strict Input Validation
        if (request.amount().compareTo(BigDecimal.ZERO) <= 0) {
            return PaymentResponse.failure("N/A", request.amount(), request.currency(), "VAL_001", "Invalid Transaction Amount");
        }
        if (!isValidCurrency(request.currency())) {
            return PaymentResponse.failure("N/A", request.amount(), request.currency(), "VAL_002", "Unsupported Currency");
        }

        String transactionId = "TXN-" + UUID.randomUUID().toString().substring(0, 8).toUpperCase();

        try {
            // 3. Core Banking/Gateway Execution (Simulated External Card Network Call)
            executeExternalClearing(request, transactionId);

            // 4. Success Execution
            PaymentResponse successResponse = PaymentResponse.success(transactionId, request.amount(), request.currency());
            paymentRepository.saveTransaction(idempotencyKey, transactionId, successResponse);

            logger.info("Payment processed successfully. TxId: {}", transactionId);
            return successResponse;

        } catch (AcquirerException e) {
            // 5. Handled Gateway Failures
            logger.error("Payment failed at acquiring network. TxId: {}. Reason: {}", transactionId, e.getMessage());
            PaymentResponse failedResponse = PaymentResponse.failure(transactionId, request.amount(), request.currency(), e.getErrorCode(), e.getMessage());
            paymentRepository.saveTransaction(idempotencyKey, transactionId, failedResponse);
            return failedResponse;

        } catch (Exception e) {
            // 6. Unexpected System Failures (Default to Pending/Review, never assume failure to prevent loss)
            logger.error("Critical System Error during processing. TxId: {}", transactionId, e);
            return new PaymentResponse(transactionId, PaymentStatus.PENDING, request.amount(), request.currency(), 
                                      java.time.Instant.now(), "SYS_500", "Internal system error. Status is PENDING verification.");
        }
    }

    private boolean isValidCurrency(String currency) {
        return "USD".equalsIgnoreCase(currency) || "EUR".equalsIgnoreCase(currency) || "GBP".equalsIgnoreCase(currency);
    }

    private void executeExternalClearing(PaymentRequest request, String txId) throws AcquirerException {
        // Simulating external network latency
        try { Thread.sleep(150); } catch (InterruptedException ignored) {}

        // Simple simulator based on card numbers
        if (request.cardNumber().startsWith("4111")) {
            // Normal Success Route
            return;
        } else if (request.cardNumber().startsWith("5100")) {
            throw new AcquirerException("DEC_001", "Insufficient Funds");
        } else if (request.cardNumber().startsWith("3700")) {
            throw new AcquirerException("DEC_002", "Suspected Fraud / Card Blocked");
        } else {
            throw new AcquirerException("DEC_999", "Declined by Issuing Bank");
        }
    }
}

class AcquirerException extends Exception {
    private final String errorCode;
    public AcquirerException(String errorCode, String message) {
        super(message);
        this.errorCode = errorCode;
    }
    public String getErrorCode() { return errorCode; }
}
