This layer handles HTTP deserialization, rate limiting (conceptually), and acts as the gatekeeper.

```java
package com.institution.payment.controller;

import com.institution.payment.model.PaymentRequest;
import com.institution.payment.model.PaymentResponse;
import com.institution.payment.service.PaymentProcessorService;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

@RestController
@RequestMapping("/api/v1/payments")
public class PaymentController {

    private final PaymentProcessorService paymentProcessorService;

    public PaymentController(PaymentProcessorService paymentProcessorService) {
        this.paymentProcessorService = paymentProcessorService;
    }

    @PostMapping("/charge")
    public ResponseEntity<PaymentResponse> processCharge(
            @RequestHeader(value = "Idempotency-Key", required = true) String idempotencyKey,
            @RequestBody PaymentRequest request) {

        // Basic validation of Header
        if (idempotencyKey == null || idempotencyKey.trim().isEmpty()) {
            return ResponseEntity.status(HttpStatus.BAD_REQUEST)
                .body(PaymentResponse.failure("N/A", request.amount(), request.currency(), "BAD_HDR", "Missing Idempotency-Key Header"));
        }

        PaymentResponse response = paymentProcessorService.processPayment(idempotencyKey, request);

        if ("SYS_500".equals(response.errorCode())) {
            return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR).body(response);
        }

        return ResponseEntity.ok(response);
    }
}
