### Key Testing Scenarios Handled by this Implementation:

1. **Successful Transaction (Visa Standard Test Card):**
   * **Payload**: Card starting with `4111`, Amount `100.00 USD`, Idempotency Key: `unique-uuid-1`
   * **Result**: `200 OK` with Status `SUCCESS` and generated `transactionId`.

2. **Idempotent Retry:**
   * **Payload**: Retrying the exact same payload with Idempotency Key: `unique-uuid-1`.
   * **Result**: `200 OK` immediate response, returns the exact same `transactionId` without calling the clearing network again.

3. **Insufficient Funds:**
   * **Payload**: Card starting with `5100`.
   * **Result**: `200 OK` with status `FAILED`, error code `DEC_001`, error message `Insufficient Funds`. No money is moved.

4. **Floating Point Safety:**
   * Values like `0.1` and `0.2` will be processed using arbitrary-precision decimals (`BigDecimal`), ensuring no micro-cents are lost or generated during volume transactions.

To demonstrate a minimal working version of a payment processing service suited for a large financial institution, we will use **Go** (our Rank 2 language). 

Go allows us to build a highly concurrent, thread-safe, and low-latency service in a single, readable file. This implementation showcases three non-negotiable patterns for enterprise financial systems:
1.  **Idempotency**: Ensuring a payment request is never processed twice if retried.
2.  **Thread-Safe Ledgers**: Protecting account balances from race conditions.
3.  **Deadlock Prevention**: Locking resources in a deterministic order when transferring money between accounts.

### The Go Implementation (`main.go`)

```go
package main

import (
	"encoding/json"
	"errors"
	"fmt"
	"log"
	"net/http"
	"sync"
	"time"
)

// --- Domain Models ---

type PaymentRequest struct {
	IdempotencyKey string  `json:"idempotency_key"`
	SenderID       string  `json:"sender_id"`
	ReceiverID     string  `json:"receiver_id"`
	Amount         float64 `json:"amount"`
	Currency       string  `json:"currency"`
}

type PaymentResponse struct {
	TransactionID string    `json:"transaction_id"`
	Status        string    `json:"status"`
	Amount        float64   `json:"amount"`
	Currency      string    `json:"currency"`
	Timestamp     time.Time `json:"timestamp"`
	Message       string    `json:"message,omitempty"`
}

type Account struct {
	ID      string
	Balance float64
	Mu      sync.Mutex // Protects individual account balance
}

// --- Payment Processor ---

type PaymentProcessor struct {
	accounts       map[string]*Account
	idempotencyMap map[string]*PaymentResponse
	stateMutex     sync.RWMutex // Protects the maps themselves
}

func NewPaymentProcessor() *PaymentProcessor {
	// Seed with dummy accounts for demonstration
	accounts := map[string]*Account{
		"ACC-1111": {ID: "ACC-1111", Balance: 1000.00},
		"ACC-2222": {ID: "ACC-2222", Balance: 500.00},
	}
	return &PaymentProcessor{
		accounts:       accounts,
		idempotencyMap: make(map[string]*PaymentResponse),
	}
}

// Process handles the core transfer transaction safely
func (p *PaymentProcessor) Process(req PaymentRequest) (*PaymentResponse, error) {
	// 1. Validate request
	if req.Amount <= 0 {
		return nil, errors.New("invalid transaction amount")
	}
	if req.SenderID == req.ReceiverID {
		return nil, errors.New("sender and receiver must be different")
	}

	// 2. Idempotency Check (Read lock)
	p.stateMutex.RLock()
	if existingResponse, exists := p.idempotencyMap[req.IdempotencyKey]; exists {
		p.stateMutex.RUnlock()
		log.Printf("[Idempotency] Request duplicate detected for key: %s. Returning cached result.", req.IdempotencyKey)
		return existingResponse, nil
	}
	p.stateMutex.RUnlock()

	// 3. Fetch Accounts
	p.stateMutex.RLock()
	sender, senderExists := p.accounts[req.SenderID]
	receiver, receiverExists := p.accounts[req.ReceiverID]
	p.stateMutex.RUnlock()

	if !senderExists || !receiverExists {
		return nil, errors.New("one or both accounts do not exist")
	}

	// 4. Lock Accounts in deterministic order to prevent deadlocks
	// (Always lock the account with the smaller string ID first)
	var firstLock, secondLock *Account
	if sender.ID < receiver.ID {
		firstLock, secondLock = sender, receiver
	} else {
		firstLock, secondLock = receiver, sender
	}

	firstLock.Mu.Lock()
	defer firstLock.Mu.Unlock()
	secondLock.Mu.Lock()
	defer secondLock.Mu.Unlock()

	// 5. Business Logic: Check Funds
	if sender.Balance < req.Amount {
		return nil, errors.New("insufficient funds")
	}

	// 6. Execute Transfer
	sender.Balance -= req.Amount
	receiver.Balance += req.Amount

	// Generate receipt
	txID := fmt.Sprintf("TXN-%d", time.Now().UnixNano())
	response := &PaymentResponse{
		TransactionID: txID,
		Status:        "SUCCESS",
		Amount:        req.Amount,
		Currency:      req.Currency,
		Timestamp:     time.Now().UTC(),
	}

	// 7. Save to Idempotency Map (Write lock)
	p.stateMutex.Lock()
	p.idempotencyMap[req.IdempotencyKey] = response
	p.stateMutex.Unlock()

	log.Printf("[Success] Processed %s %.2f from %s to %s. TxID: %s", req.Currency, req.Amount, req.SenderID, req.ReceiverID, txID)
	return response, nil
}

// --- HTTP Handler Layer ---

func handlePayments(processor *PaymentProcessor) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodPost {
			http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
			return
		}

		var req PaymentRequest
		err := json.NewDecoder(r.Body).Decode(&req)
		if err != nil || req.IdempotencyKey == "" {
			http.Error(w, "Bad request: Check payload and ensure idempotency_key is present", http.StatusBadRequest)
			return
		}

		res, err := processor.Process(req)
		if err != nil {
			w.WriteHeader(http.StatusUnprocessableEntity)
			json.NewEncoder(w).Encode(map[string]string{"error": err.Error()})
			return
		}

		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(http.StatusOK)
		json.NewEncoder(w).Encode(res)
	}
}

func main() {
	processor := NewPaymentProcessor()
	http.HandleFunc("/v1/payments", handlePayments(processor))

	log.Println("Banking Payment Gateway running on :8080...")
	if err := http.ListenAndServe(":8080", nil); err != nil {
		log.Fatal(err)
	}
}
```

