	"time"
)

// --- Domain Models ---

type PaymentRequest struct {
	IdempotencyKey string  `json:"idempotency_key"`
	SourceAccount  string  `json:"source_account"`
	DestAccount    string  `json:"destination_account"`
	Amount         float64 `json:"amount"`
	Currency       string  `json:"currency"`
}

type PaymentResponse struct {
	TransactionID string    `json:"transaction_id,omitempty"`
	Status        string    `json:"status"`
	Timestamp     time.Time `json:"timestamp"`
	Error         string    `json:"error,omitempty"`
}

type Account struct {
	ID      string
	Balance float64
	Mu      sync.Mutex // Protects individual account balance
}

// --- Ledger & Idempotency Store (In-Memory Simulation) ---

type PaymentService struct {
	accounts         map[string]*Account
	accountsMu       sync.RWMutex
	idempotencyStore sync.Map // Map[string]PaymentResponse
}

func NewPaymentService() *PaymentService {
	// Initialize with some mock bank accounts
	svc := &PaymentService{
		accounts: make(map[string]*Account),
	}
	svc.accounts["ACC123"] = &Account{ID: "ACC123", Balance: 1000.00}
	svc.accounts["ACC456"] = &Account{ID: "ACC456", Balance: 500.00}
	return svc
}

// --- Core Business Logic ---

func (s *PaymentService) ProcessPayment(req PaymentRequest) (PaymentResponse, error) {
	// 1. Validation
	if req.IdempotencyKey == "" {
		return PaymentResponse{}, errors.New("missing idempotency key")
	}
	if req.Amount <= 0 {
		return PaymentResponse{}, errors.New("amount must be greater than zero")
	}
	if req.SourceAccount == req.DestAccount {
		return PaymentResponse{}, errors.New("source and destination accounts must differ")
	}
	if req.Currency != "USD" { // Minimizing scope for demo
		return PaymentResponse{}, errors.New("only USD is supported currently")
	}

	// 2. Idempotency Check
	if val, ok := s.idempotencyStore.Load(req.IdempotencyKey); ok {
		log.Printf("[Idempotency] Duplicate request detected for key: %s. Returning cached response.", req.IdempotencyKey)
		return val.(PaymentResponse), nil
	}

	// 3. Retrieve Accounts
	s.accountsMu.RLock()
	source, okSrc := s.accounts[req.SourceAccount]
	dest, okDest := s.accounts[req.DestAccount]
	s.accountsMu.RUnlock()

	if !okSrc || !okDest {
		return PaymentResponse{}, errors.New("one or both accounts do not exist")
	}

	// 4. Deadlock Prevention (Lock accounts in lexical order)
	firstLock, secondLock := source, dest
	if source.ID > dest.ID {
		firstLock, secondLock = dest, source
	}

	firstLock.Mu.Lock()
	defer firstLock.Mu.Unlock()
	secondLock.Mu.Lock()
	defer secondLock.Mu.Unlock()

	// 5. Balance Check
	if source.Balance < req.Amount {
		return PaymentResponse{}, errors.New("insufficient funds")
	}

	// 6. Execute Transfer (Atomic state mutation)
	source.Balance -= req.Amount
	dest.Balance += req.Amount

	txID := fmt.Sprintf("TXN-%d", time.Now().UnixNano())
	resp := PaymentResponse{
		TransactionID: txID,
		Status:        "SUCCESS",
		Timestamp:     time.Now().UTC(),
	}

	// 7. Store Idempotency Record
	s.idempotencyStore.Store(req.IdempotencyKey, resp)

	log.Printf("[Success] Processed %s -> %s ($%.2f). Tx: %s", source.ID, dest.ID, req.Amount, txID)
	return resp, nil
}

// --- HTTP Transport Layer ---

func (s *PaymentService) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	var req PaymentRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, "Invalid JSON payload", http.StatusBadRequest)
		return
	}

	resp, err := s.ProcessPayment(req)
	w.Header().Set("Content-Type", "application/json")

	if err != nil {
		w.WriteHeader(http.StatusUnprocessableEntity)
		json.NewEncoder(w).Encode(PaymentResponse{
			Status:    "FAILED",
			Timestamp: time.Now().UTC(),
			Error:     err.Error(),
		})
		return
	}

	w.WriteHeader(http.StatusOK)
	json.NewEncoder(w).Encode(resp)
}

func main() {
	svc := NewPaymentService()
	http.Handle("/v1/payments", svc)

	log.Println("Payment service running on port :8080...")
	if err := http.ListenAndServe(":8080", nil); err != nil {
		log.Fatal(err)
	}
}
