	TargetAccount string `json:"target_account"`
	AmountCents   int64  `json:"amount_cents"` // Integer-only (avoid floats for money)
	Currency      string `json:"currency"`
}

type PaymentResponse struct {
	TransactionID string    `json:"transaction_id"`
	Status        string    `json:"status"`
	AmountCents   int64     `json:"amount_cents"`
	Currency      string    `json:"currency"`
	Timestamp     time.Time `json:"timestamp"`
	Error         string    `json:"error,omitempty"`
}

// --- In-Memory Database (Thread-Safe Ledger) ---

type Ledger struct {
	mu           sync.RWMutex
	balances     map[string]int64            // Account -> Balance in cents
	idempotency  map[string]*PaymentResponse // Idempotency Key -> Previous Response
	transactions map[string]bool             // Transaction ID Tracker
}

func NewLedger() *Ledger {
	return &Ledger{
		balances: map[string]int64{
			"ACC_BANK_1": 1000000, // $10,000.00 initial balance
			"ACC_BANK_2": 50000,   // $500.00 initial balance
		},
		idempotency:  make(map[string]*PaymentResponse),
		transactions: make(map[string]bool),
	}
}

// --- Payment Processor ---

type PaymentProcessor struct {
	ledger *Ledger
}

func (p *PaymentProcessor) ProcessPayment(idempotencyKey string, req PaymentRequest) (*PaymentResponse, error) {
	if idempotencyKey == "" {
		return nil, errors.New("missing X-Idempotency-Key header")
	}

	p.ledger.mu.Lock()
	defer p.ledger.mu.Unlock()

	// 1. Idempotency Check (Has this exact request been processed?)
	if existingResponse, exists := p.ledger.idempotency[idempotencyKey]; exists {
		log.Printf("[IDEMPOTENCY] Returned cached response for key: %s", idempotencyKey)
		return existingResponse, nil
	}

	// 2. Input Validation
	if req.AmountCents <= 0 {
		return nil, errors.New("transaction amount must be greater than zero")
	}
	if req.SourceAccount == req.TargetAccount {
		return nil, errors.New("source and target accounts must be different")
	}

	// 3. Balance Verification
	sourceBalance, exists := p.ledger.balances[req.SourceAccount]
	if !exists {
		return nil, errors.New("source account not found")
	}
	if _, exists := p.ledger.balances[req.TargetAccount]; !exists {
		return nil, errors.New("target account not found")
	}

	if sourceBalance < req.AmountCents {
		return nil, errors.New("insufficient funds")
	}

	// 4. ACID-like Atomic Transaction State Update
	p.ledger.balances[req.SourceAccount] -= req.AmountCents
	p.ledger.balances[req.TargetAccount] += req.AmountCents

	txID := fmt.Sprintf("TX-%d", time.Now().UnixNano())

	response := &PaymentResponse{
		TransactionID: txID,
		Status:        "SUCCESS",
		AmountCents:   req.AmountCents,
		Currency:      req.Currency,
		Timestamp:     time.Now().UTC(),
	}

	// Record transaction state and cache for idempotency
	p.ledger.idempotency[idempotencyKey] = response
	p.ledger.transactions[txID] = true

	log.Printf("[TX SUCCESS] ID: %s | %s -> %s | Amount: %d %s", 
		txID, req.SourceAccount, req.TargetAccount, req.AmountCents, req.Currency)

	return response, nil
}

// --- HTTP Handler ---

func (p *PaymentProcessor) HandleCharge(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")

	if r.Method != http.MethodPost {
		http.Error(w, `{"error": "Method not allowed"}`, http.StatusMethodNotAllowed)
		return
	}

	idempotencyKey := r.Header.Get("X-Idempotency-Key")
	var req PaymentRequest

	err := json.NewDecoder(r.Body).Decode(&req)
	if err != nil {
		w.WriteHeader(http.StatusBadRequest)
		json.NewEncoder(w).Encode(PaymentResponse{Status: "FAILED", Error: "Malformed JSON payload"})
		return
	}

	response, err := p.ProcessPayment(idempotencyKey, req)
	if err != nil {
		w.WriteHeader(http.StatusUnprocessableEntity)
		json.NewEncoder(w).Encode(PaymentResponse{Status: "FAILED", Error: err.Error()})
		return
	}

	w.WriteHeader(http.StatusOK)
	json.NewEncoder(w).Encode(response)
}

func main() {
	ledger := NewLedger()
	processor := &PaymentProcessor{ledger: ledger}

	http.HandleFunc("/v1/charge", processor.HandleCharge)

	port := ":8080"
	log.Printf("Starting secure payment service on port %s...", port)
	if err := http.ListenAndServe(port, nil); err != nil {
		log.Fatalf("Server failed to start: %v", err)
	}
}
```

