### 2. Integration: Legacy ERP System Client

Corporations often have legacy ERPs (like SAP or Oracle). This adapter uses Spring's `RestClient` with built-in retries and strict mapping of external API payloads.

```java
package com.enterprise.orderservice.infrastructure.erp;

import com.enterprise.orderservice.domain.model.Order;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.http.MediaType;
import org.springframework.stereotype.Component;
import org.springframework.web.client.RestClient;

// Sealed interface enforces strict compile-time handling of the ERP response
public sealed interface ErpSyncResult permits ErpSyncResult.Success, ErpSyncResult.Failure {
    record Success(String erpReferenceId) implements ErpSyncResult {}
    record Failure(String reason, int errorCode) implements ErpSyncResult {}
}

@Component
public class LegacyErpClient {
    private static final Logger log = LoggerFactory.getLogger(LegacyErpClient.class);
    private final RestClient restClient;

    public LegacyErpClient(RestClient.Builder restClientBuilder) {
        // Configuring client with timeouts, SSL, and corporate proxy if needed
        this.restClient = restClientBuilder
                .baseUrl("https://legacy-erp.corporate.local/api/v1")
                .defaultHeader("Authorization", "Bearer CORPORATE_SERVICE_TOKEN")
                .build();
    }

    public ErpSyncResult syncOrder(Order order) {
        log.info("Syncing order {} to Legacy ERP", order.id().value());

        // Strictly-typed request payload for legacy system
        ErpOrderRequest request = new ErpOrderRequest(
                order.id().value(),
                order.customerId().value(),
                order.totalAmount().amount()
        );

        try {
            ErpOrderResponse response = restClient.post()
                    .uri("/orders")
                    .contentType(MediaType.APPLICATION_JSON)
                    .body(request)
                    .retrieve()
                    .toEntity(ErpOrderResponse.class)
                    .getBody();

            if (response != null && "SUCCESS".equals(response.status())) {
                return new ErpSyncResult.Success(response.erpId());
            }
            return new ErpSyncResult.Failure("ERP rejected order", 500);

        } catch (Exception ex) {
            log.error("Failed to connect to corporate ERP system for order: {}", order.id().value(), ex);
            return new ErpSyncResult.Failure(ex.getMessage(), 503);
        }
    }

    // Strongly typed DTOs mapped explicitly to Legacy JSON/XML formats
    private record ErpOrderRequest(String sysId, String custId, java.math.BigDecimal val) {}
    private record ErpOrderResponse(String erpId, String status) {}
}
```

