### 3. Integration: Enterprise Message Publisher

In enterprise architectures, actions must propagate asynchronously via Brokers (Kafka, ActiveMQ, RabbitMQ).

```java
package com.enterprise.orderservice.infrastructure.messaging;

import com.enterprise.orderservice.domain.model.Order;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.kafka.core.KafkaTemplate;
import org.springframework.stereotype.Component;

@Component
public class CorporateEventPublisher {
    private static final Logger log = LoggerFactory.getLogger(CorporateEventPublisher.class);
    private final KafkaTemplate<String, OrderStatusEvent> kafkaTemplate;
    private static final String TOPIC = "corporate.orders.v1";

    public CorporateEventPublisher(KafkaTemplate<String, OrderStatusEvent> kafkaTemplate) {
        this.kafkaTemplate = kafkaTemplate;
    }

    public void publishOrderProcessedEvent(Order order) {
        log.info("Publishing transactional event for order {}", order.id().value());

        OrderStatusEvent event = new OrderStatusEvent(
                order.id().value(),
                order.state().name(),
                System.currentTimeMillis()
        );

        // Transactionally safe publishing
        this.kafkaTemplate.send(TOPIC, order.id().value(), event)
                .whenComplete((result, ex) -> {
                    if (ex == null) {
                        log.info("Successfully published order event to corporate broker");
                    } else {
                        log.error("Critical: Failed to publish corporate event", ex);
                        // In production, write to an Outbox Table or DLQ here
                    }
                });
    }

    // Type-safe schema definition mapped to JSON or Avro schema
    public record OrderStatusEvent(String orderId, String status, long timestamp) {}
}
```

