### 4. The Orchestration Service Layer

Coordinates database transactions, integrations, and business logic securely.

```java
package com.enterprise.orderservice.domain;

import com.enterprise.orderservice.domain.model.*;
import com.enterprise.orderservice.infrastructure.erp.ErpSyncResult;
import com.enterprise.orderservice.infrastructure.erp.LegacyErpClient;
import com.enterprise.orderservice.infrastructure.messaging.CorporateEventPublisher;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class OrderProcessor {

    private final LegacyErpClient erpClient;
    private final CorporateEventPublisher eventPublisher;

    public OrderProcessor(LegacyErpClient erpClient, CorporateEventPublisher eventPublisher) {
        this.erpClient = erpClient;
        this.eventPublisher = eventPublisher;
    }

    @Transactional // Enforces ACID compliance over enterprise DB actions
    public Order processOrder(Order order) {
        // 1. Sync with legacy enterprise ERP system
        ErpSyncResult syncResult = erpClient.syncOrder(order);

        // 2. Strict pattern matching on sealed interface result (Java 21 feature)
        Order processedOrder = switch (syncResult) {
            case ErpSyncResult.Success success -> 
                order.withState(OrderState.ERP_SYNCED);
            case ErpSyncResult.Failure failure -> 
                order.withState(OrderState.FAILED_ERP_SYNC);
        };

        // 3. Persist to local Microservice DB (Repository skipped for brevity)
        // dbRepository.save(processedOrder);

        // 4. Publish Event to Corporate Bus
        eventPublisher.publishOrderProcessedEvent(processedOrder);

        return processedOrder;
    }
}
