### 5. API Entry Point (REST Controller & Validation)

Provides input verification using Bean Validation to guarantee that bad payloads are rejected before hitting the business domain.

```java
package com.enterprise.orderservice.infrastructure.api;

import com.enterprise.orderservice.domain.OrderProcessor;
import com.enterprise.orderservice.domain.model.*;
import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotEmpty;
import jakarta.validation.constraints.NotNull;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

import java.math.BigDecimal;
import java.util.Currency;
import java.util.List;

@RestController
@RequestMapping("/api/v1/orders")
public class OrderController {

    private final OrderProcessor orderProcessor;

    public OrderController(OrderProcessor orderProcessor) {
        this.orderProcessor = orderProcessor;
    }

    @PostMapping
    public ResponseEntity<OrderResponseDto> createOrder(@Valid @RequestBody CreateOrderRequest request) {
        // Mapping DTO to Type-Safe Domain Objects
        Order order = new Order(
                new OrderId(java.util.UUID.randomUUID().toString()),
                new CustomerId(request.customerId()),
                request.items().stream()
                        .map(item -> new OrderLineItem(
                                item.sku(),
                                item.quantity(),
                                new Money(item.price(), Currency.getInstance("USD"))))
                        .toList(),
                new Money(request.totalAmount(), Currency.getInstance("USD")),
                OrderState.PENDING
        );

        Order processedOrder = orderProcessor.processOrder(order);

        return ResponseEntity.ok(new OrderResponseDto(
                processedOrder.id().value(),
                processedOrder.state().name()
        ));
    }

    // Strictly-typed DTO validation contracts
    public record CreateOrderRequest(
            @NotBlank String customerId,
            @NotEmpty List<@Valid ItemDto> items,
            @NotNull BigDecimal totalAmount
    ) {}

    public record ItemDto(
            @NotBlank String sku,
            int quantity,
            @NotNull BigDecimal price
    ) {}

    public record OrderResponseDto(String orderId, String status) {}
}
