### 3. Corporate System Integration: Legacy Client (with Resilience)
We use Spring's modern `RestClient` configured with a connection pool, strict timeouts, and a retry mechanism using Spring Retry to handle legacy system instability.

```java
package com.enterprise.profileservice.integration.legacy;

import com.enterprise.profileservice.domain.EmployeeId;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.retry.annotation.Backoff;
import org.springframework.retry.annotation.Retryable;
import org.springframework.stereotype.Component;
import org.springframework.web.client.ResourceAccessException;
import org.springframework.web.client.RestClient;

@Component
public class LegacyHrClient {

    private static final Logger log = LoggerFactory.getLogger(LegacyHrClient.class);
    private final RestClient restClient;

    public LegacyHrClient(RestClient restClient) {
        this.restClient = restClient;
    }

    /**
     * Fetches details from a legacy main-frame API. 
     * Retries 3 times with exponential backoff if the network drops.
     */
    @Retryable(
        retryFor = { ResourceAccessException.class }, 
        maxAttempts = 3, 
        backoff = @Backoff(delay = 1000, multiplier = 2)
    )
    public LegacyHrRecord fetchLegacyRecord(EmployeeId id) {
        log.info("Fetching record from Legacy HR System for ID: {}", id.value());

        return this.restClient.get()
            .uri("/legacy-api/employees/{id}", id.value())
            .retrieve()
            .toEntity(LegacyHrRecord.class)
            .getBody();
    }
}
