package com.enterprise.inventory.integration;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.http.HttpStatusCode;
import org.springframework.stereotype.Component;
import org.springframework.web.client.RestClient;

/**
 * Adapter implementation integrating with a legacy Corporate ERP system.
 */
@Component
public class RestCorporateErpClient implements CorporateErpClient {

    private static final Logger log = LoggerFactory.getLogger(RestCorporateErpClient.class);
    private final RestClient restClient;

    // Configured via application properties for corporate environments
    public RestCorporateErpClient(RestClient.Builder restClientBuilder) {
        this.restClient = restClientBuilder
                .baseUrl("https://internal-erp.corp.local/api/v1")
                .defaultHeader("Authorization", "Bearer " + getCorporateServiceToken())
                .build();
    }

    @Override
    public boolean verifySkuExistsInErp(String sku) {
        log.info("Verifying SKU {} with Corporate ERP...", sku);
        try {
            return Boolean.TRUE.equals(restClient.get()
                    .uri("/products/{sku}/validate", sku)
                    .retrieve()
                    .onStatus(HttpStatusCode::is5xxServerError, (req, res) -> {
                        throw new RuntimeException("Corporate ERP returned system error: " + res.getStatusCode());
                    })
                    .body(Boolean.class));
        } catch (Exception e) {
            log.error("Failed to communicate with Legacy ERP for SKU validation", e);
            return false; // Fail-secure/closed pattern
        }
    }

    @Override
    public ErpSyncResult syncInventoryToErp(String sku, int quantity) {
        log.info("Syncing stock update to ERP. SKU: {}, Qty: {}", sku, quantity);
        // Type-safe payload for legacy system mapping
        ErpSyncPayload payload = new ErpSyncPayload(sku, quantity, "MICROSERVICE_UPDATE");

        return restClient.post()
                .uri("/inventory/sync")
                .body(payload)
                .retrieve()
                .body(ErpSyncResult.class);
    }

    private String getCorporateServiceToken() {
        // OAuth2 Client Credentials flow simulation
        return "corp-jwt-token-from-vault";
    }

    // Private typed helper for outbound integration payload mapping
    private record ErpSyncPayload(String partNumber, int stockCount, String sourceSystem) {}
}
