### 4. Service Layer (Business Logic orchestrator)

Handles domain transactions and implements strict checks.

```java
package com.enterprise.inventory.service;

import com.enterprise.inventory.dto.CreateInventoryRequest;
import com.enterprise.inventory.dto.InventoryResponse;
import com.enterprise.inventory.entity.InventoryItem;
import com.enterprise.inventory.exception.DuplicateSkuException;
import com.enterprise.inventory.exception.ErpValidationException;
import com.enterprise.inventory.integration.CorporateErpClient;
import com.enterprise.inventory.integration.ErpSyncResult;
import com.enterprise.inventory.repository.InventoryRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class InventoryService {

    private final InventoryRepository repository;
    private final CorporateErpClient erpClient;

    public InventoryService(InventoryRepository repository, CorporateErpClient erpClient) {
        this.repository = repository;
        this.erpClient = erpClient;
    }

    @Transactional
    public InventoryResponse registerNewInventory(CreateInventoryRequest request) {
        // 1. Strict local uniqueness check
        if (repository.existsBySku(request.sku())) {
            throw new DuplicateSkuException("SKU " + request.sku() + " already registered locally.");
        }

        // 2. Integration verification check against legacy Corporate ERP
        boolean isValidErpProduct = erpClient.verifySkuExistsInErp(request.sku());
        if (!isValidErpProduct) {
            throw new ErpValidationException("SKU " + request.sku() + " is not active/valid in the corporate ERP.");
        }

        // 3. Save Entity
        InventoryItem item = new InventoryItem(
                request.sku(),
                request.name(),
                request.price(),
                request.initialQuantity(),
                "PENDING"
        );
        InventoryItem savedItem = repository.save(item);

        // 4. Synchronous Transactional Outbox Sync (or direct sync depending on requirements)
        try {
            ErpSyncResult result = erpClient.syncInventoryToErp(savedItem.getSku(), savedItem.getQuantity());
            savedItem.updateErpSyncStatus("SUCCESS: " + result.erpReferenceId());
        } catch (Exception e) {
            savedItem.updateErpSyncStatus("FAILED");
            // In a production system, you would register this in a transactional outbox 
            // for retry, rather than letting the whole tx fail or silent failure.
        }

        return mapToResponse(savedItem);
    }

    private InventoryResponse mapToResponse(InventoryItem item) {
        return new InventoryResponse(
                item.getId(),
                item.getSku(),
                item.getName(),
                item.getPrice(),
                item.getQuantity(),
                item.getErpSyncStatus(),
                item.getCreatedAt()
        );
    }
}
```

