import com.enterprise.order.domain.Money;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.http.HttpStatusCode;
import org.springframework.stereotype.Component;
import org.springframework.web.client.RestClient;
import org.springframework.web.server.ResponseStatusException;

import java.math.BigDecimal;

@Component
public class LegacyErpClient {

    private static final Logger log = LoggerFactory.getLogger(LegacyErpClient.class);
    private final RestClient restClient;

    // In production, URLs and timeouts would be injected via @Value or @ConfigurationProperties
    public LegacyErpClient(RestClient.Builder restClientBuilder) {
        this.restClient = restClientBuilder
            .baseUrl("https://legacy-erp.internal.corp/api/v1")
            .build();
    }

    // Strictly typed DTO for the legacy system's JSON response
    public record ErpCreditResponse(String status, BigDecimal availableLimit, String currency) {}

    public boolean hasSufficientCredit(CustomerId customerId, Money orderAmount) {
        log.info("Checking credit limit for customer {} in legacy ERP", customerId.value());

        try {
            ErpCreditResponse response = restClient.get()
                .uri("/customers/{id}/credit", customerId.value())
                .retrieve()
                .onStatus(HttpStatusCode::isError, (req, res) -> {
                    throw new ResponseStatusException(res.getStatusCode(), "Legacy ERP failed");
                })
                .body(ErpCreditResponse.class);

            if (response == null) return false;

            Money creditLimit = new Money(response.availableLimit(), response.currency());
            return creditLimit.currency().equals(orderAmount.currency()) 
                && creditLimit.amount().compareTo(orderAmount.amount()) >= 0;

        } catch (Exception e) {
            log.error("Failed to connect to Legacy ERP system", e);
            // In enterprise environments, fail-closed is usually preferred for financial operations
            throw new IllegalStateException("Legacy integration failure: Credit check unavailable", e);
        }
    }
}
