package com.enterprise.order.service;

import com.enterprise.order.domain.*;
import com.enterprise.order.dto.OrderRequest;
import com.enterprise.order.event.OrderEvent;
import com.enterprise.order.integration.LegacyErpClient;
import com.enterprise.order.repository.OrderRepository;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.context.ApplicationEventPublisher;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.Instant;
import java.util.UUID;

@Service
public class OrderService {

    private static final Logger log = LoggerFactory.getLogger(OrderService.class);

    private final LegacyErpClient erpClient;
    private final OrderRepository orderRepository;
    private final ApplicationEventPublisher eventPublisher;

    public OrderService(LegacyErpClient erpClient, OrderRepository orderRepository, ApplicationEventPublisher eventPublisher) {
        this.erpClient = erpClient;
        this.orderRepository = orderRepository;
        this.eventPublisher = eventPublisher;
    }

    @Transactional
    public OrderId processOrder(OrderRequest request) {
        OrderId orderId = new OrderId(UUID.randomUUID());
        log.info("Processing order {} for customer {}", orderId.value(), request.customerId().value());

        // Call the legacy integration point
        boolean hasCredit = erpClient.hasSufficientCredit(request.customerId(), request.totalAmount());

        if (!hasCredit) {
            log.warn("Customer {} has insufficient credit", request.customerId().value());
            OrderEntity order = new OrderEntity(orderId, request.customerId(), request.totalAmount(), OrderEntity.OrderStatus.REJECTED);
            orderRepository.save(order);

            eventPublisher.publishEvent(new OrderEvent.OrderFailed(orderId, Instant.now(), "Insufficient credit limit in ERP"));
            throw new IllegalArgumentException("Order rejected: Insufficient credit limit.");
        }

        OrderEntity order = new OrderEntity(orderId, request.customerId(), request.totalAmount(), OrderEntity.OrderStatus.APPROVED);
        orderRepository.save(order);

        // Publish event (can be listened to by an AMQP/Kafka adapter)
        eventPublisher.publishEvent(new OrderEvent.OrderCreated(orderId, Instant.now(), "Order successfully verified with ERP"));

        log.info("Order {} successfully processed and saved", orderId.value());
        return orderId;
    }
}
