### 4. Core Business Service
The service orchestrates database persistence, integration logic, and transactional rollbacks.

```java
package com.enterprise.customer.service;

import com.enterprise.customer.dto.*;
import com.enterprise.customer.entity.Customer;
import com.enterprise.customer.integration.*;
import com.enterprise.customer.repository.CustomerRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.time.Instant;

@Service
public class CustomerServiceImpl implements CustomerService {

    private final CustomerRepository repository;
    private final LegacyErpIntegrationClient erpClient;
    private final CorporateMessageBrokerGateway eventGateway;

    public CustomerServiceImpl(CustomerRepository repository, 
                               LegacyErpIntegrationClient erpClient, 
                               CorporateMessageBrokerGateway eventGateway) {
        this.repository = repository;
        this.erpClient = erpClient;
        this.eventGateway = eventGateway;
    }

    @Override
    @Transactional // Ensures database, ERP, and Message actions are treated transactionally where possible
    public CustomerResponse createCustomer(CreateCustomerRequest request) {

        // 1. Enforce business rules
        if (repository.existsByTaxId(request.taxId())) {
            throw new IllegalArgumentException("Customer with Tax ID " + request.taxId() + " already exists.");
        }

        // 2. Map and persist to DB
        Customer customer = new Customer();
        customer.setCompanyName(request.companyName());
        customer.setTaxId(request.taxId());
        customer.setCorporateEmail(request.corporateEmail());
        customer.setTier(request.tier());

        // Save preliminary entity to database
        customer = repository.save(customer);

        // 3. Integrate with the Legacy ERP
        String legacyId = erpClient.registerCustomerInLegacySystem(customer);
        customer.setLegacyErpId(legacyId);

        // Save final synchronized entity
        customer = repository.save(customer);

        // 4. Publish Event to Corporate Message Broker (Kafka/RabbitMQ)
        eventGateway.publishCustomerCreatedEvent(new CustomerCreatedEvent(
            customer.getId().toString(),
            customer.getTaxId(),
            customer.getLegacyErpId(),
            Instant.now()
        ));

        // 5. Map to strictly typed Response Record
        return mapToResponse(customer);
    }

    private CustomerResponse mapToResponse(Customer customer) {
        return new CustomerResponse(
            customer.getId(),
            customer.getCompanyName(),
            customer.getTaxId(),
            customer.getCorporateEmail(),
            customer.getTier(),
            customer.getLegacyErpId(),
            customer.getCreatedAt()
        );
    }
}
