### 6. Robust Enterprise Error Handling
To prevent raw database stack traces or unmapped null-pointer errors from leaking, we configure a global API boundary error translator.

```java
package com.enterprise.customer.exception;

import com.enterprise.customer.integration.LegacyErpIntegrationClient.LegacyErpException;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.MethodArgumentNotValidException;
import org.springframework.web.bind.annotation.ControllerAdvice;
import org.springframework.web.bind.annotation.ExceptionHandler;

import java.time.Instant;
import java.util.HashMap;
import java.util.Map;

@ControllerAdvice
public class GlobalExceptionHandler {

    // Custom Error Record to present structured JSON errors to corporate API Consumers
    public record ApiErrorResponse(
        String errorCode,
        String message,
        Instant timestamp,
        Map<String, String> details
    ) {}

    // Handle Input validation failures (Strict types failed criteria check)
    @ExceptionHandler(MethodArgumentNotValidException.class)
    public ResponseEntity<ApiErrorResponse> handleValidationExceptions(MethodArgumentNotValidException ex) {
        Map<String, String> errors = new HashMap<>();
        ex.getBindingResult().getFieldErrors().forEach(error -> 
            errors.put(error.getField(), error.getDefaultMessage())
        );

        ApiErrorResponse apiError = new ApiErrorResponse(
            "ERR_INVALID_REQUEST_PAYLOAD",
            "Request validation failed",
            Instant.now(),
            errors
        );
        return new ResponseEntity<>(apiError, HttpStatus.BAD_REQUEST);
    }

    // Handle Legacy Integration Failures gracefully (502 Bad Gateway)
    @ExceptionHandler(LegacyErpException.class)
    public ResponseEntity<ApiErrorResponse> handleLegacyErpException(LegacyErpException ex) {
        ApiErrorResponse apiError = new ApiErrorResponse(
            "ERR_LEGACY_ERP_UNAVAILABLE",
            ex.getMessage(),
            Instant.now(),
            Map.of("rootCause", ex.getCause().getMessage())
        );
        return new ResponseEntity<>(apiError, HttpStatus.BAD_GATEWAY);
    }

    // Handle standard business logic constraint violations (e.g., entity duplicate)
    @ExceptionHandler(IllegalArgumentException.class)
    public ResponseEntity<ApiErrorResponse> handleIllegalArguments(IllegalArgumentException ex) {
        ApiErrorResponse apiError = new ApiErrorResponse(
            "ERR_BUSINESS_RULE_VIOLATION",
            ex.getMessage(),
            Instant.now(),
            Map.of()
        );
        return new ResponseEntity<>(apiError, HttpStatus.CONFLICT);
    }
}
```

