```java
package com.enterprise.accountservice.dto;

import jakarta.validation.constraints.*;
import java.math.BigDecimal;

public record CreateAccountRequest(
    @NotBlank(message = "Corporate Tax ID is required")
    @Pattern(regexp = "^\\d{2}-\\d{7}$", message = "Invalid Corporate Tax ID format (XX-YYYYYYY)")
    String taxId,

