### 4. Integration Layer: Connecting to Legacy ERP System
Corporate legacy systems often return inconsistent error formats. We build a robust, type-safe client using Spring's `RestClient` that parses mainframe responses directly into typed records, handling failures gracefully.

```java
package com.enterprise.accountservice.integration;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.http.HttpStatusCode;
import org.springframework.stereotype.Component;
import org.springframework.web.client.RestClient;

// Type-safe representation of Legacy ERP Payload (e.g., SAP or IBM AS400)
public record LegacyERPAuditResponse(
    String taxId,
    String creditRatingCode,
    boolean isActiveInMainframe,
    boolean isBlacklisted
) {}

@Component
public class LegacyERPClient {

    private static final Logger log = LoggerFactory.getLogger(LegacyERPClient.class);
    private final RestClient restClient;

    public LegacyERPClient(RestClient.Builder restClientBuilder) {
        // In real environments, this base URL would point to an API Gateway or ESB
        this.restClient = restClientBuilder.baseUrl("https://legacy-erp.internal.corp/api/v1").build();
    }

    public LegacyERPAuditResponse auditCompany(String taxId) {
        log.info("Querying legacy ERP system for Tax ID: {}", taxId);
        try {
            return this.restClient.get()
                .uri("/companies/{taxId}", taxId)
                .retrieve()
                .onStatus(HttpStatusCode::is5xxServerError, (req, res) -> {
                    throw new RuntimeException("Legacy mainframe unavailable: " + res.getStatusText());
                })
                .body(LegacyERPAuditResponse.class);
        } catch (Exception ex) {
            log.error("Failed to connect to Legacy ERP system", ex);
            // Fallback default status or exception depending on corporate policy (Strict design)
            throw new IllegalStateException("Corporate Integration Layer offline.", ex);
        }
    }
}
```

