### 7. Core Business Logic (Applying Pattern Matching)
The service layer coordinates database state, legacy validation, and external messaging. Using **Java 21 Pattern Matching for switch statements**, we can resolve the `AccountCreationResult` sealed interface in an elegant, type-safe manner.

```java
package com.enterprise.accountservice.service;

import com.enterprise.accountservice.dto.AccountCreationResult;
import com.enterprise.accountservice.dto.CreateAccountRequest;
import com.enterprise.accountservice.entity.CorporateAccount;
import com.enterprise.accountservice.integration.AccountCreatedIntegrationEvent;
import com.enterprise.accountservice.integration.CorporateMessageBrokerGateway;
import com.enterprise.accountservice.integration.LegacyERPClient;
import com.enterprise.accountservice.integration.LegacyERPAuditResponse;
import com.enterprise.accountservice.repository.CorporateAccountRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.math.BigDecimal;
import java.time.Instant;

@Service
public class AccountService {

    private final CorporateAccountRepository repository;
    private final LegacyERPClient legacyERPClient;
    private final CorporateMessageBrokerGateway eventGateway;

    public AccountService(CorporateAccountRepository repository, 
                          LegacyERPClient legacyERPClient, 
                          CorporateMessageBrokerGateway eventGateway) {
        this.repository = repository;
        this.legacyERPClient = legacyERPClient;
        this.eventGateway = eventGateway;
    }

    @Transactional
    public AccountCreationResult processAccountCreation(CreateAccountRequest request) {
        // 1. Enforce local unique validation
        if (repository.existsByTaxId(request.taxId())) {
            return new AccountCreationResult.CreditLimitExceeded("Company already registered locally.");
        }

        // 2. Query Legacy Corporate System
        LegacyERPAuditResponse legacyData = legacyERPClient.auditCompany(request.taxId());

        // 3. Strict enterprise validation rules based on legacy audit
        if (legacyData.isBlacklisted()) {
            return new AccountCreationResult.RejectedByLegacyERP("BLOCKED_BLACKLISTED");
        }
        if (!legacyData.isActiveInMainframe()) {
            return new AccountCreationResult.RejectedByLegacyERP("BLOCKED_INACTIVE_CORP_STATUS");
        }

        // Apply strict tiered credit caps based on legacy risk codes
        BigDecimal maxLimitAllowed = "AAA".equalsIgnoreCase(legacyData.creditRatingCode()) 
            ? new BigDecimal("1000000.00") 
            : new BigDecimal("50000.00");

        if (request.requestedCreditLimit().compareTo(maxLimitAllowed) > 0) {
            return new AccountCreationResult.CreditLimitExceeded("Requested limit exceeds maximum corporate cap of " + maxLimitAllowed);
        }

        // 4. Persistence
        CorporateAccount savedAccount = repository.save(
            new CorporateAccount(request.taxId(), request.companyName(), request.requestedCreditLimit())
        );

        // 5. Fire Integration Event
        eventGateway.publishAccountCreationEvent(new AccountCreatedIntegrationEvent(
            savedAccount.getId(),
            savedAccount.getTaxId(),
            Instant.now().toString()
        ));

        return new AccountCreationResult.Success(savedAccount);
    }
}
```

