### 8. Web Layer: The Controller API Entrypoint
The REST Controller uses Java 21 `switch` statements to safely map each domain response type to its respective HTTP Status Code. If a developer attempts to add a new `AccountCreationResult` type without updating this controller, the Java compiler will fail to build, ensuring code-safety during rapid updates.

```java
package com.enterprise.accountservice.controller;

import com.enterprise.accountservice.dto.AccountCreationResult;
import com.enterprise.accountservice.dto.CreateAccountRequest;
import com.enterprise.accountservice.service.AccountService;
import jakarta.validation.Valid;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

@RestController
@RequestMapping("/api/v1/accounts")
public class AccountController {

    private final AccountService accountService;

    public AccountController(AccountService accountService) {
        this.accountService = accountService;
    }

    @PostMapping
    public ResponseEntity<?> createCorporateAccount(@Valid @RequestBody CreateAccountRequest request) {
        AccountCreationResult result = accountService.processAccountCreation(request);

        // Java 21 Pattern Matching Switch - Exhaustive evaluation checked by compiler
        return switch (result) {
            case AccountCreationResult.Success s -> 
                ResponseEntity.status(HttpStatus.CREATED).body(s.account());

            case AccountCreationResult.RejectedByLegacyERP r -> 
                ResponseEntity.status(HttpStatus.FORBIDDEN)
                    .body(new ErrorPayload("LEGACY_REJECTION", "Legacy system verification failed. Code: " + r.reasonCode()));

            case AccountCreationResult.CreditLimitExceeded c -> 
                ResponseEntity.status(HttpStatus.UNPROCESSABLE_ENTITY)
                    .body(new ErrorPayload("CREDIT_LIMIT_REJECTED", c.message()));
        };
    }

    // Standard immutable error payload structure
    private record ErrorPayload(String code, String detail) {}
}
```

