package com.enterprise.payment.domain;

import java.math.BigDecimal;
import java.util.Currency;
import java.util.Objects;
import java.util.UUID;

// Strongly typed Account ID to prevent mixing up Source and Destination accounts
public record AccountId(String value) {
    public AccountId {
        Objects.requireNonNull(value, "Account ID cannot be null");
        if (value.isBlank()) {
            throw new IllegalArgumentException("Account ID cannot be empty");
        }
    }
}

// Strictly typed Money class ensuring currency safety
public record Money(BigDecimal amount, Currency currency) {
    public Money {
        Objects.requireNonNull(amount, "Amount cannot be null");
        Objects.requireNonNull(currency, "Currency cannot be null");
        if (amount.compareTo(BigDecimal.ZERO) <= 0) {
            throw new IllegalArgumentException("Amount must be positive");
        }
    }
}

public record PaymentId(UUID value) {
    public PaymentId {
        Objects.requireNonNull(value, "Payment ID cannot be null");
    }
    public static PaymentId generate() {
        return new PaymentId(UUID.randomUUID());
    }
}

public enum PaymentStatus {
    PENDING, SUCCESSFUL, FAILED_INSUFFICIENT_FUNDS, FAILED_LEGACY_REJECTED
}

// Core Aggregate Root
public record Payment(
    PaymentId id,
    AccountId sourceAccount,
    AccountId destinationAccount,
    Money money,
    PaymentStatus status
) {
    public Payment withStatus(PaymentStatus newStatus) {
        return new Payment(id, sourceAccount, destinationAccount, money, newStatus);
