package com.enterprise.payment.infrastructure.legacy;

import com.enterprise.payment.domain.AccountId;
import com.enterprise.payment.domain.Money;
import org.springframework.stereotype.Component;
import org.springframework.web.client.RestClient;
import org.springframework.http.MediaType;

@Component
public class LegacyLedgerClient {

    private final RestClient restClient;

    public LegacyLedgerClient(RestClient.Builder restClientBuilder) {
        // Configuring client with enterprise-grade timeouts and SSL (mocked URL)
        this.restClient = restClientBuilder
                .baseUrl("https://legacy-mainframe.corp.internal/api/v1")
                .build();
    }

    // Strict Request/Response DTOs specifically for the legacy system boundaries
    private record LegacyCheckRequest(String acctNum, double amt, String cur) {}
    private record LegacyCheckResponse(String status, String authorizationCode) {}

    public boolean verifyFundsWithLegacyMainframe(AccountId accountId, Money money) {
        try {
            LegacyCheckResponse response = restClient.post()
                    .uri("/account/verify")
                    .contentType(MediaType.APPLICATION_JSON)
                    .body(new LegacyCheckRequest(
                            accountId.value(),
                            money.amount().doubleValue(),
                            money.currency().getCurrencyCode()
                    ))
                    .retrieve()
                    .body(LegacyCheckResponse.class);

            return response != null && "APPROVED".equalsIgnoreCase(response.status());
        } catch (Exception e) {
            // In enterprise systems, fallback behavior or typed exceptions are mandatory
            throw new LegacyIntegrationException("Failed to connect to corporate mainframe", e);
        }
    }
}
