    private final EnterpriseEventPublisher eventPublisher;

    public PaymentService(LegacyLedgerClient legacyLedgerClient, EnterpriseEventPublisher eventPublisher) {
        this.legacyLedgerClient = legacyLedgerClient;
        this.eventPublisher = eventPublisher;
    }

    @Transactional
    public Payment processPayment(AccountId source, AccountId destination, Money money) {
        // 1. Initialize local domain concept
        Payment payment = new Payment(PaymentId.generate(), source, destination, money, PaymentStatus.PENDING);

        // 2. Strict validation check against legacy mainframe
        boolean legacyApproved = legacyLedgerClient.verifyFundsWithLegacyMainframe(source, money);

        if (!legacyApproved) {
            payment = payment.withStatus(PaymentStatus.FAILED_INSUFFICIENT_FUNDS);
        } else {
            payment = payment.withStatus(PaymentStatus.SUCCESSFUL);
        }

        // 3. Publish status update event to the enterprise bus
        eventPublisher.publishPaymentSettledEvent(payment);

        return payment;
    }
}
