### 5. Web Layer & JSR-380 Validation (Inbound Adapter)
Ensures untrusted JSON input is validated strictly at the HTTP boundary before it ever enters the domain layers.

```java
package com.enterprise.payment.web;

import com.enterprise.payment.domain.*;
import jakarta.validation.Valid;
import jakarta.validation.constraints.DecimalMin;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

import java.math.BigDecimal;
import java.util.Currency;

@RestController
@RequestMapping("/api/v1/payments")
public class PaymentController {

    private final PaymentService paymentService;

    public PaymentController(PaymentService paymentService) {
        this.paymentService = paymentService;
    }

    // Type-safe inbound payload validation (JSR-380)
    public record CreatePaymentRequest(
        @NotBlank @Size(min = 10, max = 34) String sourceAccount,
        @NotBlank @Size(min = 10, max = 34) String destinationAccount,
        @NotNull @DecimalMin(value = "0.01") BigDecimal amount,
        @NotBlank @Size(min = 3, max = 3) String currencyCode
    ) {}

    public record PaymentResponse(String paymentId, String status) {}

    @PostMapping
    public ResponseEntity<PaymentResponse> initiatePayment(@Valid @RequestBody CreatePaymentRequest request) {

        // Safe mapping of primitive strings/decimals to strongly-typed domain value objects
        AccountId source = new AccountId(request.sourceAccount());
        AccountId destination = new AccountId(request.destinationAccount());
        Money money = new Money(request.amount(), Currency.getInstance(request.currencyCode()));

        Payment result = paymentService.processPayment(source, destination, money);

        return ResponseEntity.ok(new PaymentResponse(
                result.id().value().toString(),
                result.status().name()
        ));
    }
}
