### 6. Robust Enterprise Error Boundary
Uncaught runtime exceptions must be parsed into RFC 7807 standard structures to prevent internal stack traces from leaking to client networks.

```java
package com.enterprise.payment.web;

import com.enterprise.payment.infrastructure.legacy.LegacyIntegrationException;
import org.springframework.http.HttpStatus;
import org.springframework.http.ProblemDetail;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;
import org.springframework.web.servlet.mvc.method.annotation.ResponseEntityExceptionHandler;

import java.net.URI;
import java.time.Instant;

@RestControllerAdvice
public class GlobalExceptionHandler extends ResponseEntityExceptionHandler {

    @ExceptionHandler(LegacyIntegrationException.class)
    public ProblemDetail handleLegacyFailure(LegacyIntegrationException ex) {
        ProblemDetail problemDetail = ProblemDetail.forStatusAndDetail(
                HttpStatus.BAD_GATEWAY, 
                "Corporate Legacy system failed to reply. Try again later."
        );
        problemDetail.setTitle("Legacy System Integration Failure");
        problemDetail.setType(URI.create("https://enterprise.corp/errors/legacy-offline"));
        problemDetail.setProperty("timestamp", Instant.now());
        return problemDetail;
    }

    @ExceptionHandler(IllegalArgumentException.class)
    public ProblemDetail handleTypeConstructionException(IllegalArgumentException ex) {
        ProblemDetail problemDetail = ProblemDetail.forStatusAndDetail(
                HttpStatus.BAD_REQUEST, 
                ex.getMessage()
        );
        problemDetail.setTitle("Type Validation Constraint Failure");
        problemDetail.setType(URI.create("https://enterprise.corp/errors/invalid-types"));
        problemDetail.setProperty("timestamp", Instant.now());
        return problemDetail;
    }
}
```

