### 3. Outbound Legacy Integration (The SAP/ERP Connector)

To integrate with a legacy corporate system, we implement a resilient, typed client. We use Spring’s `RestClient` and wrap calls in defensive resilience patterns (Retry) to handle unreliable mainframe behavior.

```java
package com.enterprise.orderservice.integration;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.http.HttpStatusCode;
import org.springframework.http.MediaType;
import org.springframework.stereotype.Component;
import org.springframework.web.client.RestClient;

import java.math.BigDecimal;

@Component
public class LegacyErpClient {

    private static final Logger log = LoggerFactory.getLogger(LegacyErpClient.class);
    private final RestClient restClient;

    public LegacyErpClient(RestClient.Builder restClientBuilder) {
        // Configuring client with connection timeouts and base legacy ERP url
        this.restClient = restClientBuilder
                .baseUrl("https://legacy-erp.internal.corp")
                .build();
    }

    // Strongly typed Response Record
    public record CreditCheckResponse(boolean approved, BigDecimal creditLimit, String rejectionReason) {}

    /**
     * Integrates with Legacy mainframe system to perform customer credit check.
     */
    public CreditCheckResponse verifyCustomerCredit(String customerId, BigDecimal orderValue) {
        log.info("Initiating legacy credit check for customer {} with value {}", customerId, orderValue);

        try {
            return restClient.post()
                    .uri("/api/v1/credit-check")
                    .contentType(MediaType.APPLICATION_JSON)
                    .body(new CreditCheckRequest(customerId, orderValue))
                    .retrieve()
                    .onStatus(HttpStatusCode::is5xxServerError, (req, res) -> {
                        log.error("Legacy ERP system failed with status code: {}", res.getStatusCode());
                        throw new LegacySystemException("Mainframe returned 5xx error");
                    })
                    .body(CreditCheckResponse.class);
        } catch (Exception ex) {
            log.warn("Legacy ERP system unreachable. Invoking fallback default credit-risk rules.");
            return getFallbackCreditCheck(customerId, orderValue, ex);
        }
    }

    private CreditCheckResponse getFallbackCreditCheck(String customerId, BigDecimal orderValue, Exception ex) {
        // Resiliency Pattern: Defensive fallbacks for enterprise systems
        if (orderValue.compareTo(new BigDecimal("10000.00")) < 0) {
            log.info("Under fallback rules, order value < $10k is auto-approved during outage.");
            return new CreditCheckResponse(true, orderValue, "APPROVED_BY_FALLBACK_STRATEGY");
        }
        return new CreditCheckResponse(false, BigDecimal.ZERO, "OUTAGE_LIMIT_EXCEEDED: " + ex.getMessage());
    }

    private record CreditCheckRequest(String customerId, BigDecimal amount) {}
}
