package com.enterprise.orderservice.service;

import com.enterprise.orderservice.controller.dto.OrderCreationRequest;
import com.enterprise.orderservice.controller.dto.OrderItemDto;
import com.enterprise.orderservice.domain.Order;
import com.enterprise.orderservice.integration.LegacyErpClient;
import com.enterprise.orderservice.repository.OrderRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.math.BigDecimal;

@Service
public class OrderService {

    private final OrderRepository orderRepository;
    private final LegacyErpClient legacyErpClient;

    public OrderService(OrderRepository orderRepository, LegacyErpClient legacyErpClient) {
        this.orderRepository = orderRepository;
        this.legacyErpClient = legacyErpClient;
    }

    @Transactional
    public Order processOrder(OrderCreationRequest request) {
        // 1. Calculate Total cleanly and with strict scale scale safety (BigDecimal)
        BigDecimal total = request.items().stream()
                .map(item -> item.unitPrice().multiply(BigDecimal.valueOf(item.quantity())))
                .reduce(BigDecimal.ZERO, BigDecimal::add);

        // 2. Persist order in PENDING status
        Order order = new Order(request.correlationId(), request.customerId(), total);
        order = orderRepository.save(order);

        // 3. Integrate with legacy ERP System
        LegacyErpClient.CreditCheckResponse creditStatus = legacyErpClient.verifyCustomerCredit(
                order.getCustomerId(), 
                order.getTotalAmount()
        );

        // 4. Handle State updates safely based on integration result
        if (creditStatus.approved()) {
            order.updateStatus(Order.OrderStatus.COMPLETED);
        } else {
            order.updateStatus(Order.OrderStatus.FAILED_CREDIT_CHECK);
        }

        return orderRepository.save(order);
    }
}
