### 6. Robust Enterprise Error Handler (RFC 7807)

Rather than leaking stack traces or raw exceptions, we map compile-time/runtime failures into the globally recognized **RFC 7807 (Problem Details for HTTP APIs)** schema.

```java
package com.enterprise.orderservice.exception;

import org.springframework.http.HttpStatus;
import org.springframework.http.ProblemDetail;
import org.springframework.web.bind.MethodArgumentNotValidException;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;

import java.net.URI;
import java.time.Instant;
import java.util.List;
import java.util.Map;

@RestControllerAdvice
public class GlobalExceptionHandler {

    // Handles validation violations (e.g. invalid SKU format, missing correlation ID)
    @ExceptionHandler(MethodArgumentNotValidException.class)
    public ProblemDetail handleValidationErrors(MethodArgumentNotValidException ex) {
        ProblemDetail problemDetail = ProblemDetail.forStatusAndDetail(
                HttpStatus.BAD_REQUEST, 
                "Input payload validation failed."
        );
        problemDetail.setTitle("Invalid Request Payload");
        problemDetail.setType(URI.create("https://api.corp.internal/errors/bad-request"));

        // Collate validation exceptions into a safe metadata structure
        List<Map<String, String>> errors = ex.getBindingResult().getFieldErrors().stream()
                .map(err -> Map.of("field", err.getField(), "message", err.getDefaultMessage()))
                .toList();

        problemDetail.setProperty("errors", errors);
        problemDetail.setProperty("timestamp", Instant.now());
        return problemDetail;
    }

    // Catches legacy structural failures
    @ExceptionHandler(LegacySystemException.class)
    public ProblemDetail handleLegacySystemFailure(LegacySystemException ex) {
        ProblemDetail problemDetail = ProblemDetail.forStatusAndDetail(
                HttpStatus.SERVICE_UNAVAILABLE, 
                ex.getMessage()
        );
        problemDetail.setTitle("Legacy System Integration Timeout");
        problemDetail.setType(URI.create("https://api.corp.internal/errors/legacy-failure"));
        problemDetail.setProperty("timestamp", Instant.now());
        return problemDetail;
    }
}
