### 4. Core Service Orchestration

The service contains the core business logic. Notice the pattern matching using Java 21’s `switch` expression to handle `TransactionEvent` types cleanly.

```java
package com.enterprise.finance.service;

import com.enterprise.finance.domain.*;
import com.enterprise.finance.integration.LegacyMainframeGateway;
import com.enterprise.finance.integration.LegacyValidationResult;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.Instant;
import java.util.UUID;

@Service
public class TransactionProcessor {
    private static final Logger log = LoggerFactory.getLogger(TransactionProcessor.class);
    private final LegacyMainframeGateway mainframeGateway;

    public TransactionProcessor(LegacyMainframeGateway mainframeGateway) {
        this.mainframeGateway = mainframeGateway;
    }

    @Transactional
    public TransactionEvent process(AccountId source, AccountId destination, Money amount) {
        TransactionId txId = new TransactionId(UUID.randomUUID().toString());
        log.info("Initiating transaction {} between {} and {}", txId.value(), source.value(), destination.value());

        // Call the legacy mainframe gateway safely
        LegacyValidationResult validation = mainframeGateway.verifyLedgerState(source, amount);

        if (!validation.isLiquid()) {
            return new TransactionEvent.Rejected(
                txId, source, "Insufficient liquidity in Legacy Mainframe Core.", Instant.now()
            );
        }

        // Commit transaction to Mainframe ledger
        mainframeGateway.postLedgerEntry(source, destination, amount);

        return new TransactionEvent.Approved(
            txId, source, destination, amount, validation.mainframeStatusId(), Instant.now()
        );
    }

    // Demonstrating Java 21 Exhaustive Switch Pattern Matching for Event Handlers
    public void dispatchEvent(TransactionEvent event) {
        switch (event) {
            case TransactionEvent.Approved approved -> {
                log.info("Dispatching TRANSACTION_APPROVED to Kafka. Mainframe Conf Code: {}", 
                    approved.confirmationCode());
                // integration with Spring Kafka would occur here
            }
            case TransactionEvent.Rejected rejected -> {
                log.warn("Dispatching TRANSACTION_REJECTED to Kafka. Reason: {}", 
                    rejected.reason());
                // integration with Enterprise Alerting systems here
            }
        } // No 'default' block is needed! The compiler guarantees we handled all 'permits' options.
    }
}
```

