```java
package com.enterprise.finance.web;

import com.enterprise.finance.domain.*;
import com.enterprise.finance.service.TransactionProcessor;
import jakarta.validation.Valid;
import jakarta.validation.constraints.DecimalMin;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

import java.math.BigDecimal;
import java.util.Currency;

@RestController
@RequestMapping("/api/v1/transactions")
public class TransactionController {

    private final TransactionProcessor processor;

    public TransactionController(TransactionProcessor processor) {
        this.processor = processor;
    }

    @PostMapping
    public ResponseEntity<TransactionResponse> executeTransaction(
            @Valid @RequestBody TransactionRequest request) {

        // 1. Strict conversion from insecure API primitives to validated Domain Primitives
        AccountId sourceAcc = new AccountId(request.sourceAccount());
        AccountId destAcc = new AccountId(request.destinationAccount());
        Money amount = new Money(request.amount(), Currency.getInstance(request.currency()));

        // 2. Business Process execution
        TransactionEvent result = processor.process(sourceAcc, destAcc, amount);

        // 3. Dispatch enterprise event asynchronously (Kafka/Rabbit)
        processor.dispatchEvent(result);

        // 4. Return type-safe REST Response utilizing pattern matching
        return switch (result) {
            case TransactionEvent.Approved app -> ResponseEntity.ok(
                new TransactionResponse(app.transactionId().value(), "COMPLETED", app.confirmationCode(), null)
            );
            case TransactionEvent.Rejected rej -> ResponseEntity.badRequest().body(
                new TransactionResponse(rej.transactionId().value(), "FAILED", null, rej.reason())
            );
        };
    }
}

