```java
package com.enterprise.ledger.integration.legacy_cis;

import com.enterprise.ledger.domain.model.CorporateCustomerProfile;
import com.enterprise.ledger.domain.model.CustomerRiskStatus;
import org.springframework.stereotype.Component;
import java.util.Optional;

/**
 * Gateway adapter to communicate with a Legacy SOAP/XML Customer Information System (CIS).
 * It abstracts XML parsing, legacy connection timeouts, and converts legacy codes into modern Enums.
 */
@Component
public class LegacyCisClientAdapter {

    // Simulating communication over SOAP/gRPC or Legacy JDBC
    public Optional<CorporateCustomerProfile> fetchCustomerProfile(String taxId) {
        try {
            // Raw simulation of a legacy system call returning a flat SOAP payload
            LegacySoapResponse legacyResponse = callLegacySoapService(taxId);

            if (legacyResponse == null) {
                return Optional.empty();
            }

            // Map fragile, legacy string codes directly into strict modern Types/Enums
            CustomerRiskStatus riskStatus = switch (legacyResponse.riskCode()) {
                case "01" -> CustomerRiskStatus.LOW_RISK;
                case "02", "03" -> CustomerRiskStatus.HIGH_RISK;
                default -> CustomerRiskStatus.BLOCKED;
            };

            return Optional.of(new CorporateCustomerProfile(
                legacyResponse.taxNumber(),
                riskStatus,
                "Y".equalsIgnoreCase(legacyResponse.activeFlag())
            ));

        } catch (Exception e) {
            // Production systems should wrap legacy timeouts/socket exceptions safely
            throw new LegacyIntegrationException("Legacy CIS system unreachable", e);
        }
    }

    private LegacySoapResponse callLegacySoapService(String taxId) {
        // Simulated legacy payload response
        return new LegacySoapResponse(taxId, "01", "Y");
    }

    // Inner class mimicking the old XML representation
    private record LegacySoapResponse(String taxNumber, String riskCode, String activeFlag) {}
}
