```java
package com.enterprise.ledger.domain;

import com.enterprise.ledger.domain.exception.TransactionRejectedException;
import com.enterprise.ledger.domain.model.*;
import com.enterprise.ledger.integration.legacy_cis.LegacyCisClientAdapter;
import org.springframework.stereotype.Service;

@Service
public class TransactionValidationService {

    private final LegacyCisClientAdapter legacyCisClient;

    public TransactionValidationService(LegacyCisClientAdapter legacyCisClient) {
        this.legacyCisClient = legacyCisClient;
    }

    public void validateTransaction(AccountId sourceAccount, Money transferAmount, String customerTaxId) {
        // 1. Strict validation against Legacy Customer Information System
        CorporateCustomerProfile customer = legacyCisClient.fetchCustomerProfile(customerTaxId)
            .orElseThrow(() -> new TransactionRejectedException("Customer profile not found in Legacy CIS system."));

        if (!customer.isActive()) {
            throw new TransactionRejectedException("Transaction rejected: Account holder's status is inactive in legacy registry.");
        }

        if (customer.riskStatus() == CustomerRiskStatus.BLOCKED) {
            throw new TransactionRejectedException("Transaction rejected: Customer status flagged as BLOCKED.");
        }

        // 2. Strict Domain Rule
        if (transferAmount.amount().compareTo(java.math.BigDecimal.ZERO) <= 0) {
            throw new TransactionRejectedException("Transaction amount must be strictly positive.");
        }
    }
}
