        @Valid @RequestBody PostTransactionRequest request
    ) {
        log.info("Received transaction request for account: {}", request.sourceAccountId());

        // Parse primitives safely into our strict domain types
        AccountId accountId = new AccountId(request.sourceAccountId());
        Money money = new Money(request.amount(), Currency.getInstance(request.currency()));

        // Execute domain rules combined with legacy systems checks
        validationService.validateTransaction(accountId, money, request.customerTaxId());

        // Respond with a structured JSON response mapping
        return ResponseEntity.ok(Map.of(
            "status", "APPROVED",
            "accountId", accountId.value(),
            "amount", money.amount(),
            "currency", money.currency().getCurrencyCode()
        ));
    }
}
