```java
package com.enterprise.service.infrastructure;

import com.enterprise.service.domain.CorporateEmployee;
import com.enterprise.service.domain.CorporateRegistryPort;
import com.enterprise.service.domain.Department;
import com.enterprise.service.domain.EmployeeId;
import org.springframework.stereotype.Component;

import java.util.Map;
import java.util.Optional;

@Component
public class LegacySoapRegistryAdapter implements CorporateRegistryPort {

    // Simulating a legacy mainframe/database database with string-ly typed nulls
    private static final Map<String, Map<String, String>> LEGACY_DATABASE = Map.of(
        "EMP-1001", Map.of("NAME", "Jane Doe", "DEPT", "ENGINEERING", "EMAIL", "jdoe@corp.local"),
        "EMP-1002", Map.of("NAME", "John Smith", "DEPT", "FINANCE", "EMAIL", "jsmith@corp.local")
    );

    @Override
    public Optional<CorporateEmployee> fetchEmployeeById(EmployeeId id) {
        Map<String, String> rawLegacyData = LEGACY_DATABASE.get(id.value());

        if (rawLegacyData == null) {
            return Optional.empty();
        }

        try {
            // Strict type conversion and validation of raw legacy data
            String name = Optional.ofNullable(rawLegacyData.get("NAME"))
                    .orElseThrow(() -> new IllegalStateException("Legacy system returned missing Name"));

            String email = Optional.ofNullable(rawLegacyData.get("EMAIL"))
                    .orElseThrow(() -> new IllegalStateException("Legacy system returned missing Email"));

            Department dept;
            try {
                dept = Department.valueOf(rawLegacyData.get("DEPT"));
            } catch (IllegalArgumentException | NullPointerException e) {
                dept = Department.UNKNOWN; // Safely handle unexpected legacy structural changes
            }

            // Successfully map to our type-safe Domain Object
            return Optional.of(new CorporateEmployee(id, name, email, dept));

        } catch (Exception ex) {
            // In production, log integration error to APM system
            return Optional.empty();
        }
    }
}
```

