#### 3. Enterprise Integration (Legacy ERP Gateway)
This component integrates with an old SAP/ERP system via REST. It maps legacy raw JSON into strict internal types.

```java
package com.enterprise.processor.integration;

import com.enterprise.processor.domain.AccountId;
import com.enterprise.processor.domain.Money;
import org.springframework.stereotype.Component;
import org.springframework.web.client.RestClient;
import org.springframework.http.MediaType;

@Component
public class LegacyErpClient {
    private final RestClient restClient;

    // In production, the base URL is injected from corporate Vault/Config Server
    public LegacyErpClient(RestClient.Builder restClientBuilder) {
        this.restClient = restClientBuilder.baseUrl("https://legacy-erp.internal.corp/api/v1").build();
    }

    // Strongly-typed request/response records for the legacy system
    public record ErpLedgerRequest(String fromAcc, String toAcc, double value, String curr) {}
    public record ErpLedgerResponse(String ledgerRefId, String status) {}

    public String postToLegacyLedger(AccountId source, AccountId target, Money money) {
        try {
            ErpLedgerRequest payload = new ErpLedgerRequest(
                source.value(), 
                target.value(), 
                money.amount().doubleValue(), 
                money.currency()
            );

            ErpLedgerResponse response = restClient.post()
                .uri("/ledger/post")
                .contentType(MediaType.APPLICATION_JSON)
                .body(payload)
                .retrieve()
                .body(ErpLedgerResponse.class);

            if (response == null || !"SUCCESS".equalsIgnoreCase(response.status())) {
                throw new RuntimeException("Legacy ERP rejected the transaction");
            }

            return response.ledgerRefId();
        } catch (Exception e) {
            throw new LegacyIntegrationException("Failed to communicate with Legacy ERP system", e);
        }
    }
}
```

#### 4. Core Business Service
Orchestrates the transaction, ensuring atomic updates (`@Transactional`).

```java
package com.enterprise.processor.service;

import com.enterprise.processor.domain.AccountId;
import com.enterprise.processor.domain.Money;
import com.enterprise.processor.entity.TransactionEntity;
import com.enterprise.processor.integration.LegacyErpClient;
import com.enterprise.processor.repository.TransactionRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.Instant;
import java.util.UUID;

@Service
public class TransactionService {

    private final TransactionRepository repository;
    private final LegacyErpClient erpClient;

    public TransactionService(TransactionRepository repository, LegacyErpClient erpClient) {
        this.repository = repository;
        this.erpClient = erpClient;
    }

    @Transactional // Enforces ACID compliance across DB operations
    public UUID process(AccountId source, AccountId target, Money money) {
        // 1. Register with Legacy Corporate System
        String erpRef = erpClient.postToLegacyLedger(source, target, money);

        // 2. Persist in local Microservice DB
        UUID localId = UUID.randomUUID();
        TransactionEntity entity = new TransactionEntity(
            localId,
            source.value(),
            target.value(),
            money.amount(),
            money.currency(),
            erpRef,
            Instant.now()
        );
        repository.save(entity);

        return localId;
    }
}
```

#### 5. Presentation Layer (Strict Controller Validation)
Handles incoming requests, utilizing automatic type-safety validation annotations (`jakarta.validation`).

```java
package com.enterprise.processor.controller;

import com.enterprise.processor.domain.AccountId;
import com.enterprise.processor.domain.Money;
import com.enterprise.processor.service.TransactionService;
import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Positive;
import jakarta.validation.constraints.Size;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

import java.math.BigDecimal;
import java.util.UUID;

@RestController
@RequestMapping("/api/transactions")
public class TransactionController {

    private final TransactionService transactionService;

    public TransactionController(TransactionService transactionService) {
        this.transactionService = transactionService;
    }

    // Strictly validated DTO
    public record TransactionRequest(
        @NotBlank @Size(min = 5, max = 20) String sourceAccountId,
        @NotBlank @Size(min = 5, max = 20) String targetAccountId,
        @NotNull @Positive BigDecimal amount,
        @NotBlank @Size(min = 3, max = 3) String currency
    ) {}

    public record TransactionResponse(UUID transactionId, String status) {}

    @PostMapping
    public ResponseEntity<TransactionResponse> executeTransaction(
            @Valid @RequestBody TransactionRequest request) {

        // Safe conversion of input types to strong Domain Types
        AccountId source = new AccountId(request.sourceAccountId());
        AccountId target = new AccountId(request.targetAccountId());
        Money money = new Money(request.amount(), request.currency());

        UUID txId = transactionService.process(source, target, money);

        return ResponseEntity.ok(new TransactionResponse(txId, "COMPLETED"));
    }
}
```

#### 6. Enterprise Global Error Handler
Ensures no internal system details or stack traces are leaked, formatting errors to meet enterprise standards.

```java
package com.enterprise.processor.exception;

import org.springframework.http.HttpStatus;
import org.springframework.http.ProblemDetail;
import org.springframework.web.bind.MethodArgumentNotValidException;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;

import java.net.URI;
import java.time.Instant;

@RestControllerAdvice
public class GlobalExceptionHandler {

    // Catch type safety/validation failures on incoming requests
    @ExceptionHandler(MethodArgumentNotValidException.class)
    public ProblemDetail handleValidationErrors(MethodArgumentNotValidException ex) {
        ProblemDetail problemDetail = ProblemDetail.forStatusAndDetail(
            HttpStatus.BAD_REQUEST, 
            "Invalid request payload"
        );
        problemDetail.setTitle("Constraint Violation");
        problemDetail.setProperty("timestamp", Instant.now());
        return problemDetail;
    }

    // Catch corporate integration failures gracefully
    @ExceptionHandler(com.enterprise.processor.integration.LegacyIntegrationException.class)
    public ProblemDetail handleLegacyIntegrationError(Exception ex) {
        ProblemDetail problemDetail = ProblemDetail.forStatusAndDetail(
            HttpStatus.BAD_GATEWAY, 
            "Downstream Enterprise ERP System returned an error. Action halted."
        );
        problemDetail.setTitle("Integration Failure");
        problemDetail.setProperty("timestamp", Instant.now());
        return problemDetail;
    }
}
```

