    private static final Logger log = LoggerFactory.getLogger(AccountService.class);
    private final LegacyErpGateway erpGateway;

    // Dependency Injection enforced via constructor
    public AccountService(LegacyErpGateway erpGateway) {
        this.erpGateway = erpGateway;
    }

    public AccountResponse createAccount(AccountRequest request) {
        log.info("Processing account creation request for: {}", request.companyName());

        // Step 1: Query legacy system to validate customer status (Strict Type check)
        ErpCustomerDto erpData = erpGateway.fetchCustomerDetails(request.legacyErpId());

        String syncStatus = erpData.isActiveCredit() ? "SYNCED_ACTIVE" : "SYNCED_CREDIT_HOLD";

        // Step 2: In a real system, you would map and save to local DB (e.g., PostgreSQL)
        UUID generatedId = UUID.randomUUID();

        log.info("Successfully registered local account {} linked with Legacy ERP", generatedId);
        return new AccountResponse(
                generatedId,
                request.companyName(),
                request.corporateEmail(),
                syncStatus,
                Instant.now()
        );
    }
}

