@RestControllerAdvice
class GlobalExceptionHandler {

    private static final Logger log = LoggerFactory.getLogger(GlobalExceptionHandler.class);

    /**
     * Catches validation failures at the JSON boundary (Strict Type Enforcements).
     */
    @ExceptionHandler(MethodArgumentNotValidException.class)
    public ResponseEntity<ProblemDetail> handleValidationErrors(MethodArgumentNotValidException ex) {
        ProblemDetail problemDetail = ProblemDetail.forStatusAndDetail(HttpStatus.BAD_REQUEST, "Validation failed");
        problemDetail.setTitle("Invalid Request Payload");

        // Collect errors strongly
        var errors = ex.getBindingResult().getFieldErrors().stream()
                .map(err -> "%s: %s".formatted(err.getField(), err.getDefaultMessage()))
                .toList();

        problemDetail.setProperty("errors", errors);
        return ResponseEntity.of(problemDetail).build();
    }

    /**
     * Catches legacy integration issues, shielding internal stack traces 
     * from external clients while logging details for operations teams.
     */
    @ExceptionHandler(ErpIntegrationException.class)
    public ResponseEntity<ProblemDetail> handleErpIntegrationError(ErpIntegrationException ex) {
        log.error("Enterprise Integration Error occurred: {}", ex.getMessage());

        ProblemDetail problemDetail = ProblemDetail.forStatusAndDetail(
                HttpStatus.BAD_GATEWAY, 
                "The corporate ERP system could not process this request."
        );
        problemDetail.setTitle("Legacy System Integration Failure");
        return ResponseEntity.of(problemDetail).build();
    }
}
