### 2. Complete Microservice Implementation (`Application.kt`)

Below is the complete, production-grade, minimal microservice. It showcases:
1.  **Defensive Type Mapping:** Transforming dirty/nullable legacy API data into strictly typed, non-nullable domain models immediately at the integration boundary.
2.  **Type-Safe Error Handling:** Using Kotlin `sealed interfaces` instead of throwing unchecked runtime exceptions.
3.  **Exhaustive Compile-Time Checks:** Ensuring all business logic paths and errors are explicitly handled.

```kotlin
package com.enterprise.service

import org.springframework.boot.autoconfigure.SpringBootApplication
import org.springframework.boot.runApplication
import org.springframework.context.annotation.Bean
import org.springframework.context.annotation.Configuration
import org.springframework.http.HttpStatus
import org.springframework.http.ResponseEntity
import org.springframework.stereotype.Component
import org.springframework.stereotype.Service
import org.springframework.web.bind.annotation.*
import org.springframework.web.client.RestClient
import org.springframework.web.client.body

@SpringBootApplication
class Application

fun main(args: Array<String>) {
    runApplication<Application>(*args)
}

// ==========================================
// 1. STRICT DOMAIN TYPES
// ==========================================
enum class SecurityClearance {
    PUBLIC, INTERNAL, RESTRICTED, TOP_SECRET
}

// Immutable, non-nullable domain model
data class Employee(
    val id: String,
    val email: String,
    val clearance: SecurityClearance,
    val isActive: Boolean
)

// ==========================================
// 2. TYPE-SAFE ERROR/RESULT REPRESENTATION
// ==========================================
// By using a sealed interface, the compiler forces us to handle all possible outcomes.
sealed interface ServiceResult<out T> {
    data class Success<out T>(val value: T) : ServiceResult<T>

    sealed interface Failure : ServiceResult<Nothing> {
        data class LegacySystemError(val message: String) : Failure
        data class EmployeeNotFound(val id: String) : Failure
        data class AccessDenied(val reason: String) : Failure
    }
}

// ==========================================
// 3. ENTERPRISE INTEGRATION LAYER (Legacy ERP Gateway)
// ==========================================
// Unstable, loosely-typed legacy response model
data class LegacyErpUserDto(
    val ERP_ID: String?,
    val EMAIL_ADDR: String?,
    val SEC_LEVEL: String?, // "LVL_1", "LVL_2", etc.
    val STATUS_FLAG: Int?   // 1 = Active, 0 = Inactive
)

@Component
class LegacyErpClient(private val restClient: RestClient) {

    fun fetchUser(employeeId: String): ServiceResult<Employee> {
        return try {
            // Simulating HTTP GET to legacy corporate mainframe/ERP
            val rawResponse = restClient.get()
                .uri("/legacy/users/{id}", employeeId)
                .retrieve()
                .body<LegacyErpUserDto>()

            // Strict Null-Safety and Parsing validation at the boundary
            if (rawResponse?.ERP_ID == null || rawResponse.EMAIL_ADDR == null) {
                return ServiceResult.Failure.EmployeeNotFound(employeeId)
            }

            // Map fragile legacy schema into our strict domain types
            val domainEmployee = Employee(
                id = rawResponse.ERP_ID,
                email = rawResponse.EMAIL_ADDR,
                clearance = when (rawResponse.SEC_LEVEL) {
                    "LVL_4" -> SecurityClearance.TOP_SECRET
                    "LVL_3" -> SecurityClearance.RESTRICTED
                    "LVL_2" -> SecurityClearance.INTERNAL
                    else -> SecurityClearance.PUBLIC
                },
                isActive = rawResponse.STATUS_FLAG == 1
            )

            ServiceResult.Success(domainEmployee)
        } catch (ex: Exception) {
            // Capture runtime exceptions and map them to a typed Failure object
            ServiceResult.Failure.LegacySystemError("ERP Connection Failed: ${ex.message}")
        }
    }
}

// ==========================================
// 4. SERVICE / BUSINESS LOGIC LAYER
// ==========================================
@Service
class AccessControlService(private val erpClient: LegacyErpClient) {

    fun verifyAccessToResource(employeeId: String, requiredClearance: SecurityClearance): ServiceResult<Employee> {
        // Monadic-like flow utilizing our sealed Result types
        return when (val erpResult = erpClient.fetchUser(employeeId)) {
            is ServiceResult.Failure -> erpResult // Propagate integration failure up
            is ServiceResult.Success -> {
                val employee = erpResult.value

                if (!employee.isActive) {
                    return ServiceResult.Failure.AccessDenied("Employee account is inactive.")
                }

                if (employee.clearance < requiredClearance) {
                    return ServiceResult.Failure.AccessDenied("Insufficient clearance. Required: $requiredClearance")
                }

                ServiceResult.Success(employee)
            }
        }
    }
}

// ==========================================
// 5. API CONTROLLER LAYER
// ==========================================
@RestController
@RequestMapping("/api/v1/access")
class AccessController(private val accessService: AccessControlService) {

    @GetMapping("/verify")
    fun verifyAccess(
        @RequestParam empId: String,
        @RequestParam requiredClearance: SecurityClearance
    ): ResponseEntity<Any> {

        val result = accessService.verifyAccessToResource(empId, requiredClearance)

        // The compiler enforces that we check ALL branches of ServiceResult.
        // Forgetting to handle a failure branch will result in a compile-time error.
        return when (result) {
            is ServiceResult.Success -> 
                ResponseEntity.ok(result.value)

            is ServiceResult.Failure.EmployeeNotFound -> 
                ResponseEntity.status(HttpStatus.NOT_FOUND).body(MapResponse("Employee not found in legacy system."))

            is ServiceResult.Failure.AccessDenied -> 
                ResponseEntity.status(HttpStatus.FORBIDDEN).body(MapResponse(result.reason))

            is ServiceResult.Failure.LegacySystemError -> 
                ResponseEntity.status(HttpStatus.BAD_GATEWAY).body(MapResponse(result.message))
        }
    }

    private fun MapResponse(message: String) = mapOf("message" to message)
}

