// 6. INFRASTRUCTURE CONFIGURATION
// ==========================================
@Configuration
class AppConfig {
    @Bean
    fun restClient(): RestClient {
        // Configure corporate timeouts and Base URL
        return RestClient.builder()
            .baseUrl("https://legacy-erp.corporate.local/api")
            .build()
    }
}
