```java
package com.enterprise.employee;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Pattern;
import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.stereotype.Component;
import org.springframework.stereotype.Service;
import org.springframework.web.bind.annotation.*;

import java.util.Map;

@SpringBootApplication
public class EmployeeServiceApplication {
    public static void main(String[] args) {
        SpringApplication.run(EmployeeServiceApplication.class, args);
    }
}

// ==========================================
// 1. DOMAIN LAYER (Strictly Typed & Immutable)
// ==========================================
enum Department {
    ENGINEERING, HR, FINANCE, LEGAL
}

// Records guarantee thread-safe immutability
record Employee(
    String id,
    String email,
    Department department
) {}

// Input validation record for the API boundary
record OnboardRequest(
    @NotBlank(message = "Employee ID is required")
    @Pattern(regexp = "^EMP-\\d{4}$", message = "Invalid Employee ID format (Expected: EMP-XXXX)")
    String employeeId,

    @NotBlank(message = "Department is required")
    String department
) {}

// ==========================================
// 2. INTEGRATION LAYER (Legacy Gateway)
// ==========================================

// Sealed interface enforces compilation-time checks on all integration results
sealed interface LegacySystemResponse permits 
    LegacySystemResponse.Success, 
    LegacySystemResponse.ConnectionTimeout, 
    LegacySystemResponse.RecordNotFound {}

interface LegacySystemResponse {
    record Success(String rawPayload) implements LegacySystemResponse {}
    record ConnectionTimeout(String errorMessage) implements LegacySystemResponse {}
    record RecordNotFound() implements LegacySystemResponse {}
}

@Component
class LegacyCorporateGateway {
    /**
     * Simulates fetching unstructured/raw data from an old Mainframe or SOAP service.
     */
    public LegacySystemResponse fetchRawEmployeeData(String id) {
        // Mocking integration behavior based on ID
        return switch (id) {
            case "EMP-1234" -> new LegacySystemResponse.Success("ID:1234;EMAIL:alice@enterprise.com;DEPT:ENGINEERING");
            case "EMP-9999" -> new LegacySystemResponse.RecordNotFound();
            default -> new LegacySystemResponse.ConnectionTimeout("Mainframe connection socket read timeout");
        };
    }
}

// ==========================================
// 3. BUSINESS LOGIC LAYER
// ==========================================
@Service
class EmployeeService {
    private final LegacyCorporateGateway legacyGateway;

    public EmployeeService(LegacyCorporateGateway legacyGateway) {
        this.legacyGateway = legacyGateway;
    }

    public Employee onboardEmployee(OnboardRequest request) {
        // Fetch legacy data using the gateway
        LegacySystemResponse response = legacyGateway.fetchRawEmployeeData(request.employeeId());

        // STRICT TYPE SAFETY: Modern Java 'switch expressions' with pattern matching.
        // The compiler forces us to handle SUCCESS, TIMEOUT, and NOTFOUND. 
        // If we omit one, the code will not compile.
        return switch (response) {
            case LegacySystemResponse.Success success -> {
                yield parseLegacyPayload(request.employeeId(), success.rawPayload());
            }
            case LegacySystemResponse.RecordNotFound ignored -> 
                throw new CorporateSystemException("Employee " + request.employeeId() + " does not exist in Legacy Active Directory", HttpStatus.NOT_FOUND);
            case LegacySystemResponse.ConnectionTimeout timeout -> 
                throw new CorporateSystemException("Legacy Mainframe offline: " + timeout.errorMessage(), HttpStatus.GATEWAY_TIMEOUT);
        };
    }

    private Employee parseLegacyPayload(String id, String raw) {
        try {
            // Type-safe translation of unstructured legacy data to strongly-typed internal Domain
            Map<String, String> parts = Map.of(
                "EMAIL", raw.split(";")[1].split(":")[1],
                "DEPT", raw.split(";")[2].split(":")[1]
            );
            return new Employee(
                id, 
                parts.get("EMAIL"), 
                Department.valueOf(parts.get("DEPT"))
            );
        } catch (Exception ex) {
            throw new CorporateSystemException("Failed to parse corrupt legacy system payload", HttpStatus.INTERNAL_SERVER_ERROR);
        }
    }
}

// ==========================================
// 4. REST CONTROLLER / API BOUNDARY
// ==========================================
@RestController
@RequestMapping("/api/v1/employees")
class EmployeeController {

    private final EmployeeService employeeService;

    public EmployeeController(EmployeeService employeeService) {
        this.employeeService = employeeService;
    }

    @PostMapping("/onboard")
    public ResponseEntity<Employee> onboard(@Valid @RequestBody OnboardRequest request) {
        // @Valid ensures only strictly structured data passes past this boundary
        Employee onboarded = employeeService.onboardEmployee(request);
        return ResponseEntity.status(HttpStatus.CREATED).body(onboarded);
    }
}

// ==========================================
// 5. GLOBAL ENTERPRISE EXCEPTION HANDLING
// ==========================================
@ControllerAdvice
class GlobalExceptionHandler {

    record ErrorResponse(String errorCode, String message, long timestamp) {}

    @ExceptionHandler(CorporateSystemException.class)
    public ResponseEntity<ErrorResponse> handleCorporateException(CorporateSystemException ex) {
        return ResponseEntity
            .status(ex.getStatus())
            .body(new ErrorResponse("CORP_INTEGRATION_ERROR", ex.getMessage(), System.currentTimeMillis()));
    }

    @ExceptionHandler(org.springframework.web.bind.MethodArgumentNotValidException.class)
    public ResponseEntity<ErrorResponse> handleValidationException(Exception ex) {
        return ResponseEntity
            .status(HttpStatus.BAD_REQUEST)
            .body(new ErrorResponse("INVALID_PAYLOAD_STRUCTURE", "Request data violates type restrictions", System.currentTimeMillis()));
    }
}

class CorporateSystemException extends RuntimeException {
    private final HttpStatus status;
    public CorporateSystemException(String message, HttpStatus status) {
        super(message);
        this.status = status;
    }
    public HttpStatus getStatus() { return status; }
}
```

