### 2. `Program.cs`
The entry point of the application. It configures Azure Key Vault using **DefaultAzureCredential** (which uses Managed Identity in production and developer credentials in Visual Studio/local Windows environment), sets up Azure AD authentication, and registers Application Insights.

```csharp
using Azure.Identity;
using Microsoft.AspNetCore.Authentication.JwtBearer;
using Microsoft.EntityFrameworkCore;
using Microsoft.Identity.Web;
using EnterpriseService.Data;

var builder = WebApplication.CreateBuilder(args);

// 1. Configure Azure Key Vault securely using Managed Identity (no passwords in code)
if (!builder.Environment.IsDevelopment())
{
    var keyVaultUri = builder.Configuration["KeyVault:VaultUri"];
    builder.Configuration.AddAzureKeyVault(new Uri(keyVaultUri!), new DefaultAzureCredential());
}

// 2. Configure Azure Application Insights for enterprise telemetry and logging
builder.Services.AddApplicationInsightsTelemetry(options =>
{
    options.ConnectionString = builder.Configuration["ApplicationInsights:ConnectionString"];
});

// 3. Configure Enterprise Identity (Microsoft Entra ID / Azure AD)
builder.Services.AddAuthentication(JwtBearerDefaults.AuthenticationScheme)
    .AddMicrosoftIdentityWebApi(builder.Configuration.GetSection("AzureAd"));

builder.Services.AddAuthorization(options =>
{
    // Define an enterprise policy requiring specific App Roles or Scopes
    options.AddPolicy("ReadScope", policy => policy.RequireClaim("http://schemas.microsoft.com/identity/claims/scope", "Employees.Read"));
});

// 4. Configure Azure SQL Database Context
// Note: "SqlConnectionString" is fetched securely from Azure Key Vault at runtime
var connectionString = builder.Configuration["SqlConnectionString"]; 
builder.Services.AddDbContext<EnterpriseDbContext>(options =>
    options.UseSqlServer(connectionString, sqlOptions => 
    {
        // Enterprise resiliency: Auto-retry on transient Azure SQL network failures
        sqlOptions.EnableRetryOnFailure(
            maxRetryCount: 5,
            maxRetryDelay: TimeSpan.FromSeconds(10),
            errorNumbersToAdd: null);
    }));

builder.Services.AddControllers();
builder.Services.AddEndpointsApiExplorer();
builder.Services.AddSwaggerGen(); // For API documentation

var app = builder.Build();

// Configure the HTTP request pipeline
if (app.Environment.IsDevelopment())
{
    app.UseSwagger();
    app.UseSwaggerUI();
}

app.UseHttpsRedirection();

// Enforce Azure AD Authentication and Authorization globally
app.UseAuthentication();
app.UseAuthorization();

app.MapControllers();

app.Run();
