```csharp
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using EnterpriseService.Data;
using EnterpriseService.Models;

namespace EnterpriseService.Controllers;

[Authorize] // Requires valid Azure AD JWT Token
[ApiController]
[Route("api/[controller]")]
public class EmployeesController : ControllerBase
{
    private readonly EnterpriseDbContext _context;
    private readonly ILogger<EmployeesController> _logger;

    public EmployeesController(EnterpriseDbContext context, ILogger<EmployeesController> logger)
    {
        _context = context;
        _logger = logger;
    }

    // GET: api/employees
    [HttpGet]
    [Authorize(Policy = "ReadScope")] // Requires specific scope defined in Azure AD
    public async Task<ActionResult<IEnumerable<Employee>>> GetEmployees()
    {
        _logger.LogInformation("Enterprise User {User} requested all active employees.", User.Identity?.Name);

        try
        {
            var employees = await _context.Employees
                .Where(e => e.IsActive)
                .AsNoTracking() // Performance optimization for read-only enterprise queries
                .ToListAsync();

            return Ok(employees);
        }
        catch (Exception ex)
        {
            // This error will be fully logged to Azure Application Insights with stack traces
            _logger.LogError(ex, "An error occurred while fetching employee records.");
            return StatusCode(500, "An internal enterprise service error occurred.");
        }
    }

    // POST: api/employees
    [HttpPost]
    public async Task<ActionResult<Employee>> CreateEmployee([FromBody] Employee employee)
