public class EnterpriseDbContext : DbContext
{
    public EnterpriseDbContext(DbContextOptions<EnterpriseDbContext> options) : base(options)
    {
        // For Azure SQL Managed Identity (passwordless configuration)
        var conn = (Microsoft.Data.SqlClient.SqlConnection)Database.GetDbConnection();
        // Generates token automatically when running in Azure App Service with Managed Identity enabled
        var credential = new DefaultAzureCredential();
        var tokenContext = new Azure.Core.TokenRequestContext(new[] { "https://database.windows.net/.default" });
