### 3. Global Exception Handling Middleware (`Middleware/ExceptionHandlingMiddleware.cs`)
Prevents internal stack traces from leaking to clients while ensuring errors are logged directly to Azure Application Insights.

```csharp
using System.Net;
using System.Text.Json;

namespace EnterpriseService.Middleware;

public class ExceptionHandlingMiddleware
{
    private readonly RequestDelegate _next;
    private readonly ILogger<ExceptionHandlingMiddleware> _logger;

    public ExceptionHandlingMiddleware(RequestDelegate next, ILogger<ExceptionHandlingMiddleware> logger)
    {
        _next = next;
        _logger = logger;
    }

    public async Task InvokeAsync(HttpContext context)
    {
        try
        {
            await _next(context);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "An unhandled exception occurred in the enterprise service.");
            await HandleExceptionAsync(context, ex);
        }
    }

    private static Task HandleExceptionAsync(HttpContext context, Exception exception)
    {
        context.Response.ContentType = "application/json";
        context.Response.StatusCode = (int)HttpStatusCode.InternalServerError;

        var response = new
        {
            StatusCode = context.Response.StatusCode,
            Message = "A system error occurred. Please contact IT support with Correlation ID.",
            TraceId = context.TraceIdentifier // Useful for searching logs in App Insights
        };

        return context.Response.WriteAsync(JsonSerializer.Serialize(response));
    }
}
```

