#### 3. Database Context with Passwordless Azure SQL (`Data/AppDbContext.cs`)
In modern Azure environments, storing database passwords in connection strings is a major security risk. This setup uses **Azure Active Directory / Entra ID Managed Identity** to authenticate against Azure SQL dynamically.

```csharp
using Microsoft.EntityFrameworkCore;
using Microsoft.Data.SqlClient;
using Azure.Identity;
using EnterpriseService.Models;

namespace EnterpriseService.Data;

public class AppDbContext : DbContext
{
    public AppDbContext(DbContextOptions<AppDbContext> options) : base(options)
    {
        // For Azure SQL Managed Identity Authentication
        var conn = (SqlConnection)Database.GetDbConnection();

        // If we are running in Azure (App Service/Function) or local VS with Azure Sign-in
        if (!conn.ConnectionString.Contains("Password") && !conn.ConnectionString.Contains("Integrated Security=true"))
        {
            var credential = new DefaultAzureCredential();
            var tokenContext = new TokenRequestContext(new[] { "https://database.windows.net/.default" });
            var token = credential.GetToken(tokenContext);
            conn.AccessToken = token.Token;
        }
    }

    public DbSet<Employee> Employees => Set<Employee>();

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Employee>().HasIndex(e => e.Email).IsUnique();
        base.OnModelCreating(modelBuilder);
    }
}
```

