This controller enforces Microsoft Entra ID token validation and uses structured logging.

```csharp
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using Microsoft.Identity.Web.Resource;
using EnterpriseService.Data;
using EnterpriseService.Models;

namespace EnterpriseService.Controllers;

[Authorize] // Requires Entra ID Authentication
[ApiController]
[Route("api/[controller]")]
public class EmployeesController : ControllerBase
{
    private readonly AppDbContext _context;
    private readonly ILogger<EmployeesController> _logger;

    // Required scope defined in your Azure Entra ID App Registration
    private static readonly string[] RequiredScopes = new[] { "Employees.ReadWrite" };

    public EmployeesController(AppDbContext context, ILogger<EmployeesController> logger)
    {
        _context = context;
        _logger = logger;
    }

    [HttpGet]
    [RequiredScope(RequiredScopesConfigurationKey = "AzureAd:Scopes")]
    public async Task<ActionResult<IEnumerable<Employee>>> GetEmployees()
    {
        _logger.LogInformation("Retrieving all employees from the database.");
        return await _context.Employees.ToListAsync();
    }

    [HttpGet("{id}")]
    public async Task<ActionResult<Employee>> GetEmployee(Guid id)
    {
        var employee = await _context.Employees.FindAsync(id);

        if (employee == null)
        {
            _logger.LogWarning("Employee with ID {Id} not found.", id);
            return NotFound();
        }

        return employee;
    }

    [HttpPost]
    [Authorize(Roles = "Employee.Admin")] // Requires specific Azure AD App Role
    public async Task<ActionResult<Employee>> PostEmployee(Employee employee)
    {
        if (!ModelState.IsValid)
        {
            return BadRequest(ModelState);
        }

        _context.Employees.Add(employee);
        await _context.SaveChangesAsync();

        _logger.LogInformation("Successfully created employee with ID {EmployeeId}", employee.Id);
        return CreatedAtAction(nameof(GetEmployee), new { id = employee.Id }, employee);
    }
}
