### 4. Azure Key Vault Service (`Services/SecretService.cs`)
This service fetches connection strings or API keys securely at runtime, complying with enterprise security audits.

```csharp
using Azure.Security.KeyVault.Secrets;

namespace EnterpriseService.Services;

public interface ISecretService
{
    Task<string> GetSecretAsync(string secretName);
}

public class SecretService : ISecretService
{
    private readonly SecretClient _secretClient;
    private readonly ILogger<SecretService> _logger;

    public SecretService(SecretClient secretClient, ILogger<SecretService> logger)
    {
        _secretClient = secretClient;
        _logger = logger;
    }

    public async Task<string> GetSecretAsync(string secretName)
    {
        try
        {
            _logger.LogInformation("Retrieving secret {SecretName} from Azure Key Vault", secretName);
            KeyVaultSecret secret = await _secretClient.GetSecretAsync(secretName);
            return secret.Value;
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error retrieving secret {SecretName} from Key Vault", secretName);
            throw;
        }
    }
}
```

