    public EnterpriseDbContext(DbContextOptions<EnterpriseDbContext> options) : base(options)
    {
        // For Enterprise Azure SQL, we use Token-based authentication instead of hardcoded passwords
        var conn = (SqlConnection)Database.GetDbConnection();
        var credential = new DefaultAzureCredential();
        var tokenContext = new TokenRequestContext(new[] { "https://database.windows.net/.default" });
        var token = credential.GetToken(tokenContext);
        conn.AccessToken = token.Token;
    }

    public DbSet<Employee> Employees => Set<Employee>();
}
