### 4. Controller (`Controllers/DocumentsController.cs`)
This controller securely saves file metadata to **Azure SQL** and uploads the file stream to **Azure Blob Storage**.

```csharp
using Azure.Storage.Blobs;
using EnterpriseBackend.Data;
using EnterpriseBackend.Models;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using Microsoft.Identity.Web.Resource;

namespace EnterpriseBackend.Controllers;

[Authorize] // Requires Entra ID authentication
[ApiController]
[Route("api/[controller]")]
[RequiredScope("access_as_user")] // Enforces scope from JWT Token
public class DocumentsController : ControllerBase
{
    private readonly AppDbContext _dbContext;
    private readonly BlobServiceClient _blobServiceClient;
    private readonly ILogger<DocumentsController> _logger;
    private const string ContainerName = "enterprise-documents";

    public DocumentsController(
        AppDbContext dbContext, 
        BlobServiceClient blobServiceClient, 
        ILogger<DocumentsController> logger)
    {
        _dbContext = dbContext;
        _blobServiceClient = blobServiceClient;
        _logger = logger;
    }

    [HttpPost("upload")]
    [Consumes("multipart/form-data")]
    public async Task<IActionResult> UploadDocument(IFormFile file)
    {
        if (file == null || file.Length == 0)
            return BadRequest("No file was uploaded.");

        // Extract user identity from Entra ID Token
        var userUpn = User.Identity?.Name ?? "unknown-user";

        try
        {
            // 1. Upload file to Azure Blob Storage
            var containerClient = _blobServiceClient.GetBlobContainerClient(ContainerName);
            await containerClient.CreateIfNotExistsAsync();

            var blobId = Guid.NewGuid();
            var blobClient = containerClient.GetBlobClient($"{blobId}-{file.FileName}");

            await using (var stream = file.OpenReadStream())
            {
                await blobClient.UploadAsync(stream, true);
            }

            _logger.LogInformation("File {FileName} uploaded to Azure Blob Storage successfully.", file.FileName);

            // 2. Save Metadata to Azure SQL
            var metadata = new DocumentMetadata
            {
                Id = blobId,
                FileName = file.FileName,
                ContentType = file.ContentType,
                BlobStorageUrl = blobClient.Uri.ToString(),
                UploadedBy = userUpn
            };

            _dbContext.Documents.Add(metadata);
            await _dbContext.SaveChangesAsync();

            return Ok(new { metadata.Id, metadata.BlobStorageUrl });
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "An error occurred while uploading document: {FileName}", file.FileName);
            return StatusCode(500, "An internal server error occurred.");
        }
    }

    [HttpGet]
    public async Task<ActionResult<IEnumerable<DocumentMetadata>>> GetMyDocuments()
    {
        var userUpn = User.Identity?.Name ?? "unknown-user";
        var documents = await _dbContext.Documents
            .Where(d => d.UploadedBy == userUpn)
            .OrderByDescending(d => d.UploadedAt)
            .ToListAsync();

        return Ok(documents);
    }
}
```

