using Microsoft.EntityFrameworkCore;
using EnterpriseCustomerService.Data;
using EnterpriseCustomerService.Models;

namespace EnterpriseCustomerService.Endpoints;

public static class CustomerEndpoints
{
    public static void MapCustomerEndpoints(this IEndpointRouteBuilder app)
    {
        var group = app.MapGroup("/api/customers")
                       .WithOpenApi(); // Generates Swagger docs

        // GET: All active customers
        group.MapGet("/", async (AppDbContext db) =>
            await db.Customers.Where(c => c.IsActive).ToListAsync())
            .WithName("GetCustomers")
            .Produces<List<Customer>>(StatusCodes.Status200OK);

        // GET: Single customer by ID
        group.MapGet("/{id:guid}", async (Guid id, AppDbContext db) =>
            await db.Customers.FindAsync(id) is Customer customer
                ? Results.Ok(customer)
                : Results.NotFound())
            .WithName("GetCustomerById")
            .Produces<Customer>(StatusCodes.Status200OK)
            .Produces(StatusCodes.Status404NotFound);

        // POST: Create customer (Secured in production)
        group.MapPost("/", async (Customer customer, AppDbContext db) =>
        {
            db.Customers.Add(customer);
            await db.SaveChangesAsync();
            return Results.Created($"/api/customers/{customer.Id}", customer);
        })
        .WithName("CreateCustomer")
        .Produces<Customer>(StatusCodes.Status201Created)
        .RequireAuthorization(); // Requires Microsoft Entra ID OAuth token
    }
}
