var builder = WebApplication.CreateBuilder(args);

// 1. Setup Enterprise Logging
builder.Logging.ClearProviders();
builder.Logging.AddConsole(); // Streams directly to Azure Log Analytics / App Service Logs

// 2. Register Azure Blob Service Client using "Passwordless" Managed Identity
// DefaultAzureCredential automatically authenticates using:
//   - Local Visual Studio / Azure CLI login (for local Windows development)
//   - Azure Managed Identity (when deployed to Azure App Service, VM, or AKS)
var blobUri = builder.Configuration["AzureSettings:BlobServiceUri"];
builder.Services.AddSingleton(x => 
    new BlobServiceClient(new Uri(blobUri!), new DefaultAzureCredential()));

// 3. Register Health Checks (Critical for Azure load balancers and container orchestrators)
