// POST Endpoint: Upload a business document to Azure Blob Storage
app.MapPost("/api/documents", async (
    [FromBody] DocumentPayload payload, 
    BlobServiceClient blobServiceClient, 
    ILogger<Program> logger) =>
{
    if (string.IsNullOrEmpty(payload.FileName) || string.IsNullOrEmpty(payload.Content))
    {
        return Results.BadRequest("Invalid document payload.");
    }

    try
    {
        logger.LogInformation("Attempting to upload {FileName} to Azure Blob Storage.", payload.FileName);

        // Get container client (creates container "enterprise-docs" if it doesn't exist)
        var containerClient = blobServiceClient.GetBlobContainerClient("enterprise-docs");
        await containerClient.CreateIfNotExistsAsync();

        // Get blob client and upload content
        var blobClient = containerClient.GetBlobClient(payload.FileName);

        using var stream = new MemoryStream(System.Text.Encoding.UTF8.GetBytes(payload.Content));
        await blobClient.UploadAsync(stream, overwrite: true);

        logger.LogInformation("Successfully uploaded {FileName} to Azure Blob Storage.", payload.FileName);

        return Results.Ok(new { Message = "File uploaded successfully", BlobUri = blobClient.Uri });
    }
    catch (Exception ex)
    {
        logger.LogError(ex, "An error occurred while uploading {FileName}", payload.FileName);
        return Results.Problem("An internal enterprise service error occurred.");
    }
});

app.Run();

