	Status    string    `json:"status"`
	Timestamp time.Time `json:"timestamp"`
	Message   string    `json:"message"`
}

// A lightweight, high-performance handler
func benchmarkHandler(w http.ResponseWriter, r *http.Request) {
	// Only allow GET requests for this endpoint
	if r.Method != http.MethodGet {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return filterJSONError(w, "Method not allowed", http.StatusMethodNotAllowed)
	}

	response := MessageResponse{
		Status:    "success",
		Timestamp: time.Now().UTC(),
		Message:   "High-performance handling active",
	}

	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(http.StatusOK)

	// json.NewEncoder writes directly to the network socket,
	// which is faster and uses less memory than json.Marshal.
	if err := json.NewEncoder(w).Encode(response); err != nil {
		log.Printf("Error encoding response: %v", err)
	}
}

func filterJSONError(w http.ResponseWriter, msg string, code int) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(code)
	_ = json.NewEncoder(w).Encode(map[string]string{"error": msg})
}

func main() {
	// Multiplexer (router) configuration
	mux := http.NewServeMux()
	mux.HandleFunc("/api/v1/fast", benchmarkHandler)

	// Configure the HTTP server with strict limits to prevent resources 
	// from being exhausted by slow clients or "Slowloris" DDoS attacks.
	server := &http.Server{
		Addr:    ":8080",
		Handler: mux,

		// Timeouts crucial for high-concurrency systems:
		ReadTimeout:       5 * time.Second,   // Max time to read the request header/body
		WriteTimeout:      10 * time.Second,  // Max time to write the response
		IdleTimeout:       120 * time.Second, // Max time to keep a Keep-Alive connection idle
		MaxHeaderBytes:    1 << 20,           // 1 MB limit on headers (security measure)
	}

	// Channel to listen for OS interrupt signals (graceful shutdown)
	shutdownChan := make(chan os.Signal, 1)
	signal.Notify(shutdownChan, os.Interrupt, syscall.SIGTERM)

	// Run the server in a separate goroutine so it doesn't block the main thread
	go func() {
		log.Printf("High-performance server starting on port %s...", server.Addr)
		if err := server.ListenAndServe(); err != nil && err != http.ErrServerClosed {
			log.Fatalf("Server failed: %s\n", err)
		}
	}()

	// Block here until we receive an interrupt signal
	<-shutdownChan
	log.Println("Shutdown signal received. Shutting down gracefully...")

	// Create a context with a 15-second timeout to allow existing concurrent requests to finish
	ctx, cancel := context.WithTimeout(context.Background(), 15*time.Second)
	defer cancel()

	if err := server.Shutdown(ctx); err != nil {
		log.Fatalf("Server forced to shutdown: %v", err)
	}

	log.Println("Server stopped cleanly. No active requests remaining.")
}
```

