use axum::{
    extract::State,
    routing::{get, post},
    Json, Router,
};
use serde::{Deserialize, Serialize};
use std::sync::atomic::{AtomicU64, Ordering};
use std::sync::Arc;
use std::time::Duration;

// 1. Thread-safe, lock-free Shared State.
// We use AtomicU64 instead of Mutex<u64> to avoid thread locking overhead during high concurrency.
struct AppState {
    request_counter: AtomicU64,
}

#[derive(Serialize)]
struct StatusResponse {
    status: &'static str,
    requests_handled: u64,
}

#[derive(Deserialize)]
struct ComputePayload {
    numbers: Vec<i64>,
}

#[derive(Serialize)]
struct ComputeResponse {
    sum: i64,
}

#[tokio::main]
async fn main() {
    // Initialize the shared state
    let shared_state = Arc::new(AppState {
        request_counter: AtomicU64::new(0),
    });

    // Build the Router and define routes
    let app = Router::new()
        .route("/", get(root_handler))
        .route("/io-bound", get(io_bound_handler))
        .route("/compute", post(compute_handler))
        .with_state(shared_state);

    // Bind to all interfaces on port 8080
    let addr = "0.0.0.0:8080";
    let listener = tokio::net::TcpListener::bind(addr).await.unwrap();
    println!("🚀 High-performance Rust server running on http://{}", addr);

    // Start the Axum server
    axum::serve(listener, app).await.unwrap();
}

// HANDLER 1: Ultra-fast, zero-allocation endpoint.
// Perfect for health-checks. Uses atomic fetch_add for lock-free concurrency.
async fn root_handler(State(state): State<Arc<AppState>>) -> Json<StatusResponse> {
    let count = state.request_counter.fetch_add(1, Ordering::Relaxed);
    Json(StatusResponse {
        status: "OK",
        requests_handled: count + 1,
    })
}

// HANDLER 2: Simulated I/O-bound operation (e.g., Database Query or Third-party API call).
// `tokio::time::sleep` yields control back to the executor, meaning the CPU thread
// is immediately freed to handle other incoming requests while waiting.
async fn io_bound_handler() -> &'static str {
    tokio::time::sleep(Duration::from_millis(50)).await;
    "I/O Task Completed"
}

// HANDLER 3: CPU-bound operation.
// To prevent a heavy mathematical computation from blocking the async event loop (which 
// would degrade performance for all other users), we offload it to Tokio's blocking thread pool.
async fn compute_handler(Json(payload): Json<ComputePayload>) -> Json<ComputeResponse> {
    let sum = tokio::task::spawn_blocking(move || {
        // Heavy math runs on a separate worker pool thread
        payload.numbers.iter().sum::<i64>()
    })
    .await
    .unwrap();

    Json(ComputeResponse { sum })
}
```

